\section{Geometric and Analytic Preliminaries} \label{secprelim}

The aim of this section is to recall basic definitions and results concerning symmetric hyperbolic systems on globally hyperbolic Lorentzian manifolds.

\subsection{Globally Hyperbolic Manifolds}
Let $\scrM$ be a connected, oriented and smooth manifold (without boundary) of dimension~$k+1$ with $k\geq 1$. We assume that $\scrM$ is either non-compact or compact with Euler characteristic zero, so that it can be equipped with a smooth Lorentzian metric $g$ of signature~$(- ,+, \ldots, +)$. In the class of Lorentzian manifolds, those called \textit{globally hyperbolic} provide a suitable background for analyzing the Cauchy problem for hyperbolic equations.

\begin{Def}[Globally Hyperbolic Manifolds]
	A connected, oriented, time-oriented and smooth Lorentzian manifold $(\scrM,g)$ is called \emph{globally hyperbolic} if the following holds true:
	\begin{itemize}
		\item[(i)] $(\scrM,g)$ is \emph{causal}, i.e.~there are no closed causal curves;
		\item[(ii)] for every $p, q \in \scrM$, the set $J^+ (p) \cap J^{-}(q)$ is compact, where $J^+(\cdot)$ (\textit{resp.}~$J^-(\cdot)$) denotes the causal future (\textit{resp.}~past) in $\scrM$.
	\end{itemize}
\end{Def}

In the seminal paper~\cite{Geroch}, Geroch showed that global hyperbolicity of a Lorentzian manifold is equivalent to the existence of a \textit{Cauchy hypersurface}. 

\begin{Def}[Cauchy Hypersurfaces]
	A subset $\scrN\subset\scrM$ of a spacetime $(\scrM,g)$ is a {\em Cauchy hypersurface}, if it is intersected exactly once by any inextendible future-directed smooth timelike curve.
\end{Def}

Let us remind the reader that a smooth curve $\gamma \colon I \to \scrM$, where $I \subset \mathbb{R}$ is an open interval, is said to be {\em inextendible}, if there does not exist any {\em continuous} curve $\gamma'\colon J \to \scrM$ defined on  an open interval  $J \subset \mathbb{R}$ such that $I \subsetneq J$ and $\gamma'|_I =\gamma$.

\begin{Thm}[\protect{\cite[Thm.~11]{Geroch}}]\label{thm:Geroch} 
	A Lorentzian manifold $(\scrM,g)$ is globally hyperbolic if and only if it admits a Cauchy hypersurface.
\end{Thm}

It turns out that the Cauchy hypersurfaces of a globally hyperbolic manifold $(\scrM,g)$ are co-dimension-one topologically embedded submanifolds of $\scrM$ that are homeomorphic to each other. As a by-product of Geroch’s theorem, it also follows that a globally hyperbolic manifold $(\scrM,g)$ admits a continuous foliation by Cauchy hypersurfaces, namely $\scrM$ is homeomorphic to a product $\R\times \scrN$ for some Cauchy hypersurface $\scrN$. This can be established by finding a {\em Cauchy time function}, i.e.~a continuous function $t\colon\scrM\rightarrow\mathbb{R}$ which is strictly increasing on any future-directed timelike curve and whose level sets $t^{-1}(t_0)$, $t_0\in \mathbb{R}$, are Cauchy hypersurfaces homeomorphic to $\scrN$. Geroch's splitting is topological in nature and the fact that it can be done in a smooth way has been part of the mathematical folklore whilst remaining an open problem for many years. Only recently Bernal and S\'anchez \cite{bernal+sanchez2} obtained a smooth version of the result of Geroch by introducing the notion of a \emph{Cauchy temporal function}.

\begin{Def}[Cauchy Temporal Functions] \label{def:Cauchy temporal}
	Given a connected and time-oriented smooth Lorentzian manifold $(\scrM,g)$,  we say that a smooth function  $t\colon\scrM \to \R$ is a {\em Cauchy temporal function}  if the embedded submanifolds of co-dimension one given by its level sets are smooth Cauchy hypersurfaces and if $(dt)^\sharp$ is past-directed timelike. 
\end{Def} 

\begin{Thm}[\protect{\cite[Thm.~1.1~and~1.2]{bernal+sanchez2}}, \protect{\cite[Thm.~1.2]{bernal+sanchez_further_results}}]\label{thm:Sanchez}
	For any globally hyperbolic manifold $(\scrM,g)$  there exists a Cauchy temporal function. In particular, it is (smoothly) isometric to the (globally orthogonal) product 
	\begin{align*} 
		(\R\times\scrN, - \beta^2 dt\otimes dt + h_t)\, ,
	\end{align*}
	where $t:\R\times \scrN \to \R$ is a Cauchy temporal function acting as a projection onto the first factor, $\scrN$ is a smooth, spacelike Cauchy hypersurface, $\beta\in C^{\infty}(\R\times\scrN,(0,\infty))$ is called the {\em lapse function}, and $h_t$ is a one-parameter family of Riemannian metrics on $\scrN$ depending smoothly on $t$.

	Moreover, if $\scrN \subset \scrM$ is any spacelike Cauchy hypersurface, then there exists a Cauchy temporal function $t$ such that $\scrN$ belongs to the foliation $t^{-1}(\R)$.
\end{Thm}

The class of globally hyperbolic manifolds is non-empty and besides Minkowski spacetime includes many significant spacetimes in general relativity and cosmology. Notable examples include \textit{black hole spacetimes} such as Schwarzschild and Kerr, as well as \textit{de Sitter spacetime}, a maximally symmetric solution of Einstein's equations with a positive cosmological constant. Of course, given any $n$-dimensional compact manifold $\scrN$ and a smooth one-parameter family of Riemannian metrics $\{h_t\}_{t\in\R}$, the Lorentzian manifold $(\R\times\scrN, g=-dt\otimes dt+h_t)$ provides an example of a globally hyperbolic manifold.

\subsection{Sobolev Spaces}\label{SobolevSpaces}
Let $(\scrM,g)$ be a Riemannian manifold with Levi-Civita connection $\nabla$ and $\scrE\xrightarrow{\pi}\scrM$ be a finite-rank $\C$-vector bundle over $(\scrM,g)$ equipped with a \textit{positive-definite} fibre metric 
\begin{align*}
	\Sl\cdot|\cdot\Sr_{\scrE}\in C^{\infty}(\scrM,(\overline{\scrE}\otimes\scrE)^{\ast}),\qquad \Sl\cdot\vert\cdot\Sr_{\scrE_{x}}\colon\scrE_{x}\times\scrE_{x}\to\C,\qquad x\in\scrM\, .
\end{align*}
We denote the space of smooth sections by $C^{\infty}(\scrM,\scrE)$ and the subspace of sections with compact support by $C^{\infty}_{\mathrm{c}}(\scrM,\scrE)$. Furthermore, we denote the natural $L^{2}$-Hilbert space by
\begin{align*}
	L^{2}(\scrM,\scrE):=\overline{C^{\infty}_{\mathrm{c}}(\scrM,\scrE)}^{\Vert\cdot\Vert_{L^{2}}},\qquad \bra\psi\vert\varphi\ket_{L^{2}}:=\int_{\scrM}\Sl\psi(x)\vert\varphi(x)\Sr_{\scrE_{x}}\,d\mu_{\scrM}(x)\, ,
\end{align*}
noting that it depends on both the Riemannian and bundle metric. Let us further choose a (metric compatible) connection 
\begin{align*}
	\nabla^{\scrE}\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE\otimes T^{\ast}\scrM)
\end{align*} 
of $\scrE$. Writing $\scrE_{i}:=\scrE\otimes T^{\ast}\scrM^{\otimes i}$ for $i\in\N$, we denote the \textit{$i$th covariant derivative} by\footnote{By $\nabla^{\scrE}\otimes\nabla$ we mean the tensor product connection, i.e.~$\nabla^{\scrE}\otimes\nabla:=\mathrm{id}_{\scrE}\otimes\nabla+\nabla^{\scrE}\otimes\mathrm{id}_{T^{\ast}\scrM}$.}
\begin{align*}
	\nabla^{\scrE,i}\colon C^{\infty}(\scrM,\scrE)\xrightarrow{\nabla^{\scrE}}C^{\infty}(\scrM,\scrE_{1})\xrightarrow{\nabla^{\scrE}\otimes\nabla}C^{\infty}(\scrM,\scrE_{2})\xrightarrow{}\dots\xrightarrow{}C^{\infty}(\scrM,\scrE_{i})\, ,
\end{align*}
see e.g.~\cite[Sec.~12.8]{LeeBookManifolds}. We equip the bundles $\scrE_{i}$ with the obvious bundle metric induced by $\Sl\cdot|\cdot\Sr_{\scrE}$ and $g$, which we denote by $\Sl\cdot|\cdot\Sr_{\scrE_{i}}$. With this notation, we define the \textit{Sobolev space} of order $i\in\N$ by
\begin{align*}
	W^{2,i}(\scrM,\scrE)&:=\overline{\{\psi\in C^{\infty}(\scrM,\scrE)\mid \Vert\psi\Vert_{W^{2,i}}<\infty\}}^{\Vert\cdot\Vert_{W^{2,i}}},\\ \bra\psi\vert\varphi\ket_{W^{2,i}}&:=\sum_{j=0}^{i}\bra\nabla^{\scrE,j}\psi(x)\vert\nabla^{\scrE,j}\varphi(x)\ket_{L^{2}}\, .
\end{align*}
We stress that this definition strictly depends on the choice of bundle metric and connection. Furthermore, we remind the reader that for non-compact $\scrM$, this definition does in general neither coincide with the definition obtained by using distributional (weak) covariant derivatives nor with the space $W^{2,i}_{0}(\scrM,\scrE)$ obtained by taking the completion of $C_{\mathrm{c}}^{\infty}(\scrM,\scrE)$ with respect to $\Vert\cdot\Vert_{W^{2,i}}$. We refer to \cite{HebeyBook} as well as \cite[Chap.~2]{AubinBook} and \cite[Sec.~1.3]{Eichhorn} for further details.

\subsection{Symmetric Hyperbolic Systems}\label{subsec:SHS}
Consider a \textit{Hermitian vector bundle} over a globally hyperbolic manifold $(\scrM,g)$, that is, a $\mathbb{C}$-vector bundle $\scrE\xrightarrow{\pi}\scrM$ of finite rank $N\in\N$ together with a non-degenerate Hermitian fibre metric 
\begin{align*}
	\Sl\cdot|\cdot\Sr_{\scrE}\in C^{\infty}(\scrM,(\overline{\scrE}\otimes\scrE)^{\ast}),\qquad \Sl\cdot\vert\cdot\Sr_{\scrE_{x}}\colon\scrE_{x}\times\scrE_{x}\to\C,\qquad x\in\scrM\, .
\end{align*}
The bundle metric $\Sl\cdot\vert\cdot\Sr_{\scrE}$ induces a non-degenerate Hermitian sesquilinear form on the level of sections, which we shall denote by
\begin{align}\label{eq:SectionMetric}
	\bra\psi\vert\varphi\ket_{\scrE}:=\int_{\scrM}\Sl\psi(x)\vert\varphi(x)\Sr_{\scrE_{x}}\,d\mu_{\scrM}(x)
\end{align}
for all $\psi,\varphi\in C^{\infty}(\scrM,\scrE)$ with compactly overlapping support, where $d\mu_{\scrM}$ denotes the Lorentzian volume measure on $(\scrM,g)$. The \textit{formal adjoint} of a linear differential operator $\scrS\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ with respect to $\bra\cdot\vert\cdot\ket_{\scrE}$ is denoted by $\scrS^{\dagger}$.

To clarify our convention, we recall that the \textit{principal symbol} $\sigma_{\scrS}\colon T^{\ast}\scrM\to\mathrm{End}(\scrE)$ of a linear first-order differential operator $\scrS\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ can be defined in accordance to the Leibniz rule
\begin{align*}\scrS(f\psi)=f\scrS\psi+\sigma_{\scrS}(df)\psi
\end{align*}
for all $f\in C^{\infty}(\scrM)$ and $\psi\in C^{\infty}(\scrM,\scrE)$, as in \cite[Sec.~5]{baergreen}. Since $\scrS$ is a \textit{first-order} differential operator, we note that $\sigma_{\scrS}(\xi)\in\mathrm{End}(\scrE_{x})$ is also $\R$-linear in $\xi\in T^{\ast}_{x}\scrM$ for all $x\in\scrM$, i.e.~$\sigma_{\scrS}$ defines a vector bundle morphism from $T^{\ast}\scrM$ to $\mathrm{End}(\scrE)$ and hence can be viewed as a section of $\mathrm{End}(\scrE)\otimes T\scrM$. 

Furthermore, let us choose a (metric) connection $\nabla^{\scrE}$ on $(\scrE,\Sl\cdot|\cdot\Sr_{\scrE})$ and a local coordinate chart $(x^{\mu})_{\mu=0,\dots,k}$ on some open subset of $\scrM$. Then, using the simplified notation $\nabla^{\scrE}_{\mu}:=\nabla^{\scrE}_{\partial_{\mu}}$, we can write $\scrS$ locally in the form
\begin{align*}
	\scrS=\sigma_{\scrS}(d x^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}\, ,
\end{align*}
where we used the \textit{Einstein summation convention} and where $\scrS_{0}\in C^{\infty}(\scrM,\mathrm{End}(\scrE))$ is a zero-order operator, which only depends on the choice of connection on $\scrE$. 

In this article, we are mainly interested in studying linear first-order differential operators of the following type:

\begin{Def}[Symmetric Hyperbolic Systems]\label{Def:SHS}
	 A \emph{symmetric hyperbolic system} is a linear first-order differential operator $\scrS\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ whose principal symbol $\sigma_{\scrS}\colon T^{\ast}\scrM\to\mathrm{End}(\scrE)$ has the following two properties:
	\begin{itemize}
		\item[(S)]$\sigma_{\scrS}(\xi)\in\mathrm{End}(\scrE_{x})$ is Hermitian with respect to $\Sl\cdot|\cdot\Sr_{\scrE_{x}}$ for all $\xi\in T^{\ast}_{x}\scrM,\,x\in\scrM$;
		\item[(H)]The sesquilinear form $\Sl\sigma_{\scrS}(\tau)\cdot\vert\cdot\Sr_{\scrE_{x}}$ is positive definite for every future-directed\footnote{A timelike covector $\xi\in T^{\ast}\scrM$ is \textit{future/past-directed} if $\xi(v)>0$ for all future/past-directed $v\in T\scrM$. In particular, the musical isomorphism map future-directed into past-directed objects and vice versa.} timelike $\tau\in T_{x}^{\ast}\scrM$ and all $x\in\scrM$.
	\end{itemize}
\end{Def}

\begin{Remark}
	More generally, one may consider \emph{weakly symmetric hyperbolic systems}, in which condition (H) in Definition~\ref{Def:SHS} is relaxed, see e.g.~\cite[Sec.~2.5]{DiracMIT}.
\end{Remark}

The following proposition shows how the formal adjoint $\scrS^{\dagger}$ of a first-order operator $\scrS$ can be written in terms the principal symbol and zero-order part of $\scrS$.

\begin{Prp}[Formal Adjoint of a Symmetric Hyperbolic System]\label{Prop:AdjointSHS} 
	Consider a symmetric hyperbolic system 
	\begin{align*}
		\scrS=\sigma_{\scrS}(d x^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}
	\end{align*}		
	on a Hermitian bundle $(\scrE,\Sl|\cdot\Sr_{\scrE})$ with metric connection $\nabla^{\scrE}$. Let $\nabla^{\mathrm{End}(\scrE)}$ be the connection on $\mathrm{End}(\scrE)$ induced by $\nabla^{\scrE}$ and denote by $\mathscr{D}$ the divergence-like operator defined as 
	\begin{align*}
		\mathscr{D}\colon C^{\infty}(\scrM,\mathrm{End}(\scrE)\otimes T\scrM)\xrightarrow{\nabla^{\mathrm{End}(\scrE)}\otimes\nabla} C^{\infty}(\scrM,\mathrm{End}(\scrE)\otimes T\scrM\otimes T^{\ast}\scrM)\xrightarrow{c}C^{\infty}(\scrM,\mathrm{End}(\scrE))\, ,
	\end{align*}
where $c\colon T\scrM\otimes T^{\ast}\scrM\ni v\otimes \xi\mapsto \xi(v)=v^{\mu}\xi_{\mu}$ denotes the dual pairing. Then, the formal adjoint $\scrS^{\dagger}$ of $\scrS$ with respect to $\bra\cdot\vert\cdot\ket_{\scrE}$ is given by
	\begin{align*}
		\scrS^{\dagger}=-\sigma_{\scrS}(d x^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}^{\prime}-\scrS_{0}^{\dagger}\, ,
	\end{align*}
	where $\scrS_{0}^{\prime}:=\mathscr{D}\sigma_{\scrS}$ is a zero-order differential operator.
\end{Prp}

\begin{proof}
	Fix $\psi,\varphi\in C^{\infty}_{\mathrm{c}}(\scrM,\scrE)$ and consider the $k$-form $\omega\in\Omega^{k}(\scrM,\C)$ defined by
	\begin{align*}
		\omega:=\Sl\sigma_{\scrS}(dx^{\mu})\psi|\varphi\Sr_{\scrE} \partial_{\mu}\lrcorner d\mu_{\scrM}\,.
	\end{align*}
	Defining the vector field $V:=\Sl\sigma_{\scrS}(dx^{\mu})\psi|\varphi\Sr_{\scrE} \partial_{\mu}\in C^{\infty}(\scrM,T\scrM)$, then $V\lrcorner d\mu_{\scrM}$ denotes the insertion of $V$ into the first slot of the volume form $d\mu_{\scrM}$. Cartan's magic formula implies 
	\begin{align*}
		d\omega=d(V\lrcorner d\mu_{\scrM})=\mathcal{L}_{V}d\mu_{\scrM}=\mathrm{div}_{g}(V)d\mu_{\scrM}\, ,
	\end{align*}	
	where $\mathcal{L}_{V}$ denotes the Lie derivative along $V$ and $\mathrm{div}_{g}(V)$ the divergence of $V$. Furthermore, using the fact that the connection $\nabla^{\scrE}$ is metric with respect to $\Sl\cdot|\cdot\Sr_{\scrE}$, a straightforward computation yields
	\begin{align*}
		\mathrm{div}_{g}(V)=&\partial_{\mu}\Sl \sigma_{\scrS}(dx^{\mu})\psi|\varphi\Sr_{\scrE}+\Gamma_{\mu\nu}^{\mu}\Sl \sigma_{\scrS}(dx^{\nu})\psi|\varphi\Sr_{\scrE}\\=&\Sl \nabla^{\scrE}_{\mu}(\sigma_{\scrS}(dx^{\mu})\psi)|\varphi\Sr_{\scrE}+\Sl \sigma_{\scrS}(dx^{\mu})\psi|\nabla^{\scrE}_{\mu}\varphi\Sr_{\scrE}+\Gamma_{\mu\nu}^{\mu}\Sl \sigma_{\scrS}(dx^{\nu})\psi|\varphi\Sr_{\scrE}\\=&\Sl \underbrace{(\nabla^{\mathrm{End}(\scrE)}_{\mu}\sigma_{\scrS}(dx^{\mu})+\Gamma_{\mu\nu}^{\mu}\sigma_{\scrS}(dx^{\nu}))\psi}_{=:\scrS_{0}^{\prime}\psi}+\sigma_{\scrS}(dx^{\mu})\nabla_{\mu}^{\scrE}\psi|\varphi\Sr_{\scrE}+\Sl \psi|\sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\mu}\varphi\Sr_{\scrE}\\=&\Sl\psi\vert\scrS\varphi\Sr_{\scrE}+\Sl(\sigma_{\scrS}(d x^{\mu})\nabla^{\scrE}_{\mu}+\scrS_{0}^{\prime}+\scrS_{0}^{\dagger})\psi\vert\varphi\Sr_{\scrE} \, ,
	\end{align*}
	where we added and subtracted $\Sl\psi\vert\scrS_{0}\varphi\Sr_{\scrE}$ in the last step and used the fact that the adjoint relation for $\scrS_{0}$ actually holds pointwise, i.e.~$\Sl\psi\vert\scrS_{0}\varphi\Sr_{\scrE}=\Sl\scrS_{0}^{\dagger}\psi\vert\varphi\Sr_{\scrE}$, since it is an operator of order zero. Combining everything, we have shown that
	\begin{align}\label{eq:AdjointProof}
		d\omega=\Sl\psi\vert\scrS\varphi\Sr_{\scrE}-\Sl\scrS^{\dagger}\psi\vert\varphi\Sr_{\scrE}\, .
	\end{align}
	where $\scrS^{\dagger}:=-\sigma_{\scrS}(d x^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}^{\prime}-\scrS_{0}^{\dagger}$. Integrating equation~\eqref{eq:AdjointProof} over $\scrM$ and using Stokes' theorem, we conclude that $\scrS^{\dagger}$ is indeed the formal adjoint of $\scrS$. 
\end{proof}

\begin{Remark}\label{Remark:Zero}	
	As a by-product, Proposition~\ref{Prop:AdjointSHS} implies that $\scrS+\scrS^{\dagger}$ is an operator of order zero and
	\begin{align*}
		\Sl(\scrS+\scrS^{\dagger})\psi\vert\psi\Sr_{\scrE}=-2\Re \Sl\scrS_{0}\psi\vert\psi\Sr_{\scrE}-\Sl\scrS^{\prime}_{0}\psi\vert\psi\Sr_{\scrE}
	\end{align*}
	for all $\psi\in C^{\infty}(\scrM,\scrE)$. In particular, since $\Sl\scrS^{\prime}_{0}\psi\vert\psi\Sr_{\scrE}$ is clearly real-valued, it follows that $\Sl(\scrS+\scrS^{\dagger})\psi\vert\psi\Sr_{\scrE}$ is real-valued as well. 
\end{Remark}

The following basic examples shows how Definition~\ref{Def:SHS} is related to the notion of symmetric hyperbolic systems in the usual PDE sense (see e.g.~\cite{friedrichs, friedrichs2}).

\begin{Example}\label{Ex:MinkSHS}
	Consider $(1+k)$-dimensional Minkowski spacetime $\scrM=\mathbb{R}\times\mathbb{R}^{k}$ and let $\scrE:=\scrM\times \C^N$ be the trivial vector bundle equipped with the standard inner product on its fibres. Any linear first-order differential operator $\scrS\colon C^{\infty}(\scrM,\scrE) \to C^{\infty}(\scrM,\scrE)$ can be written as
	\begin{align*} 
		\scrS:=  A^0 \partial_t + \sum_{j=1}^k A^j\partial_{j} - C 
	\end{align*}
	with coefficients $A^0, A^j,C\in C^{\infty}(\scrM,\C^{N\times N})$. In the notation used before, it holds that $\sigma_{\scrS}(dt)=A^{0}$ and $\sigma_{\scrS}(dx^{j})=A^{j}$ as well as $\scrS_{0}=C$. In these coordinates, Condition~(S) in Definition~\ref{Def:SHS} hence reduces to 
	\begin{align*}
		\text{(S)}&\qquad A^0=(A^0)^\dagger \qquad \text{and} \qquad A^j=(A^j)^\dagger
	\end{align*}
	for $j=1,\dots, k$, where $\dagger$ is the (pointwise) adjoint matrix, while (H) can be stated as 
	\begin{align*}
		\text{(H)}\qquad A^0 + \sum_{j=1}^{k} \alpha_j A^j \quad\text{ is positive definite for \quad
$\sum_{j=1}^{k} \alpha_j^2 <1$}\, ,
	\end{align*}
	since any timelike future-directed covector is (up to multiplication by a positive function) of the form $\tau=dt+\sum_{j=1}^{k}\alpha_{j}d x^{j}$ with coefficients $\{\alpha_{j}\}_{j}$ such that $\sum_{j}\alpha_{j}^{2}<1$. The latter requirement seems a bit stronger to the one found in the classical PDE literature, in which one usually just requires $A^{0}$ to be positive-definite. However, since the principal symbol $\sigma_{\scrS}(\xi)=A^{\mu}\xi_{\mu}$ depends smoothly on $\xi$, it is clear that positive definiteness of $\sigma_{\scrS}(d t)=A^{0}$ extends to small perturbations of $dt$, i.e.~to $\sigma_{\scrS}(d t+\alpha_{i}d x^{i})=A^{0}+\alpha_{j}A^{j}$ for sufficiently small $\{\alpha_{j}\}_{j}$. 
\end{Example}

As another example, also \textit{normally hyperbolic operators}, namely second-order differential operators, which up to the addition of a zero-order term are given by the d'Alembertian of some connection, can be reduced to symmetric hyperbolic systems, see~\cite[Sec.~1.5]{baer+ginoux} or \cite[Sec.~6.3]{FriedrichsTimelikeBoundary} for details. Furthermore, also Maxwell's equations on ultrastatic manifolds provide an example of a symmetric hyperbolic system (see Section~\ref{sec:Maxwell}). Last but not least, as we shall see in Section~\ref{sec:Dirac}, a prototypical example of a symmetric hyperbolic system is the \textit{Dirac operator}. In this setting, the naturally defined fibre metric on the spinor bundle is indefinite. However, it turns out that assuming the fibre metric of a symmetric hyperbolic system to be positive-definite is not a loss of generality. 

\begin{Lemma}[\protect{\cite[Lemma~2.8]{FriedrichsTimelikeBoundary}}]\label{lem:scalprod}
	Let $t\colon\scrM\to\R$ be a Cauchy temporal function and $\beta\in C^{\infty}(\scrM,(0,\infty))$ the corresponding lapse function, i.e.
	\begin{align*}
		\scrM=\R\times\scrN,\qquad g=-\beta^{2}dt\otimes dt+h_{t}
	\end{align*}
	for a one-parameter family $(h_{t})_{t\in\R}$ of Riemannian metrics on $\scrN$. Furthermore, let $\scrS\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ be a symmetric hyperbolic system over $(\scrM,g)$. Then, $\scrS_\beta:=\sigma_\scrS(dt)^{-1} \scrS$ is a symmetric hyperbolic system with respect to the positive-definite Hermitian fibre metric
	\begin{align}\label{eq:scalarprod}
\Sl\cdot|\cdot\Sr_{\beta,\scrE}:=\Sl{\sigma_{\scrS}(\eta)\cdot}\vert{\cdot}\Sr_\scrE\, ,
	\end{align}
	where $\eta:=\beta dt$ is the future-directed normal covector of $\scrN$ in $\scrM$. Moreover, the Cauchy problems for $\scrS_\beta$ and $\scrS$ are equivalent.
\end{Lemma}

It turns out that the Cauchy problem for a symmetric hyperbolic systems on a globally hyperbolic manifolds is well-posed.

\begin{Thm}[\protect{\cite[Cor.~5.4 and 5.5, Thm.~5.6 and Prop.~5.7]{baergreen}}]\label{Thm:WellPosedCauchy}
	Let $\scrS\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ be a symmetric hyperbolic system over a globally hyperbolic manifold $(\scrM,g)$ and let $t\colon\scrM\to\R$ be a Cauchy temporal function with corresponding foliation $(\scrN_{t})_{t\in\R}$. For every $t_{0}\in\R$ and every pair $(\phi,\mathfrak{f})\in C_{\mathrm{c}}^{\infty}(\scrM,\scrE)\times C_{\mathrm{c}}^{\infty}(\scrN_{t_{0}},\scrE|_{\scrN_{t_{0}}})$, there exists a unique solution $\psi\in C_{\mathrm{sc}}^{\infty}(\scrM,\scrE)$ of the Cauchy problem
	\begin{align}\label{Cauchysmooth}
		\begin{cases}{}
			{\scrS}\psi &=\phi \\
			\psi_{|_{\scrN_{t_{0}}}} &= \mathfrak{f}
		\end{cases} 
	\end{align}
	and the solution map $(\phi,\mathfrak{f})\mapsto\psi$ is continuous in the respective LF-space topologies. Furthermore, it holds that
	\begin{align*}
		\mathrm{supp}(\psi)\cap J^{\pm}(\scrN_{t_0})\subset J^{\pm}((\mathrm{supp}(\phi)\cap J^{\pm}(\scrN_{t_0}))\cup\mathrm{supp}(\mathfrak{f}))\, ,
	\end{align*}
	which in particular implies that $\psi$ propagates with at most the speed of light, i.e. 
	\begin{align*}
		\mathrm{supp}(\psi)\subset J(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))\, .
	\end{align*}
\end{Thm}

As a by-product of the well-posedness of the Cauchy problem, one obtains the existence of the advanced and the retarded Green operators.

\begin{Prp}[\protect{\cite[Thm.~5.9, Cor.~3.11]{baergreen}}]\label{prop:Green}
	For any symmetric hyperbolic system $\scrS$ on a globally hyperbolic manifold $(\scrM,g)$, there exist linear maps 
	\begin{align*}
		G_{\mathrm{ret}/\mathrm{adv}}\colon C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\to C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)\, ,
	\end{align*}
	called \emph{retarded and advanced Green operators}, with the following properties:
	\begin{align*}
		\text{(i)}&\quad G_{\mathrm{ret}/\mathrm{adv}}\circ\scrS= \scrS\circ G_{\mathrm{ret}/\mathrm{adv}}=\mathrm{id}\quad\text{on}\quad  C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\\
		\text{(ii)}&\quad \mathrm{supp}(G_{\mathrm{ret}}\varphi)\subset J^{+}(\mathrm{supp}(\varphi))\quad\text{and}\quad \mathrm{supp}(G_{\mathrm{adv}}\varphi)\subset J^{-}(\mathrm{supp}(\varphi))
	\end{align*}
	Furthermore, the retarded and advanced Green operators are unique and continuous.
\end{Prp}

Since the Cauchy problem for symmetric hyperbolic systems is well-posed, the space $\mathrm{ker}(\scrS\vert_{C^{\infty}_{\mathrm{sc}}})$ of solutions with spatially compact supports is isomorphic to the space of initial data $C^{\infty}_{\mathrm{c}}(\scrN,\scrE\vert_{\scrN})$ on a fixed smooth (spacelike) Cauchy hypersurface $\scrN$ of $\scrM$. We equip this space with the (positive-definite) inner product
\begin{align}\label{eq:InnerProduct} 
	(\psi | \phi)_{\scrN} := \int_\scrN \Sl \sigma_{\scrS}(\eta) \psi | \phi\Sr_{\scrE}\: d\mu_{\scrN}\:,
\end{align}
where $\eta$ denotes the \textit{future-directed} timelike normal covector of $\scrN$ and $d\mu_{\scrN}$ the volume measure on the Riemannian manifold $(\scrN,i^{\ast}g)$ with $i\colon\scrN\to\scrM$ denoting the natural embedding.

Now, if $t\colon\scrM\to\R$ is a Cauchy temporal function for $(\scrM,g)$ with corresponding lapse function $\beta\in C^{\infty}(\scrM,(0,\infty))$ such that
\begin{align*}
		\scrM=\R\times\scrN,\qquad g=-\beta^{2}dt\otimes dt+h_{t}
\end{align*}
for a one-parameter family $(h_{t})_{t\in\R}$ of Riemannian metrics on $\scrN$, the future-directed timelike normal vector of $\scrN_{t}:=\{t\}\times\scrN$ in $\scrM$ is $\nu_{t}=\beta^{-1}\partial_{t}\vert_{\scrN_{t}}$ and hence $\eta_{t}:=-\nu_{t}^{\flat}=\beta dt\vert_{\scrN_{t}}$ is the corresponding future-directed timelike normal covector. In particular, for any $t\in\R$, we use the inner product \eqref{eq:InnerProduct} to obtain a natural family of Hilbert spaces on the foliation $(\scrN_{t})_{t\in\R}$, i.e.
\begin{align}\label{eq:Ht}
	\H_t:=\overline{C^{\infty}_{\mathrm{c}}(\scrN_{t},\scrE\vert_{\scrN_{t}})}^{\Vert\cdot\Vert_{t}},\qquad (\psi | \phi)_t := \int_{\scrN_{t}} \Sl \psi | \phi \Sr_{\beta,\scrE}\: d\mu_{\scrN_{t}} \: ,
\end{align}
where $d\mu_{\scrN_{t}}$ is the Riemannian volume measure of $(\scrN_{t},h_{t})$ and where $\Sl\psi|\phi\Sr_{\beta,\scrE}:=\Sl \sigma_{\scrS}(\eta)\psi | \phi \Sr_{\scrE}$, as in Lemma~\ref{lem:scalprod}. In other words, using the notation of Section~\ref{SobolevSpaces}, 
\begin{align*}
	\H_{t}=L^{2}(\scrN_{t},\scrE_{\beta}\vert_{\scrN_{t}})\,,
\end{align*} 
where the subscript $\beta$ in $\scrE_{\beta}$ indicates that $\scrE$ is equipped with the positive-definite bundle metric $\Sl\cdot|\cdot\Sr_{\beta,\scrE}$. For a fixed time $T>0$, we consider the corresponding \textit{open} and \textit{closed time strip} defined by
\begin{align*}
	\scrM_{T}:=t^{-1}((0,T))\cong (0,T)\times\scrN\,,\qquad \overline{\scrM}_{T}:=t^{-1}([0,T])\cong [0,T]\times\scrN\, .
\end{align*}
On such a time strip, we introduce the Hilbert space
\begin{align}\label{eq:HMt}
	\H_{\scrM_{T}}:=\int^{\oplus}_{(0,T)}\H_t\,dt,\qquad \qquad (\psi | \phi)_{\scrM_{T}} = \int_{0}^{T} (\psi_{t} | \phi_{t})_t\, dt\, .
\end{align}
Introducing the auxiliary \textit{Riemannian} metric $g_{0}:=dt\otimes dt+h_{t}$ on $\scrM$, Fubini's theorem implies that the Hilbert space $\H_{\scrM_{T}}$ can be identified with the $L^{2}$-space
\begin{align*}
	\H_{\scrM_{T}}\cong L^{2}(\scrM_{T},\scrE_{\beta})\, ,
\end{align*}
where $\scrM_{T}$ is equipped with the auxiliary Riemannian metric $g_{0}$. We will also need the corresponding Sobolev spaces defined on the open time strip, which following the notation of Section~~\ref{SobolevSpaces}, will be denoted by $W^{2,i}(\scrM_{T},\scrE_{\beta})$ for $i\in\N$.
