\section{Symmetric Hyperbolic Systems with Nonlocal Potentials}
\label{Sec:SHSNonLoc}
In this section, we discuss the Cauchy problem for symmetric hyperbolic systems with nonlocal potentials in two different situations, namely for \textit{retarded} nonlocal potentials and nonlocal potential with \textit{short time range}. To start with, let us fix the basic set-up for the following discussion.

\begin{Setup}\label{Setup} Throughout this section, we consider the following data:
\begin{itemize}
	\item[$\bullet$]A globally hyperbolic Lorentzian manifold $(\scrM=\R\times\scrN,g=-\beta^{2}dt\otimes dt+h_{t})$ of dimension $1+k$ and a time strip $\overline{\scrM}_{T}=t^{-1}([0,T])$ for $T>0$;
	\item[$\bullet$]A Hermitian vector bundle $(\scrE,\Sl\cdot\vert\cdot\Sr_{\scrE})$ over $\scrM$ and a metric connection $\nabla^{\scrE}$;
	\item[$\bullet$]A symmetric hyperbolic system $\scrS=\sigma_{\scrS}(dx^{\mu})\nabla_{\mu}^{\scrE}-\scrS_{0}$ on $\scrE$;
	\item[$\bullet$]A nonlocal potential $\B\colon C^{\infty}_{\rm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ with time kernel $(\B_{t,\tau})_{t,\tau\in\R}$.
\end{itemize}
\end{Setup}

The goal of this section is to study the Cauchy problem for the \textit{nonlocal symmetric hyperbolic system} $\scrS-\B$, i.e.
\begin{align}\label{eq:SymNonLoc}
	\begin{cases}
		(\scrS-\B)\psi &=\phi\\
		\psi\vert_{\scrN_{0}}&=\mathfrak{f}
	\end{cases}
\end{align}
on the time strip $\overline{\scrM}_{T}=[0,T]\times\scrN$ for a source $\phi\in C^{\infty}_{\mathrm{c}}(\scrM,\scrE)$ with $\mathrm{supp}(\phi)\subset\overline{\scrM}_{T}$ and initial datum $\mathfrak{f}\in C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$.

We restrict our attention to the following nonlocal potential (see also Definition~\ref{Def:Potentials}):
\begin{itemize}
	\item[(R)] The case of a \emph{retarded nonlocal potential}, i.e.~$\B_{t,\tau} = 0$ for $\tau > t$. In addition, we assume that the time kernel has \emph{past-compact support} in the sense that there exists $t_0 \geq 0$ such that $\B_{t,\tau} = 0$ for all $\tau \leq -t_0$. Hence,
	\begin{align*}
		\mathrm{supp}(k_{\B})\subset\{(x,y)\in\scrM\times\scrM\mid y\in J^{-}(x)\}\cap (J^{+}(\scrN_{t_{0}})\times J^{+}(\scrN_{t_{0}}))\, .
	\end{align*}		
	In other words, the nonlocality is \emph{switched on} only after a finite time in the past.
	\item[(S)] The case of a nonlocal potential with \emph{short time range}, i.e.~there exists a constant $\delta > 0$ such that $\B_{t,\tau} = 0$ whenever $\vert t - \tau \vert > \delta$.
\end{itemize}

We shall prove that for these nonlocal potentials the Cauchy problem~\eqref{eq:SymNonLoc} admits strong solutions (as in \cite{friedrichs}), clearly under suitable assumptions. In the context of symmetric hyperbolic systems with nonlocal potentials, strong solutions are defined as follows.

\begin{Def}\label{Def:StrongSol} \emph{(Strong Solutions)}
	\begin{itemize}
		\item[(i)]In case (R), assume in addition that $\B$ is uniformly bounded in time on $[-t_{0},T]$, i.e.~there is a constant $C_{T}>0$ such that $\Vert\B_{t,\tau}\varphi_{\tau}\Vert\leq C_{T}\Vert\varphi_{\tau}\Vert_{\tau}$ for all $\varphi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ and $t,\tau\in [-t_{0},T]$. Then, a \emph{strong solution on $\overline{\scrM}_{T}$} is an element $\psi\in\H_{[-t_{0},T]\times\scrN}$ for which there exists a sequence $\psi_{k}\in C^{\infty}(\scrM,\scrE)\cap \H_{[-t_{0},T]\times\scrN}$ such that
		\begin{align*}
			\psi_{k}\vert_{\scrN_{0}}\xrightarrow{k\to\infty}\mathfrak{f}&\quad\text{in}\quad\H_{0}\,,\qquad\qquad\psi_{k}\xrightarrow{k\to\infty}\psi\quad\text{in}\quad\H_{[-t_{0},T]\times\scrN}\,,\\ &\quad(\scrS-\B)\psi_{k}\xrightarrow{k\to\infty} \phi\quad\text{in}\quad \H_{\overline{\scrM}_{T}}\, .
		\end{align*}
		\item[(ii)]In case (S), assume in addition that $\B$ is uniformly bounded in time on $[-\delta,T+\delta]$, i.e.~there is a constant $C_{T}>0$ such that $\Vert\B_{t,\tau}\varphi_{\tau}\Vert\leq C_{T}\Vert\varphi_{\tau}\Vert_{\tau}$ for all $\varphi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ and $t,\tau\in [-\delta,T+\delta]$. Then, a \emph{strong solution on $\overline{\scrM}_{T}$} is an element $\psi\in\H_{[-\delta,T+\delta]\times\scrN}$ for which there exists a sequence $\psi_{k}\in C^{\infty}(\scrM,\scrE)\cap \H_{[-\delta,T+\delta]\times\scrN}$ such that
		\begin{align*}
			\psi_{k}\vert_{\scrN_{0}}\xrightarrow{k\to\infty}\mathfrak{f}&\quad\text{in}\quad\H_{0}\,,\qquad\qquad\psi_{k}\xrightarrow{k\to\infty}\psi\quad\text{in}\quad\H_{[-\delta,T+\delta]\times\scrN}\,,\\ &\quad(\scrS-\B)\psi_{k}\xrightarrow{k\to\infty} \phi\quad\text{in}\quad \H_{\overline{\scrM}_{T}}\, .
		\end{align*}
	\end{itemize}
\end{Def}

Note that, it is important in the above definition that the approximating sequence $\psi_{k}$ is defined on all of $\scrM$ and not just the time strip $\overline{\scrM}_{T}$, since, $\B\psi_{k}$ on $[0,T]\times\scrN$ requires us to specify $\psi_{k}$ on $[-t_{0},T]$ in the retarded case (R) and on $[-\delta,T+\delta]\times\scrN$ in the short time range case (S). Furthermore, we note that the boundedness assumption in time ensures that $\B$ is well-defined on smooth sections that are $L^{2}$ on each time slice. 

While full regularity of the strong solution cannot be expected for a generic short time range nonlocal potential with general initial data, for retarded potentials, we shall show that, under some additional assumption on the regularity of the nonlocal potential, strong solutions are  ``classical''. In the context of symmetric hyperbolic systems with nonlocal potentials, strong solutions are defined as follows. For completeness, we also give a suitable definition for classical solutions in the short time range case.

\begin{Def}\label{Def:ClassSol} \emph{(Classical Solutions)}
	\begin{itemize}
		\item[(i)] In case (R), a \emph{classical solution on $\overline{\scrM}_{T}$} is a section $\psi \in C^1((-t_0, T] \times \scrN, \scrE)$ such that
		\begin{align*}
			(\scrS - \B)\psi = \phi \quad \text{pointwise for all } t \in [0,T]\,, \quad \text{and} \quad \psi\vert_{\scrN_0} = \mathfrak{f}\,.
		\end{align*}
		\item[(ii)] In case (S), a \emph{classical solution on $\overline{\scrM}_{T}$} is a section $\psi \in C^1((-\delta, T+\delta) \times \scrN, \scrE)$ such that
		\begin{align*}
			(\scrS - \B)\psi = \phi \quad \text{pointwise for all } t \in [0,T]\,, \quad \text{and} \quad \psi\vert_{\scrN_0} = \mathfrak{f}\,.
		\end{align*}
	\end{itemize}
\end{Def}

Clearly, if a strong solution converge to a $C^1$-solution $\psi$ then $\psi$ is clearly also a classical solution. Indeed, any strong solution is a weak solution and  if it is additional $C^1$ then it is also classical.

\subsection{Energy Estimates}
To establish the existence and uniqueness of solutions, it is essential to derive appropriate energy estimates that control the behaviour of the system over time. As a first step in this direction, we derive a fundamental identity governing the evolution of the energy associated with a symmetric hyperbolic system. This identity serves as the foundation for obtaining a priori bounds, which are crucial in the subsequent analysis.

\begin{Prp}[Energy Evolution]\label{Prop:energy}
	Let $(\scrM,g)$ be a globally hyperbolic manifold with Cauchy temporal function $t\colon\scrM\to\R$ and consider a symmetric hyperbolic system $\scrS$ on a Hermitian bundle $(\scrE,\Sl\cdot|\cdot\Sr_{\scrE})$. Then, for any $\psi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$, it  holds that
	\begin{align*}
	\frac{d}{dt}\Vert\psi_{t}\Vert^{2}_{t}=2\Re\int_{\scrN_{t}}\Sl \scrS\psi|\psi\Sr_{\scrE}\beta \,d\mu_{\scrN_{t}}-\int_{\scrN_{t}}\Sl (\scrS+\scrS^{\dagger})\psi|\psi\Sr_{\scrE}\beta\,d\mu_{\scrN_{t}}
\end{align*}
for all $t\in\R$, where we used the notation $\psi_{t}(\cdot):=\psi\vert_{\scrN_{t}}(\cdot)=\psi(t,\cdot)\in C^{\infty}_{\mathrm{c}}(\scrN_{t},\scrE\vert_{\scrN_{t}})$.
\end{Prp}

\begin{proof}
	Let $\psi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ be arbitrary. Similar as in the proof of Proposition~\ref{Prop:AdjointSHS}, we consider the real-valued $k$-form $\omega\in\Omega^{k}(\scrM)$ defined by
	\begin{align*}
		\omega=\Sl\sigma_{\scrS}(dx^{\mu})\psi|\psi\Sr_{\scrE} \partial_{\mu}\lrcorner d\mu_{\scrM}\,.
	\end{align*}
	As explained in more details in the proof of 	Proposition~\ref{Prop:AdjointSHS} (see~Equation~\eqref{eq:AdjointProof}), its exterior derivative can be written as
	\begin{align}\label{eq:Leibniz}
		d\omega=\Sl\psi|\scrS\psi\Sr_{\scrE}-\Sl\scrS^{\dagger}\psi|\psi\Sr_{\scrE}=2\Re \Sl\scrS\psi|\psi\Sr_{\scrE}-\Sl (\scrS+\scrS^{\dagger})\psi|\psi\Sr_{\scrE}\, .
	\end{align}
	Now, consider a closed time strip $\overline{\scrM}_{T}:=t^{-1}([0,t])$ for $t\geq 0$. Stokes' theorem implies
	\begin{align}\label{eq:Stokes}
		\int_{\overline{\scrM}_{T}}d\omega=\int_{\scrN_{t}}i_{t}^{\ast}\omega-\int_{\scrN_{t_{0}}}i_{0}^{\ast}\omega\, ,
	\end{align}
	where $i_{\tau}\colon\scrN_{\tau}\hookrightarrow\scrM$ denote the natural embeddings. Using Fubini's theorem and Equation~\eqref{eq:Leibniz}, we rewrite the left-hand side of~\eqref{eq:Stokes} as
	\begin{align}\label{eq:LHSProof}
		\int_{\overline{\scrM}_{T}}d\omega=\int_{0}^{t}\int_{\scrN_{\tau}}\bigg\{2\Re (\Sl\scrS\psi|\psi\Sr_{\scrE})-\Sl (\scrS+\scrS^{\dagger})\psi|\psi\Sr_{\scrE} \bigg\}\beta\,d\mu_{\scrN_{\tau}} d\tau\, .
	\end{align}
	For the right-hand side of~Equation \eqref{eq:Stokes}, we first claim that for any vector field $X\in C^{\infty}(\scrM,T\scrM)$, it holds that
	\begin{align*}
		i_{\tau}^{\ast}(X\lrcorner d\mu_{\scrM})=-g(X,\nu)d\mu_{\scrN_{\tau}}\, ,
	\end{align*} 
	where $\nu$ denotes the future-directed timelike normal vector of $\scrN_{\tau}$ in $\scrM$, as usual. Indeed, decomposing $X$ into a normal component $X^{\perp}:=-g(X,\nu)\nu$ and tangential component $X^{\top}:=X-X^{\perp}$, we have that
	\begin{align*}
		i_{\tau}^{\ast}(X\lrcorner d\mu_{\scrM})=i_{\tau}^{\ast}(X^{\perp}\lrcorner d\mu_{\scrM})=-g(X,\nu)i_{\tau}^{\ast}(\nu\lrcorner d\mu_{\scrM})=-g(X,\nu)d\mu_{\scrN_{\tau}}\, ,
	\end{align*}
	as claimed above. In particular, when choosing coordinates adapted to the splitting obtained from our Cauchy temporal function $t\colon\scrM\to\R$, i.e.~$(x^{\mu})_{\mu=0,\dots,k}$ with $x^{0}=t$, where $(x^{i})_{i=1,\dots,k}$ are local coordinates on $\scrN$, we find $\nu=\beta^{-1}\partial_{t}$ and hence, we conclude that
	\begin{align*}
		-g(X,\nu)=\Sl\sigma_{\scrS}(\beta dt)\psi|\psi\Sr_{\scrE}\qquad\text{ for }\qquad X:=\Sl\sigma_{\scrS}(dx^{\mu})\psi|\psi\Sr_{\scrE} \partial_{\mu}\end{align*} 
	To sum up, we have shown that 
	\begin{align}\label{eq:RHSProof}
		\int_{\scrN_{\tau}}i_{\tau}^{\ast}\omega=\int_{\scrN_{\tau}}\Sl\sigma_{\scrS}(\beta dt)\psi|\psi\Sr_{\scrE}d\mu_{\scrN_{\tau}}=\Vert\psi_{\tau}\Vert_{\tau}^{2}
	\end{align}
	for all $\tau\in\R$. Using Equation~\eqref{eq:LHSProof} as well as Equation~\eqref{eq:RHSProof} for the right-hand side, we obtain from~\eqref{eq:Stokes} the equation
	\begin{align*}
		\int_{0}^{t}\int_{\scrN_{\tau}}\bigg\{2\Re (\Sl\scrS\psi|\psi\Sr_{\scrE})-\Sl (\scrS+\scrS^{\dagger})\psi|\psi\Sr_{\scrE} \bigg\}\beta\,d\mu_{\scrN_{\tau}} d\tau=\Vert\psi_{t}\Vert_{t}^{2}-\Vert\psi_{0}\Vert_{0}^{2}\, .
	\end{align*}
	Taking the derivative with respect to the time variable $t$ yields the claimed result. For $t\leq 0$, we reverse the arguments by choosing a time strip $t^{-1}([t,0])$, which results into the equation
	\begin{align*}
		\int_{t}^{0}\int_{\scrN_{\tau}}\bigg\{2\Re (\Sl\scrS\psi|\psi\Sr_{\scrE})-\Sl (\scrS+\scrS^{\dagger})\psi|\psi\Sr_{\scrE} \bigg\}\beta\,d\mu_{\scrN_{\tau}} d\tau=\Vert\psi_{0}\Vert_{0}^{2}-\Vert\psi_{t}\Vert_{t}^{2}\, .
	\end{align*}
	Taking the time-derivative of this expression yields the same result.
\end{proof}

Now, in the following computations, it will be useful to rewrite the right-hand side of the energy equation in Proposition~\ref{Prop:energy} in terms of the time kernel $\B_{t,\tau}$ and the Hilbert space inner product $(\cdot|\cdot)_{t}$ (see~Equation~\eqref{eq:Ht}). As a first step, we introduce the concept of a \textit{weighted time kernel}.

\begin{Def}[Weighted Time Kernel]\label{eq:modTK}
	Let $t\colon\scrM\to\R$ be a Cauchy temporal function and $\B\colon C^{\infty}_{\rm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ be a nonlocal potential with time kernel $(\B_{t,\tau})_{t,\tau\in\R}$. Then, we define the \emph{weighted potential} 
	\begin{align*}
		\V:=\beta\sigma_{\scrS}(\eta)^{-1}\B\colon C^{\infty}_{\rm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)\, ,
	\end{align*}
	where $\eta:=\beta dt$ denotes the future-directed timelike normal covector, as usual. The time kernel of $\V$ is given by $
		\V_{t,\tau}:=\beta_{t}\sigma_{\scrS}(\eta_t)^{-1}\B_{t,\tau}$ where $\beta_{t}(\cdot):=\beta(t,\cdot)$.
\end{Def}

Note that this definition is well-defined, since $\Sl\sigma_{\scrS}(\eta)\cdot|\cdot\Sr_{\scrE}$ is pointwise positive definite, which implies that $\sigma_{\scrS}(\eta)\in C^{\infty}(\scrM,\mathrm{End}(\scrE))$ is pointwise invertible.

Using this notation, we derive the following energy estimates from Proposition~\ref{Prop:energy}, which will be relevant for our analysis.


\begin{Corollary}[Energy Estimates]\label{Cor:EnEstLoc}
	Consider a symmetric hyperbolic system $\scrS$ with the property that the zero-order operator $\mathcal{Z}_{\scrS}:=\beta\sigma_{\scrS}(\eta)^{-1}(\scrS+\scrS^{\dagger})$ is uniformly bounded in time, i.e.~there exists a constant $D>0$ such that $\Vert (\mathcal{Z}_{\scrS}\varphi)_{t}\Vert_{t}\leq D\Vert\varphi_{t}\Vert_{t}$ for all $\varphi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$. Then, the unique solution $\psi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ to the Cauchy problem
	\begin{align*}
	\begin{cases}
		\scrS\psi&=\phi\\
		\psi\vert_{\scrN_{0}}&=\mathfrak{f}
	\end{cases}
\end{align*}	 
for compactly-supported Cauchy data $(\phi,\mathfrak{f})\in C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\times C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$ satisfies
\begin{align*}
	\Vert\psi_{t}\Vert_{t}\leq Me^{\frac{1}{2}D\vert t\vert}
\end{align*}
for all $t\in\R$ where $M>0$ is a constant only depending on $(\phi,\mathfrak{f})$.
\end{Corollary}

\begin{proof}
	Let us write $\phi^{\prime}:=\beta\sigma_{\scrS}(\eta)^{-1}\phi$. Then, taking the absolute value in  Proposition~\ref{Prop:energy} and using the Cauchy Schwartz inequality on the right-hand side yields
	\begin{align*}
		\bigg\vert\frac{d}{dt}\Vert\psi_{t}\Vert^{2}_{t}\bigg\vert\leq \Vert\psi_{t}\Vert_{t}\bigg(2\Vert \phi^{\prime}_{t}\Vert_{t}+\Vert(\mathcal{Z}_{\scrS}\psi)_{t}\Vert_{t}\bigg)\, ,
	\end{align*}
	We use the Leibniz rule on the left-hand side and the assumption on $\mathcal{Z}_{\scrS}$ to obtain the estimate
	\begin{align}\label{eq:EstEnGen}
		\bigg\vert\frac{d}{dt}\Vert\psi_{t}\Vert_{t}\bigg\vert\leq \Vert \phi^{\prime}_{t}\Vert_{t}+\frac{1}{2}\Vert\psi_{t}\Vert_{t}\, .
	\end{align}
	Now, we distinguish between two cases. First, note that the estimate~\eqref{eq:EstEnGen} implies
	\begin{align*}
		\frac{d}{dt}\bigg(e^{-\frac{1}{2}Dt}\Vert\psi_{t}\Vert_{t}\bigg)\leq e^{-\frac{1}{2}Dt}\Vert\phi_{t}^{\prime}\Vert_{t}\, .
	\end{align*}
	Then, for $t\geq 0$, integrating from $0$ to $t$ yields the estimate
	\begin{align*}
		\Vert\psi_{t}\Vert_{t}\leq e^{\frac{1}{2}Dt}\bigg\{\int_{0}^{t}\bigg(e^{-\frac{1}{2}D\tau}\Vert\phi^{\prime}_{\tau}\Vert_{\tau}\bigg)\,d\tau+\Vert\mathfrak{f}\Vert_{0}\bigg\}\leq e^{\frac{1}{2}Dt}\bigg(\int_{0}^{t}\Vert\phi^{\prime}_{\tau}\Vert_{\tau}\,d\tau+\Vert\mathfrak{f}\Vert_{0}\bigg)\, .
	\end{align*}
	For $t\leq 0$, we need to use a different sign in order to get the right exponential factor. In this case, we use the fact that the estimate~\eqref{eq:EstEnGen} also implies that
	\begin{align*}
		-\frac{d}{dt}\bigg(e^{\frac{1}{2}Dt}\Vert\psi_{t}\Vert_{t}\bigg)\leq e^{\frac{1}{2}Dt}\Vert\phi_{t}^{\prime}\Vert_{t}\, .
	\end{align*}
	Taking $t\leq 0$, integrating from $t$ to $0$ and using similar steps as above, results into the estimate
	\begin{align*}
		\Vert\psi_{t}\Vert_{t}\leq e^{-\frac{1}{2}Dt}\bigg(\int_{t}^{0}\Vert\phi^{\prime}_{\tau}\Vert_{\tau}\,d\tau+\Vert\mathfrak{f}\Vert_{0}\bigg)\, .
	\end{align*}
	Now, since $\phi$ (and hence also $\phi^{\prime}$) is compactly-supported, we can combine both estimates to find a constant $M>0$ such that $\Vert\psi_{t}\Vert_{t}\leq Me^{\frac{1}{2}D\vert t\vert}$, which gives the claimed result.
\end{proof}

\begin{Corollary}[Energy Estimates]\label{Cor:EnEst}
	Consider Set-up~\eqref{Setup} and let $\psi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ and $\phi\in C^{\infty}_{\mathrm{c}}(\scrM,\scrE)$ be such that $\scrS\psi=\B\phi$. Then,
	\begin{align*}
		\bigg\vert\frac{d}{dt}\Vert\psi_{t}\Vert_{t}\bigg\vert\leq \int_{\R}\Vert \V_{t,\tau}\phi_{\tau}\Vert_{t}\,d\tau+\frac{1}{2}\Vert(\mathcal{Z}_{\scrS}\psi)_{t}\Vert_{t}\, ,
	\end{align*}
	for all $t\in\R$, where $\mathcal{Z}_{\scrS}:=\beta\sigma_{\scrS}(\eta)^{-1}(\scrS+\scrS^{\dagger})$ is an operator of order zero.
\end{Corollary}

\begin{proof}
	First of all, using the defining relation of the time kernel in Definition~\ref{Def:NonLocPot} as well as the of the modified time kernel in Definition~\ref{eq:modTK} above, we can write		
	\begin{align*}
		\int_{\scrN_{t}}\Sl&\B\phi|\psi\Sr_{\scrE}\beta\,d\mu_{\scrN_{t}}=\int_{\R}\int_{\scrN_{t}}\Sl\beta_{t}\B_{t,\tau}\phi_{\tau}|\psi_{\tau}\Sr_{\scrE}\,d\mu_{\scrN_{t}}\,d\tau=\\&=\int_{\R}\int_{\scrN_{t}}\Sl\sigma_{\scrS}(\eta_{t})\V_{t,\tau}\phi_{\tau}|\psi_{t}\Sr_{\scrE}\,d\mu_{\scrN_{t}}\,d\tau=\int_{\R}\, (\V_{t,\tau}\phi_{\tau}|\psi_{t})_{t}\, d\tau\, .
	\end{align*}
	Using this equation as well as the notation $\mathcal{Z}_{\scrS}:=\beta\sigma_{\scrS}(\eta)^{-1}(\scrS+\scrS^{\dagger})$, we take the absolute value in Proposition~\ref{Prop:energy} applied to $\psi$ to obtain the estimate
	\begin{align*}
		\bigg\vert\frac{d}{dt}\Vert\psi_{t}\Vert^{2}_{t}\bigg\vert\leq \Vert\psi_{t}\Vert_{t}\bigg(2\int_{\R}\Vert \V_{t,\tau}\phi_{\tau}\Vert_{t}\,d\tau+\Vert(\mathcal{Z}_{\scrS}\psi)_{t}\Vert_{t}\bigg)\, ,
	\end{align*}
	where we used the triangle and Cauchy-Schwartz inequalities. Rewriting the left-hand side using the Leibniz rule yields the claimed result.
\end{proof}


\subsection{Extended Symmetric Hyperbolic System Including Derivatives}
\label{Subsec:ExtSHS}
In this section, we show that any symmetric hyperbolic system with a nonlocal potential can be reformulated as an equivalent first-order system with nonlocal potential for an extended variable that includes both the section and its covariant derivative. This is done by introducing an enlarged bundle, on which the corresponding enlarged system and potential are defined. The construction will be used later to establish regularity of solutions, adapting ideas from the theory of symmetric hyperbolic systems on $\mathbb{R}^{n}$ as explained in \cite[Sec.~5.3]{john} and \cite[Sec.~13.3]{intro} to the setting of vector bundles and nonlocal potentials considered in this article.

Throughout this section, we consider Set-up~\ref{Setup}. As in Section~\ref{SobolevSpaces}, we introduce the vector bundles
\begin{align*}
	\scrE_{i}:=\scrE\otimes T^{\ast}\scrM^{\otimes i}
\end{align*}
and equip them with the bundle metrics $\Sl\cdot|\cdot\Sr_{\scrE_{i}}$ and connections $\nabla^{\scrE_{i}}$ induced from the bundle metrics and connection on $\scrE$ as well as the auxiliary \textit{Riemannian} metric $g_{0}=dt\otimes dt+h_{t}$ on $\scrM$ and corresponding Levi-Civita connection $\nabla^{0}$ on $T^{\ast}\scrM$, i.e.
\begin{align*}
	\Sl\cdot|\cdot\Sr_{\scrE_{i}}:=\Sl\cdot|\cdot\Sr_{\scrE}\otimes g_{0}^{\otimes i},\qquad \nabla^{\scrE_{i}}:=\nabla^{\scrE}\otimes(\nabla^{0})^{\otimes i}\, .
\end{align*} 
Now, for any section $\psi\in C^{\infty}(\scrM,\scrE)$, we define the \textit{extended} variable $\Psi$ by
\begin{align}\label{eq:Extended}
	\Psi:=(\psi,\nabla^{\scrE}\psi)\in C^{\infty}(\scrM,\mathsf{E}_{1}),\qquad \mathsf{E}_{1}:=\scrE\oplus\scrE_{1}\, ,
\end{align}
where the bundle $\mathsf{E}_{1}$ comes equipped with a natural bundle metric $\Sl\cdot|\cdot\Sr_{\mathsf{E}_{1}}$ and metric connection $\nabla^{\mathsf{E}_{1}}$ induced from the ones on $\scrE$ and $\scrE_{1}$, i.e.
\begin{align*}
	\Sl\Psi|\Phi\Sr_{\mathsf{E}_{1}}:=\Sl\Psi_{0}|\Phi_{0}\Sr_{\scrE}+\Sl\Psi_{1}|\Phi_{1}\Sr_{\scrE_{1}}\qquad\text{and}\qquad \nabla^{\mathsf{E}_{1}}\Psi:=(\nabla^{\scrE}\Psi_{0},\nabla^{\scrE_{1}}\Psi_{1})\, .
\end{align*}

\begin{Remark}\label{Rem:SobSpL2}
	Let $\psi\in C^{1}(\scrM,\scrE)$ and write $\Psi=(\psi,\nabla^{\scrE}\psi)\in C^{0}(\scrM,\mathsf{E}_{1})$. Then, by definition, it holds that
	\begin{align*}
		\psi\in W^{2,1}(\mathcal{U},\scrE_{\beta})\qquad\Leftrightarrow\qquad \Psi\in L^{2}(\mathcal{U},\mathsf{E}_{1,\beta})\, .
	\end{align*}
	for every $\mathcal{U}\subset\scrM$ open, where $\scrM$ is equipped with the Riemannian metric $g_{0}$ and where $\mathsf{E}_{1,\beta}$ denotes the bundle $\mathsf{E}_{1}$ equipped with $\Sl\cdot|\cdot\Sr_{\beta,\mathsf{E}_{1}}:=\Sl\sigma_{\mathsf{S}_{1}}(\beta dt)\cdot|\cdot\Sr_{\mathsf{E}_{1}}$.
\end{Remark}

Now, the goal of the following is to show that there exists system $\mathsf{S}_{1}$ and nonlocal potential $\mathsf{B}_{1}$ on the Hermitian bundle $(\mathsf{E}_{1},\Sl\cdot|\cdot\Sr_{\mathsf{E}_{1}})$, such that for every smooth solution $\psi\in C^{\infty}(\scrM,\scrE)$ to the equation $(\scrS-\B)\psi=\phi$ for some given source $\phi\in C^{\infty}(\scrM,\scrE)$, the corresponding extended variables $\Psi$ and $\Phi$ as defined in~\eqref{eq:Extended} satisfy $(\mathsf{S}_{1}-\mathsf{B}_{1})\Psi=\Phi$.

We first establish the bigger system $\mathsf{S}_{1}$ for the \textit{local} problems.

\begin{Prp}\label{Prop:SHSDer} Let $\scrS=\sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}$ be a symmetric hyperbolic system over $(\scrE,\Sl\cdot|\cdot\Sr_{\scrE})$. Then, there exists a symmetric hyperbolic system $\mathsf{S}_{1}=\sigma_{\mathsf{S}_{1}}(dx^{\mu})\nabla^{\sf{E}_{1}}_{\mu}-\mathsf{S}_{1,0}$ on $(\mathsf{E}_{1},\Sl\cdot|\cdot\Sr_{\mathsf{E}_{1}})$ with principal symbol
\begin{align*}
	\sigma_{\mathsf{S}_{1}}(\xi):=\begin{pmatrix}
		\sigma_{\scrS}(\xi) &0\\ 0 & \sigma_{\scrS}(\xi)\otimes\mathrm{id}_{T^{\ast}\scrM}
	\end{pmatrix}\in \mathrm{End}(\mathsf{E}_{1}),\qquad\forall \xi\in T^{\ast}\scrM\, ,
\end{align*}
such that $\scrS\psi=\varphi$ if and only if $\mathsf{S}_{1}\Psi=\Phi$ for all $\psi,\varphi\in C^{\infty}(\scrM,\scrE)$, where we wrote $\Psi:=(\psi,\nabla^{\scrE}\psi)$ and $\Phi:=(\phi,\nabla^{\scrE}\phi)$ as in~\eqref{eq:Extended}. 
\end{Prp}

\begin{proof}
	First of all, it is clear by definition of the principal symbol $\sigma_{\mathsf{S}_{1}}\colon T^{\ast}\scrM\to\mathrm{End}(\mathsf{E}_{1})$ and the bundle metric on $\mathsf{E}_{1}$ that $\mathsf{S}_{1}$ is again a symmetric hyperbolic system, i.e.~that both the conditions (H) and (S) of Definition~\ref{Def:SHS} are satisfied. 

	For uniqueness, assume that there exists another symmetric hyperbolic system $\mathsf{S}_{1}^{\prime}$ with the same property and set $\mathsf{T}:=\mathsf{S}_{1}-\mathsf{S}_{1}^{\prime}$. Clearly, $\mathsf{T}$ is an operator of order zero. Now, let $\psi\in C^{\infty}(\scrM,\scrE)$ be arbitrary and set $\varphi:=\scrS\psi$. Then, $\mathsf{T}\Psi=\Phi-\Phi=0$ and hence $\mathsf{S}_{1}\Psi=\mathsf{S}_{1}^{\prime}\Psi$. Since $\psi$ was arbitrary and $\mathsf{T}$ an operator of order zero, it holds that $\mathsf{T}=0$ on all of $C^{\infty}(\scrM,\mathsf{E}_{1})$ and we conclude that $\mathsf{S}_{1}=\mathsf{S}_{1}^{\prime}$.

	Now, let us turn to the construction of $\mathsf{S}_{1}$. As a first step, we choose a local coordinates chart $(x^{\mu})_{\mu=0,\dots,k}$ on some open subset $\mathcal{U}$ of $\scrM$ and write $\scrS=\sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\mu}-\scrS_{0}$ for some zero-order operator $\scrS_{0}$. Now, the commutator $[\nabla_{\mu}^{\scrE},\scrS]$ for some fixed basis vector $\partial_{\mu}$ is an operator of order zero on $C^{\infty}(\mathcal{U},\scrE)$ and a straightforward computation shows that it is explicitly given by
	\begin{align}\label{eq:Comutator}
		[\nabla_{\mu}^{\scrE},\scrS]\psi=(\nabla^{\mathrm{End}(\scrE)}_{\mu}\sigma_{\scrS}(dx^{\alpha}))\nabla_{\alpha}^{\scrE}\psi+\sigma_{\scrS}(dx^{\alpha})\mathcal{F}_{\mu\alpha}(\psi)-(\nabla^{\mathrm{End}(\scrE)}_{\mu}\scrS_{0})(\psi)
	\end{align}
	 for all $\psi\in C^{\infty}(\scrM,\scrE)$, where $\nabla^{\mathrm{End}(\scrE)}$ denotes the induced connection on  $\mathrm{End}(\scrE)$, as usual, and where $\mathcal{F}\in\Omega^{2}(\scrM,\mathrm{End}(\scrE))$ defined by $\mathcal{F}(X,Y,\bullet):=[\nabla_{X}^{\scrE},\nabla_{Y}^{\scrE}]-\nabla^{\scrE}_{[X,Y]}$ for all $X,Y\in C^{\infty}(\scrM,\scrE)$ denotes the curvature $2$-form of the bundle $(\scrE,\nabla^{\scrE})$. Now, let $\psi\in C^{\infty}(\scrM,\scrE)$ and write $\nabla^{\scrE}\psi\in C^{\infty}(\scrM,\scrE_{1})$ locally as $\nabla^{\scrE}\psi=\nabla_{\mu}^{\scrE}\psi\otimes dx^{\mu}$. Then, we obtain
\begin{align*}
	\sigma_{\mathsf{S}_{1}}(dx^{\mu})\nabla_{\mu}^{\mathsf{E}_{1}}\Psi&=\begin{pmatrix}
	\sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\mu}\psi\\
	(\sigma_{\scrS}(dx^{\mu})\otimes\mathrm{id})\nabla^{\scrE_{1}}_{\mu}(\nabla^{\scrE}\psi))
	\end{pmatrix}\\&=\begin{pmatrix}
	(\scrS+\scrS_{0})\psi\\
	\sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\mu}\nabla^{\scrE}_{\alpha}\psi\otimes dx^{\alpha}+ \sigma_{\scrS}(dx^{\mu})\nabla^{\scrE}_{\alpha}\psi\otimes \nabla^{0}_{\mu}dx^{\alpha}
	\end{pmatrix}\\&=\begin{pmatrix}
	(\scrS+\scrS_{0})\psi\\
	(\scrS+\scrS_{0})(\nabla^{\scrE}_{\alpha}\psi)\otimes dx^{\alpha}-(\Gamma^{0})_{\mu\beta}^{\alpha}\sigma_{\scrS}(dx^{\mu})\nabla_{\alpha}^{\scrE}\psi\otimes dx^{\beta}
	\end{pmatrix}\\&=
	\begin{pmatrix}
		\scrS\psi\\
		\nabla^{\scrE}(\scrS\psi)
	\end{pmatrix}+\underbrace{\begin{pmatrix}
	\scrS_{0}\psi\\
	([\scrS,\nabla^{\scrE}_{\mu}]\psi+\scrS_{0}\nabla^{\scrE}_{\mu}\psi-(\Gamma^{0})_{\mu\beta}^{\alpha}\sigma_{\scrS}(dx^{\mu})\nabla_{\alpha}^{\scrE}\psi)\otimes dx^{\mu}
	\end{pmatrix}}_{=:\mathsf{S}_{1,0}\Psi}\, ,
\end{align*}
where $\Gamma^{0}$ are the Christoffel symbols of the auxiliary Riemannian manifold $(\scrM,g_{0})$. The operator $\mathsf{S}_{1,0}$ defined above clearly has order zero and we set 
\begin{align*}
	\mathsf{S}_{1}:=\sigma_{\mathsf{S}_{1}}(dx^{\mu})\nabla_{\mu}^{\mathsf{E}_{1}}-\mathsf{S}_{1,0}\, .
\end{align*}	
	 By construction, it holds that $\scrS\psi=\phi$ if and only if $\mathsf{S}_{1}\Psi=\Phi$ for all $\psi,\varphi\in C^{\infty}(\scrM,\scrE)$, where $\Psi:=(\psi,\nabla^{\scrE}\psi)$ and $\Phi:=(\phi,\nabla^{\scrE}\phi)$, which concludes the proof.
\end{proof}

Note that the zero-order term $\mathsf{S}_{1,0}\in C^{\infty}(\scrM,\mathrm{End}(\mathsf{E}_{1}))$ of the system $\sf{S}_{1}$ as constructed in the previous proof involves the derivatives of the principal symbol and $0^{\mathrm{th}}$-order terms of $\scrS$ as well as terms involving the bundle curvature of $(\scrE,\nabla^{\scrE})$. More precisely, using~\eqref{eq:Comutator}, it is explicitly given by
\begin{align}\label{eq:ZeroORderExt}
	&\mathsf{S}_{1,0}=\begin{pmatrix}
		\scrS_{0} & 0 \\ \scrA &\scrB
	\end{pmatrix}\colon C^{\infty}(\scrM,\mathsf{E}_{1})\to C^{\infty}(\scrM,\mathsf{E}_{1})
\end{align}
with zero-order operators $\scrA\colon C^{\infty}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE_{1})$ and $\scrB\colon C^{\infty}(\scrM,\scrE_{1})\to C^{\infty}(\scrM,\scrE_{1})$ given by
\begin{align*}
	\scrA\psi&:= \bigg(\sigma_{\scrS}(dx^{\alpha})\mathcal{F}_{\mu\alpha}-\nabla^{\mathrm{End}(\scrE)}_{\mu}\scrS_{0}\bigg)\psi\otimes dx^{\mu}\\
	\scrB\omega&:=\bigg(\delta^{\gamma}_{\alpha}\nabla^{\mathrm{End}(\scrE)}_{\mu}\sigma_{\scrS}(dx^{\alpha})-(\Gamma^{0})_{\alpha\mu}^{\gamma}\sigma_{\scrS}(dx^{\alpha})+\delta^{\gamma}_{\mu}\scrS_{0}\bigg)\omega_{\gamma}\otimes dx^{\mu}	
\end{align*}
where we expanded $\omega=\omega_{\alpha}\otimes dx^{\alpha}$ for coefficients $\omega_{\alpha}\in C^{\infty}(\mathcal{U},\scrE)$ in a local coordinate chart $(\mathcal{U},(x^{\mu})_{\mu=0,\dots,k})$ of $\scrM$.

\begin{Example}\label{Example:MinkoExtSys}
	Consider Minkowski spacetime $\scrM = \mathbb{R} \times \mathbb{R}^{k}$ and the trivial vector bundle $\scrE=\scrM\times\mathbb{C}^{N}$ of rank $N\in\N$, equipped with the standard complex inner product on its fibres, as discussed in Example~\ref{Ex:MinkSHS}. In this case, any symmetric hyperbolic system can be written in the form $\scrS = A^{\mu} \partial_{\mu} - \scrS_{0}$, where each $A^{\mu} \in C^{\infty}(\scrM, \mathbb{C}^{N \times N})$ is a smooth, pointwise Hermitian matrix-valued function, and $\scrS_{0}$ is a zero-order operator. In this case, $\mathsf{S}_{1}$ is given by
	\begin{align*}
		\mathsf{S}_{1}
		\begin{pmatrix}
			\psi\\ \omega_{\alpha}\otimes dx^{\alpha}
		\end{pmatrix}=
		\begin{pmatrix}
			A^{\mu}\partial_{\mu}\psi\\
			(A^{\mu}\partial_{\mu}\omega_{\alpha})\otimes dx^{\alpha}
		\end{pmatrix}-
		\begin{pmatrix}
			\scrS_{0}\psi\\
			\big((\partial_{\alpha}A^{\mu})\omega_{\mu}+\scrS_{0}\omega_{\alpha}-(\partial_{\alpha}\scrS_{0})\psi\big)\otimes dx^{\alpha}
		\end{pmatrix}
\end{align*}	 
for all $(\psi,\omega_{\alpha}\otimes dx^{\alpha})\in C^{\infty}(\scrM,\mathrm{End}(\mathsf{E}_{1}))$. Hence, we see that $\sf{S}_{1}$ is constructed out of the principal symbol $\sigma_{\scrS}(\xi)=A^{\mu}\xi_{\mu}$ and zero-order terms $\scrS_{0}$ of $\scrS$ and their derivatives. If the matrix-valued functions do actually not depend on the point and hence $\partial_{\alpha}A_{\beta}=0$ and $\partial_{\alpha}\scrS_{0}=0$, and if $\scrS_{0}$ is an imaginary number, it holds that $\scrS+\scrS^{\dagger}=0$ as well as $\mathsf{S}_{1}+\mathsf{S}_{1}^{\dagger}=0$. This is for example the case for the Dirac operator in Minkowski spacetime.
\end{Example}

Now, applying the procedure of the previous proposition inductively, we obtain a whole family of symmetric hyperbolic systems $\{\mathsf{S}_{k}\}_{k\geq 1}$ on the bundles
\begin{align*}
	\mathsf{E}_{0}:=\scrE,\qquad \mathsf{E}_{i+1}:=\mathsf{E}_{i}\oplus (\mathsf{E}_{i}\otimes T^{\ast}\scrM)\quad\forall i\geq 0
\end{align*}
equipped with the obvious bundle metrics and connections such that 
\begin{align*}
	\scrS\psi=\phi\qquad\Leftrightarrow\qquad\mathsf{S}_{i}\Psi_{i}=\Phi_{i},\qquad\Psi_{i}:=(\Psi_{i-1},\nabla^{\mathsf{E}_{i-1}}\Psi_{i-1})
\end{align*}

Now, suppose that $\B\colon C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ is a semi-regular linear operator. Note that the composition $\nabla^{\scrE}\B\colon C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE_{1})$ is a gain a continuous operator with a Schwartz kernel. In the case of symmetric hyperbolic systems with nonlocal potentials, we obtain the following generalisation of the previous proposition.

\begin{Prp}\label{Prop:SHSDerNOnLoc}	Let $\scrS$ be a symmetric hyperbolic system over $(\scrE,\Sl\cdot|\cdot\Sr_{\scrE})$ and let $\B\colon C^{\infty}_{\mathrm{c}}(\scrM,\scrE)\to C^{\infty}(\scrM,\scrE)$ be a nonlocal potential. If $\mathsf{S}_{1}$ denotes the corresponding symmetric hyperbolic system on $\mathsf{E}_{1}$, then
\begin{align*}
	(\scrS-\B)\psi=\varphi\qquad\Leftrightarrow\qquad (\mathsf{S}_{1}-\mathsf{B}_{1})\Psi=\Phi\, ,
\end{align*}
where $\mathsf{B}_{1}\colon C^{\infty}_{\mathrm{c}}(\scrM,\mathsf{E}_{1})\to C^{\infty}(\scrM,\mathsf{E}_{1})$ denotes the operator defined by
\begin{align}\label{eq:ExtB1}
	\mathsf{B}_{1}:=\begin{pmatrix}
	\B & 0\\  \nabla^{\scrE}\circ\B- (\B\otimes\mathrm{id})\circ\nabla^{\scrE}  & \B\otimes\mathrm{id}
	\end{pmatrix}
\end{align}
\end{Prp}
%
\begin{proof}
	The proof follows the same steps as in Proposition~\ref{Prop:SHSDer}.
\end{proof}

\begin{Remark}
	Note that the operator $\sf{B}_{1}$ is in general not a nonlocal potential in the sense of Definition~\ref{Def:NonLocPot}, since it might not be locally integrable in time and hence not posses a time kernel according to our definition. If $k_{\B}$ is sufficiently regular in time, however, this is the case. Furthermore, in some cases, $\sf{B}_{1}$ can be split into a nonlocal potential with time kernel and a local operator, that can be reabsorbed in the zero-order terms $\sf{S}_{1,0}$ of the symmetric hyperbolic system. 
\end{Remark}

Similar to above, we define inductively the nonlocal potentials $\mathsf{B}_{i}\colon C^{\infty}_{\mathrm{c}}(\scrM,\mathsf{E}_{i})\to C^{\infty}(\scrM,\mathsf{E}_{i})$ in the bundles $\mathsf{E}_{i}=\mathsf{E}_{i-1}\oplus (\mathsf{E}_{i-1}\otimes T^{\ast}\scrM)$ by
\begin{align*}
	\mathsf{B}_{i}:=\begin{pmatrix}
	\mathsf{B}_{i-1} & 0\\ \nabla^{\mathsf{E}_{i-1}}\circ\mathsf{B}_{i-1}-(\mathsf{B}_{i-1}\otimes\mathrm{id})\circ\nabla^{\mathsf{E}_{i-1}} & \mathsf{B}_{i-1}\otimes\mathrm{id}
	\end{pmatrix}\, .
\end{align*}

\subsection{Retarded Nonlocalities} \label{Subsection:Ret}
In this section, we present the first main result concerning the analysis of the Cauchy problem for symmetric hyperbolic systems with nonlocal potentials. As a first result, we focus in this section on the case where the system is coupled to a \textit{retarded} nonlocal potential, as defined in Definition~\ref{Def:Potentials}(i). This setting is particularly suited for initial investigation due to its inherent causal structure. The central objective of this section is to proof that the Cauchy problem~\eqref{eq:SymNonLoc} is well-posed in this case. 

To start with, consider Set-up~\ref{Setup} and let $\overline{\scrM}_{T}:=[0,T]\times\scrN$ be the closed time strip of size $T>0$. If $\B$ is a retarded nonlocal potential, our aim is to study the Cauchy problem
\begin{align}\label{eq:CauchyRetarted}
	\begin{cases}
		(\scrS-\B)\psi &=\phi\\
		\psi\vert_{\scrN_{0}}&=\mathfrak{f}
	\end{cases}
\end{align}	
for a given source $\phi\in C_{\mathrm{c}}^{\infty}(\scrM,\scrE)$ with $\mathrm{supp}(\phi)\subset \overline{\scrM}_{T}$ and initial datum $\mathfrak{f}\in C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$. As already specified at the beginning of Section~\ref{Sec:SHSNonLoc}, we additionally assume that the kernel $k_{\B}$ has \emph{past compact support}, meaning that $\B_{t,\tau} = 0$ whenever $\tau < -t_0$ for some fixed $t_0 > 0$. In the following, we restrict to the case $t_0 = 0$, i.e.~we prescribe initial data on the slice where the nonlocality is effectively ``switched on''. We comment on the more general case $t_0 \neq 0$, i.e.~in which the initial data are assigned slightly in the future of the switch-on time $t_{0}$, below in Remark~\ref{Remark:NonZeroIni}.

The main objective of this section is to prove the following theorem on the existence and uniqueness of the solutions to the Cauchy problem~\eqref{eq:CauchyRetarted}. 

\begin{Thm}[Cauchy Problem for Retarded Nonlocalities]\label{Thm:Ret} 
	Assume~Set-up~\ref{Setup} and suppose that the nonlocal potential $\B$ satisfies the following assumptions:
	\begin{itemize}
		\item[(i)]$\B$ is retarded and hence $\B_{t,\tau}=0$ for $\tau>t$ (see~Definition~\ref{Def:Potentials}(i)) and past compactly supported with switch-one time $t_{0}=0$, i.e.~$\B_{t,\tau}=0$ for $\tau<0$.
		\item[(ii)]$\B$ is uniformly bounded in the time strip, i.e.~there exists a constant $C_{T}>0$ such that $\Vert\V_{t,\tau}\varphi_{\tau}\Vert_{t}\leq C_{T}\Vert\varphi_{\tau}\Vert_{\tau}$ for all $\varphi\in C^{\infty}_{\mathrm{c}}(\scrN_{\tau},\scrE\vert_{\scrN_{\tau}})$ and $t,\tau\in [0,T]$.
		\end{itemize}
		Then, there exists a strong solution of the Cauchy problem~\ref{eq:CauchyRetarted} (see~Definition~\ref{Def:StrongSol}(R)). Furthermore, if we assume in addition that
	\begin{itemize}
		\item[(iii)]there is a $j\geq 1$ such that also $\mathsf{B}_{i}$ for $i=1,\dots,j$ are nonlocal potentials with time kernels satisfying the boundedness assumption (ii) as well\footnote{If $\mathsf{B}_{i}$ is a nonlocal potential with time kernel, then it is automatically retarded provided $\mathsf{B}_{i-1}$ is retarded, as one can easily see from the explicit expression.},
	\end{itemize}
	then, $\psi\in W^{2,j}(\scrM_{T},\scrE_{\beta})$ and in particular $\psi\in C^{l}(\overline{\scrM}_{T},\scrE)$ for $l\in\N$ such that $j\geq \frac{k+1}{2}+l$. In other words, $\psi$ is a classical solution to the Cauchy problem (see~Definition~\ref{Def:ClassSol}(R)). Furthermore, the solution $\psi$ is unique in this case and satisfies
	\begin{align*}
			\mathrm{supp}(\psi)\cap J^{+}(\scrN_{0})\subset J^{+}(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))\, .
	\end{align*}
\end{Thm}

We will split the proof of this theorem in several parts. 

\begin{Prp}\label{Prop:DysonRet}
	Assume Set-up.~\ref{Setup} together with assumptions (i)-(ii) in Theorem~\ref{Thm:Ret} and let $\psi^{(n)}\in C^{\infty}(\scrM,\scrE)$ be the sections inductively defined as the (unique) solutions to the local Cauchy problems
	\begin{align*}
		\begin{cases}
			\scrS\psi^{(0)} &=\phi\\
			\psi^{(0)}\vert_{\scrN_{0}}&=\mathfrak{f}
		\end{cases}\qquad\text{and}\qquad 
		\begin{cases}
			\scrS\psi^{(n+1)} &=\B\psi^{(n)}\\
			\psi^{(n+1)}\vert_{\scrN_{0}}&=0
		\end{cases},\quad n\geq 0\, .
	\end{align*}
	Then, $\psi_{t}:=\sum_{n=0}^{\infty}\psi^{(n)}_{t}$ is absolutely convergent in the Hilbert space $\H_{t}$ for every $t\in [0,T]$. Furthermore, the map $\psi:t\mapsto\psi_{t}$ is a well-defined element in the space $\H_{\overline{\scrM}_{T}}$.

	Furthermore, if instead of assumption (ii), $\V_{t,\tau}$ is uniformly bounded on all of $\R$, i.e.~if there exists a constant $C>0$ such that $\Vert\V_{t,\tau}\varphi_{\tau}\Vert_{t}\leq C\Vert\varphi_{\tau}\Vert_{\tau}$ for all $\varphi\in C^{\infty}_{\mathrm{c}}(\scrN_{\tau},\scrE\vert_{\scrN_{\tau}})$ and $t\in\R$, then $\psi$ is a well-defined element of $L_{\mathrm{loc}}^{2}([0,\infty),\H_{\bullet})$.
\end{Prp}

\begin{Remark}
	The collection $(\H_{t})_{t\in\R}$ can be thought of as a bundle of Hilbert spaces over $\R$ and spaces such as $L^{2}_{\mathrm{loc}}([0,T],\H_{\bullet})$ are hence defined as the $L^{2}_{\mathrm{loc}}$-sections of this bundle.
\end{Remark}

\begin{proof}[Proof of Proposition~\ref{Prop:DysonRet}]
	Let $\psi^{(n)}$ be the solutions to the local Cauchy problems as defined in the statement of the proposition. By finite speed of propagation, see~Theorem~\ref{Thm:WellPosedCauchy}, together with assumptions (i) and (ii) of the nonlocal potential $\B$, it holds that 
	\begin{align*}
		\mathrm{supp}(\psi^{(0)})\cap J^{+}(\scrN_{0}) \subset J^{+}(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))\quad\text{and}\quad \mathrm{supp}(\psi^{(n)}) \subset J^{+}(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))
	\end{align*}
	 for all $n\geq 1$. In particular, note that all the support of all the sections $\psi^{(n)}$ is contained within the same set in the future of $\scrN_{0}$. Furthermore, note that $\B\psi^{(n)}$ is well-defined, since $\B$ extends to an operator acting on smooth sections, which are in $\H_{t}$ at any fixed $t\in \R$, as a consequence of assumptions (i), (ii) and the standard energy estimates.
	Now, the goal of the following discussion is to show that the perturbative ansatz
	\begin{align}\label{eq:SeriesAnsatz}
		\psi=\sum_{n=0}^{\infty}\psi^{(n)}
	\end{align}
	is absolutely convergent in $\mathcal{H}_{t}$ for every $t\in [0,T]$. Using the energy estimates from Corollary~\ref{Cor:EnEst}, we have
	\begin{align*}
		\frac{d}{dt}\Vert\psi^{(n+1)}_{t}\Vert_{t}\leq \int_{\R}\Vert \V_{t,\tau}\psi^{(n)}_{\tau}\Vert_{t}\,d\tau+\frac{1}{2}\Vert(\mathcal{Z}_{\scrS}\psi^{(n+1)})_{t}\Vert_{t}
	\end{align*}
	for all $n\in\N$ and $t\in [0,T]$, where $\mathcal{Z}_{\scrS}:=\beta\sigma_{\scrS}(\eta)^{-1}(\scrS+\scrS^{\dagger})$ is an operator of order zero. Since all the sections $\psi^{(n)}$ are contained within the same compact set on $\overline{\scrM}_{T}$, there exists a $D_{T}>0$ such that
	\begin{align}\label{eq:ZeroOrder}
		\Vert (\mathcal{Z}_{\scrS}\psi^{(n)})_{t}\Vert_{t}\leq D_{T}\Vert\psi^{(n)}_{t}\Vert_{t}
	\end{align}
	for all $t\in [0,T]$ and $n\in\N$. Using the assumptions (i)-(ii) as well as the fact that $\psi^{(n)}=0$ for $t<0$ and $n\geq 1$, we obtain the estimate
	\begin{align*}
		\frac{d}{dt}\Vert\psi^{(n+1)}_{t}\Vert_{t}&\leq C_{T}\int_{0}^{t}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau+\frac{1}{2}D_{T}\Vert\psi_{t}^{(n+1)}\Vert_{t}\, ,
	\end{align*}
	for all $n\in\mathbb{N}$ and $t\in [0,T]$. Multiplying by $e^{-\frac{1}{2}Dt}$, this estimate can be written in the compact form
	\begin{align*}
		\frac{d}{dt}(e^{-\frac{1}{2}D_{T}t}\Vert\psi^{(n+1)}_{t}\Vert_{t})&\leq C_{T}e^{-\frac{1}{2}D_{T}t}\int_{0}^{t}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau\leq C_{T}\int_{0}^{t}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau
	\end{align*}
	and integrating over time from $0$ to $t\in [0,T]$, we obtain the inequality
	\begin{align*}
		\Vert\psi^{(n+1)}_{t}\Vert_{t} \leq C_{T}e^{\frac{1}{2}D_{T}t}\int_{0}^{t}\int_{0}^{\tau}\Vert \psi^{(n)}_{s}\Vert_{s}\, ds\,d\tau\,,
	\end{align*}
	where we used again the fact that $\psi^{(n)}=0$ for $t\leq 0$. Last but not least, we bound $e^{\frac{1}{2}D_{T}t}\leq e^{\frac{1}{2}D_{T}T}$ for all $t\in [0,T]$ to obtain the estimate
	\begin{align}\label{eq:Estimate}
		\Vert\psi^{(n+1)}_{t}\Vert_{t} \leq K_{T}\int_{0}^{t}(t-\tau)\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\,d\tau
	\end{align}
	for all $n\in\mathbb{N}$ and $t\in [0,T]$, where we set $K_{T}:=C_{T}e^{\frac{1}{2}D_{T}T}>0$.

	Now, consider the induction hypothesis $\Vert\psi_{t}^{(n)}\Vert_{t}\leq \kappa(n)t^{2n}M_{T}$ for all $t\in [0,T]$, where \begin{align*}M_{T}:=\max_{t\in [0,T]}\Vert\psi^{(0)}_{t}\Vert_{t}\,.\end{align*} By finite speed of propagation, $M_{T}$ is clearly finite, and the ansatz trivially holds true for $n=0$ with $\kappa(0)=1$. By induction, we assume that it is true for $n$. Using the estimate~\eqref{eq:Estimate}, we obtain
	\begin{align*}
		\Vert\psi^{(n+1)}_{t}\Vert_{t} &\leq K_{T}\int_{0}^{t}(t-\tau)\Vert \psi^{(n)}_{t}\Vert_{\tau}\, d\tau\leq K_{T}M_{T}\kappa(n)\frac{t^{2n+2}}{(2n+1)(2n+2)}\, .
	\end{align*}
	This completes the inductive step and allows us to determine the coefficients $\kappa(n)$ in $\Vert\psi_{t}^{(n)}\Vert_{t}\leq \kappa(n)t^{2n}M_{T}$ as $\kappa(n)=\frac{K_{T}^n}{(2n)!}$. To sum up, we have shown that 
	\begin{align*}
		\forall t\in [0,T]\,,n\in\N:\quad \Vert\psi_{t}^{(n)}\Vert_{t}\leq \frac{K_{T}^n}{(2n)!}t^{2n}
	\end{align*}
	In particular, this implies that the perturbative series~\eqref{eq:SeriesAnsatz} is absolutely convergent in the $\H_{t}$-topology for every $t\in [0,T]$, since
	\begin{align*}
	\sum_{n=0}^{\infty}\Vert\psi^{(n)}_{t}\Vert_{t}\leq \sum_{n=0}^{\infty}\frac{M_{T}K_{T}^{n}t^{2n}}{(2n)!}=M_{T}\mathrm{cosh}(\sqrt{K_{T}}t)<\infty\, .
	\end{align*}

	Now, we have constructed a map $\psi:t\mapsto\psi_{t}$, where $\psi_{t}$ is the limit of the series~\ref{eq:SeriesAnsatz} in the $\H_{t}$-topology. Now, it is clear that $t\mapsto \psi_{t}$ is measurable, since it is the pointwise limit of the smooth (and in particular strongly measurable) functions $t\mapsto \sum_{k=0}^{n}\psi^{(k)}_{t}$ for $n\to\infty$, see e.g.~\cite[Thm.~1.14]{AmannEscherIII}. To see that $\psi$ is an element of $L^{2}([0,T],\H_{\bullet})$, we note that the above estimates imply
\begin{align*}
		\Vert\psi\Vert_{\scrM_{T}}^{2}=\int_{0}^{T}\Vert\psi_{t}\Vert_{t}^{2}\,dt\leq M_{T}^{2}\int_{0}^{T} \mathrm{cosh}(\sqrt{K_{T}}t)^{2}\,dt=M_{T}^{2}\bigg(\frac{T}{2}+\frac{\mathrm{sinh}(2\sqrt{K_{T}}T)}{4\sqrt{K_{T}}}\bigg)<\infty\,.
	\end{align*}
	It is easy to see that the series~\eqref{eq:SeriesAnsatz} converges also in the $\H_{\overline{\scrM}_{T}}$-topology and by the dominant convergence theorem for series (see e.g.~\cite[Thm.~3.16]{AmannEscherIII}), we conclude that the corresponding limit coincides with $\psi$.

	If $\V_{t,\tau}$ is uniformly bounded for all $t\in [0,\infty)$ by a constant $C>0$ independent of time, we can repeat the same argument as above for every choice of $T>0$. In particular, we conclude that the series~\eqref{eq:SeriesAnsatz} converges in the $\H_{\overline{\scrM}_{T}}$ topology for every fixed $T>0$ in this case, which proves the claim.
\end{proof}


\begin{Remark}\label{Remark:NonZeroIni} 
	Let us remark that in the proof of in Proposition~\ref{Prop:DysonRet} , it was crucial that the retarded nonlocal potential $\B$ had past compact support. In fact, we needed two additional assumptions to be considered separately:
	\begin{itemize}
		\item[(i)]The nonlocal potential $\B$ has past compact support, i.e.~$\B_{t,\tau}=0$ for $\tau<-t_{0}$ and some fixed $t_{0}>0$.
		\item[(ii)]We assign initial data on a Cauchy slice that is in the past of $\scrN_{-t_{0}}$. Without loss of generality, we hence choose the foliation such that $t_{0}=0$ and assign initial data on $\scrN_{0}$.
	\end{itemize}
	Now, assumption (i) is crucial for the the local solutions $\psi^{(n)}$ constructed in Proposition~\ref{Prop:DysonRet} to be well-defined. Recall that our solution $\psi$ to the Cauchy problem~\eqref{eq:CauchyRetarted} was defined as the limit of the series of the solutions $\psi^{(n)}$ to the local Cauchy problems
	\begin{align*}
		\begin{cases}
			\scrS\psi^{(0)} &=\phi\\
			\psi^{(0)}\vert_{\scrN_{0}}&=\mathfrak{f}
		\end{cases}\qquad\text{and}\qquad 
		\begin{cases}
			\scrS\psi^{(n+1)} &=\B\psi^{(n)}\\
			\psi^{(n+1)}\vert_{\scrN_{0}}&=0
		\end{cases},\quad n\geq 0\, .
	\end{align*}
	for a given source $\phi\in C^{\infty}_{\mathrm{c}}(\overline{\scrM}_{T},\scrE)$ and initial datum $\mathfrak{f}\in C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$. Now, in general, the solutions $\psi^{(n)}$ also propagate to the past and thus, without assumption (i), already at the step $n = 1$, it is not clear whether the right-hand side $\B\psi^{(0)}$ can be consistently defined. Using the energy estimates (see Corollary~\ref{Cor:EnEstLoc}), we know that $\Vert\psi^{(0)}_{t}\Vert_{t} \sim e^{|t|}$, and hence,
\begin{align*}
	\Vert(\B\psi^{(0)})_{t}\Vert_{t}= \int_{-\infty}^{t} \Vert\B_{t,\tau} \psi^{(0)}_{\tau}\Vert_{t} \, d\tau
\end{align*}
is still well-defined, provided that the kernel $\B_{t,\tau}$ decays sufficiently fast as $\tau \to -\infty$. In general, however, it is unclear whether one can formulate a criterion on the kernel ensuring that $\B\psi^{(n)}$ is consistently defined for all $n \in \mathbb{N}$, beyond examining specific examples.\medskip

	Concerning the case where the nonlocal potential is ``switched on'' at a time  $-t_0 < 0$,  it is possible to readapt the estimates performed in the proof of Proposition~\ref{Prop:DysonRet} to prove the convergence of the perturbative series $\sum_n \psi^{(n)}$, provided that $t_0$ and $C$, the uniform bound of the nonlocal potential $\B$, satisfy
$$ t_0^2 e^{\frac{1}{2}Dt_0}  C <1 \,.$$ 
\end{Remark}


Next, we show that the element $\psi\in L^{2}_{\mathrm{loc}}([0,T],\H_{\bullet})$ constructed in the previous proposition defines a strong solution to the Cauchy problem~\eqref{eq:CauchyRetarted}.

\begin{Prp}\label{Prp:Ret} Assume~Set-up~\ref{Setup} together with assumptions (i)-(ii) in Theorem~\ref{Thm:Ret}. Then, there exists a strong solution of the Cauchy problem~\eqref{eq:SymNonLoc} on $\overline{\scrM}_{T}$. 
\end{Prp}

\begin{proof}
	Consider the sequence $(\psi^{(n)})_{n\in\N}$ as constructed in Proposition~\ref{Prop:DysonRet}. As shown in this proposition, the corresponding series converges absolutely in the $\H_{\overline{\scrM}_{T}}$ topology to some element $\psi\in\H_{\overline{\scrM}_{T}}$. We will now show that $\psi$ is a {strong} solution to the Cauchy problem~\eqref{eq:SymNonLoc}. For this, we write
	\begin{align*}
		\psi_{k}:=\sum_{n=0}^{k}\psi^{(n)}\in C^{\infty}(\scrM,\scrE)
	\end{align*}
	for $k\in\N$. As shown above, it holds that $\Vert\psi_{k}-\psi\Vert_{\scrM_{T}}\to 0$ as $k\to\infty$. Furthermore, it is clear that also $\Vert\psi_{k}\vert_{\scrN_{0}}-\mathfrak{f}\Vert_{0}\xrightarrow{k\to\infty} 0$, since $\psi_{k}\vert_{\scrN_{0}}=\mathfrak{f}$ for all $k\in\N$, by construction. Note also that
	\begin{align*}
		\Vert\psi^{(n)}\Vert_{\scrM_{T}}\xrightarrow{n\to\infty}0\, ,
	\end{align*}
	 since otherwise the series~\eqref{eq:SeriesAnsatz} would not converge absolutely. 

	On the other hand, it holds that $(\scrS-\B)\psi_{k}=\phi-\B\psi^{(k)}$, by construction, and hence, we get
	\begin{align*}
		\|(\scrS-\B)\psi_{k}-\phi\|^2_{\scrM_{T}}&=(\B\psi^{(k)}|\B\psi^{(k)})_{\scrM_{T}}= \int_{0}^{T}\,dt\,\int_{0}^{t}\,d\tau\,\int_{0}^{t}\,ds\,(\B_{t,\tau}\psi_{\tau}^{(k)}|\B_{t,s}\psi_{s}^{(k)})_{t}\\
		&\leq (C^{\prime}_{T})^{2}\int_{0}^{T}\,dt\,\int_{0}^{t}\,d\tau\,\int_{0}^{t}\,ds\,\Vert\psi_{\tau}^{(k)}\Vert_{\tau}\Vert\psi_{s}^{(k)}\Vert_{s} \\
		 &\leq T^{2}(C^{\prime}_{T})^{2} \Vert \psi^{(k)}\Vert_{\scrM_{T}}^2\xrightarrow{k\to\infty}0\, ,
	\end{align*}
	where we used Hölder's inequality. Furthermore, we used the following: By assumption, it holds that $\Vert\V_{t,\tau}\psi^{(k)}_{\tau}\Vert_{t}\leq C_{T}\Vert\psi^{(k)}_{\tau}\Vert_{\tau}$ for all $k\in\mathbb{N}$ and $t,\tau\in [0,T]$, where $\V=\beta\sigma_{\scrS}(\eta)^{-1}\B$. Now, since $\psi^{(k)}$ for arbitrary $k\in\mathbb{N}$ are supported within the same set as explained in the proof of Proposition~\ref{Prop:DysonRet}, the norm $\Vert\B_{t,\tau}\psi^{(k)}_{\tau}\Vert_{t}$ can be bounded by $\Vert\V_{t,\tau}\psi^{(k)}_{\tau}\Vert_{t}$ on $[0,T]$ and vice versa. Hence, we obtain a similar estimate for $\B_{t,\tau}$ for some constant $C^{\prime}_{T}>0$. 
	This conclude our proof.
\end{proof}
\black



\begin{Prp}[Regularity of Solutions]\label{Prp:RetReg} 		If condition (iii) in Theorem~\ref{Thm:Ret} is satisfied for some $j\in\N$ holds, then the strong solution $\psi$ constructed in Proposition~\eqref{Prp:Ret} is in the Sobolev space $W^{2,j}(\scrM_{T},\scrE_{\beta})$. In particular, by the Sobolev embedding theorem, $\psi$ is a classical solution with $\psi\in C^{l}(\overline{\scrM}_{T},\scrE)$ for $j\geq \frac{k+1}{2}+l$.
\end{Prp}



\begin{proof}
	We proof the claim by induction: Let $\psi\in\H_{\overline{\scrM}_{T}}$ be the strong solution constructed in Proposition~\ref{Prp:Ret}, i.e.~$\psi=\sum_{k=0}^{\infty}\psi^{(k)}$, where $\psi^{(k)}\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ are the unique solutions to the local Cauchy problems
	\begin{align*}
		\begin{cases}
			\scrS\psi^{(0)} &=\phi\\
			\psi^{(0)}\vert_{\scrN_{0}}&=\mathfrak{f}
		\end{cases}
		\qquad\text{and}\qquad  
		\begin{cases}
			\scrS\psi^{(n+1)} &=\B\psi^{(n)}\\
			\psi^{(n+1)}\vert_{\scrN_{0}}&=0
		\end{cases},\quad n\geq 0\, .
	\end{align*} 
	Now, consider the system $\mathsf{S}_{1}$ on 	$\mathsf{E}_{1}$ as defined in Proposition~\ref{Prop:SHSDer} and Proposition~\ref{Prop:SHSDerNOnLoc}. If the nonlocal potential $\mathsf{B}_{1}$ satisfies the same conditions as $\B$, we can construct a strong solution $\Psi$ of the nonlocal Cauchy problem
	\begin{align}\label{sdfgdS}
		\begin{cases}
			(\mathsf{S}_{1}-\mathsf{B}_{1})\Psi=\Phi\\
			\Psi\vert_{\scrN_{0}}=\mathfrak{F}
		\end{cases}
	\end{align}
	with $\Phi=(\phi,\nabla^{\scrE}\phi)$ and where the initial data $\mathfrak{F}\in C^{\infty}(\scrN_{0},\mathsf{E}_{1}\vert_{\scrN_{0}})$ is given by
	\begin{align*}
		\mathfrak{F}=(\mathfrak{f},\sigma_{\scrS}(dt)^{-1}(\phi\vert_{\scrN_{0}}+\scrS_{0}\mathfrak{f}-\sigma_{\scrS}(dx^{i})\nabla_{i}^{\scrE}\mathfrak{f})\otimes dt+\nabla_{\partial_{i}}^{\scrE}\mathfrak{f}\otimes dx^{i})
	\end{align*}		
	 by considering the perturbative ansatz $\Psi=\sum_{k=0}^{\infty}\Psi^{(k)}$ with $\Psi^{(k)}$ being the unique solutions to the local problems
	\begin{align*}
		\begin{cases}
			\mathsf{S}_{1}\Psi^{(0)} &=\Phi\\
			\Psi^{(0)}\vert_{\scrN_{0}}&=\mathfrak{F}
		\end{cases}
		\qquad\text{and}\qquad  
		\begin{cases}
			\mathsf{S}_{1}\Psi^{(n+1)} &=\mathsf{B}_{1}\Psi^{(n)}\\
			\Psi^{(n+1)}\vert_{\scrN_{0}}&=0
		\end{cases},\quad n\geq 0\, .
	\end{align*} 
	Now, due to the past-compactness assumption on $\B$, it holds that $(\B\psi^{(k)})\vert_{\scrN_{0}}=0$ for all $k\in\N$. In particular, this implies that the local solutions $\psi^{(n)}$ satisfy
	\begin{align*}
		\nabla^{\scrE}\psi^{(n)}\vert_{\scrN_{0}}=0\, .
	\end{align*}
	In particular, by uniqueness of solutions to the local equations, we conclude that in fact $\Psi^{(n)}=(\psi^{(n)},\nabla^{\scrE}\psi^{(n)})$ for all $n\in\N$.

	Now, let us write $\eta:=\mathrm{pr}_{2}\Psi$. By construction, $\nabla^{\scrE}\psi_{n}\to\eta$ where $\psi_{n}:=\sum_{k=0}^{n}\psi^{(k)}$ as $k\to\infty$ in $\H_{\overline{\scrM}_{T}}$. In particular, this shows that the sequence $(\psi_{n})_{n}$ converges also in $W^{2,1}(\scrM_{T},\scrE_{\beta})$, since 
	\begin{align*}
		\Vert \psi_{n}-\psi_{m}\Vert_{W^{2,1}}^{2}=\Vert \psi_{n}-\psi_{m}\Vert_{L^{2}}^{2}+\Vert \nabla^{\scrE}\psi_{n}-\nabla^{\scrE}\psi_{m}\Vert_{L^{2}}^{2}\to 0\, ,
	\end{align*}
	cf.~Remark~\ref{Rem:SobSpL2}. Now, it is clear that the limit of the sequence $(\psi_{n})_{n}$ in $W^{2,1}(\scrM_{T},\scrE_{\beta})$ coincides with $\psi$, which is the limit of $(\psi_{n})_{n}$ in $\H_{\scrM_{t}}$, since $\Vert\cdot\Vert_{\scrM_{T}}\leq \Vert\cdot\Vert_{W^{2,1}(\scrM_{T},\scrE_{\beta})}$. Hence, we conclude that $\psi\in W^{2,1}(\scrM_{T},\scrE_{\beta})$. Proceeding by induction, we obtain $\psi\in W^{2,j}(\scrM_{T},\scrE_{\beta})$ whenever $\mathsf{S}_{k}$ and $\mathsf{B}_{k}$ satisfy the assumptions (i)-(iii) up to order $j$.

	In order to show that the solution is actually a classical solution, we choose a partition of unity $\{\rho_i\}$ subordinated to precompact chart $\mathcal{U}_i$ and a corresponding local trivialisation of $\scrE$. Then it is clear that $\psi_i=\rho_i \psi \in W^{2,j}(\mathcal{U}_i\,, \C^N)$ and by the Sobolev embedding theorem we can conclude that $\psi_i\in C^l(\mathcal{U}_i\,,\C^N)$ for $l\leq j-\frac{k+1}{2}$, for any $i$. Since $\rho_i$ are smooth, it follows that $\psi\in C^l(\mathcal{U}_i\,,\C^N)$ and in particular we can conclude our proof.
\end{proof}

\begin{Prp}[Uniqueness and Finite Speed of Propagation]\label{Prop:UniquenessRetarded} 
	Assume~Set-up~\ref{Setup} and suppose that the nonlocal potential $\B$ satisfies the assumptions (i) and (ii) in Theorem~\ref{Thm:Ret}. Then, if there exists a (classical) $C^{1}$-solution $\psi$ of the Cauchy problem~\eqref{eq:SymNonLoc} on the time strip $\overline{\scrM}_{T}$, it is unique and and propagates at most with the speed of light, i.e.
	\begin{align*}
		\mathrm{supp}(\psi)\cap J^{+}(\scrN_{0})\subset J^{+}(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))\, .
	\end{align*}
\end{Prp}

\begin{proof}
	We first prove uniqueness. Suppose that $\psi\in C^{1}(\overline{\scrM}_{T},\scrE)$ is a solution of the homogeneous nonlocal equation $(\scrS-\B)\psi=0$ of with initial condition $\psi\vert_{\scrN_{0}}=0$. Then, following exactly the same steps as in the proof of Proposition~\ref{Prp:Ret}, cf.~\eqref{eq:Estimate} with replacing $\psi^{(n+1)}$ and $\psi^{(n)}$ by $\psi$, we obtain the estimate 
	\begin{align*}
		\Vert\psi_{t}\Vert_{t} \leq K_{T}\int_{0}^{t}(t-\tau)\Vert \psi_{\tau}\Vert_{\tau}\,d\tau \leq K_{T}T\int_{0}^{t}\Vert \psi_{\tau}\Vert_{\tau}\,d\tau=:K_{T}TF(t)
	\end{align*}
	for all $t\in [0,T]$, where $K_{T}>0$ is some constant only depending on $T$. Now, observe that $\dot{F}(t)=\Vert\psi\Vert_{t}$, where the dot denotes the time-derivative, which allows us to rewrite the above inequality as $\dot{F}(t)\leq K_{T}TF(t)$. In other words, we find that
	\begin{align*}
		\frac{d}{dt}(e^{-K_{T}Tt}F(t))\leq 0
	\end{align*}
	for all $t\in [0,T]$. Setting $G(t):=e^{-K_{T}Tt}F(t)$, we observe that $G(t)\geq 0$ and $\dot{G}(t)\leq 0$ as well as $G(0)=0$. The only such $C^{1}$-function is given by $G(t)=0$. We conclude that $\Vert\psi\Vert_{t}=0$ for all $t\in [0,T]$ and hence $\psi=0$ on $\scrM_{T}$.

	Now, if $\psi\in\H_{\overline{\scrM}_{T}}\cap C^{1}(\scrM_{T},\scrE)$ is a $C^{1}$-solution to the Cauchy problem $(\scrS-\B)\psi=\phi$ with $\psi\vert_{\scrN_{0}}=\mathfrak{f}$, uniqueness implies that $\psi$ is constructed via the perturbative series
	\begin{align*}
		\psi=\sum_{n=0}^{\infty}\psi^{(n)}\, ,
\end{align*}	
which is absolutely convergent in $\H_{\overline{\scrM}_{T}}$, where $\psi^{(n)}$ are the solutions to the local problems $\scrS\psi^{(0)}=\phi$ and $\scrS\psi^{(n+1)}=\B\psi^{(n)}$ with $\psi^{(n)}\vert_{\scrN_{0}}=0$, as explained in Proposition~\ref{Prp:Ret}. As explained in the proof of Proposition~\ref{Prop:DysonRet}, by the assumptions on $\B$, we know that 
\begin{align*}
	\mathrm{supp}(\psi^{(n)})\cap J^{+}(\scrN_{0})\subset J^{+}(\mathrm{supp}(\phi)\cap\mathrm{supp}(\mathfrak{f}))
\end{align*}
for all $n\in\N$. Hence, also the limit $\psi$, which is assumed to be $C^{1}$, is supported within the same set $J^{+}(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))$. 
\end{proof}

Collecting all the results obtained, we have all the ingredients to proof the main theorem of this section.

\begin{proof}[Proof of Theorem~\ref{Thm:Ret}]
	By Proposition~\ref{Prp:Ret}, we know that the nonlocal Cauchy problem~\eqref{eq:SymNonLoc} has a strong solution provided its nonlocal potentials satisfies assumptions (i) and (ii). Then, in Proposition~\ref{Prp:RetReg}, we discussed the claimed regularity of solutions provided assumption (iii) holds true. Uniqueness and finite speed of propagation was then shown in Proposition~\ref{Prop:UniquenessRetarded}.
\end{proof}


\subsection{Nonlocal Potential with Short Time Range}
As a second case, we turn our attention to the Cauchy problem~\eqref{eq:SymNonLoc} in the presence of a nonlocal potential with short time range, as specified in Definition~\ref{Def:Potentials}(ii). This class of potentials, being non-retarded, introduces additional analytical challenges due to the lack of a purely causal structure. 

To start with, consider Set-up~\ref{Setup} and let $\overline{\scrM}_{T}:=[0,T]\times\scrN$ be the closed time strip of size $T>0$. If $\B$ is a nonlocal potential with short time range $\delta>0$, our aim is to study the Cauchy problem
\begin{align}\label{eq:CauchySmall}
	\begin{cases}
		(\scrS-\B)\psi &=\phi\\
		\psi\vert_{\scrN_{0}}&=\mathfrak{f}
	\end{cases}
\end{align}	
for a given source $\phi\in C_{\mathrm{c}}^{\infty}(\scrM,\scrE)$ with $\mathrm{supp}(\phi)\subset \overline{\scrM}_{T}$ and initial datum $\mathfrak{f}\in C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$. 

Our aim in this section is to proof the following theorem.

\begin{Thm}\label{Thm:Small}
	Assume~Set-up~\ref{Setup} and suppose that the nonlocal potential $\B$ satisfies the following assumptions:
	\begin{itemize}
		\item[(i)]$\B$ has short time range $\delta>0$, i.e.~$\V_{t,t^{\prime}}=0$ if $\vert t-t^{\prime}\vert>\delta$.
		\item[(ii)]$\B$ is uniformly bounded in time with a constant that is small compared to $\delta$ and $D$ in the following sense: There exists a constant $C<(8e\delta^{2})^{-1}$ such that 
		\begin{align*}
			\Vert\V_{t,\tau}\varphi_{\tau}\Vert_{t}\leq Ce^{-\frac{1}{2}D\vert\tau\vert}\Vert\varphi_{\tau}\Vert_{\tau}\end{align*} 
		for all $\varphi\in C^{\infty}_{\mathrm{c}}(\scrN_{\tau},\scrE\vert_{\scrN_{\tau}})$ and $t,\tau\in\R$.
		\item[(iii)]The zero-order operator $\mathcal{Z}_{\scrS}:=\beta\sigma_{\scrS}(\eta)^{-1}(\scrS+\scrS^{\dagger})$ is uniformly bounded in time, i.e.~there exists a $D>0$ such that \begin{align*}
			\Vert(\mathcal{Z}_{\scrS}\psi)_{t}\Vert_{t}\leq D\Vert\psi_{t}\Vert_{t}
		\end{align*}
		for all $\varphi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)$ and $t\in\R$. Furthermore, also $\sigma_{\scrS}(dt)\in C^{\infty}(\scrM,\mathrm{End}(\scrE))$ is uniformly bounded in time.
	\end{itemize}
	Then, there exists a strong solution of the Cauchy problem~\eqref{eq:SymNonLoc}. \end{Thm}

\begin{Remark}
Let us highlight the key differences in the assumptions compared to the retarded case discussed in Theorem~\ref{Thm:Ret}:
\begin{itemize}
	\item[$\bullet$]Recall that strong solutions are constructed perturbatively by generating a sequence of solutions $\psi^{(n)}$ to \emph{local} equations, see~Proposition~\ref{Prop:DysonSmall} below. In this case, due to the non-retarded nature of the potential, the domain of integration in the energy estimates of Corollary~\eqref{Cor:EnEst} expands by $\pm\delta$ at each step. As a consequence, we must impose an exponential decay factor on the bounds for the time kernel. This decay compensates for the exponential growth induced by the zero-order terms associated with the operator $\scrS + \scrS^{\dagger}$.
	\item[$\bullet$] Finally, note that in this case, we do not have any uniqueness or finite speed of propagation results. The standard energy estimates used in the retarded case are not applicable here. However, in Section~\ref{secdirunique}, we will show that in the special case of a symmetric kernel, a uniqueness statement can still be established by considering a nonlocal modification of the inner product $(\cdot|\cdot)_{t}$.
\end{itemize}
\end{Remark}


As in the retarded case, we start first by constructing a sequence of solutions to local problems converging at any fixed time in the corresponding Hilbert space of the Cauchy slice.

\begin{Prp}\label{Prop:DysonSmall}
	Assume Set-up.~\ref{Setup} together with assumptions (i)-(iii) in Theorem~\ref{Thm:Small} and let $\psi^{(n)}\in C^{\infty}(\scrM,\scrE)$ be the sections inductively defined as the (unique) solutions to the local Cauchy problems
	\begin{align*}
		\begin{cases}
			\scrS\psi^{(0)} &=\phi\\
			\psi^{(0)}\vert_{\scrN_{0}}&=\mathfrak{f}
		\end{cases}\qquad\text{and}\qquad 
		\begin{cases}
			\scrS\psi^{(n+1)} &=\B\psi^{(n)}\\
			\psi^{(n+1)}\vert_{\scrN_{0}}&=0
		\end{cases},\quad n\geq 0\, .
	\end{align*}
	Then, $\psi_{t}:=\sum_{n=0}^{\infty}\psi^{(n)}_{t}$ is absolutely convergent in the Hilbert space $\H_{t}$ for every $t\in\R$. Furthermore, the map $\psi:t\mapsto\psi_{t}$ is a well-defined element in the space $L^{2}_{\mathrm{loc}}(\R,\H_{\bullet})$. 
\end{Prp}

\begin{proof}[Proof of Proposition~\ref{Prop:DysonSmall}.]
Let $\psi^{(n)}$ be the solutions to the local Cauchy problems as defined in the statement of the proposition. By finite speed of propagation, see~Theorem~\ref{Thm:WellPosedCauchy}, it holds that 
	\begin{align*}
		\mathrm{supp}(\psi^{(0)}) \subset J(\mathrm{supp}(\phi)\cup\mathrm{supp}(\mathfrak{f}))\quad\text{and}\quad \mathrm{supp}(\psi^{(n+1)}) \subset J(\mathrm{supp}(\B\psi^{(n)}))
	\end{align*}
	 for all $n\in\N$. Note that $\B\psi^{(n)}$ is well-defined, since $\B$ extends to an operator acting on smooth sections, which are in $\H_{t}$ at any fixed $t\in\R$, as a consequence of assumption (iii) and the standard energy estimates. Moreover, unlike in the retarded case, observe that $\psi^{(n)}$ will in general also include a component propagating into the past, both due to the non-zero initial datum $\mathfrak{f}$ for $\psi^{(0)}$ and the nonlocality, which increases the support of the source at each step $n$ by $\pm\delta$ in time, and hence, at some order, the source will thus intersect the initial Cauchy slice $\scrN_{0}$.

	Now, the goal of the following discussion is to show that the perturbative ansatz
\begin{align}\label{ansatzpertur2}
		\psi=\sum_{n=0}^{\infty}\psi^{(n)}
	\end{align}	
	is absolutely convergent in $\mathcal{H}_{t}$ for all $t\in\R$. Using the energy estimates from Corollary~\ref{Cor:EnEst}, we have
\begin{align}\label{eq:EnergyEstSmall}
		\bigg\vert\frac{d}{dt}\Vert\psi^{(n+1)}_{t}\Vert_{t}\bigg\vert\leq C\int_{t-\delta}^{t+\delta}e^{-\frac{1}{2}D\vert\tau\vert}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau+\frac{1}{2}D\Vert\psi^{(n+1)}_{t}\Vert_{t}
	\end{align}
	for all $n\in\N$ and $t\in\R$, where we used assumptions (i)-(iii). As a first step, we absorb the last term in~\eqref{eq:EnergyEstSmall} using an appropriate exponential factor, by noting that the energy estimate~\eqref{eq:EnergyEstSmall} imply
	\begin{subequations}
	\begin{align}
		\frac{d}{dt}\bigg(e^{-\frac{1}{2}D t}\Vert\psi^{(n+1)}_{t}\Vert_{t}\bigg)\leq Ce^{-\frac{1}{2}D t}\int_{t-\delta}^{t+\delta}e^{-\frac{1}{2}D\vert\tau\vert}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau\,,\quad &\text{for }t\geq 0\label{eq:geqt}\\
		-\frac{d}{dt}\bigg(e^{\frac{1}{2}D t}\Vert\psi^{(n+1)}_{t}\Vert_{t}\bigg)\leq Ce^{\frac{1}{2}D t}\int_{t-\delta}^{t+\delta}e^{-\frac{1}{2}D\vert\tau\vert}\Vert \psi^{(n)}_{\tau}\Vert_{\tau}\, d\tau\,,\quad &\text{for }t\leq 0\label{eq:leqt}
	\end{align}
	\end{subequations}
	for all $n\in\N$. Now, we distinguish between to cases. If $t\geq 0$, we integrate~\eqref{eq:geqt} from $0$ to $t$ and, using the fact that $\psi^{(n+1)}_{t=0}=0$, we obtain the estimate\footnote{In the first estimate, we changed the order of integration by using that for every choice of $\delta>0$ and $t\geq 0$ it holds that \begin{align*}\begin{cases}0 \leq \tau \leq t\\ \tau-\delta \leq s\leq\tau+\delta\end{cases}\qquad\Leftrightarrow\qquad\begin{cases}-\delta\leq s \leq t+\delta\\ \mathrm{max}\{s-\delta,0\} \leq \tau\leq\mathrm{min}\{s+\delta,t\}\end{cases}\, .\end{align*}
	Note also that $\mathrm{max}\{s-\delta,0\}\leq \mathrm{min}\{s+\delta,t\}$ on the range $s\in [-\delta,t+\delta]$ for all $\delta>0$, $t\geq 0$.}
		\begin{align}
		\Vert\psi_{t}^{(n+1)}\Vert_{t}&=Ce^{\frac{1}{2}Dt}\int_{0}^{t}\underbrace{e^{-\frac{1}{2}D\tau}}_{\leq 1}\int_{\tau-\delta}^{\tau+\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi_{s}\Vert_{s}\,ds\,d\tau\nonumber\\&\leq Ce^{\frac{1}{2}Dt}\int_{-\delta}^{t+\delta}\bigg(\underbrace{\mathrm{min}\{s+\delta,t\}-\mathrm{max}\{s-\delta,0\}}_{\leq 2\delta}\bigg)e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{s}\Vert_{s}\,ds\nonumber\\&\leq (2\delta C)e^{\frac{1}{2}Dt}\int_{-\delta}^{t+\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{s}\Vert_{s}\,ds\label{eq:EstPost}
	\end{align}
	for all $t\geq 0$ and $n\in\mathbb{N}$. 

	Similarly, in the case $t\leq 0$, we integrate over the estimate~\eqref{eq:leqt} from $t$ to $0$. Using again that $\psi^{(n+1)}_{t=0}=0$, we obtain the similar estimate
	\begin{align}
		\Vert\psi_{t}^{(n+1)}\Vert_{t}&=Ce^{-\frac{1}{2}Dt}\int_{t}^{0}\underbrace{e^{\frac{1}{2}D\tau}}_{\leq 1}\int_{\tau-\delta}^{\tau+\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi_{s}\Vert_{s}\,ds\,d\tau\nonumber\\&\leq Ce^{-\frac{1}{2}Dt}\int_{t-\delta}^{\delta}\bigg(\underbrace{\mathrm{min}\{s+\delta,0\}-\mathrm{max}\{s-\delta,t\}}_{\leq 2\delta}\bigg)e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{s}\Vert_{s}\,ds\nonumber\\&\leq (2\delta C)e^{-\frac{1}{2}Dt}\int_{t-\delta}^{\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{s}\Vert_{s}\,ds\label{eq:EstNegt}
	\end{align}
	for all $t\leq 0$ and $n\in\mathbb{N}$. Now, note that the previous two estimates~\eqref{eq:EstPost} and~\eqref{eq:EstNegt} for $t\geq 0$ and $t\leq 0$ can be combined and written in the compact form
	\begin{align}
		\forall t\in\R,\,n\in\N:\quad\Vert\psi^{(n+1)}_{t}\Vert_{t}\leq (2\delta C)e^{\frac{1}{2}D\vert t\vert}\int_{-\delta}^{\vert t\vert+\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{\mathrm{sgn}(t)s}\Vert_{\mathrm{sgn}(t)s}\, ds \label{ites}
	\end{align}

	After deriving the relevant estimates for the $\H_{t}$-norm of $\psi^{(n+1)}$ in terms of the $\H_{t}$-norm of $\psi^{(n)}$, we derive suitable estimates for $\Vert\psi^{(n)}_{t}\Vert_{t}$. As a first step, by Corollary~\ref{Cor:EnEstLoc}, we can find a constant $M>0$ such that 
	\begin{align*}
		\Vert\psi^{(0)}_{t}\Vert_{t}\leq e^{\frac{1}{2}D\vert t\vert}M
	\end{align*}
	for all $t\in\R$. Now, for given $n\in\N$, we consider the induction hypothesis 
	\begin{align*}
		\Vert\psi^{(n)}_{t}\Vert_{t}\leq M\kappa(n)e^{\frac{1}{2}D\vert t\vert}(\vert t\vert+2n\delta)^{n},\qquad\forall t\in\R\, .
	\end{align*}	
	 Clearly, this inequality holds true for $n=0$ with $\kappa(0)=1$. By induction, we assume that it is true for $n$. Using the estimate~\eqref{ites} and the induction hypothesis, we obtain
	\begin{align*}
		\Vert\psi^{(n+1)}_{t}\Vert_{t}&\leq (2\delta C)e^{\frac{1}{2}D\vert t\vert}\int_{-\delta}^{\vert t\vert+\delta}e^{-\frac{1}{2}D\vert s\vert}\Vert\psi^{(n)}_{\mathrm{sgn}(t)s}\Vert_{\mathrm{sgn}(t)s}\, ds\\&\leq (2\delta C)M\kappa(n)e^{\frac{1}{2}D\vert t\vert}\int_{-\delta}^{\vert t\vert+\delta}(\vert s\vert+2n\delta)^{n}\, ds\\&= (2\delta C)M\kappa(n)e^{\frac{1}{2}D\vert t\vert}\frac{1}{n+1}\bigg\{(\vert t\vert+2\delta n+\delta)^{n+1}-2(2n\delta)^{n+1}+(2\delta n+\delta)^{n+1}\bigg\}\\&\leq (4\delta C)M\kappa(n)e^{\frac{1}{2}D\vert t\vert}\frac{(\vert t\vert+2(n+1)\delta)^{n+1}}{n+1}\, .
	\end{align*}
	This allows us to determine the coefficients $\kappa(n)$ in $\Vert\psi^{(n)}_{t}\Vert_{t}\leq\kappa(n)e^{\frac{1}{2}D\vert t\vert}(\vert t\vert+n\delta)^{n}M$ and we obtain $\kappa(n)=\frac{1}{n!}(4C\delta)^{n}$. To sum up, we have shown that
	\begin{align}\label{eq:EstimatesSmallTR}
		\forall t\in\R\,,n\in\N:\quad \Vert\psi^{(n)}_{t}\Vert_{t} \leq \frac{M}{n!}(4C\delta)^{n}e^{\frac{1}{2}D\vert t\vert}(\vert t\vert+2n\delta)^{n}\, .
	\end{align}

	To show that the perturbative ansatz~\eqref{ansatzpertur2} is absolutely convergent in the $\H_{t}$-topology, we have to study the bounds on the $\H_{t}$-norms of $\psi^{(n)}$ for for large $n$. In this case, using Stirling's formula for the factorial, one obtains
	\begin{align*}
		\Vert\psi^{(n)}_{t}\Vert_{t} &\leq \frac{M}{n!}(4C\delta)^{n}e^{\frac{1}{2}D\vert t\vert}(\vert t\vert +2n\delta)^{n}= \frac{M}{n!}(8C\delta^2)^{n}n^{n}e^{\frac{1}{2}D\vert t\vert}\left(1+\frac{\vert t\vert}{2n\delta}\right)^n \\&\sim\frac{Me^{\frac{1}{2\delta}\vert t\vert(D\delta+1)}}{\sqrt{2\pi n}}(8e\delta^{2}C)^{n}\left(1 + \mathcal{O}\left(\frac{1}{n}\right)\right) \quad \text{as} \quad n \to \infty.
	\end{align*}
	In particular, using this inequality and the asymptotic expansion as written in the last line, it follows that 
	\begin{align*}
		\lim_{n\to\infty}\frac{\Vert\psi^{(n+1)}_{t}\Vert_{t}}{\Vert\psi^{(n)}_{t}\Vert_{t}}=8e\delta^{2}C
	\end{align*}
	for all $t\in\R$, which shows that the series $\sum_{n=0}^{\infty}\Vert\psi^{(n)}_{t}\Vert_{t}$ is convergent whenever $8e\delta^{2}C<0$, by the ratio test of convergence of series. 

	Now, we have constructed a map $\psi:t\mapsto\psi_{t}$, where $\psi_{t}$ is the limit of the series~\ref{ansatzpertur2} in the $\H_{t}$-topology. Now, it is clear that $t\mapsto \psi_{t}$ is measurable, since it is the pointwise limit of the smooth (and in particular strongly measurable) functions $t\mapsto \sum_{k=0}^{n}\psi^{(k)}_{t}$ for $n\to\infty$, see e.g.~\cite[Thm.~1.14]{AmannEscherIII}. The fact that $\psi$ is $L^{2}_{\mathrm{loc}}$ in time can be seen as follows: Consider the compact time interval $[0,T]$ for $T>0$. Using~\eqref{eq:EstimatesSmallTR}, we obtain
	\begin{align*}
		\Vert\psi_{t}^{(n)}\Vert_{\scrM_{T}}^2&=\int_{0}^{T}\Vert\psi^{(n)}_{t}\Vert^2_{t}\,dt \leq \frac{M^2}{(n!)^2}(4C\delta)^{2n}\int_{0}^{T}e^{D\vert t\vert}(\vert t\vert+2n\delta)^{2n}\,dt\\&\leq \frac{TM^2e^{DT}}{(n!)^2}(4C\delta)^{2n}(T+2n\delta)^{2n}\, .
	\end{align*}
	Using similar arguments as before, we conclude that the series of $\Vert\psi_{t}^{(n)}\Vert_{\scrM_{T}}^2$ is convergent. Hence, by the dominant convergence theorem applied to series (see e.g.~\cite[Thm.~3.16]{AmannEscherIII}), we conclude that the series~\eqref{ansatzpertur2} is also absolutely convergent in the $\H_{\overline{\scrM}_{T}}$-topology and 
	\begin{align*}
		\Vert\psi\Vert_{\scrM_{T}}^2=\int_{0}^{T}\Vert\psi_{t}\Vert_{t}^2\,dt=\int_{0}^{T}\sum_{n=0}^{\infty}\Vert\psi_{t}^{(n)}\Vert_{t}^2\,dt=\sum_{n=0}^{\infty}\int_{0}^{T}\Vert\psi_{t}^{(n)}\Vert_{t}^2\,dt=\sum_{n=0}^{\infty}\Vert\psi^{(n)}\Vert_{\scrM_{T}}^2<\infty\, .
	\end{align*}
	This holds true for any compact time strip, which concludes the proof.
\end{proof}



With the previous proposition, we are able to prove the main theorem of this section.

\begin{proof}[Proof of Theorem~\ref{Thm:Small}]
Consider the sequence $(\psi^{(n)})_{n\in\N}$ as constructed in Proposition~\ref{Prop:DysonSmall}. As shown in this proposition, the corresponding series converges absolutely in the $\H_{[-\delta,T+\delta]\times\scrN}$-topology to some element $\psi\in\H_{[-\delta,T+\delta]\times\scrN}$. To show that $\psi$ is a strong solution to the Cauchy problem~\eqref{eq:CauchySmall} we follows from similar steps as in Proposition~\ref{Prp:RetReg}, with the involved norms and time strips adapted properly.
\end{proof}

The following example demonstrates that Theorem~\ref{Thm:Small} cannot be expected to hold in a significantly broader sense for nonlocal potentials that do not satisfy the condition $C<(8e\delta^{2})^{-1}$ on the time kernel, even in the case $\scrS+\scrS^{\dagger}=0$.

\begin{Example}\label{Counterexample} (A simple Counterexample)\newline
	We consider $(1+1)$-dimensional Minkowski spacetime $\scrM=\R_{t}\times\R_{x}$ and the trivial line bundle over $\C$ equipped with the standard complex inner product. As a symmetric hyperbolic system we consider the operator
	\begin{align*}
		\scrS\colon C^{\infty}(\scrM)\to C^{\infty}(\scrM)\,,\qquad \scrS:=\partial_{t}\, .
	\end{align*}
	In particular, $\H_{t}\cong L^{2}(\R_{x},dx)$ for all $t\in \R_{t}$ and $\H_{\scrM_{T}}\cong L^{2}([0,T]\times\R_{x},dt\,dx)$ for $T>0$. Furthermore, we choose a real-valued function $f\in C^{\infty}_{\mathrm{c}}(\scrM)$ such that $\Vert f\Vert_{L^{2}(\R_{t}\times\R_{x})}=1$. As a nonlocal potential, we choose the integral operator $\B:C^{\infty}_{\mathrm{c}}(\scrM)\to C^{\infty}(\scrM)$ defined by
	\begin{align*}
		(\B\psi)(t,x):=-f(t,x)\int_{\R}\,d\tau\,\int_{\R}\,dy\,\dot{f}(\tau,y)\psi(\tau,y)\,,\qquad\forall \psi\in C^{\infty}_{\mathrm{c}}(\scrM)\, ,
	\end{align*}
	or in bra/ket notation, $\B=|f\ket\bra\scrS^\dagger f|=-|f\ket\bra \dot{f}|$, where $<\cdot|\cdot>$ denotes the inner product induced by the bundle metric, as usual, which in this case coincides with the $L^{2}$-inner product on $\scrM=\R_{t}\times\R_{x}$. The Schwartz kernel $k_{\B}\in C^{\infty}(\scrM\times\scrM)$ of $\B$ is regular and given by $k_{\B}(t,x;\tau,y)=-f(t,x)\dot{f}(\tau,y)\in C^{\infty}(\scrM\times\scrM)$ and the corresponding time kernel $\B_{t,\tau}:C^{\infty}_{\mathrm{c}}(\R_{x})\to C^{\infty}(\R_{x})$ can be written as
	\begin{align*}
		\B_{t,\tau}\psi_{\tau}(x)=-f(t,x)\int_{\R}\,dy\,\dot{f}(\tau,y)\psi(\tau,y)\,,\qquad\forall \psi\in C^{\infty}_{\mathrm{c}}(\scrM)\, .
	\end{align*}
	Now, in order for $\B$ to satisfy the smallness condition, we have to choose $f$ such that $\mathrm{supp}(f)\subset (0,\delta/2)\times K$, where $K\subset\R_{x}$ is some compact subset. In this way, it holds that $\B_{t,\tau}=0$ for $\vert t-\tau\vert >\delta$. Next, let us show that $\B_{t,\tau}$ is uniformly bounded in time, i.e.~that there exists a constant $C>0$ such that $\Vert\B_{t,\tau}\psi_{\tau}\Vert_{t}\leq C\Vert\psi_{\tau}\Vert_{\tau}$ for all $\psi\in C^{\infty}_{\mathrm{c}}(\scrM)$ and all $t,\tau\in\R$. For this, let $\psi\in C^{\infty}_{\mathrm{c}}(\scrM)$ be arbitrary. Then
	\begin{align*}
		\Vert\B_{t,\tau}\psi_{\tau}\Vert_{\tau}^{2}&=\int_{\R}\,dx\,\vert \B_{t,\tau}\psi_{\tau}(x)\vert^{2}=\int_{\R}\,dx\,\bigg\vert f(t,x)\int_{\R}\,dy\,\dot{f}(\tau,y)\psi(\tau,y)\bigg\vert^{2}\stackrel{\text{Hölder ineq.}}{\leq}\\&\leq \bigg(\int_{\R}\,dx\,\vert f(t,x)\vert^{2}\bigg)\bigg(\int_{\R}\,dy\,\vert \dot{f}(\tau,y)\vert^{2}\bigg)\Vert \psi_{\tau}\Vert_{\tau}^{2}\leq\\&\leq \underbrace{\max_{t,t^{\prime}\in (0,\delta/2)}\bigg(\int_{\R}\,dx\,\vert f(t,x)\vert^{2}\bigg)\bigg(\int_{\R}\,dy\,\vert \dot{f}(t^{\prime},y)\vert^{2}\bigg)}_{=:C^{2}}\Vert \psi_{\tau}\Vert_{\tau}^{2}\, .
	\end{align*} 
	Next, we will show that there exists a $\psi\in C^{\infty}_{\mathrm{c}}(\scrM)$ and a choice of $t,\tau\in\R$ such that $\Vert\B_{t,\tau}\psi_{\tau}\Vert_{t}\geq\frac{2}{\delta^{2}}\Vert\psi_{\tau}\Vert_{\tau}$, which shows that the constant $C$ cannot be chosen smaller than $\frac{2}{\delta^{2}}$ and hence that assumption (ii) in Theorem~\ref{Thm:Small} is not fulfilled for the nonlocal potential $\B$. For this, we choose 
$\psi:=\dot{f}$ and compute
	\begin{align*}
		\Vert\B_{t,t}\dot{f}_{t}\Vert_{t}^{2}&=\int_{\R}\,dx\,\bigg\vert f(t,x)\int_{\R}\,dy\,\vert\dot{f}(t,y)\vert^{2}\bigg\vert^{2}=\\&=\bigg(\int_{\R}\,dx\,\vert f(t,x)\vert^{2}\bigg)\bigg(\int_{\R}\,dy\,\vert \dot{f}(t,y)\vert^{2}\bigg)\Vert\dot{f}_{t}\Vert_{t}^{2}\stackrel{\text{Hölder ineq.}}{\geq}\\&\geq \bigg(\int_{\R}\,dx\,\vert f(t,x)\dot{f}(t,x)\vert\bigg)^{2}\Vert\dot{f}_{t}\Vert_{t}^{2}\geq\bigg(\frac{1}{2}\partial_{t}\int_{\R}\,dx\,\vert f(t,x)\vert^{2}\bigg)^{2}\Vert\dot{f}_{t}\Vert_{t}^{2}\, ,
	\end{align*}
	which holds true for any value of $t\in\R$. Now, let us set $g(t):=\int_{\R}dx\,\vert f(t,x)\vert^{2}$. By definition, we note that $g(t)\geq 0$ for all $t$ and $\Vert g\Vert_{L^{1}(0,\delta/2)}=1$. Let $t_{\mathrm{max}}\in (0,\delta/2)$ be such that $g(t)\leq g(t_{\mathrm{max}})$ for all $t\in (0,\delta/2)$. The normalisation $\int_{\R}dt\,g(t)=\int_{0}^{\delta/2}\,dt\,g(t)=1$ implies that $g(t_{\mathrm{max}})\geq \frac{2}{\delta}$. By the mean value theorem we conclude that there exists a $t_{0}\in (0,t_{\mathrm{max}})$ such that
	\begin{align*}
		\partial_{t}g(t_{0})=\frac{g(t_{\mathrm{max}})-g(0)}{t_{\mathrm{max}}-0}\geq \frac{4}{\delta^{2}}\,, 
	\end{align*} 
	since $t_{\mathrm{max}}\leq \frac{\delta}{2}$. Hence, we have shown that there exists a $t_{0}\in (0,\delta/2)$ such that 
	\begin{align*}\Vert\B_{t_{0},t_{0}}\dot{f}_{t_{0}}\Vert_{t_{0}}\geq \frac{2}{\delta^{2}}\Vert \dot{f}_{t_{0}}\Vert_{t_{0}}\, .\end{align*}
	In particular, our nonlocal potential violates the condition $C<(8e\delta^{2})^{-1}$ of Theorem~\ref{Thm:Small}. We will now show that the nonlocal equation $(\scrS-\B)\psi=\phi$ does not always admit a solution. Suppose there exists a strong solution $\psi\in L^{2}(\R_{t}\times\R_{x})$ to the nonlocal equation $(\scrS-\B)\psi=f$ with source $f$. Then, for any test function $\varphi\in C^{\infty}_{\mathrm{c}}(\scrM)$ we must have
	\begin{align}\label{eq:Cexample}
		\bra \psi|(\scrS-\B)^{\dagger}\varphi\ket=\bra f|\varphi\ket\, .
	\end{align}
	Now, note that the left-hand side can be written as
	\begin{align*}
		\bra \psi|(\scrS-\B)^{\dagger}\varphi\ket=\bra\psi|\scrS^{\dagger}f\ket-\bra\psi|\scrS^{\dagger}f\ket\bra f|\varphi\ket=\bra\psi|\scrS^{\dagger}f\ket(1-\bra f|\varphi\ket)\, .
	\end{align*}
	But now if we choose $\varphi=f$ as a test function, the left-hand side of~\eqref{eq:Cexample} gives $0$ while the right-hand side 1, which shows that such a solution $\psi$ cannot exist.
\end{Example}
