\section{Application II: Dirac Equation and Potentials with Short Time Range}\label{sec:Dirac}
In the final section, we focus on an important special case of symmetric hyperbolic systems, namely the classical \textit{Dirac operator} on globally hyperbolic manifolds. After introducing the necessary spin geometric background, we illustrate the main results of Section~\ref{Sec:SHSNonLoc} in this example. In addition, we establish a uniqueness result for nonlocal potentials with short time range by endowing the space of solutions with a modified (nonlocal) inner product. We conclude by reviewing recent applications of the nonlocal Dirac equation to causal fermion systems.

\subsection{Dirac Equations and Nonlocal Potentials with Short Time Range}
Let $(\scrM,g)$ be a globally hyperbolic manifold of dimension $k+1$ (with $k\geq 1$) equipped with a \textit{spin structure}, i.e.~a pair consisting of a ${\rm Spin}_0(1,k)$-principal bundle $P_{\rm Spin_0}$ over $\scrM$ together with a twofold covering map $\Lambda$ from $P_{\rm Spin_0}$ to the bundle of positively-oriented tangent frames $P_{\rm SO^+}$ of $\scrM$ such that the following diagram commutes:

\begin{equation*}
	\begin{tikzcd}
		P_{{\rm Spin}_0} \times {\rm Spin}_0(1,k) \arrow[r,"\cdot"]\arrow[d,swap,"\Lambda\times\lambda"] & P_{\rm Spin} \arrow[rd,"\pi"]\arrow[d,"\Lambda"] & \\
		P_{\rm SO^+} \times \textnormal{SO}(1,k)\arrow[r,"\cdot"]  & P_{\rm SO^+} \arrow[r,swap,"\pi"] & \scrM
	\end{tikzcd}
\end{equation*}
where $\lambda$ denotes the double covering at the group level, $\pi$ refers to the respective bundle projections, and the horizontal arrows represent the right group actions on the corresponding principal bundles.

The existence of spin structures is related to the topology of $\scrM$ and there are well-known topological obstructions. A sufficient -- but not necessary -- condition for the existence of a spin structure is parallelizability of $\scrM$. In particular, since any $3$-dimensional  orientable manifold is parallelizable, it follows by Theorem~\ref{thm:Sanchez} that any $(1+3)$-dimensional globally hyperbolic manifold admits a spin structure.

Now, given a fixed spin structure on $(\scrM,g)$, one can use the spin representation $\rho\colon {\rm Spin}_0(1,k) \to \textnormal{Aut}(\mathbb{C}^N)$ to construct the \textit{spinor bundle}, that is, the associated $\C$-vector bundle
$$S\scrM:={\rm Spin}_0(1,k)\times_\rho \mathbb{C}^N\, ,$$
of rank $N:= 2^{\lfloor \frac{k+1}{2}\rfloor}$ (where~$\lfloor\cdot\rfloor$ is the Gau{\ss} bracket; for details see~\cite{baum,lawson+michelsohn}). 
The spinor bundle comes together with the following additional structures:
\begin{itemize}
\item[$\bullet$] a natural ${\rm Spin}_0(1, k)$-invariant indefinite fibre metric
\begin{equation}\label{eq: spin prod}
\Sl\cdot\vert \cdot	\Sr_{{S_p}\scrM} : {S_p}\scrM \times S_p\scrM \to \mathbb{C}\,;
\end{equation}
\item[$\bullet$] a \textit{Clifford multiplication}, i.e.~a vector bundle homomorphism
$$\gamma\colon T\scrM\to \text{End}(S\scrM)\, ,$$ 
which satisfies $\Sl{\gamma(u)\psi}\vert{\phi}\Sr_{{S_p}\scrM}=\Sl{\psi}\vert{\gamma(u)\phi}\Sr_{{S_p}\scrM}$ and the Clifford relations
\begin{equation*}\label{eq:gamma symm}
 \gamma(u)\gamma(v) + \gamma(v)\gamma(u) = -2g(u, v)\1_{S_p\scrM}
\end{equation*}
for all $p \in \scrM$, $u, v \in T_p\scrM$ and $\psi,\phi\in S_p\scrM$.
\end{itemize}

After this preliminary discussion of the relevant geometric structures, we now turn to the (classical) Dirac operator. 

\begin{Def} \label{Def:Dirac}
The \textit{(classical) Dirac operator} $\Dir$ is the operator defined as the 
composition of the metric connection $\nabla^{S\scrM}$ on $S\scrM$, obtained as a lift 
of the Levi-Civita connection on $T\scrM$, and the Clifford multiplication, i.e.
$$\Dir=\imath \gamma\circ\nabla^{S\scrM} \colon C^\infty(\scrM,S\scrM) \to C^\infty(\scrM,S\scrM)\,.$$
\end{Def}

\begin{Remark}
	The classical Dirac operator can also more generally be defined on \emph{Dirac bundles}, in which the spinor bundle is replaced by a more general Clifford module bundle equipped with a Hermitian metric and compatible connection that is also compatible with the Clifford multiplication, see e.g.~\cite[Sec.~5.5]{RudolphSchmidt2}.
\end{Remark}

In local coordinates and with a local trivialisation of the spinor bundle $S\scrM$, the 
Dirac operator $\Dir$ as defined in~\eqref{Def:Dirac} can be written as
\begin{align*}
\Dir \psi = \imath \sum_{\mu=0}^{k}  \epsilon_\mu \gamma(e_\mu) \nabla^{S\scrM}_{e_\mu} 
\psi\, 
\end{align*}
where  $\{e_\mu\}$ is a local Lorentzian orthonormal frame of the tangent bundle $T\scrM$ with $\epsilon_\mu:=g(e_\mu,e_\mu)$, i.e.~$\epsilon_{0}=-1$ and $\epsilon_{i}=1$ for $i=1,\dots,k$. For a given real parameter~$m \in \R$ (the ``mass''), the \textit{Dirac equation} is the linear first-order equation 
\begin{align*}
	(\Dir - m)\psi=0
\end{align*}
for $\psi\in C^{\infty}(\scrM,S\scrM)$. Multiplying the Dirac operator $\Dir$ by a suitable factor of the imaginary unit, it can be realized as a symmetric hyperbolic system on the Hermitian bundle $(S\scrM,\Sl\cdot|\cdot\Sr_{S\scrM})$.

\begin{Prp}\label{Prop:Dirac} For any globally hyperbolic spin manifold $(\scrM,g)$, the operator  $\scrS_{m}:=-\imath (\Dir -m)$ is a symmetric hyperbolic system on $(S\scrM,\Sl\cdot\vert\cdot\Sr_{S\scrM})$ in the sense of Definition~\ref{Def:SHS}. Furthermore, $\scrS_{m}=-\scrS_{m}^{\dagger}$, where $\scrS_{m}^{\dagger}$ denotes the formal adjoint of $\scrS_{m}$ with respect to integrated bundle metric (see~\eqref{eq:SesqDirac} below), as usual.
\end{Prp}

\begin{proof}
	The principal symbol $\sigma_{\scrS_{m}}$ of the operator $\scrS_{m}:=-\imath (\Dir -m)$ is given by 
	\begin{equation*}
		\sigma_{\scrS_{m}}(\xi)=\gamma(\xi^\sharp)\, ,
	\end{equation*}
	for all covectors $\xi\in T^{\ast}\scrM$. Therefore, Property (S) of Definition~\ref{Def:SHS} is verified on account of
$$  \Sl{\gamma(\xi^{\sharp})\psi}\vert{\phi}\Sr_{{S}\scrM}=\Sl{\psi}\vert{\gamma(\xi^{\sharp})\phi}\Sr_{{S}\scrM}\, ,$$
 while Property (H) follows from~\cite[Proposition 1.1]{dimock3}, provided that the spin product was chosen with the appropriate sign.

To show that $\scrS_{m}$ is formally skew-adjoint with respect to the sesquilinear form
	\begin{align}\label{eq:SesqDirac}
		\bra\cdot\vert\cdot\ket_{S\scrM}:=\int_{\scrM}\Sl\cdot\vert\cdot\Sr_{S\scrM}\,d\mu_{\scrM}
	\end{align}
	defined on $C^{\infty}_{\mathrm{c}}(\scrM, S\scrM)$, we begin by noting that the zero-order term $\scrS_{m,0}:=-\imath m$ is trivially skew-adjoint. According to Proposition~\ref{Prop:AdjointSHS}, the only remaining contribution to $\scrS_{m} + \scrS_{m}^{\dagger}$ hence arises from the covariant derivatives of the principal symbol. Now, recall that the spin connection $\nabla^{S\scrM}$ is by definition a \emph{Clifford connection} (see~e.g.~\cite[Def.~5.5.10]{RudolphSchmidt2}), which means that it is a Clifford mudole derivation, i.e.
\begin{align*}
	\nabla_{X}^{S\scrM}(\gamma(Y)\psi)=\gamma(\nabla_{X}Y)\psi+\gamma(Y)\nabla_{X}^{S\scrM}\psi
\end{align*}	
for all $\psi\in C^{\infty}(\scrM,S\scrM)$ and vector fields $X,Y\in C^{\infty}(\scrM, T\scrM)$, where $\nabla$ denotes the Levi-Civita connection of $(\scrM,g)$. Denoting by $\nabla^{\mathrm{End}(S\scrM)}$ the induced connection on $\mathrm{End}(S\scrM)$, this is equivalent to say that
\begin{align*}
	\nabla^{\mathrm{End}(S\scrM)}_{X}(\gamma(Y))=\gamma(\nabla_{X}Y)\, .
\end{align*}
In particular, viewing the Clifford  multiplication $\gamma\colon T\scrM\to\mathrm{End}(S\scrM)$ equivalently as a smooth section of the bundle $\mathrm{End}(S\scrM)\otimes T^{\ast}\scrM$ this is equivalent to say that 
	\begin{align*}
		\nabla^{\mathrm{End}(S\scrM) \otimes T^{\ast}\scrM} \gamma = 0\, ,
	\end{align*}
	where $\nabla^{\mathrm{End}(S\scrM) \otimes T^{\ast}\scrM}$ is the tensor product connection constructed out of $\nabla^{\mathrm{End}(S\scrM)}$ and the Levi-Civita connection. Consequently, $\mathscr{D}\sigma_{\scrS_{m}}=0$, where $\mathscr{D}$ is the divergence-like operator as introduced in Proposition~\ref{Prop:AdjointSHS}. This completes the proof.
\end{proof}

Following Proposition~\ref{Prop:Dirac}, the operator $\scrS_{m}:=-\imath (\Dir-m)$ is a symmetric hyperbolic system and hence, following Section~\ref{subsec:SHS}, we can define the Hilbert space 
\begin{align}
\label{L2sprod}
	\H_t:=\overline{C^{\infty}_{\mathrm{c}}(\scrN_{t},S\scrM\vert_{\scrN_{t}})}^{\Vert\cdot\Vert_{t}},\qquad (\psi | \phi)_t := \int_{\scrN_{t}} \Sl \psi | \gamma(\nu)\phi \Sr_{S\scrM}\: d\mu_{\scrN_{t}} \: ,
\end{align}
where $\nu$ denotes the future-directed timelike normal to $\scrN_{t}$, as usual. Due to current conservation, the inner product $(\cdot|\cdot)_{t}$ is in fact independent of the choice of Cauchy hypersurface\footnote{This can also be seen from the fact that $\scrS_{m}+\scrS_{m}^{\dagger}=0$, as proven in Proposition~\ref{Prop:Dirac}, and the energy evolution equation in Proposition~\ref{Prop:energy}.}, for details see~\cite[Section~2]{finite}. 

For a given nonlocal potential $\B\colon C^{\infty}_{\mathrm{c}}(\scrM,S\scrM)\to C^{\infty}(\scrM,S\scrM)$, we shall consider the following the \textit{Dirac equation with nonlocal potential}, i.e.~the Cauchy problem
\begin{align}\label{eq:DiracNonLoc}
	\begin{cases}
		(\Dir + \B -m)\psi &=\phi\\
		\psi\vert_{\scrN_{0}}&=\mathfrak{f}
	\end{cases}
\end{align}
on the time strip $\overline{\scrM}_{T}$ for a given source $\phi\in C^{\infty}_{\mathrm{c}}(\scrM,S\scrM)$ with $\mathrm{supp}(\phi)\subset\overline{\scrM}_{T}$ and initial datum $\mathfrak{f}\in C^{\infty}_{\mathrm{c}}(\scrN_{0},\scrE\vert_{\scrN_{0}})$.

Theorem~\ref{Thm:Small} on the Cauchy problem for symmetric hyperbolic systems with nonlocal potentials with short time range implies the following results:

\begin{Corollary}\label{Cor.Dirac}
	Let $(\scrM,g)$ be a globally hyperbolic manifold such that $\sigma_{\scrS_{m}}(dt)=-\beta^{-2}\gamma(\partial_{t})$ is uniformly bounded in time and let $\B$ be a nonlocal potential with short time range $\delta>0$. If $\B$ is uniformly bounded in time in the sense that
		\begin{align*}
			\exists C\,\,\text{ with }\,\,0<C<(8e\delta^{2})^{-1}:\quad \Vert\V_{t,\tau}\psi_{\tau}\Vert_{t}\leq C\Vert\psi_{\tau}\Vert_{\tau}\,\quad\forall\psi\in C^{\infty}_{\mathrm{sc}}(\scrM,\scrE)\,,\forall t,\tau\in\R\, ,\end{align*} 
			where $\V:=\beta\gamma(\nu)^{-1}\B$ denotes the modified potential, then there exists a strong solution of the Cauchy problem~\eqref{eq:DiracNonLoc} on the time strip $\overline{\scrM}_{T}$.
\end{Corollary}

\begin{proof}
	This is a special case of Theorem~\ref{Thm:Small}, noting that the conditions on the zero-order terms are trivially fulfilled on account of $\scrS_{m}+\scrS_{m}^{\dagger}=0$, as shown in Proposition~\ref{Prop:Dirac}.
\end{proof}

We remark that the uniform boundedness assumption on $\gamma(\partial_{t})$ is essentially a condition on the lapse function $\beta$, since $\gamma(\partial_{t})^{2}=-g(\partial_{t},\partial_{t})\mathrm{id}_{S\scrM}=\beta^{2}\mathrm{id}_{S\scrM}$ by the Clifford relations.

