\section*{Appendix}
Here we present derivations of the mathematical results presented in the main text. Additionally, we describe the numerical simulation procedure used to generate data for the dual-input control systems with feedback. 

\section{Stochastic dynamics of incompletely specified chemical reaction networks}\label{sect: dynamics of incompletely specified systems}
\comm{
Because we consider incompletely specified biochemical reactions networks in which the components of interest $\boldsymbol{x}$ may depend on components $\boldsymbol{u}$ whose dynamics is not specified (see \cref{eq: jump process}) we cannot analyze the system's complete chemical master equation but analyze the following marginalized dynamics for the probability $P(\boldsymbol{x};t)$ distribution of components of interest~\cite{Hilfinger2016a}
\begin{multline}\label{eq: cCME}
    \frac{\mathrm{d}P(\boldsymbol{x};t)}{\mathrm{d}t} \\
    = \sum_{k=1}^m\left[\left\lb\mathcal{R}_k|\boldsymbol{x}-\boldsymbol{d}_k\right\rb P(\boldsymbol{x}-\boldsymbol{d}_k;t) - \left\lb\mathcal{R}_k | \boldsymbol{x}\right\rb P(\boldsymbol{x};t) \right]\ ,
\end{multline}
where for notational simplicity we suppress the functional dependence of the reaction rates $\mathcal{R}_k$ on the specified and unspecified components.}

\comm{The conditional rates are impossible to determine without specifying the dynamics of all unspecified components that directly or indirectly affect the components of interest. 
However, exact statistical moment invariants can be derived from \cref{eq: cCME} for incompletely specified systems at stationarity}. Such invariants are the key ingredient in deriving general bounds for classes of sparsely characterizes systems here and in previous work~\cite{Hilfinger2016a, Hilfinger2016, Euan2021, Euan2024}. For example, the time-evolution of the first-order ensemble moments can be obtained directly from the marginalized CME~\cite{Lestas2008,Hilfinger2016a}:%
\begin{equation}\label{eq: mean evolution}
    \frac{\mathrm{d}\langle x_i \rangle(t)}{\mathrm{d}t} = \left\langle R_i^+\right\rangle(t) - \left\langle R_i^-\right\rangle(t)\ ,
\end{equation}
where $R_i^+, R_i^-$ are the total birth and death fluxes, respectively, of $X_i$ molecules given the current state of the system $\boldsymbol{x}$ and $\langle \cdot \rangle$ denotes an ensemble average, i.e.,
\begin{equation}\label{eq: ensemble average}
    \langle f(\boldsymbol{x}) \rangle(t) \coloneqq \sum_{j=1}^n\sum_{x_j=0}^\infty f(\boldsymbol{x}) P(\boldsymbol{x};t)\ ,
\end{equation}
for any function $f$ of the state-vector $\boldsymbol{x}$. Mathematically, the birth and death fluxes are given as
\begin{equation}
\begin{aligned}
    \comm{R_i^+(\boldsymbol{x})} &\comm{\coloneqq \sum_{k\in\left\{1,2,\ldots,m\right\}:d_{ik}>0}d_{ik}\left \lb \mathcal{R}_k | \boldsymbol{x} \right\rb}\\ 
    \comm{R_i^-(\boldsymbol{x})} &\comm{\coloneqq \sum_{k\in\left\{1,2,\ldots,m\right\}:d_{ik}<0}|d_{ik}|\left \lb\mathcal{R}_k |  \boldsymbol{x} \right\rb} \ .
\end{aligned}
\end{equation}
Similarly, the time evolution the of the ensemble covariance between components $X_i$ and $X_j$ (or variance if $i=j$) can be obtained directly from the CME and must obey
\begin{multline}\label{eq: covariance evolution}
    \frac{\mathrm{d}\Cov(x_i,x_j)(t)}{\mathrm{d}t} = \left\langle\sum_{k=1}^md_{ik}d_{jk} \mathcal{R}_k\right\rangle(t) \\
    + \Cov(R_i^+ - R_i^-, y_j)(t) + \Cov(R_j^+ - R_j^-, y_i)(t)\ .
\end{multline}

In the next section we describe the statistical moment invariants constraining stationary systems by considering these moment evolution equations at stationarity. Note, that we suppress the functional dependence of the birth and death fluxes in the covariance equations for notational simplicity.  

\section{Statistical moment invariants for stationary stochastic processes}\label{sect: general relations}
We consider wide-sense stationary processes such that the time evolution of the first (\cref{eq: mean evolution}) and second-order ensemble moments (\cref{eq: covariance evolution}) are at stationarity. Many relevant processes in biology also possess the property of ergodicity which ensures the temporal statistics for a sample trajectory match the ensemble statistics of the process in the long-time limit -- i.e., for any function $f$ of the state-vector, ergodicity provides the following at stationarity:
\begin{equation}
    \left\langle f(\boldsymbol{x})\right\rangle = \left\langle f(\boldsymbol{x}) \right\rangle^*\ ,
\end{equation}
where $ \left\langle f(\boldsymbol{x})\right\rangle$ is the $t \to \infty$ limit of the ensemble average defined by \cref{eq: ensemble average} and
\begin{equation}\label{eq: long-time averaging}
    \left\langle f(\boldsymbol{x}) \right\rangle^* \coloneq \lim_{t\to \infty}\frac{1}{t} \int_{0}^t f(\boldsymbol{x}(s))ds
\end{equation}
is the $t\to \infty$ limit of the time-average of a sample trajectory. Assuming ergodicity, all of our results can be interpreted either at the level of cell-to-cell variability in a population of genetically-identical cells in a shared environment or at the level of temporal variability in a single-cell. 

\comm{Previous work~\cite{Hilfinger2016a} showed that the assumption of stationarity can be relaxed to extend the following moment invariants to time averages of time-dependent conditional ensemble averages of non-diverging systems whose probability distributions are time-dependent -- e.g., cyclo-stationary processes that exhibit oscillatory behavior due to the cell cycle or circadian clocks. For brevity, we focus on illustrating the technique for ergodic stationary states below. For such systems, \cref{eq: mean evolution} implies}
\begin{equation}\label{eq: flux balance}
    \lb R_i^+\rb = \lb R_i^-\rb \eqqcolon \lb R_i^\pm\rb\ .
\end{equation}
for all components $X_i$. 

Before considering the stationary covariance relation we first define additional quantities to characterize the dynamics. First, we define the average co-step-size $\langle s_{ij} \rangle$ as the average change in $X_j$-abundance as a $X_i$ molecule is made or degraded, where the change is negative if one is made while the other is degraded. Mathematically, this is given by
\begin{equation}\label{eq: co-step sizes}
    \langle s_{ij} \rangle = \sum_{k=1}^m \frac{d_{ik}\langle \mathcal{R}_k(\boldsymbol{x})\rangle}{2\langle R_i^\pm \rangle}d_{jk}
\end{equation}
For $i=j$, this is simply the average jump size in $X_i$-levels across all reactions that change $X_i$ levels. Additionally, we define $\tau_i$ as the average life-time of a $X_i$ molecule which is related to average abundances and fluxes through Little's law from queuing theory~\cite{Little, Little2011} through
\begin{equation}\label{eq: Little's Law}
\begin{aligned}
    \tau_i &=\frac{\langle x_i \rangle^*}{\langle R_i^\pm \rangle^*} \\
    &= \frac{\langle x_i \rangle}{\langle R_i^\pm \rangle}\ , 
\end{aligned}
\end{equation}
where the second equality follows from ergodicity. 

Combining \crefrange{eq: flux balance}{eq: Little's Law} with \cref{eq: covariance evolution} at stationarity gives the previously reported (co)variance balance relation~\cite{Hilfinger2016a}
\begin{equation}\label{eq: covariance balance}
    \boldsymbol{U} + \boldsymbol{U}^T = \boldsymbol{D}
\end{equation}
for the matrices with entries
\begin{equation}
\begin{aligned}
    U_{ij} &= \frac{1}{\tau_j}\frac{\Cov(x_i, R_j^- - R_j^+)}{\left\lb x_i \right\rb \left\lb R_j^\pm \right\rb}\\
    D_{ij} &= \frac{1}{\tau_i}\frac{\left\lb s_{ij} \right\rb}{\left\lb x_j \right\rb} + \frac{1}{\tau_j}\frac{\left\lb s_{ji} \right\rb}{\left\lb x_i \right\rb}\ ,
\end{aligned}
\end{equation}
for all pairs of components $X_i, X_j$ whose state updates with Markovian dynamics, regardless of arbitrary, potentially non-Markovian, variables affecting the transition rates, as specified by \cref{eq: jump process}~\cite{Hilfinger2016a}.

\section{Applying stationary invariants to generalized assembly processes}\label{sect: assembly invariants}
We now apply these relations to the following class of systems, which includes all classes of systems discussed in the main text:
\begin{equation}\label{eq: super class}
    \begin{gathered}
        x_1  \overset{r_1(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x})}{\xrightarrow{\hspace*{1.1cm}}} x_1 + 1 \hspace{0.47cm} x_2  \overset{r_2(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x})}{\xrightarrow{\hspace*{1.1cm}}} x_2 + 1\\
         (x_1,x_2) \overset{r_S(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x})}{\xrightarrow{\hspace*{1.1cm}}} (x_1+1,x_2+1)\\
        x_1 \overset{\beta_1 x_1}{\xrightarrow{\hspace*{1.1cm}}} x_1-1 \hspace{0.47cm} x_2 \overset{\beta_2 x_2}{\xrightarrow{\hspace*{1.1cm}}} x_2-1\\
        (x_1, x_2 ,x_3) \overset{r_A(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x})}{\xrightarrow{\hspace*{1.1cm}}} (x_1 - \delta_1, x_2 - \delta_2, x_3 + 1)\\
        (x_1, x_2 ,x_3)\overset{r_D(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x})}{\xrightarrow{\hspace*{1.1cm}}} (x_1 + \delta_1, x_2 + \delta_2, x_3 - 1) \\
        x_3 \overset{\beta_3 x_3}{\xrightarrow{\hspace*{1.1cm}}} x_3-1\ .
    \end{gathered}
\end{equation}
The flux balance equations (\cref{eq: flux balance}) for each of $i = 1,2$ gives the following for this class of systems:
\begin{equation}\label{eq: R_i}
    \begin{aligned}
        \langle R_i^\pm \rangle &= \langle r_i \rangle + \langle r_S \rangle + \delta_i \langle r_D \rangle \\ 
        &= \beta_i \langle x_i \rangle + \delta_i \langle r_A \rangle \ .
    \end{aligned}
\end{equation}
Using the bilinearity of covariance to expand individual terms, the covariance balance equations (\cref{eq: covariance balance}) for $(i,j) \in \left\{(1,1),(2,2),(1,2)\right\}$ gives the following for this class of systems:
\begin{multline}\label{eq: cb11}
    \frac{\langle s_{11} \rangle}{\langle x_1 \rangle} = (1-E_1)\CV_1^2 + E_1\frac{\Cov(r_A,x_1)}{\langle r_A \rangle \langle x_1 \rangle} \\- (1-F_1)\frac{\Cov(r_1,x_1)}{\langle r_1 \rangle \langle x_1 \rangle} \\ - \psi_1\frac{\Cov(r_D,x_1)}{\langle r_D \rangle \langle x_1 \rangle} - \phi_1\frac{\Cov(r_S,x_1)}{\langle r_S \rangle \langle x_1 \rangle} 
\end{multline}
\begin{multline}\label{eq: cb22}
    \frac{\langle s_{22} \rangle}{\langle x_2 \rangle} = (1-E_2)\CV_2^2 + E_2\frac{\Cov(r_A,x_2)}{\langle r_A \rangle \langle x_2 \rangle} \\- (1-F_2)\frac{\Cov(r_2,x_2)}{\langle r_2 \rangle \langle x_2 \rangle} \\ - \psi_2\frac{\Cov(r_D,x_2)}{\langle r_D \rangle \langle x_2 \rangle} - \phi_1\frac{\Cov(r_S,x_2)}{\langle r_S \rangle \langle x_2 \rangle} 
\end{multline}
\begin{multline}\label{eq: cb12}
    \frac{\langle s_{12} \rangle}{\tau_1\langle x_2 \rangle} + \frac{\langle s_{21} \rangle}{\tau_2\langle x_1 \rangle} = \left[\frac{1-E_1}{\tau_1} + \frac{1-E_2}{\tau_2}\right]\eta_{12} \\+ \frac{E_1}{\tau_1}\frac{\Cov(r_A,x_2)}{\langle r_A \rangle \langle x_2 \rangle} + \frac{E_2}{\tau_2}\frac{\Cov(r_A,x_1)}{\langle r_A \rangle \langle x_1 \rangle} \\ 
    - \frac{1-F_1}{\tau_1}\frac{\Cov(r_1,x_2)}{\langle r_1 \rangle \langle x_2 \rangle} - \frac{1-F_2}{\tau_2}\frac{\Cov(r_2,x_1)}{\langle r_2 \rangle \langle x_1 \rangle} \\ 
    - \frac{\psi_1}{\tau_1}\frac{\Cov(r_D,x_2)}{\langle r_D \rangle \langle x_2 \rangle} - \frac{\psi_2}{\tau_2}\frac{\Cov(r_D,x_1)}{\langle r_D \rangle \langle x_1 \rangle} \\
    - \frac{\phi_1}{\tau_1}\frac{\Cov(r_S,x_2)}{\langle r_S \rangle \langle x_2 \rangle} - \frac{\phi_2}{\tau_2}\frac{\Cov(r_S,x_1)}{\langle r_S \rangle \langle x_1 \rangle} \ ,
\end{multline}
where for each $i= 1,2$ we define
\begin{align}
        E_i &\coloneqq \frac{\delta_i\langle r_A \rangle}{\langle R_i^\pm \rangle}\label{eq: E_i appendix}\\
        \phi_i &\coloneqq \frac{\langle r_S \rangle}{\langle R_i^\pm \rangle}\label{eq: phi_i appendix}\\
        \psi_i &\coloneqq \frac{\delta_i\langle r_D \rangle}{\langle R_i^\pm \rangle}\label{eq: psi_i appendix}\\
        F_i &\coloneqq \phi_i + \psi_i\label{eq: F_i appendix} \ .
\end{align}
and
\begin{equation}
    \eta_{12} \coloneqq \frac{\Cov(x_1,x_2)}{\langle x_1 \rangle \langle x_2 \rangle}\ .
\end{equation}
Additionally, $\CV_i$ is the coefficient of variation for the component $X_i$, as defined in \cref{eq: CV}. 

While additional moment invariants can be obtained by considering pairs of components including $X_3$, we do not need these relations for the derivations presented here. 

\section{Derivation of a general bound on subunit fluctuations}\label{sect: general bound}
Here we derive a general bound on subunit fluctuations from the covariance balance relations \crefrange{eq: cb11}{eq: cb12}. To do so, we first rescale \cref{eq: cb11} and \cref{eq: cb22} by $E_2/(E_1\tau_2)$ and $E_1/(E_2\tau_1)$, respectively. Substracting the rescaled relations from \cref{eq: cb12} yields:
\begin{multline}\label{eq: gbd1}
     \frac{(1-E_1)E_2}{E_1\tau_2}\CV_1^2 + \frac{(1-E_2)E_1}{E_2\tau_1}\CV_2^2 = \Lambda \\
    + \frac{E_2\langle s_{11}\rangle  - E_1\langle s_{21} \rangle}{E_1\tau_2\langle x_1 \rangle} + \frac{E_1\langle s_{22}\rangle  - E_2\langle s_{12} \rangle}{E_2\tau_1\langle x_2 \rangle}  \\
    +\left[\frac{1-E_1}{\tau_1} + \frac{1-E_2}{\tau_2}\right]\eta_{12}\ ,
\end{multline}
where
\begin{multline}\label{eq: LAMBDA defn}
    \Lambda \coloneqq \frac{(1-F_1)E_2}{E_1\tau_2}\frac{\Cov(r_1,x_1)}{\langle r_1 \rangle\langle x_1\rangle} + \frac{(1-F_2)E_1}{E_2\tau_1}\frac{\Cov(r_2,x_2)}{\langle r_2 \rangle\langle x_2\rangle} \\
     - \frac{1-F_1}{\tau_1}\frac{\Cov(r_1,x_2)}{\langle r_1 \rangle\langle x_2\rangle} - \frac{1-F_2}{\tau_2}\frac{\Cov(r_2,x_1)}{\langle r_2 \rangle\langle x_1\rangle} \\
     + \frac{E_2\phi_1}{E_1\tau_2}\frac{\Cov(r_S, x_1)}{\langle r_S \rangle \langle x_1 \rangle} + \frac{E_1\phi_2}{E_2\tau_1}\frac{\Cov(r_S, x_2)}{\langle r_S \rangle \langle x_2 \rangle} \\
     - \frac{\phi_1}{\tau_2}\frac{\Cov(r_S, x_2)}{\langle r_S \rangle \langle x_2 \rangle} - \frac{\phi_2}{\tau_1}\frac{\Cov(r_S, x_1)}{\langle r_S \rangle \langle x_1 \rangle}\ .
\end{multline}
Note, to obtain \cref{eq: gbd1}, we used the fact that $\psi_1 E_2/E_1 = \psi_2, \phi_1 E_2/E_1 = \phi_2$, which follows directly from the definitions of these quantities, see \crefrange{eq: E_i appendix}{eq: psi_i appendix}. 

Since the covariance matrix must be positive semidefinite, we have the Cauchy-Schwarz inequality:
\begin{equation}
    -\CV_1\CV_2 \leq \eta_{12} \leq \CV_1\CV_2
\end{equation}
Combining this with the inequality of arithmetic and geometric means inequality gives
\begin{equation}
    \eta_{12} \geq -\frac{\CV_1^2 + \CV_2^2}{2}\ .
\end{equation}
Using this to lower bound $\eta_{12}$ in ~\cref{eq: gbd1} and collecting $\CV_1^2, \CV_2^2$ terms on the left-side yields
\begin{multline}\label{eq: gbd2}
     \left\{\frac{(1-E_1)E_2}{E_1\tau_2} + \frac{1}{2}\left[\frac{1-E_1}{\tau_1} 
     + \frac{1-E_2}{\tau_2}\right]\right\}\CV_1^2 \\
     + \left\{\frac{(1-E_2)E_1}{E_2\tau_1} + \frac{1}{2}\left[\frac{1-E_1}{\tau_1} 
     + \frac{1-E_2}{\tau_2}\right]\right\}\CV_2^2 \geq \Lambda \\
     +\frac{E_2\langle s_{11}\rangle  - E_1\langle s_{21} \rangle}{E_1\tau_2\langle x_1 \rangle} + \frac{E_1\langle s_{22}\rangle  - E_2\langle s_{12} \rangle}{E_2\tau_1\langle x_2 \rangle}\ .
\end{multline}
From the definition of the assembly efficiencies $E_1,E_2$ (\cref{eq: E_i appendix}) and Little's law (\cref{eq: Little's Law}), we have the following identities:
\begin{align}
    \frac{E_1\tau_2 \langle x_1 \rangle}{\delta_1} &= \frac{E_2\tau_1 \langle x_2 \rangle}{\delta_2} \\
     \tau_i &= \frac{1-E_i}{\beta_i}, \quad i = 1,2 \label{eq: tau_i identity}\ .
\end{align}
Thus, rescaling both sides of the inequality by $E_1\tau_2 \langle x_1 \rangle/\delta_1$, yields
\begin{multline}\label{eq: gbd3}
     \frac{E_1\tau_2}{\delta_1}\left\{\frac{(1-E_1)E_2}{E_1\tau_2} + \frac{1}{2}\left[\frac{1-E_1}{\tau_1} 
     + \frac{1-E_2}{\tau_2}\right]\right\}\frac{\CV_1^2}{1/\langle x_1 \rangle} \\
     + \frac{E_2\tau_1}{\delta_2}\left\{\frac{(1-E_2)E_1}{E_2\tau_1} + \frac{1}{2}\left[\frac{1-E_1}{\tau_1} 
     + \frac{1-E_2}{\tau_2}\right]\right\}\frac{\CV_2^2}{1/\langle x_2 \rangle} \\
     \geq \widetilde{\Lambda}
     +\frac{E_2\langle s_{11}\rangle  - E_1\langle s_{21} \rangle}{\delta_1} + \frac{E_1\langle s_{22}\rangle  - E_2\langle s_{12} \rangle}{\delta_2}\ ,
\end{multline}
where
\begin{equation}
    \widetilde{\Lambda} \coloneqq \frac{E_1\tau_2 \langle x_1 \rangle}{\delta_1}\Lambda\ .
\end{equation}
Then substituting \cref{eq: tau_i identity} leads to
\begin{multline}\label{eq: GB}
     \frac{1}{\delta_1}\left[E_2(1-E_1) + \frac{\frac{\beta_1}{\beta_2} + 1}{2}E_1(1-E_2)\right]\frac{\CV_1^2}{1/\langle x_1 \rangle} \\ 
     + \frac{1}{\delta_2}\left[E_1(1-E_2) + \frac{\frac{\beta_2}{\beta_1} + 1}{2}E_2(1-E_1)\right]\frac{\CV_2^2}{1/\langle x_2 \rangle} \\
     \geq \frac{E_2\langle s_{11}\rangle  - E_1\langle s_{21} \rangle}{\delta_1} 
     + \frac{E_1\langle s_{22}\rangle  - E_2\langle s_{12} \rangle}{\delta_2} + \widetilde{\Lambda}\ .
\end{multline}
Deriving the main results of the paper relies on constraining $\widetilde{\Lambda}$ for the various classes of systems considered in the main text, which are each a sub-class of \cref{eq: super class}. Before proceeding, we first simplify $\widetilde{\Lambda}$ using the definitions of $E_1, E_2,\phi_1,\phi_2, F_1, F_2$ (\crefrange{eq: E_i appendix}{eq: F_i appendix}) and Little's law (\cref{eq: Little's Law}). Combining these definitions with the bilinearity of covariances, we obtain the following simplified expression:
\begin{multline}\label{eq: tilde-lambda}
    \widetilde{\Lambda} = \frac{\delta_1\delta_2\langle r_A \rangle}{\langle R_1^\pm \rangle \langle R_2^\pm \rangle}\\
    \times \Cov\left(\frac{r_1 + r_S}{\delta_1} - \frac{r_2 + r_S}{\delta_2},\frac{x_1}{\delta_1} - \frac{x_2}{\delta_2}\right)\ .
\end{multline}

\section{Specialization of the general bound to restricted classes of assembly processes}
\subsection{Derivation of \cref{eq: beta asymmetry}}~\label{sect: beta appendix}
We consider the system defined by Eqs.~(\ref{eq: 2016 with co-synthesis - subunit dynamics},~\ref{eq: 2016 with co-synthesis - complexing dynamics}) from the main text, which corresponds to a restriction of the general class of systems \cref{eq: super class} where
\begin{equation}
    \begin{aligned}
        r_1(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= r_2(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) \\
        &\eqqcolon r_I(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) 
    \end{aligned}
\end{equation}
and $\delta_1 = \delta_2 = 1$. %

Under these restrictions $\frac{r_1 + r_S}{\delta_1} - \frac{r_2 + r_S}{\delta_2} = 0$, so that
\begin{equation}
    \widetilde{\Lambda} = \frac{\langle r_A \rangle}{\langle R_1^\pm \rangle \langle R_2^\pm \rangle}\Cov\left(0, \frac{x_1}{\delta_1} - \frac{x_2}{\delta_2}\right) = 0
\end{equation}

Additionally, the restrictions lead to the following symmetries in flux ratios, see Eqs.~(\ref{eq: E_i appendix},~\ref{eq: F_i appendix}):
\begin{equation}
    \begin{aligned}
        E_1 &= E_2 \eqqcolon E \\
        F_1 &= F_2 \eqqcolon F %
    \end{aligned}
\end{equation}
Then using the definition of average (co-)step-sizes (\cref{eq: co-step sizes} we have
\begin{equation}
    \begin{aligned}
        \langle s_{11} \rangle &= \langle s_{22} \rangle = 1 \\ %
        \langle s_{12} \rangle &= \langle s_{21} \rangle = (F+E)/2 \ .%
    \end{aligned}
\end{equation}
The general bound \cref{eq: GB} thus leads to 
\begin{equation}\label{eq: weighted average}
    \frac{3 + \frac{\beta_1}{\beta_2}}{2}\frac{\CV_1^2}{1/\langle x_1 \rangle} +  \frac{3 + \frac{\beta_2}{\beta_1}}{2}\frac{\CV_2^2}{1/\langle x_2 \rangle} \geq 1 + \frac{1-F}{1-E}
\end{equation}
To obtain \cref{eq: beta asymmetry} we assume without loss of generality that $\beta_2 \geq \beta_1$. Thus, 
\begin{multline}
    \frac{3 + \frac{\beta_2}{\beta_1}}{2}\left(\frac{\CV_1^2}{1/\langle x_1 \rangle} + \frac{\CV_2^2}{1/\langle x_2 \rangle}\right) \\
    \geq \frac{3 + \frac{\beta_1}{\beta_2}}{2}\frac{\CV_1^2}{1/\langle x_1 \rangle} +  \frac{3 + \frac{\beta_2}{\beta_1}}{2}\frac{\CV_2^2}{1/\langle x_2 \rangle}\ , 
\end{multline}
which combined with \cref{eq: weighted average} yields \cref{eq: beta asymmetry}, as desired.

While \cref{eq: beta asymmetry} is easily interpretable and establishes diverging fluctuations for any finite degradation rate asymmetry if $F \neq 100\%$, it can only be achieved for $\beta_1 = \beta_2$ and is increasingly loose for larger degradation rate asymmetries. For example, suppose a system has $F = 0\%, E = 90\%$, $\beta_2 = 10 \beta_1$ and is feedback controlled such that $X_1$ achieves exactly Poisson fluctuations, i.e., $\frac{\CV^2_1}{1/\langle x_1 \rangle} = 1$. \cref{eq: beta asymmetry} then tells us $\frac{\CV^2_2}{1/\langle x_2 \rangle} \gtrapprox 0.69$, thus permitting the possibility that $X_2$ fluctuations are suppressed to 69\% of Poisson levels. However, the more severe (but less easily interpreted) bound given by \cref{eq: weighted average} tells us that $\frac{\CV^2_2}{1/\langle x_2 \rangle} \gtrapprox 1.45$, meaning $X_2$ fluctuations must be at least 145\% of Poisson levels, which is more than twice the minimum value permitted by the looser bound.

\subsection{Derivation of \cref{eq: hoc bound}}\label{sect: delta generalization}
Now we consider the system \cref{eq: higher-order complexes} from the main text, which corresponds to a restriction of the general class of systems \cref{eq: super class} where 
\begin{equation}
    \begin{aligned}
    r_1(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= \lambda_1 r_I(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL},\boldsymbol{x})\\
    r_2(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= \lambda_2 r_I(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) \\
    r_S(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= 0
    \end{aligned}
\end{equation}
Under these restrictions $\frac{r_1 + r_S}{\delta_1} - \frac{r_2 + r_S}{\delta_2} = \left(\frac{\lambda_1}{\delta_1} - \frac{\lambda_2}{\delta_2}\right)r_I$, so that
\begin{equation}\label{eq: lambda epsilon}
    \widetilde{\Lambda} = \varepsilon\frac{\delta_1\delta_2\langle r_A \rangle}{\langle R_1^\pm \rangle \langle R_2^\pm \rangle} \Cov\left(r_I, \frac{x_1}{\delta_1} - \frac{x_2}{\delta_2}\right) \ ,
\end{equation}
where $\varepsilon \coloneqq \frac{\lambda_1}{\delta_1} - \frac{\lambda_2}{\delta_2}$. 

Thus, if $\lambda_1 = \delta_1, \lambda_2 = \delta_2$ then $\varepsilon = 0$. This leads to $\widetilde{\Lambda} = 0$ so long as $r_I$ has finite variance, as any physical rate function should. Additionally, $\varepsilon = 0$ leads to
\begin{equation}
    \begin{aligned}
        E_1 &= E_2 \eqqcolon E \\
        F_1 &= F_2 \eqqcolon F\ ,
    \end{aligned}
\end{equation}
see Eqs.(\ref{eq: E_i appendix},~\ref{eq: F_i appendix}). Then using the definition of average (co-)step-sizes (\cref{eq: co-step sizes}) we have
\begin{equation}
\begin{aligned}
    \langle s_{11} \rangle &= 1 + \frac{(F+E)(\delta_1 - 1)}{2}\\
    \langle s_{22} \rangle &= 1 + \frac{(F+E)(\delta_2 - 1)}{2}\\
    \langle s_{21} \rangle &= \frac{(F+E)\delta_1}{2}\\
    \langle s_{12} \rangle &= \frac{(F+E)\delta_2}{2} 
\end{aligned}
\end{equation}
The general bound \cref{eq: GB} thus leads to 
\begin{equation}\label{eq: weighted average deltas}
    \frac{3 + \frac{\beta_1}{\beta_2}}{1 + \frac{\delta_1}{\delta_2}}\frac{\CV_1^2}{1/\langle x_1 \rangle} +  \frac{3 + \frac{\beta_2}{\beta_1}}{1 + \frac{\delta_2}{\delta_1}}\frac{\CV_2^2}{1/\langle x_2 \rangle} \geq 1 + \frac{1-F}{1-E}\ .
\end{equation}
Without loss of generality $\beta_2 \geq \beta_1$ leads to the following (loose) bound:
\begin{multline}
    \frac{1}{1 + \frac{\delta_1}{\delta_2}}\frac{\CV_1^2}{1/\langle x_1 \rangle} +  \frac{1}{1 + \frac{\delta_2}{\delta_1}}\frac{\CV_2^2}{1/\langle x_2 \rangle} \\
    \geq \frac{1}{3 + \frac{\beta_2}{\beta_1}}\left(1 + \frac{1-F}{1-E}\right)\ .
\end{multline}
Upper bounding the left side by substituting $\min\left\{\delta_1/\delta_2,\delta_2/\delta_1\right\}$ for both delta ratios leads to \cref{eq: hoc bound}, as desired. 

\subsection{Derivation of \cref{eq: dual input OL bound}}\label{sect: OL appendix}
In the main text we present the bound \cref{eq: dual input OL bound} for the class of systems defined by restricting general class of systems \cref{eq: super class} such that 
\begin{equation}\label{eq: OL r_s}
    r_S(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) = r_S(\boldsymbol{u}^\mathrm{OL})
\end{equation}
and
\begin{equation}\label{eq: ol restrictions}
    \begin{aligned}
        r_1(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= r_1(\boldsymbol{u}^\mathrm{OL})\\
        r_2(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) &= r_2(\boldsymbol{u}^\mathrm{OL})
    \end{aligned}
\end{equation}
Here we consider a more general class of systems where for each $i = 1,2$
\begin{multline}\label{eq: unequal synthesis rates appendix}
r_i(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) = \lambda_i r_I(\boldsymbol{u}^\mathrm{OL},\boldsymbol{u}^\mathrm{CL}, \boldsymbol{x}) \\ + \Delta_i(\boldsymbol{u}^\mathrm{OL}) \ , 
\end{multline}
In the limit that $\lambda_1 = \lambda_2 = 0$, we recover the system defined by the restrictions \cref{eq: ol restrictions}.

Under the restrictions Eqs.~(\ref{eq: OL r_s},~\ref{eq: unequal synthesis rates appendix}) we have 
\begin{equation}
\begin{aligned}\label{eq: dual input appendix step-sizes}
    \langle s_{11} \rangle &= \frac{1-F_1 + \phi_1 + 1-E_1 + \delta_1 E_1 + \delta_1 \psi_1}{2}\\ %
    \langle s_{22} \rangle &= \frac{1-F_2 + \phi_2 + 1-E_2 + \delta_2 E_2 + \delta_2 \psi_2}{2}\\ %
    \langle s_{21} \rangle &= \frac{\phi_2 + \delta_1 E_2 + \delta_1 \psi_2}{2}\\ %
    \langle s_{12} \rangle &= \frac{\phi_1 + \delta_2 E_1 + \delta_2 \psi_1}{2}\\ %
\end{aligned}
\end{equation}
see Eqs.~(\ref{eq: co-step sizes},~\ref{eq: E_i appendix}-\ref{eq: F_i appendix}).

We wish to show \cref{eq: dual input OL bound} holds for this system. To do this, we first consider the time evolution of the ensemble averaged subunit abundances conditioned on the history of the open-loop variables $\boldsymbol{u}^\mathrm{OL}$. When conditioning on a particular history $\boldsymbol{u}^\mathrm{OL}[0,t]$, the time evolution of the conditional distribution follows a master equation (\cref{eq: cCME}) where $\boldsymbol{u}^\mathrm{OL}$ can be regarded as a deterministic time-dependent signal. Thus, we have the usual moment evolution equations (cf. \cref{eq: mean evolution}) for the conditional moments:
\begin{align}
    \frac{\mathrm{d}\overline{x_1}}{\mathrm{d}t} &= \overline{r_1} + \overline{r_S} + \delta_1(\overline{r_D} - \overline{r_A}) - \beta_1 \overline{x_1} \label{eq: x1-bar} \\ 
    \frac{\mathrm{d}\overline{x_2}}{\mathrm{d}t} &= \overline{r_2} + \overline{r_S} + \delta_2(\overline{r_D} - \overline{r_A}) - \beta_2 \overline{x_2} \ ,\label{eq: x2-bar} 
\end{align}
\comm{where for any dynamic random variable $y$, we define $\overline{x}(t) \coloneqq \left\langle x | \boldsymbol{u}^\mathrm{OL}[0,t]\right\rangle(t)$ to represent the time-dependent conditional ensemble average given a particular history of the open-loop control variables. Note, in Eqs.~(\ref{eq: x1-bar},~\ref{eq: x2-bar}) and below we suppress the time-dependence of these conditional averages for notational simplicity.} Rescaling Eqs.~(\ref{eq: x1-bar},~\ref{eq: x2-bar}) by $1/\delta_1, 1/\delta_2$, respectively, and subtracting leads to
\begin{multline}\label{eq: d-diff}
     \frac{\mathrm{d}\left(\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)}{\mathrm{d}t} = \frac{\overline{r_1} + \overline{r_S}}{\delta_1} - \frac{\overline{r_2} + \overline{r_S}}{\delta_2}\\
     - \frac{\beta_1 \overline{x_1}}{\delta_1} + \frac{\beta_2 \overline{x_2}}{\delta_2}\ .
\end{multline}
Multiplying both sides of \cref{eq: d-diff} by $\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}$ and time averaging leads to %
\begin{multline}\label{eq: diff^2}
    \frac{1}{2}\left\langle \frac{\mathrm{d}\left(\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)^2}{\mathrm{d}t} \right\rangle^* \\
    = \Cov^*\left(\frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right) \\
    + \left\langle \frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2} \right\rangle^*\left\langle \frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2} \right\rangle^* \\
    - \Cov^*\left(\frac{\beta_1 \overline{x_1}}{\delta_1} - \frac{\beta_2 \overline{x_2}}{\delta_2}, \frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2} \right) \\
    - \left\langle \frac{\beta_1 \overline{x_1}}{\delta_1} - \frac{\beta_2 \overline{x_2}}{\delta_2} \right\rangle^*\left\langle \frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2} \right\rangle^*\ ,
\end{multline}
where $\Cov^*(\cdot,\cdot)$ denotes the temporal covariance defined through the long-time average in \cref{eq: long-time averaging}. 

The left side of \cref{eq: diff^2} must vanish at stationarity, otherwise one of $\overline{x_1},\overline{x_2}$ must go to $\infty$ as $t\to \infty$. Additionally, at stationarity we have
\begin{equation}
    0 = \left\langle \frac{\mathrm{d}\left(\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)}{\mathrm{d}t} \right\rangle^*\ ,
\end{equation}
which implies  
\begin{multline}
    \left\langle \frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2} \right\rangle^* \\
    = \left\langle \frac{\beta_1\overline{x_1}}{\delta_1} - \frac{\beta_2\overline{x_2}}{\delta_2} \right\rangle^*
\end{multline}
Combining this with \cref{eq: diff^2} and using the bilinearity of covariance, we have
\begin{multline}\label{eq: cov-bar identity}
    \Cov^*\left(\frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)
    \\=\frac{\beta_1}{\delta_1^2}\Var^*(\overline{x_1}) + \frac{\beta_2}{\delta_2^2}\Var^*(\overline{x_2})
    \\- \frac{\beta_1+\beta_2}{\delta_1\delta_2}\Cov^*(\overline{x_1},\overline{x_2})\ .
\end{multline}

The basic identity for the variance of a weighted sum of random variables gives
\begin{multline}
    \frac{\beta_1}{\delta_1^2}\Var^*\left(\overline{x_1}\right) + \frac{\beta_2}{\delta_2^2}\Var^*\left(\overline{x_2}\right) =  2\frac{\sqrt{\beta_1\beta_2}}{\delta_1\delta_2}\Cov^*(\overline{x_1},\overline{x_2}) \\
    + \Var^*\left(\frac{\sqrt{\beta_1}\overline{x_1}}{\delta_1} - \frac{\sqrt{\beta_2}\overline{x_2}}{\delta_2} \right)\ .
\end{multline}
Along with \cref{eq: cov-bar identity} and the non-negativity of variances we thus have
\begin{multline}\label{eq: cov-bar ineq}
    \Cov^*\left(\frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right) \\
    \geq \frac{2\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)}{\delta_1\delta_2}\Cov^*(\overline{x_1},\overline{x_2})\ .
\end{multline}
Note, $\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2} \leq 0$ by the AM-GM inequality. 
As in Sect.~\ref{sect: delta generalization}, let us define $\varepsilon \coloneqq \frac{\lambda_1}{\delta_1} - \frac{\lambda_2}{\delta_2}$. Then by bilinearity of covariance and the definition of the subunit synthesis rates (\cref{eq: unequal synthesis rates appendix}), we have
\begin{multline}\label{eq: cu cov-bar1}
    \Cov^*\left(\frac{\overline{r_1}+\overline{r_S}}{\delta_1} - \frac{\overline{r_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right) \\
    = \Cov\left(\frac{\overline{\Delta_1}+\overline{r_S}}{\delta_1} - \frac{\overline{\Delta_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right) \\
    + \epsilon \Cov\left(\overline{r_I},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)
\end{multline}
Using ergodicity and the fact that $\Delta_1,\Delta_2,r_S$ depend only on the conditioned history, we have
\begin{multline}\label{eq: cu cov-bar2}
    \Cov^*\left(\frac{\overline{\Delta_1}+\overline{r_S}}{\delta_1} - \frac{\overline{\Delta_2}+\overline{r_S}}{\delta_2},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)\\
    = \Cov\left(\frac{\Delta_1+r_S}{\delta_1} - \frac{\Delta_2+r_S}{\delta_2},\frac{x_1}{\delta_1} - \frac{x_1}{\delta_2}\right)\ .
\end{multline}
Eqs.~(\ref{eq: tilde-lambda}),~(\ref{eq: cov-bar ineq})-(\ref{eq: cu cov-bar2}) and bilinearity of covariance then gives 
\begin{multline}
    \frac{\langle R_1^\pm \rangle \langle R_2^\pm \rangle}{\delta_1\delta_2\langle r_A \rangle}\widetilde{\Lambda} \\
    \geq \frac{2}{\delta_1\delta_2}\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\Cov(\overline{x_1},\overline{x_2}) \\
    + \epsilon\Cov\left(r_I,\frac{x_1}{\delta_1} - \frac{x_2}{\delta_2}\right) \\ -\epsilon\Cov\left(\overline{r_I},\frac{\overline{x_1}}{\delta_1} - \frac{\overline{x_2}}{\delta_2}\right)  
\end{multline}
The Cauchy-Schwarz inequality implies that the covariance terms involving $r_I$ vanish for $|\varepsilon| \to 0$ so long as $r_I$ has finite variance. Thus, any conclusion obtained for $\varepsilon = 0$ is asymptotically valid for small $|\varepsilon|$. Taking $\varepsilon = 0$ we have
\begin{align}
     \frac{\langle R_1^\pm \rangle \langle R_2^\pm \rangle}{\langle r_A \rangle}\widetilde{\Lambda}\notag&\geq 2\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\\
     &\hspace{1.5cm} \times \Cov(\overline{x_1},\overline{x_2})\\
     &\geq 2\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\notag\\
     &\hspace{1.5cm} \times\sqrt{\Var(\overline{x_1})\Var(\overline{x_2})}\label{eq: CS} \\
     &\geq 2\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\notag\\
     &\hspace{1.5cm} \times\sqrt{\Var(x_1)\Var(x_2)}\label{eq: LOTV}\ ,
\end{align}
where \cref{eq: CS} follows from the Cauchy-Schwarz inequality and \cref{eq: LOTV} follows from the law of total variance. Little's law (\cref{eq: Little's Law}) and the flux balance relations (\cref{eq: R_i}) give
\begin{equation}
    \frac{\langle r_A \rangle}{\langle R_1^\pm \rangle \langle R_2^\pm \rangle} = \frac{\langle r_A\rangle \tau_1\tau_2}{\langle x_1 \rangle \langle x_2 \rangle}\ .
\end{equation}
Thus,
\begin{align}
    \widetilde{\Lambda} \notag&\geq 2\langle r_A \rangle\tau_1\tau_2\\
     &\hspace{1cm} \times\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\CV_1\CV_2 \\
     \notag&\geq \langle r_A \rangle\tau_1\tau_2\\
     &\hspace{1cm} \times\left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\left(\CV_1^2 + \CV_1^2\right)\ ,\label{eq: amgm1}
\end{align}
where \cref{eq: amgm1} follows from the AM-GM inequality. Again, invoking the definition of $E_1,E_2$ (\cref{eq: E_i appendix}), Little's law (\cref{eq: Little's Law}) and the flux balance relations (\cref{eq: R_i}), we have, for example, 
\begin{equation}
    \langle r_A \rangle\tau_1\tau_2\CV_1^2 = \frac{E_1}{\delta_1}\frac{1-E_2}{\beta_2}\frac{\CV_1^2}{1/\langle x_1 \rangle}\ .
\end{equation}
Combining this with the analogous expression for $\langle r_A \rangle\tau_1\tau_2\CV_2^2$, we have
\begin{multline}
    \widetilde{\Lambda} \geq \left(\sqrt{\beta_1\beta_2} - \frac{\beta_1 + \beta_2}{2}\right)\\
    \times \left(\frac{E_1}{\delta_1}\frac{1-E_2}{\beta_2}\frac{\CV_1^2}{1/\langle x_1 \rangle} + \frac{E_2}{\delta_2}\frac{1-E_1}{\beta_1}\frac{\CV_2^2}{1/\langle x_2 \rangle}\right)
\end{multline}
Substituting this inequality and the (co-)step-sizes (\cref{eq: dual input appendix step-sizes}) in \cref{eq: GB} and collecting terms gives
\begin{multline}
     \frac{1}{\delta_1}H\left(E_1,E_2,\frac{\beta_1}{\beta_2}\right)\frac{\CV_1^2}{1/\langle x_1 \rangle} \\
     + \frac{1}{\delta_2}H\left(E_2,E_1,\frac{\beta_2}{\beta_1}\right)\frac{\CV_2^2}{1/\langle x_2 \rangle} \\
     \geq \frac{E_2(2 - E_1 - F_1)}{2\delta_1} + \frac{E_1(2 - E_2 - F_2)}{2\delta_2} \ ,
\end{multline}
where
\begin{multline}
    H\left(E_1,E_2,\frac{\beta_1}{\beta_2}\right) \coloneqq E_2(1-E_1) \\
    + \left(\frac{\beta_1}{\beta_2} + 1 - \sqrt{\frac{\beta_1}{\beta_2}}\right)E_1(1-E_2) \ .
\end{multline}
It can be verified that $H\left(E_2,E_1,\beta_2/\beta_1\right) \geq H\left(E_1,E_2,\beta_1/\beta_2\right)$ for all permissible values of $E_1,E_2$ if $\beta_2/\beta_1 \geq 1$. Assuming $\beta_2 \geq \beta_1$ without loss of generality then leads to the following loose but more easily interpreted bound:
\begin{multline}\label{eq: pre-OL bound}
     \frac{1}{\delta_1}\frac{\CV_1^2}{1/\langle x_1 \rangle} + \frac{1}{\delta_2}\frac{\CV_2^2}{1/\langle x_2 \rangle} \geq \\
     \frac{1}{2}\frac{E_2(2 - E_1 - F_1)\delta_2^{-1}+ E_1(2 - E_2 - F_2)\delta_1^{-1}}{E_1(1-E_2) + \left(\frac{\beta_2}{\beta_1} + 1 - \sqrt{\frac{\beta_2}{\beta_1}}\right)E_2(1-E_1)}\ ,
\end{multline}
\cref{eq: dual input OL bound} follows by dividing \cref{eq: pre-OL bound} by $2(\delta_1^{-1}+\delta_2^{-1})$ and upper bounding the left side by substituting $\min\left\{\delta_1/\delta_2,\delta_2/\delta_1\right\}$ for both delta ratios. 

\section{\comm{Analytical treatment of singular limits}}
\comm{
Next, we consider systems defined by Eqs.~(\ref{eq: 2016 with co-synthesis - subunit dynamics},~\ref{eq: 2016 with co-synthesis - complexing dynamics}) of the main text and analyze their behaviour in two singular limits.
\subsection{\comm{$E=F=1$}}\label{sect: E=F=1}
\comm{If $E = 1$ then $\beta_1 \langle x_1 \rangle = \beta_2 \langle x_2 \rangle = 0$ (see Eqs.~(\ref{eq: E defn},~\ref{eq: flux balance})). Thus the fraction of time that the individual degradation rate for either component is non-zero has measure $0$ and we can regard these rates as $0$. Similarly, if $F = 1$ then $r_I = 0$ (see Eq.~\eqref{eq: F defn}). Thus, $X_1$ and $X_2$ molecules always enter and leave the system as a pair. Thus, $x_2 = x_1 + \omega$ at all times, where $\omega$ is the initial offset between $x_2$ and $x_1$, which illustrates the loss of ergodicity due to the dependence of the long-term behaviour on initial conditions. Because $x_2 - x_1$ is constant, the two-component dynamics reduce to the following one-variable problem:}
\begin{equation}
    x_1 \overset{r_S}{\xrightarrow{\hspace*{1.1cm}}} x_1 + 1 \qquad x_1 \overset{r_A}{\xrightarrow{\hspace*{1.1cm}}} x_1 - 1\ ,
\end{equation}
where any functional dependence of $r_S, r_A$ on $X_2$ levels is replaced with the identity $x_2 = x_1 + \omega$. Now, as in Ref.~\cite{Laurenti2018}, we take $\omega = 0$ and let $r_S = \alpha x_0$, where $x_0$ follows a Poisson process, and $r_A = \gamma x_1 x_2 = \gamma x_1(x_1 + \omega)$. 
While the stationary moment equations are not exactly solvable due to the nonlinearity of $r_A$, we can follow a linear noise approximation ~\cite{vank1992} to approximately determine the fluctuations
\begin{equation}
    \eta_{11} \approx \frac{1}{2} \left(\frac{1}{\left\langle x_1\right\rangle } + \frac{\tau _0}{\left(2 \tau _0+\tau _1\right) \left\langle x_0\right\rangle }\right)\ .
\end{equation}
In this approximation, the quadratic degradation rate can reduce $\eta_{11}$ to $1/2$ of Poisson fluctuations as long as $X_0$ fluctuates on much faster time scales than $X_1$ -- i.e. $\tau_0 \ll \tau_1$. The noise-reducing properties of quadratic degradation terms has been discussed previously~\cite{Nicolis1972, Mazo1975}. The problem of regulating the fluctuations of single-variable dynamics through self-enhanced degradation is fundamentally different from the problem of noise control in two-component assembly processes where each component's abundance can individually fluctuate stochastically, i.e. where one component's abundance is not exactly determined by the other component's abundance.}

\subsection{\comm{$\beta_2/\beta_1 = \infty$, $E = 1$}}\label{sect: beta2/beta1 = infty, E=1}
\comm{We here consider $\beta_1 = 0$ and $\beta_2>0$ along with $E = 1$.  Assuming the system reaches a stationary state implies that $\beta_2 \langle x_2 \rangle = 0$ which follows from the flux balance relation (Eq.~\eqref{eq: flux balance}) and the definition of $E$ (Eq.~\eqref{eq: E defn}). Thus, for $\beta_2 > 0$ we have $\langle x_2 \rangle = 0$. This implies that the fraction of time that $x_2$ is non-zero has measure $0$, and we can regard $x_2 = 0$. This implies that systems with $\beta_1 = 0,\ \beta_2 >0$ can only achieve $E=1$ if the assembly rate is effectively $\infty$ for non-zero $x_2$ such that $X_2$ molecules are immediately sequestered to the complex upon synthesis. The corresponding $X_1$-dynamics then become %
\begin{equation}
