\cite[Sect.\,4]{fo}, each generator $F_i\in\gS(\g)^{\g}$ was decomposed as $F_i=\sum_{j\ge 0} F_{i,j}$, where 
$\varphi_s(F_{i,j})=s^j F_{i,j}$. In \cite{fo}, 
we introduced a Poisson-commutative subalgebra  $\gZ=\gZ(\g,\vth)\subset\gS(\g)$ associated with $\vth$.
It is shown there that 
$\gZ$ contains a subalgebra 
\begin{equation}\label{z-x}
\gZ_{\times}=\gZ_{\times}(\g,\vth)=\mathsf{alg}\langle F_{i,j} \mid 1\le i \le r \ \text{ and } \ 0\le j \rangle
\end{equation}
generated by $ F_{i,j} $. 
If $\ind\g_{(0)}=\rk\g$ and $\g_0$ is not Abelian, then $\gZ=\mathsf{alg}\langle \gZ_\times,\cz_0\rangle$;
if $\ind\g_{(0)}=\rk\g$ and $\g_0$ is Abelian, then $\gZ=\mathsf{alg}\langle \gZ_\times,\cz_0,\g_0\rangle$ 
\cite{fo,some}.

\begin{thm} \label{image1}
We have $\psi(\gZ(\wg^\vth_-,[0]))=\mathsf{alg}\langle \gZ_\times,\gS(\g_0)^{\g_0}\rangle$.
\end{thm}
\begin{proof}
By Theorem~\ref{twist-inf}, $\gZ(\wg^\vth_-,[0])$ is generated by $\gS(\g_0)^{\g_0}$ and 
$(F_i)_ {[k]}$ with $k>0$ such that $k-\ell_i\in m\Z$. Clearly $\psi(\gS(\g_0)^{\g_0})=\gS(\g_0)^{\g_0}$. 
Next we consider the images of $(F_i)_ {[k]}$  under $\psi$. 

%% 


If $0<k<m$ and $(F_i)_{[k]}\ne 0$, then $k=\ell_i$ and $\psi((F_i)_{[k]})=F_{i,\ell_i}$ in the above notation. 
%%% of \cite[Sect.\,4]{fo}. 

Recall that $d_i=\deg F_i$.
%%% Suppose that $F_{i,\ell_i+jm}$ with
For $j\ge 1$, %% is nonzero. Then 
the image $\psi((F_i)_{[\ell_i+jm]})$ 
can be calculated using \eqref{pol-t} and it 
is equal to
\begin{equation} \label{im1}
F_{i,\ell_i+jm}+d_i F_{i,\ell_i+(j-1)m}+ \ldots + \binom{d_i+k-1}{k-1} F_{i,\ell_i+(j-k)m} +
\ldots +  \binom{d_i+j-1}{j-1} F_{i,\ell_i}.  
\end{equation}

For any $i$, we have $F_i =\sum_{j\ge 0} F_{i,\ell_i+jm} $, where the sum is  
finite and $F_{i,0}$ belongs to  $\gS(\g_0)$. 
By definition,  
$$
\mathsf{alg}\langle \gZ_\times,\gS(\g_0)^{\g_0}\rangle=\mathsf{alg}\langle F_{i,\ell_i+jm},\bh_u
\mid 1\le i\le r, \ 0\le j, \ 1\le u\le \rk\g_0\rangle. 
$$
