%%% .......... 
Arguing by induction on $j$ and using~\eqref{im1}, we prove that $\psi(\gZ(\wg^\vth_-,[0]))$ and $\mathsf{alg}\langle \gZ_\times,\gS(\g_0)^{\g_0}\rangle$ have the same generators. 
\end{proof}

If we consider the quotient of $\gZ(\wg^\vth,[0])$ by $t^m-1$, then $\gZ_\times$ should be replaced 
by $\gZ_\times(\g,\vth^{-1})\subset\gZ(\g,\vth^{-1})$. Recall that  a {\sf g.g.s.} for $\vth$ is defined in 
Section~\ref{subs:contr-&-inv}. 

\begin{thm} \label{image2}
Suppose $\ind\g_{(0)}=\rk\g$, there is a {\sf g.g.s.} $F_1,\ldots,F_r$ in $\gS(\g)^{\g}$ for $\vartheta$, and 
