% Subsection : Proof of Proposition technical_result_empirical_norm.

%
\subsection{Proof of Proposition \ref{technical_result_empirical_norm}}\label{section_proof_technical_result_empirical_norm}
The proof of Proposition \ref{technical_result_empirical_norm}, but also that of Proposition \ref{general_sufficient_condition_AC}, rely on the following technical lemma.
%

% Lemma : Weak differentiability of X.

%
\begin{lemma}\label{weak_differentiability_X}
Let $\xi$ be the solution of the stochastic differential equation
%
\begin{equation}\label{weak_differentiability_X_1}
\xi_t = x_0 +
\int_{0}^{t}\varphi(\xi_s,\zeta_s)ds +
\int_{0}^{t}\psi(\xi_s,\zeta_s)dW_1(s)
\textrm{ $;$ }t\in [0,T],
\end{equation}
%
where $\varphi$ and $\psi$ are continuously differentiable functions from $\mathbb R^2$ into $\mathbb R$, $\psi$ is bounded, both $\varphi$ and $\psi$ have bounded partial derivatives, and $\zeta$ is a $\mathbb F_2$-adapted process such that
%
\begin{equation}\label{weak_differentiability_X_2}
\mathbb E\left(\sup_{t\in [0,T]}\zeta_{t}^{2}\right) +
\sup_{s\in [0,T]}\mathbb E\left(\sup_{t\in [s,T]}
(\mathbf D_{s}^{2}\zeta_t)^2\right) <\infty.
\end{equation}
%
For any $t\in [0,T]$, $\xi_t\in\mathbb D^{1,2}$ and
%
\begin{displaymath}
\mathbf D_s\xi_t =
\begin{pmatrix}
 \alpha_1(s,t)\\
 \alpha_2(s,t)
\end{pmatrix}
e^{\beta(s,t)}\mathbf 1_{t\geqslant s}
\textrm{ $;$ }
\forall s\in [0,T]
\end{displaymath}
%
where, for every $s\in [0,t]$,
%
\begin{displaymath}
\beta(s,t) :=
\int_{s}^{t}\partial_1\psi(\xi_u,\zeta_u)dW_1(u) +
\int_{s}^{t}\left(\partial_1\varphi(\xi_u,\zeta_u) -
\frac{1}{2}\partial_1\psi(\xi_u,\zeta_u)^2\right)du
\end{displaymath}
%
and
%
\begin{eqnarray*}
 \alpha_{\ell}(s,t) & := &
 \psi(\xi_s,\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}e^{-\beta(s,u)}\partial_2\varphi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_udu\\
 & &
 \hspace{1cm} +
 \int_{s}^{t}e^{-\beta(s,u)}\partial_2\psi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_u
 (dW_1(u) -\partial_1\psi(\xi_u,\zeta_u)du)
 \textrm{ $;$ }\ell = 1,2.
\end{eqnarray*}
%
\end{lemma}
%
\noindent
The proof of Lemma \ref{weak_differentiability_X} is postponed to Section \ref{section_proof_weak_differentiability_X}.
\\
\\
Let $X$ be the solution of Equation (\ref{main_equation}), which coincides with Equation (\ref{weak_differentiability_X_1}) by taking $\zeta := Y$ and, for every $(x,y)\in\mathbb R^2$, $\varphi(x,y) := a(x) + b(y)$ and $\psi(x,y) :=\sigma(x)$. Consider also $\tau\in\mathcal S_1$, $\nu\in\mathcal S_2$ fulfilling the condition (\ref{technical_result_empirical_norm_1}), and $t\in (0,T]$ satisfying
%
\begin{equation}\label{technical_result_empirical_norm_2}
\tau(X_t) +\nu(Y_t) = 0.
\end{equation}
%
First, $\mathbf D^1Y_t = 0$ because $Y$ is $\mathbb F_2$-adapted while $W_1$ and $W_2$ are independent. Then, by Equality (\ref{technical_result_empirical_norm_2}) and the chain rule for the Malliavin derivative (see Nualart \cite{NUALART06}, Proposition 1.2.3),
%
\begin{equation}\label{technical_result_empirical_norm_3}
\tau'(X_t)\mathbf D^1X_t = 0.
\end{equation}
%
Moreover, by Lemma \ref{weak_differentiability_X}, and since $\partial_2\psi = 0$,
%
\begin{equation}\label{technical_result_empirical_norm_4}
\mathbf D_{s}^{1}X_t =
\sigma(X_s)e^{\beta(s,t)}
\textrm{ $;$ }\forall s\in [0,t].
\end{equation}
%
Since $\inf_{\mathbb R}|\sigma| > 0$ (see Assumption \ref{assumption_drift_volatility}), $\mathbf D^1X_t\not\equiv 0$ by Equality (\ref{technical_result_empirical_norm_4}), and thus Equality (\ref{technical_result_empirical_norm_3}) leads to $\tau'(X_t) = 0$. Now, by Equality (\ref{technical_result_empirical_norm_2}), by the chain rule for the Malliavin derivative, and since $\tau'(X_t) = 0$,
%
\begin{displaymath}
\nu'(Y_t)\mathbf D^2Y_t = 0.
\end{displaymath}
%
Then, $\nu'(Y_t) = 0$ because $\mathbf D^2Y_t\not\equiv 0$ (see Assumption \ref{assumption_Y}.(1)). In particular, $\mathbb E(|\nu'(Y_t)|) = 0$, and since the distribution of $Y_t$ has a positive and continuously differentiable density with respect to the Lebesgue measure on $\mathbb R$ (see Assumption \ref{assumption_Y}.(2)), $\nu' = 0$. In conclusion, $\nu(.) = 0$ because $\nu$ fulfills (\ref{technical_result_empirical_norm_1}), and $\tau(X_t) = 0$ by Equality (\ref{technical_result_empirical_norm_2}).
%

% Subusbsection : Proof of Lemma weak_differentiability_X.

%
\subsubsection{Proof of Lemma \ref{weak_differentiability_X}}\label{section_proof_weak_differentiability_X}
Let $(H_n)_{n\in\mathbb N}$ be the sequence defined by $H_0 = x_0$ and, for every $n\in\mathbb N$, $H_{n + 1} =\Phi(H_n)$, where
%
\begin{displaymath}
\Phi_t(H) :=
x_0 +
\int_{0}^{t}\varphi(H_s,\zeta_s)ds +
\int_{0}^{t}\psi(H_s,\zeta_s)dW_1(s)
\textrm{ $;$ }
t\in [0,T]\textrm{, }
H\in\mathcal C.
\end{displaymath}
%
Consider $n\in\mathbb N$ - for instance $n = 0$ - such that for any $\tau\in [0,T]$ and $r\in [0,\tau]$,
%
\begin{equation}\label{weak_differentiability_X_3}
\mu_n(r,\tau) :=
\mathbb E\left(
\sup_{t\in [r,\tau]}\|\mathbf D_rH_n(t)\|_{2,\mathbb R^2}^{2}\right)\leqslant
\mathfrak c_2\sum_{k = 0}^{n}\frac{\mathfrak c_{1}^{k}(\tau - r)^k}{k!},
\end{equation}
%
where
%
\begin{displaymath}
 \mathfrak c_1 :=
 3\max\{\|\psi\|_{\infty}^{2}\textrm{ $;$ }
 2(T\|\partial_1\varphi\|_{\infty}^{2} + 4\|\partial_1\psi\|_{\infty}^{2})\textrm{ $;$ }
 2(T\|\partial_2\varphi\|_{\infty}^{2} + 4\|\partial_2\psi\|_{\infty}^{2})\}
\end{displaymath}
%
and $\mathfrak c_2 :=\mathfrak c_{2,1} +\mathfrak c_{2,2}$ with
%
\begin{displaymath}
\mathfrak c_{2,\ell} =
\mathfrak c_1\left(1 + T\sup_{s\in [0,T]}\mathbb E\left(\sup_{t\in [s,T]}
(\mathbf D_{s}^{\ell}\zeta_t)^2\right)\right)
\textrm{ $;$ }\ell = 1,2.
\end{displaymath}
%
By Inequalities (\ref{weak_differentiability_X_2}) and (\ref{weak_differentiability_X_3}), $\zeta_u,H_n(u)\in\mathbb D^{1,2}$ for every $u\in [0,T]$, and by Nualart \cite{NUALART06}, Propositions 1.2.3 and 1.3.8, for every $t\in [0,T]$, $s\in [0,t]$ and $\ell = 1,2$,
%
\begin{eqnarray*}
 \mathbf D_{s}^{\ell}H_{n + 1}(t) & = &
 \int_{s}^{t}\mathbf D_{s}^{\ell}[\varphi(H_n(u),\zeta_u)]du +
 \psi(H_n(s),\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}\mathbf D_{s}^{\ell}[\psi(H_n(u),\zeta_u)]dW_1(u)\\
 & = &
 \psi(H_n(s),\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}[\partial_1\varphi(H_n(u),\zeta_u)\mathbf D_{s}^{\ell}H_n(u) +
 \partial_2\varphi(H_n(u),\zeta_u)\mathbf D_{s}^{\ell}\zeta_u]du\\
 & &
 \hspace{3cm} +
 \int_{s}^{t}[\partial_1\psi(H_n(u),\zeta_u)\mathbf D_{s}^{\ell}H_n(u) +
 \partial_2\psi(H_n(u),\zeta_u)\mathbf D_{s}^{\ell}\zeta_u]dW_1(u).
\end{eqnarray*}
%
Then, by the Doob inequality, by the isometry property of It\^o's integral, and since $\psi$ and the derivatives of both $\varphi$ and $\psi$ are bounded, for $\ell = 1,2$,
%
\begin{eqnarray*}
 \mathbb E\left(
 \sup_{t\in [r,\tau]}(\mathbf D_{r}^{\ell}H_{n + 1}(t))^2\right)
 & \leqslant &
 3\mathbb E(\psi(H_n(r),\zeta_r)^2)\mathbf 1_{\ell = 1}\\
 & &
 + 3(\tau - r)\int_{r}^{\tau}
 \mathbb E[(\partial_1\varphi(H_n(u),\zeta_u)\mathbf D_{r}^{\ell}H_n(u) +
 \partial_2\varphi(H_n(u),\zeta_u)\mathbf D_{r}^{\ell}\zeta_u)^2]du\\
 & &
 + 12\int_{r}^{\tau}\mathbb E[(\partial_1\psi(H_n(u),\zeta_u)\mathbf D_{r}^{\ell}H_n(u) +
 \partial_2\psi(H_n(u),\zeta_u)\mathbf D_{r}^{\ell}\zeta_u)^2]du\\
 & \leqslant &
 \mathfrak c_1\left(1 +
 \int_{r}^{\tau}\mathbb E((\mathbf D_{r}^{\ell}H_n(u))^2)du +
 \int_{r}^{\tau}\mathbb E((\mathbf D_{r}^{\ell}\zeta_u)^2)du\right)\\
 & \leqslant &
 \mathfrak c_{2,\ell} +
 \mathfrak c_1\int_{r}^{\tau}\mathbb E((\mathbf D_{r}^{\ell}H_n(u))^2)du,
\end{eqnarray*}
%
leading to
%
\begin{eqnarray*}
 \mu_{n + 1}(r,\tau)
 & \leqslant &
 \mathfrak c_2 +
 \mathfrak c_1\int_{r}^{\tau}
 \mathbb E\left(\sup_{v\in [r,u]}\|\mathbf D_rH_n(v)\|_{2,\mathbb R^2}^{2}\right)du\\
 & \leqslant &
 \mathfrak c_2 +
 \mathfrak c_1\int_{r}^{\tau}\left(
 \mathfrak c_2\sum_{k = 0}^{n}\frac{\mathfrak c_{1}^{k}(u - r)^k}{k!}\right)du
 \quad\textrm{by Inequality (\ref{weak_differentiability_X_3})}\\
 & = &
 \mathfrak c_2\left(1 +
 \sum_{k = 0}^{n}\frac{\mathfrak c_{1}^{k + 1}}{k!}\cdot
 \frac{(\tau - r)^{k + 1}}{k + 1}\right) =
 \mathfrak c_2\sum_{k = 0}^{n + 1}\frac{\mathfrak c_{1}^{k}(\tau - r)^k}{k!}.
\end{eqnarray*}
%
So, Inequality (\ref{weak_differentiability_X_3}) remains true for $\mu_{n + 1}$, and by induction
%
\begin{displaymath}
\sup_{n\in\mathbb N}\left\{
\sup_{s\in [0,T]}\mathbb E\left(
\sup_{t\in [s,T]}\|\mathbf D_sH_n(t)\|_{2,\mathbb R^2}^{2}\right)\right\}
\leqslant
\mathfrak c_2\sum_{k = 0}^{\infty}\frac{\mathfrak c_{1}^{k}T^k}{k!} =
\mathfrak c_2e^{\mathfrak c_1T} <\infty.
\end{displaymath}
%
Since, in addition, the Picard scheme $(H_n)_{n\in\mathbb N}$ converges to $\xi$ in $(\mathcal C,\|.\|_{\mathcal C})$ (see the proof of Nualart \cite{NUALART06}, Lemma 2.2.1), by Nualart \cite{NUALART06}, Lemma 1.2.3, $\xi_t\in\mathbb D^{1,2}$ for every $t\in [0,T]$. Therefore, by Nualart \cite{NUALART06}, Propositions 1.2.3 and 1.3.8, for every $t\in [0,T]$, $s\in [0,t]$ and $\ell = 1,2$,
%
\begin{eqnarray}
 \mathbf D_{s}^{\ell}\xi_t & = &
 \psi(\xi_s,\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}[\partial_1\varphi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\xi_u +
 \partial_2\varphi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_u]du
 \nonumber\\
 & &
 \hspace{4cm} +
 \int_{s}^{t}[\partial_1\psi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\xi_u +
 \partial_2\psi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_u]dW_1(u)
 \nonumber\\
 \label{weak_differentiability_X_4}
 & = &
 \psi(\xi_s,\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}\mathbf D_{s}^{\ell}\xi_udZ(s,u) + R_{\ell}(s,t),
\end{eqnarray}
%
where
%
\begin{eqnarray*}
 Z(s,t) & := &
 \int_{s}^{t}\partial_1\varphi(\xi_u,\zeta_u)du +
 \int_{s}^{t}\partial_1\psi(\xi_u,\zeta_u)dW_1(u)\\
 & &
 \hspace{1.5cm}{\rm and}\quad
 R_{\ell}(s,t) :=
 \int_{s}^{t}\mathbf D_{s}^{\ell}\zeta_u(
 \partial_2\varphi(\xi_u,\zeta_u)du +\partial_2\psi(\xi_u,\zeta_u)dW_1(u)).
\end{eqnarray*}
%
In conclusion, for any $s\in [0,T]$ and $\ell = 1,2$, since $(\mathbf D_{s}^{\ell}\xi_t)_{t\in [s,T]}$ is the solution of the linear stochastic differential equation (\ref{weak_differentiability_X_4}), $\mathbf D_{s}^{\ell}\xi_t =\alpha_{\ell}(s,t)e^{\beta(s,t)}$ for any $t\in [s,T]$, where
%
\begin{eqnarray*}
 \beta(s,t)
 & := &
 Z(s,t) -\frac{1}{2}\langle Z(s,.)\rangle_t\\
 & = &
 \int_{s}^{t}\partial_1\psi(\xi_u,\zeta_u)dW_1(u) +
 \int_{s}^{t}\left(\partial_1\varphi(\xi_u,\zeta_u) -
 \frac{1}{2}\partial_1\psi(\xi_u,\zeta_u)^2\right)du
\end{eqnarray*}
%
and
%
\begin{eqnarray*}
 \alpha_{\ell}(s,t)
 & := &
 \psi(\xi_s,\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}e^{-\beta(s,u)}dR_{\ell}(s,u) -
 \int_{s}^{t}e^{-\beta(s,u)}d\langle Z(s,.),R_{\ell}(s,.)\rangle_u\\
 & = &
 \psi(\xi_s,\zeta_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}e^{-\beta(s,u)}\partial_2\varphi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_udu\\
 & &
 \hspace{3cm} +
 \int_{s}^{t}e^{-\beta(s,u)}\partial_2\psi(\xi_u,\zeta_u)\mathbf D_{s}^{\ell}\zeta_u
 (dW_1(u) -\partial_1\psi(\xi_u,\zeta_u)du).
\end{eqnarray*}
%

% Subsection : Proof of Proposition general_sufficient_condition_AC.

%
\subsection{Proof of Proposition \ref{general_sufficient_condition_AC}}\label{section_proof_general_sufficient_condition_AC}
Let $X$ be the solution of Equation (\ref{main_equation}), which coincides with Equation (\ref{weak_differentiability_X_1}) by taking $\zeta := Y$ and, for every $(x,y)\in\mathbb R^2$, $\varphi(x,y) := a(x) + b(y)$ and $\psi(x,y) :=\sigma(x)$. By Lemma \ref{weak_differentiability_X}, since $\partial_2\psi = 0$, and since $Y$ is $\mathbb F_2$-adapted while $W_1$ and $W_2$ are independent, for every $t\in [0,T]$ and $s\in [0,t]$,
%
\begin{equation}\label{general_sufficient_condition_AC_1}
\mathbf D_{s}^{1}X_t =
\sigma(X_s)e^{\beta(s,t)}
\quad {\rm and}\quad
\mathbf D_{s}^{2}X_t =
\int_{s}^{t}e^{\beta(s,u)}b'(Y_u)\mathbf D_sY_udu.
\end{equation}
%
The proof is dissected in two steps: Proposition \ref{general_sufficient_condition_AC}.(1) is established in Step 1, and Proposition \ref{general_sufficient_condition_AC}.(2) is established in Step 2.
\\
\\
{\bf Step 1.} For any $t\in (0,T]$, let $\Gamma_t$ be the Malliavin matrix of $(X_t,Y_t)$, which is defined by
%
\begin{displaymath}
\Gamma_t :=
\begin{pmatrix}
 \|\mathbf DX_t\|_{T}^{2} & \langle\mathbf DX_t,\mathbf DY_t\rangle_T\\
 \langle\mathbf DY_t,\mathbf DX_t\rangle_T & \|\mathbf DY_t\|_{T}^{2}
\end{pmatrix}.
\end{displaymath}
%
Since $\mathbf D^1Y_t = 0$, and by the Cauchy-Schwarz inequality,
%
\begin{eqnarray}
 \det(\Gamma_t) & = &
 \|\mathbf DX_t\|_{T}^{2}
 \|\mathbf DY_t\|_{T}^{2} -
 \langle\mathbf DX_t,\mathbf DY_t\rangle_{T}^{2}
 \nonumber\\
 & = &
 (\|\mathbf D^1X_t\|_{T}^{2} +\|\mathbf D^2X_t\|_{T}^{2})\|\mathbf D^2Y_t\|_{T}^{2} -
 \langle\mathbf D^2X_t,\mathbf D^2Y_t\rangle_{T}^{2}
 \nonumber\\
 \label{general_sufficient_condition_AC_2}
 & \geqslant &
 \|\mathbf D^1X_t\|_{T}^{2}\|\mathbf D^2Y_t\|_{T}^{2}.
\end{eqnarray}
%
Moreover, $\mathbf D^2Y_t\not\equiv 0$ (see Assumption \ref{assumption_Y}.(1)), and since $\inf_{\mathbb R}|\sigma| > 0$ (see Assumption \ref{assumption_drift_volatility}), (\ref{general_sufficient_condition_AC_1}) leads to $\mathbf D^1X_t\not\equiv 0$. Thus, $\det(\Gamma_t) > 0$, and by the Bouleau-Hirsch criterion (see Nualart \cite{NUALART06}, Theorem 2.1.2), the distribution of $(X_t,Y_t)$ has a density with respect to the Lebesgue measure on $\mathbb R^2$.
\\
\\
{\bf Step 2.} Assume that $\sigma$ is bounded, and that $a,b,\sigma\in C^{\infty}(\mathbb R)$ with all derivatives bounded. Assume also that $Y\in\mathbb H^{\infty}$, and that $1/\|\mathbf D^2Y_t\|_T$ belongs to $\mathbb L^p(\Omega)$ for every $p\geqslant 1$. First of all, note that since $Y\in\mathbb H^{\infty}$, by (\ref{general_sufficient_condition_AC_1}) together with Nualart \cite{NUALART06}, Lemma 2.2.1,
%
\begin{equation}\label{general_sufficient_condition_AC_3}
\mathbb E\left(\sup_{t\in [0,T]}|X_t|^p\right) +
\sup_{s\in [0,T]}\mathbb E\left(\sup_{t\in [s,T]}\|\mathbf D_sX_t\|_{p,\mathbb R^2}^{p}\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1.
\end{equation}
%
{\it Notations:}
%
\begin{itemize}
 \item For every $k\in\mathbb N^*$, $\Pi_k$ is the set of all partitions of $\{1,\dots,k\}$, and $\Pi_{k}^{*} :=\Pi_k\backslash\{\{\{1,\dots,k\}\}\}$.
 \item For every $k\in\mathbb N^*$ and $j\in\{1,\dots,k\}$, $\Pi_{k\backslash j}$ is the set of all partitions of $\{1,\dots,k\}\backslash\{j\}$.
 \item Consider a set $E$, $k\in\mathbb N^*$ and $J\subset\{1,\dots,k\}$. For every $\mathbf x = (x_1,\dots,x_k)\in E^k$, $\mathbf x_J := (x_j)_{j\in J}$.
\end{itemize}
%
{\it Step 2.1.} Consider $t\in (0,T]$. By (\ref{general_sufficient_condition_AC_1}), since $\rho : x\in (0,\infty)\mapsto 1/x$ is a convex function, by the Jensen inequality, and since $\inf_{\mathbb R}|\sigma| > 0$,
%
\begin{eqnarray*}
 \frac{1}{\|\mathbf D^1X_t\|_{T}^{2}}
 & = &
 \frac{1}{t}\rho\left(\int_{0}^{t}\sigma(X_s)^2e^{2\beta(s,t)}\frac{ds}{t}\right)\\
 & \leqslant &
 \frac{1}{t^2}\int_{0}^{t}\rho(\sigma(X_s)^2e^{2\beta(s,t)})ds\\
 & \leqslant &
 \frac{\mathfrak c_1}{t^2}\int_{0}^{t}e^{-2\beta(s,t)}ds
 \quad {\rm with}\quad
 \mathfrak c_1 =\left(\inf_{x\in\mathbb R}|\sigma(x)|\right)^{-2}.
\end{eqnarray*}
%
Then, for any $\alpha > 1$,
%
\begin{eqnarray*}
 \mathbb E\left(\frac{1}{\|\mathbf D^1X_t\|_{T}^{4\alpha}}\right)
 & \leqslant &
 \frac{\mathfrak c_{1}^{2\alpha}}{t^{2\alpha + 1}}
 \int_{0}^{t}\mathbb E(e^{-4\alpha\beta(s,t)})ds\\
 & \leqslant &
 \frac{\mathfrak c_{1}^{2\alpha}}{t^{2\alpha + 1}}
 e^{2\alpha T\|a'\|_{\infty} + (8\alpha^2 + 2\alpha)T\|\sigma'\|_{\infty}^{2}}\\
 & &
 \hspace{0.75cm}\times
 \int_{0}^{t}\mathbb E\left[\exp\left(
 \int_{s}^{t}(-4\alpha)\sigma'(X_u)dW_1(u) -
 \frac{1}{2}\int_{s}^{t}(-4\alpha)^2\sigma'(X_u)^2du\right)\right]ds\\
 & \leqslant &
 \frac{\mathfrak c_2(\alpha)^2}{t^{2\alpha}}
 \quad {\rm with}\quad
 \mathfrak c_2(\alpha) =
 \mathfrak c_{1}^{\alpha}e^{6\alpha^2T\max\{\|a'\|_{\infty},\|\sigma'\|_{\infty}^{2}\}}.
\end{eqnarray*}
%
Therefore, by Inequality (\ref{general_sufficient_condition_AC_2}),
%
\begin{displaymath}
\mathbb E\left(\left|\frac{1}{\det(\Gamma_t)}\right|^{\alpha}\right)
\leqslant
\frac{\mathfrak c_2(\alpha)}{t^{\alpha}}
\mathbb E\left(\frac{1}{\|\mathbf DY_t\|_{T}^{4\alpha}}\right)^{\frac{1}{2}} <\infty.
\end{displaymath}
%
{\it Step 2.2.} The purpose of this step is to recursively establish that for every $k\in\mathbb N^*$,
%
\begin{itemize}
 \item $\mathbf P(k)$: For every $\mathbf l\in\{1,2\}^k$, $\mathbf s\in\mathbb [0,T]^k$ and $t\in [\max(\mathbf s),T]$,
 %
 \begin{eqnarray*}
  \mathbf D_{\bf s}^{(k),\mathbf l}X_t
  & = &
  \alpha_{\bf l}(\mathbf s,t) +\beta_{\bf l}(\mathbf s,t) +
  \int_{\max(\mathbf s)}^{t}a'(X_u)
  \mathbf D_{\bf s}^{(k),\mathbf l}X_udu\\
  & &
  \hspace{4cm} +
  \int_{\max(\mathbf s)}^{t}\sigma'(X_u)
  \mathbf D_{\bf s}^{(k),\mathbf l}X_udW_1(u),
 \end{eqnarray*}
 %
 where
 %
 \begin{eqnarray*}
  \alpha_{\bf l}(\mathbf s,t) & := &
  \int_{\max(\mathbf s)}^{t}\sum_{\pi\in\Pi_k}
  b^{(|\pi|)}(Y_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}Y_udu\\
  & &
  \hspace{1.5cm} +
  \mathbf 1_{k > 1}\int_{\max(\mathbf s)}^{t}\sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi|)}(X_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_udu\\
  & &
  \hspace{3cm} +
  \mathbf 1_{k > 1}\int_{\max(\mathbf s)}^{t}\sum_{\pi\in\Pi_{k}^{*}}
  \sigma^{(|\pi|)}(X_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_udW_1(u)
 \end{eqnarray*}
 %
 and
 %
 \begin{eqnarray*}
  \beta_{\bf l}(\mathbf s,t)
%  & = &
%  \sigma(X(s_1))\mathbf 1_{k = 1,\ell_1 = 1} +
%  \mathbf D_{s_1,\dots,s_{k - 1}}^{(k - 1),\ell_1,\dots,\ell_{k - 1}}
%  [\sigma(X(\max(\mathbf s)))]\mathbf 1_{k > 1,\ell_k = 1} +\\
%  & &
%  \mathbf D_{s_2,\dots,s_k}^{(k - 1),\ell_2,\dots,\ell_k}
%  [\sigma(X(s_1)]\mathbf 1_{k > 1,\ell_1 = 1} +
%  \sum_{j = 3}^{k}\mathbf D_{s_1,\dots,s_{j - 2},s_j,\dots,s_k}^{(k - 1),
%  \ell_1,\dots,\ell_{j - 2},\ell_j,\dots,\ell_k}
%  [\sigma(X(\{s_1,\dots,s_{j - 1}\}))]\mathbf 1_{k > 2,\ell_{j - 1} = 1}\\
  & := &
  \sigma(X_{s_1})\mathbf 1_{k = 1,\ell_1 = 1} +
  \mathbf 1_{k > 1}\left[\mathbf 1_{\ell_1 = 1}\sum_{\pi\in\Pi_{k\backslash 1}}\sigma^{(|\pi|)}(X_{s_1})
  \prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{s_1}\right.\\
  & &
  \hspace{4.5cm}\left. +\mathbf 1_{\ell_k = 1}
  \sum_{\pi\in\Pi_{k - 1}}\sigma^{(|\pi|)}(X_{\max(\mathbf s)})
  \prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\max(\mathbf s)}
  \right]\\
  & &
  \hspace{0.75cm} +
  \mathbf 1_{k > 2}\sum_{j = 2}^{k - 1}\mathbf 1_{\ell_j = 1}\sum_{\pi\in\Pi_{k\backslash j}}
  \sigma^{(|\pi|)}(X_{\max\{s_1,\dots,s_j\}})
  \prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\max\{s_1,\dots,s_j\}}.
 \end{eqnarray*}
 %
 \item $\mathbf Q(k)$: For every $p\geqslant 1$ and $\mathbf l\in\{1,2\}^{k + 1}$,
 %
 \begin{displaymath}
 \sup_{\mathbf r\in [0,T]^{k + 1}}
 \mathbb E\left(\sup_{u\in [\max(\mathbf r),T]}
 |\mathbf D_{\mathbf r}^{(k + 1),\mathbf l}X_u|^p\right) <\infty.
 \end{displaymath}
 %
\end{itemize}
%
First, for $k = 1$ and every $t\in [0,T]$, as established in the proof of Lemma \ref{weak_differentiability_X}, for any $\ell\in\{1,2\}$ and every $s\in [t,T]$,
%
\begin{eqnarray*}
 \mathbf D_{s}^{\ell}X_t & = &
 \sigma(X_s)\mathbf 1_{\ell = 1} +
 \int_{s}^{t}b'(Y_u)\mathbf D_{s}^{\ell}Y_udu\\
 & &
 \hspace{3cm} +
 \int_{s}^{t}a'(X_u)\mathbf D_{s}^{\ell}X_udu +
 \int_{s}^{t}\sigma'(X_u)\mathbf D_{s}^{\ell}X_udW_1(u)\\
 & = &
 \alpha_{\ell}(s,t) +\beta_{\ell}(s,t) +
 \int_{s}^{t}a'(X_u)\mathbf D_{s}^{\ell}X_udu +
 \int_{s}^{t}\sigma'(X_u)\mathbf D_{s}^{\ell}X_udW_1(u).
\end{eqnarray*}
%
Then, since $\sigma$ is bounded, $b,\sigma\in C^{\infty}(\mathbb R)$ with all derivatives bounded, and since $Y\in\mathbb H^{\infty}$,
%
\begin{displaymath}
\sup_{r\in [0,T]}\mathbb E\left(
\sup_{u\in [r,T]}|\alpha_{\ell}(r,u) +\beta_{\ell}(r,u)|^p\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1,
\end{displaymath}
%
and for every $\ell_1,\ell_2\in\{1,2\}$, $s_1,s_2\in [0,T]$ and $t\in [s_1\vee s_2,T]$,
%
\begin{eqnarray*}
 \mathbf D_{s_2}^{\ell_2}[\alpha_{\ell_1}(s_1,t) +\beta_{\ell_1}(s_1,t)]
 & = &
 \sigma'(X_{s_1})\mathbf D_{s_2}^{\ell_2}X_{s_1}\mathbf 1_{\ell_1 = 1} +
 \int_{s_1\vee s_2}^{t}b''(Y_u)\mathbf D_{s_1}^{\ell_1}Y_u\mathbf D_{s_2}^{\ell_2}Y_udu\\
 & &
 \hspace{5cm} +
 \int_{s_1\vee s_2}^{t}b'(Y_u)\mathbf D_{s_1,s_2}^{(2),\ell_1,\ell_2}Y_udu,
\end{eqnarray*}
%
leading - together with (\ref{general_sufficient_condition_AC_3}) - to
%
\begin{displaymath}
\sup_{r_1,r_2\in [0,T]}\mathbb E\left(\sup_{u\in [r_1\vee r_2,T]}
|\mathbf D_{r_2}^{\ell_2}[\alpha_{\ell_1}(r_1,u) +\beta_{\ell_1}(r_1,u)]|^p\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1.
\end{displaymath}
%
So, since $a,\sigma\in C^{\infty}(\mathbb R)$ with all derivatives bounded, by Nualart \cite{NUALART06}, Lemma 2.2.2, for every $p\geqslant 1$ and $\ell_1,\ell_2\in\{1,2\}$,
%
\begin{displaymath}
\sup_{r_1,r_2\in [0,T]}\mathbb E\left(\sup_{u\in [r_1\vee r_2,T]}
|\mathbf D_{r_1,r_2}^{(2),\ell_1,\ell_2}X_u|^p\right) <\infty.
\end{displaymath}
%
Now, consider $k\in\mathbb N^*$ such that $\mathbf P(j)$ and $\mathbf Q(j)$ are true for every $j\in\{1,\dots,k\}$. Then, for any $\mathbf l = (\ell_1,\dots,\ell_k)\in\{1,2\}^k$, $\ell\in\{1,2\}$, $\mathbf s = (s_1,\dots,s_k)\in\mathbb [0,T]^k$, $s\in [0,T]$ and $t\in [\max(\mathbf s)\vee s,T]$,
%
\begin{eqnarray*}
 \mathbf D_{\mathbf s,s}^{(k + 1),\mathbf l,\ell}X_t
 & = &
 \mathbf D_{s}^{\ell}\alpha_{\bf l}(\mathbf s,t) +
 \mathbf D_{s}^{\ell}\beta_{\bf l}(\mathbf s,t) +
 \sigma'(X_{\max(\mathbf s)\vee s})
 \mathbf D_{\bf s}^{(k),\mathbf l}X_{\max(\mathbf s)\vee s}\\
 & &
 \hspace{0.75cm} +
 \int_{\max(\mathbf s)\vee s}^{t}
 \mathbf D_{s}^{\ell}[a'(X_u)
 \mathbf D_{\bf s}^{(k),\mathbf l}X_u]du +
 \int_{\max(\mathbf s)\vee s}^{t}
 \mathbf D_{s}^{\ell}[\sigma'(X_u)
 \mathbf D_{\bf s}^{(k),\mathbf l}X_u]dW_1(u)\\
 & = &
 A_{\mathbf s,s}^{\mathbf l,\ell}(t) + B_{\mathbf s,s}^{\mathbf l,\ell}(t) +
 \int_{\max(\mathbf s)\vee s}^{t}
 a'(X_u)\mathbf D_{\mathbf s,s}^{(k + 1),\mathbf l,\ell}X_udu\\
 & &
 \hspace{5cm} +
 \int_{\max(\mathbf s)\vee s}^{t}
 \sigma'(X_u)\mathbf D_{\bf s}^{(k + 1),\mathbf l,\ell}X_udW_1(u),
\end{eqnarray*}
%
where
%
\begin{eqnarray*}
 A_{\mathbf s,s}^{\mathbf l,\ell}(t) & := &
 \mathbf D_{s}^{\ell}\alpha_{\bf l}(\mathbf s,t) - R_{\mathbf s,s}^{\mathbf l,\ell}(t) +
 \int_{\max(\mathbf s)\vee s}^{t}
 a''(X_u)\mathbf D_{\bf s}^{(k),\mathbf l}X_u\mathbf D_{s}^{\ell}X_udu\\
 & &
 \hspace{6cm} +
 \int_{\max(\mathbf s)\vee s}^{t}
 \sigma''(X_u)\mathbf D_{\bf s}^{(k),\mathbf l}X_u\mathbf D_{s}^{\ell}X_udW_1(u)\\
 & &
 \hspace{0.5cm}{\rm with}\quad
 R_{\mathbf s,s}^{\mathbf l,\ell}(t) =\mathbf 1_{k > 1,\ell = 1}\sum_{\pi\in\Pi_{k}^{*}}
 \sigma^{(|\pi|)}(X_{\max(\mathbf s)\vee s})\prod_{J\in\pi}
 \mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\max(\mathbf s)\vee s},
\end{eqnarray*}
%
and
%
\begin{displaymath}
B_{\mathbf s,s}^{\mathbf l,\ell}(t) :=
\mathbf D_{s}^{\ell}\beta_{\bf l}(\mathbf s,t) + R_{\mathbf s,s}^{\mathbf l,\ell}(t) +
\sigma'(X_{\max(\mathbf s)\vee s})
\mathbf D_{\bf s}^{(k),\mathbf l}X_{\max(\mathbf s)\vee s}\mathbf 1_{\ell = 1}.
\end{displaymath}
%
On the one hand, note that if
%
\begin{displaymath}
{\bf (A)}\quad
A_{\mathbf s,s}^{\mathbf l,\ell}(t) =\alpha_{\mathbf l,\ell}(\mathbf s,s,t)
\quad {\rm and}\quad
{\bf (B)}\quad
B_{\mathbf s,s}^{\mathbf l,\ell}(t) =\beta_{\mathbf l,\ell}(\mathbf s,s,t),
\end{displaymath}
%
then $\mathbf P(k + 1)$ is true. So, let us establish \textbf{(A)} and \textbf{(B)}.
%
\begin{itemize}
 \item[\textbf{(A)}] For $k > 1$ and every $u\in [\max(\mathbf s)\vee s,t]$,
 %
 \begin{eqnarray*}
  & &
  \mathbf D_{s}^{\ell}\left[\sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi|)}(X_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_u\right]\\
  & &
  \hspace{3cm} =
  \sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi| + 1)}(X_u)\mathbf D_{s}^{\ell}X_u
  \prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_u\\
  & &
  \hspace{6cm} +
  \sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi|)}(X_u)\sum_{I\in\pi}\mathbf D_{\mathbf s_I,s}^{(|I| + 1),\mathbf l_I,\ell}X_u
  \prod_{J\in\pi\backslash\{I\}}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_u\\
  & &
  \hspace{3cm} =
  \sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi| + 1)}(X_u)
  \prod_{J\in\pi\cup\{\{k + 1\}\}}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u\\
  & &
  \hspace{6cm} +
  \sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi|)}(X_u)\sum_{I\in\pi}\prod_{J\in (\pi\backslash\{I\})\cup\{I\cup\{k + 1\}\}}
  \mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u\\
  & &
  \hspace{3cm} =
  \sum_{\overline\pi\in\mathcal U_{k}^{*}\cup\mathcal V_{k}^{*}}
  a^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u,
 \end{eqnarray*}
 %
 where
 %
 \begin{eqnarray*}
  \mathcal U_{k}^{*} & := &
  \{\pi\cup\{\{k + 1\}\}\textrm{ $;$ }\pi\in\Pi_{k}^{*}\}\\
  & &
  \hspace{2cm}{\rm and}\quad
  \mathcal V_{k}^{*} :=
  \{(\pi\backslash\{I\})\cup\{I\cup\{k + 1\}\}
  \textrm{ $;$ }\pi\in\Pi_{k}^{*}\textrm{, }I\in\pi\}.
 \end{eqnarray*}
 %
 Moreover, consider
 %
 \begin{eqnarray*}
  \mathcal U_k & := &
  \{\pi\cup\{\{k + 1\}\}\textrm{ $;$ }\pi\in\Pi_k\}\\
  & = &
  \mathcal U_{k}^{*}\cup\{\pi_{k,k + 1}\}
  \quad {\rm with}\quad
  \pi_{k,k + 1} =\{\{1,\dots,k\},\{k + 1\}\}.
 \end{eqnarray*}
 %
 Then,
 %
 \begin{eqnarray*}
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;a) & := &
  \int_{\max(\mathbf s)\vee s}^{t}\mathbf D_{s}^{\ell}\left[\mathbf 1_{k > 1}\sum_{\pi\in\Pi_{k}^{*}}
  a^{(|\pi|)}(X_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_u\right]du\\
  & &
  \hspace{4.5cm} +
  \int_{\max(\mathbf s)\vee s}^{t}
  a''(X_u)\mathbf D_{\bf s}^{(k),\mathbf l}X_u\mathbf D_{s}^{\ell}X_udu\\
  & = &
  \int_{\max(\mathbf s)\vee s}^{t}\left[\mathbf 1_{k > 1}
  \sum_{\overline\pi\in\mathcal U_{k}^{*}\cup\mathcal V_{k}^{*}}
  a^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u\right]du\\
  & &
  \hspace{4.5cm} +
  \int_{\max(\mathbf s)\vee s}^{t}
  a^{(|\pi_{k,k + 1}|)}(X_u)\mathbf D_{\bf s}^{(k),\mathbf l}X_u\mathbf D_{s}^{\ell}X_udu\\
  & = &
  \int_{\max(\mathbf s)\vee s}^{t}\left[
  \sum_{\overline\pi\in\mathcal U_k\cup\mathcal V_{k}^{*}}
  a^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u\right]du.
 \end{eqnarray*}
 %
 In the same way,
 %
 \begin{eqnarray*}
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;\sigma) & := &
  \int_{\max(\mathbf s)\vee s}^{t}\mathbf D_{s}^{\ell}\left[\mathbf 1_{k > 1}\sum_{\pi\in\Pi_{k}^{*}}
  \sigma^{(|\pi|)}(X_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_u\right]dW_1(u)\\
  & &
  \hspace{4.5cm} +
  \int_{\max(\mathbf s)\vee s}^{t}
  \sigma''(X_u)\mathbf D_{\bf s}^{(k),\mathbf l}X_u\mathbf D_{s}^{\ell}X_udW_1(u)\\
  & = &
  \int_{\max(\mathbf s)\vee s}^{t}\left[
  \sum_{\overline\pi\in\mathcal U_k\cup\mathcal V_{k}^{*}}
  \sigma^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_u\right]dW_1(u),
 \end{eqnarray*}
 %
 and
 %
 \begin{eqnarray*}
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;b) & := &
  \int_{\max(\mathbf s)\vee s}^{t}\mathbf D_{s}^{\ell}\left(\sum_{\pi\in\Pi_k}
  b^{(|\pi|)}(Y_u)\prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}Y_u\right)du\\
  & = &
  \int_{\max(\mathbf s)\vee s}^{t}\left(
  \sum_{\overline\pi\in\mathcal U_k\cup\mathcal V_k}
  b^{(|\overline\pi|)}(Y_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}Y_u\right)du
 \end{eqnarray*}
 %
 with
 %
 \begin{displaymath}
 \mathcal V_k =
 \{(\pi\backslash\{I\})\cup\{I\cup\{k + 1\}\}
 \textrm{ $;$ }\pi\in\Pi_k\textrm{, }I\in\pi\}.
 \end{displaymath}
 %
 Therefore, since $\Pi_{k + 1} =\mathcal U_k\cup\mathcal V_k$ and $\Pi_{k + 1}^{*} =\mathcal U_k\cup\mathcal V_{k}^{*}$,
 %
 \begin{eqnarray*}
  A_{\mathbf s,s}^{\mathbf l,\ell}(t) & = &
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;b) +
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;a) +
  A_{\mathbf s,s}^{\mathbf l,\ell}(t;\sigma)\\
  & = &
  \int_{\max(\mathbf s)\vee s}^{t}
  \sum_{\overline\pi\in\Pi_{k + 1}}
  b^{(|\overline\pi|)}(Y_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}Y_udu\\
  & &
  \hspace{1.5cm} +
  \int_{\max(\mathbf s)\vee s}^{t}
  \sum_{\overline\pi\in\Pi_{k + 1}^{*}}
  a^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_udu\\
  & &
  \hspace{3cm} +
  \int_{\max(\mathbf s)\vee s}^{t}
  \sum_{\overline\pi\in\Pi_{k + 1}^{*}}
  \sigma^{(|\overline\pi|)}(X_u)
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_udW_1(u)\\
  & = &
  \alpha_{\mathbf l,\ell}(\mathbf s,s,t).
 \end{eqnarray*}
 %
 \item[\textbf{(B)}] For the sake of simplicity, assume that $k > 2$. Then,
 %
 \begin{displaymath}
 \beta_{\bf l}(\mathbf s,t) =
 \sum_{j = 1}^{k}\beta_{\mathbf l,j}(\mathbf s,t)\mathbf 1_{\ell_j = 1}
 \end{displaymath}
 %
 where, for every $j\in\{1,\dots,k\}$,
 %
 \begin{displaymath}
 \beta_{\mathbf l,j}(\mathbf s,t) :=
 \sum_{\pi\in\Pi_{k\backslash j}}
 \sigma^{(|\pi|)}(X_{\overline{\bf s}_j})
 \prod_{J\in\pi}\mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\overline{\bf s}_j}
 \quad {\rm and}\quad
 \overline{\bf s}_j :=\max\{s_1,\dots,s_j\}.
 \end{displaymath}
 %
 By following the same line as in the proof of \textbf{(A)}, for every $j\in\{1,\dots,k\}$,
 %
 \begin{displaymath}
 \mathbf D_{s}^{\ell}\beta_{\mathbf l,j}(\mathbf s,t) =
 \sum_{\overline\pi\in\mathcal U_{k\backslash j}\cup\mathcal V_{k\backslash j}}
 \sigma^{(|\overline\pi|)}(X_{\overline{\bf s}_j})
 \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_{\overline{\bf s}_j}
 \end{displaymath}
 %
 with
 %
 \begin{eqnarray*}
  \mathcal U_{k\backslash j} & = &
  \{\pi\cup\{\{k + 1\}\}\textrm{ $;$ }\pi\in\Pi_{k\backslash j}\}\\
  & &
  \hspace{2cm}{\rm and}\quad
  \mathcal V_{k\backslash j} =
  \{(\pi\backslash\{I\})\cup\{I\cup\{k + 1\}\}
  \textrm{ $;$ }\pi\in\Pi_{k\backslash j}\textrm{, }I\in\pi\}.
 \end{eqnarray*}
 %
 Moreover,
 %
 \begin{displaymath}
 \Pi_{(k + 1)\backslash (k + 1)} =\Pi_k =\Pi_{k}^{*}\cup\{\pi_k\}
 \quad {\rm with}\quad\pi_k =\{\{1,\dots,k\}\},
 \end{displaymath}
 %
 and
 %
 \begin{displaymath}
 \Pi_{(k + 1)\backslash j} =
 \mathcal U_{k\backslash j}\cup\mathcal V_{k\backslash j}
 \textrm{ $;$ }\forall j\in\{1,\dots,k\}.
 \end{displaymath}
 %
 Therefore,
 %
 \begin{eqnarray*}
  B_{\mathbf s,s}^{\mathbf l,\ell}(t)
  & = &
  \sum_{j = 1}^{k}\mathbf 1_{\ell_j = 1}
  \sum_{\overline\pi\in\mathcal U_{k\backslash j}\cup\mathcal V_{k\backslash j}}
  \sigma^{(|\overline\pi|)}(X_{\overline{\bf s}_j})
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_{\overline{\bf s}_j}\\
  & &
  \hspace{1.5cm} +
  \mathbf 1_{\ell = 1}\sum_{\pi\in\Pi_{k}^{*}}
  \sigma^{(|\pi|)}(X_{\max(\mathbf s)\vee s})\prod_{J\in\pi}
  \mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\max(\mathbf s)\vee s}\\
  & &
  \hspace{3cm} +
  \mathbf 1_{\ell = 1}
  \sigma^{(|\pi_k|)}(X_{\max(\mathbf s)\vee s})
  \mathbf D_{\bf s}^{(k),\mathbf l}X_{\max(\mathbf s)\vee s}\\
  & = &
  \sum_{j = 1}^{k}\mathbf 1_{\ell_j = 1}
  \sum_{\overline\pi\in\Pi_{(k + 1)\backslash j}}
  \sigma^{(|\overline\pi|)}(X_{\overline{\bf s}_j})
  \prod_{J\in\overline\pi}\mathbf D_{(\mathbf s,s)_J}^{(|J|),(\mathbf l,\ell)_J}X_{\overline{\bf s}_j}\\
  & &
  \hspace{1.5cm} +
  \mathbf 1_{\ell = 1}\sum_{\pi\in\Pi_k}
  \sigma^{(|\pi|)}(X_{\max(\mathbf s)\vee s})\prod_{J\in\pi}
  \mathbf D_{\mathbf s_J}^{(|J|),\mathbf l_J}X_{\max(\mathbf s)\vee s} =
  \beta_{\mathbf l,\ell}(\mathbf s,s,t).
 \end{eqnarray*}
 %
\end{itemize}
%
On the other hand, let us show that $\mathbf Q(k + 1)$ is true. By $\mathbf Q(1),\dots,\mathbf Q(k - 1)$, since $\sigma$ is bounded, $a,b,\sigma\in C^{\infty}(\mathbb R)$ with all derivatives bounded, and since $Y\in\mathbb H^{\infty}$,
%
\begin{displaymath}
\sup_{\mathbf r\in [0,T]^{k + 1}}\mathbb E\left(
\sup_{u\in[\max(\mathbf r),T]}|\alpha_{\mathbf l,\ell}(\mathbf r,u) +
\beta_{\mathbf l,\ell}(\mathbf r,u)|^p\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1.
\end{displaymath}
%
Consider $\mathbf l_1\in\{1,2\}^{k + 1}$ and $\ell_2\in\{1,2\}$. For every $\mathbf s_1\in [0,T]^{k + 1}$, $s_2\in [0,T]$ and $t\in [\max(\mathbf s_1)\vee s_2,T]$, by following the same line as in the proofs of \textbf{(A)} and \textbf{(B)}, $\mathbf D_{s_2}^{\ell_2}\alpha_{\mathbf l_1}(\mathbf s_1,t)$ and $\mathbf D_{s_2}^{\ell_2}\beta_{\mathbf l_1}(\mathbf s_1,t)$ can be written as integrals of multilinear maps in
%
\begin{displaymath}
\mathbf D^{(1)}X,\dots,\mathbf D^{(k + 1)}X,
\mathbf D^{(1)}Y,\dots,\mathbf D^{(k + 2)}Y,\quad
\textrm{but not depending on $\mathbf D^{(k + 2)}X$.}
\end{displaymath}
%
Then, by $\mathbf Q(1),\dots,\mathbf Q(k)$, since $\sigma$ is bounded, $a,b,\sigma\in C^{\infty}(\mathbb R)$ with all derivatives bounded, and since $Y\in\mathbb H^{\infty}$,
%
\begin{displaymath}
\sup_{(\mathbf r_1,r_2)\in [0,T]^{k + 1}\times [0,T]}\mathbb E\left(
\sup_{u\in[\max(\mathbf r_1)\vee r_2,T]}
|\mathbf D_{r_2}^{\ell_2}[\alpha_{\mathbf l_1}(\mathbf r_1,u) +
\beta_{\mathbf l_1}(\mathbf r_1,u)]|^p\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1.
\end{displaymath}
%
So, by Nualart \cite{NUALART06}, Lemma 2.2.2,
%
\begin{displaymath}
\sup_{\mathbf r\in [0,T]^{k + 2}}
\mathbb E\left(\sup_{u\in [\max(\mathbf r),T]}
|\mathbf D_{\mathbf r}^{(k + 2),(\mathbf l_1,\ell_2)}X_u|^p\right) <\infty
\textrm{ $;$ }\forall p\geqslant 1.
\end{displaymath}
%
{\it Step 2.3 (conclusion).} Consider $t\in (0,T]$. By the two previous steps, and by Nualart \cite{NUALART06}, Inequality (2.32) and Proposition 2.1.5, the distribution of $(X_t,Y_t)$ has a smooth density $f_t$ with respect to the Lebesgue measure on $\mathbb R^2$, and there exist $\mathfrak c_3 > 0$ and $(m,\alpha),(N,p)\in\mathbb N^*\times (2,\infty)$, depending on $T$ but not on $t$, such that for every $(x,y)\in\mathbb R^2$,
%
\begin{eqnarray*}
 f_t(x,y)
 & \leqslant &
 \mathfrak c_3
 \mathbb E\left(\left|\frac{1}{\det(\Gamma_t)}\right|^{\alpha}\right)^{\frac{m}{\alpha}}
 \|\mathbf D(X_t,Y_t)\|_{\mathbb D^{2,p}}^{N}
 \mathbb P(|Y_t| > |y|)^{\frac{1}{2}}
 \mathbb P(|X_t - x_0| > |x - x_0|)^{\frac{1}{2}}\\
 & \leqslant &
 \frac{\mathfrak c_4\mathfrak c_2(\alpha)^{m/\alpha}}{t^m}
 \mathbb E\left(\frac{1}{\|\mathbf DY_t\|_{T}^{4\alpha}}\right)^{\frac{m}{2\alpha}}
 \Pi_t(x,y)
\end{eqnarray*}
%
with
%
\begin{eqnarray*}
 \mathfrak c_{4}^{\frac{p}{N}} & = &
 \mathfrak c_3\sum_{k = 0}^{3}\sum_{j = 1}^{p}\left[
 \sup_{r_1,\dots,r_k\in [0,T]}\mathbb E\left(
 \sup_{u\in [r_1\vee\dots\vee r_k,T]}
 \|\mathbf D_{r_1,\dots,r_k}^{(k)}X_u\|_{j,\mathbb R^{2^k}}^{j}\right)\right.\\
 & &
 \hspace{4cm}
 \left. +
 \sup_{r_1,\dots,r_k\in [0,T]}\mathbb E\left(
 \sup_{u\in [r_1\vee\dots\vee r_k,T]}
 \|\mathbf D_{r_1,\dots,r_k}^{(k)}Y_u\|_{j,\mathbb R^{2^k}}^{j}\right)\right]
 <\infty.
\end{eqnarray*}
%

% Subsection : Proof of Proposition integrability_Pi.

%
\subsection{Proof of Proposition \ref{integrability_Pi}}\label{section_proof_integrability_Pi}
The proof is dissected in two steps.
\\
\\
{\bf Step 1.} Let $M = (M_t)_{t\in [0,T]}$ be the $\mathbb F$-martingale defined by
%
\begin{displaymath}
M_t :=\int_{0}^{t}\sigma(X_s)dW_1(s)
\textrm{ $;$ }\forall t\in [0,T].
\end{displaymath}
%
Consider $t\in (0,T]$. First, since $\sigma$ is bounded,
%
\begin{displaymath}
\langle M\rangle_t =
\int_{0}^{t}\sigma(X_s)^2ds\leqslant
\|\sigma\|_{\infty}^{2}t,
\end{displaymath}
%
and since $(a,b)$ is bounded, one may consider $\gamma :=\|a\|_{\infty} +\|b\|_{\infty}$. Now, by the Bernstein inequality for local martingales (see Revuz and Yor \cite{RY99}, p. 153), for every $x\in\mathbb R$ such that $|x - x_0|\geqslant\gamma t$,
%
\begin{eqnarray*}
 \mathbb P(|X_t - x_0| > |x - x_0|) & = &
 \mathbb P\left(\langle M\rangle_t\leqslant\|\sigma\|_{\infty}^{2}t,
 \left|M_t +\int_{0}^{t}(a(X_s) + b(Y_s))ds\right| > |x - x_0|\right)\\
 & \leqslant &
 \mathbb P\left[\langle M\rangle_t\leqslant\|\sigma\|_{\infty}^{2}t,
 \sup_{s\in [0,t]}|M_s| > |x - x_0| -\gamma t\right]\\
 & \leqslant &
 2\exp\left(-\frac{(|x - x_0| -\gamma t)^2}{2\|\sigma\|_{\infty}^{2}t}\right)
 \leqslant
 2\exp\left(-\frac{(x - x_0)^2}{2\|\sigma\|_{\infty}^{2}t}
 \left(1 -\frac{2\gamma t}{|x - x_0|}\right)\right).
\end{eqnarray*}
%
So, for every $x\in\mathbb R$ such that $|x - x_0|\geqslant (2\gamma + 1)t >\gamma t$,
%
\begin{displaymath}
\mathbb P(|X_t - x_0| > |x - x_0|)\leqslant
2\exp\left(-\mathfrak c_1\frac{(x - x_0)^2}{t}\right)
\quad {\rm with}\quad
\mathfrak c_1 =\frac{1}{2(2\gamma + 1)\|\sigma\|_{\infty}^{2}},
\end{displaymath}
%
Therefore, there exist $\mathfrak c_2,\mathfrak c_3 > 0$, depending on $T$ but not on $t$, such that for every $(x,y)\in\mathbb R^2$,
%
\begin{displaymath}
\Pi_t(x,y)\leqslant
\mathfrak c_2\mathbb P(|Y_t| > |y|)^{\frac{1}{2}}
\exp\left(-\mathfrak c_3\frac{(x - x_0)^2}{t}\right).
\end{displaymath}
%
{\bf Step 2.} Under the additional condition (\ref{integrability_Pi_1}),
%
\begin{eqnarray*}
 \sup_{x\in\mathbb R}\int_{[t_0,T]\times\mathbb R}f_s(x,y)dsdy
 & \leqslant &
 \frac{\mathfrak c_{\ref{general_sufficient_condition_AC}}}{t_{0}^{m}}
 \int_{[t_0,T]\times\mathbb R}
 \mathbb E\left(\frac{1}{\|\mathbf D^2Y_s\|_{T}^{4\alpha}}\right)^{\frac{m}{2\alpha}}
 \mathbb P(|Y_s| > |y|)^{\frac{1}{2}}dsdy\\
 & \leqslant &
 \mathfrak c_{\ref{general_sufficient_condition_AC}}
 \frac{T - t_0}{t_{0}^{m}}
 \int_{-\infty}^{\infty}
 \mu_{t_0,T}(y)dy <\infty
\end{eqnarray*}
%
and, by Step 1,
%
\begin{eqnarray*}
 \sup_{y\in\mathbb R}\int_{[t_0,T]\times\mathbb R}f_s(x,y)dsdx
 & \leqslant &
 \frac{\mathfrak c_2
 \mathfrak c_{\ref{general_sufficient_condition_AC}}}{t_{0}^{m}}
 \int_{[t_0,T]\times\mathbb R}
 \mathbb E\left(\frac{1}{\|\mathbf D^2Y_s\|_{T}^{4\alpha}}\right)^{\frac{m}{2\alpha}}
 \mathbb P(|Y_s| > |y|)^{\frac{1}{2}}\\
 & &
 \hspace{5.5cm}\times
 \exp\left(-\mathfrak c_3\frac{(x - x_0)^2}{s}\right)dsdx\\
 & \leqslant &
 \mathfrak c_2
 \mathfrak c_{\ref{general_sufficient_condition_AC}}
 \frac{T - t_0}{t_{0}^{m}}\|\mu_{t_0,T}\|_{\infty}
 \int_{-\infty}^{\infty}
 \exp\left(-\mathfrak c_3\frac{x^2}{T}\right)dx <\infty.
\end{eqnarray*}
%

% Subsection : Proof of Proposition sufficient_condition_AC_diffusion.

%
\subsection{Proof of Proposition \ref{sufficient_condition_AC_diffusion}}\label{section_proof_sufficient_condition_AC_diffusion}
The process $\mathbf X = (X,Y)$ is the solution of the two-dimensional stochastic differential equation
%
\begin{equation}\label{sufficient_condition_AC_diffusion_1}
\mathbf X_t =\mathbf X_0 +
\int_{0}^{t}\Phi(\mathbf X_s)ds +
\int_{0}^{t}\Psi(\mathbf X_s)dW_s
\textrm{ $;$ }t\in [0,T]
\end{equation}
%
where, for every $(x,y)\in\mathbb R^2$,
%
\begin{displaymath}
\Phi(x,y) :=
\begin{pmatrix}
 a(x) + b(y)\\
 \mu(y)
\end{pmatrix}
\quad {\rm and}\quad
\Psi(x,y) :=
\begin{pmatrix}
 \sigma(x) & 0\\
 0 & \kappa(y)
\end{pmatrix}.
\end{displaymath}
%
For every $\mathbf x,\mathbf v\in\mathbb R^2$,
%
\begin{eqnarray*}
 \langle\Psi(\mathbf x)\Psi(\mathbf x)^*\mathbf v,\mathbf v\rangle_{2,\mathbb R^2}
 & = &
 \mathbf v^*\Psi(\mathbf x)^2\mathbf v\\
 & = &
 \|\Psi(\mathbf x)\mathbf v\|_{2,\mathbb R^2}^{2} =
 (\sigma(\mathbf x_1)\mathbf v_1)^2 +
 (\kappa(\mathbf x_2)\mathbf v_2)^2,
\end{eqnarray*}
%
leading to
%
\begin{displaymath}
m^2\|\mathbf v\|_{2,\mathbb R^2}^{2}\leqslant
\langle\Psi(\mathbf x)\Psi(\mathbf x)^*\mathbf v,\mathbf v\rangle_{2,\mathbb R^2}
\leqslant
(\|\sigma\|_{\infty}\vee\|\kappa\|_{\infty})^2\|\mathbf v\|_{2,\mathbb R^2}^{2}
\end{displaymath}
%
with
%
\begin{displaymath}
m =\left(\inf_{x\in\mathbb R}|\sigma(x)|\right)\wedge
\left(\inf_{y\in\mathbb R}|\kappa(y)|\right) > 0.
\end{displaymath}
%
Then, $\Psi$ satisfies the non-degeneracy condition (1.5) in Menozzi et al. \cite{MPZ21}. Since, in addition, $\Phi :\mathbb R^2\rightarrow\mathbb R^2$ and $\Psi :\mathbb R^2\rightarrow\mathcal M_2(\mathbb R)$ are Lipschitz continuous maps, $Y$ and $(X,Y)$ fulfill Assumptions \ref{assumption_Y} and \ref{assumption_XY}, and satisfy (\ref{integrability_Pi_2}), by Menozzi et al. \cite{MPZ21}, Theorem 1.2.
%

