%
\section{Proofs of statistical results (Section \ref{section_projection_LSE})}\label{section_proofs_statistical_results}
%

% Subsection : Proof of Lemma bound_Omega.

%
\subsection{Proof of Lemma \ref{bound_Omega}}\label{section_proof_bound_Omega}
The proof of Lemma \ref{bound_Omega} relies on the following matrix Chernov's inequality.
%

% Proposition : Matrix Chernov's inequality.

%
\begin{proposition}\label{matrix_Chernov_inequality}
Let $\mathbb X$ be a $d\times d$ positive semidefinite symmetric random matrix such that $\lambda_{\max}(\mathbb X)\leqslant R$ a.s, where $d\in\mathbb N^*$ and $R > 0$ is a deterministic constant. Consider $\mathbb G :=\mathbb X_1 +\dots +\mathbb X_n$, $\mu_{\min} :=\lambda_{\min}(\mathbb E(\mathbb G))$ and $\mu_{\max} :=\lambda_{\max}(\mathbb E(\mathbb G))$, where $n\in\mathbb N^*$ and $\mathbb X_1,\dots,\mathbb X_n$ are independent copies of $\mathbb X$. Then,
%
\begin{displaymath}
\mathbb P(
\lambda_{\min}(\mathbb G)
\leqslant (1 -\delta)\mu_{\min})
\leqslant d\left(\frac{e^{-\delta}}{(1 -\delta)^{1 -\delta}}
\right)^{\frac{\mu_{\min}}{R}}
\textrm{$;$ }\forall\delta\in [0,1],
\end{displaymath}
%
and
%
\begin{displaymath}
\mathbb P(\lambda_{\max}(\mathbb G)\geqslant (1 +\delta)\mu_{\max})
\leqslant d\left(\frac{e^{\delta}}{(1 +\delta)^{1 +\delta}}
\right)^{\frac{\mu_{\max}}{R}}
\textrm{$;$ }\forall\delta\geqslant 0.
\end{displaymath}
%
\end{proposition}
%
\noindent
See Tropp \cite{TROPP12}, Theorem 1.1 for a proof.
\\
\\
Note that
%
\begin{displaymath}
\Omega_{\bf m} =
\left\{\|\mathbb G - I_{m_1 + m_2}\|_{\rm op}\leqslant\frac{1}{2}\right\},
\end{displaymath}
%
where $\mathbb G :=\mathbb X_1 +\dots +\mathbb X_N$ with, for every $i\in\{1,\dots,N\}$,
%
\begin{displaymath}
\mathbb X_i =
\frac{1}{N}\Psi_{\bf m}^{-\frac{1}{2}}\mathbb X_{i}^{0}\Psi_{\bf m}^{-\frac{1}{2}}
\end{displaymath}
%
and
%
\begin{displaymath}
\mathbb X_{i}^{0} =
\begin{bmatrix}
 \displaystyle{\left(\frac{1}{T_0}\int_{t_0}^{T}
 \varphi_j(X_{s}^{i})\varphi_{j'}(X_{s}^{i})ds\right)_{j,j'}} &
 \displaystyle{\left(\frac{1}{T_0}\int_{t_0}^{T}
 \varphi_j(X_{s}^{i})\psi_k(Y_{s}^{i})ds\right)_{j,k}}\\
 \displaystyle{\left(\frac{1}{T_0}\int_{t_0}^{T}
 \varphi_j(X_{s}^{i})\psi_k(Y_{s}^{i})ds\right)_{k,j}} &
 \displaystyle{\left(\frac{1}{T_0}\int_{t_0}^{T}
 \psi_k(Y_{s}^{i})\psi_{k'}(Y_{s}^{i})ds\right)_{k,k'}}
\end{bmatrix}.
\end{displaymath}
%
In order to prove Lemma \ref{bound_Omega} by applying Proposition \ref{matrix_Chernov_inequality} to $\mathbb G$, let us determine $\mu_{\min}$, $\mu_{\max}$ and $R$. First, since the $\mathbb X_i$'s are i.i.d. positive semidefinite symmetric matrices such that $\mathbb E(\mathbb X_i) = N^{-1}I_{m_1 + m_2}$ for every $i\in\{1,\dots,N\}$, $\mu_{\min} =\mu_{\max} = 1$. Now, for every $i\in\{1,\dots,N\}$ and $\mathbf x\in\mathbb R^{m_1 + m_2}$, by setting $\mathbf y =\Psi_{\bf m}^{-1/2}\mathbf x$,
%
\begin{eqnarray*}
 \mathbf x^*\mathbb X_i\mathbf x
 & = &
 \frac{1}{NT_0}\int_{t_0}^{T}\left(
 \sum_{j = 1}^{m_1}y_j\varphi_j(X_{s}^{i}) +
 \sum_{k = 1}^{m_2}y_{m_1 + k}\psi_k(Y_{s}^{i})\right)^2ds\\
 & \leqslant &
 \frac{1}{NT_0}\underbrace{\left(\sum_{j = 1}^{m_1 + m_2}y_{j}^{2}\right)}_{=\|\mathbf y\|^2}
 \int_{t_0}^{T}\underbrace{\left(\sum_{j = 1}^{m_1}\varphi_j(X_{s}^{i})^{2} +
 \sum_{k = 1}^{m_2}
 \psi_k(Y_{s}^{i})^{2}\right)}_{\leqslant\mathfrak L_{\varphi}(m_1) +\mathfrak L_{\psi}(m_2)}ds
 \leqslant
 R\|\mathbf x\|^2
\end{eqnarray*}
%
with
%
\begin{displaymath}
R =
\frac{1}{N}\|\Psi_{\bf m}^{-1}\|_{\rm op}
(\mathfrak L_{\varphi}(m_1) +\mathfrak L_{\psi}(m_2)).
\end{displaymath}
%
Then, for every $i\in\{1,\dots,N\}$,
%
\begin{displaymath}
\lambda_{\max}(\mathbb X_i) =
\sup_{\|\mathbf x\|_{2,\mathbb R^{m_1 + m_2}} = 1}\mathbf x^*\mathbb X_i\mathbf x\leqslant R.
\end{displaymath}
%
So, by Proposition \ref{matrix_Chernov_inequality}, for every $\delta\in (0,1)$,
%
\begin{eqnarray}
 \mathbb P(\|\mathbb G - I_{m_1 + m_2}\|_{\rm op} >\delta)
 & \leqslant &
 \mathbb P(\lambda_{\min}(\mathbb G)\leqslant 1 -\delta) +
 \mathbb P(\lambda_{\max}(\mathbb G)\geqslant 1 +\delta)
 \nonumber\\
 \label{bound_Omega_1}
 & \leqslant &
 2(m_1 + m_2)\left(
 \frac{e^{-\delta}}{(1 -\delta)^{1 -\delta}}\right)^{\frac{1}{R}}.
\end{eqnarray}
%
In conclusion, by Inequality (\ref{bound_Omega_1}) with $\delta = 1/2$, and by Assumption \ref{stability_condition},
%
\begin{eqnarray*}
 \mathbb P(\Omega_{\bf m}^{c}) & = &
 \mathbb P\left(\|\mathbb G - I_{m_1 + m_2}\|_{\rm op} >\frac{1}{2}\right)\\
 & \leqslant &
 2(m_1 + m_2)(2^{\frac{1}{2}}e^{-\frac{1}{2}})^{\frac{1}{R}} =
 2(m_1 + m_2)\exp\left(-\frac{1}{2R}(1 -\log(2))\right)\\
 & \leqslant &
 2(m_1 + m_2)\exp\left(-\frac{\log(N)}{\mathfrak c_r}(1 -\log(2))\right) =
 \frac{2(m_1 + m_2)}{N^{r + 1}}.
\end{eqnarray*}
%

% Subsection : Proof of Proposition nonadaptive_risk_bound.

%
\subsection{Proof of Proposition \ref{nonadaptive_risk_bound}}\label{section_proof_nonadaptive_risk_bound}
First of all, one can show that
%
\begin{displaymath}
\Omega_{\bf m} =
\left\{\left|\frac{\|(\tau,\nu)\|_{N}^{2}}{\|(\tau,\nu)\|_{f}^{2}} - 1\right|\leqslant\frac{1}{2}\textrm{ $;$ }
\forall (\tau,\nu)\in S_{m_1}\times\Sigma_{m_2}\right\}
\end{displaymath}
%
by following the same line as Comte and Genon-Catalot in the beginning of the proof of \cite{CGC20}, Proposition 2.1, and that there exists a constant $\mathfrak c_1 > 0$, not depending on $\mathbf m$ and $N$, such that
%
\begin{equation}\label{nonadaptive_risk_bound_2}
\mathbb P(\Lambda_{\bf m}^{c})\leqslant
\mathbb P(\Omega_{\bf m}^{c})\leqslant
\frac{\mathfrak c_1}{N^r}
\end{equation}
%
with the same arguments as in the proof of \cite{CGC20}, Lemma 6.1. Note also that
%
\begin{equation}\label{nonadaptive_risk_bound_3}
\widehat{\bf Z}_{\bf m} =
\begin{pmatrix}
 (\langle (\varphi_j,0),(a,b)\rangle_N)_j\\
 (\langle (0,\psi_k),(a,b)\rangle_N)_k
\end{pmatrix}
+\mathbf E_{\bf m}
\quad {\rm with}\quad
\mathbf E_{\bf m} =
\begin{pmatrix}
 (\zeta_N(\varphi_j,0))_j\\
 (\zeta_N(0,\psi_k))_k
\end{pmatrix},
\end{equation}
%
where $\zeta_N$ is the centered empirical process defined by
%
\begin{displaymath}
\zeta_N(\tau,\nu) :=
\frac{1}{NT_0}\sum_{i = 1}^{N}\int_{t_0}^{T}
(\tau(X_{s}^{i}) +\nu(Y_{s}^{i}))\sigma(X_{s}^{i})dW_{1}^{i}(s),
\end{displaymath}
%
and $\langle .,.\rangle_N$ is the empirical inner product defined by
%
\begin{equation}\label{nonadaptive_risk_bound_4}
\langle (\tau_1,\nu_1),(\tau_2,\nu_2)\rangle_N :=
\frac{1}{NT_0}\sum_{i = 1}^{N}\int_{t_0}^{T}
(\tau_1(X_{s}^{i}) +\nu_1(Y_{s}^{i}))
(\tau_2(X_{s}^{i}) +\nu_2(Y_{s}^{i}))ds.
\end{equation}
%
To conclude these preliminaries, let us provide a suitable control of the second order moment of $\mathbf E_{\bf m}\mathbf 1_{\Omega_{\bf m}^{c}}$.
%

% Lemma : Control of the second order moment of E.

%
\begin{lemma}\label{2nd_order_moment_E}
Under the assumptions of Proposition \ref{nonadaptive_risk_bound}, there exists a constant $\mathfrak c_{\ref{2nd_order_moment_E}} > 0$, not depending on $\mathbf m$ and $N$, such that
%
\begin{displaymath}
\mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}\mathbf 1_{\Omega_{\bf m}^{c}})
\leqslant
\frac{\mathfrak c_{\ref{2nd_order_moment_E}}}{N^{(r - 1)/2}}.
\end{displaymath}
%
\end{lemma}
%
\noindent
The proof of Lemma \ref{2nd_order_moment_E} is postponed to Section \ref{section_proof_2nd_order_moment_E}.
%

% Subsubsection : Steps of the proof.

%
\subsubsection{Steps of the proof}
The proof of Proposition \ref{nonadaptive_risk_bound} is dissected in two steps.
\\
\\
{\bf Step 1.} Let $(a_{m_1}^{N},b_{m_2}^{N})$ be the minimizer of $(u,v)\mapsto \|(u,v) - (a,b)\mathbf 1_A\|_{N}^{2}$ over $\mathcal S_{\bf m}$. Precisely,
%
\begin{displaymath}
a_{m_1}^{N} =\sum_{j = 1}^{m_1}\theta_{j}^{N}\varphi_j
\quad {\rm and}\quad
b_{m_2}^{N} =\sum_{k = 1}^{m_2}\theta_{m_1 + k}^{N}\psi_k
\end{displaymath}
%
with
%
\begin{equation}\label{nonadaptive_risk_bound_5}
\theta^N =
\underset{\theta\in\mathbb R^{m_1 + m_2} : h(\theta) = 0}{\rm argmin}\mathbb J_N(\theta),
\end{equation}
%
where
%
\begin{displaymath}
\mathbb J_N(\theta) :=
\frac{1}{NT_0}\sum_{i = 1}^{N}\int_{t_0}^{T}\left(
\sum_{j = 1}^{m_1}\theta_j\varphi_j(X_{s}^{i}) - (a\mathbf 1_{A_1})(X_{s}^{i}) +
\sum_{k = 1}^{m_2}\theta_{m_1 + k}\psi_k(Y_{s}^{i}) - (b\mathbf 1_{A_2})(Y_{s}^{i})\right)^2ds.
\end{displaymath}
%
Consider
%
\begin{displaymath}
\mathbf Z_{\bf m} =
\begin{pmatrix}
 (\langle (\varphi_j,0),(a,b)\rangle_N)_j\\
 (\langle (0,\psi_k),(a,b)\rangle_N)_k
\end{pmatrix},
\end{displaymath}
%
and let $\mathbb L_N$ be the Lagrangian for Problem (\ref{nonadaptive_risk_bound_5}):
%
\begin{displaymath}
\mathbb L_N(\theta,\lambda) :=
\mathbb J_N(\theta) -\lambda h(\theta)\textrm{ $;$ }
(\theta,\lambda)\in\mathbb R^{m_1 + m_2}\times\mathbb R.
\end{displaymath}
%
Necessarily,
%
\begin{displaymath}
\nabla\mathbb L_N(\theta^N,\lambda^N) =
\begin{pmatrix}
 2(\widehat\Psi_{\bf m}\theta^N -
 \mathbf Z_{\bf m}) -\lambda^N\mathbf d_{\bf m}\\
 -h(\theta^N)
\end{pmatrix} = 0,
\end{displaymath}
%
leading to
%
\begin{displaymath}
\theta^N =
\widehat\Psi_{\bf m}^{-1}\left(\mathbf Z_{\bf m} +
\frac{\lambda^N}{2}\mathbf d_{\bf m}\right),
\quad\textrm{and then}\quad
\lambda^N =
-2\cdot\frac{\langle
\widehat\Psi_{\bf m}^{-1}\mathbf Z_{\bf m},
\mathbf d_{\bf m}\rangle_{2,\mathbb R^{m_1 + m_2}}}{
\langle
\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m},\mathbf d_{\bf m}
\rangle_{2,\mathbb R^{m_1 + m_2}}}.
\end{displaymath}
%
So,
%
\begin{displaymath}
\theta^N =
\widehat\Psi_{\bf m}^{-1}\mathbf Z_{\bf m} -
\frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf Z_{\bf m}}{
\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\cdot
\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}.
\end{displaymath}
%
{\bf Step 2.} First, for any $(\tau,\nu)\in\mathcal S_{\bf m}$ and $t\in (0,1)$, since $t(\tau,\nu) + (1 - t)(a_{m_1}^{N},b_{m_2}^{N})$ belongs to $\mathcal S_{\bf m}$,
%
\begin{eqnarray*}
 \|(a_{m_1}^{N},b_{m_2}^{N}) - (a,b)\mathbf 1_A\|_{N}^{2}
 & \leqslant &
 \|t((\tau,\nu) - (a_{m_1}^{N},b_{m_2}^{N})) +
 (a_{m_1}^{N},b_{m_2}^{N}) - (a,b)\mathbf 1_A\|_{N}^{2}\\
 & = &
 t^2\|(\tau,\nu) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}\\
 & &
 \hspace{1cm} -
 2t\langle (\tau,\nu) - (a_{m_1}^{N},b_{m_2}^{N}),
 (a,b)\mathbf 1_A - (a_{m_1}^{N},b_{m_2}^{N})\rangle_N\\
 & &
 \hspace{1cm} +
 \|(a_{m_1}^{N},b_{m_2}^{N}) - (a,b)\mathbf 1_A\|_{N}^{2}.
\end{eqnarray*}
%
Then,
%
\begin{equation}\label{nonadaptive_risk_bound_6}
\langle (\tau,\nu) - (a_{m_1}^{N},b_{m_2}^{N}),
(a,b)\mathbf 1_A - (a_{m_1}^{N},b_{m_2}^{N})\rangle_N\leqslant
\frac{t}{2}\|(\tau,\nu) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}
\xrightarrow[t\rightarrow 0]{} 0.
\end{equation}
%
By applying Inequality (\ref{nonadaptive_risk_bound_6}) to $(\tau,\nu) = (\widehat a_{m_1},\widehat b_{m_2})$ and to $(\tau,\nu) = 2(a_{m_1}^{N},b_{m_2}^{N}) - (\widehat a_{m_1},\widehat b_{m_2})$,
%
\begin{displaymath}
\langle
(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N}),
(a,b)\mathbf 1_A - (a_{m_1}^{N},b_{m_2}^{N})\rangle_N = 0.
\end{displaymath}
%
So,
%
\begin{displaymath}
\|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2} =
\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{N}^{2} +
\|(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2},
\end{displaymath}
%
leading to
%
\begin{eqnarray*}
 \mathbb E(\|(\widetilde a_{m_1},\widetilde b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2})
 & \leqslant &
 \mathbb E\left(\min_{(\tau,\nu)\in\mathcal S_{\bf m}}
 \|(\tau,\nu) - (a,b)\mathbf 1_A\|_{N}^{2}\right)\\
 & &
 \hspace{0.5cm} +
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}
 \mathbf 1_{\Lambda_{\bf m}\cap\Omega_{\bf m}})\\
 & &
 \hspace{0.5cm} +
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}
 \mathbf 1_{\Lambda_{\bf m}\cap\Omega_{\bf m}^{c}}) +
 \mathbb E(\|(a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Lambda_{\bf m}^{c}})\\
 & =: &
 \min_{(\tau,\nu)\in\mathcal S_{\bf m}}
 \|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} + V + R_1 + R_2.
\end{eqnarray*}
%
Now, let us control the variance term $V$ and the remainder terms $R_1$ and $R_2$.
%
\begin{itemize}
 \item {\bf Control of $V$.} By Equality (\ref{nonadaptive_risk_bound_3}), $\widehat{\bf Z}_{\bf m} -\mathbf Z_{\bf m} =\mathbf E_{\bf m}$, leading to
 %
 \begin{displaymath}
 (\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N}) =
 \left(\sum_{j = 1}^{m_1}\delta_j\varphi_j,\sum_{k = 1}^{m_2}\delta_{m_1 + k}\psi_k\right)
 \quad {\rm with}\quad
 \delta =\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m} -
 \frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m}}{
 \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}
 \widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m},
 \end{displaymath}
 %
 and then
 %
 \begin{eqnarray}
  \|(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}
  & = &
  \frac{1}{NT_0}\sum_{i = 1}^{N}\int_{t_0}^{T}
  \left(\sum_{j = 1}^{m_1}\delta_j\varphi_j(X_{s}^{i}) +
  \sum_{k = 1}^{m_2}\delta_{m_1 + k}\psi_k(Y_{s}^{i})\right)^2ds
  \nonumber\\
  & = &
  \delta^*\widehat\Psi_{\bf m}\delta
  \nonumber\\
  & = &
  \mathbf E_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m} -
  \frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}
  (\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m} +
  \mathbf E_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m})
  \nonumber\\
  & &
  \hspace{4.25cm} +
  \left(\frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\right)^2
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}
  \nonumber\\
  \label{nonadaptive_risk_bound_6}
  & = &
  \mathbf E_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m} -
  \frac{(\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m})^2}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}
  \leqslant
  \mathbf E_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m}.
 \end{eqnarray}
 %
 Moreover, on $\Omega_{\bf m}$,
 %
 \begin{displaymath}
 \mathbf E_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf E_{\bf m}\leqslant
 2\mathbf E_{\bf m}^{*}\Psi_{\bf m}^{-1}\mathbf E_{\bf m}.
 \end{displaymath}
 %
 Then,
 %
 \begin{displaymath}
 V\leqslant 2\mathbb E(
 \mathbf E_{\bf m}^{*}\Psi_{\bf m}^{-1}\mathbf E_{\bf m}) =
 \frac{2}{NT_0}{\rm Tr}(\Psi_{\bf m}^{-1}\Psi_{\bf m}^{\sigma}),
 \end{displaymath}
 %
 where
 %
 \begin{displaymath}
 \Psi_{\bf m}^{\sigma} :=
 \begin{pmatrix}
  \Psi_{1,1}^{\sigma} & \Psi_{1,2}^{\sigma}\\
  \Psi_{1,2}^{\sigma,*} & \Psi_{2,2}^{\sigma}
 \end{pmatrix}
 \end{displaymath}
 %
 with
 %
 \begin{eqnarray*}
  \Psi_{1,1}^{\sigma} & = &
  \left(\int_{\mathbb R}
  \varphi_j(x)\varphi_{j'}(x)\sigma(x)^2f_X(x)dx\right)_{1\leqslant j,j'\leqslant m_1},\\
  \Psi_{2,2}^{\sigma} & = &
  \left(\int_{\mathbb R^2}
  \psi_k(y)\psi_{k'}(y)\sigma(x)^2f(x,y)dxdy\right)_{1\leqslant k,k'\leqslant m_2}\quad {\rm and}\\
  \Psi_{1,2}^{\sigma} & = &
  \left(\int_{\mathbb R^2}
  \varphi_j(x)\psi_k(y)\sigma(x)^2f(x,y)dxdy\right)_{(j,k)\in\{1,\dots,m_1\}\times\{1,\dots,m_2\}}.
 \end{eqnarray*}
 %
 Therefore, by following the same line as in the proof of Comte and Genon-Catalot \cite{CGC20}, Proposition 2.2,
 %
 \begin{displaymath}
 V\leqslant
 \frac{2\|\sigma\|_{\infty}^{2}}{T_0}\cdot\frac{m_1 + m_2}{N}.
 \end{displaymath}
 %
 \item {\bf Control of $R_1$.} By Inequality (\ref{nonadaptive_risk_bound_6}), on $\Lambda_{\bf m}$,
 %
 \begin{displaymath}
 \|(\widehat a_{m_1},\widehat b_{m_2}) - (a_{m_1}^{N},b_{m_2}^{N})\|_{N}^{2}
 \leqslant
 \|\widehat\Psi_{\bf m}^{-1}\|_{\rm op}\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}
 \leqslant
 \mathfrak c_rN\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}.
 \end{displaymath}
 %
 Then, by Lemma \ref{2nd_order_moment_E},
 %
 \begin{displaymath}
 R_1\leqslant
 \mathfrak c_rN\mathbb E(
 \|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}\mathbf 1_{\Omega_{\bf m}^{c}})
 \leqslant
 \frac{\mathfrak c_r\mathfrak c_{\ref{2nd_order_moment_E}}}{N^{(r - 3)/2}}.
 \end{displaymath}
 %
 \item {\bf Control of $R_2$.} Since $a + b\in\mathbb L^4(A,f(x,y)dxdy)$,
 %
 \begin{displaymath}
 \mathbb E(\|(a,b)\mathbf 1_A\|_{N}^{4})
 \leqslant
 \int_A(a(x) + b(y))^4f(x,y)dxdy <\infty
 \end{displaymath}
 %
 and then, by Inequality (\ref{nonadaptive_risk_bound_2}),
 %
 \begin{displaymath}
 R_2\leqslant
 \mathbb E(\|(a,b)\mathbf 1_A\|_{N}^{4})^{\frac{1}{2}}\mathbb P(\Lambda_{\bf m}^{c})
 \leqslant
 \mathfrak c_{1}^{\frac{1}{2}}\|(a + b)^2\mathbf 1_A\|_f\frac{1}{N^{r/2}}.
 \end{displaymath}
 %
\end{itemize}
%
Since $r\geqslant 5$, gathering these controls of $V$, $R_1$ and $R_2$ gives Inequality (\ref{nonadaptive_risk_bound_1}).
%

% Subsubsection : Proof of Lemma 2nd_order_moment_E.

%
\subsubsection{Proof of Lemma \ref{2nd_order_moment_E}}\label{section_proof_2nd_order_moment_E}
First,
%
\begin{equation}\label{2nd_order_moment_E_1}
\mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}\mathbf 1_{\Omega_{\bf m}^{c}})
\leqslant
\mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4})^{\frac{1}{2}}
\mathbb P(\Omega_{\bf m}^{c})^{\frac{1}{2}},
\end{equation}
%
and
%
\begin{eqnarray*}
 \mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4})
 & = &
 \mathbb E\left[\left(
 \sum_{j = 1}^{m_1}\zeta_N(\varphi_j,0)^2 +
 \sum_{k = 1}^{m_2}\zeta_N(0,\psi_k)^2
 \right)^2\right]\\
 & = &
 \frac{1}{(NT_0)^4}\mathbb E\left[\left(
 \sum_{j = 1}^{m_1}M_j(T)^2 +
 \sum_{k = 1}^{m_2}N_k(T)^2
 \right)^2\right]\\
 & \leqslant &
 \frac{2}{(NT_0)^4}\left(
 m_1\sum_{j = 1}^{m_1}\mathbb E(M_j(T)^4) +
 m_2\sum_{k = 1}^{m_2}\mathbb E(N_k(T)^4)\right)
\end{eqnarray*}
%
where, for every $j\in\{1,\dots,m_1\}$ and $k\in\{1,\dots,m_2\}$, $M_j$ and $N_k$ are the $\mathbb F$-martingales defined by
%
\begin{eqnarray*}
 M_j(s) & := &
 \sum_{i = 1}^{N}\int_{t_0}^{s}
 \varphi_j(X_{u}^{i})\sigma(X_{u}^{i})dW_{1}^{i}(u)\\
 & &
 \hspace{1.5cm}
 \quad {\rm and}\quad
 N_k(s) :=
 \sum_{i = 1}^{N}\int_{t_0}^{s}
 \psi_k(Y_{u}^{i})\sigma(X_{u}^{i})dW_{1}^{i}(u)
 \textrm{ $;$ }\forall s\in [t_0,T].
\end{eqnarray*}
%
Now, by the Burkholder-Davis-Gundy and Jensen's inequalities, there exists a constant $\mathfrak c_1 > 0$, not depending on $\mathbf m$ and $N$, such that for every $j\in\{1,\dots,m_1\}$ and $k\in\{1,\dots,m_2\}$,
%
\begin{eqnarray*}
 \mathbb E(M_j(T)^4)
 & \leqslant &
 \mathfrak c_1\mathbb E\left[\left(\sum_{i = 1}^{N}\int_{t_0}^{T}
 \varphi_j(X_{u}^{i})^2\sigma(X_{u}^{i})^2du\right)^2\right]\\
 & \leqslant &
 \mathfrak c_1N^2T_0\int_{t_0}^{T}\mathbb E(\varphi_j(X_u)^4\sigma(X_u)^4)du
\end{eqnarray*}
%
and
%
\begin{eqnarray*}
 \mathbb E(N_k(T)^4)
 & \leqslant &
 \mathfrak c_1\mathbb E\left[\left(\sum_{i = 1}^{N}\int_{t_0}^{T}
 \psi_k(Y_{u}^{i})^2\sigma(X_{u}^{i})^2du\right)^2\right]\\
 & \leqslant &
 \mathfrak c_1N^2T_0\int_{t_0}^{T}\mathbb E(\psi_k(Y_u)^4\sigma(X_u)^4)du.
\end{eqnarray*}
%
Therefore,
%
\begin{eqnarray}
 \mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4})
 & \leqslant &
 \frac{2\mathfrak c_1}{N^2T_{0}^{3}}\left(
 m_1\sum_{j = 1}^{m_1}\int_{t_0}^{T}\mathbb E(\varphi_j(X_u)^4\sigma(X_u)^4)du +
 m_2\sum_{k = 1}^{m_2}\int_{t_0}^{T}\mathbb E(\psi_k(Y_u)^4\sigma(X_u)^4)du\right)
 \nonumber\\
 & \leqslant &
 \frac{2\mathfrak c_1}{N^2T_{0}^{2}}
 (m_1\mathfrak L_{\varphi}(m_1)^2 + m_2\mathfrak L_{\psi}(m_2)^2)
 \nonumber\\
 \label{2nd_order_moment_E_2}
 & &
 \hspace{3.5cm}
 \times\int_{-\infty}^{\infty}\sigma(x)^4f_X(x)dx
 \quad {\rm with}\quad
 f_X(.) =\int_{-\infty}^{\infty}f(.,y)dy.
\end{eqnarray}
%
The conclusion follows from Inequalities (\ref{2nd_order_moment_E_1}) and (\ref{2nd_order_moment_E_2}), Assumption \ref{stability_condition} and Lemma \ref{bound_Omega}.
%

% Subsection : Proof of Proposition nonadaptive_risk_bound_f_weighted.

%
\subsection{Proof of Proposition \ref{nonadaptive_risk_bound_f_weighted}}\label{section_proof_nonadaptive_risk_bound_f_weighted}
First,
%
\begin{eqnarray}
 \label{nonadaptive_risk_bound_f_weighted_2}
 \mathbb E(\|(\widetilde a_{m_1},\widetilde b_{m_2}) - (a,b)\mathbf 1_A\|_{f}^{2})
 & = &
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{f}^{2}
 \mathbf 1_{\Lambda_{\bf m}}) +
 \mathbb E(\|(a,b)\mathbf 1_A\|_{f}^{2}\mathbf 1_{\Lambda_{\bf m}^{c}})\\
 & =: &
 \mathbb T +\mathbb S.
 \nonumber
\end{eqnarray}
%
Since $a + b\in\mathbb L^4(A,f(x,y)dxdy)$, and by Inequality (\ref{nonadaptive_risk_bound_2}), there exists a constant $\mathfrak c_1 > 0$, not depending on $\mathbf m$ and $N$, such that
%
\begin{displaymath}
\mathbb S =
\|(a,b)\mathbf 1_A\|_{f}^{2}\mathbb P(\Lambda_{\bf m}^{c})\leqslant
\frac{\mathfrak c_1}{N}.
\end{displaymath}
%
Let $(a_{m_1}^{f},b_{m_2}^{f})$ be the minimizer of $(u,v)\mapsto\|(u,v) - (a,b)\mathbf 1_A\|_{f}^{2}$ over $\mathcal S_{\bf m}$. By following the same line as in the proof of Proposition \ref{nonadaptive_risk_bound} (see the beginning of Step 2),
%
\begin{displaymath}
\mathbb T =
\min_{(\tau,\nu)\in\mathcal S_{\bf m}}
\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
(a_{m_1}^{f},b_{m_2}^{f})\|_{f}^{2}\mathbf 1_{\Lambda_{\bf m}}).
\end{displaymath}
%
Now, note that
%
\begin{eqnarray*}
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
 (a_{m_1}^{f},b_{m_2}^{f})\|_{f}^{2}\mathbf 1_{\Lambda_{\bf m}})
 & = &
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
 (a_{m_1}^{f},b_{m_2}^{f})\|_{f}^{2}\mathbf 1_{\Omega_{\bf m}\cap\Lambda_{\bf m}})\\
 & &
 \hspace{2cm} +
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
 (a_{m_1}^{f},b_{m_2}^{f})\|_{f}^{2}\mathbf 1_{\Omega_{\bf m}^{c}\cap\Lambda_{\bf m}})\\
 & =: &
 \mathbb T_1 +\mathbb T_2,
\end{eqnarray*}
%
and let us provide suitable controls of $\mathbb T_1$ and $\mathbb T_2$.
%
\begin{itemize}
 \item {\bf Control of $\mathbb T_1$.} By the definition of $\Omega_{\bf m}$, and by Proposition \ref{nonadaptive_risk_bound},
 %
 \begin{eqnarray*}
  \mathbb T_1 & \leqslant &
  2\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
  (a_{m_1}^{f},b_{m_2}^{f})\|_{N}^{2}\mathbf 1_{\Omega_{\bf m}\cap\Lambda_{\bf m}})\\
  & \leqslant &
  4\left(\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
  \frac{2\|\sigma\|_{\infty}^{2}}{T_0}\cdot\frac{m_1 + m_2}{N} +
  \frac{\mathfrak c_{\ref{nonadaptive_risk_bound}}}{N}\right) +
  4\mathbb E(\|(a_{m_1}^{f},b_{m_2}^{f}) - (a,b)\mathbf 1_A\|_{N}^{2}).
 \end{eqnarray*}
 %
 Moreover,
 %
 \begin{displaymath}
 \mathbb E(\|(a_{m_1}^{f},b_{m_2}^{f}) - (a,b)\mathbf 1_A\|_{N}^{2}) =
 \|(a_{m_1}^{f},b_{m_2}^{f}) - (a,b)\mathbf 1_A\|_{f}^{2},
 \end{displaymath}
 %
 leading to
 %
 \begin{equation}\label{nonadaptive_risk_bound_f_weighted_3}
 \mathbb T_1\leqslant
 8\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
 \frac{8\|\sigma\|_{\infty}^{2}}{T_0}\cdot\frac{m_1 + m_2}{N} +
 \frac{4\mathfrak c_{\ref{nonadaptive_risk_bound}}}{N}.
 \end{equation}
 %
 \item {\bf Control of $\mathbb T_2$.} By Lemma \ref{bound_Omega},
 %
 \begin{displaymath}
 \|(a_{m_1},b_{m_2})\|_{f}^{2}\mathbb P(\Omega_{\bf m}^{c})
 \leqslant
 2\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
 2\mathfrak c_{\ref{bound_Omega}}\|(a,b)\mathbf 1_A\|_{f}^{2}\frac{1}{N},
 \end{displaymath}
 %
 leading to
 %
 \begin{eqnarray*}
  \mathbb T_2
  & \leqslant &
  2\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{2}
  \mathbf 1_{\Omega_{\bf m}^{c}\cap\Lambda_{\bf m}}) +
  2\|(a_{m_1},b_{m_2})\|_{f}^{2}\mathbb P(\Omega_{\bf m}^{c})\\
  & \leqslant &
  4\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
  2\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{4}
  \mathbf 1_{\Lambda_{\bf m}})^{\frac{1}{2}}\mathbb P(\Omega_{\bf m}^{c})^{\frac{1}{2}} +
  4\mathfrak c_{\ref{bound_Omega}}\|(a,b)\mathbf 1_A\|_{f}^{2}\frac{1}{N}.
 \end{eqnarray*}
 %
 Moreover,
 %
 \begin{eqnarray*}
  \|(\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{2}
  & = &
  \widehat\theta^*\Psi_{\bf m}\widehat\theta =
  \left(\widehat{\bf Z}_{\bf m} -
  \frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\cdot
  \mathbf d_{\bf m}\right)^*
  \widehat\Psi_{\bf m}^{-1}\Psi_{\bf m}\widehat\Psi_{\bf m}^{-1}
  \left(\widehat{\bf Z}_{\bf m} -
  \frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\cdot
  \mathbf d_{\bf m}\right)\\
  & = &
  \left\|\Psi_{\bf m}^{\frac{1}{2}}\widehat\Psi_{\bf m}^{-1}
  \left(\widehat{\bf Z}_{\bf m} -
  \frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\cdot
  \mathbf d_{\bf m}\right)\right\|_{2,\mathbb R^{m_1 + m_2}}^{2}\\
  & \leqslant &
  2\|\Psi_{\bf m}^{\frac{1}{2}}
  \widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2} +
  2\left(\frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\right)^2
  \|\Psi_{\bf m}^{\frac{1}{2}}\widehat\Psi_{\bf m}^{-1}
  \mathbf d_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}.
 \end{eqnarray*}
 %
 By the Cauchy-Schwarz inequality,
 %
 \begin{eqnarray*}
  (\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m})^2
  & = &
  \langle\widehat\Psi_{\bf m}^{-\frac{1}{2}}\mathbf d_{\bf m},
  \widehat\Psi_{\bf m}^{-\frac{1}{2}}\widehat{\bf Z}_{\bf m}\rangle_{2,\mathbb R^{m_1 + m_2}}^{2}\\
  & \leqslant &
  \|\widehat\Psi_{\bf m}^{-\frac{1}{2}}\mathbf d_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}
  \|\widehat\Psi_{\bf m}^{-\frac{1}{2}}\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2} =
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}
  \widehat{\bf Z}_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m},
 \end{eqnarray*}
 %
 leading to
 %
 \begin{eqnarray*}
  \left(\frac{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}}{
  \mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}\right)^2
  \|\Psi_{\bf m}^{\frac{1}{2}}\widehat\Psi_{\bf m}^{-1}
  \mathbf d_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}
  & \leqslant &
  \frac{\widehat{\bf Z}_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}
  \widehat{\bf Z}_{\bf m}}{\mathbf d_{\bf m}^{*}\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}}
  \|\Psi_{\bf m}\|_{\rm op}
  \|\widehat\Psi_{\bf m}^{-1}\mathbf d_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}\\
  & = &
  \|\Psi_{\bf m}\|_{\rm op}
  \|\widehat\Psi_{\bf m}^{-1}\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}
  \leqslant
  \|\Psi_{\bf m}\|_{\rm op}
  \|\widehat\Psi_{\bf m}^{-1}\|_{\rm op}^{2}
  \|\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}.
 \end{eqnarray*}
 %
 Thus, by the definition of $\Lambda_{\bf m}$, and since $\|\Psi_{\bf m}\|_{\rm op}\leqslant 2(\mathfrak L_{\varphi}(m_1) +\mathfrak L_{\psi}(m_2))$,
 %
 \begin{eqnarray*}
  \|(\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{2}\mathbf 1_{\Lambda_{\bf m}}
  & \leqslant &
  4\|\Psi_{\bf m}\|_{\rm op}
  \|\widehat\Psi_{\bf m}^{-1}\|_{\rm op}^{2}
  \|\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}\\
  & \leqslant &
  8\mathfrak c_{r}^{2}\frac{N^2}{(\mathfrak L_{\varphi}(m_1) +
  \mathfrak L_{\psi}(m_2))\log(N)^2}\|\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{2}.
 \end{eqnarray*}
 %
 By Inequality (\ref{2nd_order_moment_E_2}), there exists a constant $\mathfrak c_2 > 0$, not depending on $\mathbf m$ and $N$, such that
 %
 \begin{eqnarray*}
  \mathbb E(\|\widehat{\bf Z}_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4})
  & \leqslant &
  8(\mathbb E(\|\mathbf Z_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4}) +
  \mathbb E(\|\mathbf E_{\bf m}\|_{2,\mathbb R^{m_1 + m_2}}^{4}))\\
  & \leqslant &
  \mathfrak c_2N(\mathfrak L_{\varphi}(m_1)^2 +\mathfrak L_{\psi}(m_2)^2)
  \left(\int_A(a(x) + b(y))^4f(x,y)dxdy +
  \int_{-\infty}^{\infty}\sigma(x)^4f_X(x)dx\right).
 \end{eqnarray*}
 %
 So, by Lemma \ref{bound_Omega}, and since $r\geqslant 7$, there exists a constant $\mathfrak c_3 > 0$, not depending on $\mathbf m$ and $N$, such that
 %
 \begin{displaymath}
 \mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{4}
 \mathbf 1_{\Lambda_{\bf m}})^{\frac{1}{2}}\mathbb P(\Omega_{\bf m}^{c})^{\frac{1}{2}}
 \leqslant
 \frac{\mathfrak c_3}{N}.
 \end{displaymath}
 %
 Therefore,
 %
 \begin{equation}\label{nonadaptive_risk_bound_f_weighted_4}
 \mathbb T_2\leqslant
 4\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
 2(\mathfrak c_3 + 2\mathfrak c_{\ref{bound_Omega}}\|(a,b)\mathbf 1_A\|_{f}^{2})\frac{1}{N}.
 \end{equation}
 %
\end{itemize}
%
In conclusion, by Inequalities (\ref{nonadaptive_risk_bound_f_weighted_2}), (\ref{nonadaptive_risk_bound_f_weighted_3}) and (\ref{nonadaptive_risk_bound_f_weighted_4}), there exists a constant $\mathfrak c_4 > 0$, not depending on $\mathbf m$ and $N$, such that
%
\begin{displaymath}
\mathbb E(\|(\widetilde a_{m_1},\widetilde b_{m_2}) - (a,b)\mathbf 1_A\|_{f}^{2})
\leqslant
13\min_{(\tau,\nu)\in\mathcal S_{\bf m}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{f}^{2} +
\frac{8\|\sigma\|_{\infty}^{2}}{T_0}\cdot\frac{m_1 + m_2}{N} +
\frac{\mathfrak c_4}{N}.
\end{displaymath}
%

% Subsection : Proof of Lemma control_bias_term_non_degenerate_constraint.

%
\subsection{Proof of Lemma \ref{control_bias_term_non_degenerate_constraint}}\label{section_proof_control_bias_term_non_degenerate_constraint}
Recall that
%
\begin{displaymath}
b_{m_2} =\sum_{k = 1}^{m_2}\langle b,\psi_k\rangle\psi_k,
\end{displaymath}
%
and let $\overline b_{m_2}$ be the orthogonal projection of $b$ on $\mathbb S_{m_2}$ for the usual inner product in $\mathbb L^2(A_2)$. Precisely,
%
\begin{displaymath}
\overline b_{m_2} =\sum_{k = 1}^{m_2}\overline n_k\psi_k
\end{displaymath}
%
with
%
\begin{equation}\label{control_bias_term_non_degenerate_constraint_2}
\overline n =
\underset{n\in\mathbb R^{m_2} :\eta(n) = 0}{\rm argmin}J_{m_2}(n),
\end{equation}
%
where
%
\begin{displaymath}
J_{m_2}(n) :=\int_{A_2}\left(\sum_{k = 1}^{m_2}n_k\psi_k(y) - b(y)\right)^2dy
\quad {\rm and}\quad
\eta(n) :=\langle n,\delta_{m_2}\rangle_{2,\mathbb R^{m_2}}.
\end{displaymath}
%
Consider
%
\begin{displaymath}
\mathbf z_{m_2} :=
(\langle b,\psi_1\rangle,\dots,\langle b,\psi_{m_2}\rangle),
\end{displaymath}
%
and let $L_{m_2}$ be the Lagrangian for Problem (\ref{control_bias_term_non_degenerate_constraint_2}):
%
\begin{displaymath}
L_{m_2}(n,\lambda) := J_{m_2}(n) -\lambda\eta(n)
\textrm{ $;$ }(n,\lambda)\in\mathbb R^{m_2}\times\mathbb R.
\end{displaymath}
%
Necessarily,
%
\begin{displaymath}
\nabla L_{m_2}(\overline n,\overline\lambda) =
\begin{pmatrix}
 2(\overline n -\mathbf z_{m_2}) -\overline\lambda\delta_{m_2}\\
 -\eta(\overline n)
\end{pmatrix} = 0,
\end{displaymath}
%
leading to
%
\begin{displaymath}
\overline n =\mathbf z_{m_2} +\frac{\overline\lambda}{2}\delta_{m_2},
\quad\textrm{and then}\quad
\overline\lambda = -2\cdot\frac{\langle\mathbf z_{m_2},
\delta_{m_2}\rangle_{2,\mathbb R^{m_2}}}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}.
\end{displaymath}
%
So,
%
\begin{displaymath}
\overline n =\mathbf z_{m_2} -\frac{\langle\mathbf z_{m_2},
\delta_{m_2}\rangle_{2,\mathbb R^{m_2}}}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}\delta_{m_2}
\end{displaymath}
%
and, by the condition (\ref{identifiability_condition}) on $b$,
%
\begin{eqnarray*}
 \|\overline b_{m_2} - b_{m_2}\|^2 & = &
 \left\|\frac{\langle\mathbf z_{m_2},
 \delta_{m_2}\rangle_{2,\mathbb R^{m_2}}}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}
 \sum_{k = 1}^{m_2}\delta_{m_2,k}\psi_k\right\|^2\\
 & = &
 \frac{\langle\mathbf z_{m_2},
 \delta_{m_2}\rangle_{2,\mathbb R^{m_2}}^{2}}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}} =
 \frac{1}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}\left(
 \int_{A_2}(b_{m_2}(y) - b(y))dy\right)^2.
\end{eqnarray*}
%
Since $b_{m_2}$ is the orthogonal projection of $b$ on $\Sigma_{m_2}$, and since $\overline b_{m_2} - b_{m_2}\in\Sigma_{m_2}$,
%
\begin{displaymath}
\min_{\nu\in\mathbb S_{m_2}}\|\nu - b\mathbf 1_{A_2}\|^2 =
\|b_{m_2} - b\mathbf 1_{A_2}\|^2 +
\frac{1}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}\left(
\int_{A_2}(b_{m_2}(y) - b(y))dy\right)^2.
\end{displaymath}
%
Then, Inequality (\ref{bias_term_bound}) leads to (\ref{control_bias_term_non_degenerate_constraint_1}), which ends the proof of Lemma \ref{control_bias_term_non_degenerate_constraint}.
%

% Subsection : Proof of Proposition rate_Sobolev.

%
\subsection{Proof of Proposition \ref{rate_Sobolev}}\label{section_proof_rate_Sobolev}
By Proposition \ref{nonadaptive_risk_bound} together with Lemma \ref{control_bias_term_non_degenerate_constraint},
%
\begin{eqnarray}
 & &
 \mathbb E(\|(\widetilde a_{m_1},\widetilde b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2})
 \nonumber\\
 \label{rate_Sobolev_3}
 & &
 \hspace{2cm}\leqslant
 2\mathfrak c_{f,1}\|a_{m_1} - a\mathbf 1_{A_1}\|^2 +
 2\mathfrak c_{f,2}\|b_{m_2} - b\mathbf 1_{A_2}\|^2 + R(m_2) +
 \frac{2\|\sigma\|_{\infty}^{2}}{T_0}\cdot\frac{m_1 + m_2}{N} +
 \frac{\mathfrak c_{\ref{nonadaptive_risk_bound}}}{N},
\end{eqnarray}
%
where
%
\begin{displaymath}
R(m_2) :=
\frac{2\mathfrak c_{f,2}}{\|\delta_{m_2}\|_{2,\mathbb R^{m_2}}^{2}}\left(
\int_{A_2}(b_{m_2}(y) - b(y))dy\right)^2.
\end{displaymath}
%
First, since $a\in\mathbb W_{\varphi}^{\alpha}(A_1,L_1)$ and $b\in\mathbb W_{\psi}^{\beta}(A_2,L_2)$,
%
\begin{equation}\label{rate_Sobolev_4}
\|a_{m_1} - a\mathbf 1_{A_1}\|^2\leqslant L_1m_{1}^{-\alpha}
\quad {\rm and}\quad
\|b_{m_2} - b\mathbf 1_{A_2}\|^2\leqslant L_2m_{2}^{-\beta}.
\end{equation}
%
Now, by the conditions (\ref{rate_Sobolev_1}) and (\ref{rate_Sobolev_2}),
%
\begin{eqnarray*}
 R(m_2) & \leqslant &
 \mathfrak c_1m_{2}^{-(\omega + 1)}\left(
 \sum_{k > m_2}\langle b,\psi_k\rangle\int_{A_2}\psi_k(y)dy\right)^2
 \quad {\rm with}\quad
 \mathfrak c_1 =\frac{2\mathfrak c_{f,2}}{\mathfrak c_{\psi,1}}\\
 & \leqslant &
 \mathfrak c_1m_{2}^{-(\omega + 1)}
 \left(\sum_{k > m_2}k^{\beta}\langle b,\psi_k\rangle^2\right)
 \left(\sum_{k > m_2}k^{-\beta}\left|\int_{A_2}\psi_k(y)dy\right|^2\right)
 \leqslant
 \mathfrak c_2
 m_{2}^{-(\omega + 1)}
 \sum_{k > m_2}k^{\omega -\beta}
\end{eqnarray*}
%
with $\mathfrak c_2 =\mathfrak c_1L_2\mathfrak c_{\psi,2}$. Moreover,
%
\begin{displaymath}
\sum_{k > m_2}k^{\omega -\beta}
\leqslant
\int_{m_2}^{\infty}y^{\omega -\beta}dy =
\frac{m_{2}^{1 +\omega -\beta}}{\beta - (1 +\omega)},
\end{displaymath}
%
leading to
%
\begin{equation}\label{rate_Sobolev_5}
R(m_2)\leqslant
\frac{\mathfrak c_2}{\beta - (1 +\omega)}m_{2}^{-\beta}.
\end{equation}
%
Therefore, by plugging (\ref{rate_Sobolev_4}) and (\ref{rate_Sobolev_5}) in Inequality (\ref{rate_Sobolev_3}),
%
\begin{displaymath}
\mathbb E(\|(\widetilde a_{m_1},\widetilde b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2})
\lesssim
m_{1}^{-\alpha} + m_{2}^{-\beta} +
\frac{m_1 + m_2}{N}.
\end{displaymath}
%
The conclusion comes by taking $m_1 = m_{1}^{\star}\asymp N^{-1/(\alpha + 1)}$ and $m_2 = m_{2}^{\star}\asymp N^{-1/(\beta + 1)}$.
%

% Subsection : Proof of Theorem adaptive_risk_bound.

%
\subsection{Proof of Theorem \ref{adaptive_risk_bound}}\label{section_proof_adaptive_risk_bound}
Consider
%
\begin{displaymath}
\mathcal M_{N}^{+} :=
\left\{
\mathbf m = (m_1,m_2)\in\{1,\dots,N\}^2 :
(\mathfrak L_{\varphi}(m_1) +\mathfrak L_{\psi}(m_2))
(\|\Psi_{\bf m}^{-1}\|_{\rm op}\vee 1)\leqslant
\frac{3\mathfrak c_r}{2}\cdot\frac{N}{\log(N)}\right\}
\end{displaymath}
%
and
%
\begin{displaymath}
\Omega_N :=
\bigcap_{\mathbf m\in\mathcal M_{N}^{+}}\Omega_{\bf m}.
\end{displaymath}
%
The proof of Theorem \ref{adaptive_risk_bound} relies on the following lemma.
%

% Lemma : Relationship between the three collections of models.

%
\begin{lemma}\label{relationship_collections_models}
Under the assumptions of Theorem \ref{adaptive_risk_bound},
%
\begin{displaymath}
\Omega_N\subset\Xi_N :=
\{\mathcal M_N\subset\widehat{\mathcal M}_N\subset\mathcal M_{N}^{+}\}.
\end{displaymath}
%
\end{lemma}
%
\noindent
The proof of Lemma \ref{relationship_collections_models} is postponed to Section \ref{section_proof_relationship_collections_models}.
%

% Subsubsection : Steps of the proof.

%
\subsubsection{Steps of the proof}
Let $(a_{\widehat m_1}^{N},b_{\widehat m_2}^{N})$ be the minimizer of $(u,v)\mapsto \|(u,v) - (a,b)\mathbf 1_A\|_{N}^{2}$ over $\mathcal S_{\widehat{\bf m}}$. Then,
%
\begin{displaymath}
\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2} =
\min_{(\tau,\nu)\in\mathcal S_{\widehat{\bf m}}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{N}^{2} +
\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a_{\widehat m_1}^{N},b_{\widehat m_2}^{N})\|_{N}^{2}.
\end{displaymath}
%
Moreover, since $0\in\mathcal S_{\widehat{\bf m}}$,
%
\begin{displaymath}
\min_{(\tau,\nu)\in\mathcal S_{\widehat{\bf m}}}\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{N}^{2}\leqslant
\|(a,b)\mathbf 1_A\|_{N}^{2}.
\end{displaymath}
%
So,
%
\begin{equation}\label{adaptive_risk_bound_1}
\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\leqslant
\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Omega_N} +
R(\widehat{\bf m})\mathbf 1_{\Omega_{N}^{c}},
\end{equation}
%
where
%
\begin{displaymath}
R(\widehat{\bf m}) :=\|(a,b)\mathbf 1_A\|_{N}^{2} +
\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a_{\widehat m_1}^{N},b_{\widehat m_2}^{N})\|_{N}^{2}.
\end{displaymath}
%
The proof of Theorem \ref{adaptive_risk_bound} is dissected in three steps. The first step provides a preliminary risk bound on our adaptive projection least squares estimator, which is improved in Step 3 thanks to the bound established in Step 2 on
%
\begin{displaymath}
\rho(\mathbf m) :=
\mathbb E\left(\left(\left[\sup_{(\tau,\nu)\in\mathcal B_{\mathbf m,\widehat{\bf m}}}|\zeta_N(\tau,\nu)|\right]^2 -
p(\mathbf m,\widehat{\bf m})\right)_+\mathbf 1_{\Omega_N}\right)\textrm{ $;$ }
\mathbf m = (m_1,m_2)\in\mathcal M_N
\end{displaymath}
%
where, for every $\mathbf m' = (m_1',m_2')\in\mathcal M_N$,
%
\begin{displaymath}
\mathcal B_{\mathbf m,\mathbf m'} :=
\{(\tau,\nu)\in\mathcal S_{(m_1\vee m_1',m_2\vee m_2')} :\|(\tau,\nu)\|_f = 1\}
\end{displaymath}
%
and
%
\begin{displaymath}
p(\mathbf m,\widehat{\bf m}) := p(m_1\vee m_1') + p(m_2\vee m_2')
\quad {\rm with}\quad
p(m) :=
\frac{\kappa\|\sigma\|_{\infty}^{2}}{8T_0}\cdot\frac{m}{N}.
\end{displaymath}
%
{\bf Step 1.} On the one hand, by Inequality (\ref{nonadaptive_risk_bound_6}), and by the definition of $\widehat{\mathcal M}_N$,
%
\begin{eqnarray*}
 \|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a_{\widehat m_1}^{N},b_{\widehat m_2}^{N})\|_{N}^{2}
 & \leqslant &
 \|\widehat\Psi_{\widehat{\bf m}}^{-1}\|_{\rm op}
 \|\mathbf E_{\widehat{\bf m}}\|_{2,\mathbb R^{\widehat m_1 +\widehat m_2}}^{2}\\
 & \leqslant &
 \mathfrak c_rN\|\mathbf E_{\bf N}\|_{2,\mathbb R^{2N}}^{2}
 \quad {\rm with}\quad
 \mathbf N = (N,N).
\end{eqnarray*}
%
Moreover, by Lemma \ref{bound_Omega},
%
\begin{displaymath}
\mathbb P(\Omega_{N}^{c})\leqslant
\sum_{\mathbf m\in\mathcal M_{N}^{+}}
\mathbb P(\Omega_{\bf m}^{c})\leqslant
\frac{\mathfrak c_{\ref{bound_Omega}}}{N^{r - 2}}.
\end{displaymath}
%
Then, by Inequality (\ref{2nd_order_moment_E_2}),
%
\begin{eqnarray*}
 \mathbb E(R(\widehat{\bf m})\mathbf 1_{\Omega_{N}^{c}})
 & \leqslant &
 (\mathbb E(\|(a,b)\|_{N}^{4})^{\frac{1}{2}} +
 \mathfrak c_rN\mathbb E(\|\mathbf E_{\bf N}^{4}\|_{2,\mathbb R^{2N}}^{4})^{\frac{1}{2}})
 \mathbb P(\Omega_{N}^{c})^{\frac{1}{2}}\\
 & \leqslant &
 \mathfrak c_1(1 + N^{\frac{3}{2}})N^{1 -\frac{r}{2}}
 \leqslant 2\mathfrak c_1N^{-\frac{r - 5}{2}},
\end{eqnarray*}
%
where $\mathfrak c_1$ is a positive constant not depending on $N$. On the other hand, for every $(\tau,\nu),(\overline\tau,\overline\nu)\in\mathcal S_{\bf N}$,
%
\begin{displaymath}
\gamma_N(\overline\tau,\overline\nu) -\gamma_N(\tau,\nu) =
\|(\overline\tau,\overline\nu) - (a,b)\mathbf 1_A\|_{N}^{2} -
\|(\tau,\nu) - (a,b)\mathbf 1_A\|_{N}^{2} - 2\zeta_N(\overline\tau -\tau,\overline\nu -\nu).
\end{displaymath}
%
Moreover, by the definition of $\widehat{\bf m}$, for every $\mathbf m = (m_1,m_2)\in\widehat{\mathcal M}_N$,
%
\begin{equation}\label{adaptive_risk_bound_2}
\gamma_N(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) +
{\rm pen}(\widehat{\bf m})\leqslant
\gamma_N(\widehat a_{m_1},\widehat b_{m_2}) +
{\rm pen}(\mathbf m).
\end{equation}
%
On the event $\Xi_N$, Inequality (\ref{adaptive_risk_bound_2}) remains true for every $\mathbf m\in\mathcal M_N$. Then, on the event $\Omega_N$ (which is contained in $\Xi_N$ by Lemma \ref{relationship_collections_models}), for any $\mathbf m = (m_1,m_2)\in\mathcal M_N$, since $\mathcal S_{\bf m} +\mathcal S_{\widehat{\bf m}}\subset\mathcal S_{(m_1\vee\widehat m_1,m_2\vee\widehat m_2)}$ by (\ref{consequence_nested}),
%
\begin{eqnarray*}
 \|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}
 & \leqslant &
 \|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\\
 & &
 \hspace{1cm} +
 2\zeta_N(\widehat a_{\widehat m_1} -\widehat a_{m_1},\widehat b_{\widehat m_2} -\widehat b_{m_2}) +
 {\rm pen}(\mathbf m) - {\rm pen}(\widehat{\bf m})\\
 & \leqslant &
 \|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2} +
 \frac{1}{8}\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) -
 (\widehat a_{m_1},\widehat b_{m_2})\|_{f}^{2}\\
 & &
 \hspace{1cm} +
 8\mathcal Z(\mathbf m,\widehat{\bf m}) +
 {\rm pen}(\mathbf m) + 8p(\mathbf m,\widehat{\bf m}) - {\rm pen}(\widehat{\bf m}),
\end{eqnarray*}
%
where
%
\begin{displaymath}
\mathcal Z(\mathbf m,\widehat{\bf m}) :=
\left(\left[\sup_{(\tau,\nu)\in\mathcal B_{\mathbf m,\widehat{\bf m}}}|\zeta_N(\tau,\nu)|\right]^2 -
p(\mathbf m,\widehat{\bf m})\right)_+.
\end{displaymath}
%
Since $\|(\tau,\nu)\|_{f}^{2}\mathbf 1_{\Omega_N}\leqslant 2\|(\tau,\nu)\|_{N}^{2}\mathbf 1_{\Omega_N}$ for every $(\tau,\nu)\in\mathcal S_{\bf N}$, and since $8p(\mathbf m,\widehat{\bf m})\leqslant {\rm pen}(\mathbf m) + {\rm pen}(\widehat{\bf m})$,
%
\begin{eqnarray*}
 \|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}
 & \leqslant &
 3\|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\\
 & &
 \hspace{2cm} +
 4{\rm pen}(\mathbf m) + 16\mathcal Z(\mathbf m,\widehat{\bf m})
 \quad {\rm on}\quad\Omega_N.
\end{eqnarray*}
%
So,
%
\begin{displaymath}
\mathbb E(\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) -
(a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Omega_N})
\leqslant
\min_{\mathbf m\in\mathcal M_N}\{
3\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) -
(a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Omega_N}) +
4{\rm pen}(\mathbf m) + 16\rho(\mathbf m)\}.
\end{displaymath}
%
Therefore, to conclude this first step, by Inequality (\ref{adaptive_risk_bound_1}),
%
\begin{eqnarray}
 \label{adaptive_risk_bound_3}
 \mathbb E(\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2})
 & \leqslant &
 \min_{\mathbf m\in\mathcal M_N}\{
 3\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Omega_N})\\
 & &
 \hspace{3.5cm} +
 4{\rm pen}(\mathbf m) + 16\rho(\mathbf m)\} + 2\mathfrak c_1N^{-\frac{r - 5}{2}}.
 \nonumber
\end{eqnarray}
%
{\bf Step 2.} First, consider $(\tau,\nu)\in\mathcal S_{\bf N}$, and let $M(\tau,\nu)$ be the $\mathbb F$-martingale defined by
%
\begin{displaymath}
M_s(\tau,\nu) :=
\sum_{i = 1}^{N}\int_{t_0}^{t}(\tau(X_{s}^{i}) +\nu(Y_{s}^{i}))\sigma(X_{s}^{i})dW_{1}^{i}(s)
\textrm{ $;$ }\forall t\in [t_0,T].
\end{displaymath}
%
Since $W^1,\dots,W^N$ are independent Brownian motions,
%
\begin{displaymath}
\langle M(\tau,\nu)\rangle_T =
\sum_{i = 1}^{N}\int_{t_0}^{T}(\tau(X_{s}^{i}) +\nu(Y_{s}^{i}))^2\sigma(X_{s}^{i})^2ds
\leqslant NT_0\|\sigma\|_{\infty}^{2}\|(\tau,\nu)\|_{N}^{2}.
\end{displaymath}
%
Then, by the Bernstein inequality for continuous local martingales (see Revuz and Yor \cite{RY99}, p. 153), for any $\varepsilon,\upsilon > 0$,
%
\begin{eqnarray*}
 \mathbb P(\zeta_N(\tau,\nu)\geqslant\varepsilon,\|(\tau,\nu)\|_{N}^{2}\leqslant\upsilon^2)
 & \leqslant &
 \mathbb P(M_T(\tau,\nu)^*\geqslant NT_0\varepsilon,
 \langle M(\tau,\nu)\rangle_T\leqslant NT_0\upsilon^2\|\sigma\|_{\infty}^{2})\\
 & \leqslant &
 \exp\left(-\frac{NT_0\varepsilon^2}{2\upsilon^2\|\sigma\|_{\infty}^{2}}\right).
\end{eqnarray*}
%
So, since this bound remains true by replacing $(\tau,\nu)$ by $-(\tau,\nu)$,
%
\begin{equation}\label{adaptive_risk_bound_4}
\mathbb P(|\zeta_N(\tau,\nu)|\geqslant\varepsilon,\|(\tau,\nu)\|_{N}^{2}\leqslant\upsilon^2)\leqslant
2\exp\left(-\frac{NT_0\varepsilon^2}{2\upsilon^2\|\sigma\|_{\infty}^{2}}\right).
\end{equation}
%
Now, for any $\mathbf m = (m_1,m_2)$ and $\mathbf m' = (m_1',m_2')$ belonging to $\mathcal M_N$, note that
%
\begin{displaymath}
\sup_{(\tau,\nu)\in\mathcal B_{\mathbf m,\mathbf m'}}|\zeta_N(\tau,\nu)|\leqslant
\sup_{h\in\mathbb B_{\mathbf m,\mathbf m'}}|\mathbb Z_N(h)|,
\end{displaymath}
%
where
%
\begin{displaymath}
\mathbb Z_N(h) :=
\frac{1}{NT_0}\sum_{i = 1}^{N}\int_{t_0}^{T}h(X_{s}^{i},Y_{s}^{i})\sigma(X_{s}^{i})dW_{1}^{i}(s),
\end{displaymath}
%
and
%
\begin{displaymath}
\mathbb B_{\mathbf m,\mathbf m'} :=
\left\{h\in\mathbb K_{\mathbf m,\mathbf m'} :
\int_{\mathbb R^2}h(x,y)^2f(x,y)dxdy\leqslant 1\right\}
\end{displaymath}
%
with
%
\begin{eqnarray*}
 \mathbb K_{\mathbf m,\mathbf m'} & = &
 \{h :\mathbb R^2\rightarrow\mathbb R\textrm{, measurable} :\\
 & &
 \hspace{2.5cm}
 \exists (\tau,\nu)\in S_{m_1\vee m_1'}\times\Sigma_{m_2\vee m_2'}\textrm{, }
 \forall (x,y)\in\mathbb R^2\textrm{, }h(x,y) =\tau(x) +\nu(y)\}.
\end{eqnarray*}
%
Since $\mathbb K_{\mathbf m,\mathbf m'}$ is a vector subspace of $\mathbb L^2(\mathbb R^2,f(x,y)dxdy)$ of dimension $D(\mathbf m,\mathbf m') := m_1\vee m_1' + m_2\vee m_2'$, by Lorentz et al. \cite{LGM96}, Chapter 15, Proposition 1.3, for every $n\in\mathbb N$, there exists $T_n\subset\mathbb B_{\mathbf m,\mathbf m'}$ such that $|T_n|\leqslant (3/\delta_n)^{D(\mathbf m,\mathbf m')}$ with $\delta_n =\alpha 2^{-n}$ ($\alpha\in (0,1)$), and for every $h\in\mathbb B_{\mathbf m,\mathbf m'}$,
%
\begin{equation}\label{adaptive_risk_bound_5}
\exists h_n\in T_n :\int_{\mathbb R^2}(h(x,y) - h_n(x,y))^2f(x,y)dxdy\leqslant\delta_{n}^{2}.
\end{equation}
%
Thanks to (\ref{adaptive_risk_bound_4}) and (\ref{adaptive_risk_bound_5}), and since $p(\mathbf m,\mathbf m')\asymp D(\mathbf m,\mathbf m')/N$, the third step of the proof of Marie \cite{MARIE25}, Theorem 3.2 - based on the chaining technique - extends from the case $b(.) = 0$ to the case $b(.)\neq 0$. Therefore, there exists a constant $\kappa_0 > 0$, not depending on $N$, such that for every $\kappa\geqslant\kappa_0$,
%
\begin{equation}\label{adaptive_risk_bound_6}
\rho(\mathbf m)\leqslant
\mathbb E\left(\left(\left[\sup_{h\in\mathbb B_{\mathbf m,\widehat{\bf m}}}|\mathbb Z_N(h)|\right]^2 -
p(\mathbf m,\widehat{\bf m})\right)_+\mathbf 1_{\Omega_N}\right)
\lesssim\frac{1}{N}\textrm{ $;$ }\forall\mathbf m\in\mathcal M_N.
\end{equation}
%
{\bf Step 3.} By pugging Inequality (\ref{adaptive_risk_bound_6}) in Inequality (\ref{adaptive_risk_bound_3}), there exists a constant $\mathfrak c_2 > 0$, not depending on $N$, such that
%
\begin{displaymath}
\mathbb E(\|(\widehat a_{\widehat m_1},\widehat b_{\widehat m_2}) - (a,b)\mathbf 1_A\|_{N}^{2})
\leqslant
\mathfrak c_2\left(
\min_{\mathbf m\in\mathcal M_N}\{
3\mathbb E(\|(\widehat a_{m_1},\widehat b_{m_2}) - (a,b)\mathbf 1_A\|_{N}^{2}\mathbf 1_{\Omega_N}) +
{\rm pen}(\mathbf m)\} +\frac{1}{N}\right).
\end{displaymath}
%

% Subsubsection : Proof of Lemma relationship_collections_models.

%
\subsubsection{Proof of Lemma \ref{relationship_collections_models}}\label{section_proof_relationship_collections_models} We acknowledge Huang \cite{HUANG25} for a decisive improvement of the result obtained in this lemma. Consider $\omega\in\Omega_N$ and
%
\begin{displaymath}
\widehat G_{\bf m}(\omega) :=
\Psi_{\bf m}^{-\frac{1}{2}}\widehat\Psi_{\bf m}(\omega)\Psi_{\bf m}^{-\frac{1}{2}}
\textrm{ $;$ }\forall\mathbf m\in\mathcal M_{N}^{+}.
\end{displaymath}
%
For any $\mathbf m\in\mathcal M_{N}^{+}$, since $\omega\in\Omega_{\bf m}$,
%
\begin{displaymath}
{\rm Sp}(\widehat G_{\bf m}(\omega))
\subset\left[\frac{1}{2},\frac{3}{2}\right],
\quad\textrm{and then}\quad
{\rm Sp}(\widehat G_{\bf m}^{-1}(\omega))
\subset\left[\frac{2}{3},2\right].
\end{displaymath}
%
Moreover,
%
\begin{displaymath}
\widehat\Psi_{\bf m}^{-1}(\omega) =
\Psi_{\bf m}^{-\frac{1}{2}}\widehat G_{\bf m}^{-1}(\omega)\Psi_{\bf m}^{-\frac{1}{2}}.
\end{displaymath}
%
So, thanks to a well-known property of the Loewner order,
%
\begin{displaymath}
\frac{2}{3}\mathbf x^*\Psi_{\bf m}^{-1}\mathbf x
\leqslant\mathbf x^*\widehat\Psi_{\bf m}^{-1}(\omega)\mathbf x\leqslant
2\mathbf x^*\Psi_{\bf m}^{-1}\mathbf x
\textrm{ $;$ }\forall\mathbf x\in\mathbb R^{m_1 + m_2},
\end{displaymath}
%
leading to
%
\begin{displaymath}
\|\Psi_{\bf m}^{-1}\|_{\rm op}\leqslant
\frac{3}{2}\|\widehat\Psi_{\bf m}^{-1}(\omega)\|_{\rm op}
\quad {\rm and}\quad
\|\widehat\Psi_{\bf m}^{-1}(\omega)\|_{\rm op}\leqslant
2\|\Psi_{\bf m}^{-1}\|_{\rm op}.
\end{displaymath}
%
Therefore, $\omega\in\Xi_N$.
%

