\section{Introduction}

An interest to the differential properties of special functions with respect to their parameters is recently growing. Respective formulas become the sources for new classes of special functions as well as differential equations of new types. They are important as for better understanding of the behaviour of special functions as for their applications (see, e.g. \cite{Lan00}). A number of articles are devoted to the differentiation of the Bessel-type functions, see e.g.
\cite{ApeKra85},  \cite{Bry16} and references therein. In particular,
the differential equation for derivatives of the Bessel function w.r.t. parameter was used in \cite{Dun17} for derivation of
an integral representation for $\frac{\partial J_{\nu}(z)}{\partial \nu}$.

Recently Apelblat
\cite{Ape20} and   Apelblat and Mainardi proposed \cite{ApeMai22} an approach for differentiation of the Mittag-Leffler and Wright  functions, respectively,
(see, e.g. \cite{GKMR})
 with respect to parameters.
% It was mostly concerns to the differentiation of the Wright function (see, e.g. \cite{GKMR}).
The obtained formulas are derived by using the formal term-by-term differentiation of the series represented those special  functions.
 So, the derivatives with respect to the parameters are again series
and one can ask where these series do converge.

%In \cite{RoGiMa24} the differentiability with respect to parameters of the general ${\mathcal{HG}}$-function generalizing the Fox ${\mathcal{H}}$-function is studied. These function are introduced in \cite{RogDub23,RogDub24}. They are related to the so-called $I$-integral \cite{In-H87}.

In \cite{RoGiMa24} two approaches were proposed for justification of the formulas of differentiation of the special functions (Mittag-Leffler and Le Roy type) with respect to their parameters. These approaches are based on the  uniform convergence concept and used either series representations or integral representations of the functions mentioned. %In \cite{GiMaRo25}, the  sub-products of \cite{RoGiMa24} are determined and described, namely the differential equations satisfied by the considered special functions are formulated.

This article is devoted to derivation of the Laplace transforms (see, e.g., \cite{DebBha15} of these derivatives with respect to the parameters of certain special functions, namely, the Mittag-Leffler type, Wright and Le Roy type functions (see \cite{GKMR}, \cite{Luc19}, \cite{RogDub23}, \cite{RogDub24}). These formulas show the interconnection of these functions and lead to better understanding of their behavior on the real line. In this connection, we have to mention a survey paper \cite{Ape25} in which some examples are presented justifying importance of the Laplace transforms technique in different branches of applied sciences (cf. also \cite{Ape12}).


Special attention is paid to reconstruction of  these formulas by using Efros theorem \cite{Efr35} in Wlodarski form (see \cite{Wlo52}, \cite{Gra04}).

\newpage
Throughout this paper we assume that all parameters ($\alpha, \beta, \gamma, \alpha_j, \beta_j$) are positive. It follows from \cite{RoGiMa24} that under these conditions the corresponding series converge uniformly with respect to these parameters. The detailed proof is presented in Theorem \ref{Thm2.1}. Thus, we can apply the Laplace transforms to the derivatives point-wise.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Laplace transforms of the derivatives of the Mittag-Leffler functions}
\label{Laplace_M-L}

We start with the two-parametric Mittag-Leffler function (which is the most useful for applications); see, e.g. \cite[Ch. 4]{GKMR}.
\begin{equation}
\label{2parML1}
E_{\alpha,\beta}(z) = \sum\limits_{k=0}^{\infty} \frac{z^k}{\Gamma(\alpha k + \beta)}.
\end{equation}
It is well known that the function $E_{\alpha,\beta}(z)$ is an entire function of the complex variable $z$ for all ${\mathrm{Re}}\, \alpha > 0, \beta\in {\mathbb C}$. To avoid additional technical details we limit our study to the case  $\alpha > 0,\beta > 0$ only.
The most applicable formula for the Laplace transforms of the function (\ref{2parML1}) is the following one, see, e.g. \cite[(4.9.1)]{GKMR}
\begin{equation}
\label{Lap2parML2}
{\mathcal L}\left(t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})\right)(s) = \frac{s^{\alpha-\beta}}{s^{\alpha} - \lambda};\;
\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0;\;\;\; |\lambda s^{-\alpha}| < 1.
\end{equation}
 For the formulas of the derivatives of $t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})$ we use the results obtained in \cite{RoGiMa24}.
 In the following theorem we prove the formula for the Laplace transform of the derivative with respect to parameter $\alpha$ of the function $t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})$.
 \begin{theorem}
 \label{Thm2.1}
Let $\alpha,\beta > 0,$ $\lambda\in {\mathbb R}$. Then the following formula
 \begin{equation}
\label{2parML3a}
%\begin{split}
\begin{array}{ll}
{\ds {\mathcal L}\left(\frac{\partial}{\partial \alpha} \left[t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})\right]\right)(s)}
 &\! =\!
{\ds \int\limits_{0}^{\infty} e^{-st} \sum\limits_{k=0}^{\infty} k \lambda^{k} \left[\frac{t^{\alpha k + \beta - 1} \left(\ln t - \psi(\alpha k + \beta)\right)}{\Gamma(\alpha k + \beta)}\right]}
\\
 &= {\ds - \frac{\lambda s^{\alpha-\beta} \ln\, s}{(s^{\alpha} - \lambda)^2}}
%\end{split}
\end{array}
\end{equation}
is valid for all $|\lambda s^{-\alpha}| < 1$.
Here $\psi$ is the so-called digamma function $\psi(t) = \left(\ln\, \Gamma(t)\right)^{'} = \frac{\Gamma^{'}(t)}{\Gamma(t)}$ (see, e.g., \cite[Ch. 5]{NIST}).
 \end{theorem}

 {\bf Proof.} Let us take arbitrary numbers $a, b$, $0 < a < b < \infty$. Suppose that $\alpha\in [a, b]$.

 First, we prove that the derivative in $\alpha$ of the function $t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})$ can be calculated term-wise, i.e.
\begin{equation}
\label{2.3.1}
\frac{\partial}{\partial \alpha} \left[t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})\right] = \sum\limits_{k=0}^{\infty} \frac{\partial}{\partial \alpha}
\frac{t^{\alpha k + \beta - 1} \lambda^k}{\Gamma(\alpha k + \beta)} = \sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k + \beta - 1} (\ln t - \psi(\alpha k + \beta))}{\Gamma(\alpha k + \beta)}.
\end{equation}
To see this, it is sufficient to show that the last series is converging uniformly with respect to $\alpha\in [a, b]$.

Let us consider the following series
$$
\ln t \cdot t^{\beta - 1}\sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k}}{\Gamma(\alpha k + \beta)}.
$$
We can find a positive integer number $k_0\in {\mathbb N}$ such that $a k > 4$ for all $k\geq k_0$. Since $\alpha\in [a, b]$, and for integer parts of numbers $[\cdot]$ we have $[a k] \geq a k - 1 > 1, [\beta] > 0$, the the following inequalities can be derived:
$$
\sum\limits_{k=k_0}^{\infty} k \lambda^k \frac{t^{\alpha k}}{\Gamma(\alpha k + \beta)} \leq \sum\limits_{k=k_0}^{\infty} k \lambda^k \frac{t^{b k}}{\Gamma(a k + \beta)} \leq
\sum\limits_{k=k_0}^{\infty} k  \frac{(\lambda t^{b})^{k}}{\Gamma([a k] + [\beta])} \leq
$$
$$
\sum\limits_{k=k_0}^{\infty} \frac{k}{[a k] + [\beta]}  \frac{(\lambda t^{b})^{k}}{\Gamma([a k] + [\beta] - 1)} \leq
\sum\limits_{k=k_0}^{\infty} \frac{k}{a k + \beta - 2}  \frac{(\lambda t^{b})^{k}}{\Gamma(a k + \beta - 3)}.
$$
The series
$$
\sum\limits_{k=k_0}^{\infty} \frac{(\lambda t^{b})^{k}}{\Gamma(a k + \beta - 3)} =
(\lambda t^{b})^{k_0} \sum\limits_{k=k_0}^{\infty} \frac{(\lambda t^{b})^{k - k_0}}{\Gamma(a (k - k_0) + a k_0 + \beta - 3)} =
$$
$$
(\lambda t^{b})^{k_0} \sum\limits_{m=0}^{\infty} \frac{(\lambda t^{b})^{m}}{\Gamma(a m + a k_0 + \beta - 3)} = (\lambda t^{b})^{k_0} E_{a, a k_0 + \beta - 3} (\lambda t^{b})
$$
converges for all $\lambda\in {\mathbb R}$, $t\in {\mathbb R}$ and does not depend on $\alpha$. The sequence $\frac{k}{a k + \beta - 2}$ is bounded and monotonically decreasing. It gives the uniform convergence with respect to $\alpha\in [a, b]$ of the series
$\sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k+\beta -1} \ln t}{\Gamma(\alpha k + \beta)}$.

In order to show the uniform convergence with respect to $\alpha\in [a, b]$ of the series
$\sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k+\beta -1} \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)}$ we use the following inequality:
\begin{equation}
\label{psi1}
\ln (x + \frac{1}{2}) \leq \psi(x + 1) \leq \ln (x + e^{-\gamma_{0}}),
\end{equation}
valid for all $x > - 1$   (see \cite{Alz97}, cf. \cite{GuoQi14} for the best possible inequalities of such type). Here $\gamma_{0} := \lim\limits_{n\rightarrow \infty} \left(- \ln n + \sum\limits_{k=1}^{n} \frac{1}{k}\right)$ being the Euler-Mascheroni constant. We also apply Stirling-like asymptotic formula (see, e.g., \cite[Appendix A]{GKMR})
\begin{equation}
\label{gamma1}
\Gamma(\alpha k + \beta) = \sqrt{2\pi} (\alpha k)^{\alpha k + \beta - 1/2} e^{-\alpha k} [1 + o(1)],\;\;\; k \rightarrow \infty.
\end{equation}
Thus
$$ \sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k} \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)}$$
$$ \leq
\sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{b k} \psi(b k + \beta)}{\Gamma(a k + \beta)}
 \leq
\sum\limits_{k=0}^{\infty} \frac{k \ln (bk + \beta - 1 + e^{-\gamma_{0}})}{\sqrt{2\pi} \left(\frac{ak}{e}\right)^{ak} (ak)^{\beta - 1/2}[1 + o(1)]} (\lambda t^b)^k.
$$
Direct calculation show that this power series has an infinite radius of convergence. It gives the uniform convergence with respect to $\alpha\in [a, b]$ of the series
${\ds \sum\limits_{k=0}^{\infty} k \lambda^k \frac{t^{\alpha k+\beta -1} \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)}}$.

The ext step is to justify the validity of the formula
\begin{equation}
\label{2.3.2}
{\mathcal L} \left(\sum\limits_{k=0}^{\infty} \frac{\partial}{\partial \alpha} \lambda^{k} \frac{t^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)}\right) =
\sum\limits_{k=0}^{\infty} \int\limits_{0}^{\infty} e^{-st} \frac{\partial}{\partial \alpha} \left(\lambda^{k} \frac{t^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)}\right) dt.
\end{equation}
For this it is sufficient to prove that the series
\begin{equation}
\label{2.3.3}
\sum\limits_{k=0}^{\infty} \int\limits_{0}^{\infty} e^{-st} \frac{\partial}{\partial \alpha} \left(\lambda^{k} \frac{t^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)}\right) dt =
\sum\limits_{k=0}^{\infty} \int\limits_{0}^{\infty} e^{-st} k \lambda^k \frac{t^{\alpha k + \beta - 1} (\ln t - \psi(\alpha k + \beta))}{\Gamma(\alpha k + \beta)}
\end{equation}
converges uniformly with respect to $\alpha\in [a, b]$ in a proper domain of the variable $s$. Let us perform the change of variable $s t = u$ in the following integral
\begin{equation}
\label{2.3.4}
%\begin{array}{ll}
{\ds \int\limits_{0}^{\infty} e^{-st} k \lambda^k \frac{t^{\alpha k + \beta - 1} \ln t}{\Gamma(\alpha k + \beta)}}
 =
{\ds \frac{k (\lambda s^{-\alpha})^k}{s^{\beta}}
 \left[
\int\limits_{0}^{\infty} e^{-u} \frac{u^{\alpha k + \beta - 1} \ln u}{\Gamma(\alpha k + \beta)} d u
  - \int\limits_{0}^{\infty} e^{-u} \frac{u^{\alpha k + \beta - 1} \ln s}{\Gamma(\alpha k + \beta)} d u\right]}.
%\end{array}
\end{equation}
Note that
$\int\limits_{0}^{\infty} e^{-u} u^{\gamma} \ln u \,d u = \left(\int\limits_{0}^{\infty} e^{-u} u^{\gamma} d u\right)^{\prime}_{\gamma}$.
Hence
\begin{equation}
\label{2.3.5}
\begin{array}{ll}
{\ds {\int\limits_{0}^{\infty} e^{-u}
\frac{u^{\alpha k + \beta - 1} \ln u} {\Gamma(\alpha k + \beta)}
\, d u}}
&=
 {\ds \frac{1}{\Gamma(\alpha k + \beta)}
  \left(\int\limits_{0}^{\infty} e^{-u} u^{\alpha k + \beta} \,d u \right)^{\prime}_{\gamma=\alpha k + \beta}}
\\
&=
  {\ds \frac{1}{\Gamma(\alpha k + \beta)} \Gamma^{\prime}(\alpha k + \beta)}
= {\ds \psi(\alpha k + \beta)}.
\end{array}
\end{equation}
For the second term in the right hand side of (\ref{2.3.4}) we have
\begin{equation}
\label{2.3.6}
- \int\limits_{0}^{\infty} e^{-u} \frac{u^{\alpha k + \beta - 1} \ln s}{\Gamma(\alpha k + \beta)} d u = - \ln s \int\limits_{0}^{\infty} e^{-u} \frac{u^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)} d u = - \ln s.
\end{equation}
Substituting (\ref{2.3.5}), (\ref{2.3.6}) into (\ref{2.3.3}) we obtain
\begin{equation}
\label{2.3.7}
\sum\limits_{k=0}^{\infty} \int\limits_{0}^{\infty} e^{-st} \frac{\partial}{\partial \alpha} \left(\lambda^{k} \frac{t^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)}\right) dt =
- \sum\limits_{k=0}^{\infty} \frac{k (\lambda s^{-\alpha})^k}{s^{\beta}} \ln s.
\end{equation}
For the series $\sum\limits_{k=0}^{\infty} k (\lambda s^{-\alpha})^k \leq \sum\limits_{k=0}^{\infty} k (\lambda s^{-a})^k$. The last series does not depend on $\alpha$ and converges in the domain $\left|\lambda s^{-a}\right| < 1$. Hence, we can conclude that the series (\ref{2.3.7}) converges uniformly with respect to $\alpha\in [a, b]$ in the domain $\left|\lambda s^{-\alpha}\right| < 1$. Let us denote $\lambda s^{-\alpha} =: v$ and note that
$$\sum\limits_{k=0}^{\infty} k v^k = v \sum\limits_{k=0}^{\infty} \left(v^k\right)^{\prime}_{v}= \frac{v}{(1 - v)^2}.$$
 Therefore,
$$\sum\limits_{k=0}^{\infty} \int\limits_{0}^{\infty} e^{-st} \frac{\partial}{\partial \alpha} \left(\lambda^{k} \frac{t^{\alpha k + \beta - 1}}{\Gamma(\alpha k + \beta)}\right) dt = - \frac{\ln s \cdot \lambda s^{-\alpha}}{s^{\beta} (1 - \lambda s^{-\alpha})^2} = - \frac{\ln s \cdot \lambda s^{\alpha - \beta}}{(s^{-\alpha} - \lambda )^2}.
$$
It completes the proof. $\Box$
\begin{remark}
\label{Rem2.1}
The obtained result can be formally derived by the direct differentiation of the relation (\ref{Lap2parML2}) with respect to $\alpha$. In the Theorem \ref{Thm2.1} we justify the validity of this formal result.
\end{remark}

Below we present a number of other formulas for the Laplace transform of the derivatives with respect to parameters of different special functions. These formulas are justified in a way similar to that demonstrated in the Theorem \ref{Thm2.1}.
\begin{theorem}
 \label{Thm2.2}
Let $\alpha,\beta > 0,$ $\lambda\in {\mathbb R}$. Then the following formula
 \begin{equation}
\label{2parML3b}
\begin{array}{ll}
{\ds {\mathcal L} \left(\frac{\partial}{\partial \beta} \left[t^{\beta - 1} E_{\alpha,\beta}(\lambda t^{\alpha})\right]\right)(s)}
 &=
{\ds \int\limits_{0}^{\infty} e^{-st} \sum\limits_{k=0}^{\infty}  \lambda^{k} \left[\frac{t^{\alpha k + \beta - 1} \left(\ln t - \psi(\alpha k + \beta)\right)}{\Gamma(\alpha k + \beta)}\right]}
\\
& = {\ds  - \frac{ s^{\alpha-\beta} \ln\, s}{s^{\alpha} - \lambda}}
\end{array}
\end{equation}
is valid for all $|\lambda s^{-\alpha}| < 1$.
\end{theorem}

The direct application of the Laplace transforms to the Mittag-Leffler function leads to a little bit more cumbersome formula
\begin{equation}
\label{Lap2parML3}
{\mathcal L}\left(E_{\alpha,\beta}(t)\right)(s) = \sum\limits_{k=0}^{\infty} \frac{k!}{\Gamma(\alpha k + \beta)} s^{-k-1}.
\end{equation}
It follows from the asymptotic formula (\ref{gamma1}) that the series in the right-hand side of (\ref{Lap2parML3}) converge for all $s\in {\mathbb C}\setminus \{0\}$ whenever $\alpha > 1$, and for all $s\in {\mathbb C},\, |s| > 1,$  whenever $\alpha = 1$. If $0 < \alpha < 1$, then this series diverges everywhere. The corresponding formulas of the Laplace transform of the derivatives of $E_{\alpha,\beta}(t)$ are given in the next therorem.

\begin{theorem}
\label{Thm2.3}
Let $\alpha > 1, \beta\in {\mathbb R}$. Then the following formulas of the Laplace transform of the derivatives of the function $E_{\alpha,\beta}(t)$
\begin{equation}
\label{2parML3a_pure}
{\mathcal L} \left(\frac{\partial}{\partial \alpha} \left[E_{\alpha,\beta}(t)\right]\right)(s)
= - \sum\limits_{k=0}^{\infty} \frac{k!\times k\times \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)} s^{-k},
\end{equation}
\begin{equation}
\label{2parML3b_pure}
{\mathcal L} \left(\frac{\partial}{\partial \beta} \left[E_{\alpha,\beta}(t)\right]\right)(s)
= - \sum\limits_{k=0}^{\infty} \frac{k!\times \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)} s^{-k}.
\end{equation}
are valid for all $s\in {\mathbb C}\setminus \{0\}$.
\end{theorem}

