\section{Laplace transforms of the derivatives of the Wright function}
\label{Laplace_W}

In this section we provide formulas of the Laplace transforms of the derivatives with respect to parameters of the Wright function (which can be considered for the following real values of parameters $\alpha > - 1, \beta\in {\mathbb R}$)
\begin{equation}
\label{Wright1}
\phi(\alpha,\beta;z) = W_{\alpha,\beta}(z) = \sum\limits_{k=0}^{\infty} \frac{z^k}{k! \Gamma(\alpha k + \beta)}.
\end{equation}
Two formulas of the Laplace transforms of this function are known.The first one represents the Laplace transforms in terms of the Mittag-Leffler function (\ref{2parML1}) in the case $\alpha > 0$
\begin{equation}
\label{LapWright1}
{\mathcal L} \left[W_{\alpha,\beta}(\pm t)\right](s) = \frac{1}{s} E_{\alpha,\beta}(\pm s^{-1}).
\end{equation}
As in Theorem \ref{Thm2.1} we can justify the following formulas of the Laplace transforms of the derivatives with respect to parameters:
\begin{theorem}
\label{Thm3.1}
Let $\alpha > 0, \beta > 0$. Then the following formulas for the Laplace transforms of the derivatives of $W_{\alpha,\beta}(t)$ have the form.
\begin{equation}
\label{LapWright1a}
{\mathcal L} \left(\frac{\partial}{\partial \alpha} \left[W_{\alpha,\beta}(\pm t)\right]\right)(s) = - \frac{1}{s} \sum\limits_{k=0}^{\infty} \frac{\pm s^{- k} k \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)},
\end{equation}
\begin{equation}
\label{LapWright1b}
{\mathcal L} \left(\frac{\partial}{\partial \beta} \left[W_{\alpha,\beta}(\pm t)\right]\right)(s) = - \frac{1}{s} \sum\limits_{k=0}^{\infty} \frac{\pm s^{- k} \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)}.
\end{equation}
are valid for all $s\in {\mathbb C}\setminus \{0\}$.
\end{theorem}

Second variant of the Laplace transform of the Wright function is similar to formulas (\ref{2parML3a}), (\ref{2parML3b}).
\begin{equation}
\label{LapWright2}
{\mathcal L} \left(t^{\beta - 1} \left[W_{\alpha,\beta}(\lambda t^{\alpha})\right]\right)(s) = \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \frac{(\lambda s^{-\alpha})^k}{k!} = \frac{1}{s^{\beta}} e^{\lambda s^{-\alpha}}.
\end{equation}
\begin{corollary}
\label{Cor3.1}
Let $\alpha > 0, \beta > 0$. Then the following formulas for the Laplace transforms of the derivatives have the form.
\begin{equation}
\label{LapWright2a}
{\mathcal L} \left(\frac{\partial}{\partial \alpha} t^{\beta - 1} \left[W_{\alpha,\beta}(\lambda t^{\alpha})\right]\right)(s) = \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \frac{(\lambda s^{-\alpha})^k}{k!} = \frac{-\lambda \ln\, s}{s^{\alpha + \beta}} e^{\lambda s^{-\alpha}},
\end{equation}
\begin{equation}
\label{LapWright2b}
{\mathcal L} \left(\frac{\partial}{\partial \beta} t^{\beta - 1} \left[W_{\alpha,\beta}(\lambda t^{\alpha})\right]\right)(s) = \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \frac{(\lambda s^{-\alpha})^k}{k!} = \frac{- \ln\, s}{s^{\beta}} e^{\lambda s^{-\alpha}}.
\end{equation}
are valid for all $s\in {\mathbb C}, {\mathrm{Re}}\, s > 0$.
\end{corollary}

