\section{Laplace transforms of the derivatives of the three- and four-parametric Mittag-Leffler functions}
\label{Laplace_3-4M-L}

The most useful for applications among the multi-parametric functions is the so called Prabhakar function (see, e.g., \cite[Sec. 5.1]{GKMR})
\begin{equation}
\label{3parML1}
E_{\alpha,\beta}^{\gamma}(z) = \sum\limits_{k=0}^{\infty} \frac{(\gamma)_k z^k}{\Gamma(\alpha k + \beta)} =
\sum\limits_{k=0}^{\infty} \frac{\Gamma(\gamma) z^k}{\Gamma(\gamma + k)\Gamma(\alpha k + \beta)}.
\end{equation}
The Laplace transforms of the Prabhakar function is given by the following formula
\begin{equation}
\label{Lap3parML1}
{\mathcal L}\left(t^{\beta - 1} E_{\alpha,\beta}^{\gamma}(\lambda t^{\alpha})\right)(s) = \frac{s^{\alpha \gamma - \beta}}{(s^{\alpha} - \lambda)^{\gamma}};\;
\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0;\;\;\; |\lambda s^{-\alpha}| < 1.
\end{equation}
In a way similar to that of Theorem \ref{Thm2.1} we can justify the following formulas of the Laplace transforms of the derivatives of this function with respect to parameters.
\begin{theorem}
\label{Thm4.1}
Let $\alpha, \beta, \gamma > 0$. Then the following formulas of the Laplace transform of the derivatives with respect to parameters are satisfied:
\begin{equation}
\label{Lap3parML2a}
{\mathcal L} \left(\frac{\partial}{\partial \alpha} \left[t^{\beta - 1} E_{\alpha,\beta}^{\gamma}(\lambda t^{\alpha})\right]\right)(s) = \frac{- \gamma \lambda s^{\alpha \gamma - \beta} \ln\,s}{(s^{\alpha} - \lambda)^{\gamma + 1}};\;
\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0;\;\;\; |\lambda s^{-\alpha}| < 1.
\end{equation}
\begin{equation}
\label{Lap3parML2b}
{\mathcal L} \left(\frac{\partial}{\partial \beta} \left[t^{\beta - 1} E_{\alpha,\beta}^{\gamma}(\lambda t^{\alpha})\right]\right)(s) = \frac{-  s^{\alpha \gamma - \beta} \ln\,s}{(s^{\alpha} - \lambda)^{\gamma}};\;
\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0;\;\;\; |\lambda s^{-\alpha}| < 1.
\end{equation}
\begin{equation}
\label{Lap3parML2c}
{\mathcal L} \left(\frac{\partial}{\partial \gamma} \left[t^{\beta - 1} E_{\alpha,\beta}^{\gamma}(\lambda t^{\alpha})\right]\right)(s) = \frac{s^{\alpha \gamma - \beta}}{(s^{\alpha} - \lambda)^{\gamma}}\left[- \alpha  \ln\,s +  \ln\,(s^{\alpha} - \lambda)\right];
\end{equation}
$$
\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0;\;\;\; |\lambda s^{-\alpha}| < 1.
$$
\end{theorem}

The second variant of the Laplace has the following form
\begin{equation}
\label{Lap3parML3}
{\mathcal L}\left(t^{\gamma - 1} E_{\alpha,\beta}^{\gamma}(t)\right)(s) = \Gamma(\gamma) \sum\limits_{k=0}^{\infty} \frac{s^{-\gamma - k}}{\Gamma(\alpha k + \beta)} = \frac{\Gamma(\gamma)}{s^{\gamma}} E_{\alpha,\beta}\left(\frac{1}{s}\right);\;
{\mathrm{Re}}\, s > 0.
\end{equation}
\begin{corollary}
Let $\alpha, \beta, \gamma > 0$. Then the
 following formulas of the Laplace transforms of the derivatives with respect to parameters of the function $t^{\gamma - 1} E_{\alpha,\beta}^{\gamma}(t)$ are satisfied for ${\mathrm{Re}}\, s > 0$
\begin{equation}
\label{Lap3parML4a}
{\mathcal L}\left(\frac{\partial}{\partial \alpha} \left[t^{\gamma - 1} E_{\alpha,\beta}^{\gamma}(t)\right]\right)(s) = -  \frac{\Gamma(\gamma)}{s^{\gamma}} \sum\limits_{k=0}^{\infty} \frac{k \psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)} \frac{1}{s^k}.
\end{equation}
\begin{equation}
\label{Lap3parML4b}
{\mathcal L}\left(\frac{\partial}{\partial \beta} \left[t^{\gamma - 1} E_{\alpha,\beta}^{\gamma}(t)\right]\right)(s) = -  \frac{\Gamma(\gamma)}{s^{\gamma}} \sum\limits_{k=0}^{\infty} \frac{\psi(\alpha k + \beta)}{\Gamma(\alpha k + \beta)} \frac{1}{s^k}.
\end{equation}
\begin{equation}
\label{Lap3parML4c}
{\mathcal L}\left(\frac{\partial}{\partial \gamma} \left[t^{\gamma - 1} E_{\alpha,\beta}^{\gamma}(t)\right]\right)(s) = \frac{\Gamma(\gamma) [\psi(\gamma) - \ln\, s]}{s^{\gamma}} E_{\alpha,\beta}\left(\frac{1}{s}\right).
\end{equation}
\end{corollary}

The results for the four-parametric Mittag-Leffler function
\begin{equation}
\label{4parML1}
E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(z) = \sum\limits_{k=0}^{\infty} \frac{z^k}{\Gamma(\alpha_1 k + \beta_1) \Gamma(\alpha_2 k + \beta_2)}.
\end{equation}
are similar to the obtained above. For instance we can use the following formula for the Laplace transforms ($\lambda\in {\mathbb R};\; {\mathrm{Re}}\, s > 0$):
\begin{equation}
\label{Lap4parML2}
{\mathcal L} \left(t^{\beta_1 - 1} E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(\lambda t^{\alpha_1})\right)(s) = \frac{1}{s^{\beta_1}} \sum\limits_{k=0}^{\infty} \frac{(\lambda s^{-\alpha_1})^k}{\Gamma(\alpha_2 k + \beta_2)} = \frac{1}{s^{\beta_1}} E_{\alpha_2,\beta_2}(\lambda s^{-\alpha_1}).
\end{equation}
\begin{theorem}
\label{Thm4.2}
Let $\alpha_1, \alpha_2, \beta_1, \beta_2 > 0$
Then the following formulas of the Laplace transforms of the derivatives are satisfied for ${\mathrm{Re}}\, s > 0$.
\begin{equation}
\label{Lap4parML3a1}
{\mathcal L} \left(\frac{\partial}{\partial \alpha_1} \left[t^{\beta_1 - 1} E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(\lambda t^{\alpha_1})\right]\right)(s) =
- \frac{1}{s^{\beta_1}} \sum\limits_{k=0}^{\infty} \frac{k (\lambda s^{-\alpha_1})^k}{\Gamma(\alpha_2 k + \beta_2)}.
\end{equation}
\begin{equation}
\label{Lap4parML3b1}
{\mathcal L} \left(\frac{\partial}{\partial \beta_1} \left[t^{\beta_1 - 1} E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(\lambda t^{\alpha_1})\right]\right)(s) =
- \frac{\ln\, s}{s^{\beta_1}} E_{\alpha_2,\beta_2}(\lambda s^{-\alpha_1}).
\end{equation}
\begin{equation}
\label{Lap4parML3a2}
{\mathcal L} \left(\frac{\partial}{\partial \alpha_2} \left[t^{\beta_1 - 1} E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(\lambda t^{\alpha_1})\right]\right)(s) =
- \frac{1}{s^{\beta_1}} \sum\limits_{k=0}^{\infty} \frac{k \psi(\alpha_2 k + \beta_2)}{\Gamma(\alpha_2 k + \beta_2)} (\lambda s^{-\alpha_1})^k.
\end{equation}
\begin{equation}
\label{Lap4parML3b2}
{\mathcal L} \left(\frac{\partial}{\partial \beta_2} \left[t^{\beta_1 - 1} E_{(\alpha_1,\beta_1),(\alpha_2,\beta_2)}(\lambda t^{\alpha_1})\right]\right)(s) =
- \frac{1}{s^{\beta_1}} \sum\limits_{k=0}^{\infty} \frac{\psi(\alpha_2 k + \beta_2)}{\Gamma(\alpha_2 k + \beta_2)} (\lambda s^{-\alpha_1})^k.
\end{equation}
\end{theorem}

