\section{Laplace transforms of the derivatives of the Le Roy type function}
\label{Laplace_Le Roy}

Here we deal with the Laplace transforms of the derivatives of the Le Roy type function (see, e.g., \cite[Sec. 5.3]{GKMR}, \cite{RogDub23}, \cite{RogDub24})
\begin{equation}
\label{LeRoy1}
F_{\alpha,\beta}^{(\gamma)}(z) = \sum\limits_{k=0}^{\infty} \frac{z^k}{[\Gamma(\alpha k + \beta)]^{\gamma}}
\end{equation}
which generalizes the function
\begin{equation}
\label{LeRoy0}
R_{\gamma}(z) = \sum\limits_{k=0}^{\infty} \frac{z^k}{[k!]^{\gamma}},
\end{equation}
introduced by E. Le Roy at the end of XIX century for the study of the analytic continuation of power series.

Let us calculate the Laplace transforms of the Le Roy type function taken in the form similar to (\ref{Lap2parML2}), (\ref{LapWright1a}), (\ref{Lap3parML3})
\begin{equation}
\label{LapLeRoy1}
{\mathcal L}\left(t^{\gamma - 1} F_{\alpha,\beta}^{(\gamma)}(\lambda t^{\alpha})\right)(s) = \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \frac{(\lambda s^{-\alpha})^k}{[\Gamma(\alpha k + \beta)]^{\gamma - 1}} = \frac{1}{s^{\beta}} F_{\alpha,\beta}^{(\gamma)}\left(\frac{\lambda}{s^{\alpha}}\right);
\end{equation}
$$
\lambda\in {\mathbb R},\; {\mathrm{Re}}\, s > 0;\; \gamma > 1.
$$
In particular, for $\gamma = 2$ the Laplace transforms image is related to the Mittag-Leffler function
\begin{equation}
\label{LapLeRoy2}
{\mathcal L}\left(t^{\gamma - 1} F_{\alpha,\beta}^{(2)}(\lambda t^{\alpha})\right)(s) = \frac{1}{s^{\beta}} E_{\alpha,\beta}\left(\frac{\lambda}{s^{\alpha}}\right).
\end{equation}
\begin{theorem}
\label{Thm5.1} Let $\alpha > 0, \beta > 0, \gamma > 1$.
Then the formulas of the Laplace transforms of the derivatives have the following forms ($\lambda\in {\mathbb R},\; {\mathrm{Re}}\, s > 0$):
\begin{equation}
\label{LapLeRoy3a}
{\mathcal L} \left(\frac{\partial}{\partial \alpha} \left[t^{\gamma - 1} F_{\alpha,\beta}^{(\gamma)}(\lambda t^{\alpha})\right]\right)(s) =
- \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} k \left(\frac{\lambda}{s^{\alpha}}\right)^k \frac{\ln\, s + (\gamma - 1) \psi(\alpha k + \beta)}{[\Gamma(\alpha k + \beta)]^{\gamma - 1}};
\end{equation}
\begin{equation}
\label{LapLeRoy3b}
{\mathcal L} \left(\frac{\partial}{\partial \beta} \left[t^{\gamma - 1} F_{\alpha,\beta}^{(\gamma)}(\lambda t^{\alpha})\right]\right)(s) =
- \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \left(\frac{\lambda}{s^{\alpha}}\right)^k \frac{\ln\, s + (\gamma - 1) \psi(\alpha k + \beta)}{[\Gamma(\alpha k + \beta)]^{\gamma - 1}};
\end{equation}
\begin{equation}
\label{LapLeRoy3c}
{\mathcal L} \left(\frac{\partial}{\partial \gamma} \left[t^{\gamma - 1} F_{\alpha,\beta}^{(\gamma)}(\lambda t^{\alpha})\right]\right)(s) =
- \frac{1}{s^{\beta}} \sum\limits_{k=0}^{\infty} \left(\frac{\lambda}{s^{\alpha}}\right)^k \frac{\ln\, \Gamma(\alpha k + \beta)}{[\Gamma(\alpha k + \beta)]^{\gamma - 1}}.
\end{equation}
\end{theorem}

