\title{Topological Reality Switch: Towards Bulk-Boundary Selective Lasing}
\author{Sayed Ali Akbar Ghorashi$^{1}$}\email[Correspondence\,to:\,]{sayedaliakbar.ghorashi@stonybrook.edu}
\author{Masatoshi Sato$^{2}$}
