\begin{center}
% \includegraphics[width=8.6cm,height=6cm]{kgate_simulated.png}
\includegraphics[trim=0.1cm 0.3cm 0.55cm 0.3cm, clip,scale=0.49]{kGate_combined.png}
\end{center}
\caption{\label{fig:kingate1} a) Simulated kinematic gate that represents the correlation between the energy of the breakup $\alpha$ particles and the recoil $^{12}\mathrm{C}$. b) Simulated kinematic gate that gives the allowed range of the breakup $\alpha$ particle energies as a function of their detected lab angle.} 
\end{figure}


