These tables illustrate the mapping from binary strings to their encoded agreement probability vectors, providing concrete examples that will clarify the structure of our enumeration formulas.

One of the first things to notice in the tables is the monotonicity of $\lambdahash$. We will prove this important property at the end of this section. Prior to that, there is a lemma stating a recursive rule for the string-level map.

\begin{Lemma}[Recursive Rule for $\lambda^s$] \label{lemma:lambda-recursion}
Let $\bx_s \in \{0,1\}^k$, with $k \geq 2$. Then
\begin{align*}
\lambda^s(0 \mathbin{\|} \bx_s) &= \overline{\bx_s} \mathbin{\|} \lambda^s(\bx_s), \\
\lambda^s(1 \mathbin{\|} \bx_s) &= \bx_s \mathbin{\|} \lambda^s(\bx_s),
\end{align*}
where $\overline{\bx_s}$ denotes the bitwise complement of $\bx_s$.
\end{Lemma}

Before proving the lemma, we present two examples that illustrate the recursive rule.
\begin{Example}
Let $\bx_s = 100$. Then $\lambda^s(0 \mathbin{\|} \bx_s) = \lambda^s(0100)$. From Table~\ref{table:n34} ($n=4$), we know that
\[
\lambda^s(0100) = 011001.
\]
If we apply Lemma~\ref{lemma:lambda-recursion} to the same string,
\[
\lambda^s(0 \mathbin{\|} 100) = \overline{100} \mathbin{\|} \lambda^s(100) 
\]
and reading $\lambda^s(100)$ from Table~\ref{table:n34} ($n=3$), we obtain the same result $011 \mathbin{\|} 001 = 011001$.
\end{Example}

Let's take another example with a string that starts with $1$.
\begin{Example}
We see that $\lambda^s(1100) = 100001$ from Table~\ref{table:n34}. Applying Lemma~\ref{lemma:lambda-recursion}, the same string is obtained:
\[
\lambda^s(1 \mathbin{\|} 100) = 100 \mathbin{\|} \lambda^s(100) = 100 \mathbin{\|} 001 = 100001.
\]
\end{Example}

\begin{proof}
Let $\bx = (x_1, \ldots, x_k) \in \{0,1\}^k$. Then
\[
\lambda^s(0 \mathbin{\|} \bx) = \ind(0 = x_1)\, \ldots\, \ind(0 = x_k) \mathbin{\|} \lambda^s(\bx).
\]
Observe that
\[
\ind(0 = x_i) =
\begin{cases}
1 & \text{if } x_i = 0, \\
0 & \text{if } x_i = 1,
\end{cases}
= \overline{x_i},
\]
which proves the first identity. The second follows similarly, since
\[
\lambda^s(1 \mathbin{\|} \bx) = \ind(1 = x_1)\, \ldots\, \ind(1 = x_k) \mathbin{\|} \lambda^s(\bx),
\]
and clearly $\ind(1 = x_i) = x_i$.
\end{proof}

Throughout this paper, we use the standard lexicographic order on binary vectors, denoted $>_{\mathrm{lex}}$ and $\geq_{\mathrm{lex}}$, as defined below.

%\begin{Definition}[Lexicographic order]
%Let $\mathbf{a} = (a_1, \ldots, a_m)$ and $\mathbf{b} = (b_1, \ldots, b_m)$ be two binary vectors (or strings) of equal length $m$. We say that $\mathbf{a}$ is \emph{lexicographically greater than} $\mathbf{b}$, denoted $\mathbf{a} >_{\mathrm{lex}} \mathbf{b}$, if there exists an index $k$ such that $a_i = b_i$ for all $i < k$ and $a_k > b_k$. Similarly, $\mathbf{a}$ is \emph{lexicographically less than} $\mathbf{b}$, denoted $\mathbf{a} <_{\mathrm{lex}} \mathbf{b}$, if $a_i = b_i$ for all $i < k$ and $a_k < b_k$ for the first such $k$.
%\end{Definition}

\begin{Definition}[Lexicographic Order] \label{def:lex}
Let $x = (x_1, x_2, \dots, x_n)$ and $y = (y_1, y_2, \dots, y_n)$ be two binary strings or vectors of length $n$, where each $x_i, y_i \in \{0,1\}$.  
We say that $x$ is less than or equal to $y$ in the \emph{lexicographic order}, denoted $x \leq_{\mathrm{lex}} y$, if one of the following holds:
\begin{itemize}
  \item $x = y$, or
  \item there exists an index $k \in \{1, \dots, n\}$ such that
  \begin{itemize}
    \item $x_i = y_i$ for all $i < k$, and
    \item $x_k < y_k$.
  \end{itemize}
\end{itemize}
In the case where $x \neq y$, we write $x <_{\mathrm{lex}} y$. Similarly, we define $x \geq_{\mathrm{lex}} y$ if $y \leq_{\mathrm{lex}} x$.
\end{Definition}


For example, $(0,1,1,0) <_{\mathrm{lex}} (0,1,1,1)$ and $(1,0,0) >_{\mathrm{lex}} (0,1,1)$. Also $0110 <_{\mathrm{lex}} 0111$ and $ 011 <_{\mathrm{lex}} 100$.

\begin{Remark} 
For binary strings of the same fixed length,
\[ \bx_s <_{\mathrm{lex}} \by_s \Leftrightarrow \code(\bx) < \code(\by).
\] 
\end{Remark}

\begin{Proposition}[Monotonicity of $\lambda^\#$] \label{prop:monotone}
Let $\bx, \by \in \{0,1\}^n$ be binary vectors with $x_1 = y_1 = 1$. If $\operatorname{code}(\bx) < \operatorname{code}(\by)$, then $\lambda^\#(\bx) < \lambda^\#(\by)$.
\end{Proposition}

\begin{proof}
Suppose $\bx_s$ and $\by_s$ are two binary strings of length $n$ with leading digit $1$, such that $\operatorname{code}(\bx) < \operatorname{code}(\by)$ and $\operatorname{code}(\bx) = 2^{n-1} + z$ for some $z < 2^{n-1}-1$, so that $\operatorname{code}(\by) = \operatorname{code}(\bx) + 1 = 2^{n-1} + z + 1$.

Then $\bx_s = 1 \mathbin{\|} z_s$ and $\by_s = 1 \mathbin{\|} (z+1)_s$, where $z_s$ and $(z+1)_s$ denote the $n-1$-bit binary representations of $z$ and $z+1$, respectively.

By Lemma~\ref{lemma:lambda-recursion}, we have:
\begin{align*}
\lambda^s(\by_s) &= (z+1)_s \mathbin{\|} \lambda^s((z+1)_s) \\
                 &>_{\mathrm{lex}} z_s \mathbin{\|} 11\ldots1 \\
                 &\geq_{\mathrm{lex}} z_s \mathbin{\|} \lambda^s(z_s) = \lambda^s(\bx_s).
\end{align*}
The first inequality follows from the strict increase in the left part of the string, and the second from the fact that $\lambda^s(z_s) \leq_{\mathrm{lex}} 11\ldots1$ for  binary strings of the same length.

Clearly the inequality holds for integer-valued map also  and $\lambda^\#(\by) > \lambda^\#(\bx)$, as desired.
\end{proof}

