The observed near-linear alignment of encoded vertices is not merely a numerical coincidence, but can be formalized as follows.

%The almost linear ordering of encoded vertices is formalized in the following statement.

\begin{Proposition}[Almost linear ordering of vertices]
For $n \geq 2$, $k=1,\ldots,2^{n-1}$ and $v^n(k) = \lambda^\#(a_k^n)$,
\[
k-1 \leq \frac{v^n(k)}{2^{\binom{n-1}{2}}} < k.
\]
\end{Proposition}
\begin{proof}
Using the recursive rule for $\lambdas$ Lemma~\ref{lemma:lambda-recursion}, the string version of $v^n(k)$ satisfies
\[
v^n(k)_s = \lambda^s(1 \parallel (k-1)_{s[n-1]}) = (k-1)_{s[n-1]} \parallel \lambda^s((k-1)_{s[n-1]}).
\]
Therefore,
\begin{equation}\label{eq:firstrec}
v^n(k) = (k-1) 2^{\binom{n-1}{2}} + \code(\lambda^s((k-1)_{s[n-1]})).
\end{equation}
Since $\lambda^s((k-1)_{s[n-1]})$ has $\binom{n-1}{2}$ bits, $\code(\lambda^s((k-1)_{s[n-1]})) < 2^{\binom{n-1}{2}}$. Dividing by $2^{\binom{n-1}{2}}$ gives the result.
\end{proof}

Equations in the previous proof imply a recursive relation between $v^n(\cdot)$ and $v^{n-1}(\cdot)$ which we formalize next.

This recursive structure is further explored in Section~6, where we introduce the alternating cycle function and its role in the explicit formula for $v^n(k)$.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection*{Recursion}

\begin{Proposition}[Recursive relation between $\vn$s] If  $n \geq 3$ and $\vn()$ are encoded vertices of $1-\cut(n)$ then 

\begin{eqnarray} \label{recursion}
\vn(k)=   2^{ n -1 \choose 2} (k-1) + 
 \begin{cases}
      v^{n-1}(2^{n-2}+1-k) & \text{  for  } k \in \{1,\ldots,2^{n-2}\}\\
       v^{n-1}(k-2^{n-2}) & \text{  for  } k \in \{2^{n-2}+1,\ldots,2^{n-1}\}.
    \end{cases}    
\end{eqnarray}

 \end{Proposition}

 \begin{proof}
 For $n \geq 2$, $k=1,\ldots,2^{n-1}$ let's look again at $\lambdas((k-1)_{s[n-1]})$ in Equation (\ref{eq:firstrec}). 
 \begin{enumerate}
 \item 
 If $k \in \{1,\ldots,2^{n-2}\}$ then $k-1 \in \{0,\ldots,2^{n-2}-1\}$ and in its binary represenatation using $n-1$ bits means that the first bit will be $0$. Then 
 \[
 \lambdas((k-1)_{s[n-1]})= \lambdas(0 \parallel (k-1)_{s[n-2]}) = \overline{(k-1)_{s[n-2]}} \parallel \lambdas((k-1)_{s[n-2]})
 \]
by Lemma \ref{lemma:lambda-recursion}.
Then, remembering that $\lambdas(\bx_{s[n-2]})=\lambdas(\overline{\bx_{s[n-2]}})$ and that $\code(\bar{\bx})=(2^{n-1}-1)-\code(\bx)$
\begin{eqnarray*}
\code( \lambdas((k-1)_{s[n-1]})) &=&   (2^{n-1}-1-(k-1))\,2^{n-2 \choose 2} + \code (\lambdas((k-1)_{s[n-2]}))  \nonumber \\
                                                    &=& ((2^{n-1}- (k-1))-1))\,2^{n-2 \choose 2} + \code (\lambdas((2^{n-1}- (k-1))_{s[n-2]})) \nonumber \\
            \mbox{by (\ref{eq:firstrec})}  &=& v^{n-1} (2^{n-2}-(k-1)). 
\end{eqnarray*}

\item For $k \in \{2^{n-2}+1,\ldots,2^{n-1}\}$ the binary represenatation of $k-1$ using $n-1$ bits and its complement in binary representation, whose integer value is $2^{n-1}-1-(k-1) \leq 2^{n-2}$ and we can apply  the previous case result
\[
 \code(\lambdas((k-1)_{s[n-1]}))= \code(\lambdas(2^{n-1}-k)_{s[n-1]})= v^{n-1}(2^{n-2}-2^{n-1}+k)=v^{n-1}(k-2^{n-2}).
 \]
\end{enumerate} 
Combining both cases yields the stated recursion.
 \end{proof}


The recursion  \ref{recursion} relates $k$ to $2^{n-2}+1-k$ or $k-2^{n-2}$ depending on whether $k$ is in the first or second half of the $\{1,\ldots,2^{n-1}\}$.  This map will be defined using a function that we named {\em Alternating Cycle Function}. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Beyond their linear and recursive properties, the encoded vertices exhibit striking symmetries and fractal patterns, which are governed by a new integer-valued function introduced below.
\section{Symmetries and Fractal Properties}

\begin{Definition}[Alternating Cycle Function] \label{def:SN}
For integers \(N \geq 2\), the \emph{Alternating Cycle function} \(S^N \colon \mathbb{N} \to \mathbb{N}\) is defined as:
\[
S^N(k) = 
\begin{cases} 
N + 1 - \left(k - \left\lfloor \frac{k-1}{N} \right\rfloor N\right), & \text{if } \left\lfloor \frac{k-1}{N} \right\rfloor \text{ is even}, \\ 
k - \left\lfloor \frac{k-1}{N} \right\rfloor N, & \text{if } \left\lfloor \frac{k-1}{N} \right\rfloor \text{ is odd}
\end{cases}
\]
for all $k \in \N$.
\end{Definition}

Having this definition we can rewrite the recursion between vertices $\vn$ as
\begin{equation} \label{eq:vertsn}
v^n(k) = 2^{\binom{n-1}{2}} (k - 1) + v^{n-1}\left(S^{2^{n-2}}(k)\right).
\end{equation}
This motivates study of the alternating cycle function which follows.
\vskip5mm
