\section{Derivation of the AGP and LIOM Corrections for Free Fermions}\label{app:appendix_agp_derivation}

In this section, we provide derivation details for the Adiabatic Gauge Potential (AGP) with a free fermion Hamiltonian, perturbed by nearest-neighbor density-density interactions. 

We wish to find the generator $\hat X$ such that 
\begin{equation*}
    i [\hat X,\hat H_0] = \hat V_{\text{off-diag}}.
\end{equation*}
For $\hat H_0$, we have a free-fermion Hamiltonian: 
\begin{equation}
    \hat H_0=\sum_{jk} A_{jk} \hat c^{\dagger}_{j}\hat c_{k}= \sum_{jk} \left(\sum_\alpha \phi_{j \alpha}\epsilon_\alpha \phi_{k \alpha}^* \right) \hat c_j^\dagger \hat c_k=\sum_\alpha \epsilon_\alpha \hat d_\alpha^\dagger \hat d_\alpha.
\end{equation}
Here, we have defined $\hat d_\alpha= \sum_k \phi_{k\alpha}^* \hat c_k$.

We consider a perturbation $\hat V$ consisting of nearest-neighbor interactions:
\begin{align}
    \hat V&=\sum_j \hat n_j \hat n_{j+1}\\
    &=\frac{1}{4}\sum_j (\hat c_{j+1}^\dagger \hat c_{j}^\dagger \hat c_j \hat c_{j+1}-\hat c_{j}^\dagger \hat c_{j+1}^\dagger \hat c_j \hat c_{j+1} \\&-\hat c_{j+1}^\dagger \hat c_{j}^\dagger \hat c_{j+1} \hat c_{j}+\hat c_{j}^\dagger \hat c_{j+1}^\dagger \hat c_{j+1} \hat c_{j}).
\end{align}
Here, we use this form because we aim to unambiguously associate a tensor $V_{ijkl}$ to the quartic operator $\hat V$, such that $\hat V = \sum_{ijkl} V_{ijkl} \hat c_i^\dagger \hat c_j^\dagger \hat c_k \hat c_l$.
To avoid the ambiguity associated with transformations of the form $\hat V \rightarrow \hat V+\gamma (\hat c_i^\dagger \hat c_j^\dagger+\hat c_j^\dagger \hat c_i^\dagger)\hat c_k \hat c_l = \hat V$, we require that $V_{ijkl} = -V_{jikl} = -V_{ijlk}$. 

Now, we rewrite $\hat V$ in terms of $\hat{d}_\alpha$, noting that $\hat c_j=\sum_\alpha \phi_{j\alpha} \hat d_\alpha$. With this transformation, $\hat V$ takes on the form:
\begin{equation}
    \hat V=\frac{1}{4}\sum_{\alpha \beta \gamma \delta}V_{\alpha \beta \gamma \delta} \hat d_\alpha^\dagger \hat d_\beta^\dagger \hat d_\gamma \hat d_{\delta},
\end{equation}
with matrix elements
\begin{multline}
    V_{\alpha \beta \gamma \delta}=\frac{1}{4}\sum_j(\phi_{j+1,\alpha}^* \phi_{j,\beta}^* \phi_{j,\gamma} \phi_{j+1,\delta}-\phi_{j,\alpha}^* \phi_{j+1,\beta}^* \phi_{j,\gamma} \phi_{j+1, \delta}\\
    -\phi_{j+1, \alpha}^* \phi_{j, \beta}^* \phi_{j+1, \gamma} \phi_{j, \delta}+\phi_{j, \alpha}^* \phi_{j+1,\beta}^* \phi_{j+1,\gamma} \phi_{j,\delta}).
\end{multline}
This tensor has the required property that $V_{\alpha\beta\gamma\delta} = -V_{\beta\alpha\gamma\delta} = -V_{\alpha\beta\delta\gamma}$.
Now, we consider the following ansatz for $\hat X$:
\begin{equation*}
    \hat X=\sum_{\alpha, \beta,\gamma,\delta }X_{\alpha\beta\gamma\delta}\hat{d}_\alpha^\dagger \hat{d}_\beta^\dagger \hat{d}_\gamma \hat{d}_\delta.
\end{equation*}
We want to express $X_{\alpha\beta\gamma\delta}$ in terms of $V_{\alpha \beta \gamma \delta}$. To do so, we invoke the following property:
\begin{align*}
\bigl[\hat{c}_i^\dagger\,\hat{c}_j^\dagger\hat{c}_k\,\hat{c}_l,
\hat{c}_n^\dagger\hat{c}_m\bigr]
=
\delta_{l n}\,\hat{c}_i^\dagger\hat{c}_j^\dagger\,\hat{c}_k\hat{c}_m
 - 
\delta_{i m}\,\hat{c}_n^\dagger\hat{c}_j^\dagger\hat{c}_k\hat{c}_l
\\ +
\delta_{k n}\hat{c}_i^\dagger\hat{c}_j^\dagger\hat{c}_m\,\hat{c}_l
 -
\delta_{j m}\,\hat{c}_i^\dagger\hat{c}_n^\dagger\,\hat{c}_k\hat{c}_l.
\end{align*}
From this, one finds that:
\begin{align}
    V_{\alpha \beta \gamma \delta} &=i \sum_{\sigma} (A_{\sigma\delta} X_{\alpha \beta \gamma \sigma} - A_{\alpha \sigma} X_{\sigma \beta \gamma \delta} \\
    &\qquad + A_{\sigma \gamma} X_{\alpha \beta \sigma \delta} - A_{\beta \sigma} X_{\alpha \sigma \gamma \delta})\\
    &=i(\epsilon_\delta-\epsilon_\alpha+\epsilon_\gamma-\epsilon_\beta)X_{\alpha\beta\gamma\delta}.
\end{align}
We thus define
\begin{equation}
    X_{\alpha\beta\gamma\delta}=
    \begin{cases}
        i\frac{V_{\alpha\beta\gamma\delta}}{\epsilon_\alpha+\epsilon_\beta-\epsilon_\gamma-\epsilon_\delta} & \epsilon_\alpha+\epsilon_\beta-\epsilon_\gamma-\epsilon_\delta\neq 0 \\
        0 & \epsilon_\alpha+\epsilon_\beta-\epsilon_\gamma-\epsilon_\delta=0.
    \end{cases}
\end{equation}
We can now compute the correction to the $\alpha$-th localized orbital:
\begin{equation}
    \tilde{n}_{\alpha}^{(1)} \equiv i[\hat X, \hat{d}_\alpha^\dagger \hat{d}_\alpha]=\sum_{\mu\nu\rho\sigma} f^\alpha_{\mu\nu\rho\sigma}\hat{d}_\mu^\dagger \hat{d}_\nu^\dagger \hat{d}_\rho \hat{d}_\sigma
\end{equation}
One can compute the coefficients $f^\alpha_{\mu\nu\rho\sigma}$ by evaluating the commutator:

\begin{equation}
f^\alpha_{\mu\nu\rho\sigma}=i(\delta_{\alpha \sigma} +\delta_{\alpha \rho} -\delta_{\alpha \mu} -\delta_{\alpha \nu}) X_{\mu\nu\rho \sigma}.
\end{equation}
We can also go back to real space to get:
\begin{equation}
    \tilde{n}_{\alpha}^{(1)}=\sum_{jklm} g^\alpha_{jklm} \hat{c}_j^\dagger \hat{c}_k^\dagger \hat{c}_l \hat{c}_m,
\end{equation}
With coefficients:
\begin{equation}
    g^\alpha_{jklm}=\sum_{\mu\nu\rho\sigma} f^\alpha_{\mu\nu\rho\sigma} \phi_{j\mu}\phi_{k\nu}\phi_{l\rho}^* \phi_{m\sigma}^*.
\end{equation}

\section{Hilbert-Schmidt product and Frobenius Norm of Fermionic Operators}\label{app:a_frobenius_norm_derivation}

In this section, we show how to compute the Hilbert-Schmidt inner product of two fermionic operators $\hat A, \hat B$, defined as $\braket{\hat A,\hat B}_{HS}\equiv \frac{1}{\mathcal D}\Tr[\hat A^\dagger \hat B]$, where $\mathcal D$ is the Hilbert space dimension.
We will use that $\frac{1}{\mathcal D}\Tr[\dots]$ is the thermal expectation value at infinite temperature, and Wick's theorem can be applied to express expectation values of products of four or more fermionic operators in terms of expectation values of fermion bilinears \cite{surace_fermionic_2022}, of the form $\braket{\hat c_i^\dagger \hat c_j}_{\beta=0}=\frac{1}{2}\delta_{ij}$ and $\braket{\hat c_i \hat c_j^\dagger}_{\beta=0}=\frac{1}{2}\delta_{ij}$.

\subsection{Quadratic Operators} \label{quadratic}
Let us consider the case of quadratic operators of the form
\begin{equation}
    \hat O_M = \sum_{ij}M_{ij}\hat c_i^\dagger \hat c_j.
\end{equation}
The Hilbert-Schmidt product of two operators of this form reads
\begin{align}
    \braket{\hat O_M, \hat O_N}_{HS}&=\braket{\hat O_M^\dagger \hat O_N}_{\beta=0}\nonumber\\
    &=\sum_{ijkl}M_{ij}^*N_{kl} \braket{\hat c^\dagger_j \hat c_i\hat c_k^\dagger \hat c_l }_{\beta=0}.
\end{align}
We now evaluate
\begin{equation}
\braket{\hat c^\dagger_j \hat c_i\hat c_k^\dagger \hat c_l }_{\beta=0}=\frac{1}{4}(\delta_{ij}\delta_{kl}+\delta_{jl}\delta_{ik}),    
\end{equation}
and we obtain
\begin{align}
 \braket{\hat O_M, \hat O_N}_{HS}&=  \frac{1}{4}\sum_{ij}(M_{ii}^*N_{jj}+M^*_{ij}N_{ij})\nonumber\\
 &=\frac{1}{4}(\Tr[M^\dagger]\Tr[N]+\Tr[M^\dagger N] ).
\end{align}

\subsection{Quartic Operators} \label{quartic}
We now consider the case of quartic operators of the form
\begin{equation}
    \hat Q_M
=\sum_{ijkl} M_{ijkl}\hat c_i^\dagger \hat c_j^\dagger \hat c_k \hat c_l
\end{equation}
with $M_{ijkl}=-M_{jikl}=-M_{ijlk}=M_{jilk}$ (note that the tensor $M$ can always be written in this form).

We can compute now the Hilbert-Schmidt product as
\begin{align}
    &\braket{\hat Q_M, \hat Q_N}_{HS}=\braket{\hat Q_M^\dagger \hat Q_N}_{\beta=0}\nonumber\\
    &\qquad =\sum_{ijkl}\sum_{pqrs}M_{ijkl}^*N_{pqrs}\braket{\hat c_l^\dagger \hat c_k^\dagger \hat c_j \hat c_i\hat c_p^\dagger \hat c_q^\dagger \hat c_r \hat c_s}_{\beta=0}.
\end{align}
The infinite temperature correlator can be computed using Wick's theorem, obtaining a sum over all of the 24 possible contractions (with signs).
The calculation can be simplified by noting that many of the contractions give the same results, thanks to the antisymmetric properties of the tensors. 
This produces three independent contractions, and we finally obtain
\begin{align}
    \braket{Q_M^\dagger, Q_N}_{HS}=& \frac{1}{4}\left(\sum_{ij}M^*_{ijij}\right)\left(\sum_{pq}N_{pqpq}\right) \nonumber\\
    &+\sum_{lkpq}M^*_{lklq}N_{pqpk}+\frac{1}{4}\sum_{lkpq}M^*_{lkpq}N_{pqlk}.
\end{align}

