\cline{5-11}
                                                          &                                                    &                                                              &       & \cellcolor[HTML]{bce784}$p\neq2$ & \multicolumn{2}{c|}{\cellcolor[HTML]{bce784}$p\neq 2,5$}                      & \cellcolor[HTML]{bce784}$p\neq 2,3,5$ & \multicolumn{2}{c|}{\cellcolor[HTML]{bce784}$p=2$}                  & \cellcolor[HTML]{bce784}$p=5$ \\ \hline
