\section{Fitting the gene expression data}\label{app:gamma_distributions}

Gene expression distributions observed in cell cultures are frequently long-tailed, and have been successfully modeled using e.g. gamma, negative binomial, or lognormal distributions. These choices are not only empirically well-matched to the data, but also mechanistically plausible in systems where gene expression is shaped by multiple interacting timescales \cite{koch_logarithm_1966, friedman_linking_2006, cai_stochastic_2006}. In our case, we find that our distributions are particularly well described by a gamma distribution:
\begin{equation}\label{eq:likelihood_app}
p(g  \vert  k, \theta, t) = \frac{1}{\Gamma(k) \theta^k t^k}g^{k-1} e^{-g/\theta t},
\end{equation}
parametrized by a constant shape parameter $k$ and a time-dependent scale parameter $\theta t$. In fact, one can show that this parametrization is our only choice given the observed functional behavior in Eqs. \ref{eq:linear_mean} and \ref{eq:quadratic_var}. Our aim here is to estimate parameters $k$ and $\theta$ from the data using a maximum-likelihood estimate. 

We denote the data for TopFlash as $g_{ij}$ and the signal durations as $t_i$, where $i=1, \dots, n$ and $j = 1, \dots, m_i$. The $i$th experimental condition is populated by $m_i$ different cells at the end of the experiment. The likelihood function is given by: 
\begin{equation}
\mathcal{L}(k,\theta) = \prod_{i=1}^n \prod_{j=1}^{m_i}  p (g_{ij}  \vert  k, \theta, t_i),
\end{equation} 
and hence our log-likelihood is
\begin{equation}
\begin{split}
\log( \mathcal{L}(k,\theta)) &= \sum_{i=1}^n \sum_{j=1}^{m_i} \log ( p (g_{ij} \vert  k, \theta, t_i) ) \\ 
&=  \sum_{i=1}^n \sum_{j=1}^{m_i} \bigg[ -\log( \Gamma(k) ) - k\log(\theta) - k \log (t_i) \\
&\quad + (k-1) \log(g_{ij}) -\frac{g_{ij}}{\theta t_i} \bigg].
\end{split}
\end{equation} 
Setting
\begin{equation}
\frac{\partial \log (\mathcal{L}) }{ \partial \theta } \bigg{\vert}_{\hat{k},\, \hat{\theta}} = 0,
\end{equation}
we obtain:
\begin{equation}
\hat{\theta} = \frac{1}{\hat{k}} \left( \frac{1}{\sum_{l=1}^n m_l} \sum_{i=1}^n \sum_{j=1}^{m_i} \frac{g_{ij}}{t_i} \right).
\end{equation}

Further, setting 
\begin{equation}
\frac{\partial \log (\mathcal{L}) }{ \partial k } \bigg{\vert}_{\hat{k},\, \hat{\theta}} = 0,
\end{equation}
we get:
\begin{equation}
\begin{split}
\psi^{(0)}(\hat{k}) &= \log ( \hat{k}) +  \frac{1}{\sum_{l=1}^n m_l} \sum_{i=1}^n \sum_{j=1}^{m_i}  \bigg[- \log (g_{ij}) \\ &\quad + \log \bigg( \frac{1}{\sum_{r=1}^n m_r} \sum_{p=1}^n \sum_{q=1}^{m_p} \frac{g_{pq}}{t_p} \bigg)  + \log(t_i) \bigg],
\end{split}
\end{equation}
where $\psi^{(0)}(k) = \mathrm{d} \log (\Gamma(k)) / \mathrm{d} k $ is the polygamma function of order $0$. We can solve this numerically for $\hat{k}$ without too much trouble, though we can continue analytically to very good approximation using the asymptotic expansion:
\begin{equation}
\psi^{(0)}(k) \sim \log (k) - \sum_{l=1}^\infty \frac{B_l}{l k^l}.
\end{equation}
Here $B_l$ are Bernouilli numbers with the convention $B_1 = +\frac{1}{2}$. Keeping the first two terms in the sum, we obtain the following estimator for $k$:
\begin{equation}
\hat{k} = \frac{1 + \sqrt{1+ \frac{4}{3} C }}{4 C },
\end{equation}
where
\begin{equation}
\begin{split}
C &= \frac{1}{\sum_{l=1}^n m_l} \sum_{i=1}^n \sum_{j=1}^{m_i}  \bigg[- \log (g_{ij}) \\ &\quad + \log \bigg( \frac{1}{\sum_{r=1}^n m_r} \sum_{p=1}^n \sum_{q=1}^{m_p} \frac{g_{pq}}{t_p} \bigg)  + \log(t_i) \bigg].
\end{split}
\end{equation}

We obtain:
\begin{align}
\hat{k} &= 2.88 \pm 0.01, \\
\hat{\theta} &= 23.0 \pm 0.1 \text{ hr}^{-1}.
\end{align}
where the error is obtained using the asymptotic normality of maximum-likelihood estimators.

The gamma distribution in Eq. \ref{eq:likelihood_app} has a singularity at $t=0$. The singularity is not physical, as it implies that any signal $t>0$ is perfectly distinguishable from $t=0$, and more importantly does not match the experimental data in this regime. To regularize the behavior of $p(g \vert t)$ near $t=0$, we add a small exponential term to the scale parameter:
\begin{align}
    \mu_{g}(t) &= k\theta (t + \epsilon e^{-a \theta t}), \label{eq:mean_corr}\\
    \sigma_{g}^2(t) &= k \theta^2(t + \epsilon e^{-a \theta t} )^2,\label{eq:var_corr}
\end{align}
where $\hat{\epsilon} = 0.86$ hr and $\hat{a}=0.05$ are positive constants which we estimate from the data. At times $t \gtrsim 1/\hat{a} \hat{\theta}$ the exponential term decays (Fig. \ref{fig:stdev_and_mean_tf}C) and we recover the functional form of Eq. \ref{eq:likelihood_app}. 

\section{Algorithm for computing the channel capacity}\label{ap:algorithms}

We want to maximize the mutual information $I(g ; t)$ with respect to the input distribution $p(t)$:
\begin{equation}\label{eq:channel_capacity_app}
    I_\star = \max_{p(t)} I(g;t),
\end{equation}
where $I_\star$ is the channel capacity and $p(g \vert t)$ is fixed. In most cases, this optimization is analytically intractable and we must proceed numerically. The Blahut-Arimoto (BA) algorithm is the standard algorithm for solving this problem \cite{blahut_computation_1972,arimoto_algorithm_1972}. 
One starts with an initial guess $p^{(0)}(t)$ for the input distribution, and with each iteration it is updated as follows:
\begin{equation}
    p^{(\tau)}(t) = \frac{1}{Z^{(\tau-1)}} p^{(\tau-1)}(t) \, e^{f^{(\tau -1)}_{\mathrm{KL}}(t)},
\end{equation}
where
\begin{equation}
    f^{(\tau)}_{\mathrm{KL}}(t) = \int_0^\infty \mathrm{d} g \, p(g \vert t) \, \mathrm{log} \bigg( \frac{p(g \vert t)}{p^{(\tau)}(g)}\bigg),
\end{equation}
and
\begin{equation}
    p^{(\tau)}(g) = \int_{0}^{T} \mathrm{d} t \, p(g \vert t) \, p^{(\tau)}(t).
\end{equation}
Practically, we restrict ourselves to a finite domain $t\in [0,T]$, where $T$ is the maximum signal duration.

After $\tau$ iterations, the lower bound to the channel capacity is given by:
\begin{equation}
    I_L^{(\tau)} = \frac{1}{\mathrm{log} \, 2}\int_{0}^T \mathrm{d} t \, p^{(\tau)}(t) \, f^{(\tau)}_{\text{KL}}(t),
\end{equation}
and an upper bound is given by:
\begin{equation}
    I_U^{(\tau)} = \max_{t} \frac{f^{(\tau)}_{\text{KL}}(t)}{\mathrm{log} \, 2}.
\end{equation}
As such, we iterate until convergence:
\begin{equation}
    I_U^{(\tau)} - I_L^{(\tau)} < \epsilon.
\end{equation}
and use $I_\star \approx I_L^{(\tau)}$ and $p_{\star}(t) \approx p^{\tau}(t)$ as our estimates for the channel capacity and the optimal input distribution, respectively. The optimization problem in Eq. \ref{eq:channel_capacity_app} is convex and guaranteed to converge to the global maximum \cite{cover_elements_2012}. 

As shown in Fig. \ref{fig:BA_convergence} in the main text and as noted by Mattingly et al. \cite{mattingly_maximizing_2018}, convergence to a discrete solution in the interior of the domain $t \in [0,T]$ is rather slow compared to the boundaries, especially when there is high density of delta functions. To overcome this, we can exploit the knowledge that $p_{\star}(t)$ is discrete by starting with a sum of $K$ delta functions:
\begin{equation}
    p(t) = \sum_{i=1}^K w_i \delta(t - t_i),
\end{equation}
and adjusting the weights $w_i$ and positions $t_i$ iteratively. Starting with $K$ equally spaced delta functions, we use the BA algorithm to adjust the weights $w_i$ until convergence. After this, we use the gradient:
\begin{equation}\label{eq:info_gradient}
    \frac{\partial I}{\partial t_i} = w_i \int_0^\infty \mathrm{d} g \, \frac{\partial p(g \vert t_i)}{\partial t_i} \, \mathrm{log}_2 \bigg( \frac{p(g \vert t_i)}{p(g)}\bigg),
\end{equation}
to adjust the positions $t_i$. Iterating the adjustment of the weights via the BA algorithm and the positions by gradient ascent, we can converge to the optimal discrete solution.

In contrast to the BA algorithm, the optimization over $w_i$ and $t_i$ is not convex: in particular, it depends on the number of peaks $K$ we define beforehand. After convergence, we can compute $f_{\text{KL}}(t)$ everywhere in the domain. If $\max_t f_{\text{KL}}(t)$ is greater than $f_{\text{KL}}(t)$ evaluated at any of the peaks $t_i$, we have to add another delta function \cite{mattingly_maximizing_2018}. This way, we ensure that (i) we have converged to the global maximum and (ii) that we have used the optimal number of delta functions. 

\section{Sufficient statistics for independent, identical, gamma-distributed variables}\label{app:sufficient_stats}

We find that there is negligible spatial correlation in the gene expression $g$. Hence, we can treat the cells as responding independently conditional on the Wnt signal $t$. Below, we show that when one considers a group of $N$ cells, the arithmetic mean $\bar{g}$ is a sufficient statistic for the signal duration $t$. That is, $\bar{g}$ contains as much information about $t$ as the whole dataset $\boldsymbol{g}$, as claimed in the main text.

A single cell $i$ in a group of $N$ cells exposed to a Wnt signal of duration $t$ responds independently by expressing output $g_i \sim \text{Gamma}(k, \theta t)$. Hence, the likelihood function for the group of $N$ cells is given by:
\begin{align}\label{eq:likelihood_group1}
    p(\boldsymbol{g} \vert t) &= \prod_{i=1}^N p(g_i \vert t), \\
    \label{eq:likelihood_group2}
    &= \frac{\prod_{i=1}^N g_i^{k-1} }{\Gamma(k)^N (\theta t)^{Nk}} e^{-\sum_{i=1}^N g_i /\theta t}, 
\end{align}
In Sec. \ref{sec:opt_encodingN}, we claim that the arithmetic mean $\bar{g} \equiv \frac{1}{N} \sum_{i=1}^N g_i$ is a sufficient statistic for $t$. A quick way to see this is by observing that Eq. \ref{eq:likelihood_group2} satisfies Fisher-Neyman factorization \cite{halmos_application_1949}. That is, it can be written in the form $p(\boldsymbol{g} \vert t) = h(\boldsymbol{g}) \, f(\bar{g},t)$ for nonnegative functions $h$ and $f$, from which the defining property $p(\boldsymbol{g}\vert \bar{g}, t) = p(\boldsymbol{g} \vert \bar{g})$ follows. Below, however, we derive this property explicitly.

The likelihood of $\bar{g}$ conditioned on $t$ can be written as:
\begin{equation}\label{eq:likelihood_gbar}
    p(\bar{g} \vert t) = \frac{1}{\Gamma(Nk) (\theta t/N)^{Nk}} \bar{g}^{Nk-1} e^{-N\bar{g}/\theta t},
\end{equation}
which follows from the addition of $N$ independent and gamma-distributed random variables. Using Bayes' theorem, we obtain:
\begin{equation}\label{eq:likelihood_g_given_gbar_t}
    p(\boldsymbol{g} \vert \bar{g}, t) = \frac{p(\boldsymbol{g} \vert t)}{p(\bar{g} \vert t)}.
\end{equation}
Substituting Eq. \ref{eq:likelihood_group2} and Eq. \ref{eq:likelihood_gbar} into the above, we get:
\begin{equation}\label{eq:likelihood_g_given_gbar_t2}
    p(\boldsymbol{g} \vert \bar{g}, t) = \frac{\prod_{i=1}^N g_i^{k-1}}{\bar{g}^{Nk-1}}\frac{ \Gamma(Nk) } { (N^k \Gamma(k))^N } = p(\boldsymbol{g} \vert \bar{g}),
\end{equation}
as required. The last equality follows as all $t$-dependence has been canceled out.

Sufficiency of $\bar{g}$ also implies the posterior distributions $p(t \vert \boldsymbol{g})$ and $p(t \vert \bar{g})$ are identical. This can be seen by applying Bayes' theorem
$
    p(t \vert \boldsymbol{g}) = p(\boldsymbol{g} \vert t) \, p(t)/p(\boldsymbol{g}).
$
Substituting $p(\boldsymbol{g} \vert t) = p(\boldsymbol{g} \vert \bar{g}) \, p(\bar{g} \vert t)$ and $p(\boldsymbol{g}) = p(\boldsymbol{g} \vert \bar{g})\, p(\bar{g})$, we obtain:
\begin{equation}
    p(t \vert \boldsymbol{g}) = \frac{ p(\bar{g} \vert t) p(t)}{p(\bar{g})} = p(t \vert \bar{g}),
\end{equation}
as required.

We can also show that the mutual information satisfies $I(t ; \boldsymbol{g}) = I(t ; \bar{g})$. This makes precise the statement that the statistic $\bar{g}$ contains as much information about the signal $t$ as the whole dataset $\boldsymbol{g}$. To show this, we use the data-processing inequality for the mutual information in two ways. Firstly, as $\bar{g}$ is a function of the dataset $\boldsymbol{g}$, we must have that:
\begin{equation}
    I(t ; \boldsymbol{g}) \geq I(t ; \bar{g}).
\end{equation}
Secondly, we have just shown that $p(\boldsymbol{g} \vert \bar{g}, t) = p(\boldsymbol{g} \vert \bar{g})$. This implies that we have a Markov chain $t \rightarrow \bar{g} \rightarrow \boldsymbol{g}$, to which we can also apply the data-processing inequality:
\begin{equation}
    I(t ; \boldsymbol{g}) \leq I(t ; \bar{g}).
\end{equation}
Together, these inequalities imply that $I(t ; \boldsymbol{g}) = I(t ; \bar{g})$, as required.

Finally, we can show that the decoding maps $p_{\boldsymbol{g}}(t \vert t^{*})$ and $p_{\bar{g}}(t \vert t^{*})$ are identical. Starting with $p_{\boldsymbol{g}}(t \vert t^{*})$, we can introduce an integral over $\bar{g}$ using the law of total probability:
\begin{align}
    p_{\boldsymbol{g}}(t \vert t^{*}) &= \int_{0}^\infty \mathrm{d} \boldsymbol{g} \, p( t  \vert  \boldsymbol{g}) \, p(\boldsymbol{g}  \vert t^{*}), \\
    &= \int_{0}^\infty \mathrm{d} \boldsymbol{g} \int_{0}^\infty \mathrm{d} \bar{g} \, p( t  \vert  \boldsymbol{g}) \, p(\boldsymbol{g}  \vert \bar{g}) \, p(\bar{g} \vert t^{*}).
\end{align}
By changing the order of integration and using the fact that $p(t \vert \boldsymbol{g}) = p(t \vert \bar{g})$, we obtain:
\begin{align}
    p_{\boldsymbol{g}}(t \vert t^{*}) &= \int_{0}^\infty \mathrm{d} \bar{g} \, p( t  \vert  \bar{g}) \, p(\bar{g} \vert t^{*}) \int_{0}^\infty \mathrm{d} \boldsymbol{g} \, p(\boldsymbol{g}  \vert \bar{g}), \\
    &= p_{\bar{g}}(t \vert t^{*}).
\end{align}
As such, the decoding maps are identical whether we consider the gene expression in the whole group $\boldsymbol{g}$ or just the mean expression $\bar{g}$.

\section{Small-noise regime and equivalence to the Jeffreys prior}\label{app:smalllargenoise}
As before, we seek to find the distribution $p_{\star}(t)$ that maximizes the mutual information $I(\bar{g};t)$. In this section, we consider regimes where the optimization is analytically tractable. In Fig. \ref{fig:capacity_dots_hessian} in the main text, we show that we can analytically compute the channel capacity $I_\star$ in regimes where the effective noise is really small ($N \gg 1$). We derive these results here. 

As the effective noise approaches zero, it is known that the optimal code for a communication channel becomes continuous \cite{mattingly_maximizing_2018,abbott_scaling_2019}. In this regime, we can use the fact that the noise is small to derive $p_{\star}(t)$ analytically. In literature, this is often referred to as the small-noise approximation and is widely used for studying information transmission in biological systems \cite{tkacik_information_2008, tkacik_information_2011,walczak_optimizing_2010,dubuis_positional_2013,Bauer_Petkova_Gregor_Wieschaus_Bialek_2021, bauer2022,bauer_information_2023}. We will also illustrate that the prior obtained in this limit is formally the same as the Jeffreys prior, a non-informative prior that is often used in Bayesian statistics \cite{jeffreys_invariant_1997}.

We explore the gene regulatory response for a particular signal duration, $t \rightarrow \bar{g}$, which occurs with probability
\begin{equation}
    p(\bar{g} \vert t) = \frac{1}{\Gamma(Nk) (\theta t / N)^{Nk}} \bar{g}^{Nk-1} e^{-N\bar{g}/\theta t}.
\end{equation}
In the limit of small noise ($N \gg 1$), we can approximate the gamma distribution as a narrow Gaussian distribution with a mean and variance given by $\mu_{\bar{g}}(t) = k \theta t$ and $\sigma_{\bar{g}}^2(t) = k \theta^2 t^2 / N$ respectively. 

We write the mutual information as a difference of entropies:
\begin{equation}\label{eq:mutual_information_sn}
    I(\bar{g};t) = H(\bar{g}) - H(\bar{g} \vert t),
\end{equation}
where:
\begin{align}\label{eq:entropy_g_sn}
    H(\bar{g}) = - \int_0^\infty \mathrm{d} \bar{g} \, p(\bar{g}) \, \mathrm{log}_2 \, p(\bar{g}), 
\end{align}
and:
\begin{align}\label{eq:conditional_ent_sn}
    H(\bar{g} \vert t) = - \int_0^T \mathrm{d} t \, p(t) \int_0^\infty \mathrm{d} \bar{g} \, p(\bar{g} \vert t) \, \mathrm{log}_2 \, p(\bar{g} \vert t).
\end{align}
When the noise $\sigma_g(t)$ is small, the mapping $p(\bar{g}\vert t)$ is almost deterministic. As such, we can write:
\begin{equation}
    p(t) \approx p(\bar{g}) \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert.
\end{equation}
This allows us to write entropy in Eq. \ref{eq:entropy_g_sn} as:
\begin{equation}
    H(\bar{g}) \approx H(t) + \int_0^T \mathrm{d} t \, p(t) \, \mathrm{log}_2 \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert.
\end{equation}
Further, using the Gaussian approximation for $p(\bar{g} \vert t)$, the conditional entropy in Eq. \ref{eq:conditional_ent_sn} becomes:
\begin{equation}
    H(\bar{g} \vert t) \approx \frac{1}{2} \int_0^T \mathrm{d} t \, p(t) \, \mathrm{log}_2 (2 \pi e \sigma_{\bar{g}}^2(t)).
\end{equation}
Having written both $H(\bar{g})$ and $H(\bar{g} \vert t)$ in a way where $p(t)$ is the only ``free'' distribution that we can vary, we can now proceed with the optimization. We add a Lagrangian multiplier to ensure normalization of $p(t)$, and optimize
\begin{equation}
    \mathcal{L}[p(t)] = I(\bar{g} ; t) - \beta \int_0^T \mathrm{d} t \, p(t). 
\end{equation}
Taking the variational derivative with respect to $p(t)$, we get:
\begin{equation}
    \frac{\delta \mathcal{L}}{\delta p(t)} = \mathrm{log}_2 \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert - \mathrm{log}_2 \, p(t) - \frac{1}{\mathrm{log} \, 2}  - \frac{1}{2}\mathrm{log}_2 (2 \pi e \sigma_{\bar{g}}^2(t)) - \beta.
\end{equation}
Setting $\delta \mathcal{L} / \delta p(t) = 0$, we obtain:
\begin{equation}\label{eq:optimal_prior_sn}
    p_{\star}(t) = \frac{1}{Z} \frac{1}{\sigma_{\bar{g}}(t)} \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert,
\end{equation}
where
\begin{equation}\label{eq:normalizing_constant_sn}
    Z = \int_0^T \frac{\mathrm{d} t}{\sigma_{\bar{g}}(t)} \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert,
\end{equation}
is a normalizing constant. Using the optimal input distribution in Eq. \ref{eq:optimal_prior_sn} to evaluate $I(\bar{g};t)$, we obtain the channel capacity given by \cite{bialek_biophysics_2012}:
\begin{equation}\label{eq:channel_capacity_sn}
    I_\star = \mathrm{log}_2 \bigg[ \frac{Z}{\sqrt{2 \pi e}} \bigg].
\end{equation}

In Fig. \ref{fig:capacity_dots_hessian} in the main text, we show the mutual information obtained using the prior in Eq. \ref{eq:optimal_prior_sn} derived from the small-noise approximation. Indeed, asymptotically with increasing $N$, we converge to the channel capacity $I_\star$. To derive the functional behavior of the channel capacity $I_{\star}$ with large $N$ we can proceed by inspection. By construction, the mean $\mu_{\bar{g}}(t)$ does not depend on $N$. The variance obeys $\sigma_{\bar{g}}^2(t) \propto 1/N$, and therefore the normalizing constant $Z$ in Eq. \ref{eq:normalizing_constant_sn} satisfies $Z \propto N^{1/2}$. As such, the channel capacity in Eq. \ref{eq:channel_capacity_sn} asymptotically scales as:
\begin{equation}\label{eq:channel_capacity_scaling_sn}
    I_{\star} \sim (1/2)\mathrm{log}_2 N + \mathrm{o}(1).
\end{equation} 

A careful reader will notice that the integral as written in Eq. \ref{eq:normalizing_constant_sn} is undefined. We have a logarithmic singularity at $t=0$ causing the integral to diverge. The singularity is not physical, for it implies that any signal $t>0$ is perfectly distinguishable from $t=0$. As explained in Appendix \ref{app:gamma_distributions}, to regularize the integral we have to be careful about the behavior of $p(\bar{g} \vert t)$ near $t=0$. To do so, we add a small exponential term to the scale parameter as shown in Eqs. \ref{eq:mean_corr} and \ref{eq:var_corr}.
We can proceed with the optimization as before, and note that the preceding arguments still hold.

We also note that the prior obtained in the small-noise limit is formally identical to the Jeffreys prior \cite{jeffreys_invariant_1997}. It is known that in the limit of an infinite number of identically, independent trials of the same experiment (i.e. $N \rightarrow \infty$), the prior that is Shannon-optimal converges weakly to the Jeffreys prior \cite{scholl_shannon_1998}. Indeed, the same is true for a single precise experiment in the limit of small noise. 
We derive the Jeffreys prior below and verify that it is indeed identical to Eq. \ref{eq:optimal_prior_sn}. 

The Jeffreys prior is designed to be invariant under reparametrization of the probability distribution, and is defined as: 
\begin{equation}
    p_\text{J}(t) \propto \vert \mathcal{I}(t) \vert^{1/2},
\end{equation}
where $\mathcal{I}(t)$ is the \textit{Fisher information}:
\begin{equation}\label{eq:fisherinfo}
    \mathcal{I}(t) = \int_0^\infty \mathrm{d} \bar{g} \ p(\bar{g}\vert t) \bigg( \frac{\partial \, \mathrm{log} \, p(\bar{g} \vert t)}{\partial t} \bigg)^2.
\end{equation}
In our case, $p(\bar{g}\vert t)$ is gamma-distributed with shape parameter $Nk$ and a time-dependent scale parameter $\theta(t)/N$:
\begin{equation}
\begin{split}
\mathrm{log} \, p(\bar{g} \vert t) &= - \ \mathrm{log}\, \Gamma(Nk) - Nk\, \mathrm{log} (\theta(t)/ N)  \\
&\quad + (Nk-1) \, \mathrm{log} \, \bar{g} - \frac{N\bar{g}}{\theta(t)}.
\end{split}
\end{equation}
Taking the first derivative and substituting $\mu_{\bar{g}}(t) = k \theta(t)$ and $\sigma^2_{\bar{g}}(t) = k \theta(t)^2/N$, we obtain:
\begin{equation}
\bigg( \frac{\partial \, \mathrm{log} \, p(\bar{g} \vert t)}{\partial t} \bigg)^2 = \frac{1}{\sigma_{\bar{g}}(t)^4} \bigg(\frac{\mathrm{d} \mu_{\bar{g}}(t)}{\mathrm{d} t} \bigg)^2 \big( \bar{g} - \mu_{\bar{g}}(t))^2.
\end{equation}
The expectation over $(\bar{g} - \mu_{\bar{g}}(t))^2$ is just the variance $\sigma_{\bar{g}}^2(t)$; hence, the Fisher information in Eq. \ref{eq:fisherinfo} becomes:
\begin{equation}
    \mathcal{I}(t) = \frac{1}{\sigma_{\bar{g}}(t)^2} \bigg(\frac{\mathrm{d} \mu_{\bar{g}}(t)}{\mathrm{d} t} \bigg)^2.
\end{equation}
The Jeffreys prior can now be written as:
\begin{equation}
    p_\text{J}(t) \propto \frac{1}{\sigma_{\bar{g}}(t)} \bigg \vert \frac{\mathrm{d} \mu_{\bar{g}}}{\mathrm{d} t} \bigg \vert,
\end{equation}
which is identical to the Shannon-optimal prior in the limit of small noise in Eq. \ref{eq:optimal_prior_sn}. We have thus verified that the Jeffreys prior and the prior that optimizes the mutual information are equivalent in the limit of small noise. 

\section{Asymptotic scaling law for the channel capacity}\label{app:scaling_law}

\begin{figure}
    \centering
    \includegraphics[width=0.35\textwidth]{figures/Fig7.pdf}
    \caption{Asymptotic scaling law between the number of symbols $K$ in the optimized prior $p_{\star}(t)$ and the mutual information $I(g;t)$, in agreement with literature \cite{abbott_scaling_2019,mattingly_maximizing_2018}. The bound $I(\bar{g} ; t) \leq \mathrm{log}_2 K$ is shown using a dotted line.}\label{fig:scaling_law}
\end{figure}

In the main text, we explored what happens to our optimal prior $p^{(N)}_{\star}(t)$ as we considered multiple cells $N$. As the $N$ becomes larger, the effective noise level decreases -- analogous to sending the same message multiple times in a communication channel. As the noise level approaches zero, it is known that the number of symbols $K$ in the optimal code follows an asymptotic scaling law. In this limit, the channel capacity $I_\star$ scales with the logarithm of the number of symbols $K$ as $I_\star \sim (3/4)\, \mathrm{log}_2 K$ \cite{abbott_scaling_2019}. Indeed, we confirm the scaling law for our system in Fig. \ref{fig:scaling_law}, as a non-trivial check of our optimization and to verify consistency with existing literature. The dotted line shows the fundamental limit $I_\star \leq \mathrm{log}_2 K$, which would reach equality if the $K$ symbols were perfectly distinguishable. 

\section{Fine-tuning of the optimal code}\label{app:hessian}
Here we consider a prior distribution $p(t)$ composed of a set of $K$ discrete symbols $\{t_i\}$ with respective weights $\{w_i \}$:
\begin{equation}
p(t) = \sum_{i=1}^K w_i \, \delta(t - t_i),
\end{equation}
and ask to what extent the capacity-achieving distribution $p_\star(t)$ needs to be fine-tuned. Since the BA algorithm converges much more quickly to the channel capacity $I_\star$ than to the optimal prior $p_\star(t)$, we anticipate a sloppy information-landscape around the optimum.

To investigate fine-tuning of the prior, we write the mutual information $I(\bar{g} ;t)$ as a function of the positions $\{t_i\}$:
\begin{equation}
    I(\bar{g};t \vert \{ t_i \} ) = \sum_{i=1}^K  w_i \int_0^{\infty} \mathrm{d} \bar{g} \, p(\bar{g} \vert t_i) \, \mathrm{log}_2 \bigg(\frac{p(\bar{g} \vert t_i)}{p(\bar{g})} \bigg).
\end{equation}
Denoting the optimized positions as $\{t_i^\star \}$, we can expand the mutual information around its maximum, the capacity:
\begin{equation}
    I(\bar{g};t \vert \{ t_i \} ) = I_\star + \frac{1}{2} \sum_{i,j = 1}^K (t_i - t_i^\star) \chi_{ij} (t_j - t_j^\star)  + \dots,
\end{equation}
where $\chi_{ij}$ is the Hessian matrix:
\begin{equation}
    \chi_{ij} = \frac{\partial^2 I}{\partial t_i \partial t_j} \bigg \vert_{\{ t_i^\star \}}.
\end{equation}
The eigenvectors of $\chi$ determine directions in parameter space $\{t_i \}$ that have independent effects on the mutual information, whereas the eigenvalues $\{ \lambda_i \}$ tell us the sensitivity along these directions \cite{Bauer_Petkova_Gregor_Wieschaus_Bialek_2021}. Since we have have fit the data with a functional form for $p(\bar{g} \vert t_i )$, we can proceed analytically to compute the Hessian. 

To proceed, we express the partial derivatives of the marginal distribution $p(g)$ with respect to symbol $t_i$,
\begin{equation}
    \frac{\partial p(\bar{g})}{\partial t_i} = w_i \frac{\partial p(\bar{g} \vert t_i)}{\partial t_i}.
\end{equation}
We can then compute the first derivative of the mutual information with respect to $t_i$: 
\begin{equation}
    \frac{\partial I}{\partial t_i} = w_i\int_0^\infty \mathrm{d} \bar{g} \, \frac{\partial p(\bar{g} \vert t_i)}{\partial t_i} \, \mathrm{log}_2\bigg(\frac{p(\bar{g} \vert t_i)}{p(\bar{g})}\bigg).
\end{equation}
Note that this is the same gradient as the one used to iteratively adjust the positions in Eq. \ref{eq:info_gradient}. Taking a second derivative with respect to $t_j$, we obtain:
\begin{equation}
\begin{split}
\chi_{ij} &= \frac{\partial^2 I}{\partial t_{i} \partial t_{j}} \\
&= \frac{w_i}{\mathrm{log} \, 2} \int_0^\infty \mathrm{d} \bar{g}\, \bigg\{\delta_{ij} \bigg[\frac{\partial^2 p(\bar{g} \vert t_i)}{\partial t_i^2} \mathrm{log} \bigg(\frac{p(\bar{g}\vert t_i)}{p(\bar{g})} \bigg) \\
&\quad+ \frac{1}{p(\bar{g} \vert t_i)} \bigg( \frac{\partial p(\bar{g} \vert t_i)}{\partial t_i}\bigg)^2 \bigg] - \frac{w_j}{p(\bar{g})}  \frac{\partial p(\bar{g} \vert t_i)}{\partial t_i} \frac{\partial p(\bar{g} \vert t_j)}{\partial t_j}\bigg\}.
\end{split}
\end{equation}
To compute the integral we insert the functional form $p(\bar{g} \vert t)$ and integrate numerically, after which we can find the spectrum $\{\lambda_i \}$ by diagonalizing $\chi$ (Fig. \ref{fig:capacity_dots_hessian}D). 

