\subsection{Brief Review of Conformal and Split Conformal Prediction for General Regression Problems}

\begin{algorithm}[!t]
\caption{Conformal Prediction Interval Construction without Splitting \citep[adapted from ][]{lei2018distribution}.}
\label{alg:full}
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{algorithmic}[1]
\REQUIRE Data $(X_i; Y_i)$, $i = 1,\ldots,n,$ miscoverage level $\alpha\in (0, 1)$, 
regression algorithm $\mathcal{A}$, points $\mathcal{X}_{new} = \{X_{n+1};X_{n+2}, \ldots \}$ 
at which to construct prediction intervals, and values $\mathcal{Y}_{trial} = \{ y_1, y_2, \ldots \}$ 
to act as trial values.
\ENSURE Predictions intervals, at each element of $\mathcal{X}_{new}$
\For{$x\in \mathcal{X}_{new}$}
  \For{$y\in \mathcal{Y}_{trial}$}
  \State Train on augmented data: Obtain function $\hat{f}(\cdot)$ using regression algorithm $\mathcal{A}$ 
	to estimate $\mathrm{E}(Y|X)$ using $\{(X_1; Y_1), \ldots, (X_n; Y_n), (x; y)\}$.
  \State Compute non-conformity measure (absolute residuals) 
	$R_{i}:=\big|Y_{i}- \hat{f}(X_{i}) \big|$ for $i = 1,\dots,n$ 	and $R_{n+1}=\big|y- \hat{f}(x) \big|.$
	\State Obtain proportion of points whose non-conformity measure is smaller than $R_{n+1}$: 
	$$\pi(y) =(n+1)^{-1}\sum_{i=1}^{n+1} I(R_i \leq R_{n+1}),$$
	where $I(a)$ is the indicator function equaling 1 when condition $a$ is true.
	\EndFor
\State Compute prediction interval for $x$: 
$C(x) = \{ y \in \mathcal{Y}_{trial}: (n+1)\pi(y) \leq \lceil(1-\alpha)(n+1)\rceil\}$
\EndFor
\State Return prediction interval $C(x)$ for each $x\in\mathcal{X}_{new}$.
\end{algorithmic}
\end{algorithm}

Conformal analysis is an evolving field in statistics, and its suitable applications make it an increasingly important area of focus. The works by \cite{vovk2005algorithmic}, \cite{lei2014distribution}, \cite{lei2018distribution} constitute foundational literature in conformal prediction, where researchers started to investigate its importance in the regression framework. Following \cite{lei2018distribution}, 
suppose we observe i.i.d. samples $Z_i = (X_i; Y_i)\in \mathcal{R}^d \times \mathcal{R}\sim P$,
$i = 1, \ldots, n,$ and we wish to construct a prediction interval for $Y_{n+1}, Y_{n+2}, \ldots,$ 
at new feature value(s) $X_{n+1}, X_{n+2}, \ldots$, where $(X_{n+1}, Y_{n+1})$, 
$(X_{n+2}, Y_{n+2}), \ldots$, are independent draws from $P$.  The procedure is 
summarized in Algorithm~\ref{alg:full}. The key observation is that by 
exchangeability of the data points and the assumed symmetry of $\hat{f}$, when 
evaluated at $y = Y_{n+1}$, we see that $\pi(Y_{n+1})$ (defined in Algorithm~\ref{alg:full}) is uniformly distributed 
over the set $\{1/(n + 1), 2/(n + 1), \ldots, 1\}$, which
implies
\[
\Pr\left( (n+1)\pi(Y_{n+1}) \leq \lceil(1-\alpha)(n+1)\rceil \right) \geq 1-\alpha.
\]
This further implies 
$C(x) = \{ y \in \mathcal{R}: (n+1)\pi(y) \leq \lceil(1-\alpha)(n+1)\rceil\},$
although in practice, we must use a discrete grid of trial values $y$.  Also
notice that the steps in the inner for loop must be repeated for each new feature 
value for which we want a prediction, which can be time consuming for more
complicated models in the training step.  This motivated the split conformal
prediction interval approach of \cite{lei2018distribution}, described in 
Algorithm~\ref{alg:split}. 


The major difference is that in split conformal, we randomly split the $n$ 
observations into two subsets, with indices collected in $\mathcal{D}_{1}$ 
and $\mathcal{D}_{2}$, respectively, where $|\mathcal{D}_{1}|=n_1$ and 
$|\mathcal{D}_{2}|=n_2$. We train the model on the $n_1$ observations in 
$\mathcal{D}_{1}$ and then compute and rank the non-conformity 
measure on the separate calibration set $\mathcal{D}_{2}$. 
Based on the ranking of the non-conformity measures within the calibration set, 
we can then calculate the desired prediction interval.
\cite{lei2018distribution} showed that for any new i.i.d. draw $(X_{n+1}; Y_{n+1})$,
$\Pr(Y_{n+1}\in C_S(X_{n+1})) \geq 1-\alpha.$ The crucial observation is that the 
absolute residuals based on $\mathcal{D}_{2}$ are still exchangeable.
If we additionally assume that $R_i$, $i\in \mathcal{D}_{2},$ have a 
continuous joint distribution, then \cite{lei2018distribution} further showed
\[
\Pr(Y_{n+1} \in C_S(X_{n+1})) \in \Bigl[1-\alpha, 1-\alpha+\frac{1}{n_{2}+1}\Bigr).
\]


\cite{lei2018distribution} suggest using an even split to create $\mathcal{D}_{1}$ 
and $\mathcal{D}_{2}$, i.e., $n_1=n_2=n/2$ for even 
sample size $n$, but noted split conformal inference can also be implemented using 
an unbalanced split. Particularly in situations where the regression
procedure is complex, it may be beneficial to have $n_1>n_2$ so that the trained
estimator is more accurate.  Like \cite{lei2018distribution}, we focus on the
equal split in our empirical analyses.

\begin{algorithm}[!t]
\caption{Prediction Interval Construction with Data Splitting \citep[adapted from ][]{lei2018distribution}.}
\label{alg:split}
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{algorithmic}[1]
\REQUIRE Data $(X_i, Y_i)$ for $i = 1,\ldots,n$, miscoverage level $\alpha \in (0, 1)$, 
regression algorithm $\mathcal{A}$.
\ENSURE Prediction interval for $x \in \mathbb{R}^d$.
\State Randomly split indices $i = 1, \ldots, n$ into two subsets, $\mathcal{D}_1$ and 
$\mathcal{D}_2$, with $|\mathcal{D}_1| = n_1$ and $|\mathcal{D}_2| = n_2$.
\State \textbf{Train on $\mathcal{D}_1$:} Use $\mathcal{A}$ to fit regression function $\hat{f}_{n_1}(x)$ to data in $\mathcal{D}_1$.
\State\textbf{Compute residuals on $\mathcal{D}_2$:} For each $i \in \mathcal{D}_2$, compute unstandardized residuals $R_i = |Y_i - \hat{f}_{n_1}(X_i)|$.
\State \textbf{Compute nonconformity quantile $q_{n_2}$:} Let $q_{n_2}$ be the $k$th smallest value in $\{R_i : i \in \mathcal{D}_2\}$, where $k = \lceil(n_2 + 1)(1 - \alpha)\rceil$.
\State \textbf{Return prediction interval:} 
\[
C_S(x) = \left[ \hat{f}_{n_1}(x) - q_{n_2},\; \hat{f}_{n_1}(x) + q_{n_2} \right], \quad \text{for } x \in \mathbb{R}^d.
\]
\end{algorithmic}
\end{algorithm}


\cite{lei2018distribution} also proposed a variant of Algorithm~\ref{alg:split}
described as \textit{local weighting} which can help in cases of heteroscedasticity. 
This involves replacing $R_i$ in Algorithm~\ref{alg:split} with standardized 
absolute residuals
\[
R_{i} = \frac{|Y_{i} - \hat{f}_{n_{1}}(X_{i})|}{\hat{\sigma}(X_{i})},~i\in\mathcal{D}_2,
\]
where $\hat{\sigma}(X_{i})$ is an estimate of the error spread.  \cite{lei2018distribution} set  $\hat{\sigma}(X_i)$ as an estimate of the conditional mean absolute deviation (MAD) of $|Y - f(X)| |X=x$, as a function of $x \in\mathcal{R}^d$ based on the fitted residuals obtained 
from $\mathcal{D}_1$.
The prediction interval is then modified accordingly as 
\[
C_S(x) = \left[ \hat{f}_{n_{1}}(x) - \hat{\sigma}(x){q}_{n_{2}},\; \hat{f}_{n_{1}}(x) + \hat{\sigma}(x){q}_{n_{2}} \right],
\]
where ${q}_{n_{2}}$ is the $\lceil{(1-\alpha)(n_{2}+1)}\rceil$th 
smallest value of the standardized absolute residuals.


