% By exchangeability, we have
% \begin{equation}\label{eq:pi-asym}
%   \Pr\left(R_{\left(\lfloor\frac{\alpha}{2}(n_{2}+1)\rfloor\right)}\leq{R}_{n+1}\leq{}R_{\left(\lceil{(1-\frac{\alpha}{2})(n_{2}+1)}\rceil\right)}\right)
%   \geq1-\alpha.
% \end{equation}
Let \( q_L \) and \( q_R \) denote the  
\(\lfloor \tfrac{\alpha}{2}(n_2 + 1) \rfloor\)th and  
\(\lceil (1 - \tfrac{\alpha}{2})(n_2 + 1) \rceil\)th  
smallest values of \( R_i \), for \( i \in \mathcal{D}_2 \), respectively. That is,
\[
q_L = R_{\left(\lfloor \tfrac{\alpha}{2}(n_2 + 1) \rfloor \right)}, \quad
q_R = R_{\left(\lceil (1 - \tfrac{\alpha}{2})(n_2 + 1) \rceil \right)}.
\]
By exchangeability, the conformal prediction interval satisfies
\begin{equation}\label{eq:pi-asym}
\Pr\left(q_L \leq R_{n+1} \leq q_R\right) \geq 1 - \alpha.
\end{equation}
%
From Equation~\eqref{eq:pi-asym}, one can follow the same procedure for absolute residuals to obtain the prediction interval for \(Y_{n+1}\) based on the Pearson and Anscombe residuals. We call the resulting interval the asymmetric prediction interval. 

