\section{Massless scalar-tensor theories beyond GR}
\label{subsec:massless_ST}
%------------------------------------------------------------------------
%------------------------------------------------------------------------


%------------------------------------------------------------------------
\subsection{The action}
\label{subsec:action}
%------------------------------------------------------------------------

In this section, we summarize the framework in which we have studied the tidal effects on the dynamics of an inspiralling compact binary system in scalar-tensor theories of gravity~\cite{Bernard:2023eul}. The starting point is the generalized version of Brans-Dicke theories where a scalar field $\phi$ is non-minimally coupled to the metric $g_{\mu \nu}$. The theory is characterized by the coupling function $\omega(\phi)$. In order to decouple scalar and tensor degrees of freedom, we perform a conformal transformation to go from the physical metric to the conformal one, defined by
%
\be\label{eq:conformal_metric}
\tilde{g}_{\mu\nu}=\varphi\,g_{\mu\nu}\,, \qquad \varphi=\frac{\phi}{\phi_0}\,.
\ee
%
In particuliar, this conformal transformation implies that $g^{\mu\nu}=\varphi\,\tilde{g}^{\mu\nu}$ and $\sqrt{-\tilde{g}}=\varphi^2 \sqrt{-g}$.  After some reshuffling, the gravitational action can be displayed in the Einstein frame as 
%
\be\label{eq:STactionEF}
S^\text{GF}_{\mathrm{ST}} = \frac{c^{3}\phi_{0}}{16\pi G} \int\ud^{4}x\,\sqrt{-\tilde{g}}\left[ \tilde{R} -\frac{1}{2}\tilde{g}_{\mu\nu}\tilde{\Gamma}^{\mu}\tilde{\Gamma}^{\nu} - \frac{3+2\omega(\phi)}{2\varphi^{2}}\tilde{g}^{\alpha\beta}\p_{\alpha}\varphi\p_{\beta}\varphi\right] +S_{\mathrm{m}}\left(\mathfrak{m},g_{\alpha\beta}\right)\,,
\ee
%
where $\tilde{R}$ is the Ricci scalar related to the conformal metric. A gauge fixing term has been introduced, $\propto\tilde{g}_{\mu\nu}\tilde{\Gamma}^{\mu}\tilde{\Gamma}^{\nu}$ with $\tilde{\Gamma}^{\nu}\equiv\tilde{g}^{\rho\sigma}\tilde{\Gamma}^{\nu}_{\rho\sigma}$, to enforce working in the harmonic gauge. 

As for the matter part, we supplemented the classical matter action for point particles by an effective tidal action describing the response of the internal structure of the compact objects to scalar, tensorial and scalar-tensorial induced tidal interactions~\cite{Bernard:2023eul,Creci:2024wfu}. Hence, the matter action is decomposed as $S_{\rm m}=S_{\rm pp}+S_{\rm tidal}$ with 
%
\begin{subequations}\label{eq:Smatter+tidal}
\begin{align}\label{eq:Smatter}
    S_{\rm pp} &= -c\sum_{a=1,2}\,\int\ud \tau_a\,m_a\left(\phi\right)\,,\\ \nn
    S_{\rm tidal} &= -\frac{c}{2}\,\sum_{a=1,2}\,\int\ud \tau_a\,\biggl\{\lambda_a\left(\phi\right) \left(\nabla_{\alpha}^{\perp}\varphi\right)_a\,\left(\nabla^{\alpha}_{\perp}\varphi \right)_a  + \frac{1}{2} \mu_a\left(\phi\right) \left(\nabla_{\alpha\beta}^{\perp}\varphi\right)_a\,\left(\nabla^{\alpha\beta}_{\perp}\varphi \right)_a \\
& \hspace{3cm} + \nu_a\left(\phi\right) \left(\nabla_{\alpha\beta}^{\perp}\varphi\right)_a\,(G^{\alpha\beta})_a - \frac{1}{2c^2} c_a(\phi)  \,  (G_{\alpha\beta})_a \, (G^{\alpha\beta})_a \; \biggr\}  \label{eq:Stidal}\,,
\end{align}
\end{subequations}
%
The object masses are functions of the scalar field to take into account their internal self-gravity~\cite{1975ApJ...196L..59E}. The tidal action presented in Eq.~\eqref{eq:Stidal} is sufficient to study the impact of tidal deformations on the dynamics and radiation of a binary system up to the 2PN order. Hence, the results of this work will only depend on the four tidal deformability parameters $(\lambda_a,\mu_a,\nu_a,c_a)$. The action is made of the mass quadrupole tidal moment defined as 
%
\begin{align}
(G_{\mu \nu})_a= - c^2\,{\left(R_{\mu \rho \nu \sigma}\right)}_a \, u_a^{\rho} \, u_a^{\sigma}\,.
\end{align}
%
where $R_{\mu \rho \nu \sigma}$ is the usual Riemann tensor and we denote $\nabla_{\mu}^{\perp}\equiv\left(\delta_{\mu}^{\nu}+u_{\mu}u^{\nu}\right)\nabla_{\nu}$ the projected covariant derivative onto the hypersurface orthogonal to the four velocity.

%------------------------------------------------------------------------
\subsection{The field equations}
\label{subsec:field_eqns}
%------------------------------------------------------------------------

For the treatment of the radiative sector, it is necessary to consider and solve the full Einstein field equations including the tidal contributions. Varying the gauge-fixed action \eqref{eq:STactionEF}, supplemented by the matter and tidal actions \eqref{eq:Smatter+tidal}, w.r.t the conformal metric $\tilde{g}_{\mu \nu}$ and the scalar field $\varphi$, yields to the following field equations :

\begin{subequations}\label{eq:rEFE_g_tilde}
\begin{align}
\tilde{G}_{\mu\nu} + \frac{3+2 \omega(\phi)}{2 \varphi^2}\left( \frac{1}{2} \tilde{g}^{\alpha \beta}\tilde{g}_{\mu\nu} - \delta^{\alpha}_{\mu} \delta^{\beta}_{\nu}\right) \p_{\alpha} \varphi \p_{\beta} \varphi &= \frac{8 \pi G}{c^4 \phi_0} \left( \tilde{T}_{\mu \nu} + \Delta \tilde{T}_{\mu \nu} \right)\\ 
\tilde{g}^{\alpha \beta} \tilde{\nabla}_{\alpha}\tilde{\nabla}_{\beta} \varphi + \frac{1}{2} \frac{d}{d \varphi} \left[\ln{\left(\frac{3+2 \omega(\phi)}{\varphi ^2} \right)} \right]\tilde{g}^{\alpha \beta} \p_{\alpha} \varphi \p_{\beta} \varphi &= \frac{8 \pi G}{c^4 \phi_0} \frac{\varphi}{3+2 \omega(\phi)} \left( \Delta \tilde{S}_{\rm pp} + \Delta \tilde{S}_{\rm tidal}\right)\label{eq:rEFE_g_tilde_2}\,,
\end{align}
\end{subequations}
%
We have introduced $\tilde{G}_{\mu\nu}$ the conformal Einstein tensor and $\tilde{T}^{\mu\nu} \equiv \frac{2}{\sqrt{-\tilde{g}}}\frac{\delta S_{\mathrm{pp}}}{\delta \tilde{g}_{\mu\nu}}$ the conformal stress-energy tensor. Note that $\tilde{T}^{\mu\nu}$ can be related to the physical stress-energy tensor  $T^{\mu\nu} \equiv \frac{2}{\sqrt{-g}}\frac{\delta S_{\mathrm{pp}}}{\delta g_{\mu\nu}}$ by the relation $T^{\mu\nu}= \varphi^3 \tilde{T}^{\mu\nu}$ where 

\begin{align}\label{eq:Tmunupp}
    \tilde{T}^{\mu\nu}\left(t,\mathbf{x}\right) = \sum_{a=1,2}\,\dfrac{m_a\left(\phi\right)v_a^{\mu}v_a^{\nu}}{\sqrt{-\tilde{g}_{\mu\nu}v_a^{\mu}v_a^{\nu}/c^2}}\frac{1}{\sqrt{{\varphi}}}\frac{\delta_a^{(3)} (\mathbf{x}-\mathbf{y_a(t)})}{\sqrt{-\tilde{g}}}\,.
\end{align}
%
We denote by $\Delta \tilde{T}^{\mu\nu} \equiv \frac{2}{\sqrt{-\tilde{g}}}\frac{\delta S_{\mathrm{tidal}}}{\delta \tilde{g}_{\mu\nu}}$ the tidal correction to the conformal stress-energy tensor. For convenience, we have also defined $ \Delta \tilde{S}_{\rm pp} = \frac{-2 \varphi}{\sqrt{-\tilde{g}}}\frac{\delta S_{\rm pp}}{\delta \varphi}$ and $ \Delta \tilde{S}_{\rm tidal} = \frac{-2 \varphi}{\sqrt{-\tilde{g}}}\frac{\delta S_{\rm tidal}}{\delta \varphi}$. After introducing the metric perturbation ${h^{\mu\nu}\equiv  \tilde{\mathfrak{g}}^{\mu\nu} -\eta^{\mu\nu}\equiv \sqrt{-\tilde{g}}\,\tilde{g}^{\mu\nu}  -\eta^{\mu\nu}}$ and the scalar perturbation $\psi\equiv\varphi-1$, the Einstein field equations \eqref{eq:rEFE_g_tilde} can be written in the form of inhomogeneous flat d'Alembertian equations, namely
%
\begin{subequations}\label{eq:rEFE}
\begin{align}
&\Box_{\eta}\,h^{\mu\nu} = \frac{16\pi G}{c^{4}\phi_0}\tau^{\mu\nu}\,,\label{eq:EFE_V1_1}\\
& \Box_{\eta}\,\psi = \frac{8\pi G}{c^{4} \phi_0}\tau_{s}\label{EFE_V1_2}\,,
\end{align}
\end{subequations}
%
where $\Box_{\eta} = \eta^{\mu \nu} \p_{\mu} \p_{\nu}$ and where the tensor and scalar pseudo-tensors both read
%
\begin{subequations}\label{tau}
\begin{align}\label{taumunu}
\tau^{\mu\nu} &=  \vert \tilde{g}\vert (\tilde{T}^{\mu\nu}+ \Delta \tilde{T}^{\mu\nu}) +\frac{c^{4} \phi_0}{16\pi G} \Lambda^{\mu\nu} \,,\\
\label{taus} \tau_{s} &= \frac{  \varphi }{(3+2\omega)}\sqrt{-\tilde{g}}\left(\Delta \tilde{S}_{\rm pp} + \Delta \tilde{S}_{\rm tidal}\right) +\frac{c^{4} \phi_0}{8\pi G}\Lambda_s\,.
\end{align}
\end{subequations}
%
The non-linearities are encoded by the scalar source term
%
\be\label{eq:lambdas} 
\Lambda_s = -h^{\alpha\beta}\p_{\alpha}\p_{\beta}\psi-\p_{\alpha}\psi\p_{\beta}h^{\alpha\beta} +\left(\frac{1}{\varphi}-\frac{\phi_{0}\omega'(\phi)}{3+2\omega(\phi)}\right)\tilde{\mathfrak{g}}^{\alpha\beta}\p_{\alpha}\psi\p_{\beta}\psi\,.
\ee 
%
and by the gravitational one $\Lambda^{\mu\nu}$, which can in turn be decomposed as $\Lambda^{\mu\nu} = \Lambda^{\mu\nu}_{\mathrm{LL}}+\Lambda_{\mathrm{H}}^{\mu\nu}+\Lambda^{\mu\nu}_{\mathrm{GF}}+\Lambda_{\phi}^{\mu\nu}$ where $\Lambda^{\mu\nu}_{\mathrm{LL}}$ is the Landau-Lifshitz pseudo-energy tensor~\cite{Landau:1975pou}, $\Lambda^{\mu\nu}_{\mathrm{H}}$ comes from our use of the flat version of the d'Alembertian operator in Eqs.~\eqref{eq:rEFE}, $\Lambda^{\mu\nu}_{\mathrm{GF}}$ is due to the gauge-fixing term in the action and $\Lambda_{\phi}^{\mu\nu}$ is sourced by the scalar field. Note that $\Lambda_{\mathrm{GR}}^{\mu\nu}=\Lambda^{\mu\nu}_{\mathrm{LL}}+\Lambda_{\mathrm{H}}^{\mu\nu}+\Lambda^{\mu\nu}_{\mathrm{GF}}$ will take the same form as in GR. The expressions of these source terms are given by
%
\begin{subequations}\label{eq:exprLambda}
\begin{align}\label{eq:LambdaLL}
& \Lambda_{\mathrm{LL}}^{\alpha\beta} =\ \frac{1}{2}\tilde{\mathfrak{g}}^{\alpha\beta}\tilde{\mathfrak{g}}_{\mu\nu}\partial_{\lambda}h^{\mu\gamma}\partial_{\gamma}h^{\nu\lambda}-\tilde{\mathfrak{g}}^{\alpha\mu}\tilde{\mathfrak{g}}_{\nu\gamma}\partial_{\lambda}h^{\beta\gamma}\partial_{\mu}h^{\nu\lambda} -\tilde{\mathfrak{g}}^{\beta\mu}\tilde{\mathfrak{g}}_{\nu\gamma}\partial_{\lambda}h^{\alpha\gamma}\partial_{\mu}h^{\nu\lambda} \nn&\\
&\qquad\quad +\tilde{\mathfrak{g}}_{\mu\nu}\tilde{\mathfrak{g}}^{\lambda\gamma}\partial_{\lambda}h^{\alpha\mu}\partial_{\gamma}h^{\beta\nu} +\frac{1}{8}\left(2\tilde{\mathfrak{g}}^{\alpha\mu}\tilde{\mathfrak{g}}^{\beta\nu}-\tilde{\mathfrak{g}}^{\alpha\beta}\tilde{\mathfrak{g}}^{\mu\nu}\right)\left(2\tilde{\mathfrak{g}}_{\lambda\gamma}\tilde{\mathfrak{g}}_{\tau\pi}-\tilde{\mathfrak{g}}_{\gamma\tau}\tilde{\mathfrak{g}}_{\lambda\pi}\right)\partial_{\mu}h^{\lambda\pi}\partial_{\nu}h^{\gamma\tau} \,, \\
\label{eq:LambdaH}
&\Lambda_{\mathrm{H}}^{\alpha\beta} = -h^{\mu\nu}\partial_{\mu}\partial_{\nu}h^{\alpha\beta} +\partial_{\mu}h^{\alpha\nu}\partial_{\nu}h^{\beta\mu} \,,\\
\label{eq:Lambdagf}
& \Lambda_{\mathrm{GF}}^{\alpha\beta} = - \partial_{\lambda}h^{\lambda\alpha} \partial_{\sigma}h^{\sigma\beta} - \partial_{\lambda}h^{\lambda\rho}\partial_{\rho}h^{\alpha\beta} -\frac{1}{2}\tilde{\mathfrak{g}}^{\alpha\beta}\tilde{\mathfrak{g}}_{\rho\sigma} \partial_{\lambda}h^{\lambda\rho} \partial_{\gamma}h^{\gamma\sigma} +2\tilde{\mathfrak{g}}_{\rho\sigma}\tilde{\mathfrak{g}}^{\lambda(\alpha} \partial_{\lambda}h^{\beta)\rho}\partial_{\gamma}h^{\gamma\sigma} \,,\\
\label{eq:Lambdas}
&\Lambda_{\phi}^{\mu\nu} = \frac{3+2\omega(\phi)}{\varphi^2}\left(\tilde{\mathfrak{g}}^{\mu\alpha}\tilde{\mathfrak{g}}^{\nu\beta} -\frac{1}{2}\tilde{\mathfrak{g}}^{\mu\nu}\tilde{\mathfrak{g}}^{\alpha\beta}\right)\p_{\alpha}\psi\p_{\beta}\psi\,.
\end{align}
\end{subequations}
%
The gauge-fixing term~\eqref{eq:Lambdagf} contains the harmonicities $\p_{\nu}h^{\mu\nu}$ which are not zero off-shell, \textit{i.e.} when the accelerations are not replaced by the equations of motion. However in this work, all quantities will be directly computed on-shell, implying that this term is zero.

As for any general matter system in harmonic coordinates, the metric and scalar field perturbations can be parameterized by some PN potentials, $\left(V,\,V^i,\,\hat{W}^{ij}\right)$ for the metric, and $\left(\psi_{(0)},\,\psi_{(1)}\right)$ for the scalar field~\cite{Blanchet:2013haa,Bernard:2018hta}, as
%
\begin{subequations}
\label{metric_decomp}
\begin{align}
 h^{00ii} = & - \frac{4}{c^2}V- \frac{8}{c^4} V^2 + \mathcal{O}\left(\frac{1}{c^6}\right) \,, \\
h^{0i} = &- \frac{4}{c^3}V_i+ \mathcal{O}\left(\frac{1}{c^5}\right) \,, \\
h^{ij} = & - \frac{4}{c^4}(\hat{W}_{ij}-\frac{1}{2} \delta_{ij} \hat{W})+\mathcal{O}\left(\frac{1}{c^6}\right) \,, \\
\psi = & -\frac{2}{c^2}\psi_{(0)}+\frac{2}{c^4}\left(1-\frac{\phi_0 \omega_0^{'}}{3+2 \omega_0}\right)\psi_{(0)}^2 \nn \\
& \quad +\frac{1}{c^6}\left[-\frac{4}{3}\Biggl(1-\frac{4\phi_0 \omega_0^{'}}{3+2 \omega_0}-\frac{\phi_0^2(-4(\omega_0^{'})^2+ (3+2 \omega_0)\omega_0^{''})}{(3+2 \omega_0)^2}\right)\psi_{(0)}^3 +\psi_{(1)}\Biggr] +\mathcal{O}\left(\frac{1}{c^8}\right) \,, 
\end{align}
\end{subequations}
%
with $h^{00ii}\equiv h^{00}+h^{ii}$. These potentials satisfy the following flat spacetime wave equations
%
\begin{subequations}
\label{eq:PotentialWaveEq}
\begin{align}
\Box V = & -4 \pi G \sigma \,, \\
\Box V_i = & -4 \pi G \sigma_i \,, \\
\Box \hat{W}_{ij} = & -4 \pi G \left( \sigma_{ij}-\delta_{ij}\sigma_{kk}\right) -\p_i V\p_iV - (3+2 \omega_0)\p_i \psi_{(0)} \p_j \psi_{(0)} \,, \\
\Box \psi_{(0)} = & -4 \pi G \sigma_s \,, \\
\Box \psi_{(1)} = & -16 \pi G \sigma_s \hat{W} -4 \biggl( 4 V_i\p_{ti}\psi_{(0)} + 2 \hat{W}_{ij}\p_{ij}\psi_{(0)}+2V \p_t^2 \psi_{(0)} \nn \\
& \quad + 2 \bigl( \p_t V_i + \p_j \hat{W}_{ij} -\frac{1}{2} \p_i \hat{W}\bigr)\p_i \psi_{(0)} \biggr) \label{PotentialWaveEq_4}\,.
\end{align}
\end{subequations}
%
The source densities $\sigma,\sigma_i,\sigma_{ij}$ and $\sigma_s$ constitute the compact part of the sources of the potentials, and are given by
%
\begin{subequations}
\begin{align}
	\sigma & = \frac{\tilde{T}^{00}+\Delta \tilde{T}^{00} + \tilde{T}^{ii}+ \Delta \tilde{T}^{ii}}{c^2}\,,\qquad	\sigma_i = \frac{\tilde{T}^{0i}+\Delta \tilde{T}^{0i}}{c} \,,\qquad	\sigma_{ij} = \tilde{T}^{ij}+\Delta \tilde{T}^{ij} \,,\\[5pt]
\sigma_s & =  \frac{1}{c^2}\frac{1}{\sqrt{\left(3+2\omega_0\right)(3+2\omega)}} \sqrt{-\tilde{g}} \left(\Delta \tilde{S}_{\rm pp} + \Delta \tilde{S}_{\rm tidal}\right) \,.\label{eq:sigmas}	
\end{align}
\end{subequations}
%

We expand the masses $m_a\left(\phi\right)$ around the asymptotic value of the scalar field at infinity, $\phi_0$. Using the definition of the sensitivities and higher-order sensitivities (see Table~\ref{tab:ST_parameters}), we get
%
\begin{align}
m_a\left(\phi\right)=m_a \Biggl[ 1 + s_a \psi + \frac{1}{2} \Bigl( s_a^2 + s_a' - s_a\Bigr) \psi^2 + \frac{1}{6}\Bigl(s_a'' + 3 s_a's_a -3s_a' + s_a^3-3s_a^2 +2s_a\Bigr) \psi^3 + \mathcal{O}\left(\psi^4\right)\Biggr]\,.
\end{align}
%
Similarly, we expand the tidal deformability parameters in powers of the scalar perturbation as
%
\begin{align}\label{tiddeform}
& \lambda_a(\phi) = \sum_{n=0}^{\infty} \frac{\lambda_a^{(n)}}{n!} \,{\phi_0}^n \, {\psi}^n\,, \qquad \mu_a(\phi) = \sum_{n=0}^{\infty} \frac{\mu_a^{(n)}}{n!} \,{\phi_0}^n \, {\psi}^n\,, \qquad \nu_a(\phi) = \sum_{n=0}^{\infty} \frac{\nu_a^{(n)}}{n!} \,{\phi_0}^n \, {\psi}^n\,,\qquad c_a(\phi) = \sum_{n=0}^{\infty} \frac{c_a^{(n)}}{n!} \,{\phi_0}^n \, {\psi}^n\,.
\end{align}
%

%------------------------------------------------------------------------
%------------------------------------------------------------------------
\section{Tidal effects on the dynamics for circular orbits}
\label{sec:dynamics_circ}
%------------------------------------------------------------------------
%------------------------------------------------------------------------

The dynamics of compact binary systems in ST theories is currently known up to 3PN order in the point-particle approximation~\cite{Bernard:2018ivi,Bernard:2018hta}. In~\cite{Bernard:2023eul}, building up on the initial work ~\cite{Bernard:2019yfz}, we extended these results by computing the 2PN tidal corrections to the equations of motion and to the conserved quantities, notably the energy and angular momentum. In this section, we reduce these results for the dynamical sector to the specific case of circular orbits. Complete and explicit expressions are provided in the associated \textit{Mathematica} file, available upon request~\cite{SuppMaterial}.

We begin by considering the 2PN conservative equations of motion, as presented in~\cite{Bernard:2023eul}. Setting ${\bf n}\cdot{\bf v} = 0$ and ${\bf v}^2=\omega^2 r^2$, the relative acceleration becomes purely radial and can be written as 
%
\begin{align}
\label{eq:EoM_radial}
a^i= - \omega ^2 x^i
\end{align}
%
where $\omega$ is the orbital frequency. This frequency can be expressed either in terms of the orbital separation r or in terms of the PN parameter $\gamma=\tilde{G} \alpha m/(c^2 r)$. This yields
%
\begin{align}
\label{eq:omega2_v2}
\omega^2_{\text{tidal}} = & \frac{8 c^6 \gamma^6}{\alpha^2 \tilde{G}^2 m^2 (-1 + \zeta) \bar{\gamma}} \Bigl\{\zeta \bar{\gamma} \tilde{\lambda}_{+}^{(0)} + \gamma \Bigl[\frac{11}{4} \zeta \bar{\gamma} \nu \tilde{\lambda}_{+}^{(0)} + \frac{1}{16} \delta (80 \bar{\beta}^+ \zeta \tilde{\lambda}_{-}^{(0)} + 12 \zeta \bar{\gamma} \tilde{\lambda}_{-}^{(0)} + 15 \zeta \bar{\gamma}^2 \tilde{\lambda}_{-}^{(0)} - 25 \zeta \bar{\gamma} \tilde{\Lambda}_{-}^{(0)} \nn \\
