\subsection{From the asymptotic waveforms to the energy fluxes and waveform amplitude modes}
\label{sec:asymptotic_waveform}
%------------------------------------------------------------------------

Next, we consider a radiative coordinate system $(c\mathrm{T},\mathrm{X})$, where the retarded time defined by $\mathrm{U}\equiv \mathrm{T}-\mathrm{R}/c$ becomes asymptotically null at future null infinity. The transverse-traceless (TT) projection of the metric can be uniquely decomposed, at leading order in $1/R$, in terms of two sets of symmetric-trace-free (STF) radiative moments, the mass-type $\mathcal{U}_L$ and the current-type $\mathcal{V}_L$, as
%
\begin{equation}\label{eq:hijTT}
h_{ij}^\text{TT} = - \frac{4G}{c^2 R} \perp^\text{TT}_{ijab} \sum_{\ell=2}^{+\infty} \frac{1}{c^\ell \ell!}\Big( N_{L-2}\,\mathcal{U}_{ab L-2}(U) - \frac{2\ell}{c(\ell+1)} N_{c L-2} \varepsilon_{cd(a}\mathcal{V}_{b)dL-2}(U)\Big) + \mathcal{O}\Big(\frac{1}{R^2}\Big)\,,   
\end{equation}
%
where $\perp^\text{TT}_{ijab}\equiv\frac{1}{2}(\perp_{ia}\perp_{jb}+\perp_{ja}\perp_{ib}-\perp_{ij}\perp_{ab})$ with $\perp_{ij}=\delta_{ij}-N_iN_j$ being the TT projection operator. We recall that \textit{e.g.} $N_{L-2}=N_{i_1}\cdots N_{i_{\ell-2}}$. Similarly, the scalar waveform can also be decomposed, at leading order in $1/R$, in terms of another set of STF scalar radiative moments $\mathcal{U}_L^s$, as 
%
\begin{equation}\label{eq:scalar_waveform}
\psi = - \frac{2G}{c^2 R}\sum_{\ell=0}^{+\infty} \frac{1}{c^\ell \ell!} N_L \mathcal{U}_L^s(U) + \mathcal{O}\Big(\frac{1}{R^2}\Big)\,.  
\end{equation}
%
From the asymptotic gravitational and scalar waveforms~\eqref{eq:hijTT} and~\eqref{eq:scalar_waveform}, we can compute the associated gravitational and scalar energy fluxes, respectively denoted $\mathcal{F}^g$ and $\mathcal{F}^s$, and defined by
%
\begin{subequations}\label{eq:fluxes}
\begin{align}
\mathcal{F}^g & =   \frac{c^3 R^2 \phi_0}{32 \pi G} \int \!\dd\Omega \left(\frac{\partial h_{ij}^\text{TT}}{\partial U}\right)^2 \nn \\
& = \sum_{\ell=2}^{+\infty} \frac{G \phi_0}{c^{2\ell+1}}\Bigg( \frac{(\ell+1)(\ell+2)}{(\ell-1) \ell \ell! (2\ell+1)!! }  \overset{(1)}{\mathcal{U}}_L\overset{(1)}{\mathcal{U}}_L + \frac{4 \ell (\ell+2)}{c^2 (\ell-1) (\ell+1)! (2\ell+1)!!} \overset{(1)}{\mathcal{V}}_L\overset{(1)}{\mathcal{V}}_L\Bigg) \,,\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\mathcal{F}^s &= \frac{c^3 R^2 \phi_0 (3+2\omega_0) }{16\pi G} \int\!\dd\Omega \left( \frac{\partial \Psi}{\partial U}\right)^2  = \sum_{\ell=0}^{+\infty} \frac{G \phi_0 (3+2\omega_0)}{c^{2\ell+1} \ell! (2\ell+1)!!}\overset{(1)}{\mathcal{U}^s_L} \; \overset{(1)}{\mathcal{U}^s_L} \label{eq:fluxes_scalar}\,.
\end{align}
\end{subequations}
%
In this project, since we aim at computing the tidal corrections to the total energy flux up to 1PN beyond the leading order quadrupolar radiation in GR, the above expressions reduce to,
%
\bse\label{eq:fluxes_1PN}
	\begin{align}
	\mathcal{F}^g &=\frac{G \phi_0}{ c^5} \left\{ \frac{1}{5} \, \overset{(1)}{\mathcal{U}}_{ij} \, \overset{(1)}{\mathcal{U}}_{ij} + \frac{1}{c^2} \, \left[\frac{1}{189} \,  \overset{(1)}{\mathcal{U}}_{ijk} \, \overset{(1)}{\mathcal{U}}_{ijk} + \frac{16}{45} \, \overset{(1)}{\mathcal{V}}_{ij} \, \overset{(1)}{\mathcal{V}}_{ij}\right] + \mathcal{O}\left( \frac{1}{c^3} ; \frac{\epsilon_{\text{tidal}}}{c^3} \right)\right\} \label{eq:flux_grav} \,,\\
	\mathcal{F}^s &=\frac{G \phi_0 (3 +2 \omega_0)}{c^3} \left\{c^2 \,\overset{(1)}{\mathcal{U}^s} \; \overset{(1)}{\mathcal{U}^s} + \frac{1}{3} \, \overset{(1)}{\mathcal{U}^s_i} \; \overset{(1)}{\mathcal{U}^s_i}+ \frac{1}{30 c^2}\, \overset{(1)}{\mathcal{U}^s_{ij} } \; \overset{(1)}{\mathcal{U}^s_{ij} } + \frac{1}{630 c^4} \, \overset{(1)}{\mathcal{U}^s_{ijk}} \; \overset{(1)}{\mathcal{U}^s_{ijk}} + \mathcal{O}\left( \frac{1}{c^5} ; \frac{\epsilon_{\text{tidal}}}{c^5} \right) \right\} \label{eq:flux_scal} \,.
	\end{align}
\ese
%
In Table~\ref{tab:radiative_moments_for_flux}, we summarize the radiative moments needed to derive the 1PN flux, along with the orders at which they must be obtained to reach that accuracy. 
%
\begin{table*}[ht]
    \centering
    \renewcommand{\arraystretch}{2}
    \begin{tabular}{|c||c|c|c|c||c|c|c|}
        \hline
       Moments & $\quad  {\mathcal{U}}^s \quad $ & $\quad{\mathcal{U}^s_i}\quad$ & $\quad{\mathcal{U}^s_{ij}}\quad$ & $\quad{\mathcal{U}^s_{ijk}}\quad$ & $\quad{\mathcal{U}_{ij}}\quad$ & $\quad{\mathcal{V}_{ij}}\quad$ & $\quad{\mathcal{U}_{ijk}}\quad$ \\
        \hline
       Required precision & 2PN & 2PN & 1PN & 0PN & 1PN & 0PN & 0PN \\
        \hline
    \end{tabular}
    \caption{Required radiative moments to derive the total energy flux to 1PN order.}
    \label{tab:radiative_moments_for_flux}
\end{table*}
%

\noindent Next, we define the usual polarizations of the gravitational waveform as 
%
\begin{subequations}
\begin{align}
h_+& \equiv \frac{1}{2}(P_i P_j - Q_i Q_j) h_{ij}^{TT}\,,\\
h_\times & \equiv \frac{1}{2}(P_i Q_j + Q_i P_j) h_{ij}^{TT}\,,
\end{align}
\end{subequations}
%
using an orthonormal triad $(\bm{N},\bm{P},\bm{Q})$, where $\bm{N}$ is the direction of propagation of the GW, and $\bm{P}$ and $\bm{Q}$ are two unit polarization vectors. The complex gravitational field $h = h_+ - \di h_\times$ can itself be decomposed on the basis of spin-weighted spherical harmonics of weight $-2$,
%
\begin{subequations}
\be 
h = h_+ - \di h_- = \sum_{\ell=2}^{+\infty} \sum_{m=-\ell}^\ell h^{\ell m} \,Y^{\ell m}_{-2}(\Theta,\Phi)\,,
\ee
%
where the two angles $(\Theta,\Phi)$ characterize the direction $\bm{N}$. Similarly, the pure spin-0 scalar field can also be decomposed on the basis of standard (spin-0) spherical harmonics,
%
\be 
\psi =\sum_{\ell=0}^{+\infty} \sum_{m=-\ell}^\ell \psi^{\ell m}\  Y^{\ell m}(\Theta,\Phi) \label{eq:psi_spheri_harmonic}\,.
\ee
\end{subequations}
%
Using the orthogonality properties of $Y^{\ell m}_{-2}$ and $Y^{\ell m}$, we extract the waveform amplitudes modes characterized by the two numbers $(\ell,m)$ by the surface integrals 
\begin{subequations}
\begin{align}
\label{eq:hlm_psilm_integrals}
h^{\ell m} &= \int \dd\Omega \, h \,  ({Y^{\ell m}_{-2}})^{*} \,,\\
\psi^{\ell m} &= \int \dd\Omega \, \psi \,  (Y^{\ell m})^{*}\,.
\end{align}
\end{subequations}
where $\dd\Omega = \sin(\Theta)\dd\Theta\dd\Phi$ stands for the solid angle element and the star $(\cdot)^{*}$ denotes the complex conjugation. After injecting the asymptotic waveform decompositions~\eqref{eq:hijTT}-\eqref{eq:scalar_waveform} in terms of the radiative moments and performing the surface integrals, we obtain an expression for the gravitational and scalar amplitude modes directly in terms of the spherical harmonic moments $(\mathcal{U}^{\ell m},\mathcal{V}^{\ell m},\mathcal{U}_s^{\ell m})$
%
\begin{subequations}
\begin{align}
\label{eq:hlm_psilm_UlmVlmUslm}
h^{\ell m} &= - \frac{G}{\sqrt{2} R c^{\ell+2}}\Big[ \mathcal{U}^{\ell m} - \frac{\di}{c} \mathcal{V}^{\ell m}\Big]\,,\\
\psi^{\ell m} &= \frac{G}{R c^{\ell+2}} \mathcal{U}_s^{\ell m}\,.
\end{align}
\end{subequations}
%
In the case of planar orbital motion (where spins are either null or aligned/anti-aligned), symmetry considerations impose that $\mathcal{V}^{\ell m}$ is zero when $\ell+m$ is even and $\mathcal{U}^{\ell m}$ is zero when $\ell+m$ is odd. These spherical harmonic moments are related to the STF radiative moments via the relations
%
\begin{subequations}
\begin{align}
\mathcal{U}^{\ell m} &= \frac{4}{\ell!}\sqrt{\frac{(\ell+1)(\ell+2)}{2\ell(\ell-1)}}\alpha_L^{\ell m} \mathcal{U}_L\,,\\
\mathcal{V}^{\ell m} &= -\frac{8}{\ell!}\sqrt{\frac{\ell(\ell+2)}{2(\ell+1)(\ell-1)}}\alpha_L^{\ell m} \mathcal{V}_L\,,\\
\mathcal{U}_s^{\ell m} &= -\frac{2}{\ell!} \alpha_L^{\ell m} \mathcal{U}^s_L\,,
\end{align}
\end{subequations}
%
where we have introduced $\alpha_L^{\ell m}$ as
%
\begin{equation}\label{eq:alphalmL_def}
\alpha_L^{\ell m} = \frac{(-)^m\,2^\frac{2+\vert m\vert}{2}\sqrt{\pi}\,\ell !}{\sqrt{(2\ell+1) (\ell+m)!\,(\ell-m)!}}\,{\mathfrak{m}_0^{*}}^{\langle M}l_\text{\textcolor{white}{0}}^{L-M\rangle}\,,
\end{equation}
%
with $(\bm{n}_0,\bm{\lambda}_0,\bm{\ell})$ being a fixed orthonormal basis and $\mathfrak{m}_0$ defined as $\mathfrak{m}_0=(\bm{n}_0+i\bm{\lambda}_0)/\sqrt{2}$. Here, the unit vector normal to the orbital plane $\bm{\ell}=\bm{\ell}_0$ is constant due to the planar nature of the motion. Finally, anticipating on our results, we introduce the following redefinition of the phase variable
\be 
\psi \equiv \phi - \frac{2 (1-\zeta)}{\alpha} x^{3/2} \Biggl[1 +  \frac{8 \zeta x^3}{1 - \zeta} \Bigl(\tilde{\lambda}_ {+}^{(0)} + \frac{ \sqrt{\alpha} (\mathcal{S}_{-}{} \tilde{\Lambda}_ {-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})}{\bar{\gamma}}\Bigr)\Biggr] \bigg(\log(4 \omega \tau_0)+\gamma_E-\frac{11}{12}\bigg)\,,
\ee
%
that is similar to the one proposed in~\cite{Sennett:2016klh} but supplemented by a tidal correction. As we will see, it succeeds in removing most logarithms from the expressions of $h^{\ell m}$ and $\psi^{\ell m}$ once the complex exponential is PN-expanded. These modes can then be recasted into the dimensionless amplitude modes $h^{\ell m}$ and $\psi^{\ell m}$ which are given by\footnote{Recall that $h^{\ell, -m} = (-)^\ell {(h^{\ell m})}^{*}$ and $\psi^{\ell, -m} = (-)^\ell (\psi^{\ell m})^{*}$. }
%
\begin{subequations}
\begin{align}
h^{\ell m} &= \frac{2 \tilde{G}(1-\zeta) m \nu x}{R c^2}  \sqrt{\frac{16\pi}{5}} \,\hat{H}^{\ell m} \e^{-\di m \psi } \,,\\
\psi^{\ell m} &= \frac{2 i \tilde{G} \zeta \sqrt{\alpha}\mathcal{S}_{-} m \nu \sqrt{x}}{R c^2} \sqrt{\frac{8\pi}{3}} \,\hat{\Psi}^{\ell m} \e^{-\di m \psi}\,.
\end{align}
\end{subequations}
%
with normalized modes defined such that $\hat{H}^{22} = 1 + \mathcal{O}(x)$ and $\hat{\Psi}^{11} = 1 + \mathcal{O}({x})$. Consequently, in order to derive the full waveform amplitude to 1PN order, one has to know all modes $h^{\ell m}$ with $2 \leq\ell \leq 4 $ and $\lvert m \rvert \leq \ell$ up to 1PN order beyond the leading quadrupolar contribution in GR, and all modes $\psi^{\ell m}$ with with $0 \leq\ell \leq 4 $ and $\lvert m \rvert \leq \ell$ up to 1.5PN order beyond the leading dipolar contribution. In Table~\ref{tab:radiative_moments_for_waveform}, we summarize again the radiative moments needed to derive the full waveform amplitude to 1PN order, along with the orders at which they must be obtained to reach that accuracy. 
%
\begin{table*}[ht]
    \centering
    \renewcommand{\arraystretch}{2}
    \begin{tabular}{|c||c|c|c|c|c||c|c|c|}
        \hline
       Moments & $\quad  {\mathcal{U}}^s \quad $ & $\quad{\mathcal{U}^s_i}\quad$ & $\quad{\mathcal{U}^s_{ij}}\quad$ & $\quad{\mathcal{U}^s_{ijk}}\quad$ & $\quad{\mathcal{U}^s_{ijkl}}\quad$ &$\quad{\mathcal{U}_{ij}}\quad$ & $\quad{\mathcal{V}_{ij}}/{\mathcal{U}_{ijk}} \quad$ & $\quad{\mathcal{V}_{ijk}}/{\mathcal{U}_{ijkl}}\quad$ \\
        \hline
       Required precision & 2PN & 1.5PN & 1PN & 0.5PN &0PN & 1PN & 0.5PN & 0PN \\
        \hline
    \end{tabular}
    \caption{Required radiative moments to derive the full waveform amplitude to 1PN order.}
    \label{tab:radiative_moments_for_waveform}
\end{table*}
%
Hence, in order to compute the 1PN waveform, we need to calculate three additional radiative moments compared to those required for the 1PN flux, namely ${\mathcal{U}^s_{ijkl}}$, $\mathcal{V}_{ijk}$ and ${\mathcal{U}_{ijkl}}$ to 0PN order. 

%------------------------------------------------------------------------
\subsection{Radiative multipole moments}
%------------------------------------------------------------------------

Based on the PN-MPM formalism adapted to ST theories, the mass-type and current-type radiative moments can be expressed in terms of two sets of multipole moments, the sources moments $\{I_L, J_L\}$ and gauge ones $\{W_L, X_L, Y_L,Z_L\}$. These two sets are physically equivalent to the set of canonical moments $\{M_L, S_L\}$. However, as we anticipated in Sec.~\ref{sec:asymptotic_waveform}, the moment required at the highest order to compute the gravitational flux is the mass quadrupole $I_{ij}$, needed to 1PN order. At this precision, the gauge moments do not contribute, so the radiative moments depend only on the source ones. Additionally, it is known in GR that the radiative moments acquire some non-linear contributions, notably the tail and memory terms, the latter concerning only the mass-type multipole moments. However, they also enter at orders higher than the ones we are considering here. As a consequence, the radiative moments relate to the source moments only by the simple relations
%
\begin{align}
U_L = I_L^{(\ell)} \quad \text{and} \quad V_L = J_L^{(\ell)}\,,
\end{align}
%
where the upper index $(\ell)$ refer to the $\ell^{\text{th}}$ time derivative. Similarly, a previous work~\cite{Bernard:2022noq} has shown that the scalar radiative moments also acquire some tail contributions. It is notably the case for the scalar dipole moment $U_i^s$ that differs from its once-differentiated source moment by the relation 
%
\begin{align}\label{eq:dipole_moment_tail}
\mathcal{U}_i^s &= \overset{(1)}{I_i^s} + \frac{2GM}{\phi_0 c^3} \int_{-\infty}^U \dd V \overset{(3)}{I_i^s}(V) \left[ \ln{\left(\frac{U-V}{2b} \right)} + 1 \right] \,.
\end{align}
%
The rest of the scalar moments needed to derive the 1PN total flux and waveform simply satisfy
%
\begin{align}
U_L^s = {(I_L^s)}^{(\ell)}\,.
\end{align}
%
The general expression of the source moments in terms of the parameters of the source, specifically in terms of the PN expansion of the scalar and tensor pseudo-tensors~\eqref{tau}, along with the methodology to compute these moments, is provided in Sec.~\ref{sec:source_moments}.

%------------------------------------------------------------------------
\subsection{Memory contributions to $m=0$ gravitational modes}
\label{sec:memory}
%------------------------------------------------------------------------

In the previous section, we have discussed how non-linear memory effects do not contribute to the radiative multipole moments at the order we are considering for the derivation of the gravitational flux. However, they do impact the gravitational waveform. To illustrate this, we consider the quadrupole moment, whose memory contributions are given by~\cite{Bernard:2022noq} 
%
\begin{equation}\label{eq:U_ij_mem}
\mathcal{U}_{ij}^{(\text{mem})} = \frac{G(3+2 \omega_0)}{3c^3}\Bigg( \int_{-\infty}^U \!\dd V \overset{(2)}{I^s_{\langle i}}(V)\overset{(2)}{I^s_{j\rangle}}(V) -I^s_{\langle i}\overset{(3)}{I^s_{j\rangle}}- \overset{(1)}{I^s_{\langle i}}\overset{(2)}{I^s_{j\rangle}} -\frac{1}{2}I^s \overset{(3)}{I^s_{ij}} \Bigg) + \mathcal{O}\left(\frac{1}{c^5};\frac{\etidal}{c^5}\right) \,.
\end{equation}
%
These contributions formally appear at $1.5$PN order. When computing them, we will typically encounter two types of integrals: oscillatory integrals of the form
%
\begin{equation}\label{eq:AC}
\int_{-\infty}^{U} \dd \tau \, x^p(\tau) e^{-\di n \phi(\tau)} = \di \frac{\alpha \tilde{G} m}{n c^3}e^{-\di n \phi}x^{p-3/2}\,,
\end{equation}
%
and non-oscillatory integrals as
%
\begin{equation}\label{eq:DC}
\int_{-\infty}^{U} \dd \tau \, x^p(\tau) = \int_0^{x(U)} \dd y \, \frac{y^p}{\dot{x}(y)} \,.
\end{equation}
%
After integration, the oscillatory contributions coming from~\eqref{eq:AC} yield 1.5PN correction to the waveform and can therefore be neglected in this work. By contrast, for the non-oscillatory integrals, we need the time evolution of the gauge-invariant parameter $x$, which is governed at leading order in the point-particle approximation by 
%
\begin{equation}\label{eq:xdot_0PN}
\dot{x} =\frac{8 c^3 \zeta \mathcal{S}_{-}{}^2 \nu x^4}{3 \alpha \tilde{G} m} \sim \mathcal{O}\left(\frac{1}{c^{5}}\right) \,,
\end{equation}
%
where $x\sim \mathcal{O}(c^{-2})$.  As a result, after integration, the non-oscillatory terms, although formally entering at 1.5PN order, effectively contribute at Newtonian order in the waveform.

We recall that memory effects only affect the mass-type radiative moments $U_L$, and consequently the gravitational modes, with $\ell$ even. Furthermore, because the motion is quasi-circular, non-oscillatory memory effects only contribute to the $m=0$ gravitational modes. Instead of computing these effects directly from the mass-type radiative moments, which would require us to compute them up to the $n+1.5$PN order to remain consistent (with $n$ denoting the order typically required, as summarized in Table~\ref{tab:radiative_moments_for_waveform}), we proceed similarly as in~\cite{Favata:2008yd} and compute the $m=0$ modes via the angular integral: 
%
\begin{equation}\label{eq:hlmmem_generic}
h_{\ell m }^\text{mem} = -\frac{16\pi G}{R \phi_0 c^4}\sqrt{\frac{(\ell-2)!}{(\ell+2)!}}\int^{T_R}_{-\infty} \dd t \int \dd \Omega \,\frac{\dd \mathcal{F}}{\dd\Omega} (\Omega) Y_{\ell m}^{*}(\Omega) = \int_{-\infty}^{T_R} \dd t \,\dot{h}_{\ell m }^\text{mem}\,.
\end{equation}
%
In ST theories, $\dot{h}_{\ell m }^\text{mem}$ is made of two components, associated respectively to the gravitational and scalar fluxes, as :
%
\begin{equation}
\dot{h}_{\ell m }^\text{mem}= \dot{h}_{\ell m}^\text{mem, g} + \dot{h}_{\ell m}^\text{mem, s} \,.
\end{equation}
%
The first component on the right hand side is the same as in GR and reads
%
\begin{equation}\label{eq:hlmmemdotgen_grav}
\dot{h}_{\ell m}^\text{mem, g} = -\frac{R}{c}\sqrt{\frac{(\ell-2)!}{(\ell+2)!}}\sum_{\ell'=2}^\infty\sum_{\ell''=2}^\infty \sum_{m'=-\ell'}^{\ell'}\sum_{m''=-\ell''}^{\ell''} (-1)^{m+m''} G^{2 -2 0}_{\ell' \ell'' \ell m'-m''-m}\,\dot{h}_{\ell' m'}\dot{h}^{*}_{\ell'' m''}\,,
\end{equation}
%
where the value of the angular integral $G^{s s' s''}_{\ell \ell' \ell'' m m' m''}$ is given in \textit{e.g.} Appendix A of~\cite{Favata:2008yd}. The second component is obtained by combining the definitions given in Eqs.~\eqref{eq:fluxes_scalar},~\eqref{eq:psi_spheri_harmonic}, and~\eqref{eq:hlmmem_generic}, and one finds
%
\begin{equation}\label{eq:hlmmemdotgen_scal}
\dot{h}_{\ell m }^\text{mem, s} =-\frac{R (3+2 \omega_0)}{c}\sqrt{\frac{(\ell-2)!}{(\ell+2)!}}\sum_{\ell'=0}^\infty\sum_{\ell''=0}^\infty \sum_{m'=-\ell'}^{\ell'}\sum_{m''=-\ell''}^{\ell''} (-1)^{m+m''} G^{0 \,0\, 0}_{\ell' \ell'' \ell m'-m''-m}\,\dot{\psi}_{\ell' m'}\dot{\psi}^{*}_{\ell'' m''}\,.
\end{equation}
%

