%------------------------------------------------------------------------
\section{Intermediate quantities}
\label{sec:intermediate_quantities}

%------------------------------------------------------------------------
%------------------------------------------------------------------------

To derive the 1PN tidal contributions to the gravitational and scalar fluxes and waveforms, as well as to the 2PN orbital phase, it is necessary to first compute a set of intermediate quantities. This section is dedicated to the derivation of these key building blocks. The most relevant results are collected in a second \textit{Mathematica} file~\cite{SuppMaterial}, available upon request to interested readers.

%------------------------------------------------------------------------
\subsection{Dissipative 1.5PN term in the equations of motion}
%------------------------------------------------------------------------

In a previous work~\cite{Bernard:2023eul}, we have derived the 2PN tidal corrections to the conservative equations of motion, focusing exclusively on the even PN contributions. However, to treat the radiative sector, we must also account for the dissipative 1.5PN terms in the equations of motion. These contributions are important for two purposes: to compute the scalar dipolar moment, which contributes to the scalar energy flux and the mode $\hat{\Psi}^{11}$; and to determine the 1.5PN correction to the center-of-mass position, which is required to express the source moments in the center-of-mass frame. 
To derive the 1.5PN acceleration for body A in harmonic coordinates, we derive the geodesic equations by varying the matter action~\eqref{eq:Smatter+tidal} w.r.t the position of body A $y_a^{\mu}$. Since we only need the 1.5PN terms, it suffices to consider only the scalar dipolar part in the tidal action~\eqref{eq:Stidal}. Then, we perform a (3+1) splitting, as well as a PN expansion of that geodesic equation, wich can be recasted into the following form 
%
\be\label{eq:dPdtF}
\frac{\dd P^i}{\dd t} = F^i\,,
\ee
%
where $P^i=P^i_\text{pp}+P^i_\text{tidal}$ and $F^i=F^i_\text{pp}+F^i_\text{tidal}$ read:
%
\bse\label{eq:EoM_P_F}
\begin{align}
P^i_\text{pp} = & \, m \Biggl[v{}^{i} + \frac{1}{c^2}\biggl(\bigl(\psi_{(0)} (1 - 2 s) + \frac{1}{2} v^2 + 3 V\bigr) v{}^{i} - 4 V^{i}\biggr) \Biggr] + \calO\left(\frac{1}{c^4}\right)\,,\\
P^i_\text{tidal} = & \, \frac{\lambda^{(0)}}{c^4} \Biggl[2 (\partial_{a}\psi_{(0)} \partial^{a}\psi_{(0)}) v{}^{i} - 4 \biggl((v{}^{a} \partial_{a}\psi_{(0)}) + 
\partial_t \psi_{(0)}\biggr) \partial^{i}\psi_{(0)}\Biggr]+ \calO\left(\frac{\etidal}{c^4}\right)\,,\\
F^i_\text{pp} =& \, m \Biggl\{- (1 - 2 s) \partial^{i}\psi_{(0)} + \partial^{i}V + \frac1{c^2}\biggl[\biggl(\frac{(1 -  \zeta) (-4 \bar{\delta} -  \frac{32 \bar{\beta}\, \bar{\delta}}{\bar{\gamma}^2}) }{\zeta (2 + \bar{\gamma})^2}\psi_{(0)} + (1 - 2 s) \bigl(\frac{1}{2} v^2 + V\bigr)\biggr) \partial^{i}\psi_{(0)} \nn \\
& \quad + \bigl(\psi_{(0)} (1 - 2 s) + \frac{3}{2} v^2 -  V\bigr) \partial^{i}V - 4 v{}^{a} \partial^{i}V_{a}\biggl]\Biggr\}+ \calO\left(\frac{1}{c^4}\right)\,,\\
F^i_\text{tidal} = & \, - \frac{4 \lambda^{(0)}}{c^2} \partial^{a}\psi_{(0)} 
\partial^{i}\partial_{a}\psi_{(0)} + \frac{1}{c^4}\Biggl[4 \phi_{0}{} 
\lambda^{(1)} \biggl((\partial_{a}\psi_{(0)} \partial^{a}\psi_{(0)}) 
\partial^{i}\psi_{(0)} + 2 \psi_{(0)} \partial^{a}\psi_{(0)} 
\partial^{i}\partial_{a}\psi_{(0)}\biggr) \nn \\
& \quad - 2 \lambda^{(0)} \biggl(2 
(v{}^{a} \partial_{a}\psi_{(0)}) \partial_t \partial^{i}\psi_{(0)} - 
5 (\partial_{a}\psi_{(0)} \partial^{a}\psi_{(0)}) \partial^{i}\psi_{(0)} + 
4 \lambda_1 (\partial_{a}\psi_{(0)} \partial^{a}\psi_{(0)}) \partial^{i}\psi_{(0)} \nn \\
& \quad + \frac{4 (1 -  \zeta) \lambda_1 (\partial_{a}\psi_{(0)} 
\partial^{a}\psi_{(0)}) \partial^{i}\psi_{(0)}}{\zeta} - 3 
(\partial_{a}\psi_{(0)} \partial^{a}\psi_{(0)}) \partial^{i}V  + 2 
(v{}^{a} \partial_{a}\psi_{(0)}) v{}^{a} 
\partial^{i}\partial_{a}\psi_{(0)} \nn \\
& \quad + 2 v{}^{a} \partial_t \psi_{(0)} \
\partial^{i}\partial_{a}\psi_{(0)} - 10 \psi_{(0)} \partial^{a}\psi_{(0)} 
\partial^{i}\partial_{a}\psi_{(0)}  + 8 \lambda_1 \psi_{(0)} \partial^{a}\psi_{(0)} \partial^{i}\partial_{a}\psi_{(0)} \nn \\
& \quad+ \frac{8 (1 -  \zeta) \lambda_1 
\psi_{(0)} \partial^{a}\psi_{(0)} \partial^{i}\partial_{a}\psi_{(0)}}{\zeta} -  v^2 \partial^{a}\psi_{(0)} 
\partial^{i}\partial_{a}\psi_{(0)}  - 6 V \partial^{a}\psi_{(0)} 
\partial^{i}\partial_{a}\psi_{(0)}\biggr)\Biggr] \nn \\
& \quad+ \calO\left(\frac{\etidal}{c^4}\right)\,.
\end{align}
\ese
%
To derive the equations of motion for body $A$, one has to evaluate each quantity appearing in the Eqs.~\eqref{eq:EoM_P_F} at the location of body $A$. Specifically, it involves  replacing the mass $m$ by $m_a$, the velocity $v^i$ by $v^i_a$, the sensitivity $s$ by $s_a$, the parameter $\bar{\delta}$ by $\bar{\delta}_a$, the tidal deformability coefficient $\lambda^{(0)}$ by $\lambda_a^{(0)}$, and so on. Additionally, the potentials and their derivatives have to be evaluated at the location of body $A$. From Eqs.~\eqref{eq:EoM_P_F}, we see that the potentials $V$ and $\psi_{(0)}$ need be known to 1.5PN order, including their tidal corrections. This is done by inverting the flat spacetime wave equations~\eqref{eq:PotentialWaveEq} using the usual retarded d’Alembertian integral, written as an infinite PN-expansion of Poisson-like integrals, namely
%
\be\label{eq:invDalemvertian}
P(\mathbf{x},t) = \Box^{-1}_\text{ret} S(\mathbf{x},t) = -\frac{1}{4\pi} \sum_{k=0}^\infty \frac{(-)^k}{k!c^k} \frac{\dd^k}{\dd t^k}\text{PF}\int \dd^3\mathbf{x}'\vert \mathbf{x}-\mathbf{x}'\vert^{k-1} S(\mathbf{x}',t)\,,
\ee
%
where the operator PF stands for the \textit{Partie Finie} regularization scheme, and its there to cure the ultra-violet divergences associated to the eﬀective model of point masses~\cite{Blanchet:2000nu}.  The serie~\eqref{eq:invDalemvertian} scales as $1/c$ rather than $1/c^2$, leading to the appearance of odd-PN contributions in the potentials, and consequently in the acceleration. After injecting the potentials and their derivatives in $P^i$ and $F^i$, and time-differentiating $P^i$, we order-reduce all the resulting accelerations which only enter to 0PN order. Finally, we obtain the 1.5PN acceleration for body 1 in harmonic coordinates, whose 1PN part is in agreement with our previous result~\cite{Bernard:2023eul}.  Here, we choose to display only the 1.5PN tidal contribution reduced to the CoM frame, that we split into its point-particle and tidal contributions 
%
\be\label{eq:EoM_dissipative_pp_tidal}
\bm{a}^{\text{1.5PN}} = \bm{a}_{\text{pp}}^{\text{1.5PN}}+\bm{a}_{\text{tidal}}^{\text{1.5PN}}\,.
\ee
%
with
%
\begin{subequations}\label{eq:EoM_dissipative}
\begin{align}
\bm{a}_{\text{pp}}^{\text{1.5PN}} &= \frac{4 \alpha^2  \tilde{G}^2 m{}^2  \nu }{3 c^3 r^3} \mathcal{S}_{-}{}^2\zeta\bigl(3 \bm{n} (n v) -  \bm{v}\bigr) \\
\bm{a}_{\text{tidal}}^{\text{1.5PN}}& =  \, \frac{8 \alpha^2  \tilde{G}^2 m }{3 c^5 r^5}\frac{\zeta^2\mathcal{S}_{-}{}}{\bar{\gamma}(1 -  \zeta)} \Biggl\{\bm{v} \biggl[(n v)^2 \bigl((-45 \mathcal{S}_{+}{} - 45 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} + (-45 \mathcal{S}_{-}{} - 45 \mathcal{S}_{+}{} \delta) \lambda_{+}^{(0)}\bigr) \nn \\
& \hspace{-0.5cm} + v^2 \bigl((9 \mathcal{S}_{+}{} + 9 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} + (9 \mathcal{S}_{-}{} + 9 \mathcal{S}_{+}{} \delta) \lambda_{+}^{(0)}\bigr)\biggr] + \bm{n} \Bigl[(n v)v^2 \bigl((-45 \mathcal{S}_{+}{} - 45 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} + (-45 \mathcal{S}_{-}{} - 45 \mathcal{S}_{+}{} \delta) \lambda_{+}^{(0)}\bigr) \nn \\
& \hspace{-0.5cm} + (n v)^3 \bigl((105 \mathcal{S}_{+}{} + 105 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} + (105 \mathcal{S}_{-}{} + 105 \mathcal{S}_{+}{} \delta) \lambda_{+}^{(0)}\bigr)\Bigr]  + \frac{\alpha \tilde{G} m}{r} \biggl[\bm{n} (n v) \biggl((33 \mathcal{S}_{+}{} + 33 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} \nn \\
& \hspace{-0.5cm} + (33 \mathcal{S}_{-}{} + 33 \mathcal{S}_{+}{} \delta - 24 \bar{\gamma} \mathcal{S}_{-}{} \nu) \lambda_{+}^{(0)}\biggr) + \bm{v} \biggl((-7 \mathcal{S}_{+}{} - 7 \mathcal{S}_{-}{} \delta) \lambda_{-}^{(0)} + (-7 \mathcal{S}_{-}{} - 7 \mathcal{S}_{+}{} \delta + 4 \bar{\gamma} \mathcal{S}_{-}{} \nu) \lambda_{+}^{(0)}\biggr)\biggr]\Biggr\}  \,.
\end{align}
\end{subequations}
%

%------------------------------------------------------------------------
\subsection{Dissipative 1.5PN term in center-of-mass position}
%------------------------------------------------------------------------
While the 2PN CoM position $G^i$, along with the associated tidal corrections, has already been computed for the dynamical sector and displayed in Eq.(45) of~\cite{Bernard:2023eul}, we now provide  its 1.5PN contributions arising from the dissipative terms in the EoM. They are written as 
%
\begin{equation}\label{eq:Gi_dissipative_1}
\left(G^i\right)^{\text{1.5PN}}=\left(G^i\right)_{\text{pp}}^{\text{1.5PN}}+\left(G^i\right)_{\text{tidal}}^{\text{1.5PN}}\,,
\end{equation}
%
with
%
\begin{subequations}\label{eq:Gi_dissipative_2}
\begin{align}
\left(G^i\right)_{\text{pp}}^{\text{1.5PN}} = & - \frac{\alpha \tilde{G} \zeta \mathcal{S}_{-}{}}{3 c^3} \Bigl[m_{2}{} (- \mathcal{S}_{-}{} + \mathcal{S}_{+}{}) + m_{1}{} (\mathcal{S}_{-}{} + \mathcal{S}_{+}{})\Bigr] (m_{1}{} v_{1}{}^{i} -  m_{2}{} v_{2}{}^{i})\,,   \\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\left(G^i\right)_{\text{tidal}}^{\text{1.5PN}} = & \frac{2 \alpha^2 \tilde{G}^2 \zeta^2 (2 + \bar{\gamma}) }{3 c^5 (-1 + \zeta) r_{12}{}^3} \Bigl[m_{2}{} (- \mathcal{S}_{-}{} + \mathcal{S}_{+}{}) + m_{1}{} (\mathcal{S}_{-}{} + \mathcal{S}_{+}{})\Bigr] \Bigl[m_{2}{} (\mathcal{S}_{-}{} -  \mathcal{S}_{+}{}) \lambda_1^{(0)} \nn \\
&+ m_{1}{} (\mathcal{S}_{-}{} + \mathcal{S}_{+}{}) \lambda_2^{(0)}\Bigr] \Bigl[3 n_{12}{}^{i} \bigl((n_{12} v_{1}) -  (n_{12} v_{2})\bigr) -  v_{1}{}^{i} + v_{2}{}^{i}\Bigr] \,.
\end{align}
\end{subequations}
%
The odd-PN contributions to the positions and the velocities in the CoM frame and in the point-particle approximation can be found in \textit{e.g} Eqs.~(A2) of~\cite{Bernard:2022noq}. Their tidal corrections read
%
\begin{subequations}\label{eq:y1i_v1i_CM_dissipative}
\begin{align}
\left(y_1^i\right)_{\text{tidal}}^{\text{1.5PN}} &=  \frac{\alpha^2 \tilde{G}^2 m}{3 c^5  r^3}\frac{\zeta}{(1 -  \zeta) \bar{\gamma} (2 + \bar{\gamma})} \bigl(3 n^{i} (n v) -  v^{i}\bigr) \Bigl[\Bigl(8 \bar{\delta}^+ + 8 \bar{\delta}^- \delta - 4 \bigl(4 \bar{\delta}^+ + \bar{\gamma} (2 + \bar{\gamma})\bigr) \nu \Bigr) \lambda_{-}^{(0)} \nn \\
& + (8 \bar{\delta}^- + 8 \bar{\delta}^+ \delta - 16 \bar{\delta}^- \nu) \lambda_{+}^{(0)}\Bigr] \,,\\
%%%%%%%%%%
\left(v_1^i\right)_{\text{tidal}}^{\text{1.5PN}} &=  \frac{\alpha^2 \tilde{G}^2 m}{c^5  r^4} \frac{\zeta}{(1 -  \zeta) \bar{\gamma} (2 + \bar{\gamma})} \Bigl\{(n v) v^{i} \Bigl[\Bigl(16 \bar{\delta}^+ + 16 \bar{\delta}^- \delta + \bigl(-32 \bar{\delta}^+ - 8 \bar{\gamma} (2 + \bar{\gamma})\bigr) \nu \Bigr) \lambda_{-}^{(0)} \nn  \\
& + (16 \bar{\delta}^- + 16 \bar{\delta}^+ \delta - 32 \bar{\delta}^- \nu) \lambda_{+}^{(0)}\Bigr]   + \frac{\alpha \tilde{G} m}{r} n^{i} \Bigl[\Bigl(- \frac{16}{3} \bar{\delta}^+ -  \frac{16}{3} \bar{\delta}^- \delta + \bigl(\frac{32}{3} \bar{\delta}^+ + \frac{8}{3} \bar{\gamma} (2 + \bar{\gamma})\bigr) \nu \Bigr) \lambda_{-}^{(0)} \nn \\
&  + \Bigl(- \frac{16}{3} \bar{\delta}^- + \frac{16}{3} \bar{\delta}^- (2 + \bar{\gamma}) \nu + \delta \Bigl(- \frac{16}{3} \bar{\delta}^+ + \bigl(\frac{16}{3} \bar{\delta}^+ \bar{\gamma} + \frac{4}{3} \bar{\gamma}^2 (2 + \bar{\gamma})\bigr) \nu \Bigr)\Bigr) \lambda_{+}^{(0)}\Bigr] \nn \\
&  + n^{i} \Bigl[v^2 \Bigl(\Bigl(8 \bar{\delta}^+ + 8 \bar{\delta}^- \delta + \bigl(-16 \bar{\delta}^+ - 4 \bar{\gamma} (2 + \bar{\gamma})\bigr) \nu \Bigr) \lambda_{-}^{(0)} + (8 \bar{\delta}^- + 8 \bar{\delta}^+ \delta - 16 \bar{\delta}^- \nu) \lambda_{+}^{(0)}\Bigr)\nn \\
&  + (n v)^2 \Bigl(\Bigl(-40 \bar{\delta}^+ - 40 \bar{\delta}^- \delta + \bigl(80 \bar{\delta}^+ + 20 \bar{\gamma} (2 + \bar{\gamma})\bigr) \nu \Bigr) \lambda_{-}^{(0)} + (-40 \bar{\delta}^- - 40 \bar{\delta}^+ \delta + 80 \bar{\delta}^- \nu) \lambda_{+}^{(0)}\Bigr)\Bigr]\Bigr\}\,.
\end{align}
\end{subequations}
%
while $\left(y_2^i\right)_{\text{tidal}}^{\text{1.5PN}}$ and $\left(v_2^i\right)_{\text{tidal}}^{\text{1.5PN}}$ are given by $1 \leftrightarrow 2$. 

%------------------------------------------------------------------------
\subsection{Source multipole moments}
\label{sec:source_moments}
%------------------------------------------------------------------------

The first step to compute the radiative multipole moments consists in deriving their source counterparts at the same PN orders as the ones displayed in Tables~\ref{tab:radiative_moments_for_flux} and \ref{tab:radiative_moments_for_waveform}. The procedure to obtain their expressions in terms of the source, consisting in a matching of the MPM expansion of the fields to their PN expansions in the near zone, can be found in~\cite{Blanchet:1998in} in GR, and it has been adapted to ST theories in~\cite{Bernard:2022noq}. There are two different sets of STF moments, the usual mass-type and current-type ones $(I_L,J_L)$ given for any $ \ell\ge 2$, and the scalar-type moments $I^s_L$ given for any $ \ell\ge 0$. They read
%
\begin{subequations}\label{eq:momentsIJIs}
	\begin{align}
	I_L(u) &= \mathop{\mathrm{FP}}_{B=0}\int \ud^3 \mathbf{x} \,\tilde{r}^B \int_{-1}^1 \ud z \bigg[ \delta_\ell(z) \hat{x}_L \Sigma - \frac{4(2\ell +1)}{c^2(\ell+1)(2\ell+3)} \delta_{\ell+1}(z) \hat{x}_{iL} \Sigma^{(1)}_i \nn\\
	& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad + \frac{2(2\ell + 1)}{c^4 (\ell+1)(\ell+2)(2\ell+5)} \delta_{\ell+2}(z) \hat{x}_{ijL} \Sigma^{(2)}_{ij}  \bigg] ( \mathbf{x}, u+z r/c) \,,\\
	J_L(u) &= \mathop{\mathrm{FP}}_{B=0} \int \ud^3 \mathbf{x} \,\tilde{r}^B \int_{-1}^1 \ud z \,\varepsilon_{ab\langle i_\ell} \bigg[ \delta_\ell(z) \hat{x}_{L-1\rangle a} \Sigma_b -\frac{2\ell+1}{c^2(\ell+2)(2\ell+3)} \delta_{\ell+1}(z) \hat{x}_{L-1\rangle ac} \Sigma^{(1)}_{bc}\bigg]( \mathbf{x}, u + z r/c)\,,\\
    I^s_L(u) &=\mathop{\mathrm{FP}}_{B=0} \int \ud^3 \mathbf{x}\,\tilde{r}^B  \int_{-1}^1 \ud z \,\delta_\ell(z) \,\hat{x}_L \Sigma^s ( \mathbf{x}, u+z r/c)\,.
	\end{align}
\end{subequations}
%
where we have introduced the ST source terms $\Sigma \equiv (\bar\tau^{00} + \bar\tau^{ii})/c^2$, $\Sigma_i \equiv \bar\tau^{0i}/c$, $\Sigma_{ij} \equiv \bar\tau^{ij}$ and $\Sigma^s \equiv  \bar\tau_s/c^2$. The finite part (FP) operator is there to cure the infra-red (IR) divergences, as the PN-expanded integrand is expected to diverge at spatial infinity. The integrations over z are transformed into infinite PN series
\begin{equation}\label{eq:intdeltal}
\int^1_{-1} \ud z~ \delta_\ell(z) \,\Sigma( \mathbf{x}, u+z r/c) = \sum_{k=0}^{+\infty}\,\frac{(2\ell+1)!!}{(2k)!!(2\ell+2k+1)!!}
	\,\left(\frac{r}{c}\right)^{2k} \!\Sigma^{(2k)}(\mathbf{x},u)\,,
\end{equation}
and lead to time derivatives of the source terms. In practice, we start by performing the PN expansion of the pseudo stress-energy tensors $\tau^{\mu \nu}$ and $\tau^s$ defined by Eqs.~\eqref{tau} at the orders that we need, decomposing them into their spatial and temporal indices using the parametrization of the scalar and tensor fields~\eqref{metric_decomp}. Next, we insert such expansions into the definitions of the sources moments~\eqref{eq:momentsIJIs}, resulting into spatial integrals involving both compact and non-compact support terms. The former ones are either linear in the three dimensional Dirac distribution, $ \delta^{(3)}_a \equiv \delta^{(3)} (\mathbf{x} - \bm{y}_a) $, or involve higher spatial and/or time derivatives of expressions linear in $\delta^{(3)}_a$. As a consequence, we handle these integrations by parts before performing the integration at the location of body A using the Hadamard regularization scheme. The non-compact support terms consist in products of the potentials, that are integrated over all space. Methods to evaluate these integrals are explained in \textit{e.g.}~\cite{Blanchet:2000nu}. The resulting source moments are general functions of the harmonic coordinates, and we reduce them to the CoM frame using Eqs.~\eqref{eq:y1i_v1i_CM_dissipative} and Eqs.(43)-(44) in~\cite{Bernard:2023eul}. Since the expressions for the source moments are very long, even in the CoM frame, and constitute only an intermediate result, we relegated them to the Mathematica supplementary file~\cite{SuppMaterial}. 
Finally, we reduce the source moments to quasi-circular orbits, using similar methods as in Sec.~\ref{sec:dynamics_circ}. However, since we work in the radiative sector, we must account for the radiation-reaction effects that start contributing at 1.5PN order in ST, while they only start at 2.5PN in GR. In particular, we have $\bm{v}= \omega r \bm{\lambda} + \dot{r} \bm{n}$, where we denote $\dot{r}\equiv{\bf n}\cdot{\bfv}$. At 1.5PN order, the expression for $\dot{r}$ reads
%
\begin{align}\label{eq:rdot}
\dot{r} &=- \frac{8}{3} c\, \zeta \mathcal{S}_{-}{}^2 \nu x^2 + \frac{16 \,c\, \zeta x^5}{9 (1 -  \zeta) \bar{\gamma}^2} \Bigl\{16 \zeta \bar{\gamma}^2 \mathcal{S}_{-}{}^2 \nu \tilde{\lambda}_{+}^{(0)} +  \sqrt{\alpha} \Bigl[-3 \mathcal{S}_{-}{} \delta (4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{-}^{(0)} -  \bar{\gamma} \tilde{\Lambda}_{+}^{(0)} + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) \nn \\
& \quad - 24 \zeta \bar{\gamma} \mathcal{S}_{-}{}^2 \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)}) - 3 \mathcal{S}_{-}{} (- \bar{\gamma} \tilde{\Lambda}_{-}^{(0)} + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{-}^{(0)} + 4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\Bigr]\Bigr\} +\mathcal{O}\left( \frac{1}{c^5} ; \frac{\epsilon_{\text{tidal}}}{c^5} \right) \,.
\end{align}
%
After expressing the source moments entirely in terms of the parameter $\gamma$, inserting  $\gamma$ and $\dot{r}$ as functions of the gauge invariant parameter $x$, and truncating at the correct order, we have reduced our expressions for the source moments to the case of quasi-circular orbits. The corresponding lengthy expressions are displayed in Appendix~\ref{App:source_moments_circ}. 

%------------------------------------------------------------------------
%------------------------------------------------------------------------
\section{Fluxes and orbital phase}
\label{sec:fluxes_phases}
%------------------------------------------------------------------------
%------------------------------------------------------------------------

We have now all the ingredients to compute the tidal corrections to the radiated scalar and gravitational energy fluxes up to 1PN order beyond the leading quadrupolar contribution, and to the orbital phase within the time domain and Fourier domain, up to the 2PN order beyond the leading dipolar contribution. These quantities are derived within the quasi-circular orbit approximation and written in terms of the frequency-dependent parameter~$x$. The complete results presented in this section are directly available in the supplementary \textit{Mathematica} file~\cite{SuppMaterial}. 

%------------------------------------------------------------------------
\subsection{Scalar and gravitational fluxes}
%------------------------------------------------------------------------

First, we derive the instantaneous gravitational and scalar fluxes in the CoM frame, discarding tail contributions. Substituting our expressions for the radiative moments (which relate to the source ones only by multiple time-differentiations) into Eq.~\eqref{eq:fluxes_1PN} yields 
%
\begin{subequations}
\begin{align}
\left(\mathcal{F}^g_{\text{inst}}\right)_{\text{tidal}}&= \frac{\alpha^4 \tilde{G}^4 m^4 \nu^2 \zeta (2 + \bar{\gamma}) }{c^5 (1 -  \zeta) r^7} \Biggl\{\frac{1}{c^2}\Biggl[\frac{896}{15} (n v)^2 \lambda_{+}^{(0)} -  \frac{256}{5} v^2 \lambda_{+}^{(0)}\Biggr] + \frac{1}{c^4}\Biggl[\frac{\alpha^2 \tilde{G}^2 m^2}{r^2} (- \frac{64}{21} + \frac{256}{21} \nu) \lambda_{+}^{(0)} \nn \\
& \hspace{-0.5cm}+ \bigl(- \frac{32}{35} (211 + 112 \bar{\gamma}) + 384 \nu \bigr) (n v)^4 \lambda_{+}^{(0)} + \bigl(\frac{32}{105} (705 + 392 \bar{\gamma}) - 448 \nu \bigr) (n v)^2 v^2 \lambda_{+}^{(0)} \nn \\
& \hspace{-0.5cm}+ \bigl(- \frac{64}{15} (11 + 6 \bar{\gamma}) + \frac{768}{7} \nu \bigr) v^4 \lambda_{+}^{(0)} + \frac{\alpha \tilde{G} m}{r} \biggl[\frac{(1 -  \zeta)}{\zeta} \Bigl((n v)^2 (80 \delta \lambda_1 \Lambda_{-}^{(0)} - 80 \lambda_1 \Lambda_{+}^{(0)}) + v^2 (-64 \delta \lambda_1 \Lambda_{-}^{(0)} + 64 \lambda_1 \Lambda_{+}^{(0)})\Bigr) \nn \\
&\hspace{-0.5cm}+ v^2 \Bigl(\bigl(\frac{256 \bar{\beta}^-}{\bar{\gamma}} -  \frac{16 (80 \bar{\beta}^+ + 14 \bar{\gamma} + 15 \bar{\gamma}^2) \delta}{5 \bar{\gamma}}\bigr) \lambda_{-}^{(0)} + \delta (80 - 64 \lambda_1) \Lambda_{-}^{(0)} + 32 \phi_{0}{} \delta \Lambda_{-}^{(1)} \nn \\
