%------------------------------------------------------------------------
\subsection{Orbital phase in the time domain}
%------------------------------------------------------------------------

The orbital phase can be obtained from the flux balance equation for the energy
%
\begin{align}\label{eq:flux_balance_eq}
\frac{\dd E}{\dd t} = - \mathcal{F}
\end{align}
%
where $\mathcal{F}$ is the total flux, including both scalar and gravitational contributions. Up to a constant, it satisfies
\begin{align}\label{eq:phase_TD}
\phi = -\frac{c^3}{\alpha \tilde{G} m}\int \dd x \, x^{3/2}\,\frac{\dd E/ \dd x}{\mathcal{F}(x)}\,.
\end{align}
By substituting our results for the energy and the flux, along with their point-particle counterparts taken from Refs.~\cite{Bernard:2018ivi} and~\cite{Bernard:2022noq}, into Eq.~\eqref{eq:phase_TD} 
%, re-expanding the ratio $(\dd E/ \dd x)/\mathcal{F}$ 
and after truncating at the relative 2PN order in the tidal corrections, we get an analytical expression for the time domain orbital phase up to the 2PN order. Special care must be taken when re-expanding this ratio. Indeed, as highlighted in~\cite{Sennett:2016klh}, the radiated flux contains both scalar and gravitational components, giving rise to two different regimes: a dipolar-driven (DD) regime, where the energy flux is dominated by dipolar emission which vanishes when $s_1 = s_2$, and a quadrupolar-driven (QD) regime, where the flux is dominated by quadrupolar emission. 
In the following, we focus exclusively in the DD-driven regime as the corrections to tidal effects due to the presence of the scalar field in ST theories are expected to be small and hardly observable in the QD regime~\cite{Bernard:2019yfz}.

Focusing on the DD regime, the phase derivation is straightforward and yields the following tidal correction 
%
\begin{align}\label{eq:phase_TD_value_DD}
\phi_{\text{tidal}} & = - \frac{4 x^{3/2}}{(-1 + \zeta) \zeta \bar{\gamma}^2 \mathcal{S}_{-}{}^3 \nu^2} \Bigl\{\zeta \bar{\gamma}^2 \mathcal{S}_{-}{} \nu \tilde{\lambda}_{+}^{(0)} + \sqrt{\alpha} \bigl(\frac{1}{8} \delta (-4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{-}^{(0)} + \bar{\gamma} \tilde{\Lambda}_{+}^{(0)} - 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) \nn \\
& -  \zeta \bar{\gamma} \mathcal{S}_{-}{} \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)}) + \frac{1}{8} (\bar{\gamma} \tilde{\Lambda}_{-}^{(0)} - 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{-}^{(0)} - 4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\bigr) \nn \\
& +x\Bigl[ ... \Bigr] + \sqrt{\alpha} (2 + \bar{\gamma}) \pi x^{3/2} \Bigl[\frac{1}{16} \delta (4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{-}^{(0)} -  \bar{\gamma} \tilde{\Lambda}_{+}^{(0)} + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) + \zeta \bar{\gamma} \mathcal{S}_{-}{} \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)}) \nn \\
& + \frac{1}{16} (- \bar{\gamma} \tilde{\Lambda}_{-}^{(0)} + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{-}^{(0)} + 4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\Bigr] + x^2 \Bigl[-  \frac{45}{112} \zeta \bar{\gamma}^2 \mathcal{S}_{-}{} \nu  \bigl(\tilde{c}_{+}^{(0)} - 4 (4 \tilde{\mu}_{+}^{(0)} + \tilde{\mu}_{+}^{(0)}) \bigr)+ (...)\Bigr] \nn \\
& + \calO\left(\frac{\etidal}{c^{5}}\right)\Bigr\}\,.
\end{align}
%
The corresponding point-particle contribution $\phi_{\text{pp}}^{DD}$ agrees with the 2PN result displayed \textit{e.g.} in Eq.(5.7) of~\cite{Bernard:2022noq}. 

%------------------------------------------------------------------------
\subsection{Orbital phase in the stationary phase approximation}
%------------------------------------------------------------------------

For data analysis purposes, we also present the phase within the stationary phase approximation (SPA)~\cite{Tichy:1999pv}. This technique consists in performing the Fourier transform of the gravitational waveform. We proceed similarly as in~\cite{Sennett:2016klh} and write the amplitude modes as
%
\begin{equation}
h_{\ell m}^{\text{SPA}}(f) = \mathcal{A}_{\ell m}(f)\mathrm{e}^{- \mathrm{i}\Phi^{\ell m }(f)-\mathrm{i} \pi/4 }\,.
\end{equation}
The SPA phase is given by 
%
\begin{equation}\label{eq:phase_SPA}
\Phi^{\ell m }(f) = m \left( \phi(v) - \frac{c^3}{\tilde{G}\alpha \, m_{\text{tot}}}v^3t(v) \right)
\end{equation}
%
where the parameter $v=x^{1/2}$ is evaluated at $v=(2/m)^{1/3}v_f$, with $v_f=(\pi \tilde{G}\alpha \,m_{\text{tot}} f/c^3)^{1/3}$ being the parameter associated to the GW frequency $f$. 
In order not to be confused with the $m$ mode appearing in the waveform, we change the notation for the total mass, $m_{\text{tot}} = m_1 + m_2$, in this section only. The functions $\phi(v)$ and $t(v)$ are computed directly from the flux balance equation~\eqref{eq:flux_balance_eq}, and they satisfy the following relations
%
\begin{subequations}
\label{eq:SPA_phi_t}
\begin{align}
\phi(v) &= \phi(v_0) - \frac{c^3}{\alpha \tilde{G} m_{\text{tot}}}\int^v_{v_0} \dd v \,v^3 \frac{\dd E/ \dd v}{\mathcal{F}(v)} \\
t(v) &= t(v_0)- \int^v_{v_0} \dd v \, \frac{\dd E/ \dd v}{\mathcal{F}(v)}
\end{align} 
\end{subequations}
% 
where $\phi(v_0)$ and $t(v_0)$ are constants evaluated at some reference point $v_0$. We have explicitly computed Eq.~\eqref{eq:phase_SPA} within the DD regime and we decompose the Fourier domain phase as
%
\begin{align}
\Phi^{\ell m }(f) = \Phi^{\ell m }_{\text{pp}}(f) + \Phi^{\ell m }_{\text{tidal}}(f) + m \phi_0 - 2 \pi f \,t_0 \,.
\end{align}
%
The constants $\phi_0$ and $t_0$ result from the sum of $\phi(v_0)$ and $t(v_0)$, respectively, and come from the lower boundaries of the integrals~\eqref{eq:SPA_phi_t}. Finally, the tidal correction to the phase reads
%
\begin{align}\label{eq:phase_SPA_value}
\Phi^{\ell m }_{\text{tidal}}(f) &= \frac{4 m v^3}{(-1 + \zeta) \zeta \bar{\gamma}^2 \mathcal{S}_{-}{}^3 \nu^2} \biggl\{
\bigl(-1 + 3 \log(v)\bigr) \Bigl(\zeta \bar{\gamma}^2 \mathcal{S}_{-}{} \nu \tilde{\lambda}_{+}^{(0)} + \sqrt{\alpha} \bigl(\frac{1}{8} \delta (-4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{-}^{(0)} + \bar{\gamma} \tilde{\Lambda}_{+}^{(0)} - 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) \nn \\
& -  \zeta \bar{\gamma} \mathcal{S}_{-}{} \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)}) + \frac{1}{8} (\bar{\gamma} \tilde{\Lambda}_{-}^{(0)} - 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{-}^{(0)} - 4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\bigr)\Bigr) + v^2 \Bigl[...\Bigr] \nn \\
& +\sqrt{\alpha} (2 + \bar{\gamma}) \pi v^3 \Bigl[\frac{1}{16} \delta (4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{-}^{(0)} -  \bar{\gamma} \tilde{\Lambda}_{+}^{(0)} + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) + \zeta \bar{\gamma} \mathcal{S}_{-}{} \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)}) + \frac{1}{16} (- \bar{\gamma} \tilde{\Lambda}_{-}^{(0)} \nn \\
& + 4 \zeta \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{-}^{(0)} + 4 \zeta \mathcal{S}_{-}{} \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\Bigr] + v^4 \Bigl[-  \frac{135}{448} \zeta \bar{\gamma}^2 \mathcal{S}_{-}{} \nu \bigl(\tilde{c}_{+}^{(0)} - 4 (4 \tilde{\mu}_{+}^{(0)} + \tilde{\nu}_{+}^{(0)})\bigr) + (...)\Bigr] + \calO\left(\frac{\etidal}{c^{5}}\right)\biggr\}  \,.
\end{align} 
%
The 2PN point-particle counterpart to Eq.~\eqref{eq:phase_SPA_value} agrees with Eq.(77) of~\cite{Sennett:2016klh} and the leading-order dipolar tidal correction matches Eq.(14) of~\cite{Bernard:2019yfz}. For a detailed comparison with the results of Ref.~\cite{Creci:2024wfu}, we refer the reader to Appendix~\ref{eq:comparison_Creci}. 

