& + 4 \zeta \bar{\gamma} \mathcal{S}_{-}{}^2 \tilde{\Lambda}_{+}^{(0)}) - 4 \zeta \bar{\gamma} \mathcal{S}_{-}{} \delta \nu (\mathcal{S}_{-}{} \tilde{\Lambda}_{-}^{(0)} + \mathcal{S}_{+}{} \tilde{\Lambda}_{+}^{(0)})\Bigr]+ x \Bigl[...\Bigr]\Bigr\}\,, \\
