%	&=&  r_1(l-\xi).%\label{eq:threshold_prob}
%\end{eqnarray*}
\begin{align*}
	\Pr\{L(l)>\xi\} &= \Pr\{(l - rS)^+ > \xi\} \nonumber\\
	&= \Pr\{l - rS > \xi\} \nonumber\\
	&= \Pr\{S < (l-\xi)/r\} \nonumber\\
	&= r_1(l-\xi).\label{eq:threshold_prob}
\end{align*}
and the expected loss above threshold $\xi$ is given by
% \begin{eqnarray*}
