\subsubsection{Asymptotic Analysis for $r_2(l)$ Estimation}\label{sec:asymptotic_r2}

In this subsection, we delve deeper into the analysis of 
$r_2(l) = \mathbb{E}\left[(l - rY)^+\right],$ and its approximation via QRGMM.
Compared to the estimation of the default probability $r_1(l)$, which involves the direct evaluation of the estimated conditional distribution function $F_{\hat{Y}}(y|\bx)$, the estimation of $r_2(l)$ is more subtle. It requires analyzing the convergence of the expectation of a transformation of the random variable $Y(\bx)$, namely the positive part $(l - rY)^+$. This complicates the asymptotic analysis since standard weak convergence results do not automatically guarantee convergence of expectations for general functions.

Fortunately, the structure of $r_2(l)$ offers an advantage: for all $l \in [0, \bar{l}]$, the function $y \mapsto (l - ry)^+$ is uniformly bounded by $\bar{l}$ and continuous in $y$. These properties enable us to invoke a classical result from probability theory regarding the convergence of expectations under weak convergence:

\begin{lemma}[Portmanteau Theorem]\label{lemma:Portmanteau}
	Let $Z_n \Rightarrow Z$ as $n \to \infty$. Then for any bounded and continuous function $h$, it holds that
	$
	\mathbb{E} \left[h(Z_n)\right] \to \mathbb{E} \left[h(Z)\right].
	$
\end{lemma}

This Portmanteau theorem (see, e.g., \citet[page~6]{van2000}) provides a critical tool in establishing uniform convergence of $\hat{r}_2(l)$. Specifically, for each $l \in [0, \bar{l}]$, we define the transformation
$
f_l(y) := (l - ry)^+,
$
which is uniformly bounded above by $\bar{l}$ and continuous on $[0, \infty)$. Given that $\hat{Y}(\bx) \Rightarrow Y(\bx)$ as $n, m \to \infty$ by Lemma~\ref{thm:r1weakconvergence_a}, applying Lemma~\ref{lemma:Portmanteau} ensures  pointwise convergence $\hat{r}_2(l) \to r_2(l)$  for each $l$. Furthermore, leveraging the equicontinuity of  $f_l(y) = (l - ry)^+ $ with respect to $l$, we can extend this result to uniform convergence over $l \in [0, \bar{l}]$. The result is summarized in the following theorem.
%The detailed proof is provided in the appendix, and the result is summarized in the following theorem.

\begin{theorem}\label{thm:r2_noMC_rate}
	Suppose that Assumptions~\ref{ass:cons1}--\ref{ass:cons3} hold, if $m$ satisfies $\frac{1}{m}\to 0$ and $\frac{n}{m}\to\infty$ as $n\to\infty$, then, for any given $\bx$, as $m,n\to\infty$,  we have
	\[
	\sup\limits_{l\in[0,\bar{l}]}\bigl|\hat{r}_{2}(l) - r_{2}(l)\bigr| \to 0.
	\]
\end{theorem}
\begin{proof}
	For any $l \in [0, \bar{l}]$, the function $f_l(y) = (l - ry)^+$ is Lipschitz continous in $y$ with Lipschitz constant $r$, and uniformly bounded with $0 \le f_l(y) \le \bar{l}$ for all $y \in \mathbb{R}$. %This means that the family $\{f_l\}_{l \in [0, \bar{l}]}$ is equicontinuous in $y$ and uniformly bounded. 
	Additionally, for all $y \in \mathbb{R}$ and $l, l' \in [0, \bar{l}]$, we have
	\[
	|f_l(y) - f_{l'}(y)| \le |l - l'|,
	\]
	which implies that $\{f_l\}$ is equicontinuous in the parameter $l$ (since each $f_l(y)$ is Lipschitz continuous in $l$ with a common Lipschitz constant constant $1$ regardless of $y$).

	For any $\bx \in \mathcal{X}$, since $\hat{Y}(\bx) \Rightarrow Y(\bx)$ as $n, m \to \infty$ by Lemma~\ref{thm:r1weakconvergence_a} and each $f_l$ is continuous and bounded, by Lemma~\ref{lemma:Portmanteau}, it follows that 
	\[
	\hat{r}_2(l)=\mathbb{E}[f_l(\hat{Y}(\bx))] \to r_2(l)=\mathbb{E}[f_l(Y(\bx))] 
	\]
	for every fixed  $l \in [0, \bar{l}]$.
	To strengthen this to uniform convergence over $l \in [0, \bar{l}]$, fix any $\epsilon > 0$. By the compactness of $[0, \bar{l}]$ and the equicontinuity of $\{f_l\}$ in $l$, there exists a finite $\delta$-net $\{l_1, \dots, l_T\} \subset [0, \bar{l}]$ such that for any $l \in [0, \bar{l}]$, there exists $j \in \{1, \dots, T\}$ with $|l - l_j| < \delta$, where $\delta := \epsilon / 3$. 

	Then for such $l$ and corresponding $l_j$, we decompose the total error as:
%	\[
%	\begin{aligned}
%		\left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_l(Y)] \right|
%		\leq &\left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| \\
%		&+ \left| \mathbb{E}[f_{l_j}(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(Y)] \right| \\
%		&+ \left| \mathbb{E}[f_{l_j}(Y)] - \mathbb{E}[f_l(Y)] \right|.
%	\end{aligned}
%	\]
	 \begin{eqnarray*}
		\lefteqn{ \left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_l(Y)] \right|} \\
		& \le & \left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| \\
		&+& \left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| \\
		&+&  \left| \mathbb{E}[f_{l_j}(Y)] - \mathbb{E}[f_l(Y)] \right|.
	\end{eqnarray*}
	The first and third terms are bounded by
%	\[
%	\left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| = \left| \mathbb{E}[f_l(\hat{Y}_n)-f_{l_j}(\hat{Y}_n)] \right|\leq \left|\mathbb{E}[l - l_j]\right|= |l - l_j |< \delta = \epsilon/3,
%	\]
%	\begin{align*}
%	\left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| 
%	&= \left| \mathbb{E}[f_l(\hat{Y}_n)-f_{l_j}(\hat{Y}_n)] \right| \\
%	&\leq \left|\mathbb{E}[l - l_j]\right|= |l - l_j |< \delta = \epsilon/3,
%	\end{align*}
	\begin{eqnarray*}
		\lefteqn{ \left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(\hat{Y}_n)] \right| } \\
		&=& \left| \mathbb{E}[f_l(\hat{Y}_n)-f_{l_j}(\hat{Y}_n)] \right| \\
		&\leq& \left|\mathbb{E}[l - l_j]\right|= |l - l_j |< \delta = \epsilon/3,
	\end{eqnarray*}
	and similarly for $\left| \mathbb{E}[f_{l_j}(Y)] - \mathbb{E}[f_l(Y)] \right|$.

	For the second term, since the set $\{l_1, \dots, l_T\}$ is finite and $\mathbb{E}[f_{l_j}(\hat{Y}_n)] \to \mathbb{E}[f_{l_j}(Y)]$ for each $j$, there exists $M$ and $N$ such that for all $m>M$, $n > N$ and all $j$,
	\[
	\left| \mathbb{E}[f_{l_j}(\hat{Y}_n)] - \mathbb{E}[f_{l_j}(Y)] \right| < \epsilon/3.
	\]

	Combining the above, we conclude that for all $l \in [0, \bar{l}]$ and all $m,n$ sufficiently large,
	\[
	\left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_l(Y)] \right| < \epsilon.
	\]
	Therefore,
	\[
	\sup\limits_{l\in[0,\bar{l}]}\bigl|\hat{r}_{2}(l) - r_{2}(l)\bigr|=\sup_{l \in [0, \bar{l}]} \left| \mathbb{E}[f_l(\hat{Y}_n)] - \mathbb{E}[f_l(Y)] \right| \to 0.
	\]
\end{proof}

This asymptotic guarantee is particularly significant in the SCF setting, where the continous and bounded structure of $f_l(y)$ simplify the analysis. Without these properties, expectation and tail behavior could complicate the convergence analysis, requiring stronger assumptions. Our approach effectively exploits this structure, leading to the uniform convergence for \( r_2(l) \) estimation. This result provides theoretical validation for the use of QRGMM in estimating expected loss risk measures, reinforcing its applicability in SCF risk management.


\subsubsection{Asymptotic Analysis for \( r_3(l) \) Estimation}\label{sec:asymptotic_r3}


Here, ignoring the MC error, we prove the uniform convergence of the estimated risk measure \( \hat{r}_3(l) = \mathbb{E} [ g_l(\hat{Y}(\bx)) \cdot \mathbf{I}_{\{\hat{Y}(\bx) < a(l)\}} ] \), computed using the QRGMM-based generative model \( \hat{Y}(\bx) \), to the true \( r_3(l) \). Unlike \( r_2(l) \), where the function \( (l - ry)^+ \) is continuous and bounded, enabling the use of the Portmanteau Theorem to establish convergence, the general form of \( g_l(y) \cdot \mathbf{I}_{\{y < a(l)\}} \) poses a challenge. The indicator function may introduce the discontinuity, rendering the transformation non-continuous. Thus, theoretical analysis method applied to \( \hat{r}_2(l) \) is not directly applicable to \( \hat{r}_3(l) \) .

To address this, we take a different approach to establish the uniform convergence for \( \hat{r}_3(l) \), which is consequently also applicable to \( \hat{r}_1(l) \) and \( \hat{r}_2(l) \). Specifically, we first impose the following regularity conditions on $g_l(\cdot)$ and $a(l)$:

\begin{assumption}\label{ass:cons4}	
	\hfill
	\begin{enumerate}[label=(4.\alph*), left=0pt]
		\item \label{ass:cons4a} \( a(l) \) is monotone on \( [0, \bar{l}] \), satisfies \( 0 \leq a(l) \leq a(\bar{l}) < \infty \), with \( a(l) \to 0 \) as \( l \to 0 \). 
		\item \label{ass:cons4b} \( g_l(\cdot) \) is differentiable and Lipschitz continuous with constant \( K \) within $y\in[0,a(\bar{l})]$ uniformly over $l\in[0,\bar{l}]$, and uniformly bounded by $g_{\bar{l}}(0)<\infty$.
	\end{enumerate} 
\end{assumption}


Assumption~\ref{ass:cons4a} requires \( a(l) \), a threshold function, to be monotonic in $l$ and and vanish as $l\to0$, reflecting the intuition that smaller loans imply lower trigger levels. Assumption~\ref{ass:cons4b} ensures that \( g_l(\cdot) \), representing loss in SCF, is differentiable, Lipschitz continuous with constant \( K \) (implying \( |g_l'(y)| \leq K \)) within $y\in[0,a(\bar{l})]$, and bounded by \( M = g_{\bar{l}}(0) \), reflecting the maximum loss in the worst case that sales \( Y = 0 \) and loan \( l = \bar{l} \).
These conditions, intuitive and reasonable for SCF risk management, ensure tractable analysis of \( \hat{r}_3(l) \), leading to the following result.

\begin{comment}
	Under the regularity conditions imposed on $g_l(\cdot)$ and $a(l)$, we derive a uniform upper bound on $|\hat{r}_3(l) - r_3(l)|$ over $l \in [0, \bar{l}]$, leveraging \textit{integration by parts}.
	Specifically, we define 
	$$
	\delta_{n,m} := \sup_{y \geq 0} |F_{\hat{Y}}(y|\mathbf{x}) - F_Y(y|\mathbf{x})|,
	$$
	then the difference between $\hat{r}_3(l)$ and $r_3(l)$ can be bounded as
	$$
	|\hat{r}_3(l) - r_3(l)| \leq (2M + K a(\bar{l})) \cdot \delta_{n,m},
	$$
