% i.e. the isomorphism class of the tree rooted at $p$. $l_p(p)$ will then be the label of the immediate predecessor of $p$. This gives us an actual labeling of $\mathcal{T}$ (the coarsest, by the previous lemma). When we use \lemref{ch2-lem0.5} we get a non-edge-collapsing equivalence relation $\sim_l$, when we factor over it we get the canonical graph
%     \[CG(\mathcal{T}):=\mathcal{T}/{\sim_l}\]
% that unfolds into $\mathcal{T}$. Furthermore, it has an actual labeling by the previous remark. So each cocompact tree $\mathcal{T}$ has a rooted graph $(G,R)$, with an actual labeling s.t. $\mathcal{T}(G,R)\cong \mathcal{T}$.

Conversely, we can see that each actually labelled graph unfolds into another actually labelled tree by showing the following.
\begin{lemma}\label{ch2-lem0.6}
   Any rooted graph $(G,R)$, with a non-edge-collapsing equivalence relation $\sim$, s.t. $G/{\sim}$ has an actual labelling,  has an actual labelling as well.
\end{lemma}
\begin{proof}
    Note first that since we must have $t^{-1}([R]_{\sim})=\emptyset$, we also must have $t^{-1}(R)=\emptyset$. Now set for each $v\in VG$ $l(v):=l([v]_{\sim})$, $l_p(v):=l_p([v]_{\sim})$ and $M_{l(v)}=M_{l([v]_{\sim})}$. To show that this is indeed an actual labelling, we check all the conditions from \defref{ch2-def1}. Clearly $l_p(v)=l_p([v]_{\sim})\in M_{l([v]_{\sim})}=M_{l(v)}$, giving us the first point. 

    Since $\sim$ is a non-edge-collapsing equivalence relation, we have a bijection $\pi:o^{-1}(v)\to o^{-1}([v]_{\sim})$ sending $e\in o^{-1}(v)$ to $[e]_{\sim}$ and thus $t(\pi(e))=[t(e)]_{\sim}$, so $\pi$ induces a bijection $\pi:t_m(o^{-1}(v))\to t_m(o^{-1}([v]_{\sim}))$ that preserves the labels. Therefore, we have for any $v\neq R$
        \[l(t_m(o^{-1}(v)))=l(t_m(o^{-1}([v]_{\sim})))=M_{l([v]_{\sim})}\setminus\{l_p([v]_{\sim})\}=M_{l(v)}\setminus\{l_p(v)\}.\]
    The fourth point of the definition follows the same way since
        \[l(t_m(o^{-1}(R)))=l(t_m(o^{-1}([R]_{\sim})))=M_{l([R]_{\sim})}=M_{l(R)},\]

    Finally, for the third point, we will simply use that $\sim$ is a graph equivalence relation, and thus for every edge $e$ we have 
        \[l(o(e))=l([o(e)]_\sim)=l(o([e]_{\sim}))=l_p(t([e]_{\sim}))=l_p([t(e)]_{\sim})=l_p(t(e)),\]
    showing the third point.
\end{proof}

