\begin{cor}\label{ch2-cor2}
    For any $v$ s.t. $t(o^{-1}(v))\cap t(o^{-1}(R))\neq \emptyset$ we have
        \[l_m(t_m(o^{-1}(R)))=l_m(t_m(o^{-1}(v)))\cup\{l_p(v)\}.\]
\end{cor}
\begin{proof}
    By \coref{ch2-cor0}, we have a path $p\in\mathcal{T}(G, R)$ that ends in $v$ s.t.
        \[\mathcal{T}(G, R)^p\cong \mathcal{T}(G, R)^{\varepsilon_R}=\mathcal{T}(G, R)\]
    Now if we restrict this isomorphism to the neighbourhood of $p$ (in $\mathcal{T}(G, R)^p$) we get a bijection
        \[\pi:\{pe\mid e\in o^{-1}(v)\}\cup\{p_-\}\to \{e\mid e\in o^{-1}(R)\},\]
    where $p_{-}$ is the direct predecessor of $p$, s.t. for each $q$ in the domain of $\pi$ we have
        \[\mathcal{T}(G,R)^q\cong \mathcal{T}(G,R)^{\pi(q)},\]
    which means that $l(T(q))\cap l(T(\pi(q)))\neq \emptyset$. So by the previous lemma, we have
        \[l(t_m(o^{-1}(S)))=l(t_m(o^{-1}(v)))\cup\{l(p_{-})\}\]
    and by noting that $p_{-}$ ends with a predecessor of $p$ it gives us our result.
\end{proof}

Finally, by combining these results, we get that $l$ is an actual labelling, i.e.
\begin{theorem}\label{ch2-thm1}
    For any non-circular rooted graph $(G,R)$, without edges s.t.
    \begin{itemize}
        \item $t^{-1}(R)=\emptyset$
        \item $G\setminus \{R\}$ is strongly connected and non-redundant
    \end{itemize}
    then if $\mathcal{T}(G,R)$ is cocompact, there is an actual labelling on $G$.
\end{theorem}
\begin{proof}
    For each $v\in VG\setminus\{R\}$, we will define $l(v)$ to be the set of all isomorphism types of $\mathcal{T}(G, R)^p$ for $p$ that ends in $v$. For each $v\in VG\setminus\{R\}$ we define $l_p(v)$ to be the label $l(o(e))$ for any edge with $o(e)=v$, this is well-defined by \lemref{ch2-lem3}. Using \lemref{ch2-lem5}, we can define $M_{l(v)}:=M_v$. The first $3$ points of the definition of an actual label follow from these definitions, whereas the last point follows from \coref{ch2-cor2}.
\end{proof}

We will be able to remove most of the restrictions on the graph from the theorem. In the circular graph case, we can construct the actual labelling directly. 
