 To remove the strong connectivity condition, we will have to consider focal unfolding cycles separately. They are defined as follows.

 \begin{defn}
    For any $N\in \mathds{Z}_{\geq 1}$ and any $(k_i)^{N-1}_{i=0}\in (\mathds{Z}_{\geq 1})^N$ we define the focal unfolding cycle $\mathbf{FC}_{(k_i)^{N-1}_{i=0}}$ with:
    \begin{align*}
        V\mathbf{FC}_{(k_i)^{N-1}_{i=0}}:=  &\{v_0,\dots,v_{N-1}\}\cup\{w_0,\dots, w_{N-1}\}\cup \{R\},\\
        E\mathbf{FC}_{(k_i)^{N-1}_{i=0}}:=  &\{(v_i,v_{i+1\bmod N}, j)\mid 0\leq i< N,\ 1\leq j\leq k_i\}\cup\\
                                            &\{(w_i,v_{i+1\bmod N},j)\mid 0\leq i< N,\ 1\leq j\leq k_i-1 \}\cup\\
                                            &\{(w_i,w_{i-1\bmod N},k_i)\mid 0\leq i< N\}\cup\\
                                            &\{(R,v_1,i)\mid 1\leq i\leq k_1\}\cup\{(R,w_{N-1},1)\}\text{ and }\\
        \forall v,w\in V\mathbf{FC}&_{(k_i)^{N-1}_{i=0}},\forall j\in \mathds{Z}_{\geq 1}\ o((v,w,j)):=v,\ t((v,w,j)):=w,
    \end{align*}    
    where the last definition only applies if the edge is defined. We will also assume that $k_0>1$, to make sure that the degree of the root is greater than $2$.
 \end{defn}
