\begin{lemma}\label{ch2-lem6}
    For each rooted graph $(G,R)$ without sinks, s.t. 
    \begin{itemize}
        \item $t^{-1}(R)=\emptyset$
        \item $G\setminus \{R\}$ is non-redundant.
        \item $\mathcal{T}(G,R)$ is cocompact and not isomorphic to the unfolding tree of a focal unfolding cycle.
    \end{itemize}
    $G\setminus \{R\}$ is strongly connected.
