%         \item For $k\geq 1$, the graph $\mathbf{C}_k$ is defined with $V\mathbf{C}_k=\{R,v\}$, where there are $k$ edges from $v$ to $v$ and $k+1$ edges from $R$ to $v$.
%         \item For $k_1,k_2\geq 1$, the graph $\mathbf{C}_{k_1,k_2}$ is defined with $V\mathbf{C}_{k_1,k_2}=\{R,v_1,v_2\}$, where there are $k_1$ edges from $v_1$ to $v_2$, $k_2$ edges from $v_2$ to $v_1$ and $k_1+1$ edges from $R$ to $v_1$.
%     \end{itemize}
