\title{Comment on ``The SPOCK equation of state for condensed phases under arbitrary compression'' by R.~Myhill}\\[5ex]
\author{Thomas Ruedas\textsuperscript{1,2}\thanks{Corresponding author: \texttt{Thomas.Ruedas@mfn.berlin}}}
