	Let $\mathbb{F}:=\mathbb{Q}(t_1,\ldots,t_{2n})$ be the field of rational functions in $2n$ variables over $\mathbb{Q}$. A \emph{seed} (\emph{with coefficients}) is a pair $(\mathsf{x},Q)$ consisting of the following data:
	\begin{itemize}
		\item[$(1)$] $\mathsf{x}=(x_1,\ldots,x_n,y_1,\ldots,y_n)$ is a free generating set of $\mathbb{F}$ over $\mathbb{Q}$.
		\item[$(2)$] $Q$ is a quiver without loops or $2$-cycles, and assume that $Q_0=\{1,\ldots,2n\}$.
	\end{itemize}
	Then the tuple $(x_1,\ldots,x_n)$ is called the \emph{cluster}, each $x_i$ a \emph{cluster variable}, and $y_i$ a \emph{coefficient}. For a seed $(\mathsf{x},Q)$ and $k\in\{1,\ldots,n\}$, the \emph{mutation at $k$}
		\[
		 \mu_k(\mathsf{x},Q):=((x'_1,\ldots,x'_n,y_1,\ldots,y_n),\mu_k(Q))
		\]
		is defined by $x'_i = x_i$ for $i\neq k$, and
		\[
		x_k x'_k = \prod_{(j \rightarrow k)\in Q_1}x_jy_{j-n}+\prod_{(j \leftarrow k)\in Q_1}x_jy_{j-n},
		\]
		where $x_{n+1}=\cdots=x_{2n}=1=y_{1-n}=\cdots=y_0$. Note that $\mu_k$ is an involution, that is, $\mu_k(\mu_k(\mathsf{x},Q))=(\mathsf{x},Q)$. Moreover, it is easy to see that $\mu_k(\mathsf{x}, Q)$ is also a seed. 

	Let $Q$ be a quiver without loops or $2$-cycles, and assume that $Q_0=\{1,\ldots,n\}$. We obtain the quiver $\hat{Q}$ from $Q$ by adding vertices $\{1',\ldots,n'\}$ and arrow $i \rightarrow i'$ for each $1\le i\le n$. We fix a seed $(\mathsf{x}=(x_1,\ldots,x_n,y_1,\ldots,y_n),\hat{Q})$, called the \emph{initial seed}. The tuple $(x_1,\ldots,x_n)$ is called the \emph{initial cluster}, and each $x_i$ is called an \emph{initial cluster variable}.
	\begin{definition}
		The \emph{cluster algebra} $\mathcal{A}(Q)=\mathcal{A}(\mathsf{x},\hat{Q})$ with principal coefficients for the initial seed $(\mathsf{x},\hat{Q})$ is a $\mathbb{Z}$-subalgebra of $\mathbb{F}$ generated by all cluster variables and coefficients obtained from $(\mathsf{x},\hat{Q})$ by finite sequences of mutations.
	\end{definition}
	We denote by $\ClVar Q$ the set of all cluster variables in $\mathcal{A}(Q)$, and by $\Cluster(Q)$ the set of all clusters in $\mathcal{A}(Q)$. We say that $\mathcal{A}(Q)$ is of \emph{finite type} if $\ClVar(Q)$ is finite.
	\begin{theorem}[{\cite[Theorem 1.4]{FZ03}}]\label{7QdLexH7Sem2}
		Assume that $Q$ is connected. The cluster algebra $\mathcal{A}(Q)$ is of finite type if and only if $Q$ is of Dynkin type. 
	\end{theorem}
	One of the remarkable properties of cluster algebras with principal coefficients is the Laurent phenomenon as follows.
	\begin{theorem}[{\cite[Proposition 3.6]{FZ07}}]\label{LPm1saCASSoh}
		Every nonzero element $x$ of $\mathcal{A}(Q)$ is expressed by a Laurent polynomial of $x_1,\ldots,x_n$, $y_1,\ldots,y_n$
		\[
		x=\frac{F(x_1, \ldots,x_n,y_1,\ldots,y_n)}{x_1^{d_1} \cdots x_n^{d_n}},
		\]
		where $d_i\in\mathbb{Z}$ and $F(x_1, \ldots, x_n,y_1,\ldots,y_n)\in\mathbb{Z}[x_1,\ldots, x_n,y_1,\ldots,y_n]$ is not divisible by any $x_i$.
	\end{theorem}
	Theorem \ref{LPm1saCASSoh} implies that $\mathcal{A}(Q)$ is contained in $\mathbb{Z}[x_1^{\pm 1},\ldots,x_n^{\pm 1},y_1,\ldots,y_n]$. We define a $\mathbb{Z}^n$-grading on $\mathcal{A}(Q)$ as follows:
	\[
	\deg(x_i)=\mathbf{e}_i,\ \ \deg(y_j)=\sum_{i=1}^n(-b_{ij}\mathbf{e}_i),
	\]
	where $\mathbf{e}_1,\ldots,\mathbf{e}_n$ are the standard basis vectors in $\mathbb{Z}^n$. Every cluster variable $x$ of $\mathcal{A}(Q)$ is homogeneous with respect to the $\mathbb{Z}^n$-grading $\deg$ (\cite[Proposition 6.1]{FZ07}).
	\begin{definition}
		The \emph{$\g$-vector} of a cluster variable $x$ of $\mathcal{A}(Q)$ is defined by the $\mathbb{Z}^n$-grading $\deg(x)$.
	\end{definition}
	The cone spanned by the $\g$-vectors of cluster variables in a cluster $\mathbf{x}$ is denoted by $C(\mathbf{x})$, that is,
	\[
	C(\mathbf{x}):=\left\{\sum_{x\in\mathbf{x}}a_x\deg(x)\relmiddle| a_x\in\mathbb{R}_{\ge 0}\right\}.\]
	\begin{definition}\label{QeZ820slm1UEa}
		The set of all cones $C(\mathbf{x})$ for $\mathbf{x}\in\Cluster Q$, together with their faces, is called the \emph{$\g$-fan} of $\mathcal{A}(Q)$, denoted by $\mathcal{F}^{g}_{\cluster}(Q)$.
	\end{definition}
	Note that $\g$-fans are simplicial fans \cite[Theorem 0.8]{GHKK17}. There is the following transition rule, which was conjectured in \cite[Conjecture 7.12]{FZ07} and proved by \cite[Corollary 5.5]{GHKK17} and \cite[Proposition 4.2]{NZ12}: For $k\in Q_0$, $\mathcal{F}^{g}_{\cluster}(\mu_k(Q))$ is obtained from $\mathcal{F}^{g}_{\cluster}(Q)$ by the map $(g_i)_{i \in Q_0} \mapsto (g_i')_{i \in Q_0}$, where
	\begin{equation}\label{Yjd9vt0FtxUc}
		g_i' = \left\{\begin{array}{ll}
			-g_k & \mbox{if} \ \ i=k,\\
			g_i+[b_{ik}]_+g_k - b_{ik}\min(g_k,0) & \mbox{otherwise},
		\end{array} \right.
	\end{equation}
	where $[a]_+:=\max\{a,0\}$.
	This naturally provides the following result.
	\begin{proposition}
		Let $k\in Q_0$. If $\mathcal{F}^{g}_{\cluster}(Q)$ is complete (resp., dense), then so is $\mathcal{F}^{g}_{\cluster}(\mu_k(Q))$.
	\end{proposition}
	\begin{proof}
		The assertion immediately follows from \eqref{Yjd9vt0FtxUc} and the sign-coherence property of $\g$-vectors of each cluster.
	\end{proof}
	Due to this property, the completeness and denseness of $\mathcal{F}^{g}_{\cluster}(Q)$ can be examined through studying its mutation equivalence class. For instance, using Theorem \ref{7QdLexH7Sem2}, Reading proves the following theorem. By the methods of representation theory, we show that the converse also holds (see Corollary \ref{Cf4iTsp13aMpY68}).
	\begin{theorem}[{\cite[Theorem 10.6]{Re14}}]\label{7QdLexH7Sem3}
		If $Q$ is of Dynkin type, then $\mathcal{F}^{g}_{\cluster}(Q)$ is complete.
	\end{theorem}
	A similar result concerning the denseness of $\mathcal{F}^{g}_{\cluster}(Q)$ is known in the case where $Q$ is assumed to be acyclic.
	\begin{theorem}[{\cite[Theorem 1.1]{Yu23}}]\label{aEaKnR4m1UVj}
		Let $Q$ be a connected acyclic type quiver. Then $\mathcal{F}^{g}_{\cluster}(Q)$ is dense if and only if $Q$ is of either Dynkin or affine type.
	\end{theorem}
	In the general (possibly cyclic) case, a complete characterization of when $\mathcal{F}^{g}_{\cluster}(Q)$ is dense is not yet known. However, it is known that if $\mathcal{F}^{g}_{\cluster}(Q)$ is dense, then $Q$ must be of finite mutation type (see \cite[Theorem 2.27]{Yu23}).
