	\subsection{Cluster-tilting theory}\label{i3ZCfF2ro4v5}
	In this subsection, we recall several concepts from cluster-tilting theory. In particular, we review the notion of mutation for cluster-tilting objects and the notion of $\g$-vector in $2$-Calabi-Yau categories. These are used in Section \ref{uT45nbA3L9pM02} to introduce a map between Grothendieck groups of mutated Jacobian algebras.
	\begin{definition}
		A $K$-linear $\Hom$-finite triangulated category $\mathcal{C}$ is called \emph{$2$-Calabi-Yau} or just \emph{$2$-CY}, for short, if there is a bi-functorial isomorphism
		\[\Hom_{\mathcal{C}}(X,Y[1])\cong D\Hom_{\mathcal{C}}(Y,X[1])\]
		for any $X,Y\in\mathcal{C}$, where $D:=\Hom_{K}(-,K)$.
	\end{definition}
		Throughout this paper, we assume that $\mathcal{C}$ is a $2$-CY Krull-Schmidt category.
	\begin{definition}	
		An object $T\in\mathcal{C}$ is called \emph{rigid} if $\Hom_{\mathcal{C}}(T,T[1])=0$. Moreover, it is called \emph{cluster-tilting} if
		\[\add(T)=\{Y\in\mathcal{C}\mid\Hom_{\mathcal{C}}(T,Y[1])=0\}.\]
	\end{definition}
		Note that, by \cite{ZZ11} (see also \cite[Corollary 4.5]{AIR14}), a rigid object $T\in\mathcal{C}$ is cluster-tilting if and only if
		\[|T|=\max\left\{|T'|\relmiddle|\text{$T'$ is a rigid object in $\mathcal{C}$}\right\}.\]
	\begin{theorem}[{\cite{KR07}}]\label{UcfISbEawdcJ}
		Let $T$ be a cluster-tilting object in $\mathcal{C}$. Then the functor $\Hom_{\mathcal{C}}(T,-):\mathcal{C}\rightarrow\mod(\End_{\mathcal{C}}(T)^{\op})$ induces an equivalence
		\[
		\mathcal{C}/(T[1])\longrightarrow \mod(\End_{\mathcal{C}}(T)^{\op}).
		\]
		This also induces an equivalence of additive subcategories $\add(T)\cong\proj(\End_{\mathcal{C}}(T)^{\op})$.
	\end{theorem}
	\begin{theorem}[{\cite{IY08, BIRS11}}]\label{WWXhVkRSjGCF}
		Let $T$ be a basic cluster-tilting object in $\mathcal{C}$ with the Krull-Schmidt decomposition $T=T_1\oplus T_2\oplus\cdots\oplus T_n$.
		For each indecomposable direct summand $T_i$ of $T$, there exist an indecomposable rigid object $T^{\ast}_i$ and distinguished triangles
		\[\begin{array}{cc}
			\begin{tikzcd}[cramped]
				T_i & U' & T^{\ast}_i & {T_i[1],}
				\arrow["b'", from=1-1, to=1-2]
				\arrow["a'", from=1-2, to=1-3]
				\arrow[from=1-3, to=1-4]
			\end{tikzcd} &
			\begin{tikzcd}[cramped]
				{T^{\ast}_i} & U & {T_i} & {T^{\ast}_i[1],}
				\arrow["b", from=1-1, to=1-2]
				\arrow["a", from=1-2, to=1-3]
				\arrow[from=1-3, to=1-4]
			\end{tikzcd}
		\end{array}\]
		where $a$ and $a'$ (resp., $b$ and $b'$) are minimal right (resp., left) $\add(T/T_i)$-approximations, and $\Hom_{\mathcal{C}}(T_i, T_i^{\ast}[1])$ is one-dimensional. Then $\mu_{T_i}(T):=(T/T_i)\oplus T^{\ast}_i$ is a basic cluster-tilting object. Furthermore, any basic cluster-tilting object $T'$ with $T/T_i\in\add(T')$ is isomorphic to $T$ or $\mu_{T_i}(T)$.
	\end{theorem}
	The basic cluster-tilting object $\mu_{T_i}(T)$ in Theorem \ref{WWXhVkRSjGCF} is called the \emph{mutation} of $T$ with respect to $T_i$.

	Let $T$ be a basic cluster-tilting object in $\mathcal{C}$. Then based on \cite[Section 2.1]{KR07} (see also \cite{DK08,Pa08}), all objects in $\mathcal{C}$ are cones of morphisms in $\add(T)$.
	For an object $X\in\mathcal{C}$, consider a distinguished triangle
	\begin{equation}\label{MHFd8b7XFQkS}
		\begin{tikzcd}[cramped]
			{T^{-1}} & {T^{0}} & X & {T^{-1}[1]}
			\arrow["g", from=1-1, to=1-2]
			\arrow["f", from=1-2, to=1-3]
			\arrow["h", from=1-3, to=1-4]
		\end{tikzcd},
	\end{equation}
	where $T^{-1}, T^{0}\in\add(T)$. Since $T$ is rigid, it is easy to see that $f$ is a right $\add(T)$-approximation. This triangle is called the \emph{$\add(T)$-presentation} of $X$, and is referred to as \emph{minimal} when $f$ is right minimal. Assume that
	\[\begin{tikzcd}[cramped]
		{T'^{-1}} & {T'^{0}} & X & {T'^{-1}[1]}
		\arrow["g'", from=1-1, to=1-2]
		\arrow["f'", from=1-2, to=1-3]
		\arrow["h'", from=1-3, to=1-4]
	\end{tikzcd}\]
	is another $\add(T)$-presentation. Using \cite[Proposition 1.1.11]{BBD82}, one can show that
	\[[T^{0}]-[T^{-1}]=[T'^{0}]-[T'^{-1}]\in K_0(\add(T)).\]
	The \emph{index} of $X$ with respect to $T$ is defined by $\ind_{T}X:=[T^{0}]-[T^{-1}]$.

	Now, assume that $T=T_1\oplus T_2\oplus\cdots\oplus T_n$ is a Krull-Schmidt decomposition. Then there exist unique integers $g_i$, $1\le i\le n$, such that $\ind_{T}X=\sum_{i=1}^{n}g_i[T_i]$. The integer vector $g^{X}_{T}:=(g_1,\cdots,g_n)$ is called the \emph{$\g$-vector} of $X$ with respect to $T$.

	\subsection{Silting theory}\label{yEThQDuEWkJB}
	The notion of mutation for silting complexes is reviewed. Furthermore, we discuss the connection between cluster-tilting theory and silting theory. In Section \ref{sec:clcat}, this helps us to see the role of Jacobian algebras as a link between the representation theory of algebras and the theory of cluster algebras.
	\begin{definition}
		We say that $X\in K^b(\proj\Lambda)$ is
		\begin{itemize}
			\item \emph{presilting} if $\Hom_{K^b(\proj\Lambda)}(X,X[m])=0$ for all $m>0$;
			\item \emph{silting} if it is presilting and the smallest thick subcategory containing $X$ is $K^b(\proj\Lambda)$;
			\item \emph{$2$-term} if $X^i=0$ for all $i\neq -1,0$.
		\end{itemize}
	\end{definition}
	Note that a $2$-term presilting complex $X\in K^b(\proj\Lambda)$ is silting if and only if $|X|=|\Lambda|$ \cite[Proposition 2.16]{Ai13}.

	Recall that the Krull-Schmidt decomposition $\Lambda = P_{(1)}\oplus P_{(2)}\oplus\cdots\oplus P_{(n)}$ yields a basis $\{[P_{(1)}], \ldots, [P_{(n)}]\}$ for $K_0(\proj\Lambda)$, establishing $K_0(\proj\Lambda) \cong \mathbb{Z}^n$. The \emph{$\g$-vector} of $X\in K^b(\proj\Lambda)$ is an integer vector $g^X:=[X]\in K_0(\proj\Lambda)\cong\mathbb{Z}^n$.

	We denote by $\twopresilt(\Lambda)$ (resp., $\twosilt(\Lambda)$) the set of isomorphism classes of basic $2$-term presilting (resp., $2$-term silting) complexes in $K^b(\proj\Lambda)$.
	\begin{definition}[{\cite{DIJ19}}]
		The algebra $\Lambda$ is called \emph{$\tau$-tilting finite} if $\twosilt(\Lambda)$ is finite.
	\end{definition}
	\begin{remark}\label{LJwIJTvJ2fcB}
		If $\Lambda$ is representation-finite, then it is $\tau$-tilting finite.
	\end{remark}
	\begin{namedthm}{Definition-Theorem}[{\cite[Theorem 2.31]{AiIy12}}]
		Let $S$ be a $2$-term silting complex and $S=S_1\oplus S_2\oplus\cdots\oplus S_n$ its Krull-Schmidt decomposition.
		\begin{itemize}
			\item[$(1)$] Consider a distinguished triangle
			\[\begin{tikzcd}[cramped]
				{S^{\ast}_i} & U & {S_i} & {S_{i}^{\ast}[1],}
				\arrow[from=1-1, to=1-2]
				\arrow["a", from=1-2, to=1-3]
				\arrow[from=1-3, to=1-4]
			\end{tikzcd}\]
			where $a$ is the minimal right $\add(S/S_i)$-approximation. Then the \emph{right mutation} of $S$ with respect to $S_i$ is the $2$-term silting complex $\mu^{+}_{S_i}(S):=(S/S_i)\oplus S_i^{\ast}$.
			\item[$(2)$] Consider a distinguished triangle
			\[\begin{tikzcd}[cramped]
				{S_i} & U' & {S^{\star}_i} & {S_{i}[1],}
				\arrow["b'", from=1-1, to=1-2]
				\arrow[from=1-2, to=1-3]
				\arrow[from=1-3, to=1-4]
			\end{tikzcd}\]
			where $b'$ is the minimal left $\add(S/S_i)$-approximation. Then the \emph{left mutation} of $S$ with respect to $S_i$ is the $2$-term silting complex $\mu^{-}_{S_i}(S):=(S/S_i)\oplus S_i^{\star}$.
		\end{itemize}
		Moreover, $\mu^{+}_{S_i^{\star}}(\mu_{S_i}^{-}(S))\cong S$ and $\mu^{-}_{S_i^{\ast}}(\mu^{+}_{S_i}(S))\cong S$.
	\end{namedthm}
	\begin{lemma}[{\cite[Corollary 3.8]{AIR14}}]
		Let $X\in\twopresilt(\Lambda)$ with $|X|=|\Lambda|-1$. Then $X$ is a direct summand of exactly two $2$-term silting complexes, which are left or right mutations of each other (and other possible completions of $X$ are not $2$-term).
	\end{lemma}
	We denote by $K^{\{-1,0\}}(\proj\Lambda)$ the full subcategory of $K^b(\proj\Lambda)$ consisting of $2$-term complexes.
	\begin{theorem}[{\cite[Section 4.2]{AIR14}}]\label{nyKSQbIejd2O}
		Let $\mathcal{C}$ be a $2$-CY Krull-Schmidt category with a cluster-tilting object $T$. Let $T=T_1\oplus T_2\oplus\cdots\oplus T_n$ be a Krull-Schmidt decomposition. 
		For any $X\in\mathcal{C}$, we can consider the minimal $\add(T)$-presentation of $X$
		\[\begin{tikzcd}[cramped]
			{T^{-1}} & {T^0} & X & {T^{-1}[1]}
			\arrow["a",from=1-1, to=1-2]
			\arrow[from=1-2, to=1-3]
			\arrow[from=1-3, to=1-4]
		\end{tikzcd}.\]
		Let $\Lambda=\End_{\mathcal{C}}(T)^{\op}$.
		Then the functor
		$\Hom_{\mathcal{C}}(T,-):\mathcal{C}\rightarrow\mod\Lambda$
		induces a bijection
		\[
		\begin{array}{r c l}
			\tilde{H}_{T}:\iso\mathcal{C} &\longrightarrow &  \iso K^{\{-1,0\}}(\proj\Lambda),\\
			X & \longmapsto & \Hom_{\mathcal{C}}(T, a)
		\end{array}
		\]
		which sends $T$ to $\Lambda$ and commutes with mutations. Thus it preserves $\g$-vectors.
		Moreover, it maintains the number of non-isomorphic indecomposable direct summands and thus, induces the following bijections:
		\[\begin{array}{lcr}
			\rigid(\mathcal{C})\longleftrightarrow\twopresilt(\Lambda), &&
			\ctilt(\mathcal{C})\longleftrightarrow\twosilt(\Lambda).
		\end{array}\]
	\end{theorem}
	\subsection{$\mathbf{\g}$-finiteness and $\mathbf{\g}$-tameness}
	Since $\g$-fans reflect many features of algebras, numerous papers have been devoted to studying $\g$-fans (see e.g.\ \cite{AHIKM22,AHIKM23,As21,DIJ19,HY25a}). Following this approach, the notions of $\g$-finiteness and $\g$-tameness were examined in \cite{AsIy24,AY23}. In this subsection, we prepare some preliminaries for the proofs of our results in Section \ref{4p5IXJsU8vuj}.

	For $X\in\twopresilt(\Lambda)$, the cone spanned by the $\g$-vectors of indecomposable direct summands of $X$ is denoted by $C(X)$, that is,
	\[C(X):=\left\{\sum_{X'\in\ind X}a_{X'}g^{X'}\relmiddle| a_{X'}\in\mathbb{R}_{\ge 0}\right\}.\]
	\begin{definition}[{\cite{DIJ19, DeFe15}}]
		The set of all cones $C(X)$ for $X\in\twopresilt(\Lambda)$ forms a simplicial fan which is called the \emph{$\g$-fan} of $\Lambda$, denoted by $\mathcal{F}^{g}_{\twosilt}(\Lambda)$.
	\end{definition}
	\begin{definition}\label{1s65JGnzx70lk}
		The algebra $\Lambda$ is called \emph{$\g$-finite} (resp., \emph{$\g$-tame}) if $\mathcal{F}^{g}_{\twosilt}(\Lambda)$ is complete (resp., dense).
	\end{definition}
	\begin{remark}
		Two maximal cones of the $\g$-vector fan $\mathcal{F}^{g}_{\twosilt}(\Lambda)$ do not have any $n$-dimensional face in common, and they share an $(n-1)$-dimensional face if and only if they are mutations of each other.
	\end{remark}
	\begin{theorem}[{\cite{As21}}]\label{Ypp40yreQWb2}
		The algebra $\Lambda$ is $\tau$-tilting finite if and only if it is $\g$-finite.
	\end{theorem}
	\begin{theorem}[{\cite{PYK23}}]\label{tGCGN5Yoe6G9}
		If $\Lambda$ is representation-tame, then it is $\g$-tame.
	\end{theorem}
	\section{Quivers with potentials}\label{Bm04xjtUpW3v}
	We begin by recalling the definitions of quivers with potentials and their associated Jacobian algebras, following \cite{DWZ08}. Next, we review classifications of the representation types —namely, representation-tameness and $\g$-tameness— of finite-dimensional Jacobian algebras \cite{GLFS16, PYK23}. These results play a direct role in the proofs presented in Section \ref{4p5IXJsU8vuj}. In Section \ref{sec:clcat}, we study the relationship between silting theory and cluster algebras through Jacobian algebras. This perspective is also applied in Appendix \ref{app:ms} to classify $E$-finite Jacobian algebras of surface type. Finally, we study mutations of Jacobian algebras and introduce a map between the Grothendieck groups of a Jacobian algebra and its mutation at an arbitrary vertex.

	Let $Q$ be a quiver. For an integer $m\ge 0$, we denote by $Q_{m}$ the set of all paths of length $m$. Consider the vector space $KQ_m$ freely generated by $Q_m$. Then the \emph{complete path algebra} associated with $Q$ is defined by
	\[K\doublelrangle{Q}:=\prod_{m=0}^{\infty}KQ_m,\]
	where multiplication is induced by the concatenation of paths. Let $\mathfrak{m}$ be the ideal of $K\doublelrangle{Q}$ generated by all arrows. For an ideal $I\subset K\doublelrangle{Q}$, the \emph{$\mathfrak{m}$-adic closure} of $I$ is denoted by
	\[\overline{I}:=\bigcap_{l=0}^{\infty}I+\mathfrak{m}^{l}.\]
	\begin{definition}[{\cite{DWZ08}}]
		Let $Q$ be a quiver without loops. A \emph{potential} on $Q$ is a (possibly infinite) linear combination of oriented cycles in $Q$ modulo the closure of the commutator $[K\doublelrangle{Q},K\doublelrangle{Q}]$. Indeed, a potential is an element of 
		\[\Pot(Q):=K\doublelrangle{Q}/\overline{[K\doublelrangle{Q},K\doublelrangle{Q}]}.\]
		The pair $(Q, W)$ is called a \emph{quiver with potential} or just a \emph{QP}, for short. For an arrow $\alpha$ of $Q$, we define a \emph{cyclic derivative} $\partial_{\alpha}:\Pot(Q)\rightarrow  K\doublelrangle{Q}$ as the unique continuous linear map that sends any cycle $c$ to $\sum\limits_{c=u\alpha v}vu$.
		For the ideal $J(W):=\langle \partial_{\alpha}W\mid\alpha\in Q_1\rangle$ of $K\doublelrangle{Q}$, the \emph{Jacobian algebra} associated with the QP $(Q, W)$ is defined by
		\[\mathcal{J}(Q,W):=K\doublelrangle{Q}/\overline{J(W)}.\]
		If the Jacobian algebra is finite-dimensional, then $(Q, W)$ is called a \emph{Jacobi-finite} QP.
	\end{definition}
	Let $(Q', W')$ and $(Q'', W'')$ be two QPs with $Q'_0=Q''_0$. Their \emph{direct sum} is a QP $(Q,W)$ defined by $Q_0=Q'_0=Q''_0$, $Q_1=Q'_1\sqcup Q''_1$, and $W=W'+W''$.
	\begin{definition}[{\cite{DWZ08}}]
		Let $(Q, W)$ and $(Q', W')$ be two QPs with $Q_0=Q'_0$. Then we say that they are \emph{right equivalent} if there is an algebra isomorphism $\varphi:K\doublelrangle{Q}\rightarrow K\doublelrangle{Q'}$ whose restriction on vertices is the identity map and $\varphi(W)=W'$.
	\end{definition}
	We recall two special classes of QPs introduced in \cite{DWZ08}: A QP $(Q,W)$ is called \emph{trivial} if $W$ is a linear combination of $2$-cycles and $\mathcal{J}(Q,W)$ is isomorphic to $KQ_{0}$. It is called \emph{reduced} if $W$ has no terms that are cycles of length at most $2$.
	\begin{theorem}[{\cite[Theorem 4.6]{DWZ08}}]
		Let $(Q, W)$ be a QP.
		Up to right equivalence, uniquely, we can write it as a direct sum of a trivial QP $(Q_{\text{tri}}, W_{\text{tri}})$ and a reduced QP $(Q_{\text{red}}, W_{\text{red}})$, called the \emph{reduced part} of $(Q, W)$. Moreover, $\mathcal{J}(Q,W)\cong\mathcal{J}(Q_{\text{red}},W_{\text{red}})$.
	\end{theorem}
	\begin{definition}[{\cite{DWZ08}}]\label{def:mutation}
		Let $(Q, W)$ be a QP. Assume that $k\in Q_0$ lies on no $2$-cycles. Moreover, we may assume that no oriented cycle appearing in the expansion of $W$ starts or ends at $k$. The \emph{QP-premutation} of $(Q,W)$ at $k$ is the QP $\tilde{\mu}_k(Q,W):=(\tilde{Q},\tilde{W})$ obtained from $(Q,W)$ by the following steps (cf. Section \ref{sec:cluster}):
		\begin{itemize}
			\item[$(1)$] For each
			$(b,a)\in Q_{2,k}:=
			\{(b,a)\in Q_1\times Q_1\mid\begin{tikzcd}[cramped]
				i & k & j
				\arrow["b", from=1-2, to=1-1,swap]
				\arrow["a", from=1-3, to=1-2,swap]
			\end{tikzcd}\}$,
			add an arrow 
			$\begin{tikzcd}[cramped]
				i & j
				\arrow["{[ba]}", from=1-2, to=1-1,swap]
			\end{tikzcd}$.
			\item[$(2)$] Replace each arrow
			$\begin{tikzcd}[cramped]
				k & i
				\arrow["{a}", from=1-2, to=1-1,swap]
			\end{tikzcd}$
			with
			$\begin{tikzcd}[cramped]
				k & i
				\arrow["{a^{\ast}}", from=1-1, to=1-2]
			\end{tikzcd}$, and each arrow
			$\begin{tikzcd}[cramped]
				i & k
				\arrow["{a}", from=1-2, to=1-1,swap]
			\end{tikzcd}$
			with
			$\begin{tikzcd}[cramped]
				i & k
				\arrow["{a^{\ast}}", from=1-1, to=1-2]
			\end{tikzcd}$.
			\item[$(3)$] Define $\tilde{W}$ by \[\tilde{W}:=[W]+\sum_{(b,a)\in Q_{2,k}} [ba]a^{\ast}b^{\ast}.\] Here, $[W]$ is obtained from $W$ by replacing each occurrence of $ba$, where $(b,a)\in Q_{2,k}$, with the arrow $[ba]$.
		\end{itemize}
		Up to right equivalence, the reduced part of $\tilde{\mu}_k(Q, W)$ is called the \emph{QP-mutation} of $(Q, W)$ at $k$, denote by $\mu_k(Q, W)$.
		\begin{theorem}[{\cite[Corollary 6.6]{DWZ08}}]\label{thm:Jfin}
			Let $(Q, W)$ be a Jacobi-finite QP. Assume that $k\in Q_0$ lies on no $2$-cycles. Moreover, we may assume that no oriented cycle appearing in the expansion of $W$ starts or ends at $k$. Then $\mu_k(Q,W)$ is also Jacobi-finite.
		\end{theorem}
		We say that $W$ or $(Q, W)$ is \emph{non-degenerate} if every quiver obtained from $(Q, W)$ by a finite sequence of mutations has no $2$-cycles. In which case, the quiver of $\mu_k(Q,W)$ is equal to $\mu_k(Q)$ for $k\in Q_0$.
	\end{definition}
	\begin{theorem}[{\cite[Corollary 7.4]{DWZ08}}]\label{qQ9PzgKXEX4s}
		Let $Q$ be a quiver without loops or $2$-cycles. If $K$ is uncountable, then $Q$ admits a non-degenerate potential.
	\end{theorem}

	\begin{proposition}\label{prop:fin mut}
		Let $Q$ be a quiver without loops or $2$-cycles. Assume that $Q$ is of finite mutation type. Then there exists a potential $W$ such that $(Q,W)$ is non-degenerate and Jacobi-finite.
	\end{proposition}
	\begin{proof}
		We may assume that $Q$ is connected, since the existence of a non-degenerate Jacobi-finite potential can be checked componentwise.

		If $Q$ is defined from a triangulated surface, the assertion follows from \cite{LF09,Lad12,LF15} (see Remark \ref{rem:Jacobi-fin}).

		If $Q$ is of exceptional finite mutation type, we divide the proof into cases: If $Q$ is of acyclic type, then the assertion follows from Theorems \ref{thm:Jfin} and \ref{qQ9PzgKXEX4s}. If $Q$ is mutation equivalent to $E_i^{(1,1)}$ for $i=6,7,8$, to $X_6$, or to $X_7$, then the assertion follows from \cite{GGS14}, \cite[Section 9.4]{GLFS16}, and \cite[Theorem B]{La25}, respectively.
	\end{proof}

	For later use, we recall the notion of the restriction of a QP to a subset of vertices. Let $(Q,W)$ be a QP, and $I$ be a subset of $Q_{0}$. Then the \emph{restriction} of $(Q,W)$ to $I$ is denoted by $(Q|_I,W|_I)$ and defined as follows:
	\begin{itemize}
		\item $Q|_I$ is the full subquiver of $Q$ with $(Q|_I)_0=I$.
		\item $W|_I$ is obtained from $W$ by deleting summands of $W$ that are not cycles in $Q|_I$.
	\end{itemize}
	It induces naturally a surjective algebra homomorphism $\mathcal{J}(Q,W)\rightarrow\mathcal{J}(Q|_I,W|_I)$. If $(Q,W)$ is non-degenerate, then so is $(Q|_I,W|_I)$ \cite[Proposition 2.3]{GLFS16}.

