	\subsection{Finite-dimensional Jacobian algebras}
	In this paper, we focus on finite-dimensional Jacobian algebras associated with non-degenerate QPs. From now on, all quivers are assumed to have no loops or $2$-cycles, and by a QP $(Q,W)$, we mean a non-degenerate Jacobi-finite QP.
	\subsubsection{Representation types}
	The classification of representation-finite (resp., representation-tame) Jacobian algebras plays a crucial role in the classification of $\g$-finite (resp., $\g$-tame) Jacobian algebras, and subsequently, in our study for the classification $E$-finite (resp., $E$-tame) Jacobian algebras.
	\begin{theorem}[{\cite[Theorem 7.1]{GLFS16}}]\label{on26Fdo7dIPi}
		The Jacobian algebra $\mathcal{J}(Q,W)$ is representation-finite (resp., representation-tame) if and only if so is $\mathcal{J}(\mu_k(Q,W))$ for $k\in Q_0$.
	\end{theorem}
	\begin{corollary}\label{cor:rep type}
		Let $Q$ be a connected acyclic type quiver. Then $\mathcal{J}(Q,W)$ is
		\begin{itemize}
			\item representation-finite if and only if $Q$ is of Dynkin type;
			\item representation-tame if and only if $Q$ is of either Dynkin or affine type.
		\end{itemize}
	\end{corollary}
	\begin{proof}
		It follows from the classifications of representation finite and tame algebras in Section \ref{sec:finite rep} and Theorem \ref{on26Fdo7dIPi}.
	\end{proof}
	\begin{theorem}[{\cite{GLFS16}}]\label{SF76ppyobv7F}
		Assume that $Q$ is not mutation equivalent to any of the following quivers: $K_m$ for $m\ge 3$, $X_6$, $X_7$, and $T_2$. Then $\mathcal{J}(Q,W)$ is representation-tame if and only if $Q$ is of finite mutation type. Otherwise, the representation type of the Jacobian algebra $J(Q,W)$ is identified by the following assertions.
		\begin{itemize}
			\item[$(1)$] For $m\ge 3$, $\mathcal{J}(K_m,0)$ is representation-wild.
