	\subsubsection{Cluster categories}\label{sec:clcat}
	We recall the definition of Ginzburg dg algebras (see \cite[Section 3.3]{Am09} and \cite{Gi06}). Let $(Q, W)$ be a QP. We denote by $\hat{Q}$ the quiver such that $\hat{Q}_0=Q_0$, and each of its arrows is one of the following:
	\begin{itemize}
		\item[$(0)$] an arrow of $Q$,
		\item[$(-1)$] an arrow $\begin{tikzcd}[cramped]
			i & j
			\arrow["{a^\ast}", from=1-1, to=1-2]
		\end{tikzcd}$,
		for each arrow
		$\begin{tikzcd}[cramped]
			i & j
			\arrow["{a}", from=1-2, to=1-1,swap]
		\end{tikzcd}$
		of $Q$,
		\item[$(-2)$] a loop
		$\begin{tikzcd}[cramped]
			i & i
			\arrow["{l_i}", from=1-2, to=1-1,swap]
		\end{tikzcd}$,
		for each vertex $i$ of $Q$.
	\end{itemize}
	Define the degree of arrows in the case $(m)$ to be $m$. Then this grading induces a grading on the complete path algebra $K\doublelrangle{\hat{Q}}$. Moreover, there is a unique differential\footnote{By a differential, we mean a morphism of graded $K$-spaces of degree $1$ with $d^2=0$ \cite{Ke07}.} $d:K\doublelrangle{\hat{Q}}\rightarrow K\doublelrangle{\hat{Q}}$ satisfying the following conditions:
	\begin{itemize}
		\item (Leibniz rule) For all $v,u\in K\doublelrangle{\hat{Q}}$, where $u$ is homogeneous of degree $p$,
		\[d(uv)=d(u)v+(-1)^{p}ud(v).\]
		\item For all $a\in Q_1$, $d(a)=0$ and $d(a^{\ast})=\partial_{a}W$.
		\item For all $i\in Q_0$, \[d(l_i)=e_i\left(\sum_{a\in Q_1}aa^{\ast}-a^{\ast}a\right)e_i.\]
	\end{itemize}
	The \emph{complete Ginzburg dg algebra} $\hat{\Gamma}_{(Q,W)}$ is the graded algebra $K\doublelrangle{\hat{Q}}$ endowed with the differential $d$.
	\begin{proposition}[{\cite[Lemma 2.8]{KY11}}]
		The $0$-th cohomology of complete Ginzburg dg algebra $\hat{\Gamma}_{(Q,W)}$ is the Jacobian algebra $\mathcal{J}(Q,W)$, that is,
		\[H^{0}\hat{\Gamma}_{(Q,W)}=\mathcal{J}(Q,W).\]
		Moreover, all terms of $\hat{\Gamma}_{(Q,W)}$ in positive degrees vanish.
	\end{proposition}
	Consider the derived category $\mathcal{D}(\hat{\Gamma}_{(Q,W)})$ of the complete Ginzburg dg algebra $\hat{\Gamma}_{(Q,W)}$ (see \cite{Ke94} for details). We denote by $\mathcal{D}_{\text{f.d}}(\hat{\Gamma}_{(Q,W)})$ the full subcategory of $\mathcal{D}(\hat{\Gamma}_{(Q,W)})$ consists of all dg modules with finite-dimensional total cohomology. Then by \cite[Theorem 2.17]{KY11}, $\mathcal{D}_{\text{f.d}}(\hat{\Gamma}_{(Q,W)})$ is a triangulated subcategory of $\per(\hat{\Gamma}_{(Q,W)})$, which is the smallest thick subcategory of $\mathcal{D}(\hat{\Gamma}_{(Q,W)})$ containing $\hat{\Gamma}_{(Q,W)}$.

	Following \cite{Am09}, we define the \emph{cluster category} $\mathcal{C}_{(Q, W)}$ to be the triangulated quotient
	\[\per(\hat{\Gamma}_{(Q,W)})/ \mathcal{D}_{\text{f.d}}(\hat{\Gamma}_{(Q,W)}).\]
	By \cite[Theorem 3.5]{Am09} or \cite[Section 2.1]{KR07},
	\begin{itemize}
		\item $\mathcal{C}_{(Q,W)}$ is Krull-Schmidt and $2$-CY,
		\item the image of $\hat{\Gamma}_{(Q,W)}$ in $\mathcal{C}_{(Q,W)}$ is a cluster-tilting object, and
		\item $\End_{\mathcal{C}_{(Q,W)}}(\hat{\Gamma}_{(Q,W)})^{\op}\cong \mathcal{J}(Q,W)$.
	\end{itemize}
	For $X \in \mathcal{C}_{(Q,W)}$, we refer to its $\g$-vector $g_{\hat{\Gamma}_{(Q,W)}}^X$ with respect to $\hat{\Gamma}_{(Q,W)}$ simply as the $\g$-vector of $X$, and denote it by $g^X$.
	We define
	\begin{itemize}
		\item $\ctilt^{+}\mathcal{C}_{(Q,W)}$ (resp., $\ctilt^{-}\mathcal{C}_{(Q,W)}$) to be the subset of $\ctilt\mathcal{C}_{(Q,W)}$ consisting of all objects obtained from $\hat{\Gamma}_{(Q,W)}$ (resp., $\hat{\Gamma}_{(Q,W)}[1]$) by all finite sequences of mutations;
		\item $\rigid^{+}\mathcal{C}_{(Q,W)}$ (resp., $\rigid^{-}\mathcal{C}_{(Q,W)}$) to be the set of direct summands of objects in $\ctilt^{+}\mathcal{C}_{(Q,W)}$ (resp., $\ctilt^{-}\mathcal{C}_{(Q,W)}$).
	\end{itemize}
	\begin{theorem}[{\cite[Corollary 3.5]{CIKLFP13}}]\label{VTIFVbl5KQBe}
		There is a bijection
		\begin{equation}\label{PjIjz0gGmdIk}
			\ind\bigl(\rigid^{+}(\mathcal{C}_{(Q,W)})\bigr)\longleftrightarrow\ClVar(Q)
		\end{equation}
		preserving $\g$-vectors. Moreover, it induces a bijection
		\[
		\ctilt^{+}\mathcal{C}_{(Q,W)}\longleftrightarrow\Cluster(Q),
		\]
		which sends $\hat{\Gamma}_{(Q,W)}$ to the initial cluster of $\mathcal{A}(Q)$ and commutes with mutations.
	\end{theorem}

	For a finite-dimensional algebra $\Lambda$, we similarly define
	\begin{itemize}
		\item $\twosilt^{+}\Lambda$ (resp., $\twosilt^{-}\Lambda$) to be a subset of $\twosilt^{+}\Lambda$ consisting of all complexes obtained from $\Lambda\in K^{b}(\proj\Lambda)$ (resp., $\Lambda[1]$) by all finite sequences of mutations;
		\item $\twopresilt^{+}\Lambda$ (resp., $\twopresilt^{-}\Lambda$) to be the set of direct summands of complexes in $\twosilt^{+}\Lambda$ (resp., $\twosilt^{-}\Lambda$).
	\end{itemize}
	By Theorem \ref{nyKSQbIejd2O}, one can obtain the bijection
	\[
	\ind\bigl(\rigid(\mathcal{C}_{(Q,W)})\bigr)\longleftrightarrow\ind\bigl(\twopresilt(\mathcal{J}(Q,W))\bigr),
	\]
	which preserves $\g$-vectors. Moreover, it induces the bijection
	\[
	\ctilt\mathcal{C}_{(Q,W)}\longleftrightarrow\twosilt(\mathcal{J}(Q,W)),
	\]
	which sends $\hat{\Gamma}_{(Q,W)}$ to $\mathcal{J}(Q,W)$ and commutes with mutations. 
	Thus the map \eqref{PjIjz0gGmdIk} induces the bijection
	\[
	\ind\bigl(\twopresilt^{+}(\mathcal{J}(Q,W))\bigr)\longleftrightarrow\ClVar(Q),
	\]
	which preserves $\g$-vectors. Furthermore, it induces the bijection
	\[
	\twosilt^{+}(\mathcal{J}(Q,W))\longleftrightarrow\Cluster(Q),
	\]
	which sends $\mathcal{J}(Q,W)$ to the initial cluster of $\mathcal{A}(Q)$ and commutes with mutations.
	\begin{remark}\label{teSU4F2m6VPA}
		The $g$-fan $\mathcal{F}^{g}_{\cluster}(Q)$ coincides with the subfan of $\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q,W))$ consisting of $\g$-vectors of complexes in $\ind\bigl(\twopresilt^{+}(\mathcal{J}(Q,W))\bigr)$.
	\end{remark}
		Similarly to the above observation, the following result is a consequence of Theorem \ref{nyKSQbIejd2O} and \cite[Corollary 4.4]{Yu20}, and it will be used in Appendix \ref{app:ms}.
	\begin{theorem}[{\cite[Section 4.2]{Yu20}}]\label{Lr78jTdZdIN3}
		There is a bijection
		\[
		\ind\bigl(\twopresilt^{-}(\mathcal{J}(Q,W))\bigr)\longleftrightarrow\ClVar(Q^{\op})
		\]
		reversing $\g$-vectors. Moreover, it induces a bijection
		\[
		\twosilt^{-}(\mathcal{J}(Q,W))\longleftrightarrow\Cluster(Q^{\op}),
		\]
		which sends $\mathcal{J}(Q,W)[1]$ to the initial cluster of $\mathcal{A}(Q^{\op})$ and commutes with mutations.
	\end{theorem}
	\subsubsection{Mutations of Jacobian algebras}\label{uT45nbA3L9pM02}
	Let $k\in Q_0$. By Theorem \ref{thm:Jfin}, $\mu_k(Q, W)$ is Jacobi-finite and $\mathcal{C}_{\mu_k(Q,W)}$ satisfies the properties in Section \ref{sec:clcat}. In particular,
	\[\End_{\mathcal{C}_{\mu_k(Q,W)}}(\hat{\Gamma}_{\mu_k(Q,W)})^{\text{op}}\cong \mathcal{J}(\mu_k(Q,W)).\]
	Based on \cite[Theorem 3.2]{KY11}, one can see that there is a triangulated equivalence
	\begin{equation}\label{eq:F_k}
		F_k: \mathcal{C}_{(Q,W)}\longrightarrow \mathcal{C}_{\mu_k(Q,W)}
	\end{equation}
	that sends $\hat{\Gamma}_{(Q,W)}$ to $\hat{\Gamma}_{\mu_k(Q,W)}$.

	Let
	$\hat{\Gamma}_{(Q,W)}=\hat{\Gamma}_{(Q,W),1}\oplus\hat{\Gamma}_{(Q,W),2}\oplus\cdots\hat{\Gamma}_{(Q,W),n}$
	be a Krull-Schmidt decomposition with the property that for all $1\le i\le n$, $\hat{\Gamma}_{(Q,W),i}$ corresponds to the $i$-th vertex of $Q$, that is, $\Hom_{\mathcal{C}_{(Q,W)}}(\hat{\Gamma}_{(Q,W)},\hat{\Gamma}_{(Q,W),i})$ is the indecomposable projective $\mathcal{J}(Q,W)$-module corresponding to the $i$-th vertex of $Q$. Denote $\mu_k(\hat{\Gamma}_{(Q,W)}):= \mu_{\hat{\Gamma}_{(Q,W),k}}(\hat{\Gamma}_{(Q,W)})$.
	Then by Theorem \ref{nyKSQbIejd2O}, we obtain the following commutative diagram:
	\begin{equation}\label{zvHv2HLFf7K4}
		\begin{tikzcd}[cramped]
			{\iso\mathcal{C}_{(Q,W)}} && {\iso\mathcal{C}_{\mu_k(Q,W)}} \\
			\\
			{\iso\bigl(K^{\{-1,0\}}(\proj\mathcal{J}(Q,W))\bigr)} && {\iso\bigl(K^{\{-1,0\}}(\proj\mathcal{J}(\mu_k(Q,W)))\bigr)}
			\arrow["{F_k}", from=1-1, to=1-3]
			\arrow[dotted, "\tilde{H}_{\mu_k(\hat{\Gamma}_{(Q,W)})}"{description}, from=1-1, to=3-3]
			\arrow["{\tilde{H}_{\hat{\Gamma}_{(Q,W)}}}"', from=1-1, to=3-1]
			\arrow["{\tilde{H}_{\hat{\Gamma}_{\mu_k(Q,W)}}}", from=1-3, to=3-3]
			\arrow["{F_k}", from=3-1, to=3-3]
		\end{tikzcd}
	\end{equation}
	Here, both maps labeled $F_k$ are induced from the triangulated equivalence \eqref{eq:F_k}. In particular, the bottom map $F_k$ in Diagram \eqref{zvHv2HLFf7K4} sends presilting complexes to presilting complexes and also preserves the number of indecomposable direct summands. Therefore, it sends silting complexes to silting complexes.

	Diagram \eqref{zvHv2HLFf7K4} induces the following commutative diagram of bijections:
	\begin{equation}\label{6FUzaTwbFh77}
