	\section{$E$-invariant}
	In this section, following \cite{DeFe15}, we recall the notion of $E$-invariant. We then review generic decompositions of $\g$-vectors and discuss some of our results concerning the notions of $E$-finiteness and $E$-tameness.
	\subsection{Generic decompositions of $\mathbf{\g}$-vectors}
	For any $g\in K_{0}(\proj\Lambda)$, there exist unique $P^{-1},P^{0}\in\proj\Lambda$ such that they do not share any non-zero direct summands and $g=[P^0]-[P^{-1}]\in K_{0}(\proj\Lambda)$. Denote
	\[\Hom_{\Lambda}(g):= \Hom_{\Lambda}(P^{-1},P^{0}).\]
	Let $a_1,a_2$ be two morphisms in $\proj\Lambda$. Then the \emph{$E$-invariant} of $a_1$ and $a_2$ is defined by
	\[e(a_1,a_2):=\dim_{K}{\Hom_{K^b(\proj\Lambda)}(a_1,a_2[1])}.\]
	Let $g_1,g_2\in K_0(\proj\Lambda)$. Then the $E$-invariant of $g_1$ and $g_2$ is defined by
	\[e(g_1,g_2):= \min\{e(a_1,a_2)\mid a_1\in\Hom_{\Lambda}(g_1),a_2\in\Hom_{\Lambda}(g_2)\}.\footnote{Since the function $e(-,?):\Hom_{\Lambda}(g_1)\times\Hom_{\Lambda}(g_2)\rightarrow\mathbb{Z}$ is upper semi-continuous, for a general pair $(a_1,a_2)\in\Hom_{\Lambda}(g_1)\times\Hom_{\Lambda}(g_2)$, we have $e(g_1,g_2)=e(a,b)$.}\]
	By \cite[Corollary 4.2]{DeFe15}, $e(g_1,g_2)=e(g_2,g_1)=0$ if and only if a general morphism of $\Hom_{\Lambda}(g_1+g_2)$ can be written as a direct sum of two (general) morphisms in $\Hom_{\Lambda}(g_1)$ and $\Hom_{\Lambda}(g_2)$. We write $g_1 \oplus g_2$ for $g_1 + g_2$ when $e(g_1, g_2) = e(g_2, g_1) = 0$.

	Let $g\in K_0(\proj\Lambda)$. Then $g$ is called \emph{generically indecomposable} if a general morphism in $\Hom_{\Lambda}(g)$ is indecomposable. The decomposition $g=g_1\oplus g_2\oplus\cdots\oplus g_s$ is called the \emph{generic decomposition} of $g$ if a general morphism $a$ of $\Hom_{\Lambda}(g)$ can be written as a direct sum $a=a_1\oplus a_2\oplus\cdots\oplus a_s$ where each $a_i$ is indecomposable and belongs to $\Hom_{\Lambda}(g_i)$. Equivalently, all $g_i$'s are generically indecomposable and $e(g_i,g_j)=0$, for all $1\le i\neq j\le s$. In this case, we denote by \emph{$\ind(g)$} the set of all generically indecomposable $\g$-vectors in the generic decomposition of $g$.

	Let $\mathcal{C}$ be a $2$-CY Krull-Schmidt category with a cluster-tilting object $\Gamma$. Denote $\Lambda=\End_{\mathcal{C}}(\Gamma)^{\op}$. Then by Theorem \ref{UcfISbEawdcJ}, we have a triangulated equivalence
	\begin{equation}\label{lrRwOeVYo6aj}
		\Hom_{\mathcal{C}}(\Gamma,-):K^{b}(\add(\Gamma))\longrightarrow K^{b}(\proj\Lambda).
	\end{equation}
	Thus
	for morphisms $a',a''\in\add(\Gamma)$,
	\[\Hom_{K^b(\add( \Gamma))}(a',a''[1])\cong \Hom_{K^b(\proj\Lambda)}(\Hom_{\mathcal{C}}(\Gamma,a'), \Hom_{\mathcal{C}}(\Gamma,a'')[1]).\]
	Define
	\[e(a',a''):=\dim_{K}{\Hom_{K^b(\add( \Gamma))}(a',a''[1])}.\]
	By \cite[Section 4]{DeFe15} and the above equivalence \eqref{lrRwOeVYo6aj}, one can see that for two $\g$-vectors $g_1,g_2\in K_0(\add(\Gamma))$, $e(g_1,g_2)=e(g_2,g_1)=0$ if and only if a general $\add(\Gamma)$-presentation in $\Hom_{\mathcal{C}}(g_1+g_2)$ can be written as a direct sum of two (general) $\add(\Gamma)$-presentations in $\Hom_{\mathcal{C}}(g_1)$ and $\Hom_{\mathcal{C}}(g_2)$.
	Therefore, one can extend the notion of direct sums of $\g$-vectors for cluster categories \cite[Remark 3.11]{Pla13}.

	\subsection{$E$-finiteness and $E$-tameness}\label{Nfr91saLLBz78}
	We begin by reviewing the notions of $E$-finiteness and $E$-tameness, along with known examples of $E$-finite and $E$-tame algebras. The focus then shifts to Jacobian algebras, where we demonstrate that both $E$-finiteness and $E$-tameness are preserved under mutations of Jacobian algebras. To establish this, we prove that mutation commutes with the direct sum of $\g$-vectors.
	\begin{definition}[{\cite[Definition 6.3]{AsIy24}}]\label{Fr4567nvAEoQJ}
		We say that $g \in K_0(\proj\Lambda)$ is \emph{rigid} if there exists a $2$-term presilting complex $X$ such that $g^X = g$, and \emph{tame} if $e(g, g) = 0$. The algebra $\Lambda$ is called \emph{$E$-finite} (resp., \emph{$E$-tame}) if every element of $K_0(\proj\Lambda)$ is rigid (resp., tame).
	\end{definition}
	\begin{remark}\label{RgDFJ5y6gThr}
		Finite-dimensional $E$-finite algebras are $E$-tame.
	\end{remark}
	\begin{proposition}[{\cite{BST19, As21}}]\label{YQWOqSW20Zqa}
		Every finite-dimensional $\g$-finite algebra is $E$-finite.
	\end{proposition}
	\begin{theorem}[{\cite[Theorem 3.8]{PYK23}}]\label{B9OIm5j2hMxc}
		Finite-dimensional representation-tame algebras are $E$-tame.
	\end{theorem}

	\begin{corollary}
		Let $(Q,W)$ be a non-degenerate Jacobi-finite QP. Assume that $Q$ is of finite mutation type and not mutation equivalent to any of the following quivers: $K_m$ for $m\ge 3$, $X_6$, $X_7$, and $T_2$. Then $\mathcal{J}(Q,W)$ is E-tame.
	\end{corollary}
	\begin{proof}
		It follows directly from Theorems \ref{SF76ppyobv7F} and \ref{B9OIm5j2hMxc}.
	\end{proof}
	\begin{proposition}\label{prop:Kro}
		The Jacobian algebra $\mathcal{J}(K_m,0)$ is not $E$-finite for $m=2$, and not $E$-tame for any $m\ge 3$.
	\end{proposition}
	\begin{proof}
		The non-$E$-finiteness of $\mathcal{J}(K_2,0)$ follows from \cite[Remark 3.19]{BST19}, and the non-$E$-tameness of $\mathcal{J}(K_m,0)$ for $m\ge 3$ follows from \cite[Example 4.6]{HY25b}.
	\end{proof}

	\begin{proposition}[{\cite[Proposition 6.4]{AsIy24}}]\label{R2gTZuMZA4vV}
		Let $\Lambda'$ be a finite-dimensional $K$-algebra.
		Assume that there is a surjective $K$-algebra homomorphism $\Lambda\rightarrow\Lambda'$.
		If $\Lambda$ is $E$-finite (resp., $E$-tame), then so is $\Lambda'$.
	\end{proposition}
	\begin{corollary}\label{cor:Kro}
		Let $(Q,W)$ be a non-degenerate Jacobi-finite QP. If $Q$ contains the Kronecker quiver (resp., the generalized Kronecker quiver $K_m$ for $m\ge 3$) as a subquiver, then $\mathcal{J}(Q,W)$ is not $E$-finite (resp., $E$-tame).
	\end{corollary}
	\begin{proof}
		Let $I \subset Q_0$ be the vertex set of the generalized Kronecker subquiver $K_m$ for $m\ge 2$. Then the restriction $(Q|_I, W|_I)$ is equal to $(K_m,0)$ since $Q$ has no loops or $2$-cycles. Since there is a surjective algebra homomorphism $\mathcal{J}(Q,W) \rightarrow \mathcal{J}(Q|_I, W|_I)$, the assertion follows from Propositions \ref{prop:Kro} and \ref{R2gTZuMZA4vV}.
	\end{proof}
	\subsubsection{Under mutations of Jacobian algebras}
	Let $(Q,W)$ be a non-degenerate Jacobi-finite QP, and
	\[\hat{\Gamma}_{(Q,W)}=\hat{\Gamma}_{(Q,W),1}\oplus\hat{\Gamma}_{(Q,W),2}\oplus\cdots\hat{\Gamma}_{(Q,W),n},\]
	be a Krull-Schmidt decomposition with the property that for all $1\le i\le n$, $\hat{\Gamma}_{(Q,W),i}$ corresponds to the $i$-th vertex of $Q$. Fix $k$ with $1\le k\le n$.
	\begin{proposition}\label{0N428LtgFMnp}
		Let $g_1,g_2\in K_0(\add(\hat{\Gamma}_{(Q,W)}))$. If $g_1+g_2=g_1\oplus g_2$, then
		\[\mu_k(g_1+g_2)=\mu_k(g_1)\oplus\mu_k(g_2).\] 
	\end{proposition}
	\begin{proof}
		It is a direct consequence of \cite[Proposition 3.24]{Pla13} and Diagram \eqref{6FUzaTwbFh77}. It also follows from \cite[Corollary 7.3]{DeFe15}.
	\end{proof}
	\begin{theorem}\label{L9znmRN7cMFf}
		Let $g_1,g_2\in K_0(\proj\mathcal{J}(Q,W))$. Then the following are equivalent:
		\begin{itemize}
			\item[$(1)$] $g_1+g_2=g_1\oplus g_2$.
			\item[$(2)$] $\mu_k(g_1)+\mu_k(g_2)=\mu_k(g_1)\oplus\mu_k(g_2)$.
		\end{itemize}
	\end{theorem}
	\begin{proof}
		It follows from Diagram \eqref{6FUzaTwbFh77} and Proposition \ref{0N428LtgFMnp}.
	\end{proof}
	\begin{theorem}\label{LwDWFmqsJxpt}
		Let $g\in K_{0}(\proj\mathcal{J}(Q,W))$. Then the following hold:
		\begin{itemize}
			\item[$(1)$] $g$ is rigid if and only if so is $\mu_k(g)$.
			\item[$(2)$] $g$ is tame if and only if so is $\mu_k(g)$.
		\end{itemize}
		In particular, $\mathcal{J}(Q,W)$ is $E$-finite (resp., $E$-tame) if and only if so is $\mathcal{J}(\mu_k(Q,W))$.
	\end{theorem}
	\begin{proof}
		The statement $(2)$ is direct consequence of Theorem \ref{L9znmRN7cMFf}. The statement $(1)$ follows from the fact that the bottom map $F_k$ in Diagram \eqref{zvHv2HLFf7K4} preserves presilting complexes.
	\end{proof}
	\begin{remark}
		Based on Theorem \ref{L9znmRN7cMFf}, one can show that if a $\g$-vector $g$ satisfies the ray condition (resp., the non-decreasing condition), then so does $\mu_k(g)$ (see \cite{HY25b, AsIy24, DeFe15} for definition). Therefore, if $\mathcal{J}(Q,W)$ satisfies the ray condition (resp., the non-decreasing condition), then so does $\mathcal{J}(\mu_k(Q,W))$. Thus, by \cite[Proposition 7.1]{AsIy24}, in the case that $Q$ is of acyclic type, $\mathcal{J}(Q,W)$ satisfies the ray condition.\footnote{JiaRui Fei conjectured (through our email discussion) that every finite-dimensional Jacobian algebra satisfies the ray condition.}
	\end{remark}
	\begin{lemma}\label{lem:affine E}
		If $Q$ is of affine type, then $\mathcal{J}(Q,W)$ is not $E$-finite.
	\end{lemma}
	\begin{proof}
		Since $E$-finiteness is invariant under mutations by Theorem \ref{LwDWFmqsJxpt}, we may assume that $Q$ is an acyclic affine quiver and $W=0$. Then it follows from \cite[Corollary 4.9]{RS17} that
		\[
		\mathbb{Z}^{|Q_0|} \setminus \mathcal{F}^{g}_{\cluster}(Q) \neq \emptyset.
		\]
		On the other hand, \cite[Proposition 3.5]{BMRR06} implies that $\rigid^{+}\mathcal{C}_{(Q,0)}=\rigid\mathcal{C}_{(Q,0)}$ and $\ctilt^{+}\mathcal{C}_{(Q,0)}=\ctilt\mathcal{C}_{(Q,0)}$. Therefore, it follows from the observation below Theorem \ref{VTIFVbl5KQBe} that
		\[
		\mathbb{Z}^{|Q_0|} \setminus \mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q,W)) \neq \emptyset.
		\]
		Hence, $\mathcal{J}(Q,W)$ is not $E$-finite.
	\end{proof}


