	\section{Main results}\label{4p5IXJsU8vuj}
	In this section, we discuss the classifications of finite-dimensional Jacobian algebras of finite and tame representation types —namely, representation-finite, $\g$-finite, $E$-finite, $\tau$-tilting finite, representation-tame, $\g$-tame, and $E$-tame— via quivers of Dynkin and finite mutation types. In particular, we show that these finiteness (resp., tameness) representation types are (resp., nearly) the same on finite-dimensional Jacobian algebras. Furthermore, applying our results, we classify cluster algebras with dense $\g$-fans.

	Throughout this section, we assume that all quivers have no loops or $2$-cycles, and all QPs are non-degenerate and Jacobi-finite.
	\begin{lemma}\label{lem:Etame finmut}
		If $\mathcal{J}(Q,W)$ is $E$-tame, then $Q$ is of finite mutation type.
	\end{lemma}
	\begin{proof}
		Assume that $Q$ is not of finite mutation type. Then it must have at least $3$ vertices. By \cite[Theorem 2.6]{FST12}, $Q$ is mutation equivalent to some quiver $Q'$ containing $K_m$ for $m\ge 3$ as a subquiver. Therefore, by Corollary \ref{cor:Kro}, every finite-dimensional Jacobian algebra associated with $Q'$ is not $E$-tame. Thus by Theorem \ref{LwDWFmqsJxpt}, $\mathcal{J}(Q,W)$ is not $E$-tame.
	\end{proof}
	\begin{lemma}\label{Trn7AJuEsX9s}
		Let $(Q,W)$ be a connected QP. If $\mathcal{J}(Q,W)$ is $E$-finite, then $Q$ is of Dynkin type.
	\end{lemma}
	\begin{proof}
		By Remark \ref{RgDFJ5y6gThr} and Lemma \ref{lem:Etame finmut}, the $E$-finiteness of $\mathcal{J}(Q,W)$ implies that $Q$ is of finite mutation type. On the other hand, it follows from Corollary \ref{cor:Kro} and Theorem \ref{LwDWFmqsJxpt} that $Q$ is not mutation equivalent to any of the following quivers: $K_m$ ($m\ge 2$), $X_6$, $X_7$, and $E^{(1,1)}_{i}$ ($i=6,7,8$) as listed in Table \ref{axzK0GRWH13u}. Moreover, by Lemma \ref{lem:affine E}, $Q$ is not of affine type. Therefore, by Theorem \ref{MupWVVH0u2Zz}, $Q$ is either one of the exceptional quivers $E_6$, $E_7$, $E_8$, or defined from a triangulated surface. Then, by Theorem \ref{thm:surf main}, $Q$ must be of Dynkin type.
	\end{proof}
	\subsection{Finiteness classification}
	\begin{theorem}\label{thm:finiteness}
		Let $(Q,W)$ be a connected QP. Then the following are equivalent:
		\begin{itemize}
			\item[$(1)$] $\mathcal{J}(Q,W)$ is $E$-finite;
			\item[$(2)$] $\mathcal{J}(Q,W)$ is $\g$-finite;
			\item[$(3)$] $\mathcal{J}(Q,W)$ is $\tau$-tilting finite;
			\item[$(4)$] $\mathcal{J}(Q,W)$ is representation-finite;
			\item[$(5)$] $Q$ is of Dynkin type;
			\item[$(6)$] $\mathcal{A}(Q)$ is of finite type;
			\item[$(7)$] $\mathcal{F}^g_{\cluster}(Q)$ is complete.
		\end{itemize}
	\end{theorem}
	\begin{proof}
		The relations among the conditions $(1)$--$(7)$ are summarized in the following diagram, where all arrows are justified by the indicated results:
		\[\begin{tikzcd}[column sep=large,cramped]
			{(4)} && {(5)} && {(6)}\\
			&& {(1)} &&\\
			{(3)} && {(2)} && {(7)}
			\arrow["\text{Cor. \ref{cor:rep type}}", Leftarrow, from=1-1, to=1-3]
			\arrow["\text{Thm. \ref{7QdLexH7Sem2}}", Leftrightarrow, from=1-3, to=1-5]
			\arrow["\text{Rem. \ref{LJwIJTvJ2fcB}}"{swap}, Rightarrow, from=1-1, to=3-1]
			\arrow["\text{Thm. \ref{7QdLexH7Sem3}}", Rightarrow, from=1-3, to=3-5]
			\arrow["\text{Thm. \ref{Ypp40yreQWb2}}"{swap}, Leftrightarrow, from=3-1, to=3-3]
			\arrow["\text{Rem. \ref{teSU4F2m6VPA}}"{swap}, Leftarrow, from=3-3, to=3-5]
			\arrow["\text{Prop. \ref{YQWOqSW20Zqa}}", Rightarrow, from=3-3, to=2-3]
			\arrow["\text{Lem. \ref{Trn7AJuEsX9s}}", Rightarrow, from=2-3, to=1-3]
		\end{tikzcd}\]
	\end{proof}
	\begin{corollary}\label{Cf4iTsp13aMpY68}
		Let $Q$ be a connected quiver. Then $\mathcal{F}^{g}_{\cluster}(Q)$ is complete if and only if $Q$ is of Dynkin type.
	\end{corollary}
	\begin{proof}
		The ``if'' part follows from Theorem \ref{7QdLexH7Sem3}. 
		Assume that $\mathcal{F}^{g}_{\cluster}(Q)$ is complete. Then it is dense, and hence $Q$ is of finite mutation type \cite[Theorem 2.27]{Yu23}. Proposition \ref{prop:fin mut} implies that $Q$ admits a non-degenerate Jacobi-finite potential. Therefore, by Theorem \ref{thm:finiteness}, $Q$ must be of Dynkin type.
	\end{proof}
	\subsection{Tameness classification}
	\begin{theorem}\label{thm:tame}
		Let $(Q, W)$ be a connected QP. Assume that $Q$ is not mutation equivalent to any of the following quivers: $K_m$ for $m\ge 3$, $X_6$, $X_7$, and $T_2$. Then the following are equivalent:
		\begin{itemize}
			\item[$(1)$] $\mathcal{J}(Q,W)$ is $E$-tame.
			\item[$(2)$] $\mathcal{J}(Q,W)$ is $\g$-tame.
			\item[$(3)$] $\mathcal{J}(Q,W)$ is representation-tame.
			\item[$(4)$] $Q$ is of finite mutation type.
		\end{itemize}
	\end{theorem}
	\begin{proof}
		The relations among the conditions $(1)$--$(4)$ are summarized in the following diagram, where all arrows are justified by the indicated results:
		\[\begin{tikzcd}[column sep=huge,row sep=large,cramped]
			{(3)} && {(1)}\\
			{(2)} && {(4)}
			\arrow["\text{Thm. \ref{B9OIm5j2hMxc}}", Rightarrow, from=1-1, to=1-3]
			\arrow["\text{Thm. \ref{tGCGN5Yoe6G9}}"{swap}, Rightarrow, from=1-1, to=2-1]
			\arrow["\text{Lem. \ref{lem:Etame finmut}}", Rightarrow, from=1-3, to=2-3]
			\arrow["\text{Thm. \ref{YTckH2lR6VY1}}"{swap}, Leftrightarrow, from=2-1, to=2-3]
			\arrow["\text{Thm. \ref{SF76ppyobv7F}}"{description}, Leftrightarrow, from=1-1, to=2-3]
		\end{tikzcd}\]
	\end{proof}
	Note that $\mathcal{J}(K_m,0)$ is not $E$-tame for any $m\ge 3$ (see Proposition \ref{prop:Kro}). On the other hand, Theorems \ref{SF76ppyobv7F}(4) and \ref{B9OIm5j2hMxc} imply that $\mathcal{J}(T_2,W_2^{\text{tame}})$ is $E$-tame.

	\begin{corollary}\label{G4R4PmnT5Zx09}
		Let $(Q,W)$ be a connected acyclic type QP. Then the following are equivalent:
		\begin{itemize}
			\item[$(1)$] $\mathcal{J}(Q,W)$ is $E$-tame.
			\item[$(2)$] $\mathcal{J}(Q,W)$ is $\g$-tame.
			\item[$(3)$] $\mathcal{J}(Q,W)$ is representation-tame.
			\item[$(4)$] $Q$ is of either Dynkin or affine type.
			\item[$(5)$] $\mathcal{F}^{g}_{\cluster}(Q)$ is dense.
		\end{itemize}
	\end{corollary}
	\begin{proof}
		Conditions $(1)$, $(2)$, and $(3)$ are equivalent by Theorem \ref{thm:tame}. The equivalence between $(3)$ and $(4)$ follows from Corollary \ref{cor:rep type}, and the one between $(4)$ and $(5)$ from Theorem \ref{aEaKnR4m1UVj}.
	\end{proof}

	\begin{conjecture}
		Let $(Q,W)$ be a non-degenerate Jacobi-finite QP. Then $\mathcal{J}(Q,W)$ is $\g$-tame if and only if it is $E$-tame.\footnote{This conjecture was posed by Asai and Iyama for any finite-dimensional algebra \cite[Figure 1]{AsIy24}.}
	\end{conjecture}

