	Next, we assume that $T$ is a tagged triangulation. If there is an ideal triangulation $T^0$ such that $T=\iota(T^0)$, then we define $b_{\gamma,T}(\ell)=b_{\gamma^0,T^0}(\ell)$, where $\gamma=\iota(\gamma^0)$. For an arbitrary $T$, we can obtain a tagged triangulation $T^{(p_1\cdots p_m)}$ from $T$ by changing all tags at punctures $p_1,\ldots,p_m$ (possibly $m=0$), in such a way that there is a unique ideal triangulation $T^0$ such that $T^{(p_1\cdots p_m)}=\iota(T^0)$ (see \cite[Remark 3.11]{MSW11}). Then we define $b_{\gamma,T}(\ell)=b_{\gamma^{(p_1\cdots p_m)},T^{(p_1\cdots p_m)}}\bigl((\cdots((\ell^{(p_1)})^{(p_2)})\cdots)^{(p_m)}\bigr)$, where $\gamma^{(p_1\cdots p_m)}$ is a tagged arc of $T^{(p_1\cdots p_m)}$ corresponding to $\gamma$.

	For a multi-set $L=L'\sqcup\{\ell\}$ of laminates of $\mathcal{S}$, the \emph{shear coordinate $b_{\gamma,T}(L)$ of $L$} with respect to $\gamma\in T$ is inductively defined by
	\[
	b_{\gamma,T}(L)=b_{\gamma,T}(L')+b_{\gamma,T}(\ell).
	\]
	We denote by $b_T(L)$ a vector $(b_{\gamma,T}(L))_{\gamma \in T}\in\mathbb{Z}^{|T|}$, and by $C_T(L)$ the cone in $\mathbb{R}^{|T|}$ spanned by $b_T(\ell)$ for all $\ell\in L$, that is, it is given by
	\[
	C_T(L):=\left\{\sum_{\ell\in L}a_{\ell}b_T(\ell)\relmiddle| a_{\ell}\in\mathbb{R}_{\ge 0}\right\}.
	\]

	\begin{theorem}[{\cite[Theorems 12.3 and 13.6]{FT18}}]\label{z9mIFLwJvbBb}
		Let $T$ be a tagged triangulation of $\mathcal{S}$. The map sending laminations $L$ to $b_T(L)$ induces a bijection between the set of all laminations on $\mathcal{S}$ and $\mathbb{Z}^{|T|}$.
	\end{theorem}
	\subsection{Elementary and exceptional laminates}
