	\begin{theorem}[{\cite{FST08,FT18,LF09b,Re14b}}]\label{XRh46SpQsaiI}
		Let $T$ be a tagged triangulation of $\mathcal{S}$.
		\begin{itemize}
			\item[$(1)$] If $\mathcal{S}$ is not a closed surface with exactly one puncture, then there is a bijection
			\[
			x_{(-)}:\{\text{Tagged arcs in $\mathcal{S}$}\}\longrightarrow\ClVar(Q_T)
			\]
			such that $-b_T(\mathsf{e}(\delta))=g(x_{\delta})$ for any tagged arc $\delta$ in $\mathcal{S}$. Moreover, it induces a bijection
			\[
			x_{(-)}:\{\text{Tagged triangulations in $\mathcal{S}$}\}\longrightarrow\Cluster(Q_T),
			\]
			which sends $T$ to the initial cluster in $\mathcal{A}(Q_T)$ and commutes with flips and mutations.
			\item[$(2)$] If $\mathcal{S}$ is a closed surface with exactly one puncture, then there is a bijection
			\[
			x_{(-)}:
			\Biggl\{\begin{gathered}\text{Tagged arcs in $\mathcal{S}$ with}\\\text{the same tags as those in $T$}\end{gathered}\Biggr\}
			\longrightarrow\ClVar(Q_T)
