	\subsection{Jacobian algebras associated with triangulated surfaces}
	Let $T$ be a tagged triangulation of $\mathcal{S}$ and $W$ a non-degenerate Jacobi-finite potential of $Q_T$. We consider a property of the Jacobian algebra $\mathcal{J}(Q_T,W)$.
	\begin{theorem}[{\cite[Corollary 1.4]{Yu20}}]\label{thm:connected}
		The following holds depending on the type of the surface $\mathcal{S}$:
		\begin{itemize}
			\item[$(1)$] If $\mathcal{S}$ is not a closed surface with exactly one puncture, then
			\[
			\ind\bigl(\rigid(\mathcal{C}_{(Q_T,W)})\bigr)=\ind\bigl(\rigid^+(\mathcal{C}_{(Q_T,W)})\bigr)= \ind\bigl(\rigid^-(\mathcal{C}_{(Q_T,W)})\bigr).
			\]
			\item[$(2)$] If $\mathcal{S}$ is a closed surface with exactly one puncture, then
			\[
			\ind\bigl(\rigid(\mathcal{C}_{(Q_T,W)})\bigr)= \ind\bigl(\rigid^+(\mathcal{C}_{(Q_T,W)})\bigr)\sqcup\ind\bigl(\rigid^-(\mathcal{C}_{(Q_T,W)})\bigr).
			\]
		\end{itemize}
	\end{theorem}
	%
	%
	%
	\begin{remark}\label{rem:Jacobi-fin}
		Labardini–Fragoso \cite{LF09} attaches to $T$ a non-degenerate potential $W_T$ on the quiver $Q_T$. The Jacobian algebra $\mathcal{J}(Q_T,W_T)$ is finite-dimensional in each of the following mutually exclusive cases:
		\begin{itemize}
			\item[$(1)$] $\partial\mathcal{S}\neq\emptyset$ \cite{LF09};
			\item[$(2)$] $\partial\mathcal{S}=\emptyset$ and $\mathcal{S}$ is not the sphere with exactly four punctures \cite{Lad12};
			\item[$(3)$] $\mathcal{S}$ is the sphere with exactly four punctures \cite{LF15}.
		\end{itemize}
		Moreover, if $\mathcal{S}$ is not a closed surface with exactly one puncture, then $\mathcal{J}(Q_T,W)$ is finite-dimensional for every non-degenerate potential $W$ of $Q_T$. This follows from the classification of non-degenerate potentials of $Q_T$ developed in \cite{GGS14, GLFS16, GLFMO20, LF09, LF15, Lad12} (see also \cite{LF16a}).
	\end{remark}
	%
	%
	%
	\begin{corollary}\label{cor:surfbij}
		There is a bijection
		\[
		\mathsf{X}:\{\text{Tagged arcs in $\mathcal{S}$}\}\longrightarrow\ind\bigl(\twopresilt(\mathcal{J}(Q_T,W))\bigr)
		\]
		such that $-b_T(\mathsf{e}(\delta))=g^{\mathsf{X}(\gamma)}$ for any tagged arc $\delta$ in $\mathcal{S}$. Moreover, it induces a bijection
		\[
		\mathsf{X}:\{\text{Tagged triangulations of $\mathcal{S}$}\}\longrightarrow\twosilt(\mathcal{J}(Q_T,W)),
		\]
		which sends $T$ to $\mathcal{J}(Q_T,W)$ and commutes with flips and mutations. In particular, if $\mathcal{S}$ is a closed surface with exactly one puncture, then $\mathsf{X}$ sends $\rho(T)$ to $\mathcal{J}(Q_T,W)[1]$.
	\end{corollary}
	\begin{proof}
		If $\mathcal{S}$ is not a closed surface with exactly one puncture, the desired bijection is obtained by combining the correspondences given in the observation below Theorem \ref{VTIFVbl5KQBe} and Theorem \ref{XRh46SpQsaiI}(1). Then Theorem \ref{thm:connected}(1) ensures that this covers all indecomposable two-term presilting complexes.

		Now, assume that $\mathcal{S}$ is a closed surface with exactly one puncture. In this case, the set of tagged arcs naturally splits into two disjoint subsets depending on the tags (same or different from those in $T$). The desired bijection on the first part is obtained by composing the bijections in Theorems \ref{VTIFVbl5KQBe} and \ref{XRh46SpQsaiI}(2), and that on the second part by Theorems \ref{Lr78jTdZdIN3} and \ref{C2TUel07uSol}. Then Theorem \ref{thm:connected}(2) yields the desired bijection.
	\end{proof}

	%
	%
	%
	\begin{theorem}\label{thm:surf main}
		There is a commutative diagram of bijections:
		\[\begin{tikzcd}[cramped]
			\node(L)at(0,0){\{\text{Laminations on $\mathcal{S}$ consisting of non-closed laminates}\}};
			\node(M)at(0,-1.5){\{\text{Finite multi-sets of pairwise compatible tagged arcs in $\mathcal{S}$}\}};
			\node(2)at(0,-3){\twopresilt\mathcal{J}(Q_T,W)};
			\node(Z)at(7,-3){\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W))\cap\mathbb{Z}^{|T|}};
			\draw[->](L)to[out=0,in=90]node[right]{\scriptstyle -b_T}(Z);
			\draw[->](L)--node[left]{\scriptstyle\mathsf{e}^{-1}((-)_{\sf pq})}(M);
			\draw[->](M)--node[left]{\scriptstyle\mathsf{X}}(2);
			\draw[->](2)--node[above]{\scriptstyle g^{(-)}}(Z);
		\end{tikzcd}\]
		In particular, $\mathcal{J}(Q_T,W)$ is $E$-finite if and only if $Q_T$ is of Dynkin type.
	\end{theorem}
	\begin{proof}
		We verify that all maps in the diagram are bijections and that the diagram is commutative.

		The map $\mathsf{e}^{-1}((-)_{\sf pq})$ is a bijection by Proposition \ref{prop:bij lam arc}. The map $\mathsf{X}$ is a bijection by Corollary \ref{cor:surfbij}. The map $g^{(-)}$ is injective on $\twopresilt(\mathcal{J}(Q_T,W))$ by \cite[Corollary 6.7]{DIJ19} (see also \cite[Section 2.3]{DK08}), and its image lies in $\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W)) \cap \mathbb{Z}^{|T|}$. As the fan $\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W))$ is simplicial and the $g$-vectors of the indecomposable direct summands of any basic two-term silting complex form a $\mathbb{Z}$-basis of the corresponding cone, the map $g^{(-)}$ is also surjective. Hence, $g^{(-)}$ is a bijection onto $\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W)) \cap \mathbb{Z}^{|T|}$.

		The composition $g^{\mathsf{X}(\mathsf{e}^{-1}((-)_{\sf pq}))}$ coincides with $-b_T((-)_{\sf pq})$ by Corollary \ref{cor:surfbij}. Since $b_T(L)=b_T(L_{\sf pq})$ for any lamination $L$ by Lemma \ref{qiaQy8xB1mFh}, it follows that $g^{\mathsf{X}(\mathsf{e}^{-1}(L_{\sf pq}))} = -b_T(L)$. Therefore, the diagram is commutative.

		Finally, combining the bijection $-b_T$ in the diagram with Theorem \ref{z9mIFLwJvbBb} yields a bijection between the set of laminations containing at least one closed laminate and $\mathbb{Z}^{|T|}\setminus\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W))$. By definition, $\mathcal{J}(Q_T,W)$ is $E$-finite if and only if 
		\[\mathbb{Z}^{|T|}\setminus\mathcal{F}^{g}_{\twosilt}(\mathcal{J}(Q_T,W))=\emptyset.\]
		Therefore, the final assertion follows from the fact that $\mathcal{S}$ admits no closed laminates if and only if it is a disc with at most one puncture, in which case $Q_T$ is of Dynkin type.
	\end{proof}

