\section{Proofs of Results} \label{convergence_proof}
In this final section, we assume without loss of generality that $N=N^*$ and denote $Q_t^N := Q_{\phi_t}^N$ and $U_t^N := U_{\theta_t}^N$. We also fix an arbitrary training time bound $T>0$. The constants $C>0$ may vary from line to line (even within the same chain of inequalities) and depend on $T$, but are always independent of $N$. For simplicity, the proof is done with a one-dimensional action space (i.e. $U_t^N: \overline{\Omega} \to \R$), but essentially nothing other than notation changes if $U_t^N$ maps to $\R^k$ for $k \geq 2$.

As a reminder, we are operating under Assumptions \ref{assumption_bounded_second_derivative}, \ref{assumption_eta}, \ref{assumption_g}, and \ref{assumption_neural_net}. There is a fixed neural network scaling parameter $\beta\in \paren{\frac{1}{2},1}$ and a fixed family of smooth truncation functions $\{\psi^N\}_{N\geq1}$ (cf. Definition \ref{definition_smooth_truncation}) with parameter $\delta \in \paren{0, \frac{1-\beta}{4}}$.

We begin by presenting the following lemmas before starting the main proof.

\begin{proposition}[Lipschitz behaviors]\label{proposition_lipschitz}
There exists a constant $C>0$ such that
\begin{enumerate}
    \item For any $x \in \Omega$, any admissible feedback control $u \in \mathcal{U}$, and any functions $f_1, f_2 \in \mathcal{D}(\mathcal{L}^{u})$
    \begin{align}
      \modu{\mathcal{L}^{u}f_1(x)-\mathcal{L}^{u}f_2(x)}\leq C \sum_{|\alpha|\leq 2}\modu{D_\alpha f_1(x)-D_\alpha f_2(x)}
      \end{align}

      \item For any $x \in \Omega$, any admissible feedback controls $u_1, u_2 \in \mathcal{U}$, and any $f \in \mathcal{D}(\mathcal{L}^{u_1})\cap \mathcal{D}(\mathcal{L}^{u_2})$
      \begin{align}
        \modu{\g^{u_1}f(x)-\g^{u_2}f(x)} \leq C\modu{u_1(x)-u_2(x)} \sum_{|\alpha|\leq 2}\modu{D_\alpha f(x)}
      \end{align}

      \item For any $x \in \Omega$, any $u\in \mathcal{U},$ and any $f_1,f_2 \in C^2,$
      \begin{align}
          \modu{\partial_u H(u, f_1 -f_2)(x)} \leq C\sum_{\modu{\alpha} \leq 2}\modu{D_\alpha f_1(x) - D_\alpha f_2(x)}
      \end{align}

      \item For any $x \in \Omega$, any $u_1, u_2 \in \mathcal{U}$, and any $f \in C^2,$
      \begin{align}
          \modu{\partial_u H(u_1 - u_2, f)(x)} \leq C \modu{u_1(x) - u_2(x)}\sum_{\modu{\alpha}\leq 2}\modu{D_\alpha f(x)}
      \end{align}
\end{enumerate}
\end{proposition}
\begin{proof}
Each of these properties ultimately derives from Assumption \ref{assumption_bounded_second_derivative} -- namely that there exists a constant that bounds $\{b_i, \Phi \Phi^\intercal_{ij}, c\}_{i,j}$ and their relevant first-order and second-order derivatives.
\begin{enumerate}
    \item Using the bound on the coefficients directly,
    \begin{align*}
        \modu{\mathcal{L}^{u}f_1(x)-\mathcal{L}^{u}f_2(x)} &\leq \modu{\sum_{i}b_i(x,u(x))\partial_i (f_1-f_2)(x)+\frac{1}{2}\sum_{i,j}{\Phi\Phi^\intercal}_{ij}(x,u(x))\partial^2_{ij} (f_1-f_2)(x) - \gamma(f_1-f_2)(x)}\\ 
        &\leq C\sum_{|\alpha|\leq 2}\modu{D_\alpha (f_1-f_2)(x)}.
    \end{align*}

    \item By the mean value theorem and the bound on the first derivatives in $u$,
    \begin{align*}
        \modu{\g^{u_1}f(x)-\g^{u_2}f(x)} &\leq \bigg|\sum_{i}(b_i(x,u_1(x) )-b_i(x,u_2(x)))\partial_i f(x) \\
        &\quad+\frac{1}{2}\sum_{i,j}({\Phi\Phi^\intercal}_{ij}(x,u_2(x))\partial^2_{ij} - {\Phi\Phi^\intercal}_{ij}(x,u_2(x)))\partial^2_{ij} f(x) - c(x,u_1(x)) - c(x,u_2(x))\bigg| \\
        &\leq C\modu{u_1(x)-u_2(x)} \sum_{|\alpha|\leq 2}\modu{D_\alpha f(x)}.
    \end{align*}

    \item Using the bound on the first derivatives in $u$,
    \begin{align*}
        \modu{\partial_u H(u, f_1 -f_2)(x)} &\leq \modu{\sum_{i}\partial_u b_i(x, u(x))\partial_i (f_1-f_2)(x) + \frac{1}{2}\sum_{i,j} \partial_u (\Phi\Phi^\intercal)_{ij}(x,u(x)) \partial_{ij}(f_1-f_2)(x)} \\
        &\leq C\sum_{\modu{\alpha} \leq 2}\modu{D_\alpha (f_1 - f_2)(x)}.
    \end{align*}

    \item By the mean value theorem and the bound on the second derivatives in $u$,
    \begin{align*}
        \modu{\partial_u H(u_1 - u_2, f)(x)} &\leq \bigg| \sum_i (\partial_u b_i(x,u_1(x))-\partial_ub_i(x,u_2(x)))\partial_i f(x) \\
        &\quad + \sum_{i,j} (\partial_u \Phi\Phi^\intercal(x,u_1(x)) - \partial_u\Phi\Phi^\intercal(x,u_2(x)))\partial_{ij}f(x) + \partial_u c(x,u_1(x)) - \partial_u c(x,u_2(x)) \bigg|\\
        &\leq C \modu{u_1(x) - u_2(x)}\sum_{\modu{\alpha}\leq 2}\modu{D_\alpha f(x)}.
    \end{align*}
\end{enumerate}
\end{proof}

\begin{lemma}[Parameter growth bounds] \label{lemma_param_growth}
    Following the dynamics of \eqref{phi_gradient} and \eqref{theta_gradient}, there exists a constant $C > 0$ such that, for any $0\leq t\leq T$, the critic network parameters satisfy \begin{align}
    \modu{c_t^i - c_0^i} \leq CN^{\delta + \beta - 1},\quad \modu{w_t^{i,j}-w_0^{i,j}} \leq CN^{\delta+\beta-1},\quad \modu{b_t^i - b_0^i} \leq CN^{\delta + \beta - 1},
\end{align}
and the actor network parameters satisfy
\begin{align}
    \modu{h_t^i-h_0^i}\leq CN^{\delta + \beta - 1},\quad \modu{v_t^{i,j} -v_0^{i,j}}\leq CN^{\delta + \beta - 1},\quad \modu{z_t^i-z_0^i}\leq CN^{\delta + \beta - 1}.
\end{align}
In particular, because of Assumption \ref{assumption_neural_net},
\begin{align}
    |c_t^i|\leq C,\quad \mathbb{E}|w_t^{i,j}|\leq C,\quad \mathbb{E}|b_t^i|\leq C,
\end{align}
and
\begin{align}
    |h_t^i|\leq C,\quad \mathbb{E}|v_t^{i,j}|\leq C,\quad \mathbb{E}|z_t^i|\leq C.
\end{align}
\end{lemma}
\begin{proof}
    \begin{enumerate}
    \item It follows directly from training dynamics \eqref{phi_gradient} and the definition of $Q_t^N$ that
    \begin{align*}
        \frac{dc^i_t}{dt} = \omega_t N^{\beta-1} \int_\Omega F^N\paren{\g^{U_t^N}(x)}\eta(x)\sigma(w_t^i \cdot x + b_t^i)d\mu(x).
    \end{align*}
    Since $\eta$, $\sigma$, and $\omega_t$ are bounded and $\modu{F^N(x)} \leq 2N^\delta$, this gives
    \begin{align*}
        \modu{\frac{dc_t^i}{dt}} \leq N^{\beta-1}N^{\delta}C,
    \end{align*}
    so
    \begin{align*}
        \modu{c_t^i-c_0^i} \leq CN^{\delta+\beta-1} \leq CN^{\delta+\beta-1}.
    \end{align*}
    Thus
    \begin{align*}
        \modu{c_t^i} \leq \modu{c_0^i} + \modu{c_t^i - c_0^i} \leq \modu{c_0^i} + CN^{\delta + \beta - 1} \leq C,
    \end{align*}
    where we have used Assumption \ref{assumption_neural_net} to bound $\modu{c_0^i}$.

    Similarly, for any individual weight $w_t^{i,j}$ in a weight vector $w_t^i$, we have
    \begin{align*}
        \frac{dw_t^{i,j}}{dt} = \omega_t N^{\beta-1} \int_\Omega F^N\paren{\g^{U_t^N}(x)}\eta(x) c_t^i \sigma'(w_t^i \cdot x + b_t^i)x_jd\mu(x).
    \end{align*}
    By $\modu{c_t^i} \leq C$, the boundedness of $\eta$, $\sigma'$, and $\omega_t$, and the fact that $\modu{F^N(x)} \leq 2N^\delta$, this gives
    \begin{align*}
        \modu{w_t^{i,j} - w_0^{i,j}} \leq tCN^{\delta+\beta-1} \leq CN^{\delta+\beta-1}.
    \end{align*}
    Thus
    \begin{align*}
        \modu{w_t^{i,j}} \leq \modu{w_0^i} + \modu{w_t^{i,j} - w_0^{i,j}} \leq \modu{w_0^{i,j}} + CN^{\delta + \beta - 1}.
    \end{align*}
    Taking expectations shows $\E\modu{w_t^{i,j}} \leq C$.

    In the same way, for any bias $b_t^i$, we have
    \begin{align*}
        \frac{db_t^i}{dt} = \omega_t N^{\beta-1} \int_\Omega F^N\paren{\g^{U_t^N}(x)}\eta(x) c_t^i \sigma'(w_t^i \cdot x + b_t^i)d\mu(x).
    \end{align*}
    This gives
    \begin{align*}
        \modu{b_t^i - b_0^i} \leq tCN^{\delta+\beta-1} \leq CN^{\delta+\beta-1},
    \end{align*}
    and so
    \begin{align*}
        \modu{b_t^i} &\leq \modu{b_0^i} + \modu{b_t^i - b_0^i} \leq \modu{b_0^i} + CN^{\delta+\beta-1}.
    \end{align*}
    Taking expectations shows $\E\modu{b_t^i} \leq C$.

    \item It follows from the training dynamics \eqref{theta_gradient} that the actor network's parameter dynamics are given by
    \begin{align*}
        \frac{dh^i_t}{dt} &= -\alpha_t N^{\beta-1} \int_\Omega \psi^N(\partial_u H(U_t^N,Q_t^N))\sigma(v_t^i \cdot x + z_t^i)d\mu(x), \\
        \frac{dv^{i,j}_t}{dt} &= -\alpha_t N^{\beta-1} \int_\Omega \psi^N(\partial_u H(U_t^N,Q_t^N))h_t^i\sigma'(v_t^i \cdot x + z_t^i)x_jd\mu(x), \\
        \frac{dz^i_t}{dt} &= -\alpha_t N^{\beta-1} \int_\Omega \psi^N(\partial_u H(U_t^N,Q_t^N))h_t^i\sigma'(v_t^i \cdot x + z_t^i)d\mu(x).
    \end{align*}
    Using the boundedness of $\alpha_t$ and repeating the above reasoning gives the desired bounds.
    \end{enumerate}
\end{proof}
\begin{lemma}\label{lemma_kernel_regularity}
    There exists a constant $C > 0$ such that the kernels $A$ and $B$ defined in \eqref{kernel_A_def} and \eqref{kernel_B_def} obey
    \begin{align*}
        \modu{A(x,y)} \leq C, \qquad \sum_{\modu{\alpha} \leq 2} \modu{D_\alpha^y B(x,y)} \leq C,
    \end{align*}
    for all $(x,y) \in \overline\Omega\times\overline\Omega.$
\begin{proof}
    That $\modu{A(x,y)} \leq C$ follows immediately from the bounds on $\sigma, \sigma'$, the boundedness of $\Omega$, and the assumption that the distribution of $c_0$ has compact support. For the bound on $B$, observe that for any multi-index $\alpha$ such that $\modu{\alpha} \leq 2,$
    \begin{align*}
        \modu{D_\alpha^y B(x,y)} &= \modu{D_\alpha^y \brac{\eta(x)\eta(y)A(x,y)}} \\
        &= \eta(x) \modu{D_\alpha^y \paren{\eta(y) \E_{c,w,b} \brac{\sigma(w\cdot x + b)\sigma(w\cdot y + b) + c^2\sigma'(w\cdot x + b)\sigma'(w\cdot y + b) (x\cdot y + 1)}}} \\
        &= \eta(x) \modu{\E_{c,w,b} \brac{D_\alpha^y \paren{\eta(y)\paren{\sigma(w\cdot x + b)\sigma(w\cdot y + b) + c^2\sigma'(w\cdot x + b)\sigma'(w\cdot y + b) (x\cdot y + 1)} }}} \\
        &\leq C,
    \end{align*}
    where we are able to interchange the derivative and the expectation and show that the expectation is bounded because of Assumption \ref{assumption_neural_net} and that $\eta \in C^3_b$ and $\sigma \in C^4_b.$
\end{proof}
\end{lemma}
\begin{lemma}\label{QQ}
    There exists a constant $C>0$ such that, for any $y \in \overline\Omega$ and $t \in [0,T]$, we have 
    \begin{align}
        \sum_{\modu{\alpha} \leq 2} |D_\alpha Q_t(y)| \leq C.
    \end{align}
\end{lemma}
\begin{proof}
    From the the limit ODE \eqref{limit_ODE}, we have
    \begin{align*}
        Q_t(y) - \overline{g}(y) = \int_0^t \omega_t\int_\Omega \mathcal{L}^{U_s}Q_s(x) B(x,y)d\mu(x)ds.
    \end{align*}
    Then by the boundedness of $\omega_t$ and $B$ and its derivatives, it follows that
    \begin{align*}
        \sum_{\modu{\alpha} \leq 2} |D_\alpha (Q_t(y)-g(y))| &\leq \int_0^t \omega_t \int_\Omega |\mathcal{L}^{U_s}Q_s(x)| \modu{\sum_{\modu{\alpha} \leq 2} D_\alpha^y B(x,y)}d\mu(x)ds\\
        &\leq C\int_0^t \int_\Omega |\mathcal{L}^{U_s}Q_s(x)-\mathcal{L}^{U_s}\overline{g}(x)|+|\mathcal{L}^{U_s}\overline{g}(x)| d\mu(x)ds \\
        & \leq C \int_0^t \int_\Omega \sum_{\modu{\alpha} \leq 2} |D_\alpha Q_t(x) - D_\alpha \overline{g}(x)|d\mu(x)ds + C \int_0^t \int_\Omega \sum_{\modu{\alpha}\leq 2} \modu{D_\alpha \overline{g}(x)}d\mu(x)ds \\
        & \leq C \int_0^t \int_\Omega \sum_{\modu{\alpha} \leq 2} |D_\alpha Q_t(x) - D_\alpha \overline{g}(x)|d\mu(x)ds + C.
    \end{align*}
    In particular,
    \begin{align*}
        \max_{x \in \overline{\Omega} }\sum_{\modu{\alpha} \leq 2} \modu{D_\alpha (Q_t(x)-\overline{g}(x))} \leq C\mu(\Omega)\int_0^t \max_{x \in \overline{\Omega}} \sum_{\modu{\alpha} \leq 2} \modu{D_\alpha (Q_s(x)-\overline{g}(x))} ds + C.
    \end{align*}
    Thus, Gronwall's inequality shows that $$\max_{x \in \overline{\Omega}} \sum_{\modu{\alpha} \leq 2}\modu{D_\alpha Q_t(x) - D_\alpha \overline{g}(x)} \leq C$$ for $t\in[0,T]$. Since $\overline{g} \in C^2_b(\overline\Omega)$, this completes the proof.
\end{proof}
\begin{lemma}\label{l7}
Let
\begin{align}
    \Xi_0^N(y):= \modu{U_0^N(y)-U_0(y)} + \sum_{\modu{\alpha}\leq 2}|D_\alpha(Q_0^N-Q_0)(y)|=|U_0^N(y)|+ \sum_{|\alpha|\leq 2}\modu{D_\alpha Q_0^N(y) - D_\alpha \overline{g}(y)}.
\end{align}
Then
\begin{align}
    \lim_{N \to \infty} \E\brac{\int_\Omega \Xi_0^N(y)^2 d\mu(y)}.
\end{align}
\end{lemma}
\begin{proof}
Notice that
\begin{align*}
    \E\brac{U_0^N(y)}=0, \quad \E\brac{D_\alpha Q_0^N(y) - D_\alpha \overline{g}(y)}=0.
\end{align*}
for arbitrary $\modu{\alpha} \leq 2$. Then
\begin{align*}
    \mathbb{E}[U_0^N(y)^2]=\text{Var}[U_0^N(y)]=N^{1-2\beta}\text{Var}_{h,v,z}[h\sigma(vx+z)] \leq CN^{1-2\beta}
\end{align*}
and
\begin{align*}
    \mathbb{E}[\paren{D_\alpha Q_0^N(y) - D_\alpha \overline{g}(y)}^2]=\text{Var}[D_\alpha \eta(y)Z_0^N(y)]=CN^{1-2\beta}\text{Var}_{c,w,b}[c\sigma(wx+b)] \leq CN^{1-2\beta}.
\end{align*}
Therefore
\begin{align*}
    \E\brac{\int_\Omega \Xi_0^N(y)^2 d\mu(y)} &= \int_\Omega
    \mathbb{E}\brac{\Xi_0^N(y)^2} d\mu(y) \\
    &\leq C\int_\Omega \mathbb{E}\brac{U_0^N(y)^2} + \sum_{|\alpha|\leq 2}\mathbb{E}\brac{\paren{D_\alpha Q_0^N(y) - \overline{g}(y)}^2}d\mu(y) \\ &\leq C N^{1-2\beta} \to 0.
\end{align*}
\end{proof}

\begin{lemma} \label{l8}
    Let $A_s^N$ represent the neural tangent kernel of each finite-width network at time $s \in [0,T]$, i.e.
    \begin{align}
        A_s^N(x,y) = \frac{1}{N}\sum_{i=1}^N \nabla_{c^i,w^i,b^i}\brac{c^i_s \sigma(w^i_s\cdot x+b^i_s)}\cdot \nabla_{c^i,w^i,b^i}\brac{c^i_s \sigma(w^i_s\cdot y+b^i_s)},
    \end{align}
    and let $A = \lim_{N\to\infty}A_0^N$ be the infinite-width limit at time 0 (i.e. the kernel in \eqref{kernel_A_def}). Then
    \begin{align}
        \lim_{N \to \infty}\E\brac{\int_0^T \int_{\Omega^2} N^{2\delta}\modu{{A}_s^N(x,y)-A(x,y)}^2d\mu(x)d\mu(y)ds} = 0.
    \end{align}
\end{lemma}
\begin{proof}
It suffices to prove that
\begin{align*}
    \lim_{N \to \infty} \int_0^T \int_{\Omega^2}N^{2\delta}\E\brac{\modu{A_s^N(x,y)-A(x,y)}^2}d\mu(x)d\mu(y)ds = 0.
\end{align*}
First, we notice that
\begin{align*}
    &\modu{A_s^N(x,y)-A^N_0(x,y)} \\&= \bigg|\frac{1}{N}\sum_{i=1}^N \sigma(w^i_s\cdot x + b_s^i)\sigma(w_s^i \cdot y + b_s^i) - \sigma(w^i_0\cdot x + b_0^i)\sigma(w_0^i \cdot y + b_0^i) \\
    &\quad + (x\cdot y +1)(c_s^i)^2\sigma'(w_s^i\cdot x + b_s^i)\sigma'(w_s^i\cdot y + b_s^i) - (x\cdot y +1)(c_0^i)^2\sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)\bigg| \\
    &\leq \frac{1}{N}\sum_{i=1}^N \modu{\sigma(w^i_s\cdot x + b_s^i)\sigma(w_s^i \cdot y + b_s^i) - \sigma(w^i_0\cdot x + b_0^i)\sigma(w_0^i \cdot y + b_0^i)} \\
    &\quad+ \frac{1}{N}\sum_{i=1}^N\modu{(x\cdot y +1)(c_s^i)^2\paren{\sigma'(w_s^i\cdot x + b_s^i)\sigma'(w_s^i\cdot y + b_s^i) - \sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)}} \\
    &\quad + \frac{1}{N}\sum_{i=1}^N\modu{(x\cdot y +1)\sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)\paren{(c_s^i)^2 - (c_0^i)^2}}.
\end{align*}
We deal with each of these three sums independently. For the first, notice that for each $i \in \{1,\dots, N\}$, since $\sigma \in C_b^4$, the mean value theorem combined with Lemma \ref{lemma_param_growth} gives that
\begin{align*}
    \big|\sigma(w^i_s\cdot x + b_s^i)\sigma(w_s^i \cdot y + b_s^i) &- \sigma(w^i_0\cdot x + b_0^i)\sigma(w_0^i \cdot y + b_0^i) \big| \\ &= \nor{w_s^i - w_0^i}_{l^2} \modu{\sigma'(w^*\cdot x + b_s^i)\sigma(w^*\cdot x + b_s^i) - \sigma'(w^*\cdot x + b_0^i)\sigma(w^*\cdot x + b_0^i)} \\
    &\leq C\nor{w_s^i - w_0^i}_{l^2} \\
    &\leq CN^{\delta + \beta - 1},
\end{align*}
where $w^*$ is a point in the line segment between $w_0^i$ and $w_s^i$. Thus
\begin{align*}
    \frac{1}{N}\sum_{i=1}^N \modu{\sigma(w^i_s\cdot x + b_s^i)\sigma(w_s^i \cdot y + b_s^i) - \sigma(w^i_0\cdot x + b_0^i)\sigma(w_0^i \cdot y + b_0^i)} \leq C N^{\delta + \beta - 1}.
\end{align*}
For the second sum, we again have by a mean value theorem argument that for each $i \in \{1,\dots,N\}$,
\begin{align*}
    \big|(x\cdot y +1)(c_s^i)^2&\big(\sigma'(w_s^i\cdot x + b_s^i)\sigma'(w_s^i\cdot y + b_s^i) - \sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)\big)\big| \\
    &\leq \big|(x\cdot y +1)(c_s^i)^2 \big[(\sigma''(w^* \cdot x + b^*)\sigma'(w^* \cdot x + b^*)\\
    &\quad+\sigma''(w^* \cdot y + b^*)\sigma'(w^* \cdot y + b^*)\big]\big|\nor{(w_s^i - w_0^i, b_s^i - b_0^i)}_{l^1}\\
    &\leq C N^{\delta+\beta-1},
\end{align*}
where $(w^*, b^*)$ is a point on the line segment between $(w_0^i, b_0^i)$ and $(w_s^i,b_s^i)$, and we have used Lemma \ref{lemma_param_growth} and that $\sigma', \sigma''$ are bounded. Thus
\begin{align*}
    \frac{1}{N}\sum_{i=1}^N\modu{(x\cdot y +1)(c_s^i)^2\paren{\sigma'(w_s^i\cdot x + b_s^i)\sigma'(w_s^i\cdot y + b_s^i) - \sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)}} &\leq CN^{\delta+\beta-1}.
\end{align*}
Finally, it is straightforward that
\begin{align*}
    \frac{1}{N}\sum_{i=1}^N\big|(x\cdot y +1)\sigma'(&w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)\paren{(c_s^i)^2 - (c_0^i)^2}\big| \\
    &\leq \frac{\modu{(x\cdot y +1)\sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)}}{N}\sum_{i=1}^N \modu{(c_s^i)^2 - (c_0^i)^2} \\
    &\leq \frac{C}{N} \sum_{i=1}^N  \modu{c_s^i + c_0^i}\modu{c_s^i - c_0^i} \\
    &\leq \frac{C}{N}\sum_{i=1}^N N^{\delta + \beta - 1} \\
    &\leq C N^{\delta + \beta - 1}.
\end{align*}
Hence
\begin{align*}
    \modu{A_s^N(x,y)-A^N_0(x,y)} \leq CN^{\delta+\beta-1},
\end{align*}
and in particular
\begin{align*}
    \modu{A_s^N(x,y)-A^N_0(x,y)}^2 \leq CN^{2\delta+2\beta-2}.
\end{align*}
Next, since $A_0^N(x,y)$ is the mean of $N$ independent and identically distributed random variables with finite variance (namely, $\sigma(w^i_0\cdot x + b_0^i)\sigma(w_0^i \cdot y + b_0^i) + (x\cdot y +1)(c_0^i)^2\sigma'(w_0^i\cdot x + b_0^i)\sigma'(w_0^i\cdot y + b_0^i)$), we have
\begin{align*}
    \mathbb{E}\brac{\modu{{A}_0^N(x,y)-A(x,y)}^2}&=\mathbb{E}\brac{\paren{A_0^N(x,y)-\mathbb{E}[A_0^N(x,y)]}^2}=\text{Var}[{A}_0^N(x,y)]
    \leq \frac{C}{N}.
\end{align*}
Combining the inequalities above gives
\begin{align*}
    N^{2\delta} \mathbb{E}\brac{\modu{A_s^N(x,y)-A(x,y)}^2} &\leq 2N^{2\delta} \E\brac{(A_s^N(x,y) - A_0^N(x,y))^2 + (A_0^N(x,y) - A(x,y))^2}\\
    &\leq C N^{4\delta+\beta-1}+ CN^{2\delta-1}.
    \end{align*}
Thus
\begin{align*}
    \int_0^T \int_{\Omega^2}N^{2\delta}\E\brac{\modu{A_s^N(x,y)-A(x,y)}^2}d\mu(x)d\mu(y)ds \leq C N^{4\delta+\beta-1}+ CN^{2\delta-1} \to 0.
\end{align*}
\end{proof}

\begin{lemma} \label{l9}
Let $B_s^N(x,y) = \eta(x)\eta(y)A_s^N(x,y)$ and $B = \lim_{N\to\infty} B_0^N$ be the infinite-width limit at time 0 (i.e. the kernel in \eqref{kernel_B_def}). Denote
\begin{align}
    S_s^N(x,y) := \sum_{|\alpha|\leq 2} \modu{D_\alpha^y B(x,y)-D_\alpha^y B^N_s(x,y)}.
\end{align}
Then
\begin{align}
    \lim_{N\to\infty}\mathbb{E}\brac{\int_0^T \int_{\Omega^2} N^{2\delta} S_s^N(x,y)^2 d\mu(x)d\mu(y)ds} = 0.      
\end{align}
\end{lemma}
\begin{proof}
    The proof is very similar to that of Lemma \ref{l8}. It suffices to show that for arbitrary multi-index $\alpha$ with $\modu{\alpha} \leq 2$, we have
    \begin{align*}
        \lim_{N \to \infty} \int_0^T \int_{\Omega^2}N^{2\delta}\mathbb{E}\brac{\modu{D_\alpha^y B(x,y)-D_\alpha^y B^N_s(x,y)}^2} d\mu(x)d\mu(y) ds = 0.
    \end{align*}
    Since $\eta\in C_b^3$ and $\sigma \in C_b^4$, it follows for $\modu{\alpha} \leq 2$ and any $i \in \{1,\dots,N\}$ that
    \begin{align*}
        D_\alpha^y \paren{\eta(x)\eta(y)\nabla_{c^i,w^i,b^i}\brac{c^i_s \sigma(w^i_s\cdot x+b^i_s)}\cdot \nabla_{c^i,w^i,b^i}\brac{c^i_s \sigma(w^i_s\cdot y+b^i_s)}} := R(c_s^i,w_s^i,b_s^i) \in C^1_b
    \end{align*} as a function of the parameters $(c_s^i,w_s^i,b_s^i)$ with a $C^1$-bound independent of $(x,y)\in \Omega^2$. Then by the mean value theorem (as in the proof of Lemma \ref{l8}),
    \begin{align*}
        \modu{R(c_s^i,w_s^i,b_s^i) - R(c_0^i,w_0^i,b_0^i)} &\leq \paren{\|c_s^i-c_0^i\|+ \|w_s^i-w_0^i\|+\|b_s^i-b_0^i\|} \sup_{c,w,b}\nor{\nabla_{c,w,b}R(c,w,b)} \\
        &\leq C\paren{\|c_s^i-c_0^i\|+ \|w_s^i-w_0^i\|+\|b_s^i-b_0^i\|} \\
        &\leq CN^{\delta + \beta - 1},
    \end{align*}
    where we use the bounds on the parameter increments provided by Lemma \ref{lemma_param_growth}. Thus
    \begin{align*}
        \modu{D_\alpha^y B_0^N(x,y)-D_\alpha^y B^N_s(x,y)}^2 &\leq \frac{1}{N} \sum_{i=1}^N \modu{R(c_s^i,w_s^i,b_s^i) - R(c_0^i,w_0^i,b_0^i)}^2\\
        &\leq \frac{C}{N}\sum_{i=1}^N N^{2\delta+2\beta-2} \\
        &\leq CN^{2\delta+2\beta-2},
    \end{align*}
    and so
    \begin{align*}
     \mathbb{E}\brac{\modu{D_\alpha^y B_0^N(x,y)-D_\alpha^y B^N_s(x,y)}^2} \leq C N^{2\delta+2\beta-2}.
    \end{align*}
    On the other hand, $D_\alpha^y B^N_0(x,y)$ is the mean of $N$ independent and identically distributed random variables with finite variance. Thus
    \begin{align*}
        \mathbb{E}\brac{\modu{D_\alpha^y B_0^N(x,y)-D_\alpha^y B(x,y)}^2}=\mathbb{E}\brac{\paren{D_\alpha^y B_0^N(x,y)-\mathbb{E}[D_\alpha^y B_0^N(x,y)]}^2} = \text{Var}[D_\alpha^y B_0^N(x,y)] \leq \frac{C}{N}.
    \end{align*}
    Combining the inequalities above gives
    \begin{align*}
        N^{2\delta} \mathbb{E}\brac{\modu{D_\alpha^y B(x,y)-D_\alpha^y B^N_s(x,y)}^2} &\leq 2N^{2\delta}\E\brac{(D_\alpha^yB_s^N(x,y) - D_\alpha B_0^N(x,y))^2 + (D_\alpha^yB_0^N(x,y) - D_\alpha^yB(x,y))^2}\\
        &\leq CN^{4\delta+\beta-1}+ CN^{2\delta-1}.
    \end{align*}
    Thus
    \begin{align*}
        \int_0^T \int_{\Omega^2}N^{2\delta}\mathbb{E}\brac{\modu{D_\alpha^y B(x,y)-D_\alpha^y B^N_s(x,y)}^2} d\mu(x)d\mu(y) ds = CN^{4\delta+\beta-1}+ CN^{2\delta-1} \to 0.
    \end{align*}
\end{proof}

\begin{lemma} \label{lemma_dominated_convergence}
    We have that
    \begin{align}
        \lim_{N \to \infty}\E\brac{\int_0^T \int_\Omega \modu{\g^{U_s}Q_s(x)}^2\mathbf{1}_{\{\modu{\g^{U_s}Q_s} \geq N^\delta\}}(x) + \modu{\partial_uH(U_s,Q_s)(x)}^2\mathbf{1}_{\modu{\partial_uH(U_s,Q_s)} \geq N^\delta\}}(x)d\mu(x)ds} = 0.
    \end{align}
\end{lemma}
\begin{proof}
    By Lemma \ref{QQ} and Assumption \ref{assumption_bounded_second_derivative}, it is clear that there exists a constant $C$ such that for each $s \in [0,T]$ and $x \in \Omega$,
    \begin{align*}
        \modu{\g^{U_s}Q_s(x)} \leq C \quad \text{ and } \quad \modu{\partial_uH(U_s,Q_s)(x)} \leq C.
    \end{align*}
    Thus, the dominated convergence theorem (on the product $\sigma$-algebra) gives the desired result.
\end{proof}

\begin{proof}[\textbf{Proof of Theorem \ref{thm_limit_ode}}]
    Integrating the dynamics of $Q^N$ and $Q$ with respect to time gives
    \begin{align*}
        Q_t^N(y) = Q_0^N(y)+ \int_0^t \omega_t \int_\Omega F^N\paren{\mathcal{L}^{U_s^N}Q_s^N(x)}B_s^N(x,y)d\mu(x) ds
    \end{align*}
    and
    \begin{align*}
        Q_t(y)=Q_0(y)+\int_0^t \omega_t \int_\Omega \mathcal{L}^{U_s}Q_s(x) B(x,y)d\mu(x)ds.
    \end{align*}
    Then for arbitrary multi-index $\alpha$ with $\modu{\alpha} \leq 2$,
    \begin{align*}
        D_\alpha(Q_t^N-Q_t)(y)&=D_\alpha (Q_0^N-Q_0)(y)+ \int_0^t \omega_t \int_\Omega F^N\paren{\mathcal{L}^{U_s^N}Q_s^N(x)}D_\alpha^y B_s^N(x,y) - \mathcal{L}^{U_s}Q_s(x) D_\alpha^y B(x,y)d\mu(x) ds.
    \end{align*}
    We may bound the integral above by four integrals that are individually easier to handle:
    \begin{align}
        \begin{split}
            |D_\alpha(Q_t^N-Q_t)(y)| \leq |D_\alpha (Q_0^N-Q_0)(y)| &+ C\int_0^t \int_\Omega |F^N(\mathcal{L}^{U_s^N}Q_s^N(x))||D_\alpha^y B_s^N(x,y)-D_\alpha^y B(x,y)|d\mu(x) ds \\
            &+ C\int_0^t \int_\Omega |F^N(\mathcal{L}^{U_s^N}Q_s^N(x))-F^N(\mathcal{L}^{U_s^N}Q_s(x))||D_\alpha^y B(x,y)|d\mu(x) ds\\
            &+ C\int_0^t \int_\Omega |F^N(\mathcal{L}^{U_s^N}Q_s(x))-F^N(\mathcal{L}^{U_s}Q_s(x))||D_\alpha^y B(x,y)|d\mu(x) ds\\
            &+ C\int_0^t \int_\Omega |F^N(\mathcal{L}^{U_s}Q_s^N(x))-\mathcal{L}^{U_s}Q_s(x)||D_\alpha^y B(x,y)|d\mu(x) ds.
        \end{split}
    \end{align}
    Using that $|F^N(x)|\leq 2N^\delta$ and $\modu{F^N(x) - x} \leq 2\modu{x}\mathbf{1}_{\{x \geq N^\delta\}}$, each $F^N$ is Lipschitz with a uniform constant, Proposition \ref{proposition_lipschitz}, Lemma \ref{QQ}, and that there exists a constant $C$ such that $\sum_{\modu{\alpha} \leq 2}|D_\alpha^y B(x,y)|\leq C$, we have
    \begin{align} \label{Q_split}
    \begin{split}
        |D_\alpha(Q_t^N-Q_t)(y)|
        &\leq |D_\alpha (Q_0^N-Q_0)(y)| + C\int_0^t\int_\Omega N^\delta |D_\alpha^y B_s^N(x,y)-D_\alpha^y B_s(x,y)|d\mu(x) ds \\
        &\quad+C \int_0^t \int_\Omega \sum_{\modu{\alpha}\leq 2}\modu{D_\alpha \paren{Q_s^N - Q_s}(x)}d\mu(x) ds\\
        &\quad+C \int_0^t \int_\Omega |U_s^N(x)-U_s(x)|\sum_{\modu{\alpha}\leq 2}|D_\alpha Q_s(x)|d\mu(x) ds\\
        &\quad+ C\int_0^t \int_\Omega |\mathcal{L}^{U_s}Q_s(x)|\mathbf{1}_{\{|\mathcal{L}^{U_s}Q_s|\geq N^{\delta}\}}(x) d\mu(x) ds\\
        &\leq |D_\alpha (Q_0^N-Q_0)(y)| + C\int_0^t\int_\Omega N^\delta |D_\alpha^y B_s^N(x,y)-D_\alpha^y B_s(x,y)|d\mu(x) ds \\
        &\quad+C \int_0^t \int_\Omega \sum_{|\alpha|\leq 2}|D_\alpha(Q_s^N-Q_s)(x)|+|U_s^N(x)-U_s(x)|d\mu(x) ds\\
        &\quad+ C\int_0^t \int_\Omega |\mathcal{L}^{U_s}Q_s(x)|\mathbf{1}_{\{|\mathcal{L}^{U_s}Q_s|\geq N^{\delta}\}}(x) d\mu(x) ds.
    \end{split}
    \end{align}
    Similarly, for the actor process $U_t^N$, we have
    \begin{align} \label{UN_growth}
        U_t^N(y)=U_0^N(y)-\int_0^t \alpha_s \int_\Omega \psi^N(\partial_u H(U_s^N,Q_s^N)(x))A^N_s(x,y)d\mu(x) ds,
    \end{align}
    and
    \begin{align} \label{U_growth}
        U_t(y)=U_0(y)-\int_0^t \alpha_s\int_\Omega \partial_u H(U_s,Q_s)(x){A}(x,y)d\mu(x) ds.
    \end{align}
    Subtracting \eqref{U_growth} from \eqref{UN_growth}, splitting the integral, and using that $\alpha_s \leq C$ gives
    \begin{align} \label{U_diff_growth}
        \begin{split}
            |U_t^N(y)-U_t(y)| &\leq |U_0^N(y)-U_0(y)| + C \int_0^t \int_\Omega |\psi^N(\partial_u H(U_s^N,Q_s^N)(x))||A_s^N(x,y)-A(x,y)|d\mu(x)ds\\
            &\quad + C\int_0^t \int_\Omega |\psi^N(\partial_u H(U_s^N,Q_s^N)(x))-\psi^N(\partial_u H(U_s,Q_s)(x))||A(x,y)|d\mu(x)ds\\
            &\quad + C\int_0^t \int_\Omega |\psi^N(\partial_u H(U_s,Q_s)(x))-\partial_u H(U_s,Q_s)(x)||A(x,y)|d\mu(x)ds\\
            &\leq |U_0^N(y)-U_0(y)| + C\int_0^t \int_\Omega N^\delta |A_s^N(x,y)-A(x,y)|d\mu(x)ds\\
            &\quad + C\int_0^t \int_\Omega |\partial_u H(U_s^N,Q_s^N)(x)-\partial_u H(U_s,Q_s)(x)||A(x,y)|d\mu(x)ds\\
            &\quad + C \int_0^t \int_\Omega |\partial_u H(U_s,Q_s)(x)|\mathbf{1}_{\{|\partial_u H(U_s,Q_s)|\geq N^\delta\}}(x)|A(x,y)|d\mu(x)ds.
        \end{split}
    \end{align}
    Notice that by Proposition \ref{proposition_lipschitz} and Lemma \ref{QQ},
    \begin{align*}
        &|\partial_u H(U_s^N,Q_s^N)(x)-\partial_u H(U_s,Q_s)(x)|\\ &\leq |\partial_u H(U_s^N,Q_s^N)(x)-\partial_u H(U_s^N,Q_s)(x)|+|\partial_u H(U_s^N,Q_s)(x)-\partial_u H(U_s,Q_s)(x)|\\
        &\leq C \sum_{|\alpha|\leq 2}|D_\alpha(Q_s^N-Q_s)(x)|+ C|U_s^N(x)-U_s(x)|\sum_{|\alpha|\leq 2}|D_\alpha Q_s(x)| \\
        &\leq C \paren{\sum_{|\alpha|\leq 2}|D_\alpha(Q_s^N-Q_s)(x)|+ |U_s^N(x)-U_s(x)|}.
    \end{align*}
    Using this and applying the bound $|A(x,y)| \leq C$, we have from \eqref{U_diff_growth} that
    \begin{align} \label{U_diff_bound}
        \begin{split}
            \modu{U_t^N(y)-U_t(y)}&\leq \modu{U_0^N(y)-U_0(y)} + C\int_0^t \int_\Omega N^\delta\modu{A_s^N(x,y)-A(x,y)}d\mu(x)ds\\
            &\quad + C \int_0^t\int_\Omega \sum_{|\alpha|\leq 2}\modu{D_\alpha(Q_s^N-Q_s)(x)}+\modu{U_s^N(x)-U_s(x)}d\mu(x)ds\\
            &\quad + C \int_0^t \int_\Omega \modu{\partial_u H(U_s,Q_s)(x)}\mathbf{1}_{\{|\partial_u H(U_s,Q_s)|\geq N^\delta\}}(x)d\mu(x)ds.
        \end{split}
    \end{align}
    Summing up the inequalities \eqref{Q_split} for all multi-indices $\modu{\alpha} \leq 2$ and adding \eqref{U_diff_bound} gives
    \begin{align} \label{Xi_bound}
        \Xi_t^N(y) \leq \Bar{J}_t^N(y)+C\int_0^t \int_\Omega \Xi^N_s(x) d\mu(x)ds,
    \end{align}
    where we define
    \begin{align}
        \Xi_t^N(y):=|U_t^N(y)-U_t(y)|+ \sum_{|\alpha|\leq 2}|D_\alpha(Q_t^N-Q_t)(y)|
    \end{align}
    and a residual term
    \begin{align}
        \begin{split}
            \Bar{J}_t^N(y):&=C \bigg[ \int_0^t \int_\Omega N^\delta \modu{\Bar{A}_s^N(x,y)-A(x,y)}d\mu(x)ds + \int_0^t\int_\Omega N^\delta S_s^N(x,y)dx ds\\
            &\quad + \int_0^t \int_\Omega \modu{\mathcal{L}^{U_s}Q_s(x)}\mathbf{1}_{\curlbrac{|\mathcal{L}^{U_s}Q_s|\geq N^{\delta}}}(x)d\mu(x)ds \\
            &\quad+ \int_0^t \int_\Omega\modu{\partial_u H(U_s,Q_s)(x)}\mathbf{1}_{\curlbrac{|\partial_u H(U_s,Q_s)|\geq N^\delta}}(x) d\mu(x) ds+\Xi_0^N(y) \bigg].
        \end{split}
    \end{align}
    Here, $S_s^N(x,y):=\sum_{|\alpha|\leq 2} |D_\alpha^y B_s^N(x,y)-D_\alpha^y B_s^N(x,y)|$. Multiplying by $\Xi_t^N(y)$ on both sides of \eqref{Xi_bound}, integrating, and using the Cauchy and Jensen inequalities gives
    \begin{align*}
        \int_\Omega \Xi_t^N(y)^2 d\mu(y) & \leq \int_\Omega \Xi_t^N(y)\Bar{J}_t^N(y) d\mu(y) + \int_0^t \int_{\Omega^2} \Xi_s^N(x)\Xi_t^N(y)d\mu(x)d\mu(y)ds \\
        & \leq C\paren{\int_\Omega \Xi_t^N(y)^2 d\mu(y)}^{\frac{1}{2}}\brac{J_T^N + \int_0^t \paren{\int_\Omega \Xi_s^N(y)^2 d\mu(y)}^{\frac{1}{2}} ds},
    \end{align*}
    where repeatedly using the Cauchy inequality and that $t \leq T$ inspires setting
    \begin{align}
        \begin{split}
            J_T^N&= \paren{\int_\Omega \Xi_0^N(y)^2 d\mu(y)}^{\frac{1}{2}} + \int_0^T\paren{ \int_{\Omega^2} N^{2\delta}|\Bar{A}_s^N(x,y)-A(x,y)|^2d\mu(x)d\mu(y)ds}^{\frac{1}{2}}ds\\
            &\quad +\int_0^T \paren{\int_{\Omega^2} N^{2\delta} S_s^N(x,y)^2 d\mu(x)d\mu(y)}^{\frac{1}{2}}ds+\int_0^T \int_\Omega \modu{\mathcal{L}^{U_s}Q_s(x)}\mathbf{1}_{\{|\mathcal{L}^{U_s}Q_s|\geq N^{\delta}\}}(x)d\mu(x) ds\\
            &\quad +\int_0^T \int_\Omega \modu{\partial_u H(U_s,Q_s)(x)}\mathbf{1}_{\{|\partial_u H(U_s,Q_s)|\geq N^\delta\}}(x) d\mu(x) ds.
        \end{split}
    \end{align}
    Therefore
    \begin{align*}
        \paren{\int_\Omega \Xi_t^N(y)^2 d\mu(y)}^{\frac{1}{2}} \leq J_T^N + C \int_0^t \paren{\int_\Omega \Xi_s^N(y)^2 d\mu(y)}^{\frac{1}{2}} ds,
    \end{align*}
    and so by Gronwall's inequality,
    \begin{align*}
        \paren{\int_\Omega \Xi_t^N(y)^2 d\mu(y)}^{\frac{1}{2}} \leq J_T^N e^{Ct}.
    \end{align*}
    Squaring this relation and taking expectations with respect to the parameter initialization gives
    \begin{align*}
        \E\brac{\int_\Omega \Xi_t^N(y)^2 d\mu(y)} \leq \mathbb{E}\brac{(J_T^N)^2}e^{2Ct}.
    \end{align*}
    Observe that by squaring $J_T^N$, using Jensen's inequality, and taking expectations, we have
    \begin{align}
    \begin{split}
        \E\brac{(J_T^N)^2} &\leq  C\E\bigg[\int_\Omega \Xi_0^N(y)^2 d\mu(y)+\int_0^T \int_{\Omega^2} N^{2\delta}|\Bar{A}_s^N(x,y)-A(x,y)|^2d\mu(x)d\mu(y)dsds\\
        &\quad +\int_0^T \int_{\Omega^2} N^{2\delta} S_s^N(x,y)^2 d\mu(x)d\mu(y) ds+\int_0^T \int_\Omega \modu{\mathcal{L}^{U_s}Q_s(x)}^2\mathbf{1}_{\{|\mathcal{L}^{U_s}Q_s|\geq N^{\delta}\}}(x)\\
        &\quad +\modu{\partial_u H(U_s,Q_s)(x)}^2\mathbf{1}_{\{|\partial_u H(U_s,Q_s)|\geq N^\delta\}}(x) d\mu(x) ds\bigg].
    \end{split}
    \end{align}
    Then as $N\to\infty$, the first integral disappears by Lemma \ref{l7}, the second by Lemma \ref{l8}, the third by Lemma \ref{l9}, and the fourth by Lemma \ref{lemma_dominated_convergence}. Thus
    \begin{align*}
        \lim_{N \to \infty} \E\brac{\int_\Omega \Xi_t^N(y)^2 d\mu(y)} = 0.
    \end{align*}
    Further,
    \begin{align*}
        \|U_t^N-U_t\|_{L^2}^2+\|Q_t^N-Q_t\|_{\mathcal{H}^2}^2 &= \int_\Omega \bigg( |U_t^N(y)-U_t(y)|^2+ \sum_{|\alpha|\leq 2}|D_\alpha(Q_t^N-Q_t)(y)|^2\bigg) d\mu(y) \\
        &\leq C \int_\Omega \Xi_t^N(y)^2 d\mu(y).
    \end{align*}
    Therefore
    \begin{align*}
        \lim_{N\to\infty}\E\brac{\nor{U_t^N-U_t}_{L^2}^2+\nor{Q_t^N-Q_t}_{\h^2}^2} = 0.
    \end{align*}
    Since the original training time bound $T\geq t$ is arbitrary, we conclude that this holds for any $t \geq 0$. A final round of applying Jensen's inequality then gives \eqref{eq_limit_ode_convergence}.
\end{proof}
