\section{Frustration-free open projections}\label{Sec:FFOpenProj}


We start with a few context-free remarks about open projections. Henceforth, let $\Aa$ be again a unital separable $C^\ast$-algebra and $\Aa^{\ast \ast}$ be its double dual. The latter is naturally a $W^\ast$-algebra that can be concretely realized as the weak closure of the universal representation $\pi_u = \bigoplus_{\eta \in {\rm S}(\Aa) } \pi_\eta$ of $\Aa$ \cite{ShermanPICM1950,TakedaPJA1954}. If $\Aa$ is a $G$-$C^\ast$-algebra, then $\Aa^{\ast \ast}$ is a $G$-$W^\ast$-algebra.

\begin{definition}[\cite{AkemannJFA1969}]
    A projection $p\in \Aa^{\ast \ast}$ is open if there exists a net $\{a_\alpha\}\in \Aa$ such that $0\leq a_\alpha \uparrow p$. If $p$ is open, one says that $p'=1-p$ is closed.
\end{definition}

\begin{proposition}[\cite{AkemannJFA1969,AkemannAM2015}]
    We denote the sets of projections and of open projections in $\Aa^{\ast \ast}$ by $\Pp(\Aa^{\ast \ast})$ and $\Pp_o(\Aa^{\ast \ast})$, respectively, and we endow both with the partial order inherited from $\BM(\Hh_u)$. Then $(\Pp(\Aa^{\ast \ast}),\leq )$ is a complete lattice and $(\Pp_o(\Aa^{\ast \ast}),\leq )$ is a semilattice.
\end{proposition}

\begin{proof}
    The first statement is always true for $W^\ast$-algebras. Now, let $p,p' \in \Pp_o(\Aa^{\ast \ast})$ and consider the subset 
    \begin{equation}
    J(p,p') =\{q \in \Pp_o(\Aa^{\ast \ast}), \ q \leq p, \ q \leq p' \}.
    \end{equation}
    Then 
    \begin{equation}
     p \wedge_o p' := \sup\nolimits_{\Pp(\Aa^{\ast \ast})} \, J(p,p')
    \end{equation} 
    exists and is an open projection \cite{AkemannJFA1969}. Clearly, $p \wedge_o p' \leq p$ and $p \wedge_o p' \leq p'$ and $p \wedge_o p'$ is the maximal open projection with this property.
\end{proof}

\begin{remark}
    {\rm Note that, in general, $(\Pp_o(\Aa^{\ast \ast}),\leq )$ is not a sublattice of $(\Pp(\Aa^{\ast \ast}),\leq )$, since $p\wedge p'$ may not be open \cite{AkemannJFA1969}[Example~II.6].   }
\end{remark}

\begin{proposition}[\cite{AkemannJFA1969,AkemannJFA1970}]\label{Prop:P1}
    $\Pp_o(\Aa^{\ast \ast})$ and $\mathfrak H(\Aa)$ are isomorphic posets. In one direction, the isomorphism is implemented by 
    \begin{equation}
        \Pp_o(\Aa^{\ast \ast})\ni p \mapsto p\Aa^{\ast \ast} p \cap \Aa =p \Aa p \cap \Aa \in \mathfrak H(\Aa).
    \end{equation}
    and by 
    \begin{equation}
       \mathfrak H(\Aa) \ni \Bb=\overline{w_\Bb \Aa w_\Bb} \mapsto p = \lim w_\Bb^{1/n} \in \Aa^{\ast \ast} \in \Pp_o(\Aa^{\ast \ast})
    \end{equation}
    in the opposite direction.
\end{proposition}

Specializing now to $\Aa = \Ss^{\otimes G}$, here is our first remark:

\begin{proposition}\label{Prop;FtoP}
    There exists a $G$-equivariant morphism of semilattices
\begin{equation}
   \mathfrak F(\Ss^{\otimes G}) \to \Pp_o((\Ss^{\otimes G})^{\ast \ast})     
\end{equation}
\end{proposition}

\begin{proof}
A frustration-free system of projections $\{p_\Lambda\} \in \mathfrak F(\Ss^{\otimes G})$ is an increasing net of projections; hence it has a unique strong limit in $\BM(\Hh_u)$, and hence a unique limit in $\Aa^{\ast \ast}$. Then the correspondence $\{p_\Lambda\} \mapsto \lim p_\Lambda$ supplies the morphism mentioned in the statement. This morphism respects the partial orders and the $G$-actions.
\end{proof}

If $\Pp_o^F((\Ss^{\otimes G})^{\ast \ast})$ denotes the image of this morphism, then \ref{Prop;FtoP} supplies the first morphism in the top part of diagram \eqref{Eq:MasterDiag}, while the second morphism in the same part of the diagram derives from \ref{Prop:P1}.

\begin{remark}
    {\rm The subset of open projections induced by the frustration-free systems of projections also coincides with the image of $\mathfrak H^F(\Ss^{\otimes G})$ through the map \ref{Prop:P1}. As a consequence, the set of frustration-free open projections is fully determined by property (F).}  $\Diamond$
\end{remark}

\begin{proposition}
    $\Pp_o^F((\Ss^{\otimes G})^{\ast \ast})$ is dense in $\Pp_o((\Ss^{\otimes G})^{\ast \ast})$ in the norm topology of $\BM(\Hh_u)$.
\end{proposition}

\begin{proof}
    Let $p \in \Pp_o((\Ss^{\otimes G})^{\ast \ast})$ and $\Bb = p (\Ss^{\otimes G}) p \cap \Ss^{\otimes G}$ be the associated hereditary sub-$C^\ast$-algebra. Let $\epsilon_n \to 0$ be a sequence of positive numbers and, for each $\epsilon_n$, we pick a unitary element $u_n \in \Ss^{\otimes G}$ as in \eqref{Prop:BU}. Then $u_n \Bb u_n^\ast$ belong to $\mathfrak H^F(\Ss^{\otimes G})$, hence their corresponding open projections $p_n = u_n p u_n^\ast$ belong to $\Pp_o^F((\Ss^{\otimes G})^{\ast \ast})$. The statement now follows because $u_n \to 1$ in $\Aa$ and, since the latter is isometrically embedded in $\BM(\Hh_u)$, $p_n \to p$ in norm topology of $\BM(\Hh_u)$.
\end{proof}

