\section{Synergy Between  Derivations and States}

The following questions are important for the current programs on classifications of topological phases of quantum spin systems: \begin{enumerate}
    \item[(Q1)] Given a state $\omega$ over a $C^\ast$-algebra, pure or otherwise, is there an inner-limit derivation $\delta$ such that $\omega$ is a gapped state for $\delta$?
    \item[(Q2)] Given an inner-limit derivation $\delta_{\bm h}$ on a $C^\ast$-algebra, can we decide if $\delta_{\bm h}$ has a unique gapped state?
\end{enumerate}

We start addressing Q1, for which we introduce the following concept:

\begin{definition}
   Let $\Aa$ be a unital separable $C^\ast$-algebra and $\omega \in S(\Aa)$ a state. We say that an i.l. derivation $\bm h=\{h_n\}$ is adapted to $\omega$ if each $h_n$ is a positive element from the hereditary $C^\ast$-subalgebra $\Nn_\omega^\ast \cap \Nn_\omega$.
\end{definition}

\begin{remark}\label{Re:HnSpec}
    {\rm The above qualifiers imply that $\omega(h_n)=0$, which can happen only if $\min {\rm Spec}(h_n)=0$. This justifies the choice made in Remark~\ref{Re:ZeroS}.}$\Diamond$
\end{remark}

Such derivations have harmonious relations with their respective states:

\begin{proposition} If $\bm h$ is an i.l. derivation adapted to $\omega \in S(\Aa)$, then:
\begin{enumerate}[{\rm i)}]
   \item $\omega \circ \delta_{\bm h}=0$ on $\Dd_{\bm h}$.  
\item $\omega$ is a ground state for $\delta_{\bm h}$, {\it i.e} $\omega\big(a^\ast \delta_{\bm h}(a)\big)\geq 0$ for all $a\in \Dd_{\bm h}$.
\end{enumerate}
    \end{proposition}

   \begin{definition}
        Let $\bm h =\{h_n\}$ be an i.l. derivation over a separable unital $C^\ast$-algebra $\Aa$. We define 
        \begin{equation}
          w_{\bm h} : =\sum\lambda_n \, h_n \in \Aa, \quad \lambda_n = 2^{-n}/\|h_n\|.
        \end{equation}
        and we let $L_{\bm h} := \overline{\Aa w_{\bm h}}$ be its corresponding left ideal. 
    \end{definition}

    \begin{remark}
        {\rm If $\Aa$ and $\bm h$ are as in Examples~\ref{Ex:SG} and \ref{Ex:DG}, respectively, then each $h_n$ has discrete spectrum and we can equivalently define $w_{\bm h}$ as $\sum 2^{-n}\, p_n$, where $p_n$ is the spectral projection $p_n \in \Aa$ of $h_n$ onto its non-zero spectrum (we recall that ${\rm ker}\, h_n \neq \emptyset$). This will lead to same left ideal $L_{\bm h}$. In fact, this alternative definition is available whenever $0$ is isolated from the rest of the spectrum of each $h_n$.}$\Diamond$
    \end{remark}

    \begin{assumption}\label{Assum:A1}
        {\rm A working assumption of ours is that $L_{\bm h}$ is proper, hence $1 \notin L_{\bm h}$.}
    \end{assumption}

    \begin{proposition}\label{Prop:Adapt}
    If the i.l. derivation $\bm h$ displays property~\ref{Assum:A1}, then it is adapted to at least one $\omega \in PS(\Aa)$.
\end{proposition}

\begin{proof}
    Since $h_n \leq 2^n \|h_n\|\, w_{\bm h}$, each $h_n$ belongs to the hereditary algebra $L_{\bm h}^\ast \cap L_{\bm h}$. According to Th.~5.3.3 in \cite{MurphyBook}, the set 
    \begin{equation}\label{Eq:Rr}
        \Rr= \{\Nn_\omega \, | \, \omega \in PS(\Aa), \ L_{\bm h} \subseteq \Nn_\omega\}
    \end{equation}
   is non-empty and $L_{\bm h} = \cap \, \Rr$. We have
    \begin{equation}
        h_n \in \overline{w_{\bm h} \Aa w_{\bm h}}\subseteq \Nn_\omega^\ast \cap \Nn_\omega, \quad \forall \ \Nn_\omega \in \Rr,
    \end{equation}
    and the statement follows.
\end{proof}

The following statement identifies situations where $\Rr$ from \eqref{Eq:Rr} consists of a single element and where question Q1 has affirmative answer:

\begin{proposition}\label{Prop:Q1}
    Let $\omega$ be a pure state on the separable unital $C^\ast$-algebra $\Aa$, $\{1_n^\omega\}$ an approximate unit for the hereditary algebra $\Nn^\ast_\omega \cap \Nn_\omega$, and $\bm h = \{h_n\}$ an i.l. derivation adapted to $\omega$ and displaying property~\ref{Assum:A1}.
    \begin{enumerate}[{\rm i)}]
        \item If there exists a sequence $\{\gamma_n\}$ of strictly positive numbers such that $h_{n} \geq \gamma_n 1_n^\omega$ for all $n$, then $L_{\bm h} = \Nn_\omega$ and $\Rr$ contains $\Nn_\omega$ as its single element.
        \item Furthermore, if $\gamma := \inf \{\gamma_n\}>0$, then 
    \begin{equation}\label{eq: 13}
        \omega\big (a^\ast \delta_{\bm h}(a) \big) \geq \gamma \, \omega(a^\ast a), \quad \forall \ a \in {\rm ker}\, \omega \cap \Dd_{\bm h}.
    \end{equation}
    \end{enumerate}
\end{proposition}

\begin{proof} i) With the stated assumption, $\Nn_\omega^\ast \cap \Nn_\omega \subseteq L_{\bm h}^\ast \cap L_{\bm h}$, hence $\Nn_\omega \subseteq L_{\bm h}$. In the same time, $\Nn_\omega$ is maximal because $\omega$ is pure. This leaves $\Nn_\omega = L_{\bm h}$ as the only option.

   ii) We have
    \begin{equation}
        \omega\big (a^\ast \delta_{\bm h}(a) \big ) = \lim \, \omega(a^\ast h_{n} a).
    \end{equation}
    For $a$ in ${\rm ker}\, \omega \cap \Dd_{\bm h}$, we have the decomposition 
    \begin{equation}
        a=a_1 + a_2 \in \Nn_\omega^\ast + \Nn_\omega,
    \end{equation} 
and we can continue
    \begin{equation}
        \omega\big (a^\ast \delta_{\bm h}(a) \big ) = \lim \, \omega(a_1^*h_{n} a_1) \geq \gamma \lim \, \omega(a_1^* 1_{n}^\omega a_1 ).
    \end{equation}
 Moreover, one knows
    \begin{equation}
          \lim\|a_1^*-a_1^*1_n^\omega\|^2 =\lim\|(1-1_n^\omega)a_1a_1^*(1-1_n^\omega)\| = 0,   
    \end{equation}
where the last equality uses the fact that $a_1a_1^*\in \Nn_\omega^*\cap \Nn_\omega.$ Therefore, one concludes that
    \begin{equation}
        \lim \, \omega(a_1^* 1_{n}^\omega a_1) = \omega\big ((a_1+a_2)^* (a_1+a_2)=\omega(a^\ast a)\big),
    \end{equation}
    where we could safely take the norm limit $a_1^*1_n^\omega a_1 \to a_1^*a_1$.
\end{proof}

\begin{remark}
    {\rm According to Proposition~\ref{Prop:GDeriv}, $\bm h$ cannot be bounded in the situations of interest to us. In particular, $\bm h$ cannot be a multiple of approximate unit $\{1_n\}$. Often, when a group action is available, the desired $h_n$'s are found in the form $\sum_g \alpha_g(1^\omega_\ell) $, where the sum is over increasing subsets of $G$ and $\ell$ is a fixed integer.}$\Diamond$
\end{remark}

Proposition~\ref{Prop:Q1} provides some guidance when dealing with Q1. It suggests that answers can be found by computing the hereditary subalgebra induced by $\omega$ and by sampling various approximate units.

Pure states and maximal left ideal of unital $C^\ast$-algebras are in a bijective relation (Th.~5.3.5 in \cite{MurphyBook}). Thus, if $\bm h$ is given instead of $\omega$, then the uniqueness part of Q2 can be answered in the affirmative if $L_{\bm h}$ can be shown to be maximal.

\begin{proposition}\label{Prop:Q21}
  Let $\Aa$ and $\bm h$ be as in Examples~\ref{Ex:SG} and \ref{Ex:DG}, respectively, with $\bm h$ displaying property~\ref{Assum:A1}. If ${\rm ker}\, h_n$ are 1-dimensional, then $L_{\bm h}$ is maximal.
\end{proposition}

\begin{proof}
    Consider the left ideals $L_n= \Aa h_n$ associated with the ground states of $h_n$. Then $L_n \subset L_{\bm h}$ for each $n$ and $L_n \cap \Ss_{\Lambda_n}$ are maximal left ideals in $\Ss_{\Lambda_n}$. Assume now a proper closed left ideal $L$ with the property $L_{\bm h} \subseteq L$. Then $L \cap \Ss_{\Lambda_n}$ is a proper left ideal in $\Ss_{\Lambda_n}$ that includes $L_n \cap \Ss_{\Lambda_n}$. Maximality of the latter implies the two are equal. Then
    \begin{equation}
        L=\overline{\cup(L \cap \Ss_{\Lambda_n})} =\overline{\cup \, (L_n \cap \Ss_{\Lambda_n})} \subset \overline{\cup \,  L_n } \subseteq L_{\bm h},
    \end{equation}
    and the statement follows.
\end{proof}

We collect the results of the subsection in:

\begin{theorem}
   Let $\bm h = \{h_n\}$ be an i.l. derivation on a separable unital $C^\ast$-algebra $\Aa$. If $\bm h$ satisfies assumption~\ref{Assum:A1} and ${\rm ker}\, h_n =1$ for all $n$, then $\bm h$ is adapted to one and only one pure state. Furthermore, if $h_n \geq \gamma \, p_n$ for each $n$ and a strictly positive $\gamma$, then this state is a gapped state for $\bm h$.
\end{theorem}



\begin{example}[AKLT model] {\rm Let us consider the one-dimensional chain given by the group $G=\mathbb{Z}$ and the on-site algebra $\mathcal{S}={\rm M}_3(\mathbb{C})$. On $\big({\rm M}_3(\mathbb{C})\big)^{\otimes \mathbb{Z}}$, the AKLT model is described by the local Hamiltonian
\begin{equation}
    H_{[-L,L]}=\sum_{i=-L}^{L-1} \left(\frac{1}{2}{\bf S}_i\cdot {\bf S}_{i+1}+\frac{1}{6}({\bf S}_i\cdot{\bf S}_{i+1})^2+\frac{1}{3}\right),
\end{equation}
where $L\geq 1$ and ${\bf S}_i$ stands for the generator of the spin-$1$ representation of $SU(2)$. It is well-known that this model has a unique gapped ground state in the thermodynamic limit, with exponential decay of correlation given by the correlation length $1/{\rm ln}(3)$. In this example, we shall describe such a state and the associated free sequence of projections.


\medskip  


Let us first notice that the term
\begin{equation}
    {\bf P}_{i,i+1}:=\frac{1}{2}{\bf S}_i\cdot {\bf S}_{i+1}+\frac{1}{6}({\bf S}_i\cdot{\bf S}_{i+1})^2+\frac{1}{3}
\end{equation}
describes a nearest-neighbor interaction. Furthermore,  ${\bf P}_{i,i+1}$ is the orthogonal projection onto the spin $2$ subspace of the product of two spins $1$ located at the sites $i$ and $i+1.$ As a consequence, the local Hamiltonian $H_{[-L,L]}$ is a positive element for any $L\geq 1.$ 
Thus if $\psi_L\in \mathcal{H}_{[-L,L]}$ so that $H_{[-L,L]}\psi_L=0$ then this immediately implies that $\psi_L$ is a ground state for $H_{[-L,L]}.$ 

\medskip

A set of generators for ${\rm Ker}(H_{[-L,L]})$ can be described through the spinless state $\phi\in \mathbb{C}^2\otimes \mathbb{C}^2$ given by
$$\phi:=\frac{1}{\sqrt{2}}\big(|\uparrow\downarrow\rangle-|\downarrow\uparrow\rangle\big)$$
Namely, denote by $D^{(j)}$ the irreducible representation of $\mathfrak{su}(2)$ of spin $j,$ and let $W\colon \mathbb{C}^3\to \mathbb{C}^2\otimes \mathbb{C}^2$ be a intertwiner isometric embedding of $D^{(1)}\subset D^{(1/2)}\otimes D^{(1/2)}.$ For any choice of $|\alpha\rangle$ and $|\beta\rangle$ in $\mathbb{C}^2$ let us define the vector $\psi_{\alpha\beta}^{L}\in \mathcal{H}_{[-L,L]}$ via
\begin{equation}
    \psi_{\alpha\beta}^L:=(W^*)^{\otimes (2L+1)}( \tilde{\psi}_{\alpha\beta}^L)
\end{equation}
where $ \tilde{\psi}_{\alpha\beta}^L:=|\alpha\rangle \otimes \phi^{\otimes 2L}\otimes |\beta\rangle$.
Define by $\mathcal{K}_{L}:={\rm span}\{ \psi_{\alpha\beta}^L\,:\,|\alpha\rangle,|\beta\rangle\in \mathbb{C}^2\}$ and $P_{L}$ the projection onto the orthogonal complement of $\mathcal{K}_{L}$ in $\mathcal{H}_{[-L,L]}.$ Then from the very definition, it follows that  $${\rm dim}(\mathcal{K}_{[-L,L]})={\rm Ker}(P_L)=4,\qquad \forall\,L\geq 1$$ Observe that $\tilde{\psi}_{\alpha\beta}^L$ has spin at most $2$ since the only non-trivial contribution is coming from $\alpha$ and $\beta$. Thus the spin of $\psi_{\alpha\beta}^L$ cannot exceed  $1$ by the properties of the intertwiner $W$. To sum up, ${\bf P}_{i,i+1}\psi_{\alpha\beta}^L=0$ and inductive argument verify that ${\rm Ker}(H_{[-L,L]})=\mathcal{K}_{L}$ for all $L$. 

\medskip

It should be mentioned that the sequence of  subspaces $\{ \mathcal{K}_L\}_{L\geq 1}$ satisfy the following intersection property
$$\mathcal{K}_{L+1}=\big(\mathbb{C}^3\otimes \mathcal{K}_L\otimes \mathbb{C}^3\big)\,\cap\, \big(\mathcal{K}_L\otimes (\mathbb{C}^3)^{\otimes 2}\big)\,\cap\, \big((\mathbb{C}^3)^{\otimes 2}\otimes \mathcal{K}_L\big)$$
 The latter equality can be obtained by noticing that $\tilde{\psi}_{\alpha\beta}^{L+1}=|\alpha\rangle \otimes \phi\otimes \phi^{\otimes 2L}\otimes \phi\otimes |\beta\rangle$ and decomposing the first or last occurrence (or both) of $\phi$ that appears in the latter tensor product in terms of the base $|1\rangle\equiv |\uparrow\rangle$ and $|2\rangle\equiv |\downarrow\rangle$ of $\mathbb{C}^2$. Indeed, one has the relations
$$\tilde{\psi}_{\alpha\beta}^{L+1}=\frac{1}{\sqrt{2}}|\alpha\rangle \otimes \phi\otimes\big(|1\rangle \otimes \tilde{\psi}_{2\beta}^L-|2\rangle \otimes \tilde{\psi}_{1\beta}^L\big)$$
$$\tilde{\psi}_{\alpha\beta}^{L+1}=\frac{1}{\sqrt{2}}\big(\tilde{\psi}_{\alpha 1}^L\otimes |2\rangle-\tilde{\psi}_{\alpha 2}^L\otimes |1\rangle\big)\otimes\phi\otimes |\beta\rangle$$

\begin{equation*}
    \begin{split}
\tilde{\psi}_{\alpha\beta}^{L+1}=\frac{1}{2}|\alpha\rangle\otimes \tilde{\phi}\otimes |\beta\rangle
    \end{split}
\end{equation*}
where $\tilde{\phi}=|1\rangle\otimes\tilde{\psi}_{21}^L\otimes 2-|1\rangle \otimes \tilde{\psi}_{22}^L\otimes |1\rangle-|2\rangle \otimes \tilde{\psi}_{11}^L\otimes |2\rangle-|2\rangle \otimes \tilde{\psi}_{12}^L\otimes |1\rangle$. This checks that $\psi_{\alpha\beta}^{L+1}$ lies in the intersection. 

 Once the equality between the kernels is verified one concludes that the sequence of projections $\{ P_L\}_{L\geq 1}$ is a free sequence, in the sense that  for $L\leq L'$
$$P_LP_{L'}=P_{L'}P_L=P_{L'}$$


Finally, the unique gapped ground state of the thermodynamic limit of $H_{[-L,L]}$ is provided by 
$$\omega(A)=\lim_{L\to \infty}\frac{1}{\|\psi_{\alpha\beta}^L\| ^{2}}\langle A\psi_{\alpha\beta}^L,\psi_{\alpha\beta}^L\rangle=\lim_{L\to \infty}\frac{1}{4}{\rm Tr}(P_L^\bot AP_L^\bot)$$
which is known to be independent of $\alpha$ and $\beta$.}

\end{example}




\section{High throughput of gapped states and Hamiltonians}

The following statement gives us the means to produce a high throughput of gapped states and gapped interactions:

\begin{proposition}
    Let $\Aa$ be a separable AF-algebra with a free action $\alpha$ of a finitely generated infinite group $G$. Let $q$ be a positive element from one of the finite dimensional subalgebras of $\Aa$ and consider 
    \begin{equation}
        h_n(q):= \sum_{d(e,g)\leq n}\alpha_g(q), \quad n\in \NM^\times,
    \end{equation}
    where $d$ is a $G$-invariant distance on the standard Cayley graph of $G$. If $\omega$ is a state as in Proposition~\ref{Prop:Adapt} that happens to be pure, then $\omega$ is a gapped state for $\bm h$, provided the first non-zero eigenvalue of $\alpha_g(p)+\alpha_{g'}(p)$ is closed enough to 1, for each pair $g,g' \in G$. Here, $p$ is the supporting projection of $q$.
\end{proposition}

\begin{remark}
    {\rm The condition that assures the existence of the gap can be checked by a finite number of calculations, see the proof below.}$\Diamond$
\end{remark}

\begin{proof}
    Since the action is free, there exists a finite number $N$ such that $\alpha_g(q)$ and $\alpha_{g'}(q)$ commute whenever $d(g,g') > N$. We replace $q$ by its supporting projection $p$ and observe that
    \begin{equation}\label{Eq:H2}
    \begin{aligned}
        h_n(p)^2  = & h_n(p) +\sum_{d(g,g')> N}\alpha_g(p)\, \alpha_{g'}(p)\\
        & \qquad \qquad  \qquad +\tfrac{1}{2}\sum_{0<d(g,g')\leq N}\big(\alpha_g(p)\, \alpha_{g'}(p) +\alpha_{g'}(p) \alpha_g(p)\big ).
        \end{aligned}
    \end{equation}
    \red{is there a factor of $2$ in the third term of the r.h.s.?}
    The second term of the right side of \eqref{Eq:H2} is a sum of projections, hence a positive element. For the last sum, we observe that
    \begin{equation}
       \alpha_g(p)\, \alpha_{g'}(p) +\alpha_{g'}(p) \alpha_g(p)=X(g,g')^2-X(g,g'),  
    \end{equation}
    with
    \begin{equation}
        X(g,g')=\alpha_g(p)+ \alpha_{g'}(p).
    \end{equation}
  All these elements have discrete spectra, hence we can define 
    \begin{equation}
\lambda=\min\Big (\bigcup_{0<d(e,g)\leq N} \, {\rm Spec}(X(e,g)) \setminus \{0\}\Big ),
    \end{equation}
   which is a strictly positive number, whose evaluation requires a finite number of calculations. Then
   \begin{equation}
       X(g,g')^2-\lambda X(g,g')=\alpha_{g} \big (X(e,g^{-1}g')^2-\lambda X(e,g^{-1}g')\big)\geq 0,
   \end{equation}
   for all $g,g'\in G$ with $0<d(g,g')\leq N$. As a consequence, for all such pairs of $g,g'\in G$,
   \begin{equation}
       X(g,g')^2-X(g,g') \geq -(1-\lambda) X(g,g')
   \end{equation}
   and, as such, 
   \begin{equation}
    \begin{aligned}
        h_n(p)^2  \geq & \big(1-|B_N\setminus \{e\}|(1-\lambda)\big) h_n(p),
        \end{aligned}
        \end{equation}
where $B_N$ is the ball of radius $N$ on the Cayley graph of $G$. If $\lambda$ is closed enough to 1 \red{and $\lambda \leq 1$}, then the constant 
\begin{equation}
    \gamma : = 1-|B_N\setminus \{e\}|(1-\lambda)
\end{equation}
 is positive, which automatically implies $h_n\geq \gamma\,  p_n$, where $p_n$ is the supporting projection of $h_n(p)$.
\end{proof}

\section{MPS Machinery}

   We use Lemma~6.2 in \cite{FannesCMP1992} to prove that there are many interactions for which $\gamma$ is a strictly positive constant. 

   Let $M_s$ denote the algebra of $s \times s$ complex matrices. We fix $k \in \NM^\times$ and $\rho \in M_k$.

   \begin{proposition}
       Let $\{v_\mu\}_{\mu=1}^d$ be a collection of $k \times k$ matrices such that 
       \begin{equation}
    \sum_\mu v_\mu v_\mu^\ast = 1_k, \quad \sum_\mu v_\mu^\ast \rho v_\mu = \rho
    \end{equation}
    and the linear map 
       \begin{equation}
           M_k \ni B \mapsto \sum_\mu v_\mu B v_\mu^\ast \in M_k
