\title{\sc{radiation-reaction on the straight-line motion of a point charge accelerated by 
a constant applied electric field in an electromagnetic
 \sc{b}{\tiny\sc{opp}}-\sc{l}{\tiny\sc{and\'e}}-\sc{t}{\tiny\sc{homas}}-\sc{p}{\tiny\sc{odolsky}} vacuum}\vspace{-0.5truecm}}
%
\author{\textbf{Ryan J. McGuigan$^1$ and Michael K.-H. Kiessling$^2$}\\
\small           $^1$ Department of Physics, \\
