%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     \section{\hspace{-10pt}Initial value problem for fields and point charge} %\vspace{-10pt}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 

 The electromagnetic vacuum in BLTP electrodynamics is defined by the two equations
\begin{alignat}{1}
        \HV(t,\sV)  
& = \label{eq:BLTPlawBandH}
       \left(1  + \varkappa^{-2}\square\,\right) \BV(t,\sV) \, , \\ 
        \DV(t,\sV) 
& =
        \left(1  + \varkappa^{-2}\square\,\right) \EV(t,\sV) \, ;
\label{eq:BLTPlawEandD}
\end{alignat}
in \refeq{eq:BLTPlawBandH} and \refeq{eq:BLTPlawEandD}, the parameter $\varkappa^{-1}$ is the ``Bopp length'' \cite{BoppA,BoppB},
and $\square \equiv c^{-2}\partial_t^2 -\Delta$ is the d'Alembertian, with $c$ the vacuum speed of light.
 The evaluations $\HV(t,\sV)$, $\BV(t,\sV)$, $\EV(t,\sV)$, and $\DV(t,\sV)$ of the fields at the space point
$\sV\in\Rset^3$ and instant of time $t\in\Rset$ are defined in any convenient flat foliation of Minkowski spacetime 
into space \&\ time. 
 These fields satisfy the familiar system of pre-metric Maxwell field equations, which consist of two evolution equations
\begin{alignat}{1}
\textstyle
\pddt{\BV(t,\sV)}
&= \label{eq:MdotB}
        - c \nab\crprd\EV(t,\sV) \, ,
\\
\textstyle
\pddt{\DV(t,\sV)}
&= 
        + c\nab\crprd\HV(t,\sV)  - 4\pi \ee \delta_{\qV(t)}(\sV){\vV}(t)\, ,
\label{eq:MdotD}
\end{alignat}
and two constraint equations
\begin{alignat}{1}
        \nab\cdot \BV(t,\sV)  
&= \label{eq:MdivB}
        0\, ,
\\
        \nab\cdot\DV(t,\sV)  
&=
        4 \pi \ee \delta_{\qV(t)}(\sV)\, .
\label{eq:MdivD}
\end{alignat}
 Here,  $\ee (>0)$ is the elementary electric charge,
$\qV(t)\in\Rset^3$ its position and $\vV(t) \in\Rset^3$ its velocity at time $t$.


  The particle's velocity is defined as usual to be the time-derivative of its position vector,
\begin{equation}
\Ddt \qV(t)
= : \label{eq:dotQisV}
\vV(t).
\end{equation}
   In the relativistic generalization of Newton's point mechanics by Einstein, Lorentz, and Poincar\'e, 
the velocity $\vV(t)$, in turn, changes with time according to
\begin{equation}
\Ddt   \frac{\vV(t)}{\sqrt{1 - \frac{1}{c^2}|{\vV}(t)|^2}}
= \label{eq:EinsteinNewtonEQofMOT}
\frac{1}{\mbare}\fV(t);
\end{equation}
here, $\mbare \neq 0$ is the \emph{bare inertial rest mass} of the particle, 
and $\fV(t)$ is the total electromagnetic force acting on it.
 Following Poincar\'e (cf. \cite{MillerBOOK}) we~define~it~as  (cf. \cite{KiePRD})
\begin{equation}
\fV(t) := \label{eq:POINCAREforce}
\eEL\,\EV^{\mbox{\tiny{hom}}}
 - \Ddt \int_{\Rset^3} \PiV^{\mbox{\tiny{field}}}(t,\sV) \drm^3s,
\end{equation}
where  $\EV^{\mbox{\tiny{hom}}}$ is a constant applied electric field (an idealization of the field between the plates of a 
capacitor), and $\PiV^{\mbox{\tiny{field}}}(t,\sV)$ is the momentum vector-density of the Maxwell-BLTP fields 
\begin{equation}
\textstyle
4\pi c \PiV^{\mbox{\tiny{field}}}
= \label{eq:PiMBLTP}
\DV\crprd\BV + \EV\crprd\HV - \EV\crprd\BV 
- \varkappa^{-2} \big(\nabla\cdot\EV\big)\Big(\nabla\crprd\BV - \frac{1}{c}\pddt\EV\Big).
\end{equation}

 As announced in \cite{KiePRD} and shown in \cite{KTZonBLTP}, BLTP electrodynamics is well-posed as a joint
initial value problem for the fields and the point charge, requiring initial data 
$\BV(0,\sV)$, $\DV(0,\sV)$, $\EV(0,\sV)$, $(\pddt\EV)(0,\sV)$ for the fields, and $\qV(0)$ and $\vV(0)$ for
the particle. 
 The data for $\BV$ and $\DV$ are constrained by the divergence equations, and  $\vV(0)$ by $|\vV(0)|<c$.

 For a charged particle released from rest in 
the constant applied electric field $\EV^{\mbox{\tiny{hom}}}$,
the initial data are
\begin{equation}
\qV(0)=\NullV
\qquad \mbox{and} \qquad
\vV(0)=\NullV.
\end{equation}
 The initial fields are the sum of the external constant electric field and the electrostatic field of the point charge,
thus we have
\begin{equation}\label{Dinit}
\DV(0,\sV)\equiv \EV^{\mbox{\tiny{hom}}} +\ee \frac{\sV}{|\sV|^3}
\end{equation}
and
\begin{equation}\label{Einit}
\EV(0,\sV)
\equiv \EV^{\mbox{\tiny{hom}}} + \ee \frac{1 - (1+\varkappa |\sV|)e^{-\varkappa |\sV|}}{|\sV|^2}\frac{\sV}{|\sV|},
\end{equation}
\textcolor{black}{in addition to the initial conditions}
 $\big(\partial_t \EV\big)(0,\sV)\equiv \NullV$, as well as $\BV(0,\sV) \equiv \NullV$. 


