     \section{Reduction to a Volterra integral equation for the particle acceleration} %\vspace{-10pt}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 

 For the initial data of our problem the electromagnetic fields outside the forward light cone of 
the initial location of the particle remain precisely the electrostatic fields, i.e., the magnetic field $\HV$ 
and the magnetic induction field $\BV$ vanish, while the electric displacement field $\DV(t,\sV)$ is given by \refeq{Dinit}
and the electric field $\EV(t,\sV)$ is given by \refeq{Einit}, for all $t\geq 0$.

 Inside the forward light cone of the initial particle location, 
%but away from the particle position at $t$,
\textcolor{black}{but excluding the world line of the particle itself,}
the fields $\DV(t,\sV)$ and $\HV(t,\sV)$ are for all $t\geq 0$ given by
$\DV = \EV^{\mbox{\tiny{hom}}} + \DLWr$ \&\ $\HV =\HLWr$, with 
(the acceleration vector of the point charge is highlighted in {\color{red}red})
\begin{alignat}{1}
\hskip-.6truecm
{\DLWr(t,\sV)} &=\label{eq:LWsolD}
  \ee \frac{c^2-|\vV|^2}{|\sV-\qV|^2} 
\frac{{c\nV(\qV,\sV)}_{\phantom{!\!}}-{\vV}}{\bigl(\textstyle{c-\nV(\qV,\sV)\cdot {\vV}}\bigr)^{\!3}} 
\Biggl.\Biggr|^{\mathrm{ret}}
+\ee 
\frac{\nV(\qV,\sV)\crprd
\bigl[\bigl(c\nV(\qV,\sV)_{\phantom{!\!}}-{\vV}\bigr)\crprd{\color{red}\aV}\bigr]}{{|\sV-\qV|}
\bigl(\textstyle{c-\nV(\qV,\sV)\cdot {\vV}}\bigr)^{\!3}}
\Biggl.\Biggr|^{\mathrm{ret}},\hskip-1truecm
\\
\hskip-1truecm
{\HLWr(t,\sV)} 
&= \label{eq:LWsolH}
        \nV(\qV,\sV)|^{_{\mathrm{ret}}}\crprd {\DLWr(t,\sV)}
\, \vspace{-10pt}
\end{alignat}
the retarded Li\'enard--Wiechert fields \cite{JacksonBOOKb}. 
 Here, $\nV(\qV,\sV) = \frac{\sV-\qV}{|\sV-\qV|}$ is a \emph{normalized} vector from $\qV$ to $\sV$, and
\textcolor{black}{the notation ``$|^{\mathrm{ret}}$'' means that the quantities $\qV$ and $\vV$ and ${\color{red}\aV}$ 
to the left of ``$|^{\mathrm{ret}}$'' are to be evaluated at the retarded time $t^{\mathrm{ret}}$, 
with $t^{\mathrm{ret}}(t,\sV)$ being defined implicitly by $c(t-t^{\mathrm{ret}}) = |\sV-\qV(t^{\mathrm{ret}})|$;
thus, for instance, 
$(\qV,\vV,{\color{red}\aV})|^{\mathrm{ret}}= (\qV(t^{\mathrm{ret}}),\vV(t^{\mathrm{ret}}),{\color{red}\aV}(t^{\mathrm{ret}}))$.
 Inside the initial forward light cone, $0< t^{\mathrm{ret}} <t$.
The terms $\propto{\color{red}\aV}$ in (\ref{eq:LWsolD}) and (\ref{eq:LWsolH}) account for radiation emitted into the 
far-field $(|\sV|\gg |\qV|$).}

 Note that the electromagnetic Li\'enard--Wiechert fields $\HLWr$ and $\DLWr$ exhibit both
a $\propto 1/r^2$ singularity and a $\propto 1/r$ singularity, where $r$ denotes $|\sV-\qV(t)|$; they each
have a directional singularity at the location of the  point charge source, too.

\textcolor{black}{Analogously the fields $\BV$ and $\EV$ for a moving point charge can be expressed \cite{KiePRD}; cf. \cite{Lazar}.
 Inside and on} the forward light cone of the initial particle location, 
\textcolor{black}{but excluding the world line of the particle itself,}
 % away from the particle position at $t$,
the MBLTP field solutions $\BV(t,\sV)$ and $\EV(t,\sV)$ for $t\geq 0$ are given by 
$\BV=\BV_0+ \BV_1$ and $\EV = \EV_0 + \EV_1$, 
with $\BV_0\equiv\NullV$ and $\EV_0\equiv \EV^{\mbox{\tiny{hom}}}$, and
(see \cite{KiePRD})
\begin{alignat}{1}
\hspace{-20pt}
{\EV_1(t,\sV)} =\; \nonumber
 & \ee \varkappa^2\Bigl(\frac{1 - (1+\varkappa |\sV|)e^{-\varkappa |\sV|}}{\varkappa^2|\sV|^2} -\tfrac12 \Bigr)\frac{\sV}{|\sV|} + 
\ee \varkappa^2 \int_{0}^{ct-|\sV|}
\tfrac{J_2\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV|^2}\bigr)}{{c^2(t-t')^2-|\sV|^2}^{\phantom{n}} }
 \sV \drm{(ct')} +
\\  \label{eq:EjsolMBLTP} 
 & \ee \varkappa^2\tfrac12\tfrac{\nV(\qV^{},\sV)-{\vV^{}}/{c}}{1-\nV(\qV^{},\sV)\cdot{\vV}/{c}}
\Big|^{\mathrm{ret}} \, - \\ \nonumber
 &
\ee \varkappa^2 \int_{0}^{t^\mathrm{ret}(t,\sV)}
\tfrac{J_2\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2}\bigr)}{{c^2(t-t')^2-|\sV-\qV(t')|^2}^{\phantom{n}} }
\left(\sV-\qV^{}(t') - \vV^{}(t')(t-t')\right)c\drm{t'} , \\ 
\hspace{-20pt}
{\BV_1(t,\sV)} =\; \label{eq:BjsolMBLTP}
&\ee \varkappa^2 \tfrac{1}{2} 
\tfrac{{\color{black}\vV^{}\crprd\nV(\qV^{},\sV)/c}}{1-\nV(\qV^{},\sV)\cdot{\vV}/{c}}
\Big|^{\mathrm{ret}}
\, -  \\ \nonumber
 &
 \ee \varkappa^2 \int_{0}^{t^\mathrm{ret}(t,\sV)}
\tfrac{J_2\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2 }\bigr)}{{c^2(t-t')^2-|\sV-\qV(t')|^2}^{\phantom{n}} }
{\vV^{}(t')}\crprd \left(\sV-\qV^{}(t') 
\right)\drm{t'} .
\end{alignat}
 The fields $\BV(t,\sV)$ and $\EV(t,\sV)$ 
are globally bounded in $\sV$ for each $t$, and away from the point charge they are Lipschitz-continuous in $\sV$, including
across the initial forward light cone. 

 Similarly (see \cite{CarKie}),
\begin{alignat}{1}
\qquad\qquad\nabla\cdot\EV(t,\sV) =\; \nonumber
 & \ee \varkappa^2 \frac{e^{-\varkappa |\sV|} - 1}{|\sV|}
+ 
\ee \varkappa^3 \int_{0}^{ct-|\sV|}
\tfrac{J_1\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV|^2}\bigr)}{\sqrt{c^2(t-t')^2-|\sV|^2}^{\phantom{n}} }
 \drm{(ct')} +
\\  \label{eq:LWsolPHI}
& \ee^{}\varkappa^2 
\tfrac{1}{\bigl(1-\nV(\qV,\sV)\cdot {\vV^{}}/{c}\bigr)}
\tfrac{1}{|\sV-\qV|}
\Bigl.\Bigr|^{\mathrm{ret}}
- \\ \nonumber
&
\ee^{} \varkappa^3 \int_{0}^{t^\mathrm{ret}(t,\sV)}
\tfrac{J_1\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2}\bigr)}{\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2}^{\phantom{n}} }
c \drm{t'} ,
\end{alignat}
and
\begin{alignat}{1}
\big(\nabla\crprd\BV - {\textstyle{\frac{1}{c}\pddt}}\EV\big)(t,\sV) 
=\; \label{eq:LWsolA}
& \ee^{}\varkappa^2\tfrac{1}{\bigl(1-\nV(\qV,\sV)\cdot {\vV^{}}/{c}\bigr)}
\tfrac{1}{|\sV-\qV|}\tfrac{\vV^{}}{c}
\Bigl.\Bigr|^{\mathrm{ret}}
- \\ \nonumber
 & \ee^{} \varkappa^3  \int_{0}^{t^\mathrm{ret}(t,\sV)} 
\tfrac{J_1\!\bigl(\varkappa\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2}\bigr)}{\sqrt{c^2(t-t')^2-|\sV-\qV(t')|^2}^{\phantom{n}} }
\vV^{}(t')\drm{t'} .
\end{alignat}


 With the help of the solution formulas for the fields, given the motions, 
the electromagnetic force of the MBLTP field on its point charge source can be expressed as a functional over
the maps $t\mapsto (\qV(t),\vV(t),{\color{red}\aV}(t))$.
 Namely, since each electromagnetic field component is the sum of a vacuum field and a sourced field, the bilinear 
$\PiV^{\mbox{\tiny{field}}}$ decomposes into a sum of three types of terms: the vacuum-vacuum terms, the source-source 
terms, and the mixed vacuum-source terms.
 In our problem the vacuum field is $\EV^{\mbox{\tiny{hom}}}$; it does not contribute to $\PiV^{\mbox{\tiny{field}}}$,
but appears separately at rhs\refeq{eq:POINCAREforce}.
 As explained in \cite{KiePRD}, this term is not put in by hand but is a contribution to the momentum 
balance due to a surface integral at ``$|\sV|=\infty$.''
 Hence the only contribution to rhs\refeq{eq:POINCAREforce} from $\PiV^{\mbox{\tiny{field}}}$ is the 
source-source contribution, a self-field force in BLTP electrodynamics. 
 Thus, \refeq{eq:POINCAREforce} is given by 
\begin{equation}\label{eq:totalF}
\fV(t) 
=
 \ee \EV^{\mbox{\tiny{hom}}}
+
\fV^{\mbox{\tiny{self}}}[\qV,\vV;{\color{red}\aV}](t),
\end{equation} 
where $\ee \EV^{\mbox{\tiny{hom}}}$ is the Lorentz force 
evaluated with the vacuum field (i.e., a ``test particle contribution'' to the total force), and
(after taking advantage of hyperbolicity; cf. \cite{KiePRD})
\begin{alignat}{2}\label{eq:selfFa}
\hspace{-20pt}
\fV^{\mbox{\tiny{self}}}[\qV,\vV;{\color{red}\aV}](t)
 \equiv &  - \frac{\drm}{\drm{t}} \displaystyle\int_{B_{ct}(\qV_0)}
\Bigl( \PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}(t,\sV) - 
\PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}(0,\sV-\qV_0-\vV_{\!0}t)\Bigr) d^3{s}  \\
 =& - \frac{\drm}{\drm{t}} \displaystyle\int_{B_{ct}(\qV_0)}
 \PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}(t,\sV)  d^3{s}  ,\label{selfFb}
\end{alignat}
with $\PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}$ given by \refeq{eq:PiMBLTP} 
with $(\BV,\DV-\EV^{\mbox{\tiny{hom}}},\EV-\EV^{\mbox{\tiny{hom}}},\HV)$ in place of $(\BV,\DV,\EV,\HV)$.
 To go from \refeq{eq:selfFa} to 
 \refeq{selfFb} we made use of the initial data $\qV_0=\NullV$ and $\vV_0=\NullV$, and 
$\PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}(0,\sV)\equiv \NullV$.

 The following merits emphasis: The r.h.s.(\ref{selfFb}) contains the acceleration ${\color{red}\aV}$ only linearly 
through the contributions $\propto \DV$ and $\propto \HV$ in  $\PiV^{\mbox{\tiny{field}}}_{\mbox{\tiny{source}}}$ 
given by \refeq{eq:PiMBLTP} 
with $(\BV,\DV-\EV^{\mbox{\tiny{hom}}},\EV-\EV^{\mbox{\tiny{hom}}},\HV)$ in place of $(\BV,\DV,\EV,\HV)$.
 Therefore the equation of motion for the point charge can be viewed as 
a linear Volterra integral equation for $t\mapsto{\color{red}\aV}(t)$, given $t\mapsto\qV(t)$ and $t\mapsto\vV(t)$ (even without
demanding that $\vV(t) =\dot\qV(t)$), viz.
\begin{equation}\label{Volterra}
\forall t:\ 
{\color{red}\aV}(t)= W[\vV]\cdot\left(\eEL \EV^{\mbox{\tiny{hom}}}+\fV^{\mbox{\tiny{self}}}[\qV,\vV;{\color{red}\aV}]\right)(t).
\end{equation}
 Here,
\begin{equation}
 W[\vV]
:= \label{eq:FtoAmapINv}
\textstyle
\frac{1}{\mbare}\sqrt{1-\frac{|\vV|^2}{c^2}}
\left[\ID - \frac{1}{c^2}\vV\otimes \vV\right],
\end{equation}
which for motion along $\EV^{\mbox{\tiny{hom}}}$ simplifies to
\begin{equation}
 W[\vV]
:= \label{eq:FtoAmapINvAGAIN}
\textstyle
\frac{1}{\mbare}\left(1-\frac{|\vV|^2}{c^2}\right)^{3/2}\ID .
\end{equation}
 In \cite{KTZonBLTP} we show that the Volterra equation can be uniquely solved to yield ${\color{red}\aV}$ as a nonlinear
functional of (a priori unrelated) curves $t\mapsto\qV(t)$ and $t\mapsto\vV(t)$. 
 Finally setting $\vV(t) = \dot\qV(t)$ and ${\color{red}\aV}(t) = \ddot\qV(t)$, 
 the solution to the Volterra integral equation poses a second-order differential equation 
initial value problem for $\qV(t)$ without the infamous $\dddot\qV(t)$ term of the Abraham--Lorentz--Dirac equation.

 To compute $\vV(t)$ and $\qV(t)$, 
the integral at r.h.s.(\ref{selfFb}) will be rewritten with the help of retarded spherical coordinates (see our Appendix),
then expanded in powers of $\varkappa$, and then all terms up to $O(\varkappa^4)$ included will be evaluated in terms of 
$\qV(t)$, $\vV(t)$, and in terms of integrals over time involving $t\mapsto\qV(t)$, $t\mapsto\vV(t)$, and 
$t\mapsto{\color{red}\aV}(t)$. 
 While these evaluations are daunting, the eventual outcomes up to order $\varkappa^3$ included are surprisingly simple;
see \cite{CarKie}. 
 Our new contribution, the $O(\varkappa^4)$ term, is much more complicated, yet readily amenable to numerical treatment on a 
computer.
\vspace{-0.5truecm}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                \section{Small-$\varkappa$ expansion of the Volterra equation}\label{sec:MBLTPkappaSMALL}\vspace{-0.2truecm}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 The formal power series expansion about $\varkappa=0$ of  $\fV^{\mbox{\tiny{self}}}$ is
 $\fV^{\mbox{\tiny{self}}}[\qV,\vV;{\color{red}\aV}](t) = \sum\limits_{n=0}^\infty \FV^{(n)}_0[\qV,\vV;{\color{red}\aV}](t)$,
where $\FV^{(n)}_0 \propto \varkappa^n$;
 the subscript ${}_0$ at $\FV^{(n)}_0$ indicates that we are expanding about $\varkappa=0$. 
 It is manifest that the terms $O(\varkappa^0)$ and $O(\varkappa^1)$ vanish identically, so we need to discuss terms
$O(\varkappa^n)$ for $n\geq 2$.
 Several of the spherical integrations can been carried out explicitly in terms of well-known functions.
 In particular, the contributions $\FV^{(2)}_0$, $\FV^{(3)}_0$, and $\FV^{(4)}_0$ can be computed explicitly
as expressions in $\qV$ and $\vV$ at time $t$, and time integrals over algebraic expressions of $\qV$ and $\vV$ and
${\color{red}\aV}$. 
 Remarkably, the integrations involving ${\color{red}\aV}$ can be carried out and reduced to 
time integrals over algebraic expressions of only $\qV$ and $\vV$. 

 In the ensuing subsections \ref{sec:MBLTPkappaSQR}, \ref{sec:MBLTPkappaTHREE}, and \ref{sec:MBLTPkappaFOUR}
 we will temporarily suppress the argument $[\qV,\vV;{\color{red}\aV}]$ from the $\FV^{(k)}$.\vspace{-0.5truecm}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                \subsection{The self-force at $O(\varkappa^2)$}\label{sec:MBLTPkappaSQR} \vspace{-7pt}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 The $O(\varkappa^2)$ contribution to the self-force has been computed in \cite{CarKie}
(see also the erratum in \cite{KiePRD}), and it turns out to be
\begin{alignat}{1}
 \FV^{(2)}_0(t) = \label{eq:SELFforceATorderTWOmerged}
 \, \NullV.
\end{alignat}
 In this problem of straight line motion in a constant external electric field, with the particle starting from rest,
the BLTP radiation-reaction force \emph{vanishes identically} at $O(\varkappa^2)$.
\vspace{-0.5truecm}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                \subsection{The self-force at $O(\varkappa^3)$}\label{sec:MBLTPkappaTHREE} \vspace{-7pt}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 The $O(\varkappa^3)$ contribution to the radiation-reaction force for small $\varkappa$ has been computed in \cite{CarKie}.
 It reads
\begin{alignat}{1}
\label{eq:F3}
 \FV^{(3)}_0(t) = 
  - \frac13   \varkappa^3 \eEL^2\qV(t) .
\end{alignat}

 This is a very surprising result: the $O(\varkappa^3)$ term of the radiation-reaction force in our initial value problem 
is a harmonic oscillator force!
 This result relies on the particular setup of the initial data and the geometry of the problem, but not more. 
\vspace{-0.5truecm}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
                \subsection{The self-force at $O(\varkappa^4)$}\label{sec:MBLTPkappaFOUR}\vspace{-7pt}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 The $O(\varkappa^4)$ contribution to the radiation-reaction force for small $\varkappa$ is computed in this paper. % our Appendix.
 Defining the unit vector $\be$ as $\EV^{\mbox{\tiny{hom}}}=: |\EV^{\mbox{\tiny{hom}}}|\be$, and 
setting $\beta(t) :=\frac1c\vV(t)\cdot\be$, it reads
\begin{equation}
\label{eq:F4}
\hspace{-10pt}
\FV^{(4)}_0(t)=
\frac{1}{4}\varkappa^4 e^{2}
\Bigg[5\!\int_{0}^{t}\qV(t^{r} )c\drm{t}^{r} 
-
2 \be  
\!\int_{0}^{t}\int_{0}^{t^r}\!\!
\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\rt)\!(\tilde{t})\,
c^2\drm\tilde{t}
\drm{t}^{r}
\Bigg],
\end{equation}
where in the double integral the $\tilde{t}$ integration has to be carried out first.
\textcolor{black}{As mentioned in the introduction, the technical details for obtaining this result are supplied in the appendix.}
\vspace{-0.5truecm}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Integro-differential equation for the particle position to $O(\varkappa^4)$ included, and numerical solutions}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\vspace{-0.2truecm}

 When all ${\color{red}\aV}$ terms up to $O(\varkappa^4)$ included are
converted through time-integration into expressions that involve only $\qV$
and $\vV$, the Volterra equation for ${\color{red}\aV}$ becomes an integro-differential equation for $\qV$ of
second order.
 Writing now $\FV^{(k)}_0[\qV,\vV](t)$ instead of $\FV^{(k)}_0[\qV,\vV;{\color{red}\aV}]$ 
to highlight this elimination of ${\color{red}\aV}$ in favor of $\qV$ and $\vV$
in the self-force terms, the integro-differential equation for $\qV(t)$ reads 
\begin{equation}\label{VolterraATorderFOUR}
\ddot\qV(t)= 
\textstyle
\frac{1}{\mbare}\bigl(1-\frac{1}{c^2}|\vV(t)|^2\bigr)^{\frac32}\left(\eEL \EV^{\mbox{\tiny{hom}}} 
+ \FV^{(3)}_0[\qV,\vV](t)
+ \FV^{(4)}_0[\qV,\vV](t)
\right),
\end{equation}
with $\FV^{(3)}_0[\qV,\vV]$ and $\FV^{(4)}_0[\qV,\vV](t)$ given by r.h.s.(\ref{eq:F3}) and r.h.s.(\ref{eq:F4}), 
respectively.

 This equation is converted into a system of first-order differential equations by defining the 
variables $q(t):=\be\cdot\qV(t)$, $v(t):=\be\cdot\vV(t)$, 
$ X(t) := \be\cdot \int_{0}^{t}\qV(t^{r} )c dt^{r}$, 
$Y(t):= \int_{0}^{t} Z(\hat{t})c d\hat{t}$, and 
$Z(t):= \int_{0}^{t}\!\!
\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)\!(\tilde{t})cd\tilde{t}$, and
using that $\dot{q}(t) = v(t)$.
 This equivalent first order ODE system thus reads
\begin{align}
\dot{q}(t) & = v(t),\\
\dot{v}(t) & = \frac{1}{\mbare}\left(1-\beta(t)^2\right)^{\frac32}\left(\eEL |\EV^{\mbox{\tiny{hom}}}|
 -\frac13  \varkappa^3 \eEL^2 q(t) \right) + 
\frac{1}{4}\varkappa^4 e^{2}
\Big(5 X(t) - 2 Y(t)\Big)\!,
\\
\dot{X}(t) & = cq(t),\\
\dot{Y}(t) & = cZ(t),\\
\dot{Z}(t) & = 
c\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)\!\!(t),
\end{align}
with $\beta(t) = \frac1c \vV(t)\cdot\be$ as defined earlier.
 We need to supplement this ODE system with vanishing initial data for $X(t)$, $Y(t)$, $Z(t)$, and also for $q(t)$ and $v(t)$.

 Incidentally, if we drop all $O(\varkappa^4)$ terms we obtain the $O(\varkappa^3)$ approximation discussed in 
\cite{CarKie}.
 For positive $\mbare$ it is equivalent to the problem of special-relativistic test particle motion in a 
harmonic oscillator potential, but featuring anharmonic time-periodic solutions due to the relativistic mass change.
  For negative $\mbare$ it is equivalent to the problem of special-relativistic positive mass test particle motion in a 
``harmonic repeller'' potential, featuring run-away solutions whose speed monotonically approaches the speed of light.
 In either case the motions conserve the effective total particle energy 
\begin{equation}\label{EFFECTIVEenergy}
% U = \sqrt{\mbare^2 c^4 + |\pV|^2 c^2} - \eEL  \EV^{\mbox{\tiny{hom}}}\cdot\qV  +\tfrac16  \eEL^2 \varkappa^3|\qV|^2. % mb>0
U = \frac{\mbare c^2}{\sqrt{ 1- \frac{1}{c^2}|\vV|^2}} 
- \eEL  \EV^{\mbox{\tiny{hom}}}\cdot\qV  +\tfrac16  \eEL^2 \varkappa^3|\qV|^2.
\end{equation}
 Since $\vV(t) = \frac{d\qV(t)}{dt}$, and since we have straight line motion, i.e. $\vV\|\qV$ for all $t$ for which both 
vectors are non-vanishing, this is an implicit first-order differential equation for $t(\qV)$ (in the usual simplified
notation). 
 Eq. \ref{EFFECTIVEenergy} can easily be converted into an explicit first-order differential equation for $t(\qV)$ that
then can be solved by quadrature.

 The study \cite{CarKie} left open whether the mathematical validity of the $O(\varkappa^3)$ approximation to the
untruncated Volterra equation is restricted to short times $\varkappa ct\ll 1$ or whether such
periodic motion over longer times for $\mbare>0$, respectively monotonic run-away solutions for $\mbare<0$, 
are genuine features of BLTP electrodynamics as long as $\varkappa e^2/|\mbare| c^2\ll 1$.
 If the $O(\varkappa^3)$ approximation is faithful provided $\frac{\varkappa e^2 }{ |\mbare| c^2} \ll 1$, then BLTP 
electrodynamics would have to be purged from the list of contenders for a realistic classical electrodynamics.

 By now a verdict is in (see Fig.s~1--4 below).
 The solutions to the $O(\varkappa^4)$ approximation that we computed numerically confirm that the ``small $\varkappa$'' 
expansion is mathematically applicable for ``small times $t$'', viz. when  $\varkappa ct\ll 1$, 
with the motions at $O(\varkappa^0)$, $O(\varkappa^3)$, and $O(\varkappa^4)$ barely distinguishable.
 However, truncation after $O(\varkappa^3)$ does not yield mathematically accurate approximations to 
the true BLTP motions over arbitrarily long times even if $\frac{\varkappa e^2}{|\mbare| c^2}\ll~1$. 
 Should this expansion converge to the actual BLTP motions also over longer times
provided $\varkappa e^2/|\mbare| c^2 \ll 1$, then reasonable accuracy will require to go to much higher powers of
$\varkappa$.  
 In the following we distinguish $\mbare>0$ and $\mbare<0$, beginning with $\mbare>0$.

 For the first figure the parameter values are the same as in Fig.~1 of \cite{CarKie}. %, where $\mbare>0$.
 In Figs.~2 and 3 we keep $\mbare>0$ but vary the parameter values compared to \cite{CarKie}. 
 Figures 1--3 all reveal that the $O(\varkappa^4)$ motion is faster than the $O(\varkappa^3)$ motion for late enough
times, and eventually even faster than the test particle motion, 
the resolution is not fine enough to reveal what happens for very short time spans after release of the particle.
 This is readily worked out by expanding the self-force about $t=0$, noting that the leading order contribution is 
the test particle motion $\qV^{\mbox{\tiny{test}}}(t) = \frac12 \frac{e}{\mbare}\EV^{\mbox{\tiny{hom}}}t^2$,
which yields
\begin{alignat}{1}
\label{selfFexpandedNEARzero}
\Big( \FV^{(3)}_0 +  \FV^{(4)}_0\Big)[\qV,\vV](t) & = 
  - \frac13  \eEL^2 \varkappa^3\qV(t) 
+
 \frac{7}{12}  e^{2}\varkappa^4 c \!\int_{0}^{t} \qV(t^r) dt^{r} + \cdots \\
& = \EV^{\mbox{\tiny{hom}}}\Big(- \frac16  \frac{\eEL^3\varkappa^3 }{\mbare} t^2
+
 \frac{7}{72} 
\frac{\eEL^3\varkappa^4 c}{\mbare}t^3
+ O(t^4)\Big).
\end{alignat}
 This demonstrates that for very short time spans after release of the particle, 
the $O(\varkappa^4)$ motion is faster than the $O(\varkappa^3)$ motion, 
but both are slower than the radiation-free test particle motion. 


