\section{Computing the self-force at $O(\varkappa^4)$}
The goal of Appendix B is to explicitly calculate the 4th order contribution to the self-force in the small-$\varkappa$ regime. 
 To compute the self-force we need to expand
the vectors $\bld{Z}_{\boldsymbol{\xi}}^{[k]}$ and $\pt{t}\bld{Z}_{\boldsymbol{\xi}}^{[k]}$, with $k\in\{0,1,2\}$, in 
powers of $\varkappa$.
 For this in turn we begin by expanding their constituent terms $\bsym{\pi}_{\bxi}^{[k]}$ about $\varkappa=0$ 
and ignore all terms of higher and lower order than 4.

 Writing $\bsym{\pi}_{\boldsymbol{\xi}}^{[k]}=\sum_{i}\bsym{\pi}_{\boldsymbol{\xi}}^{[k],i}$, where $i$ enumerates the 
lines at r.h.s.(\ref{pi2}), resp. r.h.s.(\ref{pi1}), resp. r.h.s.(\ref{pi0}), we find that for the 
non-derivative terms the following $\bsym{\pi}_{\bxi}^{[k],i}$ terms will make non-vanishing contributions at 4th order:
\begin{align}
\label{eq:4a}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[0],1}(t,\sV)=
-\frac{\varkappa^{4}}{4}\lt[\frac{(\nh-\bsym{\beta})\crprd (\bsym{\beta}\crprd \nh)}{(1-\bsym{\beta}\cdot \nh)^{2}}\rt]\re
\\
\label{eq:4b}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],2}(t,\sV)=
-\varkappa^{2}\lt[\nh\crprd\frac{(\nh\crprd {\color{red}\aV})}{c^{2}(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\re \crprd 
\int_{0}^{t\re_{\boldsymbol{\xi}} } \bbeta(t') \crprd \bld{K}_{\boldsymbol{\xi}}(t',t,\sV)c\drm{t'}
\\
\label{eq:4c}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],3}(t,\sV)=
\varkappa^{2}\lt[\nh\crprd\lt[\nh\crprd\frac{(\nh\crprd {\color{red}\aV})}{c^{2}(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\rt]\re \crprd 
\int_{0}^{t\re_{\boldsymbol{\xi}} } \bld{K}_{\boldsymbol{\xi}}(t',t,\sV)c\drm{t'}
\end{align}
\begin{align}
\label{eq:4d}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],4}(t,\sV)=
-\varkappa^{2}\lt[\nh\crprd\!\lt[\nh\crprd\frac{(\nh\crprd {\color{red}\aV})}{c^{2}(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\rt]\re
\!\!\crprd\! 
\lt(\!\frac{1-(1+\varkappa|\sV|)e^{-\varkappa |\sV|}}{\varkappa^{2}|\sV|^{2}}-\frac{1}{2}\rt)\!\frac{\sV}{|\sV|}
\\
\label{eq:4e}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],5}(t,\sV)=
-\varkappa^{2}\lt[\nh\crprd\lt[\nh\crprd\frac{(\nh\crprd {\color{red}\aV})}{c^{2}(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\rt]\re \crprd 
\int_{0}^{t_{\boldsymbol{\xi}^\circ}\re } \bld{K}_{\boldsymbol{\xi}^\circ}(t',t,\sV)c\drm{t'}
\\
\label{eq:4f}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],6}(t,\sV)=
\varkappa^{3}\lt[\frac{1}{(1-\bsym{\beta}\cdot \nh)}\rt]\re
\int_{0}^{t\re_{\boldsymbol{\xi}} }
\mathrm{K}_{\boldsymbol{\xi}}(t',t,\sV)[\bbeta\re+\bbeta(t)]c\drm{t'}
\\
\label{eq:4g}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],7}(t,\sV)=
\varkappa^{2}\frac{1-e^{-\varkappa|\sV|}}{|\sV|}\lt[\frac{\bsym{\beta}}{(1-\bsym{\beta}\cdot \nh)}\rt]\re
\\
\label{eq:4h}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[1],8}(t,\sV)=
-\varkappa^{3}\lt[\frac{\bsym{\beta}}{(1-\bsym{\beta}\cdot \nh)}\rt]\re
\int_{0}^{t_{\boldsymbol{\xi}^\circ}\re }\mathrm{K}_{\boldsymbol{\xi}^\circ}(t',t,\sV)c\drm{t'}
\\
\label{eq:4i}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[2],2}(t,\sV)=
\varkappa^{2}\lt[(1-\beta^{2})\frac{\bsym{\beta}\crprd \nh}{(1-\bsym{\beta}\cdot \nh)^{3}}\rt]\re \crprd 
\int_{0}^{t\re_{\boldsymbol{\xi}} }  \bld{K}_{\boldsymbol{\xi}}(t',t,\sV)c\drm{t'}
\\
\label{eq:4j}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[2],3}(t,\sV)=
-\varkappa^{2}\lt[(1-\beta^{2})\frac{\bsym{\beta}\crprd \nh}{(1-\bsym{\beta}\cdot \nh)^{3}}\rt]\re \crprd \lt(\frac{1-(1+\varkappa|\sV|)e^{-\varkappa |\sV|}}{\varkappa^{2}|\sV|^{2}}-\frac{1}{2}\rt)\frac{\sV}{|\sV|}
\\
\label{eq:4k}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[2],4}(t,\sV)=
-\varkappa^{2}\lt[(1-\beta^{2})\frac{\bsym{\beta}\crprd \nh}{(1-\bsym{\beta}\cdot \nh)^{3}}\rt]\re \crprd 
\int_{0}^{t_{\boldsymbol{\xi}^\circ}\re }\bld{K}_{\boldsymbol{\xi}^\circ}(t',t,\sV)c\drm{t'} 
\\
\label{eq:4l}
&\bsym{\pi}_{\boldsymbol{\xi}}^{[2],5}(t,\sV)=
-\varkappa^{2}\lt[(1-\beta^{2})\frac{ \nh-\bsym{\beta}}{(1-\bsym{\beta}\cdot \nh)^{3}}\rt]\re \crprd \int_{0}^{t\re }
\bbeta(t) \crprd \bld{K}_{\boldsymbol{\xi}}(t',t,\sV)c\drm{t'} 
\end{align}
where the variables denoted by the ``ret'' suffix are evaluated at the retarded time $t\re$ 
which is defined by $c(t-t\re)=|\sV-\qV(t\re)|$, e.g. $\qV\re=\qV(t\re)$. 
 Here genericall the vector $\nh$ is tacitly a vector function $\nh(\qV,\sV)$. 
The retarded time denoted $t\re_{\boldsymbol{\xi}^\circ}$ for the auxiliary (trivial) trajectory
is simply defined by $t\re_{0}(t,\sV)=t-|\sV|/c$. 

We next begin expanding the \req{4a}--\req{4l} terms to 4th order in $\varkappa$.

\subsection{Identifying all order $\varkappa^4$ terms}
To extract the 4th order contributions from the $\boldsymbol{\pi}_{\bxi}^{[k],i}$ 
we must expand the pertinent Bessel function kernels, respectively the exponentials 
$e^{-\varkappa|\sV|}$ and identify those terms that, when multiplied by the pertinent pre-factors $\varkappa^j$, with
$j\in\{2,3\}$, in \req{4a}--\req{4l}, yield a total factor of  $\varkappa^{4}$. 

 We begin with the exponential 
\begin{equation}
\label{eq:11}
e^{-\varkappa |\sV|} =
 1-\varkappa |\sV|+\frac{\varkappa^{2} |\sV|^{2}}{2}-\frac{\varkappa^{3} |\sV|^{3}}{6}+\frac{\varkappa^{4} |\sV|^{4}}{24} +
 O(\varkappa^5|\sV|^5).
\end{equation}
With the help of (\ref{eq:11}) we find
\begin{equation}
\label{eq:13}
\frac{1-e^{-\varkappa|\sV|}}{\varkappa|\sV|} = 1 - \frac{\varkappa|\sV|}{2} + O(\varkappa^2|\sV|^2)
\end{equation}
and
\begin{align}
% \begin{split}
\label{eq:12}
\frac{1-(1+\varkappa|\sV|)e^{-\varkappa |\sV|}}{\varkappa^{2}|\sV|^{2}}-\frac{1}{2}
 = 
%
%\approx \lt(\frac{1-(1+\varkappa|\sV|)\lt(1-\varkappa |\sV|+\frac{\varkappa^{2} |\sV|^{2}}{2}-\frac{\varkappa^{3} |\sV|^{3}}{6}+\frac{\varkappa^{4} |\sV|^{4}}{24}\rt)}{\varkappa^{2}|\sV|^{2}}-\frac{1}{2}\rt) \\ & =-\frac{-\varkappa |\sV|+\frac{\varkappa^{2} |\sV|^{2}}{2}-\frac{\varkappa^{3} |\sV|^{3}}{6}+\frac{\varkappa^{4} |\sV|^{4}}{24}}{\varkappa^{2}|\sV|^{2}}-\frac{1-\varkappa |\sV|+\frac{\varkappa^{2} |\sV|^{2}}{2}-\frac{\varkappa^{3} |\sV|^{3}}{6}+\frac{\varkappa^{4} |\sV|^{4}}{24}}{\varkappa|\sV|}-\frac{1}{2} \\ & =\frac{1}{\varkappa |\sV|}-\frac{1}{2}+\frac{\varkappa |\sV|}{6}-\frac{\varkappa^{2}|\sV|^{2}}{24}-\frac{1}{\varkappa |\sV|}+1-\frac{\varkappa|\sV|}{2}+\frac{\varkappa^{2}|\sV|^{2}}{6}-\frac{1}{2} \\ & =
%
-\frac{\varkappa|\sV|}{3}+\frac{\varkappa^{2}|\sV|^{2}}{8} + O(\varkappa^3|\sV|^3)
% \end{split}
\end{align}
 Inserting \req{13} in \req{4g} and identifying the fourth order term $\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[1],7}$, we find
\begin{align}
\label{eq:pi174}
\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[1],7}(t,\sV)
=
-\frac12\varkappa^{4}|\sV|\lt[\frac{\bsym{\beta}}{1-\bsym{\beta}\cdot \nh}\rt]\re
\end{align}
 Inserting \req{12} in \req{4d} and \req{4j}, then identifying the fourth order terms 
$\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[1],4}$, respectively $\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[2],3}$, we find
\begin{align}
\label{eq:pi144}
\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[1],4} (t,\sV)
&=
-\varkappa^{4}\frac{|\sV|}{8c^2}
\lt[\frac{({\color{red}\aV}\cdot \sV)\nh-(\nh\cdot \sV){\color{red}\aV}}
{(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\re,
\\
\label{eq:pi234}
\bsym{\pi}_{\boldsymbol{\xi},(4)}^{[2],3}(t,\sV)
&=
\varkappa^{4}\frac{|\sV|}{8}
\lt[\frac{(1-\beta^{2})\big((\sV\cdot \bsym{\beta})\nh-(\nh \cdot \sV)\bsym{\beta}\big)}{(1-\bsym{\beta}\cdot \nh )^{3}}\rt]\re.
\end{align}

 Coming next to the Bessel function kernels of the first kind $J_{n}$, their 
expansions read
\begin{equation}
\label{eq:9}
J_{1}(x) = \frac{x}{2}\lt(1-\frac{x^{2}}{8}+\frac{x^{4}}{192} + O(x^6)\rt),
\end{equation}
\begin{equation}
\label{eq:10}
J_{2}(x)=\frac{x^{2}}{8}\lt(1-\frac{x^{2}}{12}+\frac{x^{4}}{384}+ O(x^6)\rt).
\end{equation}
 Recalling that the terms containing the  Bessel function kernels
already have factors of $\varkappa^{2}$ or $\varkappa^{3}$, 
to arrive at the $O(\varkappa^4)$ contributions to the $\bsym{\pi}$s 
the leading order of the Bessel expansions (\ref{eq:9}), (\ref{eq:10}) is all that is required.
 Note that the integrals over $\mathrm{K}_{\bxi}$ and $\bld{K}_{\bxi}$ in 
(\ref{eq:4b}), (\ref{eq:4c}), (\ref{eq:4e}), (\ref{eq:4f}), (\ref{eq:4h}), (\ref{eq:4i}), (\ref{eq:4k}), (\ref{eq:4l})
 are rendered integrable when the Bessel functions are expanded to 0th order of(\ref{eq:10}), (\ref{eq:11}). 
 To this end we evaluate as follows
\begin{align}
\begin{split}
\label{eq:14}
\int_{0}^{t\re_{\bxi} } \bbeta(t') \crprd \bld{K}_{\bxi}(t',t,\sV)c\drm{t'}&
= \frac{\varkappa^{2}}{8} \int_{0}^{t\re_{\bxi} } \vV (t')\crprd \lt[\sV-\qV(t')-\vV(t')(t-t')\rt]\drm{t'} +O(\varkappa^4)
\\
&
=\frac{\varkappa^{2}}{8}\int_{0}^{t\re_{\bxi} } \vV(t') \drm{t'}\crprd \sV +O(\varkappa^4)
\\
&
=\frac{\varkappa^{2}}{8}\qV(t\re_{\bxi}) \crprd \sV +O(\varkappa^4),
\end{split}
\end{align}
where we have utilised the fact that $\qV(t) \ || \ \vV(t') \ ||\  \EV^{\mbox{\tiny{hom}}}$ 
for any choices of $t$ and $t'$ (i.e. the charge travels in a straight line).


 Likewise the other integrals that appear are easy enough to evaluate; thus
\begin{align}
\begin{split}
\label{eq:15}
\int_{0}^{t\re_{\bxio} }\bld{K}_{\bxio}(t',t,\sV)c\drm{t'}
 & =\frac{\varkappa^{2}}{8} \sV \int_{0}^{t\re_{\bxio} }c\drm{t'} +O(\varkappa^4)
\\
&
=\frac{\varkappa^{2}}{8}\sV\lt(ct-|\sV|\rt)+O(\varkappa^4)
 \end{split}
\end{align}
\begin{align}
\begin{split}
\label{eq:16}
