%&+c^{2}{\color{red}a}(t-t^{r})^{2}\lt(-\frac{2}{(1-\beta^{2})}\frac{1-\beta^{2}}{\beta^{2}}-\frac{2}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt)\Bigg]
%\\
%& +2 \pi \varkappa^{4} \lt(q-v(t-t^{r})\rt)
%\\
=\varkappa^{4}\frac{\pi}{4c^{2}}\Bigg[&{\color{red}a}(t^r)q(t^r)c(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}
\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)\!\!(t^r)
\\
&+c^{2}{\color{red}a}(t^ r)(t-t^{r})^{2}\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\! \rt)\!\!(t^r)\Bigg]
\\
&\hspace{-1.5truecm} +\varkappa^{4} 2 \pi  \lt(q(t^r)-v(t^r)(t-t^{r})\rt).
\end{split}
\end{align}
The next term is 
\begin{align}
\begin{split}
\label{eq:32}
\hspace{-1truecm}
\bld{Z}^{[2],(4)}(t,t^{r})=
&\varkappa^{4}\frac18
\Big(1-\beta^{2}(t^{r})\Big)\int^{2\pi}_{0}\!\int^{\pi}_{0} 
\frac{\sin \theta}{(1-\beta \cos\theta)^{2}}\times\\ 
&\times\Bigg[\{\bsym{\beta}(t^{r})\cdot \qV(t^{r})+(\qV(t^r)+\vV(t^r)(t-t^r))\cdot \nh\}c(t-t^{r})\nh
\\
&\qquad -\{c(t-t^{r})+2\nh \cdot \qV(t^{r})\}c(t-t^{r})\bsym{\beta}(t^{r})-\{(\nh-\bsym{\beta}(t^{r}))\cdot \nh \}c(t-t^{r})\qV(t^r)
\\
&\qquad -2\lt(\bsym{\beta}(t^{r})\cdot\int_{0}^{t^{r}}\!
\qV(t')\drm{t}^\prime \rt)\nh+2\lt(\nh\cdot\int_{0}^{t^{r}}\! \qV(t')\drm{t}^\prime\rt)\bsym{\beta}(t^{r})\Bigg]\drm\theta \drm\phi.
\end{split}
\end{align}
Like before, we integrate over $\phi$, eliminating all components that are not parallel to the motion. 
We find that the two integral terms over $t'$ cancel, as well as terms sharing the coefficients linear in $c(t-t^{r})$, thus
\begin{align}
\begin{split}
\label{eq:33}
\hspace{-1truecm}
Z^{[2],(4)}_{\parallel}(t,t^{r})=&\varkappa^{4}\frac{\pi}{4}(1-\beta^{2}\lt(t^{r})\rt)\int^{\pi}_{0} 
\frac{\lt[\beta(t^{r})c^{2}(t-t^{r})^{2}+q(t^{r})c(t-t^{r}) \rt]\sin \theta}{(1-\beta(t^r) \cos\theta)^{2}}\Big[\cos^{2} \theta-1\Big]
\drm\theta.
\end{split}
\end{align}
Integration over $\theta$  simply yields
\begin{align}
\label{eq:34}
\hspace{-1truecm}
Z^{[2],(4)}_{\parallel}(t,t^{r})=
\varkappa^{4}\frac{\pi}{4} \Big(1-\beta^{2}(t^{r})\Big)\!
\Big[\beta(t^{r})c^{2}(t-t^{r})^{2}+q(t^{r})c(t-t^{r}) \Big]\! \Bigg[\frac{4}{\beta^{2}}-\frac{2}{\beta^{3}}\ln 
\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\Bigg](t^r).
\end{align}

According to \req{selfFexpl}, the self-force also depends on the time derivative of these terms.
 We readily find
\begin{align}
\label{eq:35a}
\hspace{-1truecm}
\pt{t} \bld{Z}^{[0],(4)}(t,t^{r})&=0,
\\
\label{eq:35b}
\hspace{-1truecm}
\pt{t} \bld{Z}^{[1],(4)}(t,t^{r})&=\varkappa^{4}\frac{\pi}{8c^{2}}
\Bigg[{\color{red}a}(t^r)q(t^r)c\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)
\!\!(t^r)\\ \notag
&\qquad\qquad +2c^{2}{\color{red}a}(t^r)(t-t^{r})\!\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\! \rt)\!\!(t^r)
\Bigg]\be - \varkappa^{4} 2 \pi\vV(t^r),
\\
\label{eq:35c}
\hspace{-1truecm}
\pt{t} \bld{Z}^{[2],(4)}(t,t^{r})&=\varkappa^{4}\frac{\pi}{4}(1-\beta^{2}(t^{r}))
\lt[2\beta(t^{r})c^{2}(t-t^{r})+q(t^{r})c \rt]
\lt(\!\frac{4}{\beta^{2}}-\frac{2}{\beta^{3}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)\!\!(t^r)\be;
\end{align}
recall that $\be$ is the unit vector pointing along $\EV^{\mbox{\tiny{hom}}}$, thus $\be=\qV/|\qV|$ too. 

According to \req{selfFexpl}, the self-force also depends on $Z^{[2],4}_{||}(t,t)=\lim_{t^r\to t} Z^{[2],4}_{||}(t,t^r)$. 
From \req{34} we readily find that $ Z^{[2],4}_{||}(t,t) \equiv 0 $, making no contribution.

\subsection{The final formula for the self-force at $O(\varkappa^4)$}
 We now have all the ingredients needed to evaluate the self-force term \req{selfFexpl} at 4th order in powers of $\varkappa$.
 We denote the 4th order term as $\bld{F}_{0}^{(4)}(t)=F_{0}^{(4)}(t)\be$.
 Since all contributing terms are $\propto\varkappa^4$, we can factor out an overall coefficient $\varkappa^4$. 
 After also cancelling $\pi$s wherever possible, it is given by
\begin{align}
\begin{split}
\label{eq:36}
F_{0}^{(4)}(t)=\frac{1}{4}\varkappa^{4}e^{2}\Bigg[
& c^{2}
\int_{0}^{t}(t-t^{r})\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
\\
&-\frac{1}{4} \int_{0}^{t}
\Bigg[(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)q{\color{red}a}
\\
&\hspace{3truecm} 
+c(t-t^{r})^{2}\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt){\color{red}a}\Bigg]\drm{t}^r
\\
& -2  c  \int_{0}^{t} \lt(q-(t-t^{r})v\rt) \drm{t}^r
\\
&-\frac{1}{4}\int_{0}^{t}
(t-t^{r})\Bigg[{\color{red}a}
q\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)
\\
&\hspace{3truecm}
+ 2c(t-t^{r})^{2}\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt){\color{red}a}\Bigg]\drm{t}^r
\\
&+2  c \int_{0}^{t} (t-t^{r})v\drm{t}^r
\\
&- c^{2}\int_{0}^{t}
(t-t^{r})(1-\beta^{2})\Bigg[\frac{2}{\beta}-\frac{1}{\beta^{2}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\Bigg]\drm{t}^r
\\
&-\frac{1}{4}\int_{0}^{t}
qc(1-\beta^{2})\Bigg[\frac{4}{\beta^{2}}-\frac{2}{\beta^{3}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\Bigg]\Bigg]\drm{t}^r.
\end{split}
\end{align}
There are many terms that can be collected such as the %third and sixth %% NOW
second and fifth lines; the % fourth and seventh %%% NOW
third and sixth lines can also be collected;
lines % 2 and 9 %%% NOW
one and eight may also be collected together. 
Line % 5  %%% NOW
four simply evaluates to zero via integration by parts. 
% We also note that the first line vanishes %%% ALREADY TAKEN CARE OF.

 This yields
\begin{align}
\begin{split}
\label{eq:37}
F_{0}^{(4)}(t)=\frac{1}{4}\varkappa^{4}e^{2}\Bigg[& c^{2}\int_{0}^{t}(t-t^{r})2\beta \drm{t}^r
\\
&-\frac{1}{4}\int_{0}^{t}
\Bigg[2(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)q
\\
&\hspace{2truecm}
+3c(t-t^{r})^{2}\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt)\Bigg]{\color{red}a} \drm{t}^r
\\
&+2  c \int_{0}^{t} (t-t^{r}) v\drm{t}^r
\\
&-\frac{1}{4}\int_{0}^{t}
qc(1-\beta^{2})\lt(\frac{4}{\beta^{2}}-\frac{2}{\beta^{3}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)\drm{t}^r\Bigg].
\end{split}
\end{align}
We can perform integration by parts on the third line
\begin{align}
\begin{split}
\label{eq:38}
c\int_{0}^{t}
(t-t^{r})^{2}&\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt){\color{red}a} \drm{t}^r
=\\
& c^{2}(t-t^{r})^{2}\int_{0}^{t^{r}}
\frac{d\beta}{d\tau}\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)\drm\tau\Bigg|_{t^r=0}^{t^r=t}
\\
&+2c^{2}\int_{0}^{t} 
(t-t^{r})\int_{0}^{\beta}\lt(-\frac{4}{x^{2}}+\frac{2}{x^{3}}\ln\lt(\frac{1+x}{1-x}\rt)\rt)
\drm{x}\drm{t}^r.
\end{split}
\end{align}
The first line at r.h.s.\req{38} vanishes whereas the second can be evaluated, in total yielding
\begin{align}
\begin{split}
\label{eq:39}
c\int_{0}^{t}(t-t^{r})^{2}&\lt(-\frac{4}{\beta^{2}}+\frac{2}{\beta^{3}}\ln\lt(\frac{1+\beta}{1-\beta}\rt) \rt){\color{red}a}\drm{t}^r\\
& \qquad 
= 2c^{2}\int_{0}^{t} (t-t^{r})\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\rt)\drm{t}^r,
\end{split}
\end{align}
and so
\begin{align}
\begin{split}
\label{eq:40}
F_{0}^{(4)}(t)=&\frac{1}{4}\varkappa^{4}e^{2}\Bigg[-\frac{1}{4}\int_{0}^{t}
\Bigg[2(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)\Bigg]q{\color{red}a}
\drm{t}^r
\\
&\qquad 
-\frac{3}{2}c^{2}\int_{0}^{t}
(t-t^{r})\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt) \drm{t}^r
\\
&\qquad +4  c \int_{0}^{t} (t-t^{r})v  \drm{t}^r
\\
&\qquad -\frac{1}{4}\int_{0}^{t}
(1-\beta^{2})qc\lt(\frac{4}{\beta^{2}}-\frac{2}{\beta^{3}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\!\rt)\drm{t}^r\Bigg]
\end{split}
\end{align}
 We can also integrate by parts the remaining term containing ${\color{red}a}$, 
\begin{align}
\begin{split}
\label{eq:41}
&\int_{0}^{t}
(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\rt)q{\color{red}a}\drm{t}^r
\\
&=qc(t-t^{r})
\int_{0}^{t^{r}}
\frac{d\beta}{d\tau}\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\rt)
\!\!(\tau) \drm\tau \Bigg|_{t^r=0}^{t^r=t}
\\
&-c\int_{0}^{t}
\frac{d}{\drm{t}^r}\lt(q(t^r)(t-t^{r})\rt)\int_{0}^{\beta(t^r)}\lt(\frac{6}{x^{3}}+\frac{\lt(1-\frac{3}{x^{2}}\rt)}{x^{2}}\ln  
\lt(\frac{1+x}{1-x}\rt)\rt)\drm{x}\drm{t}^r.
\end{split}
\end{align}
The boundary term vanishes while the inner integral over $x$ can be evaluated, and so
\begin{align}
\notag
&\int_{0}^{t}
(t-t^{r})\lt(\frac{6}{\beta^{3}}+\frac{\lt(1-\frac{3}{\beta^{2}}\rt)}{\beta^{2}}\ln  \lt(\frac{1+\beta}{1-\beta}\rt)\rt)q{\color{red}a}\drm{t}^r
\\ \label{eq:42a}
&=-c\int_{0}^{t}\lt(c (t-t^{r})\beta-q\rt)\lt(\frac{4}{3}-\frac{1}{\beta}\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\rt)\drm{t}^r
\\ \label{eq:42b}
&=-\frac{4c}{3}\int_{0}^{t} \lt(c (t-t^{r})\beta-q\rt)\drm{t}^r
+c^{2}\int_{0}^{t}
(t-t^{r})\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
\\ \notag
&\qquad -c\int_{0}^{t}
\frac{q}{\beta}\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
%\\
%&=c^{2}\int_{0}^{t}
%(t-t^{r})\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r\\
%&\qquad -c\int_{0}^{t}\frac{q}{\beta}\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
\end{align}
and the integral over $c\beta(t^r) (t-t^{r})-q(t^r)$ at r.h.s.\req{42b} vanishes.
 The self-force at $O(\varkappa^4)$ becomes
\begin{align}
\begin{split}
\label{eq:43}
F_{0}^{(4)}(t)=\frac{1}{4}\varkappa^{4}e^{2}\Bigg[&-\frac{1}{2}c^{2}\int_{0}^{t}
(t-t^{r})\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
\\
&+\frac{1}{2}\int_{0}^{t}
\frac{qc}{\beta}\lt[\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt]\drm{t}^r
\\
&-\frac{3}{2}c^{2}\int_{0}^{t} 
(t-t^{r})\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\rt)\drm{t}^r
\\
&+4  c \int_{0}^{t} (t-t^{r}) v\drm{t}^r
\\
&-\frac{1}{2}\int_{0}^{t}
(1-\beta^{2})qc\lt(\frac{2}{\beta^{2}}-\frac{1}{\beta^{3}}\ln \lt(\frac{1+\beta}{1-\beta}\rt)\!\rt)\drm{t}^r\Bigg].
\end{split}
\end{align}
We can combine all but the 4th line to yield
\begin{align}\notag
\hspace{-1truecm}
F_{0}^{(4)}(t)&=\frac{1}{4}\varkappa^4 e^{2} c 
\!\int_{0}^{t}\!\Bigg[4  v(t^r)(t-t^{r})-2 c(t-t^{r})\lt(\frac{2}{\beta}+\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)+ q(t^r)\Bigg]\drm{t}^r\\
& 
\label{eq:44}
=
\frac{1}{4}\varkappa^4 e^{2}
\Bigg[5 \!\int_{0}^{t}\! q(t^r) c\drm{t}^r-2 \!\int_{0}^{t}\!\int_{0}^{t^r}\!\! \lt(\frac{2}{\beta}+
\lt(1-\frac{1}{\beta^{2}}\rt)\ln\lt(\frac{1+\beta}{1-\beta}\rt)\!\!\rt)\!\!(\tilde{t})c^2\drm\tilde{t}\drm{t}^r\Bigg],
\end{align}
where integration by parts produces the final r.h.s.(\ref{eq:44}) from the previous line.
 We have arrived at  (\ref{eq:F4}).

