\begin{lemma}[Multiplication involving single dimension of Hankel mode%type \uppercase\expandafter{\romannumeral1}
]\label{lem:HT_mul_1or2}
     Let $\mL\in\C^{n_1\times r}$, $\mR\in\C^{n_2\times r}$, and $\mE\in\C^{r\times n}$. The computation of the following terms % realized by fast convolution via FFT:
     $$\G(\mE)\times_{1}\mL^H~\mbox{and}~ \G(\mE)\times_{2}\mR^H$$
     can be realized by $r^2$ fast convolution via FFT, which cost $O(nr^2\log(n))$ flops. 
\end{lemma}
\begin{proof}
     We take the computation of $\G(\mE)\times_{1}\mL^H \in \C^{r\times n_2\times r}$ for example. For $j_1,i_3\in[r]$, $i_2\in[n_2]$
    \begin{align*}
        [\G(\mE)\times_{1}\mL^H](j_1,i_2,i_3)&{=}\sum_{i_1=0}^{{n_1}-1}\frac{1}{\sqrt{w_{i_1{+}i_2}}}\mE(i_3,i_1{+}i_2)\overline{\mL}(i_1,j_1)
        \\&=[\tilde{\mE}(i_3,:)\ast\overline{\mL'}(:,j_1)](n_1+i_2),
    \end{align*}
    where $\tilde{\mE}=\D^{-1}(\mE)$ is the weighted version of $\mE$ and $\mL'(:,j_1)$ is the vector that reverses the order of $\mL(:,j_1)$. The previous computation can be realized via $r^2$ fast convolution, which costs $O(nr^2\log(n))$ flops.   
\end{proof}
