    \begin{lemma}\label{lem:Hankel_mul3}
For $\mV\in\C^{s\times r}$, $\mE\in\C^{s\times n}$ and $\tilde{\bcZ}\in\C^{n_1\times n_2\times r}$:
\begin{align*}
    \G(\mE)\times_{3}\mV^H&=\G(\mV^H\mE),\label{eq:Hankellift_mul3} \numberthis 
    \\\G^{*}(\tilde{\bcZ}\times_{3}\mV)&=\mV\G^{*}(\tilde{\bcZ}). \label{eq:DeHankel_mul3} \numberthis 
\end{align*}

\end{lemma}
\begin{proof}
We first prove \eqref{eq:Hankellift_mul3}. For $i_1\in[n_1]$, $i_2\in[n_2]$, and $j_3\in[r]$:
    \begin{align*}
        &[G(\mE)\times_{3}\mV^H](i_1,i_2,j_3)=\sum_{i_3=0}^{s-1}[\G(\mE)](i_1,i_2,i_3)\overline{\mV}(i_3,j_3)
        \\&=\frac{1}{\sqrt{w_{i_1+i_2}}}\sum_{i_3=0}^{s-1}\mE(i_3,i_1+i_2)\overline{\mV}(i_3,j_3)
        \\&=\frac{1}{\sqrt{w_{i_1+i_2}}}[\mV^H\mE](j_3,i_1+i_2)
        =[\G(\mV^H\mE)](i_1,i_2,j_3).
    \end{align*}

Then we prove \eqref{eq:DeHankel_mul3}. Let $\mZ=\G^{*}(\tilde{\bcZ}\times_{3}\mV)$, and we rewrite that for $k\in[s]$ and $a\in[n]$,
     \begin{align*}
        &\mZ(k,a)=\frac{1}{\sqrt{w_a}}\sum_{i_1+i_2=a}\sum_{i_3=0}^{r-1}\tilde{\bcZ}(i_1,i_2,i_3)\mV(k,i_3)
        \\&=\sum_{i_3=0}^{r-1}\(\frac{1}{\sqrt{w_a}}\sum_{i_1+i_2=a}\tilde{\bcZ}(i_1,i_2,i_3)\)\mV(k,i_3)=\mV\G^{*}(\tilde{\bcZ}).
    \end{align*}
\end{proof}
\end{comment}

