\begin{lemma}[Fast computation of the scaled terms] \label{lem:fast_scaleterm}
    We give the fast computation of $ \breve{\mL}^H\breve{\mL}, \breve{\mR}^H\breve{\mR},   \breve{\mV}^H\breve{\mV}$ as follows, where $\breve{\mL},\breve{\mR},\breve{\mV}$ are defined in \eqref{eq:breve_lrv}. 
    \begin{align*}
        \breve{\mL}^H\breve{\mL}&=\cM_{1}\((\mI_r,\mR^H\mR,\mV^H\mV)\bcdot\bcS\)\cM_1(\bcS)^H,
       \\ \breve{\mR}^H\breve{\mR}&=\cM_{2}\((\mR^H\mR,\mI_r,\mV^H\mV)\bcdot\bcS\)\cM_2(\bcS)^H,
       \\ \breve{\mV}^H\breve{\mV}&=\cM_{3}\((\mL^H\mL,\mR^H\mR,\mI_r)\bcdot\bcS\)\cM_3(\bcS)^H,
    \end{align*}
    and this costs $O((s+n)r^2+r^4)$ flops in total. 
\end{lemma} 
\begin{proof}
    Taking $\breve{\mL}^H\breve{\mL}$ for example:
    \begin{align*}
        \breve{\mL}^H\breve{\mL}&=\cM_{1}(\bcS ) (\overline{\mV} \otimes\overline{\mR})^H(\overline{\mV} \otimes\overline{\mR} )\cM_{1}(\bcS )^{H}
        \\&=\cM_{1}(\bcS )\(\mV^H\mV\otimes\mR^H\mR\)^T\cM_{1}(\bcS )^{H}
        \\&=\cM_{1}\((\mI_r,\mR^H\mR,\mV^H\mV)\bcdot\bcS\)\cM_1(\bcS)^H
    \end{align*}
    Note that we should compute $\breve{\mL}^H\breve{\mL}$ from the last equality, which is realized by mode-$i$ tensor product sequentially. %If we compute $\breve{\mL}^H\breve{\mL}$ just from the second equality, the computational complexity is $O((s+n)r^2+r^5)$ flops. % The most efficient computation
\end{proof}

