%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{General setting of the problem and definitions}\label{sec.setting}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The model \fer{prob} considered in the Introduction captures a sharp, discontinuous transition between seasons which is not always appropriate. Indeed, in many natural phenomena such as  climatic seasons, transitions are smooth and progressive in time.  For capturing this effect we consider a regularized model in which this smoothing is taken into account and where the sharp transition model is recovered as a limit process, see Remark~\ref{convergence}.

Let $A\subset\R$ be a measurable set and denote by $\chil_A^0(t)$ to its characteristic function which is, in consequence, a measurable function.
 Let $\rho\in C^\infty(\R)$  be supported in $(-1/2,1/2)$ and satisfy
\begin{align}\label{hip.kernel}
\rho(s) \geq 0,\quad \rho'(s)s\geq 0,\quad \rho(s)=\rho(-s),\quad \int_\R \rho(s)ds = 1.	
\end{align}
Then, for $\eps\in(0,1)$, the rescaled kernel   $\rho_\eps(s) = \rho(s/\eps)/\eps$ is a Dirac $\delta-$approximation with support contained in $(-\eps/2,\eps/2)\subset (-1,1)$. We define 
\begin{align*}
\chil_{A}^\eps =	\rho_\eps * \chil_{A}.
\end{align*}
  Notice that, by standard approximation results, see e.g. \cite[Th. 4.22]{Brezisbook},  if $A$ is of finite measure then 
  $\chil_{A}^\eps \to \chil_A^0$ as $\eps\to0$ in $L^p(\R)$, for any $1\leq p<\infty$.


We are now prepared to give the general formulation of our model.
Let the season length be given by  $\tau\in(0,1)$. We introduce the partition of the time domain  $	\R_+ = G \cup D$ with $G=\bigcup_{n=0}^\infty G_n$, $D=\bigcup_{n=0}^\infty D_n$, and with $G_n,D_n$ given by \fer{def.cndn}. 

Consider two  functions 
\begin{align}
\label{ass.lip}
	f_g,f_d \in C^1(\R^N;\R^N)
\end{align}
 and an initial data $u_0\in \R^N$. Let $\eps\in[0,1)$. The problem is: Find $u:[0,\infty)\to\R^N$ such that $u(0)=u_0$, and
\begin{align}
&u'(t) = 	f_g(u(t)) \chil_G^\eps(t) + f_d(u(t)) \chil_D^\eps(t) && \text{for }t>0,&\label{prob2}\\
& u(0)=u_0. &&&\label{prob2b}
\end{align}
Observe that this formulation encapsulates both the sharp transition model ($\eps=0$) and the smooth transition model ($\eps>0$). 


We assume
\begin{align}
&f_g(0)=f_d(0)=0,\label{ass.cero1}
\end{align}
implying that $u_*=0$ is an equilibrium for all $\tau\in(0,1)$, and the existence of a constant $K\in\R^N$ with positive components such that for $j=1,\ldots,N$ and $ u_j\in[0,K_j] $ we have 
\begin{align}
	f_{g,i}(u)\geq0,~f_{d,i}(u)\geq0 \text{ if } u_i=0,\quad  	f_{g,i}(u)\leq0,~f_{d,i}(u)\leq0 \text{ if } u_i=K_i,\label{ass.cero2}
\end{align}
implying the uniform boundedness of the solution of \fer{prob2}-\fer{prob2b}, this is,  if for $i=1,\ldots,N$ we have $u_{0,i}\in[0,K_i]$  then $u_{i}(t)\in[0,K_i]$ for $t\in[0,\infty)$.


For $\eps>0$, the existence and uniqueness of a $C^{2}((0,\infty))\cap C([0,\infty))$ solution and  its smooth dependence on the parameters  is ensured by classical results for  non-autonomous systems of differential equations. 


For $\eps=0$, the solution to \fer{prob2}-\fer{prob2b} may be constructed by matching the solutions of the collection of successive  regular problems defined in $G_n$ and $D_n$, and then the existence, uniqueness and Lipschitz continuity of the solution is a straightforward consequence of the differentiability of $f_g$ and $f_d$.  The non-negativity of the components and the equilibria and boundedness properties also follow from \fer{ass.cero1}-\fer{ass.cero2}. 


We conclude this section by introducing the notion of equilibrium we use. 
Let us introduce the notation $\chil_g^\eps(t,\tau) =\chil^\eps_{G_0}(t)$,  and  $\chil_d^\eps(t,\tau) =\chil^\eps_{D_0}(t)$, this is,
\begin{align}\label{def.chis2}
& \chil_g^\eps(t,\tau) = \int_0^\tau 	 \rho_\eps(t-s)ds, \quad
 \chil_d^\eps(t,\tau) =\int_\tau^1 	 \rho_\eps(t-s)ds,
\end{align}
and consider the increasing function 
\begin{align}\label{def.calR}
r_\eps(\tau) = \int_0^\tau\int_0^1 \rho_\eps(t-s)dt ds,
\end{align}
for which we have $r_\eps(\tau)\to\tau$ as $\eps\to0$, uniformly in $\tau$.


\begin{definition}\label{def.eq}
Let $\eps,\tau\in(0,1)$. The function $u^*\in   C^2_{per}([0,1])$ is an \emph{equilibrium} of \fer{prob2}-\fer{prob2b} if it satisfies $\abs{u^*_i(t)}\leq K_i$ for $i=1,\ldots,N$, and 
\begin{align*}
&(u^*)'(t)  = 	f_g(u^*(t)) \chil_g^\eps(t,\tau) + f_d(u^*(t)) \chil_d^\eps(t,\tau)\big),&&\text{for } t\in(0,1). %\label{def.eq.eq}
%&u^*(0)=u^*(1). &&& \label{def.eq.id}
\end{align*}
For $\eps=0$ the definition is similar, but with $u^*\in  W^{1,\infty}((0,1))\cap C_{per}([0,1])$.

\end{definition}

\begin{remark}\label{convergence}

The boundedness property assumed on the definition of an equilibrium is motivated by the  boundedness of the solution of \fer{prob2}-\fer{prob2b} implied by assumption \fer{ass.cero2}. Notice that this property together with Arzel\`a-Ascoli theorem ensure  the uniform convergence of any sequence of equilibria $u^*_\eps$ to an equilibrium $u^*_0$ as $\eps\to0$, where $u^*_\eps$ and $u^*_0$ denote equilibria of the problems corresponding to $\eps>0$ and $\eps=0$, respectively. 	
\end{remark}




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Main results}\label{sec.results}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Consider the Banach spaces  $X= C^1((0,1))\cap C_{per}([0,1]) $, $Y= C([0,1])$. The application of the Crandall-Rabinowitz theorem to our problem \fer{prob2}-\fer{prob2b} encompasses the analysis of the operator $F:(0,1)\times X \to Y$ given by
\begin{align}\label{def.F}
	F(\tau,v) = v' - \big(f_g(v) \chil_g^\eps(\cdot,\tau) + f_d(v) \chil_d^\eps(\cdot,\tau)\big). 
\end{align}
We also introduce some matrices that will play an important role in our analysis:
\begin{align*}
 & H[\tau,u](t) =	Df_g(u)\chil_g^\eps(t,\tau)+ Df_d(u) \chil_d^\eps(t,\tau),\\%\label{def.H}	\\
& A[u]= Df_g(u)- Df_d(u). %\label{def.A}	 
\end{align*}


Our main result establishes the conditions under which a uniquely determined local in time non-trivial branch of equilibria, $u^*$, emerges from the trivial equilibrium $u_*=0$. 


\begin{theorem}\label{th.CR}
Assume \fer{hip.kernel}, \fer{ass.lip}, and \fer{ass.cero1}-\fer{ass.cero2}.
Let $u_*(t)=0$ for $t\in[0,1]$ and let $E\subset X$ be an open neighbourhood of $u_*$.	
Suppose that the following conditions are satisfied:
\begin{enumerate}
\item[(C1)]  
 There exists $\tau_*\in(0,1)$ such that the linear subspace of solutions of 
\begin{align}\label{prob.sys1}
\Phi'(t) =H[\tau_*,u_*](t)\Phi(t)\qtext{for } t\in(0,1),\quad \Phi(0)=\Phi(1)	,
\end{align}
is span by some non-zero function $\Phi_0$.
\item[(C2)] It is satisfied the transversality condition 
\begin{align}\label{cond.trans2}
\int_0^1 \rho_\eps(s-\tau_*) \Phi_R(s) \cdot A[u_*] \Phi_0(s) ds \neq 0,
\end{align}
where $\Phi_R$ spans the linear subspace of solutions of the dual problem
\begin{align}\label{prob.sys1d}
\Phi'(t) = -H[\tau_*,u_*](t)^T\Phi(t) \qtext{for } t\in(0,1), \quad \Phi(0)=\Phi(1)	.
\end{align}
\end{enumerate}
Then, there exist 
\begin{enumerate}
\item An open neighborhood $B\subset X$ of $u_*$ and an  interval $I=(-\delta,\delta)$, for some $\delta>0$,	
\item Functions $\tau^* \in C^1(I;(0,1))$, $u^*\in C^1(I;E)$,  with $\tau^*[0]=\tau_*$, $u^*[0]=u_*$ and $u^*[s]\neq u_*$ for $s\neq0$,
\end{enumerate}
 such that 
\begin{align*}
F(\tau^*[s],u^*[s]) =0 \qtext{for all }s\in I.	
\end{align*}
Moreover, for $N=\{(\tau,u)\in ( (0,1) \times E\backslash\{0\}) ) : F(\tau,u)=0 \}$, we have 
\begin{align*}%\label{a.thCR}
B \cap N = \{ (\tau^*[s], u^*[s]): s\in I\backslash \{0\}\}	.
\end{align*}
\end{theorem}

\begin{remark}
The local behavior of the non-trivial equilibrium  $u^*[s]$ may be approximated  as  $u^*[s]=u_*+s\Phi_0 + s \xi[s]$, where $\xi$ is a continuous function with $\xi[0]=0$.
Under further regularity assumptions on $f_g$ and $f_d$, a more detailed local behavior of $\tau^*[s]$ may  also be obtained, see \cite[Th.~1.18]{Crandall1973}.
\end{remark}


Conditions (C1) and (C2) are easy to check when the Jacobian matrices $Df_g(u_*)$ and $Df_d(u_*)$ are symmetric and commute. In this case, $H[\tau_*,u_*](t)$ and $H[\tau_*,u_*](s)$ are also symmetric and commute for all $t,s\in(0,1)$, implying that the solutions of \fer{prob.sys1} and \fer{prob.sys1d} may be expressed in terms of 
\begin{align}\label{def.calH}
\cH[\tau_*,u_*](t) = \int_0^t H[\tau_*,u_*](s)ds	
\end{align}
 as $\Phi_0(t) = e^{\cH[\tau_*,u_*](t)}\vfi_0$, and $\Phi_R(t) = e^{-\cH[\tau_*,u_*](t)}\vfi_0$, with $\vfi_0\in\ker(I-e^{\cH[\tau_*,u_*](1)})$.

\begin{corollary}\label{cor.symm}
In the conditions of Theorem~\ref{th.CR}, suppose that  $Df_g(u_*)$ and $Df_d(u_*)$  are symmetric and commute, that  $A[u_*]$ is definite, and that there exists $\tau_*\in(0,1)$ such that (C1) is satisfied. Then (C2) is also satisfied and the thesis of the theorem applies.	
\end{corollary}

If $H[\tau_*,u_*](t)$ does not commute with itself for different times,  we must resort to the notion of fundamental matrix for solving multi-dimensional non-autonomous non-homogeneous linear problems 
\begin{align*}
& \Psi(t)' = H[\tau_*,u_*](t) \Psi(t) + \psi(t) && \text{for }t>0,& \\%\label{eqna1}\\
& \Psi(0)=\Psi_0. &&& %\label{eqna2}
\end{align*}
In this case, the solution is given by 
\begin{align}\label{solnh}
\Psi(t) = G(t,0)\Psi_0 + \int_0^t G(t,s)\psi(s)ds,	
\end{align}
where the 
 non-singular matrix $G(t,s)$ is the unique solution of
\begin{align*}
\p_t G(t,t_0) = H[\tau_*,u_*](t) G(t,t_0)	
\end{align*}
such that $G(t_0,t_0)=I$, the identity matrix.
On noting that the fundamental matrix of the dual problem is $G(s,t)^T$, 
we deduce that the solutions of \fer{prob.sys1} and \fer{prob.sys1d} may be expressed as
\begin{align*}
\Phi_0(t) = G(t,0)\vfi_0,\quad 	\Phi_R(t) = G(1,t)^T\vfi_R, \qtext{for }t\in(0,1),
\end{align*}
with $\vfi_0\in\ker(I-G(1,0))$ and $\vfi_R\in\ker(I-G(1,0)^T)$. Then, the transversality condition \fer{cond.trans2} may be rewritten as 
\begin{align*}
\int_0^1 \rho_\eps(s-\tau_*) ~ \vfi_R^T G(1,s)AG(s,0)\vfi_0 ds \neq 0.
\end{align*}
It is not difficult to find examples in which this transversality condition is not satisfied, showing that it is a restrictive condition.

\bigskip

\no\emph{Proof of Theorem~\ref{th.CR}.} The proof consists on checking that $F$ defined by \fer{def.F} satisfies the four conditions of Crandall-Rabinowitz theorem \cite[Theorem~1.7]{Crandall1971}. The first two conditions are straightforward.



\emph{Condition (a): $F(\tau,u_*)=0$ for all $\tau\in(0,1)$. } This is clear, since $f_g(u_*)=f_d(u_*)=0$ by hypothesis \fer{ass.cero1}. 



\emph{Condition (b): The partial Frechet derivatives $F_\tau,~F_v$ and $F_{\tau v}$ exist and are continuous. }Replacing \fer{def.chis2} in \fer{def.F} and differentiating with respect to $\tau$, we get, for $\sigma\in(0,1)$ 
\begin{align*}
F_\tau(\tau,v)[\sigma] = - (f_g(v)-f_d(v)) \rho_\eps(\cdot-\tau)\sigma .	
\end{align*}
We also have, for $\vfi\in X$,
\begin{align*}
F_v(\tau,v)[\vfi] & = \frac{d}{dh} F(\tau, v+h\vfi)\Big|_{h=0} \\
& = \vfi'-	\big(Df_g(v) \chil_g^\eps(\cdot,\tau) + Df_d(v) \chil_d^\eps(\cdot,\tau)\big) \vfi  ,
\end{align*}
and then 
\begin{align*}
F_{\tau v}(\tau,v)[\sigma,\vfi] = - (Df_g(v)-Df_d(v)) \rho_\eps(\cdot-\tau)\sigma \vfi.
\end{align*}
The continuity of these operators follows from the continuous differentiability of $f_g,~f_d$ and $\rho_\eps$, see \fer{hip.kernel} and \fer{ass.lip}.



\emph{Condition (c): $\ker(F_v(\tau_*,u_*))$ and $Y\backslash R(F_v(\tau_*,u_*))$  are one-dimensional. }
We have $\Phi\in \ker(F_v(\tau_*,u_*))$ if $\Phi$ is a solution of \fer{prob.sys1}. 
By hypothesis, the linear space of solutions of \fer{prob.sys1} is one-dimensional, i.e, the dimension of  $\ker(F_v(\tau_*,u_*))$ is one.

Notice that using formula \fer{solnh} with $\psi=0$ we obtain the representation of the solution of  \fer{prob.sys1} as $\Phi_0(t)=G(t,0)\vfi_0$, whenever the periodic boundary condition $(I-G(1,0))\vfi_0=0$ is satisfied. Since, by hypothesis, the solution is unique up to a multiplicative constant, we deduce $\dim(\ker(I-G(1,0)))=1$.

Now we check that the co-dimension of $R(F_v(\tau_*,u_*))$ is one. 
We have $\psi \in  R(F_v(\tau_*,u_*))$ if the equation 
\begin{align}
&	 \xi'(t) =	H[\tau_*,u_*](t) \xi(t) + \psi(t) &&\text{ for }t\in(0,1), \label{nR.1}
\end{align}
has a solution $\xi \in X$, this is, also satisfying $\xi(0)=\xi(1)$.  Let $\Phi_R$ be  the solution of the dual problem \fer{prob.sys1d}. Then, multiplying \fer{nR.1} by $\Phi_R$ and integrating in $(0,1)$ we obtain
\begin{align*}
-\int_0^1 \xi(t)\cdot \Phi_R'(t)dt =	\int_0^1 H[\tau_*,u_*](t)\xi(t)\cdot \Phi_R(t) + \int_0^1 \psi(t)\cdot \Phi_R(t) dt,
\end{align*}
 and using that $\Phi_R'(t) = -H[\tau_*,u_*](t)^T\Phi_R(t)$, we deduce the orthogonality condition
\begin{align*}
\int_0^1  \psi(t)  \cdot \Phi_R(t)dt = 0	.
\end{align*}
Therefore, any $\psi\in R(F_v(\tau_*,u_*))$ must be orthogonal  to the subspace span by $ \Phi_R(t)$, implying that the co-dimension of $R(F_v(\tau_*,u_*))$ is one.

\emph{Condition (d): $F_{\tau v}(\tau_*,u_*)[1,\Phi_0] \notin R(F_v(\tau_*,u_*))$. } This condition reads
\begin{align*}
0 \neq \int_0^1 \Phi_R(s) \cdot F_{\tau v}(\tau_*,u_*)[1,\Phi_0](s)  ds 
 =
- 	\int_0^1 \rho_\eps(s-\tau_*) \Phi_R(s) \cdot A[u_*] \Phi_0(s) ds,
\end{align*}
which is true by assumption.
%where $A=Df_g(u_*)-Df_d(u_*)$. 
\hfill$\Box$

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\bigskip

\no\emph{Proof of Corollary~\ref{cor.symm}. }If the Jacobian matrices $Df_g(u_*)$ and $Df_d(u_*)$ are symmetric and commute then the matrices $A[u_*]$, $H[\tau_*,u_*](t)$ and $H[\tau_*,u_*](s)$ have the same property for all $t,s\in(0,1)$. Thus,  the solutions of \fer{prob.sys1} and \fer{prob.sys1d} may be expressed in terms of the matrix $\cH[\tau_*,u_*](t)$ given by \fer{def.calH} as 
\begin{align*}
\Phi_0(t) = e^{\cH[\tau_*,u_*](t)}\vfi_0,\quad \Phi_R(t) = e^{-\cH[\tau_*,u_*](t)}\vfi_R, 	
\end{align*}
with $\vfi_0\in \ker(I- e^{\cH[\tau_*,u_*](1)})$, one-dimensional by assumption,  and $\vfi_R\in \ker(I- e^{-\cH[\tau_*,u_*](1)})$. Since $e^{\cH[\tau_*,u_*](1)}$ is non-singular, we have $ \ker(I- e^{\cH[\tau_*,u_*](1)})= \ker(I- e^{-\cH[\tau_*,u_*](1)})$, so that we may choose $\vfi_R=\vfi_0$. On noting that  $A[u_*]$ also  commutes with $e^{\cH[\tau_*,u_*](t)}$, we deduce 
\begin{align*}
	 \Phi_R(t) \cdot A[u_*] \Phi_0(t) = \vfi_R^Te^{-\cH[\tau_*,u_*](t)}A[u_*]e^{\cH[\tau_*,u_*](t)}\vfi_0 = \vfi_0^T A[u_*]\vfi_0,
\end{align*}
 for all $t\in(0,1)$.  Finally, since by assumption $A[u_*]$ is definite, we have  $ \vfi_0^T A[u_*]\vfi_0\neq0$. Then, condition \fer{cond.trans2} in (C2) reduces to 
\begin{align*}
\int_0^1 \rho_\eps(s-\tau_*) ds \neq 0,
\end{align*}
which is true in view of $\tau_*\in(0,1)$ and the properties assumed on the kernel $\rho_\eps$, see \fer{hip.kernel}. 
\hfill$\Box$





