\section{Standard optimality conditions of second order problem}
Following \cite{sato2025}, let us consider a state-control vector bundle $(\mathcal{E}, \pi^\mathcal{E}, \mathcal{M})$ where the base space is given by the state space $\mathcal{M} = T\mathcal{Q}$ with $\mathcal{Q}$ a smooth manifold, and the control by a vector space $\mathcal{N}$. We want to solve an OCP defined in local coordinates on $\mathcal{E}$ in the form
\begin{equation} \label{eq:OCP}
\begin{aligned}
	\min_{(q,u)} \quad &&      \mathcal{J}[q,u] &= \int_0^{T} C(q(t),\dot{q}(t),u(t))~dt\\
	\text{subject to} \quad &&        \ddot{q}(t) &= f(q(t), \dot{q}(t), u(t)),\\
	&& q(0) &= q_0, \quad \dot q(0) = v_0, \\
        && q(T) &= q_T, \quad \dot q(T) = v_T,
\end{aligned}
\end{equation}
where $C, f$ are assumed to be of class $C^2$. The necessary conditions of optimality for such optimal control problems are given by Pontryagin's Maximum Principle (PMP) \cite{pontryagin1962}. To apply PMP, \eqref{eq:OCP} should be first transformed into first order form by introducing a new variable $v$ for $\dot q$. This leads to the following OCP
\begin{equation} \label{eq:OCP.1ord}
	\begin{aligned}
		\min_{(q,v,u)} \quad &&      \mathcal{J}[q,v,u] &= \int_0^{T} C(q(t),v(t),u(t))~dt\\
		\text{subject to} \quad &&        \dot{q}(t) &= v(t),\\
        &&        \dot{v}(t) &= f(q(t), v(t), u(t)),\\
		&& q(0) &= q_0, \quad v(0) = v_0, \\
        && q(T) &= q_T, \quad v(T) = v_T.
	\end{aligned}
\end{equation}
  In particular, in the setting of problem \eqref{eq:OCP} with no constraint on the control, the weak PMP applies \cite{bonnard2003singular,trelat2024control}. The \michael{Pontryagin's} Hamiltonian associated with \eqref{eq:OCP} is given by 
$$ \mathcal{H}_{\lambda^0}(x,\lambda, u) = \rodrigo{\langle (\lambda_q,\lambda_v), (v, f(q, v, u)) \rangle} +  \lambda^0 C(q,v,u),$$
\rodrigo{where $\lambda^0 \in \mathbb{R}$ and $\lambda = (\lambda_q,\lambda_v) \in T^*\mathcal{M}$ receive the names of abnormal multiplier and adjoint (also costate), respectively}.
\begin{theorem}[Weak Pontryagin's Maximum Principle]
	Assume that $u(\cdot) \in L^\infty([0,T], \mathcal{N})$. If the control $u(\cdot)$ and the corresponding state $x(\cdot)= (q(\cdot), v(\cdot))$ are optimal for \eqref{eq:OCP.1ord}. Then, there exits an absolutely continuous adjoint $\lambda(\cdot) = (\lambda_q(\cdot), \lambda_v(\cdot))$ and constant $\lambda^0 \leq 0$ such that $(\lambda(\cdot), \lambda^0) \neq 0$ for any $t \in [0,T]$ and $(x,\lambda,\lambda^0, u)$ satisfy the following system of equations
    \begin{subequations}
    \label{eq:PMP}
        \begin{align}
		\dot q(t) &= \hphantom{-}\frac{\partial \mathcal{H}_{\lambda^0}}{\partial \lambda_q}(q(t),v(t),\lambda_q(t),\lambda_v(t), u(t)), & \textcolor{black}{\dot v(t)} &= \hphantom{-}\frac{\partial \mathcal{H}_{\lambda^0}}{\partial \lambda_q}(q(t),v(t),\lambda_q(t),\lambda_v(t), u(t)), \\
		\dot \lambda_q(t) &= -\frac{\partial \mathcal{H}_{\lambda^0}}{\partial q}(q(t),v(t),\lambda_q(t),\lambda_v(t), u(t)), & \textcolor{black}{\dot\lambda_v(t)} &= -\frac{\partial \mathcal{H}_{\lambda^0}}{\partial v}(q(t),v(t),\lambda_q(t),\lambda_v(t), u(t)), \\
		0 &= \hphantom{-}\frac{\partial \mathcal{H}_{\lambda^0}}{\partial u}(q(t),v(t),\lambda_q(t),\lambda_v(t), u(t)). && \label{eq:PMP_optimality}
	\end{align}
    \end{subequations}
and boundary conditions
\begin{subequations} \label{eq:PMP.boundary}
	\begin{alignat}{2}
		q(0) &= q_0, \quad & v(0) &= v_0, \\
		q(T) &= q_T, \quad & v(T) &= v_T.
        %\lambda_q(T) &= \lambda^0 \frac{\partial \phi}{\partial q}(q(T), v(T)), \quad \lambda_v = \lambda^0 \frac{\partial \phi}{\partial v}(q(T), v(T)).
	\end{alignat}
\end{subequations} 
\end{theorem}
\rodrigo{Solutions $(x, \lambda, \lambda^0,u)$ of \eqref{eq:PMP}-\eqref{eq:PMP.boundary} are candidates to be minimisers for \eqref{eq:OCP.1ord}. Given a candidate pair $(x,u)$, the dimension $m \geq 1$ of the vector space spanned by the admissible pairs $(\lambda(\cdot),\lambda^0)$ satisfying \eqref{eq:PMP} is said to be the corank of the minimiser. In this work it is assumed that we are always in the corank $m = 1$ case.}

The previous equations are invariant with respect to a rescaling of $(\lambda_q, \lambda_v, \lambda^0)$, therefore, it is classical to fix the value of $\lambda^0$ and distinguish two cases, namely, the normal case when $\lambda^0 = -1$, and the abnormal case when $\lambda^0 = 0$. In our consideration, we will restrict our attention to the normal case.

\rodrigo{If we define the augmented functional associated to \eqref{eq:OCP.1ord},
\begin{equation}
    \widetilde{\mathcal{J}}[x,\lambda,u] = \int_{0}^T \left[C(q(t),v(t),u(t) + \langle (\lambda_q(t),\lambda_v(t)), (\dot{q}(t) - v(t), \dot{v}(t) - f(q(t), v(t), u(t))) \rangle \right] \,dt, \label{eq:augmented.1ord}
\end{equation}
it should be noted that Equations \eqref{eq:PMP} imply the vanishing of the first variation of \eqref{eq:augmented.1ord}. That is, for all $(\delta x(\cdot),\delta \lambda(\cdot), \delta u(\cdot))$ such that $(\delta x(\cdot), \delta \lambda(\cdot)) \in T_{(x(\cdot),\lambda(\cdot))}T^*\mathcal{M}$ and $(\delta x(\cdot),\delta u(\cdot)) \in T_{(x(\cdot),u(\cdot))}\mathcal{E}$, we have that
\begin{equation*}
    d\widetilde{\mathcal{J}}_{[x,\lambda,u]}[\delta x,\delta \lambda,\delta u] = 0.
\end{equation*}}

The second order necessary optimality conditions allow us to distinguish minimising and maximising curves. The sufficient optimality conditions %have a local nature and
ensure optimality of a given curve. %for \rodrigo{sufficiently short time.}
In the case of \eqref{eq:OCP.1ord}, the \rodrigo{local} \michael{necessary and sufficient} second order conditions are given by the Legendre conditions and can be summarised as follows \cite{Bonnard2007}.
\begin{theorem}[Legendre conditions \cite{Bonnard2007}] \label{th.Legendre} $\left. \right.$ 
\begin{itemize}
	\item If the control $u(\cdot)$ and the corresponding state $x(\cdot)$ are optimal for \eqref{eq:OCP.1ord}, then  $(x,\lambda,\lambda^0, u)$ satisfy the Legendre condition 
	\begin{equation} \label{eq:Legendre}
		\frac{\partial^2 \mathcal{H}_{\rodrigo{\lambda_0}}}{\partial u^2}(x(t),\lambda(t), u(t)) \leq 0, \qquad \michael{\forall t\in[0,T].}
	\end{equation} 

	\item If $(x,\lambda,\lambda^0, u)$ satisfy the strong Legendre condition 
	\begin{equation} \label{eq:Legendre.strong}
		\frac{\partial^2 \mathcal{H}_{\rodrigo{\lambda_0}}}{\partial u^2}(x(t),\lambda(t), u(t)) <0, \qquad \michael{\forall t\in[0,T],}
	\end{equation}  
then, there exists \rodrigo{$\varepsilon > 0$ such that $(x,u)$ is optimal throughout the time interval $[0,\varepsilon]$}. %time interval $[0,\varepsilon]$ on which $(x,u)$ is locally optimal.
\end{itemize}

\end{theorem}

\rodrigo{One can refine this result further introducing the notion of conjugate times. First, we can consider the second variation of \eqref{eq:augmented.1ord}, $d^2\tilde{\mathcal{J}}$. In the corank 1 case, when restricted to candidate minimisers, and fixing $\delta \lambda = 0$, this provides a unique quadratic form $Q = \left.d^2\tilde{\mathcal{J}}\right\vert_{\ker d\tilde{\mathcal{J}}}$ on the space of variations $T_{(x(\cdot),u(\cdot))}\mathcal{E}$ \cite{Bonnard2007,agrachev2013control}. Theorem \ref{th.Legendre} guarantees the positive definiteness of $Q$ for sufficiently small intervals. The times at which the signature of $Q$ changes are called conjugate times and under the strong Legendre condition these can be shown to be isolated \cite{agrachev2013control}. The first of these conjugate times along a candidate minimiser marks the time where $Q$ stops being definite and becomes indefinite. This leads to the following
