\section{First order conditions in the new Lagrangian formulation}

The first order optimality conditions equivalent to \eqref{eq:PMP}-\eqref{eq:PMP.boundary} can be obtained without transformation to \textcolor{black}{first order form as in} \eqref{eq:OCP.1ord} using the variational approach under more restrictive regularity assumptions on $u$, namely, $u \in C([0,T], \mathcal{N})$. The variational approach is based on the consideration of the augmented Lagrangian
\begin{equation} \label{aug.Lagrangian}
	\mathcal{J}_{\mathrm{aug}}[q, \kappa ,u] = \int_0^{T} C(q(t),\dot{q}(t),u(t))+ \kappa^{\top} \left(\ddot q -  f(q(t), \dot{q}, u(t)) \right)~dt.
\end{equation}
Assume $q$ is of class $C^2$, $\kappa$ is of class $C^1$ and $u$ of class $C$. Then imposing the vanishing of the first variation of $\mathcal{J}_{\mathrm{aug}}$ leads to the following equations
\begin{equation} \label{eq:aug.Lagrangian}
	\begin{aligned}
		\ddot q(t) &= \textcolor{black}{f(q(t), \dot{q}(t), u(t))} \\
		\ddot \kappa(t) &= \frac{d}{dt} \left[\frac{\partial C}{\partial \dot q}(q(t),\dot{q}(t),u(t)) - \kappa(t)^{\top} \frac{\partial f}{\partial \dot q}(q(t),\dot{q}(t),u(t))\right] - \frac{\partial C}{\partial q} (q(t),\dot{q}(t),u(t)) + \kappa(t)^{\top} \frac{\partial C}{\partial q}(q(t),\dot{q}(t),u(t))\\
		0 &= \frac{\partial C}{\partial u}(q(t),\dot{q}(t),u(t)) - \kappa(t)^{\top} \frac{\partial f}{\partial u}(q(t),\dot{q}(t),u(t))
	\end{aligned}
\end{equation} 
and boundary conditions
\begin{equation} \label{eq:aug.Lagrangian.boundary}
	\begin{aligned}
		q(0) &= q_0, \quad v(0) = v_0,  \\
		q(T) &= q_T, \quad v(T) = v_T.
        %\kappa(T) &=\frac{\partial \phi}{\partial q}(q(T),\dot{q}(T)), \ \dot{\kappa}(T)^{\top} = \frac{\partial \phi}{\partial q}(q(T),\dot{q}(T)) +\frac{\partial C}{\partial \dot q}(q(T),\dot{q}(T),u(T)) + \frac{\partial \phi}{\partial \dot q}(q(T),\dot{q}(T)) \, \frac{\partial f}{\partial \dot q}(q(T),\dot{q}(T),u(T)).
	\end{aligned}
\end{equation} 
As shown in \cite{sato2025}, \eqref{eq:aug.Lagrangian}-\eqref{eq:aug.Lagrangian.boundary} are equivalent to \eqref{eq:PMP}-\eqref{eq:PMP.boundary} under \textcolor{black}{the}  identification $\lambda_v = \kappa$ and $\lambda_q = \frac{\partial C}{\partial \dot q}(q,\dot{q},u) - \langle \kappa, \frac{\partial f}{\partial \dot q}(q,\dot{q},u) - \dot{\kappa}\rangle$.

The new approach to first order conditions introduced in \cite{leyendecker2024new,kono2025,sato2025,kono2025b} is based on the new Lagrangian formulation obtained from \eqref{aug.Lagrangian} by integration by parts
\begin{multline} \label{new.Lagrangian.cost}
	\widetilde{ \mathcal{J}_{\mathrm{aug}}}[q, \kappa ,u] =  \kappa(T)^{\top} \dot{q}(T) - \kappa(0)^{\top} \dot{q}(0)  + \int_{0}^T \left[ C(q(t),\dot{q}(t),u(t)) - \dot{\kappa}(t)^{\top} \dot{q}(t) - \kappa(t)^{\top} f(q(t),\dot{q}(t),u(t)))\right] dt.
\end{multline}
The new control Lagrangian is defined on $TT^*\mathcal{Q} \oplus_{T\mathcal{Q}}^{\alpha} \mathcal{E} \to \mathbb{R}$, where $TT^*\mathcal{Q} \oplus_{T\mathcal{Q}}^\alpha \mathcal{E}$ is the $\alpha_\mathcal{Q}$-twisted sum of $TT^*\mathcal{Q}$ and $\mathcal{E}$ defined as follows
$$TT^*\mathcal{Q} \oplus_{T\mathcal{Q}}^\alpha \mathcal{E} = \left\lbrace (V,U) \in TT^*\mathcal{Q} \times \mathcal{E} \;\vert\; \pi_{T\mathcal{Q}} \circ \alpha_{\mathcal{Q}} (V) = \pi^{\mathcal{E}}(U) \right\rbrace,$$ see \cite{sato2025} for more details on the geometrical setting. In local coordinates $(q,\kappa,v_q,v_{\kappa},u)$, the new Lagrangian is given by 
\begin{equation} \label{new.Lagrangian}
	\tilde{\mathcal{L}}^\mathcal{E}(q,\kappa,v_q,v_{\kappa},u) = v_{\kappa}^{\top} v_q + \kappa^{\top} X_v(q,v_q,u) - C(q,v_q,u)\,.
\end{equation}
For \rodrigo{the sake of notational economy}, we introduce the notation $y = (q, \kappa)$. As it was shown in \cite{sato2025}, the matrix $\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}}{\partial \dot y^2}(y, \dot y, u)$ is non degenerate, which implies that the new control Lagrangian is hyperregular and the first order conditions of optimality take the form of regular Euler-Lagrange equations involving the control variable as an additional parameter.  %In case if the optimality condition issued from variations of control variable, namely $0 = \frac{\partial \tilde{\mathcal{L}}^\mathcal{E}}{\partial u} = 0$, allows to express control as a $u = u(q, \kappa, v_q)$, then the optimality conditions are in the form of classical Euler-Lagrange equations. Notice that if the strong Legendre condition is satisfied, then $u = u(q, \kappa, v_q)$ by implicit function theorem. 


The relation between the new Lagrangian formulation and the Hamiltonian formulation from PMP was established in \cite{sato2025} based on an extension of Tulczyjew’s isomorphism. 
The classical Tulczyjew’s isomorphism \cite{TulczyjewLag} is defined as an isomorphism between the double bundles $T^*T\mathcal{Q}$ and $TT^*\mathcal{Q}$. Let $(q,\kappa,v_q,v_{\kappa})$ be local coordinates on $T^*T\mathcal{Q}$. Then we have the following relation
\begin{equation*}
	\alpha_{\mathcal{Q}}(q,\kappa,v_q,v_{\kappa}) = (q,v_q,v_{\kappa},\kappa) \in T^*T\mathcal{Q}.
%	\beta_{\mathcal{Q}}(q,\kappa,v_q,v_{\kappa}) &= (q,\kappa,-v_{\kappa},v_q) \in T^*T^*\mathcal{Q},
\end{equation*}
This formulation was extended in \cite{leyendecker2024new,sato2025} to double control bundles. In adapted local coordinates, Tulczyjew's diffeomorphism has the following form
\begin{equation*}
	\alpha^\mathcal{E}_{\mathcal{Q}}(q,\kappa,v_q,v_{\kappa}, u) = (q,v_q,v_{\kappa},\kappa, u) \in T^*T\mathcal{Q}\oplus_{T\mathcal{Q}} \mathcal{E}.
%	\beta^\mathcal{E}_{\mathcal{Q}}(q,\kappa,v_q,v_{\kappa}, u) &= (q,\kappa,-v_{\kappa},v_q, u) \in T^*T^*\mathcal{Q}\oplus_{T\mathcal{Q}} \mathcal{E},
\end{equation*}
with $(q,\kappa,v_q,v_{\kappa}) \in TT^*\mathcal{Q}$. It induces the following relation
\begin{align} \label{eq:Tulc}
	\tilde{\mathcal{L}}^\mathcal{E} &= \mathcal{H}_{-1} \circ \alpha_{\mathcal{Q}}^{\mathcal{E}}. % \qquad \text{or equivalently} \qquad \tilde{\mathcal{L}}^\mathcal{E}\circ (\alpha_{\mathcal{Q}}^{\mathcal{E}})^{-1} = \mathcal{H}_{-1}.
\end{align}
As a result, the extended Tulczyjew's diffeomorphism makes the relation between the optimality conditions given by the weak PMP and obtained from the variational approach in the new Lagrangian setting \textcolor{black}{explicit}. In the next section we will further describe the implications on the second order necessary and sufficient optimality conditions.
\section{Second order conditions in the new Lagrangian setting}

Assume that $(q^*, \kappa^* ,u^*)$ satisfy the first order conditions \eqref{eq:aug.Lagrangian} and $(q^* ,u^*)$ minimise \eqref{eq:OCP}. Let $(q,u)$ satisfy $\ddot q = f(q,\dot q, u)$, then the following inequality holds%To get the second order condition using the formulation $\widetilde{ \mathcal{J}_{\mathrm{aug}}}[q, \kappa ,u] $, we will use the following 
\begin{equation} \label{eq:frozen.adj}
	\widetilde{ \mathcal{J}_{\mathrm{aug}}}[q, \kappa^* ,u] - \widetilde{ \mathcal{J}_{\mathrm{aug}}}[q^*, \kappa^* ,u^*] = \mathcal{J}[q, u] - \mathcal{J}[q^*, u^*] \geq 0.
\end{equation}
%for all $(q,u)$ satisfying $\ddot q = f(q,\dot q, u)$. 
\michael{In the following, w}e denote $\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* [q ,u] = \widetilde{ \mathcal{J}_{\mathrm{aug}}}[q, \kappa^* ,u]$. \michael{From}
%It follows from
\eqref{eq:frozen.adj} \michael{it follows}, that $(q^*, u^*)$ minimise $\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* [q ,u]$ under the condition $\ddot q = f(q,\dot q, u)$, and thus, its second variation must be non negative. Using the notation $x = (q,\dot q)$, we have
$$ 
0 \leq \delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* =  - \int_0^T (\delta x^\top, \delta u^\top) \left(
\begin{array}{cc}
	\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial^2 x} & \frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial x \partial u} \\
	\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial x \partial u} & \frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2} 
\end{array}
\right) \left(
\begin{array}{cc}
	\delta x \\
\delta u
\end{array}
\right) dt,
$$
where $\delta x$ and $\delta u$ are related by $\dot \delta x  = \frac{\partial f}{\partial x}(x^*,u^*)\delta x + \frac{\partial f}{\partial u}(x^*,u^*)\delta u$. Using the classical argument of the dominant term, see \cite[Section 3.4.3]{Liberzon2012}, we conclude that $-\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2}(\rodrigo{y^*(t), \dot y^*(t)},u^*(t)) \geq 0$ for all $t \in [0,T]$. We also provide a proof for completeness. 
\begin{theorem}
    Let \rodrigo{$(y^*(\cdot), u^*(\cdot)) = (q^*(\cdot), \kappa^*(\cdot), u^*(\cdot))$} be an optimal solution of \eqref{eq:OCP} \rodrigo{with} $\kappa^*$ the corresponding adjoint from \eqref{aug.Lagrangian}. Then the following condition is satisfied
    $$ \frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2}(\rodrigo{y^*(t), \dot y^*(t)}, u^*(t)) \leq 0, \qquad t \in [0,T].$$
\end{theorem}
\begin{proof}
    The proof is by contradiction and follows the classical ideas in the calculus of variations for the proof of the Legendre necessary condition of optimality \cite{gelfand1963calculus}. Assume that there is $t_0 \in (0,T)$ such that $\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2}(\rodrigo{y^*(t), \dot y^*(t)},u^*(t)) > 0$. Then there exists an interval $(t_0-h,t_0+h)$ such that $\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2}(\rodrigo{y^*(t), \dot y^*(t)},u^*(t)) > \varepsilon$ for some $\varepsilon > 0$. We will choose variations $\delta q, \delta u$ such that $0 > \delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^*$, which would contradict optimality of $(q^*(\cdot), u^*(\cdot))$. The relation between $\delta q$ and $\delta u$ is given by
    $$\delta \ddot q = A_1(t) \delta q + A_2(t) \delta \dot q + B(t) \delta u$$
    where matrices $A_1,A_2,B$ are defined as follows
    $$\quad A_1(t)= \frac{\partial f}{\partial q}(q^*(t), \dot q^*(t), u^*(t)), \ A_2(t)= \frac{\partial f}{\partial \dot q}(q^*(t), \dot q^*(t), u^*(t)), \ B(t)= \frac{\partial f}{\partial u}(q^*(t), \dot q^*(t), u^*(t)).$$
    We assume that $\mathrm{rank} B(t) = \dim \mathcal{N}$. Let us denote $\tilde B = (B^\top B)^{-1}B^\top$. Then we can express $\delta u$ as a function of $\delta q, \delta \dot q, \delta \ddot q$ as follows
    \begin{equation} \label{eq:deltau}
    \delta u = \tilde B(t) \delta \ddot q - \tilde B(t) A_1(t) \delta q - \tilde B(t) A_2(t) \delta \dot q.    
    \end{equation}
    We define variations $\delta q_i$ for $i = 1, \dots, n= \dim \mathcal{Q}$ of the form
    $$
    \delta q_i = \begin{cases}
        0, \quad 0 \leq t < t_0- h, \\
        \frac{6}{h^5}(t - (t_0 - h))^5 - \frac{15}{h^4}(t-(t_0-h))^4 + \frac{10}{h^3}(t-(t_0-h))^3, \quad  t_0- h\leq t \leq t_0, \\
        \frac{6}{h^5}((t_0 + h)-t)^5 - \frac{15}{h^4}((t_0 + h)-t)^4 + \frac{10}{h^3}((t_0 + h)-t)^3, \quad  t_0 \leq t \leq t_0+h, \\
        0, \quad t_0+h <  t \leq T.
    \end{cases}
    $$
    It follows from the construction that $\delta q = (\delta q_1, \dots, \delta q_n) \in C^2[0,T]$ and satisfies the boundary conditions $\delta q(0) = \delta q(T) = 0$. In addition, we have the following
     $$
    \max_{t\in [0,T]} \|\delta q(t) \|_2  = \sqrt{n},  \  \max_{t\in [0,T]} \|\delta \dot q(t)\|_2  = \sqrt{n}\frac{15}{8h}, \  \max_{t\in [0,T]} \|\delta \ddot q_i(t)\|_2  = \sqrt{n}\frac{10 \sqrt{3}}{3h^2}.
    $$
    Together with \eqref{eq:deltau}, \michael{this} implies
    $$
    \max_{t\in [0,T]} \|\delta u(t) \|_2 \leq M \sqrt{n} \left( 1 + \frac{15}{8h} + \frac{10 \sqrt{3}}{3h^2} \right), \quad M = \max\{ \max_{[0,T]}\tilde B(t), \max_{[0,T]}\tilde B(t) A_1(t), \max_{[0,T]}\tilde B(t)A_2(t)\}.
    $$
    The second variation $\delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^*$ corresponding to the chosen $\delta q$ has the following form
    \begin{multline}
         \delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* =  -\int_{t_0-h}^{t_0+h} \delta q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 q}(t) \delta q(t) + 2 \delta q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial q \partial \dot q}(t) \delta \dot q(t) + \delta  \dot q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 \dot q}(t) \delta \dot q(t) \\ + 2 \delta  q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial q \partial u}(t) \delta u(t)  + 2 \delta  \dot q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial \dot q \partial u}(t) \delta u(t) + \delta  u^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 u}(t) \delta u(t) dt, \end{multline}
         where we use the following notation for shortness $\tilde{\mathcal{L}}^\mathcal{E}_*(t) = \tilde{\mathcal{L}}^\mathcal{E}(\rodrigo{y^*(t), \dot y^*(t)},u^*(t))$.
         We split $\delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^*$ into two terms $\delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* = J_1(h) + J_2(h)$ defined as follows
         \begin{multline}
             J_1(h) = -\int_{t_0-h}^{t_0+h} \delta q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 q}(t) \delta q(t) + 2 \delta q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial q \partial \dot q}(t) \delta \dot q(t) + \delta  \dot q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 \dot q}(t) \delta \dot q(t) \\ + 2 \delta  q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial q \partial u}(t) \delta u(t)  + 2 \delta  \dot q^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial \dot q \partial u}(t) \delta u(t)dt,
         \end{multline}
         and 
         $$ J_2(h) = -\int_{t_0-h}^{t_0+h} \delta  u^\top(t)\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E}_* }{\partial^2 u}(t) \delta u(t) dt.$$
         We have the following estimates on $J_1(h), J_2(h)$
         \begin{align}
             J_1(h) &\leq C_1h + C_2 +C_{-1}\frac{1}{h} + C_{-2} \frac{1}{h^2}, \\
             J_2(h) &\leq -\varepsilon \left(D_1h + D_2 +D_{-1}\frac{1}{h} + D_{-2} \frac{1}{h^2} + D_{-3} \frac{1}{h^3} \right)< 0,
         \end{align} 
         where the constants $C_i, D_i$ are positive and independent from $h$. This implies that there exists $0<h_0<1$ such that for all $0<h<h_0$ $| J_2(h)| > |J_1(h)|$, which implies $\delta^2\widetilde{ \mathcal{J}_{\mathrm{aug}}}^* < 0$. This contradicts the optimality of $(q^*(\cdot),u^*(\cdot))$. Therefore, we conclude that $\frac{\partial^2 \tilde{\mathcal{L}}^\mathcal{E} }{\partial u^2}(\rodrigo{y^*(t), \dot y^*(t)},u^*(t)) \leq 0$ for any $ t \in [0,T]$.
\end{proof}


