Given any independent set $I\in\mathscr C^1_n$, by adding up the Constraints \eqref{con:LP-italia-spagna_max-w} related to $I$, we obtain:
%
\begin{gather*}\label{proof_step:sum_indep_1}
|I| \, \pi_I \, \ge \, \sum_{u \in I}\sum_{e \in \delta(u)} \ \ \varrho_{eu}\quad
\Longrightarrow \quad 
2 \, \pi_I \, \ge \, \sum_{u \in I}\sum_{e \in \delta(u)} \ \ \varrho_{eu},
\end{gather*}
since $|I|\le 2$.
%
Moreover, adding up all these last inequalities for every independent set $I\in\mathscr C^1_n$, we then have:
%
\begin{equation*}
    2 \, \sum_{I \in \mathscr C^1_n} \pi_I \geq \sum_{e \in E} \ (\varrho_{eu} + \varrho_{ev}),
\end{equation*}
since any coloring is a partition of the vertex set.
Then, according to Constraints \eqref{con:LP-italia-spagna_splitting}, the following holds:
%
\begin{align*}
  \underbrace{\sum_{I \in \mathscr C^1_n} \pi_I}_{=\OSBunon} \,\geq \frac 12\sum_{e \in E^1_n} c_{e} = \frac12\sum_{e \in E^1_n[C_1]} c_{e} +\frac 12 \sum_{e \in E^1_n[C_2]} c_{e} + \frac 12 n\, \bar{c}
=  \underbrace{\frac{n(n-1)}{2}}_{=\optunon} + \frac 12 n \, \bar{c}. 
\end{align*}
%
Finally, it follows that:
%
\begin{equation*}
    \lim_{n \to +\infty} \frac{\OSBunon}{\optunon} \,  \geq \, \lim_{n \to +\infty} 1 + \frac{n}{2} - \frac{1}{n - 1}= +\infty.
\end{equation*}
\end{proof}

The following proposition states that the ratio between the upper bound $\JAPbound$ and edge-weighted clique number $\optimum$ can be arbitrarily large.


\begin{proposition}\label{prop:example_bad_japan}
The sequence $\{(G^1_n,\boldsymbol c^1_n)\}$ of EWMCP instances is such that
\begin{equation*}
\frac{\JAPunon}{\optunon} \rightarrow + \infty \quad   ~~\text{as}~~ \quad n \rightarrow +\infty,
\end{equation*}
where $\mathscr{C}^1_n$ is any coloring of the vertices of $G^1_n$.
\end{proposition}

\begin{proof}
% We consider any arbitrary coloring \(\mathscr C_n=\{I_1,\dots ,I_k\}\) of $G_n$, where the independent sets are ordered by their indices.
% For any vertex \(u \in V_n\), let \(\tau(u)\) be the index of the set containing it, and recall that:

% \[
% \sigma_u \;=\;
% \sum_{h<\tau(u)}
%      \max \, \bigl\{c_{e} \;:\; e \in E,\; v\in I_h \bigr\}.
