Based on the above relations, the algorithm we propose to reconstruct the bulk function $k_0(\cdot)$ in $\Omega$ is stated as the following
\begin{algo}\label{AlgoScheme}
\begin{enumerate}
\item[]
    \item \label{Stepa} \textbf{Step (1)}.  We start by collecting our inversion input
    \begin{equation}\label{KK}
       \xi(z) :=  \xi(z,\theta, \omega_{n_{0}})  :=   v^{\infty}(-  \theta, \theta, \omega_{n_0}) -  u^{\infty}_z(-  \theta, \theta, \omega_{n_{0}}),
    \end{equation}
    with $z\in\Omega$, which corresponds to the left hand side of $(\ref{BSD-1-Algo})$.

    \item \label{Stepb} \textbf{Step (2)}. Based on $(\ref{BSD-1-Algo}), (\ref{KK})$ and $(\ref{DefCn0})$, we compute $v(z,\theta,\omega_{n_{0}})$, which is the point-wise value of the total field  before injecting the droplet $D_{z}$ into $\Omega$.

     \item \label{Stepc} \textbf{Step (3)}. We use numerical differentiation techniques (mollification method) to compute $\Delta v(z,\theta,\omega_{n_{0}})$ from the already reconstructed value $v(z,\theta,\omega_{n_{0}})$, as shown in \textbf{Step $(\ref{Stepb})$}.

     \item \label{Stepd} \textbf{Step (4)}. We use the Helmholtz equation $(\ref{Heq})$ to obtain a set of point-wise values of $k_{0}(\cdot)$  by
     \begin{equation}\label{liu03-01}
        \frac{1}{k_0(z)}  =   - \frac{1}{\omega_{n_0}^2}  \frac{\Delta v(z,\theta,\omega_{n_0})}{v(z,\theta,\omega_{n_0})},\quad z\in\Omega,
     \end{equation}
    where, in the right-hand side, $v(z,\theta,\omega_{n_0})$ is already reconstructed from \textbf{Step $(\ref{Stepb})$}, and $\Delta v(z,\theta,\omega_{n_0})$ is already reconstructed from \textbf{Step $(\ref{Stepc})$}. Hence, by moving the droplet $D_{z}$ in $\Omega$, we can recover $\left\{k_{0}(z_{j})\right\}_{j=1}^{N}$, the point-wise values of $k_{0}(\cdot)$.
\end{enumerate}
\end{algo}


Based on this algorithm, the continuous values of $k_0(\cdot)$ can be finally approximated from  $\left\{k_{0}(z_{j})\right\}_{j=1}^{N}$ obtained in \textbf{Step (\ref{Stepd})} from the expansion
\begin{equation}\label{coro-Eq2.8}
    k_{0}(x)  =  \sum_{j=1}^{N} \gamma_{j}  f_{j}(x), \quad x\in\Omega,
\end{equation}
where $(f_{1}(\cdot), \cdots, f_{N}(\cdot))$ is the specified radial basis functions, for example, see
subsection \ref{SubSectionUnperturbed} for the choice of the radial basis functions. The expansion coefficient $\vec{\gamma}:=(\gamma_{1}, \cdots, \gamma_{N})^T \in  \mathbb{C}^{N}$ can be determined from the following linear algebraic system
\begin{equation}\label{coro-LZEq1037}
(f_i(z_j))_{N\times N}\cdot\vec{\gamma}=\vec{k_0}
\end{equation}
with known $\vec{k_0}:=(k_0(z_1),\cdots,k_0(z_N))^T\in \mathbb{C}^N$.


Some necessary clarifications to the implementation of   \textbf{Algorithm \ref{AlgoScheme}} are stated as follows.

\begin{itemize}

\item Concerning the selected index.

Since the index $n_{0} \in \mathbb{N}$ in $(\ref{KK})$ is arbitrary,  we take $n_{0} = 1$  in $(\ref{KK})$ to obtain
\begin{equation}\label{BSDI}
\xi(z)  =  \xi(z,\theta, \omega_{1})  =  v^{\infty}(- \theta, \theta, \omega_1)  -  u_z^{\infty}(- \theta, \theta, \omega_1)   \overset{(\ref{BSD-1-Algo})}{=}  C_{1} \left( v(z,\theta, \omega_1) \right)^{2}, \quad z \in \Omega,
\end{equation}
without loss of generality, where $\omega_1   \overset{(\ref{Eigfreq})}{=}  \lambda_1^{-1/2}  \overset{( \ref{EigValFractionalOrder})}{=}  \mu_{1}   \overset{\textbf{Table \ref{Table1}}}{\simeq}  1.8366$, and
\begin{equation}\label{KKWHW}
    C_{1}  \overset{(\ref{DefCn0})}{=}  \frac{1}{4  \pi} \lambda_{1}^{-2}  \left(\int_{B} e_{1}(x)  dx \right)^{2}  \varepsilon^{1-h} \overset{\textbf{Table \ref{Table1}}}{\simeq} \frac{1}{4  \pi}  \left( 0.2965 \right)^{-2}  \left( 3.1745\right)^{2}  \varepsilon^{1-h}
\end{equation}
with $h >1/2$. Under this configuration, the equation $(\ref{liu03-01})$ becomes
\begin{equation}\label{liu03}
\frac{1}{k_0(z)}  = - \frac{1}{\omega_{1}^2} \frac{\Delta v(z,\theta,\omega_{1})}{v(z,\theta,\omega_{1})},\quad z\in\Omega.
\end{equation}

\item  Concerning the numerical differentiation involved in \textbf{Step (\ref{Stepc})}.

To handle the numerical differentiation of $v(z,\theta,\omega_{1})$ such as $\Delta v(z,\theta,\omega_{1})$, see for instance \textbf{Step $(\ref{Stepc})$}, we express the complex-valued inversion input data as
\begin{equation}\label{liu0201}
\xi(z)   = C_{1} \left(v(z, \theta, \omega_{1})\right)^2, \quad z \in \Omega,
\end{equation}
see $(\ref{BSDI})$, with $C_{1}$ is estimated by $(\ref{KKWHW})$. Then, from $(\ref{liu0201})$, we deduce that
\begin{equation}\label{Equa1129}
    v(z, \theta, \omega_{1})  =  \frac{\sqrt{\xi(z)}}{\sqrt{C_{1}}}, \quad z \in \Omega.
\end{equation}
Hence, for $z\in\Omega$, from $(\ref{liu03})$ and $(\ref{Equa1129})$, it follows that
\begin{equation}\label{rek0}
\frac{1}{k_0(z)} =  - \frac{1}{\omega_{1}^2}  \frac{\Delta \sqrt{\xi(z)}}{\sqrt{\xi(z)}}=-  \frac{1}{\omega_{1}^2}  \left( \frac{\Delta\xi(z)}{2\xi(z)}-\frac{|\nabla\xi(z)|^2}{4\xi(z)^2}\right).
\end{equation}

\end{itemize}

A very important observation in \eqref{rek0} is  that, once we determine $\xi(z)$ from  \eqref{BSDI}, the right-hand side of  $(\ref{rek0})$ is independent of $C_1$, i.e.,  we do not need $C_1$ approximated by \eqref{KKWHW} for our reconstruction. On the other hand, the right-hand side of  $(\ref{rek0})$ requires numerical differentiations, which are  ill-posed for $\xi(z)$ given by $(\ref{BSDI})$, since %both $v^{\infty}\left(-\theta, \theta, \omega_{1}\right)$ and
$u_z^{\infty}\left(-\theta, \theta, \omega_{1}\right)$ are approximated by solving truncated integral equations for small $0 <\varepsilon \ll 1$, and consequently $\xi(z)$ is of unavoidable noise.  To address this issue, we utilize the mollification method to deal with the ill-posedness, see \cite{mol1,Mur}
for related regularization schemes. More precisely, for given  $\xi(\cdot)$ on a domain $\mathfrak{U}$ containing the point $z$ where we want to compute its Laplacian, we compute its second order partial derivatives along three directions, respectively. We firstly  take $\mathfrak{U}\subset \mathbb{R}^3$ to be a cube and  introduce
\begin{equation*}
  \eta(x):= \begin{cases}
			\textbf{c} \exp\left(\dfrac{1}{\left| x\right|^2-1}\right), & \text{if $\left\vert x \right\vert < 1$,}\\
            0, & \text{if $\left\vert x \right\vert \geq 1$,}
		 \end{cases}
\end{equation*}
with
     $\textbf{c}:= \left( \int^{1}_{-1}e^{\frac{1}{\left|x \right|^2-1}}dx \right)^{-1}$, which is a $C^{\infty}_0(\mathbb{R}^1)$ function satisfying $\int_{\mathbb{R}^1}\eta(x)dx=1$. For kernel function $\eta_{\delta}(x):=\frac{1}{\delta}\eta(\frac{x}{\delta})$ with specified $\delta>0$, if $f\;:U \subset \mathbb{R}\to \mathbb{R}$ is locally integrable, define its mollification \cite{EvansBook}
        \begin{equation*}
            f^{\delta}(x) := (\eta_{\delta}*f)(x) :=\int_{U}\eta_{\delta}(x-y)f(y)dy=\int_{-\delta}^{\delta}\eta_{\delta}(y)f(x-y)dy, \qquad x \in   U_{\delta},
        \end{equation*}
        where $U_{\delta}:= \left\{x \in U \mid  \hbox{dist}(x,\partial U)>\delta \right \}$. Additionally, from \cite[Chapter 2, Page 37]{Adam}, we have
     \begin{equation}\label{FARNJB}
         D^{\alpha}f^{\delta}(x) =  \int_{U} D^{\alpha}\eta_{\delta}(x-y)f(y)  dy, \quad x \in U_{\delta}\subset U\subset \mathbb{R}^1,
     \end{equation}
     where $D=\frac{d}{dx}$  and $\alpha=1,2$ is the order of derivative. According to \cite[Theorem 4.1.1]{molill}, the formula $(\ref{FARNJB})$ makes sense under the condition $\left\Vert D^{\alpha}f \right\Vert_{\mathbb{L}^{p}\left( U_{\delta}\right)} \le \mathrm{M}(\alpha, p, \delta)$ for $1 \le p \le \infty$, with some  positive constant $\mathrm{M}(\alpha, p, \delta)$, and it holds that
        \begin{equation}\label{VUPR}
           \lim_{\delta \to  0} \left\Vert D f^{\delta} - Df \right\Vert_{\mathbb{L}^{p}\left( U_{\delta} \right)} \to 0 \quad \text{and} \quad  \lim_{\delta  \to  0} \left\Vert D^2f^{\delta} - D^2f \right\Vert_{\mathbb{L}^{p}\left( U_{\delta} \right)} \to 0.
        \end{equation}
To compute $\nabla\xi(z)$ and $\Delta\xi(z)$, we first use \eqref{FARNJB} to compute all the partial derivatives in
\begin{eqnarray*}
    \nabla\xi^{\delta}(z)=\left(\frac{\partial\xi^{\delta}}{\partial z_1}(z), \frac{\partial\xi^{\delta}}{\partial z_2}(z), \frac{\partial\xi^{\delta}}{\partial z_3}(z)\right) \quad \text{and} \quad \Delta\xi^{\delta}(z) =\frac{\partial^2\xi^{\delta}}{\partial z_1^2}(z) + \frac{\partial^2\xi^{\delta}}{\partial z_2^2}(z)+\frac{\partial^2\xi^{\delta}}{\partial z_3^2}(z)
\end{eqnarray*}
with specified mollification constant $\delta>0$,
and then  get the approximations to $\nabla\xi(z)$ and $\Delta\xi(z)$ in the sense (\ref{VUPR}).
Assuming $\xi(\cdot,z_2,z_3): U \to \mathbb{R}$ is locally integrable for fixed $(z_2,z_3)$, we have
\begin{eqnarray*}
        \xi^{\delta }(z_1,z_2,z_3):= \left( \eta_{\delta}*\xi(\cdot,z_2,z_3)\right)(z_1)=\int_{U}\eta_{\delta}(z_1-t)\xi(t,z_2,z_3)dt, \quad z_1\in U_{\delta}.
\end{eqnarray*}
Then, it holds that
\begin{equation*}
    \partial_{z_1}\left(\xi^{\delta }(z_1,z_2,z_3)\right) = \int_{U}\partial_{z_1}\eta_{\delta}(z_1-t)\xi(t,z_2,z_3)dt, \quad z_1\in U_{\delta}
\end{equation*}
from \eqref{FARNJB}.
In a similar manner, we have
\begin{eqnarray*}
        \partial_{z_2}\left(\xi^{\delta }(z_1,z_2,z_3)\right)&=&\int_{U}\partial_{z_2}\eta_{\delta}(z_2-t)\xi(z_1,t,z_3)dt, \quad z_2\in U_{\delta},\\
        \partial_{z_3}\left(\xi^{\delta }(z_1,z_2,z_3)\right)&=&\int_{U}\partial_{z_3}\eta_{\delta}(z_3-t)\xi(z_1,z_2,t)dt, \quad z_3\in U_{\delta}.
\end{eqnarray*}
Hence, we can compute the approximation to $\nabla\xi(z)$ by
\begin{equation}\label{grexi}
     \nabla\xi^{\delta}(z) \, = \, \left(\frac{\partial\xi^{\delta}}{\partial z_1}, \frac{\partial\xi^{\delta}}{\partial z_2}, \frac{\partial\xi^{\delta}}{\partial z_3}\right)(z).
\end{equation}
In addition, we also have the approximation to $\Delta \xi(z)$ by
\begin{equation}\label{lapxi}
    \Delta\xi^{\delta}(z) =\frac{\partial^2\xi^{\delta}}{\partial z_1^2}(z) + \frac{\partial^2\xi^{\delta}}{\partial z_2^2}(z)+\frac{\partial^2\xi^{\delta}}{\partial z_3^2}(z),
\end{equation}
where
\begin{equation*}
        \partial_{z_1}^2\left(\xi^{\delta }(z_1,z_2,z_3)\right)=\int_{U}\partial_{z_1}^2\eta_{\delta}(z_1-t)\xi(t,z_2,z_3)dt, \quad z_1\in U_{\delta},
\end{equation*}
and
$\partial_{z_2}^2\left(\xi^{\delta }(z_1,z_2,z_3)\right), \partial_{z_2}^2\left(\xi^{\delta }(z_1,z_2,z_3)\right)$
are of similar representations.


Thus, from $(\ref{rek0})$, we deduce
\begin{equation}\label{XC-Equa0850}
\frac{1}{k_0(z)}  = -  \frac{1}{\omega_{1}^2}  \left( \frac{\Delta\xi^{\delta}(z)}{2\xi(z)}-\frac{|\nabla\xi^{\delta}(z)|^2}{4\xi(z)^2}\right) - \frac{1}{\omega^{2}}  Error(z), \quad z \in \mathfrak{U}_{\delta},
\end{equation}
where the error term $Error(z)$ is given by
\begin{eqnarray*}
 Error(z) &:=&  \frac{\Delta\left(\xi-\xi^{\delta}\right)(z)}{2\xi(z)}  -   \frac{|\nabla\left(\xi -\xi^{\delta}\right)(z)|^2}{4 \xi(z)^2}- \\ & & \frac{\langle Re\left(\nabla \xi (z) \right);Re\left(\nabla \xi (z)-\nabla \xi^{\delta}(z) \right)\rangle  +  \langle Im\left(\nabla \xi (z) \right);Im\left(\nabla \xi (z)-\nabla \xi^{\delta}(z) \right)\rangle}{2  \xi(z)^2},
\end{eqnarray*}
which can be estimated as
$\left\Vert Error \right\Vert_{\mathbb{L}^{p}\left( \mathfrak{U}_{\delta} \right)} \lesssim \left\Vert \Delta \xi^{\delta} - \Delta \xi \right\Vert_{\mathbb{L}^{p}\left( \mathfrak{U}_{\delta} \right)} + \left\Vert \nabla \xi^{\delta} - \nabla \xi \right\Vert_{\mathbb{L}^{2p}\left( \mathfrak{U}_{\delta} \right)}  \to 0$ as $\delta\to 0$
from \eqref{VUPR}.
Hence, by referring to $(\ref{XC-Equa0850})$, we have
\begin{equation*}
 \dfrac{1}{k_{0}(z)}\approx -  \frac{1}{\omega_{1}^2} \left( \frac{\Delta\xi^{\delta}(z)}{2\xi(z)}-\frac{|\nabla\xi^{\delta}(z)|^2}{4\xi(z)^2}\right), \quad z \in \mathfrak{U}_{\delta}\subset \mathfrak{U}\subset \mathbb{R}^3,
\end{equation*}
where $\xi(z)$ is given by \eqref{BSDI}, while $\nabla\xi^{\delta}(z), \Delta\xi^{\delta}(z)$ are given by (\ref{grexi}) and (\ref{lapxi}), respectively.

We conclude this section by the following explanations.
\begin{remark}
The following points are in order.
\begin{enumerate}

    \item Due to the quotient structure in the right-hand side of \eqref{liu03}, the constant difference of the argument when we determine the complex-valued $v(z, \theta, \omega_{1})$ from $\left( v(z, \theta, \omega_{1}) \right)^2$ has nothing to do with the reconstruction of $k_0(z)$.

    \item In \textbf{Step $(\ref{Stepc})$}, we use the mollification method to calculate $\Delta v(z, \theta, \omega_{1})$ from $v(z, \theta, \omega_{1})$, but there are other methods that can also be used, such as finite difference methods, the Tikhonov regularization, the level set methods, and the conjugate gradient techniques, as shown in \cite{wave,con, FDM1,FDM2}, and the references therein.

    \item The point-wise values of the bulk modulus function $k_{0}(\cdot)$ can only be recovered in regions where the total field $v(\cdot, \theta, \omega_{1})$ is not constant, see \eqref{Heq} and \eqref{liu03-01}.

    \item  To recover $k_{0}(\cdot)$ from its discrete values, we have opted for interpolation with radial basis functions in $(\ref{coro-Eq2.8})$. Obviously, there are other methods that can be employed such as the spline interpolation.
\end{enumerate}
\end{remark}
