\section{Kernel calculation}
\label{sec:SM_kernels}

The (normalised) kernel $K$ is given by probability that an active neuron in the representation of position $p$ is also active for position $p + \Delta p$,
%
\begin{equation}
    K(\Delta p ) = L \mathbb{E}_{\omega, \theta} [ x_i(p) x_i(p + \Delta p) ] = \mathbb{E}_{\omega, \theta} [x_i(p+\Delta p) | x_i(p) = 1]
\label{eqn:SM_kernel_def}
\end{equation}
%
The $L$ prefactor ensures that the inner product between a vector and itself is 1, i.e. $K(0) = 1$. We will henceforth drop the neuron index $i$, since the expected inner product is equal at every index.
%
Because the offsets $\theta \in [0,L)$ are uniformly distributed across the acceptance region of the neural activation function, and since we are conditioning on $x(p) = 1$, then (\ref{eqn:SM_kernel_def}) is equivalent to
%
\begin{equation}
\begin{split}
K(\Delta p) & = \mathbb{E}_{\omega} \Big[ \probP\big[ \mathrm{mod}_L (\omega \Delta p + t ) < 1 \big] \Big] \\
& = \mathbb{E}_\omega \Big[ \mathrm{ReLU}\big( 1 - \mathrm{mod}_L (\omega \Delta p) \big) + \mathrm{ReLU}\big(1 - \mathrm{mod}_L ( \omega \Delta p - L + 1)\big) \Big]
\end{split}
\end{equation}
%
where we introduce the uniform random variable $t \sim \mathcal{U}_{[0,1)}$ representing the distance to the edge of the acceptance region in either direction (positive or negative $\omega \Delta p$), and $\mathrm{ReLU}$ is a rectified-linear function.
We then want to write the above function as a Fourier series, periodic with period $L$. To make life easier, we will shift the domain of interest from $[0,L)$ to $[-L/2, L/2)]$. Then, the above expression is given by
%
\begin{equation}
\mathbb{E}_{\omega} \Big[ \mathrm{tri} \big( \mathrm{wrap}_{-\frac{L}{2}, \frac{L}{2}} (\omega \Delta p) \big) \Big]
\end{equation}
%
where $\mathrm{tri}$ is a triangle function and $\mathrm{wrap}_{-\frac{L}{2}, \frac{L}{2}} $ wraps its input to the desired range. The Fourier coefficients $C_n$ of the triangle function are easily calculated, giving
%
\begin{equation}
\begin{split}
K(\Delta p) & = \mathbb{E}_\omega \Big[ \sum_{n = -\infty}^{\infty} C_n e^{\frac{2 \pi i n }{L} \omega \Delta p} \Big] \\
& = \frac{1}{L} \sum_{n = -\infty}^{\infty}  \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) \mathbb{E}_\omega \Big[ e^{\frac{2 \pi i n }{L} \omega \Delta p} \Big] \\
& = \frac{1}{L} \sum_{n = -\infty}^{\infty}  \mathrm{sinc}^2 \Big( \frac{n}{L} \Big)  \int_{-\infty}^\infty P(\omega) e^{\frac{2 \pi i n }{L} \omega \Delta p} \de \omega \\
& = \frac{1}{L} \sum_{n = -\infty}^{\infty}  \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) \mathcal{F} \big[ P(\omega) \big]\Big(\frac{2 \pi  n}{L} \Delta p \Big) \\
& = \frac{1}{L} \sum_{n = -\infty}^{\infty}  \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) K_{\text{RFF}} \Big(\frac{2 \pi n}{L} \Delta p \Big) \\
& = \frac{1}{L} + \frac{2}{L} \sum_{n = 1}^{\infty}  \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) K_{\text{RFF}} \Big(\frac{2 \pi n}{L} \Delta p \Big)
\end{split}
\end{equation}
%
where $\mathrm{sinc}(u) = \sin (\pi u) /  \pi u$, and $K_\text{RFF} : \mathbb{R} \rightarrow [0,1]$ is the random Fourier feature kernel, corresponding to the phasor state embedding function $x_j(p) = \exp i( \omega_j p + \theta_j)$, with $\theta_j \sim \mathcal{U}_{[0, 2 \pi)}$ \cite{rahimi_random_2007,thomas_theoretical_2022, frady_computing_2022}. 
Note that in these equations we're treating $\omega$ as frequency, not an angular frequency.

As an example, if the frequencies are drawn from a rectangular distribution, whose Fourier transform is a $\mathrm{sinc}$ function, then
%
\begin{equation}
P(\omega) \propto \mathrm{rect}\Big(\frac{\omega}{4 \wma} \Big) \quad \longrightarrow \quad  K(\Delta p) = \frac{1}{L} + \frac{2}{L} \sum_{n=1}^{\infty} \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) \mathrm{sinc} \Big( \frac{4n}{L} \wma \Delta p \Big)
\end{equation}
%
while for a Gaussian $P(\omega)$, whose Fourier transform is also Gaussian we have
%
\begin{equation}
P(\omega) \propto \exp \Big(-\omega^2 / (2 \sigma_\omega^2) \Big) \quad \longrightarrow \quad  K(\Delta p) = \frac{1}{L} + \frac{2}{L} \sum_{n=1}^{\infty} \mathrm{sinc}^2 \Big( \frac{n}{L} \Big) \exp \Big(-\frac{(2 \pi n \sigma_\omega)^2 \Delta p^2}{2 L^2} \Big)
\end{equation}
where $\sigma_\omega = \sqrt{\frac{\pi}{2}} \wma$ is the Gaussian's standard deviation.
The sampling distributions $P(\omega)$ and exact and measured kernels $K(\Delta p)$ are plotted in Fig. \ref{fig:integration_megafig}g,h with the first hundred $n$ terms calculated in each summation.



\section{Multidimensional kernels}
\label{sec:SM_kernel_multi}

\begin{figure}
\centering
\includegraphics[width=5in]{figs/lcc_kernel.pdf}
\caption{Measured \textbf{(a)} and theoretical \textbf{(b)} 2D similarity kernels, with the embedding frequencies $\omega_i$ drawn from a rectangular distribution.}
\label{fig:SM_lcc_multidim}
\end{figure}

We wish to obtain a similar approximation for the similarity kernels of the multidimensional vector embeddings, in the 2D case defined by
%
\begin{equation}
\begin{split}
K(p_1 + \Delta p_1, p_2 + \Delta p_2) & = \frac{L}{N} \expect{\hv{x}(p_1, p_2) \cdot \hv{x}(p_1 + \Delta p_1, p_2 + \Delta p_2)} \\
& = L \mathbb{E} \big[  x_i (p_1, p_2) x_i (p_1 + \Delta p_1, p_2 + \Delta p_2) \big] \\
& = \mathbb{E} \big[ x_i (p_1 + \Delta p_1, p_2 + \Delta p_2)  |  x_i (p_1, p_2)  = 1 \big]    
\end{split}
\label{eqn:SM_multidim_kernel_def}
\end{equation}
%
for some index $i$. We consider the hypervector $\hv{c}(p_1, p_2)$ formed by the LCC binding operation of two hypervectors $\hv{a}(p_1)$ and $\hv{b}(p_2)$, i.e.
%
\begin{equation}
    \hv{c}(p_1, p_2) = \hv{a}(p_1) \LCC \hv{b}(p_2)
\label{eqn:SM_lcc_multidim_def}
\end{equation}
%
To calculate (\ref{eqn:SM_multidim_kernel_def}), we need to calculate the probability that an active index in $\hv{c}$ continues to be active when shifting in encoded position by $(\Delta p_1, \Delta p_2)$.
We use $A,B,C$ to denote the events that an active index in $\hv{a}, \hv{b}, \hv{c}$ remains active after this shift, respectively. Then, per the definition of LCC binding, we have
%
\begin{equation}
\begin{split}
\probP (C) & = \probP (C | A, B)\probP(A, B) + \probP(C | A, \text{ not } B) \probP (A, \text{ not } B) + \text{v.v.} + \probP (C | \text{ not } A, \text{ not } B) \\
& \approx 1 \cdot \probP(A) \probP(B) + 0 \cdot \big[ \probP (A) (1 - \probP(B)) + \text{v.v.} \big] + \frac{1}{L-1} \big( 1 - \probP(A) \big) \big( 1 - \probP(B) \big) \\
& = \frac{L}{L-1} \big[  \probP(A) \probP(B) - \frac{1}{L}\probP(A) - \frac{1}{L} \probP(B) + \frac{1}{L} \big]
\end{split}
\end{equation}
%
where on the second line we assume that, if the active indices in both $\hv{a}$ and $\hv{b}$ change, then there is a $1/(L-1)$ probability that the new indices combine to leave $\hv{c}$ unchanged. We then recognise that the probabilities $\probP(A)$ and $\probP(B)$ are precisely the 1D kernels we calculated earlier, giving us
%
\begin{equation}
K(\Delta p_1, \Delta p_2) = \frac{L}{L-1} \Big[ K_1(\Delta p_1) K_2(\Delta p_2) - \frac{1}{L} \big( K_1(\Delta p_1) + K_2(\Delta p_2)\big) + \frac{1}{L} \Big]
\label{eqn:SM_multidim_lcc_kernel_formula}
\end{equation}

This expression and an empirically-measured similarity kernel are shown in Fig. \ref{fig:SM_lcc_multidim}. To obtain an expression for higher-dimensional kernels, we can iteratively apply (\ref{eqn:SM_multidim_lcc_kernel_formula}), yielding in the 3D case for example
%
\begin{equation}
K(\Delta p_1,  \Delta p_2, \Delta p_3) = \frac{1}{(L-1)^2} \Big[ L^2 K_1 K_2 K_3 - L \big( K_1 K_2 + K_2 K_3 + K_3 K_1 \big) + (K_1 + K_2 + K_3) + (L-2) \Big]
\end{equation}
%
where $K_s = K_s( \Delta p_s), \: s = \{1,2,3\}$ are the 1D kernels in each dimension.

\newpage

\section{Noisy inner-products as a stochastic process}
\label{sec:SM_stochproc}

Since we know the expected inner product between position vectors, we can rewrite inner products as
%
\begin{equation}
     \hv{x}(p) \cdot \hv{x}(p + \Delta p) / M = K(\Delta p) + \epsilon(p, \Delta p)
\end{equation}
%
where $\epsilon$ is the deviation of the inner products from their expected values. Although we can apply CLT-based techniques to estimate the magnitude of $\epsilon$ (or apply more rigorous methods \cite{thomas_theoretical_2022}), we don't have a way of estimating how $\epsilon$ varies as the positions are varied. If $p$ is changed by a very small amount, we would expect $\epsilon$ to be approximately constant, while for a large change in $p$, we expect that $\epsilon$ would be resampled from some underlying stationary distribution.
Understanding the dynamics of $\epsilon$ is necessary to derive properties of the energy landscape along the line attractor, principally the length scale of its heterogeneity.

We will calculate the overlap between a binary sparse (non-block) hypervector $\hv{x}(p)$ of dimension $N$, with average number of nonzero components $M = \frac{N}{L}$, and a vector of all ones $\hv{1}$. Applying this calculation to two sparse block vectors will require only that some of the quantities be relabelled at the end.
%
We split the domain of possible $\omega$ values into equally-sized bins of width $\eta$, indexed by $k$. Assuming that $\eta$ is small enough, we can approximate neurons in the same bin $k$ as having the same frequency $\omega_k$. We denote the number of neurons in bin $k$ by $n_k$, with expected occupancy $\langle n_k \rangle = N P(\omega_k) \eta $. We denote the contribution to the inner product $\hv{x}(p)\cdot \hv{1}$ from bin $k$ as $X_k \in \{0, \ldots, n_k \}$, and consider how $X_k$ varies as $p$ is changed by a small amount $p \rightarrow p + \delta p$.
%
Since $\delta p$ is small, the only possibilities for change are:
%
\begin{enumerate}
    \item a component for which $x_i(p) = 1$ turns off, $x_i(p + \delta p) = 0$.
    \item a component for which $x_i(p) = 0$ turns on, $x_i(p + \delta p) = 1$.
\end{enumerate}
%
The change in overlap $\delta X_k$ is thus given by
%
\begin{equation}
\begin{split}
    \delta X_k   & =  \delta X_k^+ - \delta X_k^- \\
    \delta X_k^+ & \sim B \big( n_k - X_k, \frac{\omega_k \, \delta p}{L-1} \big) \\
    \delta X_k^- & \sim  B \big( X_k, \frac{\omega_k \, \delta p}{1} \big )
\end{split}
\end{equation}
%
where $B(n, p)$ is the binomial distribution, and $\delta X_k^+$ and $\delta X_k^-$ are the number of neurons that switch on and off respectively.


\subsection{Ornstein-Uhlenbeck approximation}

In order to make the dynamics of $X_k$ amenable to mathematical manipulation, we now try to approximate its dynamics with a Gaussian noise process $\de W$, which has variance $\expect{\de W^2} = \de p$ and mean $\expect{\de W} = 0$. We can thus construct a stochastic differential equation (SDE) which has the same mean and variance for a small step in $p$, given by
%
% We can now try to approximate this using a Gaussian noise process $\de W$, which has variance $\langle \de W^2 \rangle = \de p$, by constructing a stochastic differential equation that has the same mean and variance for a small step in $p$. It is given by
%
\begin{equation}
\begin{split}
    \de X_k & = \Big[(n_k-X_k) \frac{\omega_k}{L-1} - X_k \omega_k \Big] \de p + \sqrt{X_k \omega_k + (n_k-X_k) \frac{\omega_k}{L-1}} \de W \\
    & = \frac{\omega_k}{L-1} \big[ n_k - X_k L \big] \de p + \sqrt{\frac{\omega_k}{L-1} \big[ n_k + X_k (L-2) \big] } \de W
\end{split}
\end{equation}
%
where we have used that the variance of a Binomial distribution is approximately equal to the mean for very small probabilities. This expression gives us the dynamics of the contribution to the overlap from bin $k$. To obtain an expression for the total overlap, we thus sum the contributions from all bins $k$ and take the limit $\eta \rightarrow 0$. We will make the assumption that the fraction of 1-valued neurons in each bin is equal to the total fraction of 1-valued neurons across all bins, i.e.
%
%
\begin{equation}
    \frac{X_k}{n_k} = \frac{X}{N} \quad \rightarrow \quad X_k = \frac{n_k}{N} X = P(\omega_k) \eta X
\end{equation}
%
where $X = \sum_k X_k$, $X \in \{0, \ldots, N\}$ is the total inner product.
Then, summing contributions from each bin $k$ and taking limits, we get 
%
\begin{equation}
\begin{split}
\de X & = \lim_{\eta \rightarrow 0} \sum_k \de X_k \\
& = \frac{1}{L-1}\lim_{\eta \rightarrow 0} \Big[ \sum_k \omega_k n_k  - L \sum_k \omega_k X_k \Big] \de p + \sqrt{ \frac{1}{L-1} \lim_{\eta \rightarrow 0}  \Big[\sum_k \omega_k n_k  + (L-2) \sum_k \omega_k X_k \Big] } \de W \\
& = \frac{1}{L-1} \Big[ N \wma - LX \wma \Big] \de p + \sqrt{\frac{1}{L-1} \Big[ N \wma + (L-2) X \wma \Big] } \de W \\
& = \frac{\wma L}{L-1} \Big[ \frac{N}{L} - X \Big] \de p + \sqrt{\frac{\wma }{L-1} \Big[ N + (L-2) X \Big] } \de W
\end{split}
\end{equation}
%
where $\wma = \int | \omega | P(\omega) \de \omega$ is the mean absolute embedding frequency. For a Gaussian $P(\omega)$, this is $\sqrt{\frac{2}{\pi}} \approx 0.8$ times the standard deviation.
%
This expression can be simplified further. Since we know that independent SBC hypervectors will have an inner product tightly-concentrated around $N/L$, with standard deviation $\sqrt{N/L}$, we can replace $X$ in the noise term with its mean value. This is of course valid only for large $N$ (as is the bedrock of this derivation), and we are presuming that slight fluctuations in the magnitude of the noise term can be neglected. This gives
%
\begin{equation}
\begin{split}
\de X & \approx \frac{\wma L}{L-1} \Big[ \frac{N}{L} - X \Big] \de p + \sqrt{\frac{\wma }{L-1} \Big[ 2N -2\frac{N}{L} \Big] } \de W \\
& =  \frac{\wma L}{L-1} \Big[ \frac{N}{L} - X \Big] \de p + \sqrt{\frac{2 N}{L} \wma } \de W \\
% & \approx  \wma \Big[ M - X \Big] \de p + \sqrt{2 M \wma } \de W \\
\end{split}
\end{equation}
%
This SDE describes the inner product between a vector of all ones, and a sparse (not necessarily block) hypervector. To obtain the SDE for the inner product between two sparse block vectors, we need only to replace $N$ and $M$ with $N/L$ and $M/L$ respectively, to reflect that the SBC hypervector is effectively just a vector of all ones in $1/L$ of its sites. This gives
%
\begin{equation}
\de X = \wma \frac{L}{L-1} \Bigg[ \frac{N}{L^2} - X \Bigg] \de p + \sqrt{\frac{2N}{L^2} \wma } \de W
\label{eqn:SM_dX_with_offset}
\end{equation}
%
Hence, the inner-product between two sparse block hypervectors, as the position of one of them is varied, follows a mean-reverting noisy process. This has a steady-state solution with mean $N/L^2$ and variance $\frac{N}{L^2} \frac{L-1}{L}$, as is expected of the inner product between two independent SBC hypervectors.
What will be more useful for subsequent calculations however, is the inner product between two SBC hypervectors with the mean subtracted. For this, we redefine $X(p)$ as
%
\begin{equation}
X(p) := (\hv{z} - f)\cdot \hv{x}(p)
\end{equation}
%
This of course amounts only to subtracting the offset from (\ref{eqn:SM_dX_with_offset}), giving
%
\begin{equation}
\begin{split}
\de X & = -\wma \frac{L}{L-1}X \de p + \sqrt{\frac{2N}{L^2} \wma } \de W \\
& = \vphantom{\frac{L}{L}}-\gamma X \de p + g \de W
\end{split}
\label{eqn:SM_OU}
\end{equation}
%
where we define $\gamma = \wma \frac{L}{L-1}$ and $g = \sqrt{2N\wma / L^2}$. This is the famed Ornstein-Uhlenbeck (OU) equation, originally describing the velocity of a pollen grain under the bombardment of air particles \cite{uhlenbeck_theory_1930, jacobs_stochastic_2010}, but here modelling the residual of the inner product between SBC vectors. This has solution
%
\begin{equation}
X(p) = X_0 e^{-\gamma p} + g \int_0^p e^{\gamma (p^\prime - p)} \de W^\prime
\label{eqn:SM_OU_soln}
\end{equation}
%
where $X_0$ is the value of $X$ at $p = 0$. In Fig. \ref{fig:SM_stochproc_overlaps} we compare empirically-measured overlaps and the distribution predicted by (\ref{eqn:SM_OU_soln}).

\begin{figure}
    \centering
    \includegraphics[width=2.5in]{figs/stochproc_overlaps.pdf}
    \caption{10,000 sample paths of the mean-adjusted overlap error between two sparse block code hypervectors, as the represented position $p$ for one of them is varied. Each path represents a resampling of the offsets and frequencies. The static hypervector $\hv{z}$ was constructed to have an initial overlap error of $0.3$ for each path. Overlain is the theoretical distribution, derived from the OU approximation.}
    \label{fig:SM_stochproc_overlaps}
\end{figure}


\subsection{Residual autocovariance}

The autocovariance of the residual, $\expect{X(p) X(p+\Delta p)}$ will be needed to calculate the autocorrelation of the energies. Although this calculation can be lifted from other sources \cite{jacobs_stochastic_2010, uhlenbeck_theory_1930}, for completeness it is given here by
%
\begin{equation}
\begin{split}
\expect{X(p)X(p+\Delta p)} & = \iint X_1 X_0 \mathbb{P}[X_1(p + \Delta p)| X_0(p)] \mathbb{P}[X_0(p)] \de X_0 \de X_1 \\
& = \iint \frac{1}{2 \pi \sigma(X_0) \sigma_0}X_1 X_0 e^{-(X_1-\mu(X_0))^2/ (2 \sigma(X_0)^2)} e^{-X_0^2 / (2 \sigma_0^2)} \de X_0 \de X_1 \\
& = \int \frac{1}{\sqrt{2 \pi} \sigma_0} X_0 \mu(X_0) e^{X_0^2 /2 \sigma_0^2} \de X_0 \\
& = \int \frac{1}{\sqrt{2 \pi} \sigma_0 } X_0 \big( X_0e^{-\gamma \Delta p} \big) e^{X_0^2 /2 \sigma_0^2} \de X_0 \\
& = \sigma_0^2 e^{-\gamma \Delta p}
\label{eqn:XX_overlaps}
\end{split}
\end{equation}
%
where $\sigma_0^2 = g^2/(2\gamma)$ is the steady-state (unconditioned) variance of $X$. This is plotted in Fig. \ref{fig:autocorr_overlaps}. From this we can conclude that the length scale over which $X$ ``forgets'' its value is approximately $1/ \gamma \approx 1/\wma$.

\begin{figure}
\centering
\includegraphics[width=2in]{figs/stochproc_autocorr_overlaps.pdf}
\caption{Autocorrelation for the cross-talk noise (deviation from the expected kernel $K$) for different offsets between position states. Specifically, this is looking at $\mathrm{Corr}\big[\bar{\hv{z}} \cdot \hv{x}(p), \bar{\hv{z}} \cdot \hv{x}(p+\Delta p) \big](\Delta p)$. Overlain is the theoretical autocorrelation from the OU approximation, which is a decaying exponential with length scale $\wma^{-1}$ (shown by scale).}
\label{fig:autocorr_overlaps}
\end{figure}

\subsection{Energy statistics}

The energy of a state $\hv{x}(p)$, if the weight matrix consists only of the symmetric matrix $\mat{A}$, is given by
%
\begin{equation}
\begin{split}
E(\hv{x}(p)) & = - \hv{x}(p)\T \mat{A} \hv{x}(p) = - \hv{x}(p)\T \int_0^P \bar{\hv{x}}(p^\prime) \bar{\hv{x}}(p^\prime)\T \de p^\prime \hv{x}(p) = \int_0^P \big( \bar{\hv{x}}(p^\prime) \cdot \hv{x}(p) \big)^2 \de p^\prime
\end{split}
\label{eqn:SM_E_int_def}
\end{equation}
%
where w.l.o.g. we set $P = \qty{1}{\metre}$, such that the line attractor represents positions between 0 and 1 metres, since increasing $P$ is equivalent to increasing the frequencies $\omega$. Because the energy consists of inner products between position states, $E(p)$ will also follow a stochastic process. To calculate the statistics of $E$, we will make the quite heavy-handed assumption that the residual error between two position states is well-modelled by (\ref{eqn:SM_OU}), and critically is unaffected by the value of $K$.
If one considers the residual from two very-distant states, this is a reasonable assumption, since then the states are almost completely independent, and $X$ may be sampled from its steady-state distribution. But, for two proximal states, this is obviously not true, since the error $\epsilon = \hv{x}(p) \cdot \hv{x}(p) - \frac{N}{L} K(p - p) = \frac{N}{L} - \frac{N}{L} = 0$ will be exactly 0 for identical states. We will thus be overestimating the error between vectors representing nearby positions.
Expanding (\ref{eqn:SM_E_int_def}) we get
%
\begin{equation}
\begin{split}
E(\hv{x}(p)) & \approx \int_0^P \big(  M  \bar{K}(p^\prime - p) +  \bar{\hv{z}}(p^\prime) \cdot \hv{x}(p) \big)^2 \de p^\prime \\
& = \int_0^P  M^2 \bar{K}^2(p^\prime - p) +2 M  \bar{K}(p^\prime - p) \big( \bar{\hv{z}}(p^\prime) \cdot \hv{x}(p) \big)  + \big( \bar{\hv{z}}(p^\prime) \cdot \hv{x}(p) \big)^2  \de p^\prime
\end{split}
\end{equation}
%
where $\overline{\hv{z}}(p')$ is a fictitious distant position representation vector, which enforces our above mentioned assumption by giving rise to errors with dynamics given by the OU approximation (\ref{eqn:SM_OU}).


To calculate the energy variance, we will need the autocorrelation function of $X^2(p) = \big( \bar{\hv{z}} \cdot \hv{x}(p)\big)^2$. We thus need to calculate
%
\begin{equation}
\begin{split}
\expect{(X_0^2 (p) - \sigma_0^2)( X^2(p+\Delta p) - \sigma_0^2)} & = \iint \big( X_0(p)^2 - \sigma_0^2 \big) \big( X(p+\Delta p) - \sigma_0^2 \big) \mathbb{P}[X_0(p), X(p+ \Delta p)] \de X_0 \de X \\
% & = \iint \big( X_0(p)^2 - \sigma_0^2 \big) \big( X(p+\Delta p) - \sigma_0^2 \big) \frac{1}{\sigma \sqrt{2 \pi}} e^{-(X-\mu)^2 / (2 \sigma^2)} \frac{1}{\sigma_0 \sqrt{2 \pi}} e^{-X_0^2/(2 \sigma_0^2)} \de X_0 \de X \\
& = \iint \big( X_0(p)^2 - \sigma_0^2 \big) \big( X(p+\Delta p) - \sigma_0^2 \big) \frac{1}{\sigma \sigma_0 2 \pi} e^{-(X-\mu)^2 / (2 \sigma^2)} e^{-X_0^2/(2 \sigma_0^2)} \de X_0 \de X \\
& = \frac{1}{2 \pi \sigma \sigma_0} \int \big( X_0^2 - \sigma_0^2 \big) e^{-X_0^2 / (2 \sigma_0^2)} \Bigg( \int_{-\infty}^\infty  (X^2 - \sigma_0^2) e^{-(X-\mu)^2 / (2 \sigma^2)} \de X \Bigg) \de X_0 \\
& = \frac{1}{\sigma_0 \sqrt{2 \pi}} \int \big( X_0^2 - \sigma_0^2 \big) e^{-X_0^2 / (2 \sigma_0^2)} (\sigma^2 + \mu^2 - \sigma_0^2) \de X_0 \\
\intertext{then subbing in the expressions for the mean $\mu(X_0)$ and standard deviation $\sigma(X_0)$ from (\ref{eqn:SM_OU_soln}),}
& = \frac{1}{\sigma_0 \sqrt{2 \pi}} \int \big( X_0^2 - \sigma_0^2 \big) \big( \sigma_0^2 \big[ 1 - e^{-2\gamma \Delta p} \big] + X_0^2 e^{-2\gamma \Delta p} - \sigma_0^2 \big) e^{-X_0^2 / (2 \sigma_0^2)} \de X_0 \\
& = \frac{1}{\sigma_0 \sqrt{2 \pi}} e^{-2 \gamma \Delta p} \int \big( X_0^4 + - 2\sigma_0^2 X_0^2 + \sigma_0^4 \big)  e^{-X_0^2 / (2 \sigma_0^2)}  \de X_0 \\
& = 2 \sigma_0^4 e^{-2 \gamma \Delta p} \\
& = 2 \sigma_0^4 e^{-2 \wma \frac{L}{L-1} \Delta p}
\label{eqn:autocorr_X2}
\end{split}
\end{equation}
%
which will later be useful. This says that the noisy contribution to the energy of unrelated (far separated in $p$) states has a forgetting length-scale of approximately $(2 \wma)^{-1}$.

The mean energy is similarly calculated as
%
\begin{equation}
\begin{split}
\expect{E(p)} & = \int_0^P  \expect{ M^2 \bar{K}^2(p^\prime - p)} -2 M  \expect{\bar{K}(p^\prime - p) \big( \bar{\hv{z}}(p^\prime) \cdot \hv{x}(p) \big)} + \expect{\big( \bar{\hv{z}}(p^\prime) \cdot \hv{x}(p) \big)^2}  \de p^\prime \\
& \approx M^2 \int_{-\infty}^{\infty} \bar{K}^2(p^\prime) \de p^\prime - 2M \int_{-\infty}^\infty \expect{K(p^\prime) X(p^\prime)} \de p^\prime + \int_0^P \expect{X^2 (p^\prime)} \de p^\prime \\
& \approx M^2 \frac{1}{\wma}\int_{-\infty}^{\infty} \bar{K}^2(x / \wma) \de x - 2M \int_{-\infty}^\infty \expect{K(p^\prime)} \underbrace{\expect{X(p^\prime)}}_{0} \de p^\prime + \int_0^P \sigma_0^2 \de p^\prime \\
& = M^2 \frac{\kappa_2}{\wma} + \sigma_0^2P \\
& = \frac{N^2}{L^2} \frac{\kappa_2}{\wma}  + \frac{N}{L^2} \frac{L}{L-1} P
\end{split}
\label{eqn:SM_mean_E}
\end{equation}
%
where we introduce the integral $\kappa_2 = \int_{-\infty}^\infty \bar{K}^2(x / \wma) \de x \approx 1$, which is independent of $\wma$ due to the the kernel's width scaling with $\wma$ too (\ref{sec:SM_kernels}). We neglect edge effects by assuming that $p$ is far from the integration bounds. Since $\bar{K} \approx 0$ for distances greater than $1/\wma$, on the second line we extended the integration bounds to infinity.
%
Assuming $L \gg 1$ (states are sparse), we can write (\ref{eqn:SM_mean_E}) as
%
\begin{equation}
\expect{E(p)} \approx \frac{N^2}{L^2 \wma} \Big(\kappa_2 + \frac{P \wma}{N}  \Big)
\end{equation}
%
which clearly splits the energy into a contribution from the kernel overlap (independent of the length of the attractor), and a contribution from the nonzero cross-talk overlaps (proportional to the length of the stored attractor $P \wma$). Note that off-manifold states will thus have a mean energy given by the rightmost term.

We are now in a position to calculate the autocorrelation length scale and variance of the energy. We first calculate $\big \langle E(\hv{x}(p)) E( \hv{x}(p + \Delta p)) \big \rangle$, which, keeping only terms with even powers of $X$, is given by
%
\begin{equation}
\begin{split}
\centering
\Bigg \langle \int_0^P \int_0^P \mathcolorbox{yellow}{M^4 \bar{K}^2 (p' - p ) \bar{K}^2 (p'' - p - \Delta p)} &  + \mathcolorbox{cyan}{4 M^2 \bar{K}(p' - p) \bar{K}(p'' -p - \Delta p) X(p',p) X(p'', p+\Delta p)} \\
& \hspace{-4em} + \mathcolorbox{pink}{2M^2 \bar{K}^2(p' -p) X^2(p'', p + \Delta p)} + \mathcolorbox{lime}{X^2(p', p) X^2(p'', p + \Delta p)} \de p' \de p'' \Bigg \rangle
\end{split}
\end{equation}
%
\textit{Divide et impera:}

The yellow terms are easily calculated. Assuming that $p$ is ``far'' from the edges of the line attractor, meaning many multiples of $\wma^{-1}$, we can safely extend the integration limits to $\pm \infty$. Then, it is given as
\begin{equation}
\begin{split}
    % \mathcolorbox{yellow}{\int_0^P \int_0^P M^4 \bar{K}^2 (p' - p ) \bar{K}^2 (p'' - p - \Delta p) \de p' \de p''}
     \colorbox{yellow}{$\ldots \vphantom{\int}$} & \approx \int_{-\infty}^\infty \int_{-\infty}^\infty M^4 \bar{K}^2 (p' - p ) \bar{K}^2 (p'' - p - \Delta p) \de p' \de p'' \\
    & = M^4 \int_{-\infty}^\infty \int_{-\infty}^\infty \bar{K}^2 (p' ) \bar{K}^2 (p'') \de p' \de p'' \\
    & = M^4 \Bigg[ \int_{-\infty}^\infty\bar{K}^2 (p' ) \de p' \Bigg]^2 \\
    & = M^4 \frac{1}{\wma^2 }\Bigg[ \int_{-\infty}^\infty \bar{K}^2 \Big( \frac{u}{\wma} \Big) \de u \Bigg]^2 \\
    & = \mathcolorbox{yellow}{\frac{M^4}{\wma^2} \kappa_2^2}
\end{split}
\end{equation}
%
where $\kappa_2 \approx 1$ is as previously defined. The blue terms are simplified by applying our assumption that the errors are independent of the kernel value. Note that this means we will be overestimating the variance contributed to this term, since we know that the error is reduced around $K(p\approx 0)$. Regardless,
\begin{equation}
\begin{split}
\qquad \qquad \colorbox{cyan}{$\ldots \vphantom{\int K^2}$} & = 4M^2 \int_0^P \int_0^P \bar{K}(p' -p) \bar{K}(p'' -p - \Delta p) \expect{X(p',p)X(p'', p + \Delta p)}  \de p' \de p'' \\
& \approx 4M^2 \int_{-\infty}^\infty \int_{-\infty}^\infty \bar{K}(p') \bar{K}(p'' - \Delta p) \expect{X(p',0)X(p'', \Delta p)}  \de p' \de p'' \\
\intertext{where we have assumed again that $p$ is far from the edges. We then assume that our expression for the autocorrelation (\ref{eqn:XX_overlaps}) can be applied for either of the states varying independently}
& \approx 4M^2 \sigma_0^2 \int_{-\infty}^\infty \int_{-\infty}^\infty\bar{K}(p')\bar{K}(p''- \Delta p) e^{- \gamma \Delta p} e^{- \gamma | p' - p''|} \de p' \de p'' \\
& = 4M^2 \sigma_0^2  e^{- \gamma \Delta p} \int_{-\infty}^\infty \int_{-\infty}^\infty \bar{K}(p') \bar{K}(p'') e^{- \gamma| p' - p'' - \Delta p|} \de p ' \de p'' \\
& =  \frac{4M^2 \sigma_0^2}{\wma^2}  e^{- \gamma \Delta p} \int_{-\infty}^\infty \int_{-\infty}^\infty \bar{K}\big(\frac{u}{\wma} \big) \bar{K} \big( \frac{v}{\wma} \big) \exp \Big[- \frac{\gamma}{\wma} | u - v - \wma \Delta p | \Big] \de u \de v \\
\intertext{where we have changed variables such that the kernels $\bar{K}$ are independent of $\wma$, and are nonzero only within $\approx 1$ distance of 0. Evaluating this integral is made difficult by the exponential absolute expression. But, given that the the kernels will be nonzero only for small $u$ and $v$, we can reasonably approximate the exponential to the value at $u = v = 0$,}
& \approx \frac{4M^2 \sigma_0^2}{\wma^2}  e^{- \gamma \Delta p} \int_{-\infty}^\infty \int_{-\infty}^\infty \bar{K}\big(\frac{u}{\wma} \big) \bar{K} \big( \frac{v}{\wma} \big) e^{-\gamma \Delta p} \de u \de v \\
& =  \mathcolorbox{cyan}{\frac{4M^2 \sigma_0^2}{\wma^2}  e^{- 2 \gamma \Delta p} \kappa_1^2}
\end{split}
\end{equation}
%
where we define $\kappa_1 = \int_{-\infty}^{\infty} \bar{K}(u / \wma) \de u \approx 1$. The pink terms are:
%
\begin{equation}
\begin{split}
\colorbox{pink}{$\ldots \vphantom{\int}$} & = \int_0^P \int_0^P 2 M^2 \bar{K}^2(p' - p) \expect{X^2(p'', p + \Delta p)} \de p' \de p'' \\
& \approx  2M^2  \int_{-\infty}^{\infty}  \int_{-\infty}^{\infty} K^2(p') \sigma_0^2 \de p' \de p'' \\
& = \mathcolorbox{pink}{\frac{2M^2 \sigma_0^2 P}{\wma} \kappa_2}
\end{split}
\end{equation}
%
% \newpage
And lastly we have the green terms, where again we will assume that our expression for the autocorrelation (\ref{eqn:autocorr_X2}) can be applied for both arguments independently,
%
\begin{equation}
\begin{split}
\hspace{8em} \colorbox{lime}{$\ldots \vphantom{\int}$} & = \int_0^P \int_0^P \big \langle X^2(p', p) X^2(p'', p + \Delta p) \big \rangle \de p' \de p'' \\
& \approx \int_0^P \int_0^P 2 \sigma_0^4 e^{-2\gamma \Delta p} e^{-2\gamma |p' - p''|} + \sigma_0^4 \:  \de p' \de p'' \\
& = P^2 \sigma_0^4 + 2 \sigma_0^4 e^{- 2 \gamma \Delta p} \int_0^P \int_0^P e^{-2\gamma |p' - p''|}  \de p' \de p'' \\
\intertext{change variables to $u = \frac{1}{2}(p' + p'')$ and $v = \frac{1}{2}(p' - p'')$}
& =  P^2 \sigma_0^4 + 2 \sigma_0^4 e^{- 2 \gamma \Delta p} \int_{u = 0}^{u = P} \int_{v = -|u - \frac{P}{2}| - \frac{P}{2}}^{v = |u - \frac{P}{2}| + \frac{P}{2} } e^{-4\gamma |v|}  \de v \de u \\
\intertext{which due to the integrand being $\approx 0$ for large $v$, and ignoring the behaviour at the extremities, can be simplified to }
& \approx  P^2 \sigma_0^4 + 2 \sigma_0^4 e^{- 2 \gamma \Delta p} \int_{u = 0}^{u = P} \int_{-\infty}^\infty  e^{-4\gamma |v|} \de v \de u \\
% & =  P^2 \sigma_0^4 + \sigma_0^4 e^{- 2 \gamma \Delta p} P \frac{1}{ \gamma} \\
& = \mathcolorbox{lime}{P^2 \sigma_0^4 + \frac{P \sigma_0^4}{\gamma} e^{- 2 \gamma \Delta p}}
\end{split}
\end{equation}
%
We can now combine these technicolor results to obtain the energy covariance, given by
%
\begin{equation}
\begin{split}
\hspace{6em} \mathrm{Cov}\big[ E(\hv{x}(p)), E(\hv{x}(p + \Delta p)) \big] & = \big \langle E(\hv{x}(p)) E( \hv{x}(p + \Delta p)) \big \rangle - \expect{E}^2 \\
& = \big \langle E(\hv{x}(p)) E( \hv{x}(p + \Delta p)) \big \rangle - \Big[ M^2 \frac{\kappa_2}{\wma} + \sigma_0^2 P \Big]^2 \\
& = \Big[ \frac{P \sigma_0^4}{\gamma} + \frac{4M^2 \sigma_0^2}{\wma^2}  \kappa_1^2 \Big] e^{- 2 \gamma \Delta p} \\
& = \frac{N^2}{L^4} \Big( \frac{L-1}{L} \Big) \frac{P}{\wma} \Bigg[ \Big( \frac{L-1}{L} \Big)^2 + \frac{4 N \kappa_1^2}{P \wma} \Bigg]e^{-2 \wma \frac{L}{L-1} \Delta p} \\
\intertext{which for very sparse states $L \gg 1$ simplifies to} 
& \approx \frac{N^2}{L^4} \frac{P}{\wma} \Bigg[1 + \frac{4 N \kappa_1^2}{P \wma} \Bigg]e^{- 2 \wma \Delta p}
\label{eqn:SM_covariance}
\end{split}
\end{equation}
%
where, the most important thing for us is that the heterogeneity of the energy surface has an autocorrelation length scale of approximately $(2\wma)^{-1}$. For a Gaussian $P(\omega)$, we can numerically integrate our kernel approximation to obtain the estimate $\kappa_1^2 \approx 1.5$. The theoretical estimate for the correlation and the simulated values are shown in Fig. \ref{fig:correlation_plot}. Although the estimate is off by a factor of 2 or so, there is good agreement with the length scale of the dependence upon $\Delta p$. 

\begin{figure}
\centering
\includegraphics[width=0.6\linewidth]{figs/correlation_plot.pdf}
\caption{The \textbf{a)} autocovariance and \textbf{b)} autocorrelation of the energy on the line attractor, for different offsets $\Delta p$. The theoretical estimate is given by (\ref{eqn:SM_covariance}). The discrepancy between the magnitude of the theoretical and simulated covariances is most likely due to the quite heavy-handed assumption, that the inner product error is independent of $\Delta p$. When the variance is divided out, the simulated correlations show good agreement with the theory, in particular the length scale over which the correlation decays.}
\label{fig:correlation_plot}
\end{figure}

