\State \textbf{begin} \textit{Step 2}:
\State Initialize $VerifiedInfo \gets \emptyset$
\Foreach{$\text{assert statement} ~Assert_j \in Asserts$}
    \State $VerifiedInfo_j \gets \text{all objects and attributes passed as arguments in} ~Assert_j$
    \State $MethCalls\_Assert_j \gets ~\text{all method calls in} ~Assert_j$
